	local CARD, CARD_IN = 0x18, 0x19
	local MOVIE, MOVIE_IN = 0x34, 0x35
	local DATA_SIZE = 0x2B0               -- the whole allocation (0x021D2D4C `movs r1,#0x2B; lsls
	                                      -- r1,#4`), so the gate proves the LAST byte it might read
	                                      -- is mapped, not just the first (a Gen V review lesson).

	-- Transcribed from the rendered artwork, member by member. Re-render any of them with
	-- `py -3.12 nitrogfx.py one <narc> <ncgr> <nclr> <nscr> out.png` and look.
	local COPYRIGHT = "© 2009 Pokémon. © 1995-2009 Nintendo. © 1995-2009 Creatures Inc. "
		.. "© 1995-2009 GAME FREAK inc."      -- demo/title/titledemo.narc  ncgr15 nclr14 nscr13
	local NOTICE    = "Online Interactions Not Rated by the ESRB"
		                                     -- demo/title/op_demo.narc    ncgr114 nclr115 nscr113
	local GAMEFREAK = "GAME FREAK presenta"  -- op_demo ncgr16 nclr15 nscr18 (nscr17 is the emblem
	                                         -- beside it, which carries no words at all)
	local WORDMARK  = "Pokémon"              -- op_demo ncgr95 nclr96 nscr12, and again as ncgr14
	                                         -- nclr13 with the SAME nscr12 — a second treatment of
	                                         -- the same word, so it is not announced twice.

	local said, last_data

	-- The opening's data, or nil. See the overlay note above for why the id is asked of sApplication.
	local function boot()
		if u32(A.sApplication + 0x00) ~= 77 then return nil end
		local app = u32(A.sApplication + 0x04)
		local d = app_at(app, A.OpeningCutscene_Main, 0xFFFFFFFF)
		if not (d and inram(d + DATA_SIZE - 1)) then return nil end
		return d, app
	end

