		[3] = "CONECTAR CON RANGER",   -- row: Pokemon Ranger link
		[4] = "TRANSFERIR DESDE RUBÍ",   -- row: GBA migration, agbGameType 1
		[5] = "TRANSFERIR DESDE ZAFIRO",   -- row: GBA migration, agbGameType 2
