			local total, ordinal = 0, 0
			for s = 0, 7 do
				if u32(d + MM_ACTIONS + s * 4) ~= 0 then
					total = total + 1
					if s <= cur then ordinal = ordinal + 1 end
				end
			end

			local entry = SLOT_LABEL[cur]
			if entry == nil and cur == 4 then
