				-- ONE, and entries 4..8 follow that order (0x0222B780 subtracts one before choosing).
				local t = u32(d + MM_AGB)
				if t >= 1 and t <= 5 then entry = 3 + t end
			end
			local label = entry and MENU[entry]
			if not label then return end            -- a row we cannot name is one we do not speak

			local line = label .. ", " .. ordinal .. " de " .. total
			if action == 1 then line = line .. continue_summary(d) end
			if line ~= mm_said_row then
				mm_said_row = line
				say(line)
			end
		end,
	}
