		[1] = "Por favor, elige cómo quieres recibir tu regalo.",   -- ChooseHowToReceiveGift: with the reception-method menu
		[2] = "La comunicación inalámbrica de Nintendo DS se iniciará. ¿Seguir?",   -- WirelessCommunicationsWillBeLaunched: friend/GBA Yes/No; Wonder Card share wireless Yes/No
		[3] = "Buscando regalo. Por favor, espera...",   -- SearchingForGift: friend, local wireless and WFC searches
		[4] = "¿Aceptar este regalo?",   -- ReceiveThisGift: with the receive Yes/No
		[6] = "Se ha enviado tu petición. Por favor, espera...",   -- RequestSentPleaseWait: after accepting a friend's gift
		[7] = "Recibiendo tu regalo. No apagues la consola.",   -- ReceivingGiftDontTurnOff: while a gift is received and saved
		[23] = "No se encontraron regalos.",   -- NoGiftsToBeFound: MG_APP_STATE_NO_GIFT_FOUND
		[24] = "Se ha rechazado tu solicitud.",   -- RequestTurnedDown: MG_APP_STATE_FRIEND_LEFT_BEFORE_SENDING
		[36] = "Tarj. misteriosa",   -- WonderCard: the album's header, and the actions menu's message box
		[37] = "Pídele tu regalo a un repartidor de cualquier Tienda Pokémon.",   -- PleasePickUpInPokeMart: gift status, gift waiting
		[38] = "Ya has recibido este regalo antes.",   -- AlreadyReceivedBefore: gift status, gift collected
		[39] = "Esta tarjeta no lleva ningún regalo.",   -- NoGiftAttached: gift status, no gift
		[40] = "Fecha recepción",   -- DateReceived: the label before the date
		[41] = "N.º de veces que puedes distribuir este regalo: {0}.",   -- CanBeDistributedNTimes: back of the card, {0} = sharesLeft
		[46] = "¿Quieres compartir este regalo?",   -- WouldYouLikeToShareThisGift: share Yes/No
		[49] = "{2}/{1}/{0}",   -- DateTemplate: {0} year, {1} month name, {2} day
		[51] = "Puedes compartir este regalo con tantos amigos como quieras.",   -- CanBeSharedAsManyFriendsAsYouLike: back of the card, sharesLeft 0xFF
		[52] = "Registro distribución",   -- PalDistributionRegitration: the share screen's title
		[55] = "Particip. actuales",   -- CurrentEntries: share screen label
		[56] = "{0}/4",   -- EntriesCountTemplate: share screen count, {0} = entries
		[57] = "ENVIAR",   -- Send: share screen button
		[58] = "SALIR",   -- Cancel_WonderCards: share screen button
		[61] = "¿Quieres tirar esta tarjeta?",   -- ThrowCardAway: trash Yes/No, no gift waiting
		[62] = "No has recibido tu regalo aún. ¿Quieres rechazar esta tarjeta?",   -- HaventReceivedGiftYet: trash Yes/No, gift still waiting
		[63] = "Rechazando... No apagues la consola.",   -- DiscardingDontTurnOff: while the card is erased and the game saves
		[77] = "La comunicación inalámbrica de Nintendo DS se iniciará. ¿Seguir?",   -- WirelessCommunicationsWillBeLaunched2: local wireless Yes/No
