		[0] = "No se ha podido acceder a la Conexión Wi-Fi de Nintendo. Para obtener ayuda, consulta el manual de instrucciones o visita el sitio web support.nintendo.com. Error: {0}",
		[1] = "La Conexión Wi-Fi de Nintendo tiene un volumen de tráfico demasiado elevado o el servicio se ha interrumpido. Vuelve a intentar conectarte más tarde. Para obtener ayuda, visita el sitio web support.nintendo.com. Error: {0}",
		[2] = "Se ha borrado este ID de la CWF de Nintendo porque ha permanecido inactivo durante demasiado tiempo. Para obtener ayuda, visita el sitio web support.nintendo.com. Error: {0}",
		[3] = "El servicio de Conexión Wi-Fi de Nintendo ya no está disponible para este juego. Visita support.nintendo.com para ver la lista completa de juegos actualmente compatibles con la Conexión Wi-Fi de Nintendo. Error: {0}",
		[4] = "El punto de acceso está ocupado. No se puede establecer la conexión. Inténtalo más tarde. Para obtener ayuda, visita el sitio web support.nintendo.com. Error: {0}",
		[5] = "No hay ningún punto de acceso cerca. Acércate a uno y vuelve a intentarlo. Para obtener ayuda, visita el sitio web support.nintendo.com. Error: {0}",
		[6] = "No se ha podido encontrar ningún punto de acceso compatible cerca. Comprueba tus ajustes de conexión y vuelve a intentarlo. Para obtener ayuda, visita el sitio web support.nintendo.com. Error: {0}",
		[7] = "No se ha podido detectar el Conector USB Wi-Fi de Nintendo. Comprueba los ajustes de conexión usados en la configuración de la CWF de Nintendo. Para obtener ayuda, visita el sitio web support.nintendo.com. Error: {0}",
		[8] = "No se ha podido acceder a la Conexión Wi-Fi de Nintendo. Comprueba los ajustes de conexión y la configuración del punto de acceso. Para obtener ayuda, visita el sitio web support.nintendo.com. Error: {0}",
		[9] = "No se recibe ninguna señal. Puede que el otro jugador se haya desconectado de la Conexión Wi-Fi de Nintendo o que ya no figures en su lista de amigos. Error: {0}",
		[10] = "Error de conexión. Te has desconectado de la Conexión Wi-Fi de Nintendo. Para obtener ayuda, visita el sitio web support.nintendo.com. Error: {0}",
		[11] = "Error de conexión. Para obtener ayuda, visita el sitio web support.nintendo.com. Error: {0}",
		[12] = "Error de descarga. Para obtener ayuda, visita el sitio web support.nintendo.com. Error: {0}",
		[13] = "Error de conexión. Te has desconectado de la Conexión Wi-Fi de Nintendo. Para obtener ayuda, visita el sitio web support.nintendo.com.",
		[14] = "Error de conexión...",
	}
	--[[ MYSTERY_GIFT_TEXT:END ]]

	local APP_STATE = 0x14                 -- ApplicationManager procState
	local OVL_MAIN_MENU = 97               -- FS_OVERLAY_ID(main_menu), the 0x61 in both enqueue pools

	-- MysteryGiftAppData. Size from MysteryGiftApp_Init's ApplicationManager_NewData (pool word
	-- 0x0222E384 = 0x29F8); every offset from the instruction that uses it.
	local MG_SIZE = 0x29F8
	local MG_STRING  = 0x14   -- string: ShowMessageBoxIntoStateTransition 0x0222E262 `str r0,[r4,#0x14]`
	local MG_DELAY   = 0x68   -- msgBoxPrinterDelay: ShowMessageBox 0x0222DF00 stores 0xFF after
	                          -- every print; the transition path's finish stores 0 (0x0222E29A)
	local MG_PRINTER = 0x6C   -- textPrinterId: 0x0222DED8 `str r0,[r4,#0x6c]`, read as a byte (0x0222E284)
