	                          -- ov97_02238DA4 0x02238DBE/0x02238DC6 write them, ShowWiFiCommError
	                          -- 0x0222E144/0x0222E17A reads them (pool 0x0222E1CC)
	local MG_HEAP = 0x56      -- HEAP_ID_MYSTERY_GIFT_APP: StringList_New's r1 at 0x0222DD3A

