	local WC_SIZE = 0x3D54
	local WC_GIFT    = 0x2BA0 -- mysteryGift: DetermineGiftStatus 0x0223092C (0x2BC0 - 0x20)
	local WC_CARDS   = 0x2BB4 -- wonderCards[3]: PrintWondercardTitle 0x022308CC (0x2BC0 - 0xC)
	local WC_SLOT    = 0x2BC0 -- selectedWondercardSlot: `movs r1,#0xaf; lsls r1,#6` at 0x022308C6
	local WC_LIST    = 0x2BC8 -- listMenu: ProcessStateTransitionMenuInput, pool 0x022310F0
	local WC_CHOICES = 0x2BCC -- strList: MakeStateChangeListMenuFromEntryTemplates, pool 0x022305D8
	local WC_BUTTON  = 0x3D4C -- shareScreenSelectedBtn: HandleWCShareScreenInput, pool 0x02231600
	local WC_HEAP = 0x57      -- HEAP_ID_WONDER_CARDS_APP: StringList_New's r1 at 0x0223055A

