	local CARD_SHARES = 0x348 -- sharesLeft u8 (SetupRemainingSharesCount / InitWondercardActionsMenu)
	local CARD_DATE   = 0x354 -- receivedDate s32, days: SetupDateString `movs r1,#0xd5; lsls #2`
	local CARD_SIZE, GIFT_CARDS, GIFT_PGTS, PGT_SIZE = 0x358, 0x920, 0x100, 0x104

	-- RTC_ConvertDayToDate (ARM, 0x020CC27C), the SDK routine SetupDateString calls: days since
	-- 2000-01-01, clamped to 0..36524 (pool 0x020CC36C = 0x8EAC), years peeled off 366/365 at a time
	-- for at most 99 years, the remainder clamped to 365, Jan/Feb of a leap year special-cased, and
	-- the month found in the cumulative table at 0x02101450. Copied rule for rule, so a corrupt day
	-- count reads exactly as the card shows it rather than as something we guessed.
	local MONTH_START = { [0] = 0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334 }
	local function day_to_date(days)
		if days < 0 then days = 0 elseif days > 36524 then days = 36524 end
		local y = 0
		while y < 99 do
			local len = (y % 4 == 0) and 366 or 365
			if days - len < 0 then break end
			days, y = days - len, y + 1
		end
		if days > 365 then days = 365 end
		if y % 4 == 0 then
			if days < 60 then
				if days < 31 then return y, 1, days + 1 end
				return y, 2, days - 31 + 1
			end
			days = days - 1
		end
		for m = 11, 0, -1 do
			if days >= MONTH_START[m] then return y, m + 1, days - MONTH_START[m] + 1 end
		end
	end

