	-- to `width`, or none. A value wider than `width` draws a '?' in the game; we say nothing instead.
	local function fmt_int(n, width, zeroes)
		if not n or n < 0 or n >= 10 ^ width then return nil end
		local s = tostring(math.floor(n))
		if zeroes then s = string.rep("0", width - #s) .. s end
		return s
	end

	-- A baked entry with its StringTemplate slots filled, or nil if any slot has no value.
	local function fill(t, args)
		if not t then return nil end
		local ok = true
		local s = t:gsub("{(%d)}", function(n)
			local v = args and args[tonumber(n)]
			if not v then ok = false; return "" end
			return v
		end)
		return ok and clean(s) or nil
