	--   StringList: 8-byte {String *, value} rows, then a terminator {0xFFFFFFFF, heapID}
	--   (StringList_New 0x02013A2E-0x02013A34) — which is checked, so a list from another heap or
	--   a count that disagrees with the allocation fails closed.
	local function list_row(lm, choices, heap)
		if not (inram(lm) and inram(lm + 0x2F)) then return fail("no list menu") end
		if not inram(choices) then return fail("no StringList") end
		if u32(lm) ~= choices then return fail("the list menu is not over this app's StringList") end
		local n = u16(lm + 0x10)
		local pos = u16(lm + 0x2C) + u16(lm + 0x2E)
		if n < 1 or n > 8 or pos >= n then return fail("list cursor outside its rows") end
		if not inram(choices + n * 8 + 7) then return fail("StringList unreadable") end
		if u32(choices + n * 8) ~= 0xFFFFFFFF or u32(choices + n * 8 + 4) ~= heap then
