	local CUT_OVERLAY, PROC_STATE, PROC_RUNNING = 100, 0x14, 1
	local SCENE_IDX, SCENE, WORK, ARGS = 0x04, 0x08, 0x0C, 0xD0
	local LOADER, WINDOW, PRINTER_ID = WORK + 0x2C, WORK + 0x30, WORK + 0x40
	local SCENE_WORK = { [0] = 0x1D28, [2] = 0x1EC8 }
	local SPEAR_PILLAR_BANK = 234                   -- TEXT_BANK_SPEAR_PILLAR
	local PARKED = { [2] = true, [3] = true }       -- RENDER_STATE_CLEAR, RENDER_STATE_START_SCROLL

	-- The running cutscene: its data and its manager, or nil.
	local function cutscene()
		local fs = field_sys()
		if not fs then return nil end
		local pm = u32(fs + 0x00)
		if not inram(pm) or u32(pm + 0x00) ~= 0 then return nil end
		local man = u32(pm + 0x04)
		local d = app_at(man, A.SpearPillarCutscene_Main, CUT_OVERLAY)
		if d and inram(d + ARGS + 3) then return d, man end
		return nil
	end

	-- One line of console per distinct reason, so a silent cutscene names its own cause (Rule 5)
	-- without repeating it every frame.
	local last_why
	local function why(s)
		if s ~= last_why then last_why = s; if s then dbg("spear pillar: " .. s) end end
		return nil
	end

	-- A Thumb BL's target, or nil if the two halfwords at `p` are not a BL.
	local function bl_target(p)
		local hi, lo = u16(p), u16(p + 2)
		if hi & 0xF800 ~= 0xF000 or lo & 0xF800 ~= 0xF800 then return nil end
		local off = ((hi & 0x7FF) << 12) | ((lo & 0x7FF) << 1)
		if off & 0x400000 ~= 0 then off = off - 0x800000 end
		return p + 4 + off
	end

	-- ⭐ THE ENTRY IDS ARE READ OUT OF THE RUNNING OVERLAY, not trusted from the table above (Rule 11):
	-- each site must still be `movs r2,#imm` followed within four halfwords by a BL to the print
	-- helper. Any site that fails is dropped with its reason, so a patched overlay goes silent for
	-- that line instead of speaking the wrong one. Read once per application run.
	local function read_sites()
		local p = A.SpearPillarCutscenePrint
		local cmp = u16(p + 0x1E)                       -- `cmp r7,#name_entry`
		local name_entry = (cmp & 0xFF00 == 0x2F00) and (cmp & 0xFF) or nil
		if not name_entry then why("print helper is not the traced code (cmp r7 missing)") end
		local out = {}
		for scene, states in pairs(A.SpearPillarCutsceneSites) do
			out[scene] = {}
			for st, site in pairs(states) do
				local mov = u16(site)
				local ok = false
				if mov & 0xFF00 == 0x2200 then
					for k = 2, 8, 2 do
						if bl_target(site + k) == p then ok = true; break end
					end
				end
				if ok then out[scene][st] = mov & 0xFF
				else why(string.format("print site %08X is not a traced print", site)) end
			end
		end
		return out, name_entry
	end

	-- The one formatted entry, with argument 0 set to the player's name (ov100_021D46C8:
	-- TrainerInfo_NameNewString of args +0x08). Only argument 0 is ever set here, so fill_args fails
	-- closed on any other index.
	local function with_name(codes, args)
		local ti = u32(args + 0x08)
		if not inram(ti + 15) then return why("no TrainerInfo for the player's name") end
		local name = {}
		for i = 0, 7 do
			local c = u16(ti + i * 2)
			if c == 0xFFFF then break end
			name[#name + 1] = c
			if i == 7 then return why("player name has no terminator") end
		end
		return fill_args(codes, { [0] = name }, why)
	end

	-- What the printer is printing: its pages and where each page break leaves the cursor, both in
	-- bytes from the start of the String the game freed.
	-- ⛔ A NAME ARGUMENT STILL IN THE TEXT FAILS CLOSED. with_name has replaced the one the game
	-- formats; any left means the print helper's own check could not be read, so the game may be
	-- formatting text that would otherwise be spoken with a hole in it ("Now, .").
	local function line_of(codes)
		local rd = function(p) return codes[p // 2 + 1] or 0xFFFF end
		local to = 2 * (#codes - 1)                     -- the terminator's position
		local pages = pt_pages(0, to, rd)
		if #pages == 0 then return why("entry does not decode as text") end
		local breaks, q = {}, 0
		while q < to do
			local c = rd(q)
			if c == 0xF100 then break end
			local n = code_size(q, c, to, rd)
			if not n then return why("entry is malformed") end
			if c == 0xFFFE then
				local m = rd(q + 2) & 0xFF00
				if m == 0x100 or m == 0x500 or m == 0x600 then return why("an unformatted name argument") end
			end
			q = q + n
			if c == 0x25BC or c == 0x25BD then breaks[#breaks + 1] = q end
		end
		return { pages = pages, breaks = breaks }
	end

	-- The live printer drawing into this application's message window, or nil.
	local function printer_of(d)
		local slot = u32(d + PRINTER_ID)
		if slot >= 8 then return nil end
		local task = u32(A.sTextPrinterTasks + slot * 4)
		if not inram(task) then return nil end
		local pr = u32(task + 0x10)
		if not inram(pr + 0x28) or u32(pr + 0x04) ~= d + WINDOW then return nil end
		return pr
	end

	local sites, name_entry, sites_for
	-- The line being followed: its key (scene pointer, index and state), its text, how many pages
	-- have been said, and the printer's String base once the first page break has revealed it.
	-- `dead` means: say nothing more about this line.
	-- `first` is the cursor when the line was first seen, which bounds the base (see below).
	local key, line, said_n, base, dead, first
	-- ⛔ WHAT THE LAST FRAME SHOWED: scene, index, state and whether a printer was up. A line is only
	-- followed from its START, and the game's own state machine is the witness for that: every print
	-- site increments the scene state by exactly one in the same call (scene 2's state 19 instead
	-- prints inside the state, with no printer before it). So a new line is fresh only if the frame
	-- before showed the same scene one or two states earlier, or the same state with no printer.
	-- Anything else — the reader starting mid-line, a save state loaded or a rewind into another
	-- line — waits for the next line rather than reading page one over a later page.
	local prev

	local function forget()
		key, line, said_n, base, dead, first = nil, nil, 0, nil, false, nil
	end

	MODULES[#MODULES + 1] = {
		name = "Spear Pillar cutscene",
		detect = function() return cutscene() ~= nil end,
		on_enter = function()
			forget()
			-- The sites are read again on every run: the next run's manager can be allocated at the
			-- same address, so the address alone cannot say the check is still current.
			prev, last_why, sites_for = nil, nil, nil
		end,
		update = function()
			local d, man = cutscene()
			if not d then return end
			if sites_for ~= man then sites, name_entry = read_sites(); sites_for = man end
			local was = prev
			prev = nil
			if u32(man + PROC_STATE) ~= PROC_RUNNING then return end
			local idx = u32(d + SCENE_IDX)
			local back = SCENE_WORK[idx]
			if not back then return end                -- the middle scene prints nothing
			local scene = u32(d + SCENE)
			if not inram(scene + back + 7) then return why("no scene data") end
			if u32(scene + back) ~= d + WORK then return why("scene does not point back at its work block") end
			local st = u32(scene)
			local entry = sites[idx] and sites[idx][st]
			local pr = entry and printer_of(d)
			prev = { scene = scene, idx = idx, st = st, pr = pr ~= nil }
			if not pr then return end

			local k = scene * 64 + idx * 32 + st
			if k ~= key then
				forget()
				key, first = k, u32(pr)
				local started = was and was.scene == scene and was.idx == idx
					and ((was.st < st and was.st >= st - 2) or (was.st == st and not was.pr))
				if not started then dead = true; return why("joined mid-line; waiting for the next one") end
				local codes = bank_codes(u32(d + LOADER), SPEAR_PILLAR_BANK, entry, why)
				if codes and entry == name_entry then codes = with_name(codes, u32(scene + back + 4)) end
				line = codes and line_of(codes)
				if not line then dead = true; return end
				why(nil)
			end
			if dead then return end

			-- WHICH PAGE IS UP. The printer's String base is unknown (it was never kept), but at a
			-- page break the cursor sits exactly on the character after the break
			-- (src/render_text.c:186-195), so the FIRST park of a fresh line is the first break and
			-- fixes the base. Every later park must land on a break too, or the bank and the
			-- printer disagree about the text and the line goes quiet.
			local cursor = u32(pr)
			if PARKED[u8(pr + 0x28)] then
				if not base then
					if not line.breaks[1] then dead = true; return why("parked on a line without page breaks") end
					base = cursor - line.breaks[1]
					-- The second net: a fresh printer was first seen at its String's start or a
					-- glyph or two in (one RenderText call per frame, src/text.c:228-256), so a
					-- base that puts that first sighting further along means this park is not
					-- the first break. ⚠ A NET, NOT A PROOF: a printer first seen exactly one page
					-- in, where that page is within four characters of page one's length, passes.
					-- Only a mid-line arrival from the state just before can reach this at all;
					-- the state witness above is the guard.
					if first - base < 0 or first - base > 8 then
						dead = true; return why("first park is not the line's first break")
					end
				end
				local at, ok = cursor - base, false
				for _, b in ipairs(line.breaks) do if b == at then ok = true; break end end
				if not ok then dead = true; return why("printer parked off a page break") end
			end
			local shown = base and page_at(line.pages, cursor - base) or 1
			if shown > said_n then
				said_n = shown
				-- Every line interrupts: the box is wiped before each print (ov100_021D4788), and a
				-- later page is the player pressing A past the one before (Rule 1).
				say(line.pages[shown].text)
			end
		end,
	}
end)()

-- 6) FIELD-SCRIPT DIALOGUE — every NPC line, sign-triggered message and cutscene line that the
-- standard message box shows.
--
-- ⭐ THE ANCHOR IS ScriptManager.msgBuf, AND IT IS BETTER THAN ANYTHING GEN V HAD. It is a
-- persistent 1024-character String allocated once with the script task (src/script_manager.c:119-167)
-- and it holds the COMPLETE, fully expanded message — every page of it — from the moment
-- LoadAndFormatMessage runs, which is BEFORE a single glyph is drawn
-- (src/overlay005/script_message.c:141-145). Gen V's dialogue buffer relocated per message and only
-- ever exposed the prefix that had been drawn so far; here the text is simply there.
--
-- ⛔ WHY NOT THE PRINTER POOL. sTextPrinterTasks is the obvious global, and it is the wrong anchor:
-- a TextPrinter keeps only an advancing raw cursor with no base pointer, it disappears at end of
-- string, it carries every UI printer in the game and not just dialogue, and it is never created at
-- all for instant text (src/text.c:171-225). It can say WHERE the game has got to, which is exactly
-- how it is used below, and it cannot say WHAT the message is.
--
-- THE GATE, in order, each failing closed:
--   * a script is running and its manager magic checks out   (script_manager above)
--   * ScriptManager +0x08 isMsgBoxOpen ~= 0 — the flag OpenMessageBox owns
--     (src/overlay005/script_message.c:130-139), cleared by the explicit close commands
--   * ⚠ AND A STRUCTURALLY VALID, NON-EMPTY msgBuf. ScrCmd_OpenMessage can raise that flag before
--     any message has been loaded (src/scrcmd.c:1462-1471), so the flag alone means "this window
--     exists", not "there is something to read".
;(function()
	local said_text, said_n, last_first, last_off, last_sm = nil, 0, nil, nil, nil
	local settled

	-- Is a SIGNPOST up? Signs, plaques and the town-map boards do not use the ordinary message box:
	-- they draw into their own window and never touch isMsgBoxOpen (src/scrcmd.c:1562-1589 and
	-- 1630-1650 write msgBuf and print straight into Signpost_GetWindow). Their own flag is the one
	-- to gate on, and it is a BITFIELD, so the mask was taken from the emitted code and not from the
	-- `command:7, active:1` declaration: Signpost +0x13, **active is bit 7, mask 0x80**, command the
	-- low seven bits (verified in the retail ROM, report-20260904-pt-dialogue-anchors.md item 14).
	-- Only ever dereferenced under field_map_live, because the object is created and freed with the
	-- field map without the owning pointer being nulled (src/overlay005/fieldmap.c:314-321, 890-898).
	local function signpost_up(fs)
		local sp = u32(fs + 0x64)
		return inram(sp) and (u8(sp + 0x13) & 0x80) ~= 0
	end

	-- The message that is up: its page list and the printer's position in it, or nil.
	-- ⭐ ONE MODULE HANDLES BOTH SURFACES, deliberately. The box and the signpost read the SAME
	-- msgBuf, so splitting them into two modules would give each its own idea of what had already
	-- been said — and a script that moves between them would then repeat itself. One gate, one
	-- memory.
	-- Is a script PAUSED waiting for a message to finish printing? ScriptManager.ctx[2] lives at
	-- +0x38/+0x3C (ScriptManager_GetMemberPtr 0x0203EF60; msgBuf at +0x44 is the same table and is
	-- already proven in game).
	local function print_wait(sm)
		for i = 0, 1 do
			local ctx = u32(sm + 0x38 + i * 4)
			if inram(ctx + 0x07) and u8(ctx + 0x01) == 2 and u32(ctx + 0x04) == A.ScriptWaitPrint then
				return true
			end
		end
		return false
	end

	local function state()
		local sm, fs = script_manager()
		if not sm then return nil end
		local sign = signpost_up(fs)
		if u8(sm + 0x08) == 0 and not sign then return nil end
		local first, last = str_range(u32(sm + 0x44), 1024)
		if not first then return nil end
		-- ⛔⛔ A HALF-FORMATTED BUFFER IS A VALID STRING, AND THAT IS WHAT SPOKE TWICE.
		-- (Ola, 2026-09-06.) StringTemplate_Format clears msgBuf and appends it ONE CHARACTER AT A
		-- TIME, and every completed append updates the length and writes a fresh 0xFFFF terminator
		-- at data + 2*size — so a PREFIX passes every structural test above. The game calls it
		-- synchronously, but the emulator stops the CPU at a frame boundary and lets us look, so we
		-- saw page one complete with the later pages missing, spoke it, then saw the finished
		-- buffer, called it new text, and spoke page one again.
		-- ⚠ "Synchronous" is not "atomic" to something sampling RAM between frames. That single
		-- distinction is the whole bug, and it invalidated an earlier RE answer of our own.
		-- ⭐ THE CURE IS THE ENGINE'S OWN COMMIT MARKER: formatting has finished if either a printer
		-- exists for this message, or the command has RETURNED and paused the script waiting for the
		-- print. During the construction window neither is true — the old printer is already
		-- destroyed and the command has not reached ScriptContext_Pause.
		-- Both are needed: an animated message is caught by the printer, an INSTANT message box
		-- never makes one and is caught by the pause.
		return sm, first, last
	end

	-- Has the message FINISHED being built? Two independent kinds of evidence, both needed.
	--
	-- ⛔⛔ THE COMMIT MARKER ALONE SILENCED INSTANT MESSAGES (codex-review 2026-09-06, confirmed
	-- against the source). ScrCmd_MessageInstant, ScrCmd_MessageFromBankInstant and
	-- ScrCmd_SentenceInstant render synchronously and `return FALSE` WITHOUT calling
	-- ScriptContext_Pause (src/scrcmd.c:1188-1206, 1223-1231) — compare ScrCmd_Sentence just below
	-- them, which does. So they have an open box and a finished buffer and satisfy neither marker:
	-- the Pal Park countdown and the PC's "Access which PC?" would have gone SILENT. That would
	-- have been the third silent reader in one day and it was mine, so the fix needs no per-command
	-- knowledge at all.
	-- ⭐ A BUFFER UNCHANGED SINCE LAST FRAME IS FINISHED. StringTemplate_Format runs to completion
	-- inside one CPU frame, so a partial prefix can be sampled AT MOST ONCE; seeing the same text
	-- twice running proves the append loop is over. It costs one frame — 17ms — before anything
	-- speaks, and it covers instant messages AND signposts without knowing which command made them,
	-- which is why the blanket signpost exemption is gone too (that was a MEDIUM in the same review).
	-- The printer/pause marker stays as the fast path for ordinary animated dialogue — almost
	-- everything — so the common case still speaks the moment the message exists.
	local function committed(sm, first, last)
		return printer_at(u8(sm + 0x05), first, last) ~= nil or print_wait(sm)
	end

	-- ⭐⭐ THE PRESENTATION ENDS WITH THE SCRIPT RUN, AND THAT IS THE ONLY HONEST RESET EDGE.
	--
	-- ⛔ THE BUG THIS FIXES (Ola, 2026-09-05): "talking to the same sign twice only speaks the
	-- first time." A wall sign is `ScrCmd_DrawSignpostInstantMessage`, which prints with
	-- **TEXT_SPEED_INSTANT** (src/scrcmd.c:1587) — and an instant print never creates a printer
	-- task (src/text.c:196-223, and see printer_at). So there is no cursor, the "cursor went
	-- backwards" edge below can never fire for a sign, the text is identical to last time, and
	-- msgBuf comes back at the same address because the heap hands the same block straight back.
	-- All three edges miss, and the second read is silent. The same hole swallows any repeated
	-- INSTANT message box, not just signs.
	--
	-- The fix is not a fourth content edge — it is the game's own lifetime. `ScriptManager_New`
	-- heap-allocates a manager per script run and `FieldTask_RunScript` frees it, msgBuf and all,
	-- the moment the last context finishes (src/script_manager.c:100-167, `magic = 0; Heap_Free`).
	-- So: **no manager == no message, and whatever we remembered saying is about a screen that no
	-- longer exists.** Reading the sign again is a NEW RUN, and it speaks.
	--
	-- ⚠ AND THIS IS WHY IT IS NOT on_enter, WHICH WOULD BE WRONG FOR EXACTLY THE REASON THE OLD
	-- COMMENT GAVE. ScrCmd_OpenMessage raises isMsgBoxOpen and draws an EMPTY box without touching
	-- msgBuf (src/scrcmd.c:1462-1471), and `ScrCmd_DrawSignpostTextBox` does the same for a
	-- signpost — it sets SIGNPOST_CMD_DRAW and lets the field's own per-frame pump raise `active`
	-- (src/overlay005/fieldmap.c:478) frames before any text arrives. Both leave the PREVIOUS
	-- message sitting in the buffer with a window open over it, and both happen INSIDE one script
	-- run. A module-lifetime reset would read that stale text out; a run-lifetime reset cannot,
	-- because the run has not ended.
	--
	-- ⛔ THE POINTER CLAUSE'S ORIGINAL JUSTIFICATION WAS WRONG, AND IT IS WORTH SAYING SO RATHER
	-- THAN QUIETLY REWORDING IT. This used to read "belt and braces: a changed manager POINTER
	-- resets too, which covers ScriptManager_Change jumping to another script without the field task
	-- ending." Codex checked every retail call site of ScriptManager_Change on 2026-09-06: they are
	-- all in encounter.c, field_move_tasks.c and start_menu.c, and every one converts a NON-script
	-- FieldTask into a script task. It is never used to chain one live script manager to another, and
	-- it has no teardown, so doing that would leak. The clause survives because a different manager
	-- pointer really does prove a different allocation — but the reason written beside it was
	-- invented, and it is exactly the sort of note that misdirects whoever reads it next.
	-- ⚠ What made this clause DANGEROUS was not the clause: it was script_manager() returning the
	-- first script task on the list rather than the one showing the message, so the pointer changed
	-- under a message that had not. That is fixed at the source (see script_manager above).
	--
	-- ⚠ IT LIVES IN detect() BECAUSE THAT IS THE ONLY THING THAT RUNS EVERY FRAME. update() only
	-- runs while text is up, which is precisely when the edge is not happening; on_exit fires
	-- between two messages of one script as readily as between two scripts, so it cannot tell them
	-- apart. Same reasoning as the save panel's arrival edge.
	local function forget_when_the_run_ends()
		local sm = script_manager()
		if sm == nil or sm ~= last_sm then
			-- ⚠ INSTRUMENTED 2026-09-06, because some messages in the Lake Verity opening spoke
			-- TWICE and five different edges could each explain it. This module has four ways to
			-- decide a message is new, and a spoken line does not say which one fired — which is
			-- exactly the shape of bug the project's own rule was written for: instruments beat
			-- inference, and one keypress with a named reason beats a round of theorising.
			-- Console only, never speech. Guarded on `said_text` so it is silent when there was
			-- nothing to forget, i.e. it cannot chatter while no script is running.
			if said_text then
				dbg(sm == nil and "dlg: forget — the script run ended"
					or ("dlg: forget — the manager moved to " .. string.format("%08X", sm)))
			end
			said_text, said_n, last_first, last_off, settled = nil, 0, nil, nil, nil
		end
		last_sm = sm
	end

	local prompt_serial = 0
	MODULES[#MODULES + 1] = {
		name = "field dialogue",
		detect = function()
			forget_when_the_run_ends()
			-- ⛔⛔ STAND DOWN INSIDE A BATTLE, OR THIS MODULE STARVES EVERY BATTLE READER BELOW IT
			-- (CLAUDE.md Rule 2, and this is the trap in its quietest form). A trainer battle is
			-- started BY a field script, and that script stays alive and PAUSED for the whole
			-- battle with its msgBuf still holding the last thing it said. So `state()` keeps
			-- answering "my screen" while the battle covers both screens. It would not SPEAK —
			-- the text has not changed and there is no printer, so no edge fires — which is
			-- exactly what makes it dangerous: context_of() runs only the FIRST module whose
			-- detect matches, so a module that is silently true is indistinguishable from a bug
			-- in the readers it is starving. That is how Gen V's party reader was silenced, and
			-- how the naming keyboard was silenced here on 2026-09-05.
			-- ⚠ The battle menus below ALSO have detects far more specific than this one, so
			-- either fix would do on its own; both are kept for the same reason the keyboard and
			-- the opening carry both — the ordering is a belt and this is the braces.
			if battle_sys() then return false end
			if shop_active and shop_active() then return false end
			if pc_field_active and pc_field_active() then return false end
			return (state()) ~= nil
		end,
		-- ⛔ DELIBERATELY NO on_enter/on_exit RESET — see forget_when_the_run_ends above for why
		-- the module's own lifetime is the wrong clock. Message identity is owned by the three
		-- edges below plus that one, all of which are properties of the message or of the script
		-- showing it, never of when this reader happened to become current.
		update = function()
			local sm, first, last = state()
			if not sm then return end

			local _, cursor = printer_at(u8(sm + 0x05), first, last)

			local pages = pt_pages(first, last)
			if #pages == 0 then return false end
			-- Identity is the WHOLE message, every page of it — not page one. Two different
			-- messages that happen to open with the same line would otherwise look identical, and
			-- the second one would go completely unspoken because its page counter never reset.
			local parts = {}
			for i = 1, #pages do parts[i] = pages[i].text end
			local full = table.concat(parts, "\1")

			-- IS THIS A NEW MESSAGE? Three independent edges, because each alone has a hole:
			--   * the text changed — catches every ordinary next line;
			--   * the BUFFER changed — msgBuf is allocated per ScriptManager (String_Init(1024) in
			--     src/script_manager.c:119-167), so a new script gets a new one and the message
			--     before it is simply gone;
			--   * the cursor went BACKWARDS WITHIN THE SAME BUFFER — every printer starts at the
			--     buffer's first character, so this catches the case a text compare cannot see:
			--     the same NPC line twice in a row.
			-- ⛔ THE OFFSET IS RELATIVE, AND THAT MATTERS (codex-review 2026-09-04, confirmed). It
			-- used to compare raw POINTERS across message lifetimes, which is meaningless once the
			-- buffer itself has moved: an identical line shown later from a HIGHER-addressed msgBuf
			-- would compare as "further along", no edge would fire, and it would never be spoken.
			-- ⚠ last_off is only updated from a LIVE printer: nilling it in the gap between two
			-- messages (the old printer is destroyed at end of string, the next is not created until
			-- the script resumes) would throw away the high-water mark the comparison depends on.
			-- ⛔ WAIT FOR IT TO SETTLE unless the engine has already committed it. `settled` is the
			-- text seen LAST frame; speaking only once it repeats is what keeps a half-built buffer
			-- out, and it is why signposts no longer need an exemption of their own.
			if not committed(sm, first, last) then
				if full ~= settled then settled = full; return false end
			end
			settled = full

			local off = cursor and (cursor - first) or nil
			-- ⛔⛔ AND THE MARK MUST DIE WITH THE MESSAGE IT BELONGED TO (Ola, 2026-09-06: some lines
			-- in the Lake Verity opening were spoken TWICE, and his console named both resets — "the
			-- text changed", then "the cursor restarted", with the same line after each). The first
			-- was right: it really was a new message. The second was not. `last_off` was still the
			-- high-water cursor of the message that had just ENDED, so the moment the NEW message's
			-- own printer was created at the start of the buffer, the backwards test compared it
			-- against a dead message's mark and declared the page new all over again.
			-- ⭐ The backwards edge itself has to SURVIVE — it is the only thing that can notice the
			-- same text being shown twice in a row, which is the sign case. So the mark is cleared
			-- only once another edge has already PROVED this is a different message; on a repeat of
			-- identical text neither of those fires, the mark stands, and the edge still works.
			local newer = full ~= said_text or first ~= last_first
			if newer or (off and last_off and off < last_off) then
				-- ⚠ INSTRUMENTED 2026-09-06 — see forget_when_the_run_ends. Says WHICH of the three
				-- content edges decided this was a new message, so a doubled line in the console
				-- names its own cause. Silent on the first message of a run, when there is nothing
				-- to have changed FROM.
				if said_text then
					-- ⚠ SHARPENED 2026-09-06 after a second round: knowing the text CHANGED was not
					-- enough, because the line spoken after each reset was identical — so page one was
					-- stable and something else in the buffer was not. This says WHAT, which is the
					-- difference between an answer and another theory: how many pages the buffer now
					-- parses into, how long the String says it is, and the tail of the last page.
					dbg("dlg: new message — " ..
						(full ~= said_text and "the text changed"
						 or first ~= last_first and "the buffer moved"
						 or "the cursor restarted")
						.. " (" .. #pages .. "p len=" .. ((last - first) // 2)
						.. " last=" .. pages[#pages].text:sub(1, 28) .. ")")
				end
				said_text, said_n = full, 0
				if newer then last_off = nil end
			end
			last_first = first
			if off then last_off = off end

			-- WHICH PAGE IS ON SCREEN (page_at, above). With no live printer we know only that page
			-- one is up, and that is the honest answer: an instant message never creates a printer
			-- and cannot carry a page break (the engine's synchronous renderer would stall on one),
			-- while a finished message was already followed page by page while its printer lived,
			-- because every break waits for an A press and so cannot be crossed between two frames.
			local shown = page_at(pages, cursor)

			-- Say only the page that is up. Earlier ones would each be cut off by the next in the
			-- same frame anyway, and the screen is showing this one (CLAUDE.md Rule 1: interrupt
			-- what has replaced what came before).
			if shown > said_n then
				said_n = shown
				prompt_serial = prompt_serial + 1
				say(pages[shown].text)
			end
			return true
		end,
	}
	local read = MODULES[#MODULES].update
	field_dialogue_step = function()
		forget_when_the_run_ends()
		return read(), prompt_serial
	end
end)()

-- 7) THE OPENING — Professor Rowan's introduction, before any save file or field map exists.
--
-- ⛔ THIS IS WHY IT WAS SILENT. The dialogue reader above gates on the FIELD application, and the
-- intro is not the field: it is its own application (gRowanIntroAppTemplate), running its own
-- overlay, with its own message buffer. There is no ScriptManager, no msgBuf and no field map
-- anywhere in it, so every gate in module 1 correctly answered "not my screen" — Ola opened a new
-- game and heard nothing at all.
--
-- ⚠ AND IT SHARES AN ADDRESS WITH THE FIELD. The intro's overlay 73 and the field's overlay 5 BOTH
-- load at 0x021D0D80, because overlays that can never be resident together deliberately reuse the
-- range. That is why app_data() checks the overlay id as well as the callback.
--
-- THREE SURFACES, TWO of which share one String — all offsets read out of the retail cartridge in
-- RowanIntro_DisplayMessage (0x021D1510), RowanIntro_DisplayTextBlock (0x021D1784) and
-- RowanIntro_ChoiceBox (0x021D1648), never from the struct declaration:
--   * the message box      — displayMessageState +0x50 == 1, text in string +0x5C, printer slot in
--                            textPrinterID +0x58. Pages exactly like field dialogue.
--   * the info text blocks — displayTextBlockState +0x54 in 1..4, SAME string +0x5C, rendered with
--                            TEXT_SPEED_INSTANT so there is no printer at all.
--   * the choice box       — choiceBoxState +0x2C == 1, options in the StringList at +0x44, cursor
--                            in the ListMenu at +0x40.
