		[99]="Gimnasio Corazón", [100]="Gimnasio Corazón", [122]="Gimnasio Pradera",
		[133]="Gimnasio Rocavelo", [154]="Gimnasio Marina", [155]="Gimnasio Marina",
		[156]="Gimnasio Marina", [167]="Gimnasio Puntaneva",
