		[1112]={[2]="@rival", [3]="@counterpart", [4]="Serbal", [5]="Mamá", [6]="Roco", [7]="Gardenia", [8]="Fantina", [9]="Brega", [10]="Mananti", [11]="Acerón", [14]="Cintia", [15]="Fausto", [16]="Brega", [12]={{"Maylene",{2,16462,1,14},{2,16474,1,0}},{"Maylene",{2,16462,1,14},{2,16474,2,0},{2,16474,1,1}},{"Maylene",{2,16462,1,14},{2,16474,2,0},{2,16474,2,1},{2,16474,1,2}},{"Maylene",{2,16462,1,14},{2,16474,2,0},{2,16474,2,1},{2,16474,2,2},{2,16474,1,3}},{"Maylene",{2,16462,1,14},{2,16474,2,0},{2,16474,2,1},{2,16474,2,2},{2,16474,2,3},{2,16474,1,4},{1,2473,0}},{"Maylene",{2,16462,1,14},{2,16474,2,0},{2,16474,2,1},{2,16474,2,2},{2,16474,2,3},{2,16474,1,4},{1,2473,1}},{"Candice",{2,16462,2,14},{2,16474,1,0}},{"Candice",{2,16462,2,14},{2,16474,2,0},{2,16474,1,1}},{"Candice",{2,16462,2,14},{2,16474,2,0},{2,16474,2,1},{2,16474,1,2}},{"Candice",{2,16462,2,14},{2,16474,2,0},{2,16474,2,1},{2,16474,2,2},{2,16474,1,3}},{"Candice",{2,16462,2,14},{2,16474,2,0},{2,16474,2,1},{2,16474,2,2},{2,16474,2,3},{2,16474,1,4}}}, [13]={{"Volkner",{2,16462,1,13},{2,16474,1,0}},{"Volkner",{2,16462,1,13},{2,16474,2,0},{2,16474,1,1}},{"Flint",{2,16462,1,13},{2,16474,2,0},{2,16474,2,1},{2,16474,1,2}},{"Flint",{2,16462,1,13},{2,16474,2,0},{2,16474,2,1},{2,16474,2,2},{2,16474,1,3}},{"Flint",{2,16462,1,13},{2,16474,2,0},{2,16474,2,1},{2,16474,2,2},{2,16474,2,3},{2,16474,1,4}},{"Volkner",{2,16462,2,13},{2,16474,1,0}},{"Volkner",{2,16462,2,13},{2,16474,2,0},{2,16474,1,1}},{"Volkner",{2,16462,2,13},{2,16474,2,0},{2,16474,2,1},{2,16474,1,2}},{"Volkner",{2,16462,2,13},{2,16474,2,0},{2,16474,2,1},{2,16474,2,2},{2,16474,1,3}},{"Volkner",{2,16462,2,13},{2,16474,2,0},{2,16474,2,1},{2,16474,2,2},{2,16474,2,3},{2,16474,1,4}}},},
