	--[[ STORYSCRIPT:END ]]

	-- A baked entry is either a NAME, or an ordered list of rules for the four places where the game
	-- genuinely decides between two people — the Resort Area Villa's rotating guests, and one Battle
	-- Hall slot. A rule is {name, test, test, ...}; a test is {1, flagID, want} or {2, varID, cmp, n}.
	-- ⛔ AN UNANSWERABLE TEST STOPS THE WHOLE THING, it does not skip to the next rule. If we cannot
	-- tell whether rule 1 matches, we cannot know that rule 2 is the one that applies either — and
	-- guessing here puts the wrong person's name on somebody, which Ola has said is worse than
	-- "Person". Same reason the pathfinder treats an unloaded tile as impassable rather than open.
	local function story_name(arch, sc)
		local m = STORY_SCRIPT[arch]
		local e = m and m[sc]
		if type(e) ~= "table" then return e end
		for i = 1, #e do
			local r, ok = e[i], true
			for j = 2, #r do
				local t = r[j]
				local v
				if t[1] == 1 then
					local f = story_flag(t[2])
					if f == nil then return nil end
					v = (f == (t[3] == 1))
				else
					local n = story_var(t[2])
					if n == nil then return nil end
					local c, w = t[3], t[4]
					v = (c == 1 and n == w) or (c == 2 and n ~= w) or (c == 3 and n < w)
						or (c == 4 and n <= w) or (c == 5 and n > w) or (c == 6 and n >= w)
				end
				if not v then ok = false; break end
			end
			if ok then return r[1] end
		end
		return nil
	end

	-- ── THE ENTITIES ────────────────────────────────────────────────────────────────────────────
	--
	-- Two sources, and they answer different questions:
	--   * the current MAP HEADER DATA (FieldSystem +0x14) — the parsed, live copy of this map's event
	--     lists. Warps live here. It is more authoritative than the ROM's own event archive because a
	--     map-init script can move a warp before play begins.
	--   * the live MAP OBJECT MANAGER (FieldSystem +0x38) — everything the game has actually SPAWNED.
	--     People, ground balls, HM obstacles and signboards are all MapObjects and are all here.
	-- ⭐ THE LIVE MANAGER IS WHY THIS LIST CAN BE TRUSTED. The static event list says what a map CAN
	-- hold, so it over-counts: a story NPC who has left, an item already picked up, a tree already cut.
	-- Gen V learned that the expensive way. Reading what is spawned gives correct behaviour for free —
	-- including the one ground item in the game that is injected by code and appears in no event
	-- archive at all (the Griseous Orb).
	--
	-- MapHeaderData, proved in MapHeaderData_ParseEvents (retail 0x0203A5B0):
	--   +0x00 u32 bgCount   +0x10 BgEvent*    stride 0x14
	--   +0x08 u32 warpCount +0x18 WarpEvent*  stride 0x0C
	--   +0x20 .. +0x81F     the buffer all four lists point into (0x0203A3F4 refuses a bigger member)
	-- WarpEvent:  +0x00 u16 x, +0x02 u16 z, +0x04 u16 destMapHeaderID, +0x06 u16 destWarpID
	--             (MapHeaderData_GetWarpEventByIndex 0x0203A450 for the stride and the bound;
	--             Field_MapConnection 0x021D2D90-0x021D2D94 for the field meanings, at the point the
	--             game itself reads them to perform the transition)
	-- BgEvent:    +0x00 u16 scriptID, +0x02 u16 type, +0x04 s32 x, +0x08 s32 z
	--             (FieldEvent_GetInteractedWallSignScript 0x0203CB80 reads x at +4, z at +8, and
	--             requires type 1 for a wall sign)
	local FS_MHD = 0x14
	local MHD_BGN, MHD_WARPN, MHD_BGP, MHD_WARPP = 0x00, 0x08, 0x10, 0x18
	local MHD_BUF, MHD_BUFLEN = 0x20, 0x800
	local WARP_STRIDE, BG_STRIDE = 0x0C, 0x14
	local BG_TYPE_WALLSIGN = 1
	-- BG_EVENT_TYPE_FACING 0: FieldEvent_GetInteractedBgEventScript (0203CA6C) runs it when the tile
	-- in front of the player holds it (x +4, z +8) and BgEvent_CheckPlayerFacingDirection (0203CB18)
	-- accepts the player's facing against +0x10: 4 any; player north 0 or 6, south 3 or 6, and by
	-- the generated order west 2 or 5, east 1 or 5. No height test. Value -> where the player stands.
	PM.spot.facing = 0
	PM.spot.stand = { [0] = { { 0, 1 } }, [1] = { { -1, 0 } }, [2] = { { 1, 0 } }, [3] = { { 0, -1 } },
		[4] = { { 0, 1 }, { 0, -1 }, { 1, 0 }, { -1, 0 } }, [5] = { { 1, 0 }, { -1, 0 } }, [6] = { { 0, 1 }, { 0, -1 } } }
	-- Poketch app 6 (overlay 34). Opening it reveals uncollected hidden events
	-- in this map. Radar controls retain the native search and spoken results.
	local dowsing = {
		text = { radar = "Radar", previous = "Aplicación anterior", next = "Aplicación siguiente", app = "Aplicación",
		         here = "aquí", item = WORD_ITEM, none = "No se detectan objetos", near = "Hay un objeto cerca",
		         stopped = "Guiado desactivado", hints = "Up and down select rows. Left and right select columns. Confirm searches. App controls are above the first row.", keyboard = "H confirms. Escape returns to the overworld list." },
		row = 8, column = 8, action = 1,
	}
	function dowsing.bad(reason)
		if dowsing.lastbad ~= reason then dbg("dowsing: " .. reason) end
		dowsing.lastbad = reason
		return nil
	end
	function dowsing.system(fs)
		if u32(fs + 0xC) ~= u32(A.sSaveDataPtr) then return dowsing.bad("save owner") end
		local field = u32(fs + 4)
		if not inram(field) or not inram(field + 0x27) then return dowsing.bad("field graphics") end
		local p = u32(field + 0x14)
		if p == 0 then return nil end -- Poketch unavailable on this field
		if not inram(p) or not inram(p + 0x63) then return dowsing.bad("PoketchSystem") end
		if u32(p + 0x5C) ~= fs or u32(p + 0x34) ~= field + 0x14 then return dowsing.bad("Poketch owners") end
		if u8(p) ~= 1 or u8(p + 1) ~= 0 or u8(p + 2) ~= 2 or u8(p + 5) ~= 0 then return nil end
		local id = u32(p + 0x14)
		if id > 24 then return dowsing.bad("app ID") end
		return p, id
	end
	function dowsing.work(p, id)
		if id ~= 6 then return nil end
		if u32(p + 0x18) ~= 34 or u32(p + 0x3C) ~= 0x022563F5
		   or u32(p + 0x40) ~= 0x022564B5 then return dowsing.bad("app callbacks") end
		local w = u32(p + 0x24)
		if not inram(w) or not inram(w + 0x53) then return dowsing.bad("app work") end
		if u32(w + 0x4C) ~= p then return dowsing.bad("app owner") end
		if u8(w) ~= 1 or u8(w + 2) ~= 0 then return nil end
		local g = u32(w + 0x48)
		if not inram(g) or not inram(g + 0x8F) then return dowsing.bad("radar graphics") end
		if u32(g) ~= w + 4 or u32(g + 8) ~= 8 or u32(g + 12) ~= 0x12345678 then
			return dowsing.bad("radar graphics owner")
		end
		return w, g
	end
	function dowsing.events(fs)
		local mhd = u32(fs + FS_MHD)
		if not inram(mhd) or not inram(mhd + MHD_BUF + MHD_BUFLEN - 1) then return dowsing.bad("event owner") end
		local n, events = u32(mhd + MHD_BGN), u32(mhd + MHD_BGP)
		if n == 0 then return 0, 0 end
		if n > MHD_BUFLEN // BG_STRIDE or events < mhd + MHD_BUF
		   or events + n * BG_STRIDE > mhd + MHD_BUF + MHD_BUFLEN then return dowsing.bad("event span") end
		return n, events
	end
	function dowsing.available(fs, e)
		local h = e.hidden
		if not h or h.fs ~= fs or h.map ~= map_id(fs) then return false end
		local p, id = dowsing.system(fs)
		if p ~= h.system or id ~= 6 then return false end
		local w = dowsing.work(p, id)
		if w ~= h.work then return false end
		local n, events = dowsing.events(fs)
		local ev = h.event
		if not n or not ev or ev < events or ev >= events + n * BG_STRIDE
		   or (ev - events) % BG_STRIDE ~= 0 then return false end
		return u16(ev) == h.script and u16(ev + 2) == 2
		       and s32(ev + 4) == e.x and s32(ev + 8) == e.z
		       and story_flag(h.script - 0x1C66) == false
	end
	function dowsing.capture(fs, w, g)
		if not dowsing.pending then return end
		if u8(w + 1) ~= 1 or u32(g + 0x6C) ~= 1 then
			dowsing.ping = nil
			if dowsing.pending then dowsing.pending.ready = true end
			return
		end
		local result, count = u32(w + 12), u32(w + 16)
		if result > 2 or count > 8 or (result ~= 2 and count ~= 0) then return dowsing.bad("radar result") end
		if result ~= 2 then
			if dowsing.pending and dowsing.pending.ready then say(result == 1 and dowsing.text.near or dowsing.text.none, true); dowsing.pending = nil end
			return
		end
		if count == 0 then return dowsing.bad("empty nearby result") end
		local first = u32(g + 0x38)
		if not inram(first) or not inram(first + 0x8A) then return dowsing.bad("item sprite") end
		if u8(first + 0x8A) ~= 0 then return end -- ping has not displayed its dots yet
		if dowsing.ping == w then return end
		local px, pz = player(fs)
		if not px then return dowsing.bad("radar player") end
		local n, events = dowsing.events(fs)
		if not n then return end
		local found = {}
		for i = 0, count - 1 do
			local r, sprite = w + 20 + i * 6, u32(g + 0x38 + i * 4)
			local sx, sy = u16(r), u16(r + 2)
			if sx < 35 or sx > 189 or sy < 24 or sy > 167 or (sx - 112) % 11 ~= 0
			   or (sy - 101) % 11 ~= 0 or u16(r + 4) > 2 then return dowsing.bad("radar coordinates") end
			if not inram(sprite) or not inram(sprite + 0x8A) or u8(sprite + 0x8A) ~= 0
			   or s32(sprite + 0x68) ~= sx * 4096 or s32(sprite + 0x6C) ~= sy * 4096 then
				return dowsing.bad("rendered item position")
			end
			local x, z = px + (sx - 112) // 11, pz + (sy - 101) // 11
			for j = 0, n - 1 do
				local ev = events + j * BG_STRIDE
				local script = u16(ev)
				if u16(ev + 2) == 2 and script >= 8000 and script < 8800
				   and s32(ev + 4) == x and s32(ev + 8) == z and story_flag(script - 0x1C66) == false then
					found[#found + 1] = { name = dowsing.text.item, x = x, z = z }
					break
				end
			end
		end
		dowsing.ping = w
		if dowsing.pending and dowsing.pending.ready then
			dowsing.pending = nil
			for i, e in ipairs(found) do say(e.name .. ", " .. dirword(px, pz, e.x, e.z) .. ", " .. i .. " de " .. #found, i == 1) end
		end
	end
	function dowsing.list(fs)
		local out = {}
		local p, id = dowsing.system(fs)
		local w = p and dowsing.work(p, id)
		if not w then return out end
		local n, events = dowsing.events(fs)
		if not n then return out end
		local map = map_id(fs)
		for i = 0, n - 1 do
			local ev = events + i * BG_STRIDE
			local script = u16(ev)
			if u16(ev + 2) == 2 and script >= 8000 and script < 8800
			   and story_flag(script - 0x1C66) == false then
				out[#out + 1] = { name = dowsing.text.item, key = "H" .. script,
					x = s32(ev + 4), z = s32(ev + 8),
					hidden = { fs = fs, system = p, work = w, map = map, script = script, event = ev } }
			end
		end
		return out
	end
	function dowsing.control_line(id)
		if id ~= 6 or dowsing.row == 0 then
			return (dowsing.action == 1 and dowsing.text.previous or dowsing.text.next) .. ", " .. dowsing.action .. " de 2"
		end
		return dowsing.text.radar .. ", " .. dirword(8, 8, dowsing.column, dowsing.row)
		       .. ", " .. ((dowsing.row - 1) * 15 + dowsing.column) .. " de 210"
	end
	function dowsing.step(fs, pressed)
		local p, id = dowsing.system(fs)
		local w, g
		if p then w, g = dowsing.work(p, id) end
		if dowsing.owner ~= w or dowsing.map ~= map_id(fs) then
			dowsing.ping, dowsing.owner, dowsing.map = nil, w, map_id(fs)
			dowsing.pending = nil
		end
		if w then dowsing.capture(fs, w, g) end
		local rt = keys.held()[pad.PAD .. "RightTrigger"] and true or false
		if dowsing.keyboard and pressed.Escape then
			dowsing.keyboard, dowsing.rt = false, false
			pressed.K = true -- return to the current overworld selection
			return false
		end
		local entering = not rt and not dowsing.keyboard and pressed.H and p
		if entering then dowsing.keyboard = true end
		if not p or not (rt or dowsing.keyboard) then
			dowsing.rt = false
			return dowsing.keyboard and true or false
		end
		local moved = pressed.J or pressed.L or pressed.I or pressed.O
		if id == 6 then
			if pressed.J then dowsing.row = (dowsing.row + 14) % 15 end
			if pressed.L then dowsing.row = (dowsing.row + 1) % 15 end
		end
		if id ~= 6 or dowsing.row == 0 then
			if pressed.I or pressed.J and id ~= 6 then dowsing.action = 1 end
			if pressed.O or pressed.L and id ~= 6 then dowsing.action = 2 end
		else
			if pressed.I then dowsing.column = (dowsing.column + 13) % 15 + 1 end
			if pressed.O then dowsing.column = dowsing.column % 15 + 1 end
		end
		if not dowsing.rt or dowsing.app ~= id then
			say(dowsing.text.app .. " " .. (id + 1), true)
			say(dowsing.control_line(id), false)
			if id == 6 then say(dowsing.text.hints, false) end
			if dowsing.keyboard then say(dowsing.text.keyboard, false) end
		elseif moved then say(dowsing.control_line(id), true) end
		dowsing.rt, dowsing.app = true, id
		if pressed.H and not entering and not touch.busy() then
			if id ~= 6 or dowsing.row == 0 then
				dowsing.touching = touch.tap(240, dowsing.action == 1 and 64 or 128, 1)
			else
				dowsing.ping = nil
				dowsing.pending = { ready = w and u8(w + 1) == 0 }
				dowsing.touching = touch.tap(112 + (dowsing.column - 8) * 11, 101 + (dowsing.row - 8) * 11, 1)
			end
		end
		return true
	end
	pad.register_rt(function()
		local fs = field_ready()
		return fs and dowsing.system(fs) ~= nil
	end, true)
	-- MapObject fields beyond the ones the player uses, each from its own retail accessor
	-- (0x02062910 / 0x02062918 / 0x02062920 / 0x02062950 / 0x02062960).
	local MO_LOCALID, MO_MAPID, MO_GFX, MO_TRAINER, MO_SCRIPT = 0x08, 0x0C, 0x10, 0x18, 0x20
	-- The manager and the fields the OCCUPANCY reader shares with the list — declared here, with the
	-- rest of the object model, because both readers walk the same array and a second copy of these
	-- numbers is a second place for them to drift.
	local MOM_MAX, MOM_ARRAY = 0x04, 0x124
	local MO_NOCOLLIDE = 1 << 18       -- the bit the PLAYER's own collision check skips; see occupied()
	local MO_XPREV, MO_ZPREV = 0x58, 0x60
	local MOM_FS = 0x128                       -- the manager's back-pointer to its own FieldSystem
	local MO_HIDDEN, MO_CLONE = 0x200, 0x2000000
	local GFX_BALL, GFX_HM_LO, GFX_HM_HI = 0x57, 0x54, 0x56
	local GFX_SIGN_LO, GFX_SIGN_HI = 0x5B, 0x60
	local GFX_DETACHED = 0xFFFF                -- no graphics at all: an invisible helper object
	local MOM_EXPECT = 64                      -- FieldMapChange_CreateObjects 0x02053326 `movs r1,#0x40`

	-- Build the raw per-category lists for this map. Positions are TILES throughout and in the same
	-- space as the player — warps, BG events and live objects all agree, and nothing here divides by
	-- 16. (Gen V's warps were in world units while its actors were in tiles, and mixing them announced
	-- a bridge as "3,000 steps south" when it was north.)
	-- Parsed events and spawned objects have different owners. The STATIC half — warps and wall signs — comes from the map's parsed event
	-- lists. Scripts can relocate those events, so it is refreshed on navigation keys. The LIVE half —
	-- people, ground balls, obstacles, signboards — is rebuilt on EVERY nav press, because that is
	-- exactly what changes: someone walks away, an item is picked up, a tree is cut down.
	-- Caching the live half per map was the first version of this, and the offline harness caught it
	-- immediately: objects added after the list was built were invisible for as long as the player
	-- stayed in the room. That is the same over-counting failure the static event list has, arrived at
	-- from the other direction — and it would have been nearly impossible to diagnose in game, because
	-- it only shows up as "the list is stale" some minutes into a room.

	-- Windworks' native script swaps a warp and a north-facing BG interaction.
	-- Match the authored event pair and its live identities; arbitrary BG events
	-- are not doors. Source: scripts_valley_windworks_outside.s.
	local function windworks_door(fs)
		if map_id(fs) ~= 200 or not PM.rom_member then return nil end
		local mhd = u32(fs + FS_MHD)
		if not inram(mhd) or not inram(mhd + 0x81F) then return nil end
		local bn, bp = u32(mhd + MHD_BGN), u32(mhd + MHD_BGP)
		local wn, wp = u32(mhd + MHD_WARPN), u32(mhd + MHD_WARPP)
		if bn ~= 2 or wn ~= 1 or bp < mhd+MHD_BUF or bp+bn*BG_STRIDE > mhd+0x820
			or wp < mhd+MHD_BUF or wp+WARP_STRIDE > mhd+0x820 then return nil end
		local id = u16(A.sMapHeaders + 200*MH_STRIDE + 0x10)
		local rom, size = PM.rom_member("fielddata/eventdata/zone_event.narc",id,8)
		if not rom or PM.rom_read(rom,4) ~= bn then return nil end
		local bg = rom+4+BG_STRIDE
		local at = 4+bn*BG_STRIDE
		if at+4 > size then return nil end
		local objects = PM.rom_read(rom+at,4)
		if not objects then return nil end
		at = at+4+objects*0x20
		if at+4+WARP_STRIDE > size or PM.rom_read(rom+at,4) ~= 1 then return nil end
		local warp = rom+at+4
		local x,z = PM.rom_read(warp,2),PM.rom_read(warp+2,2)
		if not x or not z or PM.rom_read(warp+4,2) ~= 201 or PM.rom_read(warp+6,2) ~= 0
			or PM.rom_read(bg,2) ~= 4 or PM.rom_read(bg+2,2) ~= 0
			or PM.rom_read(bg+4,4) ~= x or PM.rom_read(bg+8,4) ~= z
			or PM.rom_read(bg+0x10,2) ~= 0 then return nil end
		local live = bp+BG_STRIDE
		if u16(live) ~= 4 or u16(live+2) ~= 0 or u16(live+0x10) ~= 0
			or s32(live+4) ~= x or s32(live+8) ~= z
			or u16(wp+4) ~= 201 or u16(wp+6) ~= 0
			or x ~= 243 or z ~= 654 or u16(wp) ~= 243 or u16(wp+2) ~= 650 then return nil end
		local name = door_name(201)
		if name then return {name=name,key="Bdoor1",x=x,z=z,dz=201,door_bg=live} end
	end

	-- The static half: warps and wall signs, from the map's own parsed event lists.
	-- Artwork-only marks, verified against fldeff.narc models 0x74..0x7B.
	local hearthome = {text={blue="Baldosa azul", red="Puerta roja", symbols={
		"Círculo", "Cuadrado", "Triángulo", "Sol", "Anillo", "Luna creciente", "Estrella", "Corazón"}}}
	function hearthome.door(fs,x,z)
		local id=map_id(fs)
		local xs=id==89 and {4,8,12} or id==90 and {4,9,14,19,24}
		if xs and z==2 then
			for i,v in ipairs(xs) do
				if x==v then return hearthome.text.red..", "..hearthome.text.symbols[i+(id==90 and 3 or 0)] end
			end
		end
	end
	function hearthome.snapshot(fs)
		local id=map_id(fs)
		if id~=89 and id~=90 then hearthome.known=nil; return nil end
		local function bad(why)
			if hearthome.error~=why then dbg("Hearthome Gym: "..why) end
			hearthome.error=why
			return nil
		end
		if u32(fs+0xC)~=u32(A.sSaveDataPtr) then return bad("save owner") end
		local misc=save_page(10,0x794,"Hearthome Gym")
		if not misc or not inram(misc+0x70B) then return bad("persisted feature span") end
		if u32(misc+0x700)~=2 then return bad("persisted feature type") end
		if u16(misc+0x704)~=1 then return bad("clue uninitialized") end
		local symbol,x,z=u16(misc+0x706),u16(misc+0x708),u16(misc+0x70A)
		local first,count,width,height=id==89 and 0 or 3,id==89 and 3 or 5,id==89 and 15 or 27,id==89 and 8 or 20
		if symbol<first or symbol>=first+count then return bad("room symbol") end
		if x<1 or x>=1+width or z<3 or z>=3+height then return bad("clue coordinates") end
		local field=u32(fs+4)
		if not inram(field+0x27) then return bad("field manager") end
		local gym=u32(field+0x24)
		if not inram(gym) or u32(gym)~=fs then return bad("gym owner") end
		local key=table.concat({fs,id,misc,symbol,x,z},":")
		if hearthome.identity~=key then hearthome.identity=key; hearthome.known=nil; hearthome.on_tile=false end
		hearthome.error=nil
		return {key=key,x=x,z=z,symbol=hearthome.text.symbols[symbol+1]}
	end
	function hearthome.entry(fs)
		local clue=hearthome.snapshot(fs)
		if not clue then return nil end
		return {name=hearthome.text.blue..(hearthome.known and (", "..clue.symbol) or ""),
			key="HearthomeClue",x=clue.x,z=clue.z,clue=clue.key}
	end
	function hearthome.step(fs,id)
		if id~=89 and id~=90 then
			hearthome.identity,hearthome.known,hearthome.on_tile=nil,nil,false
			return
		end
		local clue=hearthome.snapshot(fs)
		if not clue then return end
		local x,z=player(fs)
		local on=x==clue.x and z==clue.z
		if on and not hearthome.on_tile then
			hearthome.known=true
			say(hearthome.text.blue..", "..clue.symbol,true)
		end
		hearthome.on_tile=on
	end

	-- ── VEILSTONE GYM: punching bags on rails, and the tire stacks they knock down ───────────────
	-- src/overlay008/gym_features.c, retail ov8. Walking into a bag (field_control.c:567) slides it
	-- along its rail until VeilstoneGym_GetTileFlags (0224BA0C) stops it; a stack beyond the stop is
	-- toppled and deleted. Both are invisible-graphics MapObjects with one shared local id, so the list
	-- must classify them by the gym's own arrays rather than call them people. Only bags are listed (the
	-- player's choice, 2026-10-30); stacks stay obstacles to occupancy and to the planner below.
	-- FieldSystem+4 -> field manager+24 -> VeilstoneGymSystem, 0x1E4 bytes (Init 0224B764:
	-- `movs r1,#0x79 ; lsls r1,#2`, `str r4,[r0,#0x24]`, `str r5,[r4]` owner back-pointer).
	-- Entries are 0x18: exists +0, x +8, z +0xC, MapObject +0x10 (InitAnimManagerForObject 0224B80C
	-- gets entry+8; RemoveTireStack clears +0). Stacks at +4 x11 (GetTireStackAtPosition 0224B87C
	-- `adds r0,#4`), bags at +0x10C x9 (GetPunchingBagAtPosition `movs r3,#0x43 ; lsls r3,#2`).
	-- Persisted feature 4 with initialized +4 at Misc+700/+704 (Init 0224B770 `movs r1,#4`).
	local veilstone = {text={bag="Saco de boxeo"}}
	do
		local GYM_SIZE, STACKS, BAGS, STRIDE = 0x1E4, 0x04, 0x10C, 0x18
		-- `detail` carries the values read, so the console line pins the hop; the repeat test keys on
		-- `why` alone so a failing frame logs once rather than every press.
		local function bad(why, detail)
			if veilstone.error ~= why then dbg("Veilstone Gym: "..why..(detail and (" ("..detail..")") or "")) end
			veilstone.error = why
			return nil
		end
		function veilstone.active(fs) return map_id(fs) == 133 end
		-- ⛔ THE HELPERS' LOCAL ID IS READ FROM THE GAME'S OWN CODE, NEVER ASSUMED. Retail stamps 0xFD;
		-- a follower-Pokémon patch of this cartridge code (2026-10-31) moves the helpers to 0xFC in both
		-- instructions below and gives 0xFD to the follower, whose data[0] is its species. Assuming 0xFD
		-- there classified the follower as a bag and rejected every real one. Both sites must agree
		-- and both opcodes must be the expected ones, inside the identity-checked overlay.
		function veilstone.helper_id()
			if u32(A.VeilstoneGymTileBehavior+0x30) ~= A.VeilstoneGymTileBehaviors then
				return bad("tile behavior overlay identity")
			end
			local make, find = u16(A.VeilstoneGymCreateLocalID), u16(A.VeilstoneGymReinitLocalID)
			if make >> 8 ~= 0x21 or find >> 8 ~= 0x28 or make & 0xFF ~= find & 0xFF then
				return bad("helper local id", string.format("create %04X reinit %04X", make, find))
			end
			return make & 0xFF
		end
		-- The validated live puzzle: behavior table, every bag, every standing stack and a signature
		-- that changes exactly when a kick moved something. nil whenever any hop disagrees.
		-- ⚠ Never memoized in a caller's cache: the navigation cache outlives kicks, and a stale bag
		-- would route the player to the wrong side of it. About thirty reads; only on presses and re-plans.
		function veilstone.snapshot(fs)
			if not veilstone.active(fs) then return nil end
			if u32(fs+0xC) ~= u32(A.sSaveDataPtr) then return bad("save owner") end
			local misc = save_page(10,0x794,"Veilstone Gym")
			if not misc or not inram(misc+0x707) then return bad("persisted feature span") end
			if u32(misc+0x700) ~= 4 then return bad("persisted feature type") end
			if u32(misc+0x704) ~= 1 then return bad("puzzle uninitialized") end
			local field = u32(fs+4)
			if not inram(field+0x27) then return bad("field manager") end
			local gym = u32(field+0x24)
			if not inram(gym) or not inram(gym+GYM_SIZE-1) or u32(gym) ~= fs then return bad("gym owner") end
			local hid = veilstone.helper_id()
			if not hid then return nil end
			local beh = veilstone.beh
			if not beh then
				beh = {}
				for i = 0, 1023 do
					local v = u8(A.VeilstoneGymTileBehaviors+i)
					if v > 5 then return bad("tile behavior value") end
					beh[i] = v
				end
				-- Bags never leave the rails, so the border must be solid for the slide walk to stop.
				for i = 0, 31 do
					if beh[i] ~= 1 or beh[992+i] ~= 1 or beh[i*32] ~= 1 or beh[i*32+31] ~= 1 then
						return bad("tile behavior border")
					end
				end
				veilstone.beh = beh
			end
			-- The live helpers, classified the way VeilstoneGym_ReinitMapObjects (0224B958) does it:
			-- the helper local id, then data[0] (+0x38, MapObject_GetDataAt 020629D8) 0 = stack,
			-- 1 = bag. Each gym entry must name, by its MapObject pointer (+0x10), the live helper of
			-- its kind on its own tile, and every live helper must belong to an entry.
			local mm = u32(fs+FS_OBJMAN)
			if not inram(mm) or u32(mm+MOM_FS) ~= fs then return bad("object manager") end
			local arr = u32(mm+MOM_ARRAY)
			if s32(mm+MOM_MAX) ~= MOM_EXPECT or not inram(arr) or not inram(arr+MOM_EXPECT*MO_STRIDE-1) then
				return bad("object array")
			end
			local live = { bag = {}, stack = {} }
			for i = 0, MOM_EXPECT-1 do
				local o = arr + i*MO_STRIDE
				if (u32(o+MO_STATUS) & MO_INUSE) ~= 0 and u32(o+MO_LOCALID) == hid then
					local flag = u32(o+0x38)
					if flag > 1 then return bad("helper kind", string.format("object %08X data %X", o, flag)) end
					local x, z = s32(o+MO_X), s32(o+MO_Z)
					-- The MapObject is only moved when the slide stops (SetX/SetZ, then UpdateCoords copies
					-- them to prev), so a mid-slide or unsettled difference is no state to plan from.
					if s32(o+MO_XPREV) ~= x or s32(o+MO_ZPREV) ~= z then return bad("helper settling") end
					local kind = flag == 1 and "bag" or "stack"
					local k = x..","..z
					if live[kind][k] then return bad("two helpers on one tile", kind.." "..k) end
					live[kind][k] = o
				end
			end
			local used, counts = { bag = 0, stack = 0 }, { bag = 0, stack = 0 }
			for _, kind in ipairs({"bag", "stack"}) do
				for _ in pairs(live[kind]) do counts[kind] = counts[kind] + 1 end
			end
			local function object(entry, kind)
				local x, z = s32(entry+8), s32(entry+0xC)
				if x < 1 or x > 30 or z < 1 or z > 30 then return bad(kind.." coordinates") end
				local o = live[kind][x..","..z]
				if not o then return bad(kind.." without a live object", x..","..z) end
				if u32(entry+0x10) ~= o then
					return bad(kind.." entry names another object", string.format("entry %08X names %08X, tile holds %08X",
						entry, u32(entry+0x10), o))
				end
				used[kind] = used[kind] + 1
				return {x=x,z=z,actor=o}
			end
			local bags, stacks, sig = {}, {}, {}
			for i = 0, 8 do
				local entry = gym+BAGS+i*STRIDE
				if u32(entry) ~= 1 then return bad("bag missing") end
				local b = object(entry,"bag")
				if not b then return nil end
				bags[#bags+1] = b
				sig[#sig+1] = b.x..","..b.z
			end
			for i = 0, 10 do
				local entry = gym+STACKS+i*STRIDE
				local exists = u32(entry)
				if exists > 1 then return bad("stack flag") end
				if exists == 1 then
					local s = object(entry,"stack")
					if not s then return nil end
					stacks[#stacks+1] = s
					sig[#sig+1] = "s"..s.x..","..s.z
				end
			end
			-- Every live helper must be one the gym knows: an extra would be a wall the plan ignores.
			if used.bag ~= counts.bag or used.stack ~= counts.stack then
				return bad("helpers the gym does not list", string.format("bags %d/%d stacks %d/%d",
					used.bag, counts.bag, used.stack, counts.stack))
			end
			veilstone.error = nil
			return {fs=fs,gym=gym,beh=beh,bags=bags,stacks=stacks,sig=fs..":"..table.concat(sig,";")}
		end
		-- address -> "bag" / "stack" for the live list; nil outside the gym or when unverifiable.
		function veilstone.objects(fs)
			local snap = veilstone.snapshot(fs)
			if not snap then return nil end
			local kinds = {}
			for _, b in ipairs(snap.bags) do kinds[b.actor] = "bag" end
			for _, s in ipairs(snap.stacks) do kinds[s.actor] = "stack" end
			return kinds
		end
	end

	local function build_static(fs, inert)
		local L = { Transitions = {}, Signs = {}, Objects = {} }

		-- ── warps ───────────────────────────────────────────────────────────────────────────────
		local mhd = u32(fs + FS_MHD)
		if not inram(mhd) then
			dbg("nav: no mapHeaderData")
		else
			local n, p = u32(mhd + MHD_WARPN), u32(mhd + MHD_WARPP)
			-- Both bounds are the game's own: the count comes from the parser and the list must lie
			-- inside the 0x800-byte buffer the parser filled. A list that does not is a bad read.
			if n > 0 and inram(p) and p >= mhd + MHD_BUF
				and p + n * WARP_STRIDE <= mhd + MHD_BUF + MHD_BUFLEN
				and inram(p + n * WARP_STRIDE - 1) then
				local tiles, rows = {}, {}
				for i = 0, n - 1 do
					local e = p + i * WARP_STRIDE
					local dest = u16(e + 0x04)
					local x, z = u16(e), u16(e + 2)
					local key = x .. ":" .. z
					-- The native lookup returns the FIRST event at a coordinate.
					-- Lake entrances retain overlapping full/dry event rows.
					-- `inert` drops a warp the player is not offered (terrain.offered_warp).
					if tiles[key] == nil and inert and inert(x, z, dest) then tiles[key] = false
					elseif tiles[key] == nil then
						local row = { x=x, z=z, dz=dest, key="W" .. i, name=hearthome.door(fs,x,z) or door_name(dest, map_id(fs)) }
						tiles[key], rows[#rows + 1] = row, row
					end
				end
				-- A wide entrance has adjacent source tiles, sometimes with different
				-- destination warp indices (Oreburgh Mine uses three). Keep disconnected
				-- entrances separate even when their destination header is identical.
				local used = {}
				for _, first in ipairs(rows) do
					if first.name and not used[first] then
						local group, nextrow = { first }, 1
						used[first] = true
						while nextrow <= #group do
							local row = group[nextrow]; nextrow = nextrow + 1
							for _, d in ipairs({{0,-1},{0,1},{-1,0},{1,0}}) do
								local other = tiles[(row.x+d[1]) .. ":" .. (row.z+d[2])]
								if other and other.dz == first.dz and not used[other] then
									used[other] = true; group[#group + 1] = other
								end
							end
						end
						L.Transitions[#L.Transitions + 1] = {name=first.name, key=first.key,
							x=first.x, z=first.z, dz=first.dz, warps=group}
					end
				end
			elseif n > 0 then
				dbg("nav: warp list out of the header buffer")
			end
		end

		-- ── wall signs, which are map events rather than objects ────────────────────────────────
		if inram(mhd) then
			local n, p = u32(mhd + MHD_BGN), u32(mhd + MHD_BGP)
			if n > 0 and inram(p) and p >= mhd + MHD_BUF
				and p + n * BG_STRIDE <= mhd + MHD_BUF + MHD_BUFLEN
				and inram(p + n * BG_STRIDE - 1) then
				local spots, names = {}, PM.spot.names[map_id(fs) or -1] or {}
				for i = 0, n - 1 do
					local e = p + i * BG_STRIDE
					local kind = u16(e + 0x02)
					if kind == BG_TYPE_WALLSIGN then
						L.Signs[#L.Signs + 1] = { name = WORD_SIGN, key = "B" .. i,
							x = s32(e + 0x04), z = s32(e + 0x08) }
					elseif kind == PM.spot.facing then
						-- Interaction spots, one entry per tile (several events can share one).
						local x, z, dir = s32(e + 0x04), s32(e + 0x08), u16(e + 0x10)
						local k = x .. ":" .. z
						if PM.spot.stand[dir] then
							local spot = spots[k]
							if not spot then
								spot = { name = names[u16(e)] or PM.spot.word, key = "B" .. i, x = x, z = z, bg_stand = {} }
								spots[k] = spot
								L.Objects[#L.Objects + 1] = spot
							end
							for _, d in ipairs(PM.spot.stand[dir]) do spot.bg_stand[#spot.bg_stand + 1] = d end
						end
					end
				end
			end
		end
		local door = windworks_door(fs)
		if door then L.Transitions[#L.Transitions+1] = door end
		return L
	end

	-- The live half: everything the game has actually SPAWNED, rebuilt on every press.
	local function build_live(fs)
		local L = { NPCs = {}, Items = {}, HM = {}, Signs = {}, Objects = {} }
		local hm_ok = {}                 -- one badge read per field move per list
		-- ⚠ THE RIVAL'S NAME IS LOOKED UP ONCE PER LIST, NOT ONCE PER PERSON. It is a walk down
		-- the save's page table, and 28 objects in the game wear his sprite — the offline harness
		-- caught it repeating the whole walk, and its failure line, for every one of them.
		-- `false` means not looked up yet; nil is a real answer meaning the save would not read.
		local rival, counter, pgender = false, false, false
		-- This map's script archive, for the names people give themselves. Once per list: it is a
		-- map header read and the map cannot change while the list is being built.
		-- ⛔ EACH HOP NAMES ITS OWN FAILURE (codex-review 2026-09-06, confirmed). One shared
		-- message covered three different faults — an unreadable location, a map id the engine
		-- itself would reject, and a header record running off the end of RAM. A total loss of
		-- story names would then be undiagnosable from the console, which is the whole reason this
		-- project has the rule.
		local arch
		do
			local loc = u32(fs + FS_LOC)
			local id = inram(loc) and u32(loc + 0x00) or nil
			if not id then dbg("nav: the field's location is unreadable")
			elseif id >= MH_COUNT then dbg("nav: map id " .. id .. " is past the header table")
			else
				local rec = A.sMapHeaders + id * MH_STRIDE
				if not inram(rec + MH_STRIDE - 1) then dbg("nav: map header " .. id .. " is unreadable")
				else arch = u16(rec + MH_SCRIPTS) end
			end
		end
		-- ── the live objects ────────────────────────────────────────────────────────────────────
		local mm = u32(fs + FS_OBJMAN)
		local pmo = nil
		do
			local pa = u32(fs + FS_AVATAR)
			if inram(pa) then pmo = u32(pa + PA_OBJ) end
		end
		-- Veilstone Gym's helpers are classified by the gym's own arrays. One the gym cannot vouch
		-- for is left out rather than called a person; without the code-read helper id nothing is
		-- singled out, because guessing the id would hide whoever wears it in a patched game.
		local veil = veilstone.active(fs) and (veilstone.objects(fs) or {})
		local veil_id = veil and veilstone.helper_id()
		-- An Elite Four room's door (OBJ_EVENT_GFX_ELITE_FOUR_ROOM_DOOR, 209; its script is
		-- CommonScript_Dummy2037, a bare End) is listed only while it stands on a warp event: that
		-- is the exit, which the member's script opens with RemoveObject LOCALID_EXIT_DOOR. The
		-- entrance door is added behind the player by the room's OnFrame script (ClearFlag, AddObject
		-- LOCALID_ENTRANCE_DOOR) on the wall's gap at (8,12), on no warp, and the arrival warp
		-- (8,11) is an open tile no step fires (terrain.offered_warp): the way back is sealed for as
		-- long as the room lasts. The rooms' events are the same in the follower patch, whose
		-- OnFrame scripts only add the follower's walk. Unreadable warps: the door is left out.
		local GFX_E4_DOOR, e4_warps = 209, nil
		local function e4_door_shuts(x, z)
			if e4_warps == nil then
				e4_warps = false
				local mhd = u32(fs + FS_MHD)
				local n, p = inram(mhd) and u32(mhd + MHD_WARPN), inram(mhd) and u32(mhd + MHD_WARPP)
				if not n or (n > 0 and not (inram(p) and p >= mhd + MHD_BUF and p + n * WARP_STRIDE <= mhd + MHD_BUF + MHD_BUFLEN)) then
					dbg("nav: Elite Four door: warp events unreadable")
				else
					e4_warps = {}
					for i = 0, n - 1 do e4_warps[u16(p + i * WARP_STRIDE) .. "," .. u16(p + i * WARP_STRIDE + 2)] = true end
				end
			end
			return e4_warps and e4_warps[x .. "," .. z] or false
		end
		if not inram(mm) then
			dbg("nav: no mapObjMan")
		elseif u32(mm + MOM_FS) ~= fs then
			dbg("nav: mapObjMan belongs to another field")   -- its own back-pointer disagrees
		else
			local n = s32(mm + MOM_MAX)
			local arr = u32(mm + MOM_ARRAY)
			if n ~= MOM_EXPECT then
				dbg("nav: maxObjects is not 64")
			elseif not (inram(arr) and inram(arr + n * MO_STRIDE - 1)) then
				dbg("nav: object array unreadable")
			else
				for i = 0, n - 1 do
					local o = arr + i * MO_STRIDE
					local st = u32(o + MO_STATUS)
					-- ⛔ THREE BITS, NOT ONE, and each rules out a different kind of ghost: not
					-- spawned at all; spawned but script-HIDDEN (bit 9, what HideObject toggles); or
					-- an unresolved connection CLONE (bit 25) whose real map, script and flag have
					-- not been installed yet, so anything read off it now is the neighbouring map's.
					local gfx = u32(o + MO_GFX)
					if o ~= pmo and (st & MO_INUSE) ~= 0
						and (st & MO_HIDDEN) == 0 and (st & MO_CLONE) == 0 and not (PM.dw_skip and PM.dw_skip(fs, o, gfx)) then
						local x, z = s32(o + MO_X), s32(o + MO_Z)
						-- ⭐ THE OBJECT'S OWN ADDRESS IS ITS IDENTITY. A person who walks changes tile
						-- every second, so a route or a selection remembered by COORDINATE quietly
						-- becomes a route to where they used to be; remembered by slot it stays theirs.
						local okey = "O" .. o
						local vk = veil and (veil[o] or (veil_id and u32(o + MO_LOCALID) == veil_id))
						if vk then
							if vk == "bag" then
								L.Objects[#L.Objects + 1] = { name = veilstone.text.bag, key = okey, x = x, z = z, actor = o }
							end
						elseif gfx == GFX_BALL then
							-- ⛔ AN ITEM IS JUST "Item", AND NAMING IT WOULD BE CHEATING (Ola,
							-- 2026-09-05: "items need to just be named item since we can't see from
							-- the ground what an item is, so we can't have names here"). A Poké Ball
							-- lying on the floor looks the same whatever is inside it — a sighted
							-- player finds out by picking it up, and so should this one.
							-- ⭐ THE MACHINERY TO NAME THEM WAS BUILT AND HAS BEEN DELETED, not left
							-- commented out: the script-id-to-item table and bank 392's names are in
							-- git history if a screen ever legitimately needs them. Two of the same
							-- word in a category still get numbered, so it reads "Item 1", "Item 2" —
							-- which is what Black and White says too.
							L.Items[#L.Items + 1] = { name = WORD_ITEM, key = okey, x = x, z = z, actor = o }
						elseif gfx >= GFX_HM_LO and gfx <= GFX_HM_HI then
							-- Listed once the badge for that field move is held (Black and White's
							-- "only what you can clear", by Platinum's own rule; 2026-11-02). Unknown
							-- hides. Routes still name the move needed beyond one (occupied's gates).
							local check = gfx == 0x56 and A.FieldMovesCheckCut or gfx == 0x55 and A.FieldMovesCheckRockSmash
								or A.FieldMovesCheckStrength
							if hm_ok[check] == nil then hm_ok[check] = PM.field_move_badge(check) or false end
							if hm_ok[check] then
								L.HM[#L.HM + 1] = { name = HM_NAME[gfx], key = okey, x = x, z = z, actor = o }
							end
						elseif gfx >= GFX_SIGN_LO and gfx <= GFX_SIGN_HI then
							L.Signs[#L.Signs + 1] = { name = WORD_SIGN, key = okey, x = x, z = z, actor = o }
						elseif OBJECTS[gfx] then
							-- Not a person, and the cartridge's own sprite name says so.
							if gfx ~= GFX_E4_DOOR or e4_door_shuts(x, z) then
								L.Objects[#L.Objects + 1] = { name = OBJECTS[gfx], key = okey, x = x, z = z, actor = o }
							end
						elseif gfx ~= GFX_DETACHED then
							-- ⭐ NAME THEM IF THE GAME CAN. A sight trainer's script carries a trainer
							-- id, and that gives a real class out of the game's own bank 619 — so
							-- "Youngster, 4 north" instead of one more "Person".
							-- ⛔ SIGHT TRAINERS ONLY, and the type test is the game's own (GetTrainerType
							-- 0x02067C54 passes 0..3 through and folds 4..8 to 1). Type 3 is NOT one —
							-- some ordinary item balls use it — and a type-0 person's script id is a MAP
							-- script, so running it through the trainer arithmetic would produce a
							-- confident, arbitrary class. Rule 7: two small-integer id spaces.
							local tt = u32(o + MO_TRAINER)
							local sc = u32(o + MO_SCRIPT)
							local nm2
							if tt == 1 or tt == 2 or (tt >= 4 and tt <= 8) then
								-- Script_GetTrainerID (0x0203F254), with the bounds the game omits.
								-- ⚠ NO DISCRIMINATING TEST, and the reason is worth stating rather than
								-- leaving as an untested line: every script outside these two ranges
								-- already resolves to an id the table has no row for, so removing the
								-- bounds changes no answer today. It is kept because it makes the
								-- arithmetic's INTENT checkable, and because a future table with more
								-- rows would silently start naming things it should not.
								local tid
								if sc >= 3000 and sc <= 3926 then tid = sc - 2999
								elseif sc >= 5000 and sc <= 5926 then tid = sc - 4999 end
								local cls = tid and TRAINER_CLASS[tid]
								nm2 = cls and CLASS_NAME[cls]     -- nil for class 63, the rival
							end
							-- ⚠ AND THIS REMAINDER IS NOT PURELY PEOPLE, which the code should say
							-- out loud rather than imply. The manager is heterogeneous — people,
							-- Pokémon, berry soil, invisible helpers and runtime-added objects all
							-- share the one structure — and Gen IV has NO event-kind field and no
							-- graphics range that means "person". Everything the cartridge can
							-- positively classify is taken above; what is left is called "Person"
							-- because that is the word Black and White settled on and because most
							-- of it IS people, not because the engine says so.
							-- The one thing that can be ruled out cheaply is an object with no
							-- graphics at all (0xFFFF) — those are helpers the player cannot see.
							-- The battle class first where the cartridge gave us one, then the
							-- sprite, then the honest generic. Same order as Black and White's, minus
							-- the layers that need the script decoded.
							-- ⭐ A NAME REPLACES THE CLASS, it does not join it (Ola, questions_open.md
							-- round 1 Q2 = A): "Roark, 3 north", never "Roark, Gym Leader, 3 north".
							-- So a character's name answers first and the battle class only speaks
							-- where there is no name — which is also the order Black and White uses.
							-- ⚠ The rival's name is not in the table because it is not in the
							-- cartridge; it is in the save, and a save that cannot be read yields nil
							-- here and falls through to his sprite word rather than to a wrong name.
							-- ⛔ THE SPRITE OUTRANKS THE SCRIPT, and it is needed EXACTLY ONCE in the
							-- whole game — measured, not assumed. A cutscene slot opens on whoever
							-- speaks first, which is often not the person standing there; in Black and
							-- White that made Lenora announce herself as "Hawes". Platinum's one case
							-- is a Crasher Wake object in Pastoria whose script opens on the rival.
							-- ⭐ AND IT MUST NOT BE THE OTHER WAY ROUND. Looker and Riley both appear
							-- DISGUISED as Galactic grunts, where the sprite is the lie and the
							-- script's own line is the truth — so a generic sprite word never beats a
							-- name, only a CHARACTER's sprite does. That is why STORY_SPRITE and
							-- NPC_SPRITE are two tables and only the first one wins here.
							-- ⛔⛔ AND A NAME THAT BELONGS TO SOMEBODY ELSE IS NOT THIS THING'S NAME.
							-- Ola, 2026-09-06: Rowan's BRIEFCASE announced itself with his RIVAL'S
							-- name, because the starter scene's first line is the rival's. Every
							-- character who has a sprite of their own is in STORY_OWNER, so a script
							-- name whose owner wears a DIFFERENT sprite is provably a line somebody
							-- else speaks in that scene, and is dropped.
							-- Measured over the whole game this rejects exactly FOUR objects and all
							-- four are wrong: the briefcase, a Crasher Wake object in Pastoria whose
							-- script opens on the rival, and two Iron Island grunts that Riley
							-- speaks over. It costs nothing else — 133 objects keep their name.
							local sn = arch and story_name(arch, sc)
							if sn and STORY_OWNER[sn] and STORY_OWNER[sn] ~= gfx then sn = nil end
							local who = STORY_SPRITE[gfx] or sn
							-- Whose appearance D describes (core/describe.lua): exactly whom this list
							-- names. A story name maps through TRAINER_KEY.story; the counterpart by the
							-- same gender test that names them below; a sight trainer named by class by
							-- its sprite. Anyone the list calls "Person" has no key and stays silent.
							local dkey = who and TRAINER_KEY.story[who]
							-- ⭐⭐ THE COUNTERPART WEARS THE OTHER PROTAGONIST'S SPRITE, and that is the only
							-- thing that can name the one standing beside Rowan's briefcase: its
							-- script slot is 0, the NULL script, so no dialogue can ever reach it.
							-- (Ola, 2026-09-06: "there is one person here just labeled person. I am
							-- 90% that should be Dawn on my save since I am a boy.")
							-- ⛔ THE SPRITE MUST BE THE OPPOSITE ONE TO YOURS. Yours is you — that is
							-- what makes this identification and not a guess, and it is the same test
							-- the game makes: StringTemplate_SetCounterpartName indexes the
							-- counterpart-name bank by the gender the player is NOT.
							-- ⚠ KNOWN LIMIT, stated rather than hidden: a Battle Tower multi partner
							-- can also wear a protagonist sprite. Naming one "Dawn" there would be
							-- wrong. It is a late-game room and the alternative today is "Person" on
							-- a story character in the first hour, so this ships and the limit is
							-- written down.
							-- ⛔ RESTRICTED TO OBJECTS THE CARTRIDGE ITSELF CALLS A COUNTERPART
							-- (codex-review 2026-09-06, confirmed). Battle Tower hands a multi-battle
							-- PARTNER a protagonist sprite chosen by that partner's gender
							-- (frscrcmd_battle_tower.c:132-140) and gives it a script-0 object, so
							-- "wears the other protagonist" alone would announce a stranger as Dawn.
							-- STORY_CPSLOT is every object the event data names a counterpart, keyed
							-- by archive and script id — twelve of them, Route 201's among them.
							local cps = STORY_CPSLOT[arch]
							if not who and cps and cps[sc] and STORY_PLAYERSPR[gfx] ~= nil then
								if pgender == false then pgender = player_gender() end
								if pgender and STORY_PLAYERSPR[gfx] ~= pgender then
									if counter == false then counter = counterpart_name(STORY_COUNTERPART) end
									who = counter
									dkey = pgender == 0 and "dawn" or "lucas"
								end
							end
							if who == STORY_RIVAL then
								if rival == false then rival = rival_name() end
								who = rival
							elseif who == STORY_COUNTER then
								-- Same shape as the rival: a marker, not a word, because which of the
								-- two it is lives in the save. Looked up once per list, not per person.
								if counter == false then counter = counterpart_name(STORY_COUNTERPART) end
								who = counter
								if pgender == false then pgender = player_gender() end
								dkey = pgender == 0 and "dawn" or pgender == 1 and "lucas" or nil
							end
							if not dkey and nm2 then dkey = TRAINER_KEY.gfx[gfx] end
							-- A Pokémon with no script name (Giratina, the lake trio in the Distortion World) is
							-- named by its species, from the cartridge (PM.mon_sprite, gen_pt_nav_text.py).
							L.NPCs[#L.NPCs + 1] = { name = who or nm2 or PM.mon_sprite[gfx] or NPC_SPRITE[gfx] or WORD_PERSON,
								key = okey, x = x, z = z, actor = o, describe = dkey }
						end
					end
				end
			end
		end
		return L
	end

	-- ── THE GROUND: can I stand on this tile? ───────────────────────────────────────────────────
	--
	-- ⭐ ONE u16 PER TILE CARRIES EVERYTHING. `TerrainCollisionManager_CheckCollision` (0x02054f68) is
	-- nothing but a fetch of that halfword and a test of BIT 15; `..._GetTileBehavior` (0x02054f94) is
	-- the same fetch masked with 0xFF. All the difficulty is in the fetch — and there are TWO of them.
	--
	-- ⛔⛔ WHICH FETCH IS AN IDENTITY, NOT A GUESS. FieldSystem +0x5C points at one of two static const
	-- function tables, chosen by TerrainCollisionManager_Init from this map's own
	-- `mapLoadMode->useSimpleTerrainCollisions` (field_map_change.c:396). So the mode is a comparison
	-- against a fixed address, and a field system pointing at NEITHER is a bad read that must say
	-- nothing — which is the whole reason this is written as an identity test rather than a guess from
	-- whether landDataMan happens to look valid.
	--
	-- A) STREAMED (sTerrainCollision) — the outdoor case AND every interior, GetTileAttributes at
	--    retail 0x02054e84. It reads `FieldSystem +0x28 landDataMan` (`ldr r7,[r0,#0x28]`), then asks
	--    `LandDataManager_GetRelativeLoadedMapsQuadrantOfTile` (0x021e9580) which of FOUR loaded maps
	--    holds the tile, then `LandDataManager_GetLoadedMapTerrainAttributes` (0x021e9624) for that
	--    map's `u16` grid, and indexes it `(z % 32) * 32 + (x % 32)`.
	--
	-- ⛔⛔ AND THE SLOT IS NOT A FORMULA — THIS IS THE BUG THAT COST OLA TWO TEST ROUNDS. I computed it
	-- as `(relX/32) + (relZ/32) * windowWidth` from the window origin at +0x10C/+0x114, which is what
	-- the first half of the engine's function does — and then read the answer out of slot 0. But the
	-- engine does NOT stop there: at 0x021e95e0 it hands that cell index to
	-- `LandDataManager_GetRelativeLoadedMapsQuadrant` (0x021e9390), and THAT is a rotating-quadrant
	-- lookup, not an index. The four loaded maps are a window that ROTATES as you walk, so the map you
	-- are standing on can be in any of the four slots. His dump settled it in one line: standing in his
	-- bedroom every tile read `FFFF` — unwritten memory — because the room was not in slot 0.
	--
	-- ⭐ SO ASK THE GAME WHICH MAP IT IS, rather than reimplementing the rotation. Each `LoadedMap`
	-- records the matrix cell it holds and whether it is live, and those two fields turn the whole
	-- question into a four-entry lookup that cannot drift out of step with the engine:
	--    LoadedMap +0x860  mapMatrixIndex   LandDataManager_GetLoadedMapMatrixIndex 0x021e9576
	--                                       (`movs r0,#0x86 ; lsls r0,#4 ; ldr r0,[r1,r0]`)
	--    LoadedMap +0x864  valid            LandDataManager_SetLoadedMapValid 0x021ea6ea, literal 0x864
	--    LoadedMap +0x000  the u16 grid     (the struct begins with it, land_data.c:49-58)
	-- and there are exactly FOUR, which is the game's own bound: GetLoadedMapMatrixIndex asserts
	-- `index < 4` at 0x021e9566, and the quadrant lookup rejects anything above 3 at 0x021e9602.
	-- ⚠ WHAT THIS REPLACES IS THE SLOT ARITHMETIC, NOT THE COORDINATE ARITHMETIC. The engine still
	-- normalises the tile first — `fixed = tile - LandDataManager.offsetTile`, then the cell from the
	-- MANAGER's own width — and so do we; what is gone is computing WHICH SLOT holds that cell, which
	-- the maps answer themselves. A cell that is not loaded matches no slot and answers UNKNOWN, which
	-- is the honest answer and the one the old code could not give.
	-- ⛔ THIS COMMENT SAID THE OPPOSITE UNTIL THE REVIEW CAUGHT IT (2026-09-05). It was written while
	-- the read genuinely did drop the origin and dimensions, and survived the commit that put them
	-- back — which is the exact trap of a load-bearing comment: it preserved the obsolete model that
	-- caused the bug, right next to the code that had already been fixed.
	-- B) WHOLE-MATRIX (sSimpleTerrainCollis) — GetSimpleTileAttributes at retail 0x02054ef4:
	--      ldr r0,[r6,#0x2c]      FieldSystem +0x2C  mapMatrix   (width u8 at +0, height u8 at +1,
	--                             from MapMatrix_GetWidth 0x02039e1a / GetHeight 0x02039e2a)
	--      ldr r1,[r6,#0x58]      FieldSystem +0x58  terrainAttributes
	--      bl 0x02054c0c          TerrainAttributes_Get: `ldrb r0,[r1,r0]` picks a BLOCK index out of
	--                             the byte array at +0x00, then `adds r2,#0xE2 ; lsls r0,#0xB` lands on
	--                             block*0x800 inside the u16 array at +0xE2.
	--    There are 225 matrix slots and 16 blocks (TERRAIN_ATTRIBUTES_MAP_MATRIX_COUNT /
	--    ..._MAX_BLOCK_COUNT), and this path has NO "not loaded" answer at all — it always says TRUE —
	--    so its bounds are ours to check.
	--
	-- ⛔⛔ THE ONE PLACE WE MUST NOT COPY THE ENGINE. When the fetch fails, `CheckCollision` returns
	-- FALSE — because the 0xFF it wrote has bit 15 clear — so the ENGINE TREATS AN UNLOADED TILE AS
	-- WALKABLE. That is harmless for the game, which never asks about a tile it has not loaded, and it
	-- is exactly the fail-OPEN that routed Ola up a 2.75-tile cliff in Gen V. So tile_walk answers
	-- THREE things and never two: true, false, or nil for "I cannot see this tile" — and the callers
	-- differ on what nil means, which is the point of keeping it.
	local FS_LAND, FS_MATRIX, FS_TATTR, FS_TCM = 0x28, 0x2C, 0x58, 0x5C
	-- +0x90 is the array of four LoadedMap pointers. +0x10C/+0x114 are offsetTileX/Z and +0xC0/+0xC4
	-- the matrix dimensions: the STREAMED read uses all four, exactly as GetTileAttributes does, and
	-- takes the width from HERE rather than from the MapMatrix object (the engine copies one to the
	-- other at init, so they always agree, but the streamed path asks the manager).
	local LDM_ATTRS, LDM_W, LDM_H, LDM_OFFX, LDM_OFFZ = 0x90, 0xC0, 0xC4, 0x10C, 0x114
	local TA_BLOCKS, TA_SLOTS, TA_MAX_BLOCKS = 0xE2, 225, 16
	local TILES, BLOCK_BYTES = 32, 0x800
	local ATTR_COLLIDE, ATTR_BEHAVIOR = 0x8000, 0xFF
	-- EXACTLY FOUR loaded maps, which is the game's own bound rather than an inference:
	-- LandDataManager_GetLoadedMapMatrixIndex asserts `index < 4` (0x021e9566) and the quadrant lookup
	-- rejects anything above 3 (0x021e9602).
	local LOADED_SLOTS = 4
	-- ⭐ INSIDE EACH LoadedMap, and every byte of this is arithmetic off the decompilation's own
	-- struct rather than a guess, because getting it wrong reads a live, plausible pointer and then
	-- silently finds no map — which is indistinguishable from the bug it fixes:
	--   terrainAttributes[TERRAIN_ATTRIBUTES_SIZE/2]  0x000  (TERRAIN_ATTRIBUTES_SIZE = 0x800, so the
	--                                                        u16 grid IS the start of the object)
	--   NNSG3dRenderObj mapRenderObj                 0x800  (0x54: 15 words to recMatAnm, then three
	--                                                        hint arrays of NNS_G3D_SIZE_*_MAX/32 = 2)
	--   mapModelFile / bdhcFile / bdhc               0x854 / 0x858 / 0x85C
	--   int mapMatrixIndex                           0x860  <- which square of the matrix this holds
	--   BOOL valid                                   0x864
	-- and LDM_ATTRS 0x90 falls out the same way: loadedMapBufs 0x00, two MapLazyLoaderManagers of 0x30
	-- from 0x04, MapLazyLoaderPending 0x1C at 0x64, four cancel BOOLs at 0x80, loadedMaps[4] at 0x90.
	-- ⚠ mapMatrixIndex is a plain `int` and INVALID_MAP_MATRIX_INDEX is -1 (constants/field/map.h), so
	-- it is read SIGNED — an emptied slot must read as -1, not as four billion, or the dump lies.
	local LM_CELL, LM_VALID = 0x860, 0x864

	-- The raw attribute halfword for a tile, or nil if it cannot be read.
	-- ⚠ NEGATIVE RELATIVE COORDINATES ARE REJECTED OUTRIGHT, and that is deliberately STRICTER than the
	-- engine. The compiler emitted C's truncating division (the `asrs #4 ; lsrs #27 ; adds ; asrs #5`
	-- at 0x021e9596), so a tile one column west of the window computes the SAME map index and then a
	-- negative remainder — reading the end of the previous row. The engine never asks, so it never
	-- notices; we would, and a wrong tile is worse than no tile. Rejecting negatives also means Lua's
	-- // and % agree with C's for everything we do read.
	-- One integer per tile, used as a table key by everything below. Packed so that a negative
	-- coordinate is still a distinct key rather than colliding with a positive one.
	local function tkey(x, z) return (x + 0x8000) * 0x10000 + (z + 0x8000) end

	local terrain = {}
	-- Victory Road 1F, the main room (the player, 2026-11-04): an entry the player can reach only by
	-- jumping down a ledge says so, the way an obstacle's move name does ("Item, Ledge, 3 north"),
	-- because there a ledge means walking the side rooms again. 2F and B1F have no place that only a
	-- ledge reaches from where the player arrives (research/re/pt-victory-road-20261104). The game
	-- has no word for a ledge, so this one is ours. By map header.
	terrain.ledge_word, terrain.ledge_maps = "Ledge", { [244] = true }
	local eterna = {}
	do
		function eterna.active(fs,cache)
			cache=cache or {}
			if cache.eterna_map==nil then cache.eterna_map=map_id(fs)==67 end
			return cache.eterna_map
		end
		local targets = {
			{id=2,script=5,x=14,z=22}, {id=3,script=6,x=20,z=17},
			{id=4,script=7,x=2,z=7}, {id=1,script=4,x=11,z=3}
		}
		local goal_stage = {[5]=0,[6]=1,[7]=2,[4]=3}
		local function bad(why) dbg("Eterna Gym: "..why); return nil end
		function eterna.snapshot(fs, cache)
			cache = cache or {}
			if cache.eterna_state ~= nil then return cache.eterna_state or nil end
			if not eterna.active(fs,cache) then return nil end
			cache.eterna_state = false
			if u32(fs+0xC) ~= u32(A.sSaveDataPtr) then return bad("save owner") end
			local misc = save_page(10,0x794,"Eterna Gym")
			if not misc or not inram(misc+0x723) then return bad("persisted feature span") end
			if u32(misc+0x700) ~= 8 then return bad("persisted feature type") end
			local state = u32(misc+0x704)
			if state > 4 then return bad("clock state") end
			if story_var(0x404B) ~= state then return bad("saved clock state mismatch") end
			local field = u32(fs+4)
			if not inram(field+0x27) then return bad("field manager") end
			local gym = u32(field+0x24)
			if not inram(gym+0x3F) or u32(gym+0x3C) ~= fs then return bad("clock system owner") end
			if u32(A.EternaGymCollision+0x74) ~= A.EternaGymClockCollision
				or u32(A.EternaGymCollision+0x78) ~= A.EternaGymFountainCollision
				or u32(A.EternaGymJump+0x4C) ~= A.EternaGymJumpTiles then return bad("clock overlay identity") end
			local j = A.EternaGymJumpTiles+state*8
			local x,z,axis = u16(j),u16(j+2),u32(j+4)
			if x==0xFFFF then x=-1 end; if z==0xFFFF then z=-1 end
			if state==0 then
				if x~=-1 or z~=-1 or axis~=2 then return bad("initial jump record") end
			elseif x<0 or x>31 or z<0 or z>31 or axis>1 then return bad("jump record") end
			cache.eterna_state = {state=state,fs=fs,gym=gym,jump={x,z,axis}}
			return cache.eterna_state
		end
		function eterna.blocked(snapshot,x,z)
			if not snapshot or snapshot.state > 4 then return nil end
			local function bit(base,index)
				local v=u8(base+index)
				if v>1 then return nil end
				return v==1
			end
			local state=snapshot.state
			if x>=5 and x<=17 and z>=7 and z<=19 then
				local v=bit(A.EternaGymClockCollision,state*169+(z-7)*13+x-5)
				if v==nil or v then return v end
			end
			if z==19 and x>=1 and x<=21 then return bit(A.EternaGymFountainCollision,state*21+x-1) end
			return false
		end
		-- A native forced jump is decided by the next tile, before normal ledges/collision.
		-- PlayerAvatar_WillJump checks this before ordinary tile behavior predicates.
		function eterna.jump(snapshot,x,z,dir)
			if not snapshot then return nil end
			local j=snapshot.jump
			if not j then return nil end
			local d=({[0]={0,-1},[1]={0,1},[2]={-1,0},[3]={1,0}})[dir]
			if not d then return nil end
			if x+d[1]==j[1] and z+d[2]==j[2] and
					((j[3]==1 and dir<2) or (j[3]==0 and dir>=2)) then
				return 2,x+2*d[1],z+2*d[2]
			end
			return nil
		end
		function eterna.waypoint(snapshot,goal_script)
			local required=goal_stage[goal_script]
			if not snapshot or not required then return nil end
			if snapshot.state < required then return targets[snapshot.state+1],true end
			return targets[required+1],false
		end

	end

	-- Resolve prerequisites through the same live actor list as ordinary navigation.
	function eterna.effective(fs, entry, cache)
		cache = cache or {}
		if not entry.actor or not eterna.active(fs,cache) then return entry end
		local script, id = u32(entry.actor+MO_SCRIPT), u32(entry.actor+MO_LOCALID)
		if entry.eterna_script and (entry.eterna_script ~= script or entry.eterna_id ~= id
			or entry.eterna_fs ~= fs or u32(entry.actor+MO_MAPID) ~= 67) then
			dbg("Eterna Gym: original target identity changed"); return nil
		end
		local expected = ({[4]=1,[5]=2,[6]=3,[7]=4})[script]
		if not expected or id ~= expected then return entry end
		cache = cache or {}
		local state = eterna.snapshot(fs,cache)
		if not state then return nil end
		if not cache.eterna_actors then cache.eterna_actors = build_live(fs).NPCs end
		local target, prerequisite = eterna.waypoint(state,script)
		local original, found
		for _, actor in ipairs(cache.eterna_actors) do
			local o = actor.actor
			if o and u32(o+MO_MAPID) == 67 and u32(o+0xB4) == u32(fs+FS_OBJMAN) then
				if o == entry.actor and u32(o+MO_SCRIPT) == script and u32(o+MO_LOCALID) == id then original = actor end
				if u32(o+MO_SCRIPT) == target.script and u32(o+MO_LOCALID) == target.id then
					if found then dbg("Eterna Gym: duplicate waypoint actor"); return nil end
					found = actor
				end
			end
		end
		if not original or not found then dbg("Eterna Gym: live target actor missing"); return nil end
		return found,state.state,prerequisite
	end


	-- A loaded map holds 32x32 attributes plus immutable BDHC collision geometry.
	-- The four slots rotate, and a new cell index is published BEFORE loading finishes.
	-- Snapshot their identity once per query; only valid slots can supply attributes.
	-- GetTileAttributes uses land-manager dimensions/tile offsets, while GetHeight
	-- uses matrix dimensions/fixed-point offsets. Keep those two coordinate systems.
	function terrain.map(fs, cache)
		if cache.map then return cache.map end
		local m = { fs = fs, tcm = u32(fs + FS_TCM), ld = u32(fs + FS_LAND),
			mm = u32(fs + FS_MATRIX), ta = u32(fs + FS_TATTR), attrs = {}, heights = {} }
		cache.map = m
		if inram(m.mm) and inram(m.mm + 5) then
			m.mw, m.mh, m.mid = u8(m.mm), u8(m.mm + 1), u8(m.mm + 2)
			m.dh, m.dw = u8(m.mm + 4), u8(m.mm + 5)
		end
		if m.tcm == A.sTerrainCollision and inram(m.ld) and inram(m.ld + 0x123) then
			m.lw, m.lh = s32(m.ld + LDM_W), s32(m.ld + LDM_H)
			m.tx, m.tz = s32(m.ld + LDM_OFFX), s32(m.ld + LDM_OFFZ)
			m.ox, m.oy, m.oz = s32(m.ld + 0x118), s32(m.ld + 0x11C), s32(m.ld + 0x120)
			m.slots = {}
			for i = 0, LOADED_SLOTS - 1 do
				local lm = u32(m.ld + LDM_ATTRS + i * 4)
				local slot = { lm }
				m.slots[#m.slots + 1] = slot
				if inram(lm) and inram(lm + LM_VALID + 3) then
					local valid, cell = u32(lm + LM_VALID), s32(lm + LM_CELL)
					slot[2], slot[3] = valid, cell
					if valid ~= 0 and not m.attrs[cell] then m.attrs[cell] = lm end
					if valid == 1 then
						if m.heights[cell] ~= nil then m.heights[cell] = false
						else m.heights[cell] = lm end
					end
				end
			end
		elseif m.tcm == A.sSimpleTerrainCollis and m.mw and m.mw * m.mh <= TA_SLOTS
			and inram(m.ta) and inram(m.ta + TA_SLOTS - 1) then
			m.blocks = {}
			for cell = 0, m.mw * m.mh - 1 do m.blocks[cell] = u8(m.ta + cell) end
		end
		return m
	end

	-- A missing streamed cell inside a valid matrix is different from bad
	-- geometry or the edge of the world. Only this case permits a partial route.
	function terrain.unloaded(fs, x, z, cache)
		local m = terrain.map(fs, cache)
		if m.tcm ~= A.sTerrainCollision or not m.lw or not m.mw
			or m.lw ~= m.mw or m.lh ~= m.mh or m.lw < 1 or m.lh < 1 then return false end
		local fx, fz = x - m.tx, z - m.tz
		if fx < 0 or fz < 0 or fx >= m.lw * TILES or fz >= m.lh * TILES then return false end
		return m.attrs[fx // TILES + (fz // TILES) * m.lw] == nil
	end

	function terrain.loading(fs)
		local ld = u32(fs + FS_LAND)
		if u32(fs + FS_TCM) ~= A.sTerrainCollision then return nil, "streaming collision manager changed" end
		if not inram(ld) or not inram(ld + 0xA0) then return nil, "lazy loader owner unreadable" end
		-- LandDataManager_Tick decrements +A0 only after the loader finishes.
		-- Waiting at a partial endpoint needs this one counter, not another flood.
		local count = u8(ld + 0xA0)
		if count > 2 then return nil, "lazy loader count invalid" end
		return count > 0
	end

	local function tile_attrs_raw(fs, x, z, cache)
		local m = terrain.map(fs, cache or {})
		if m.tcm == A.sTerrainCollision then
			if not m.lw then return nil end
			local fx, fz = x - m.tx, z - m.tz
			-- Reject negative relative coordinates: C's truncating division would
			-- otherwise address the wrong row. Unknown terrain must stay unknown.
			if fx < 0 or fz < 0 or m.lw < 1 or m.lh < 1 or fx >= m.lw * TILES or fz >= m.lh * TILES then return nil end
			local lm = m.attrs[(fx // TILES) + (fz // TILES) * m.lw]
			if lm then return u16(lm + ((fz % TILES) * TILES + (fx % TILES)) * 2) end
		elseif m.blocks then
			if x < 0 or z < 0 or m.mw < 1 or m.mh < 1 or x >= m.mw * TILES or z >= m.mh * TILES then return nil end
			local blk = m.blocks[(x // TILES) + (z // TILES) * m.mw]
			if not blk or blk >= TA_MAX_BLOCKS then return nil end
			local at = m.ta + TA_BLOCKS + blk * BLOCK_BYTES + ((z % TILES) * TILES + (x % TILES)) * 2
			if inram(at + 1) then return u16(at) end
		end
		if cache and cache.hm_offline then return terrain.rom_attrs(fs,x,z,cache) end
		return nil
	end

	-- Geometry is reused only while its native owners and loading state still match.
	-- No cache argument requests an independent snapshot (diagnostics and tests).
	local function tile_attrs(fs, x, z, cache)
		cache = cache or {}
		local ck = tkey(x, z)
		local hit = cache[ck]
		if hit ~= nil then return hit or nil end
		local a = tile_attrs_raw(fs, x, z, cache)
		if a and eterna.active(fs,cache) then
			local state = eterna.snapshot(fs,cache)
			if not state then return nil end
			local blocked = eterna.blocked(state,x,z)
			if blocked == nil then return nil end
			if blocked then a = a | ATTR_COLLIDE end
		end
		cache[ck] = a or false
		return a
	end

	-- true = you can stand here, false = solid, nil = not loaded / unreadable. See the block above for
	-- why the third answer exists and why it must never be folded into either of the other two.
	local function tile_walk(fs, x, z, cache)
		local a = tile_attrs(fs, x, z, cache)
		if not a then return nil end
		return (a & ATTR_COLLIDE) == 0
	end

	-- The tile's behavior byte (ledges, water, ice, doors, ...), or nil.
	local function tile_behavior(fs, x, z, cache)
		local a = tile_attrs(fs, x, z, cache)
		return a and (a & ATTR_BEHAVIOR) or nil
	end

	-- Collision height, sampled at tile centres just like GetVerticalDirection (02054FD0).
	-- GetHeight (02054D0C) -> FS+28 -> land+90+4*slot -> LoadedMap+85C -> BDHC.
	-- CalculateObjectHeight (021EED9C) chooses the nearest of the strip's containing planes;
	-- an overlapping bridge and the ground below it are different search states.
	-- Retail traces and buffer bounds: research/re/takeover-20260915/pt-terrain-chain.txt.
	-- Geometry is queried only for navigation or replanning, never on idle frames.

	function terrain.fail(cache, reason)
		cache.height_errors = cache.height_errors or {}
		if not cache.height_errors[reason] then
			cache.height_errors[reason] = true
			dbg("ow height: " .. reason)
		end
		return nil
	end

	function terrain.player_object(fs, cache)
		local pa = u32(fs + FS_AVATAR)
		if not (inram(pa) and inram(pa + PA_OBJ + 3)) then
			return terrain.fail(cache, "playerAvatar unreadable")
		end
		local mo = u32(pa + PA_OBJ)
		if not (inram(mo) and inram(mo + MO_STRIDE - 1)) or (u32(mo) & MO_INUSE) == 0 then
			return terrain.fail(cache, "player mapObject invalid")
		end
		return mo
	end

	function terrain.seed(fs, x, z, cache)
		-- A platform lift's landing (terrain.panel_search): the ride ends with the player on the
		-- plate at its new height (FieldTask_PlatformLiftGoUp/GoDown: Player_SetYPos to the plate).
		local ride = cache.ride
		if ride and ride.x == x and ride.z == z then
			local p = terrain.profile(fs, x, z, cache)
			return p and p.dynamic and p.dynamic + p.offset or nil
		end
		local mo = terrain.player_object(fs, cache)
		if not mo then return nil end
		-- MapObject_GetPosPtr 02063050 copies +70/+74/+78; this is the Y the collision
		-- consumer uses. Resolve the centre of the committed tile when already mid-step.
		return terrain.height(fs, x, z, s32(mo + 0x74), cache)
	end

	function terrain.dynamic(fs, cache)
		if cache.height_dynamic ~= nil then return cache.height_dynamic or nil end
		cache.height_dynamic = false
		local dm = u32(fs + 0xA0)
		if not (inram(dm) and inram(dm + 7)) then return terrain.fail(cache, "dynamic manager unreadable") end
		local n, arr = s32(dm), u32(dm + 4)
		-- FieldSystem_InitLandManager creates eight plates; the reader of +10 height and
		-- +14 valid is DynamicTerrainHeightManager_GetHeight, 021EF35C, stride 18.
		if n ~= 8 then return terrain.fail(cache, "dynamic plate count invalid") end
		if not (inram(arr) and inram(arr + n * 0x18 - 1)) then
			return terrain.fail(cache, "dynamic plate array unreadable")
		end
		local plates = {}
		for i = 0, n - 1 do
			local p = arr + i * 0x18
			if u32(p + 0x14) ~= 0 then
				local sx, sz = s32(p + 8), s32(p + 0xC)
				if sx <= 0 or sz <= 0 then return terrain.fail(cache, "dynamic plate extent invalid") end
				plates[#plates + 1] = { s32(p), s32(p + 4), sx, sz, s32(p + 0x10) }
			end
		end
		cache.height_dynamic = plates
		return plates
	end

	function terrain.bdhc(lm, cache)
		cache.height_bdhc = cache.height_bdhc or {}
		local hit = cache.height_bdhc[lm]
		if hit ~= nil then return hit or terrain.fail(cache, "BDHC unavailable") end
		cache.height_bdhc[lm] = false
		local b, buf = u32(lm + 0x85C), u32(lm + 0x858)
		if not (inram(b) and inram(b + 0x1F)) then return terrain.fail(cache, "BDHC unreadable") end
		if u32(b + 0x18) ~= 1 then return terrain.fail(cache, "BDHC still loading") end
		if not (inram(buf) and inram(buf + 0x9000 - 1)) then return terrain.fail(cache, "BDHC buffer unreadable") end
		local p = { u32(b + 0x10), u32(b + 0x14), u32(b + 4), u32(b), u32(b + 8), u32(b + 0xC) }
		local strides, counts = { 8, 12, 4, 8, 8 }, {}
		if p[1] ~= buf then return terrain.fail(cache, "BDHC points outside buffer") end
		for i = 1, 5 do
			local len = p[i + 1] - p[i]
			if len < 0 or len % strides[i] ~= 0 or p[i + 1] > buf + 0x9000 then
				return terrain.fail(cache, "BDHC section layout invalid")
			end
			counts[i] = len // strides[i]
		end
		if counts[5] ~= s32(b + 0x1C) or counts[5] < 1 then
			return terrain.fail(cache, "BDHC strip count invalid")
		end
		local out = { p = p, n = counts, finish = buf + 0x9000, scanlines = {}, strips = {}, plates = {} }
		cache.height_bdhc[lm] = out
		return out
	end

	function terrain.planes(b, x, z, cache)
		local p, n = b.p, b.n
		local u16,s32 = b.u16 or u16,b.s32 or s32
		-- BDHC_FindStripIndexByScanline 021EED38: first scanline strictly above Z.
		local idx = 0
		if n[5] > 1 then
			local lo, hi = 0, n[5] - 1
			while true do
				local mid = (lo + hi) // 2
				local scanline = b.scanlines[mid]
				if scanline == nil then scanline = s32(p[5] + mid * 8); b.scanlines[mid] = scanline end
				if scanline > z then
					if hi - 1 > lo then hi = mid else idx = mid; break end
				else
					if lo + 1 < hi then lo = mid else idx = mid + 1; break end
				end
			end
		end
		-- ⛔ ONE PAST THE LAST STRIP IS A REAL ANSWER IN THE DISTORTION WORLD. The search above returns
		-- mid + 1 = stripsCount for a z beyond the last scanline (BDHC_FindStripIndexByScanline), and
		-- CalculateObjectHeight then reads strips[stripsCount]: the first 8 bytes of the access list,
		-- which BDHC_PrepareBuffers places right after the strips. 1F's slab corner is such a cell
		-- (land 600). Read where the game reads, there only; the bounds and plate checks below still
		-- fail closed on anything outside the buffer or not a plate.
		if idx > n[5] or (idx == n[5] and not (cache.dw_ground and p[5] + idx * 8 + 8 <= b.finish)) then
			return terrain.fail(cache, "BDHC strip index invalid")
		end
		local entries = b.strips[idx]
		if not entries then
			local strip = p[5] + idx * 8
			local count, start = u16(strip + 4), u16(strip + 6)
			if p[6] + (start + count) * 2 > b.finish then return terrain.fail(cache, "BDHC access list overflow") end
			entries = {}
			for i = 0, count - 1 do entries[#entries + 1] = u16(p[6] + (start + i) * 2) end
			b.strips[idx] = entries
		end
		local heights = {}
		for _, plate in ipairs(entries) do
			if plate >= n[4] then return terrain.fail(cache, "BDHC plate index invalid") end
			local bounds = b.plates[plate]
			if not bounds then
				local a = p[4] + plate * 8
				local first, second, normal, constant = u16(a), u16(a + 2), u16(a + 4), u16(a + 6)
				if first >= n[1] or second >= n[1] or normal >= n[2] or constant >= n[3] then
					return terrain.fail(cache, "BDHC plane indices invalid")
				end
				local x1, z1 = s32(p[1] + first * 8), s32(p[1] + first * 8 + 4)
				local x2, z2 = s32(p[1] + second * 8), s32(p[1] + second * 8 + 4)
				bounds = { math.min(x1, x2), math.max(x1, x2), math.min(z1, z2), math.max(z1, z2),
					normal = p[2] + normal * 12, constant = p[3] + constant * 4 }
				b.plates[plate] = bounds
			end
			if x >= bounds[1] and x <= bounds[2] and z >= bounds[3] and z <= bounds[4] then
				if not bounds.plane then
					local np = bounds.normal
					bounds.plane = { s32(np), s32(np + 4), s32(np + 8), s32(bounds.constant) }
				end
				local nx, ny, nz = bounds.plane[1], bounds.plane[2], bounds.plane[3]
				if ny == 0 then return terrain.fail(cache, "BDHC vertical plane") end
				local val = -((nx * x + 0x800) // 0x1000 + (nz * z + 0x800) // 0x1000
					+ bounds.plane[4])
				if val < -0x7FFFFFFF or val > 0x7FFFFFFF then return terrain.fail(cache, "BDHC height overflow") end
				-- FX_DivAsync uses (signed numerator << 32) / denominator, truncating
				-- toward zero. FX_GetDivResult adds 80000 before shifting down 20.
				local q = (math.abs(val) * 0x100000000) // math.abs(ny)
				if (val < 0) ~= (ny < 0) then q = -q end
				local y = (q + 0x80000) // 0x100000
				if y < -0x80000000 or y > 0x7FFFFFFF then return terrain.fail(cache, "BDHC result overflow") end
				heights[#heights + 1] = y
				if #heights == 10 then break end             -- game's candidate limit and tie order
			end
		end
		return heights
	end

	-- `sdx, sdz`: an fx32 offset from the tile centre, within the tile (the ice slope test samples a
	-- quarter tile ahead); such a sample is cached as its own entry.
	function terrain.profile(fs, x, z, cache, sdx, sdz)
		cache.height_tiles = cache.height_tiles or {}
		local key = tkey(x, z)
		if sdx then key = key .. ":" .. sdx .. ":" .. sdz end
		local hit = cache.height_tiles[key]
		if hit ~= nil then return hit or terrain.fail(cache, "height profile unavailable") end
		cache.height_tiles[key] = false
		local m = terrain.map(fs, cache)
		local tcm = m.tcm
		if tcm == A.sSimpleTerrainCollis then
			if tile_attrs(fs, x, z, cache) == nil then return terrain.fail(cache, "simple terrain unavailable") end
			-- GetSimpleHeight ALWAYS returns zero, even when its source tag is NONE.
			-- The caller still uses the whole-matrix attributes for collision in that case.
			local out = { heights = { 0 }, offset = 0 }
			cache.height_tiles[key] = out
			return out
		end
		if tcm ~= A.sTerrainCollision then return terrain.fail(cache, "unknown collision manager") end
		if not m.lw then return terrain.fail(cache, "land manager unreadable") end
		if not m.mw then return terrain.fail(cache, "map matrix unreadable") end
		local ox, oy, oz = m.ox, m.oy, m.oz
		local fx, fz = x * 0x10000 + 0x8000 + (sdx or 0) - ox, z * 0x10000 + 0x8000 + (sdz or 0) - oz
		local mw, mh = m.mw, m.mh
		if fx < 0 or fz < 0 or fx >= mw * 0x200000 or fz >= mh * 0x200000 then
			return terrain.fail(cache, "tile outside height matrix")
		end
		local tx, tz = fx // 0x10000, fz // 0x10000
		local cell = (tx // TILES) + (tz // TILES) * mw
		local lm = m.heights[cell]
		if lm == false then return terrain.fail(cache, "duplicate loaded height cell") end
		if not lm and not cache.hm_offline then return terrain.fail(cache, "height cell not loaded") end
		local b
		if lm then b = terrain.bdhc(lm,cache)
		elseif cache.hm_offline then b = terrain.rom_bdhc(fs,cell,cache) end
		if not b then return nil end
		local heights = terrain.planes(b, fx - ((tx // TILES) * TILES + 16) * 0x10000,
			fz - ((tz // TILES) * TILES + 16) * 0x10000, cache)
		if not heights then return nil end
		local plates = terrain.dynamic(fs, cache)
		if not plates then return nil end
		local dyn
		for _, p in ipairs(plates) do
			if tx >= p[1] and tx < p[1] + p[3] and tz >= p[2] and tz < p[2] + p[4] then dyn = p[5]; break end
		end
		local out = { heights = heights, dynamic = dyn, offset = oy }
		cache.height_tiles[key] = out
		return out
	end

	function terrain.height(fs, x, z, previous, cache, sdx, sdz)
		local p = terrain.profile(fs, x, z, cache, sdx, sdz)
		if not p or previous == nil then return nil end
		local old, best, diff = previous - p.offset, nil, math.huge
		for _, y in ipairs(p.heights) do
			local d = math.abs(y - old)
			if d < diff then best, diff = y, d end
		end
		local dyn = p.dynamic
		if dyn and (not best or (dyn > best and math.abs(dyn - old) < diff)) then
			return dyn + p.offset, 2
		end
		if best then return best + p.offset, 1 end
		-- ⛔ NO PLATE IS NOT NO GROUND IN THE DISTORTION WORLD, where most walkable tiles have none
		-- (1F's four cells hold 14 plates between them). GetHeight answers the land offset with source
		-- NONE; GetVerticalDirection lets the step through when that is less than 20 * FX32_ONE
		-- (0x14000, a tile and a quarter) from the player; MapObject_RecalculatePositionHeightEx then refuses a NONE height, so
		-- pos.y stays where it was. Only the Distortion World's searches ask (cache.dw_ground); the rest
		-- of the game keeps treating a plate-less tile as unknown.
		if cache.dw_ground and math.abs(p.offset - previous) < 0x14000 then return previous, 0 end
		return terrain.fail(cache, "no surface at tile")
	end

	-- ── PASTORIA GYM: three water levels and ten floor buttons ──────────────────────────────────
	-- src/overlay008/gym_features.c and the gym's scripts/events; ov8, the land data, events and
	-- scripts are byte-identical in the follower patch (research/re/pt-pastoria-gym-20261031).
	-- Stepping onto a button is a coord event (sub_0203CC14: tile match and var == value), whose script
	-- calls PastoriaGym_PressButton: the water prop moves, and only when it stops does
	-- DynamicTerrainHeightManager_SetHeight move plate 0 (tiles 1..25 x 2..39) to the new level.
	-- The scripts keep VAR_MAP_LOCAL_1/2/3 one-hot for the level last chosen, so the button of the
	-- current level is disarmed and every other button fires.
	-- Two native rules make a level matter. Heights: GetHeight prefers the water plate over a lower
	-- BDHC floor when it is closer to the player's height, and a plate surface over behavior 0x59
	-- collides; terrain.height and step_ok already model both. Gates: behaviors 0x56/0x57/0x58 collide
	-- unless the player's CURRENT height equals one exact water height (pastoria.rules).
	-- Persisted feature 1 (PersistedMapFeatures_InitForPastoriaGym 02071B10); pressedButton u8 at
	-- Misc+0x704: 0 low (orange model), 1 middle (green), 2 high (blue).
	local pastoria = {}
	do
		local function bad(why, detail)
			if pastoria.error ~= why then dbg("Pastoria Gym: "..why..(detail and (" ("..detail..")") or "")) end
			pastoria.error = why
			return nil, why
		end
		function pastoria.active(fs, cache)
			cache = cache or {}
			if cache.pastoria_map == nil then cache.pastoria_map = map_id(fs) == 122 end
			return cache.pastoria_map
		end
		-- ⛔ THE GATE RULE IS READ FROM THE GAME'S OWN CODE. PastoriaGym_DynamicMapFeaturesCheckCollision
		-- (02249A40) calls three behavior predicates and compares the player's height (r5) with a
		-- constant after each: `cmp r5,#0`, then `movs r0,#2 ; lsls #16 ; cmp r5,r0`, then
		-- `movs r0,#1 ; lsls #18 ; cmp r5,r0`. Each predicate (0205DBFC/08/14) is
		-- `cmp r0,#behavior ; bne ; movs r0,#1 ; bx lr`. Decoding both sides ties every behavior to its
		-- height inside the identity-checked overlay; any other shape fails closed.
		-- Returns { [behavior] = height } plus level = { [0] = low, [1] = middle, [2] = high }: the same
		-- three constants are the water heights PastoriaGym_DynamicMapFeaturesInit and the press tasks set.
		function pastoria.rules(cache)
			cache = cache or {}
			if cache.pastoria_rules then return cache.pastoria_rules end
			local f = A.PastoriaGymCheckCollision
			-- `push {r4-r6,lr} ; adds r5,r3,#0`: r5 is the height argument the compares below test.
			if u16(f) ~= 0xB570 or u16(f + 2) ~= 0x1C1D then
				return bad("collision code identity", string.format("%04X %04X", u16(f), u16(f + 2)))
			end
			local function predicate(at)
				local t = bl_target(at)
				if not t or u16(t) >> 8 ~= 0x28 or u16(t + 2) ~= 0xD101 or u16(t + 4) ~= 0x2001 or u16(t + 6) ~= 0x4770 then
					return nil
				end
				return u16(t) & 0xFF
			end
			local function shifted(at)
				local mov, lsl, cmp = u16(at), u16(at + 2), u16(at + 4)
				if mov >> 8 ~= 0x20 or lsl & 0xF83F ~= 0 or cmp ~= 0x4285 then return nil end
				return (mov & 0xFF) << ((lsl >> 6) & 0x1F)
			end
			local b1, b2, b3 = predicate(f + 0x0C), predicate(f + 0x20), predicate(f + 0x38)
			local h1 = u16(f + 0x14) >> 8 == 0x2D and (u16(f + 0x14) & 0xFF) or nil
			local h2, h3 = shifted(f + 0x28), shifted(f + 0x40)
			if not (b1 and b2 and b3 and h1 and h2 and h3) or b1 == b2 or b2 == b3 or b1 == b3
				or not (h1 < h2 and h2 < h3) then
				return bad("collision rule shape")
			end
			local out = { [b1] = h1, [b2] = h2, [b3] = h3, level = { [0] = h1, [1] = h2, [2] = h3 } }
			cache.pastoria_rules = out
			return out
		end
		-- VAR_MAP_LOCAL_1/2/3 = 0x4001..0x4003 -> the level that button's press stores. Each var's
		-- script presses the button prop under the player, and every prop sits on its event's tile:
		-- blue (model 239) var 1, green (240) var 2, orange (241) var 3 — checked on both cartridges.
		local BUTTON_LEVEL = { [0x4001] = 2, [0x4002] = 1, [0x4003] = 0 }
		local LEVEL_VAR = { [0] = 0x4003, [1] = 0x4002, [2] = 0x4001 }
		local PLATE = { 1, 2, 25, 38 }       -- DynamicTerrainHeightManager_SetPlate(0, 1, 2, 25, 38, ...)
		-- The validated live puzzle, or nil and a reason. "water moving" means the press has not
		-- finished: the persisted level is already the new one, the plate is not.
		function pastoria.snapshot(fs, cache)
			cache = cache or {}
			if not pastoria.active(fs, cache) then return nil, "inactive" end
			if u32(fs + 0xC) ~= u32(A.sSaveDataPtr) then return bad("save owner") end
			local misc = save_page(10, 0x794, "Pastoria Gym")
			if not misc or not inram(misc + 0x704) then return bad("persisted feature span") end
			if u32(misc + 0x700) ~= 1 then return bad("persisted feature type", tostring(u32(misc + 0x700))) end
			local level = u8(misc + 0x704)
			if level > 2 then return bad("pressed button", tostring(level)) end
			local rules = pastoria.rules(cache)
			if not rules then return nil, "rules" end
			local plates = terrain.dynamic(fs, cache)
			if not plates then return bad("water plate unreadable") end
			local plate
			for i, p in ipairs(plates) do
				if p[1] == PLATE[1] and p[2] == PLATE[2] and p[3] == PLATE[3] and p[4] == PLATE[4] then plate = i end
			end
			if not plate or #plates ~= 1 then return bad("water plate extent", tostring(#plates)) end
			if plates[plate][5] ~= rules.level[level] then
				if pastoria.error ~= "water moving" then dbg("Pastoria Gym: water moving") end
				pastoria.error = "water moving"
				return nil, "water moving"
			end
			for l = 0, 2 do
				local v = story_var(LEVEL_VAR[l])
				if v ~= (l == level and 1 or 0) then return bad("button vars", "level "..level.." var "..LEVEL_VAR[l].."="..tostring(v)) end
			end
			-- Buttons are the live coord events (MapHeaderData +0C count, +1C list, stride 0x10:
			-- script, x, z, width, length, y, value, var). Any other trigger would run a script the plan
			-- cannot model, so it refuses rather than walk over it.
			local mhd = u32(fs + 0x14)
			if not inram(mhd) then return bad("map header data") end
			local n, p = u32(mhd + 0x0C), u32(mhd + 0x1C)
			if n == 0 or n > 64 or not inram(p) or p < mhd + 0x20 or p + n * 0x10 > mhd + 0x820 then
				return bad("coord event list", tostring(n))
			end
			local buttons, at = {}, {}
			for i = 0, n - 1 do
				local e = p + i * 0x10
				local var, value = u16(e + 0x0E), u16(e + 0x0C)
				local x, z = u16(e + 2), u16(e + 4)
				local b = BUTTON_LEVEL[var]
				-- Script 2/3/4 is the press for var 1/2/3 (scripts_pastoria_city_gym.s).
				if not b or value ~= 0 or u16(e) ~= 2 + var - 0x4001 or u16(e + 6) ~= 1 or u16(e + 8) ~= 1 then
					return bad("unknown coord event", string.format("%d,%d var %04X", x, z, var))
				end
				local key = tkey(x, z)
				if at[key] then return bad("duplicate button", x..","..z) end
				local button = { x = x, z = z, level = b, key = key }
				buttons[#buttons + 1], at[key] = button, button
			end
			pastoria.error = nil
			return { fs = fs, level = level, rules = rules, plates = plates, plate = plate,
				buttons = buttons, at = at, sig = level }
		end
		-- Occupancy plus every armed button: a route at the current level must not step on one.
		function pastoria.blocked(snap, occ, except)
			local out = {}
			for k in pairs(occ) do out[k] = true end
			for _, b in ipairs(snap.buttons) do
				if b.level ~= snap.level and b.key ~= except then out[b.key] = true end
			end
			return out
		end
		-- A terrain cache in which the water plate stands at `level`.
		-- ⛔ THE GYM IS TWO LAND CELLS AND ONLY THE NEAR ONE MAY BE LOADED. LandData loads by the
		-- player's quadrant: north of z 16 the southern cell (z 32..63) is not loaded at all, and a
		-- search that treats it as a wall reported "Can't reach" in game (2026-11-01). So the cells
		-- that are not loaded come from the running cartridge (hm_offline: rom_attrs/rom_bdhc), the
		-- same static land file the game loads, and the loaded ones stay live. The water plate, the
		-- one moving part, is modelled here and the gate rule in step_ok, so no dynamic feature is
		-- substituted by the cartridge.
		function pastoria.level_cache(snap, level, motion)
			local plates = {}
			for i, p in ipairs(snap.plates) do
				plates[i] = { p[1], p[2], p[3], p[4], i == snap.plate and snap.rules.level[level] or p[5] }
			end
			return { height_dynamic = plates, motion = motion, pastoria_map = true, hm_offline = true,
				pastoria_rules = snap.rules, eterna_map = false }
		end
	end

	-- ── SUNYSHORE GYM: three rooms of gears that turn together ─────────────────────────────────
	-- src/overlay008/gym_features.c (Sunyshore section) and the three rooms' scripts and events;
	-- research/re/report-20261104-platinum-sunyshore-gym.md. Map headers 154/155/156 are rooms 0/1/2.
	-- Each gear's arms are two-tile walkways; one rotation state (0..3) turns every gear in the room.
	--  * Walking: SunyshoreGym_DynamicMapFeaturesCheckCollision (ov8 0224ACC0), which
	--    TerrainCollisionManager_WillPlayerCollide asks BEFORE the land collision, collides on every
	--    tile inside a region listed for the current state: sSunyshoreCollisionLists[room] =
	--    { s32 numRegions, u8 *lists[4] } (stride 0x14), sSunyshoreCollisionRegions[room] -> regions of
	--    { u8 x, z, sizeX, sizeZ }. Anywhere else the land collision applies as usual. Room and state are
	--    the live gym system's (FieldSystem +4 -> +0x24: +0x11 roomID, +0x13 rotationState); the
	--    persisted copy (feature 5 at Misc +0x700; +0x704 state, +0x708 room) is written with it.
	--  * Pressing: the buttons are 1x1 coord events on gear centres, var 0x4000 value 0. The rooms keep
	--    that var 0, so EVERY button is armed, the one underfoot included: pressing it again is a step
	--    off and back on. Each script calls SunyshoreGym_PressButton (0224AD34) with its button type,
	--    which turns the state +1, -1 or +2 (mod 4) at once; the gears then turn in a field task
	--    inside the script, so the player has control again only when they have stopped.
	--  * Entering a room resets it (PersistedMapFeatures_InitForSunyshoreGym 02071B6C).
	-- ov8's Sunyshore code and tables and the rooms' headers, land data, events and scripts are
	-- byte-identical in the follower patch (research/re/pt-sunyshore-gym-20261104).
	terrain.sunyshore = {}
	do
		local suny = terrain.sunyshore
		local ROOM = { [154] = 0, [155] = 1, [156] = 2 }
		-- Coord-event script -> button type: scripts_sunyshore_city_gym_room_1/2/3.s, each script one
		-- PressSunyshoreGymButton (room 1: 2 normal; room 2: 2 normal, 3 reverse; room 3: 2 normal,
		-- 3 double). Checked against both cartridges by the harness.
		local SCRIPT_TYPE = { [0] = { [2] = 0 }, [1] = { [2] = 0, [3] = 1 }, [2] = { [2] = 0, [3] = 2 } }
		local function bad(why, detail)
			if suny.error ~= why then dbg("Sunyshore Gym: "..why..(detail and (" ("..detail..")") or "")) end
			suny.error = why
			return nil, why
		end
		function suny.active(fs, cache)
			cache = cache or {}
			if cache.sunyshore_room == nil then cache.sunyshore_room = ROOM[map_id(fs)] or false end
			return cache.sunyshore_room ~= false
		end
		-- ⛔ THE TURN OF EACH BUTTON TYPE IS READ FROM SunyshoreGym_PressButton: `cmp r5,#0` then
		-- `adds r0,r0,#1`; `cmp r5,#1` then `subs r0,r0,#1` (below 0 -> `movs r0,#3`); `cmp r5,#2` then
		-- `adds r0,r0,#2`. Any other shape fails closed.
		local function turns()
			local f = A.SunyshoreGymPressButton
			if u16(f) ~= 0xB5F8 or u16(f + 0x3E) ~= 0x2D00 or u16(f + 0x5C) ~= 0x2D01 or u16(f + 0x72) ~= 0x2D02
				or u16(f + 0x6E) ~= 0x2003 then
				return nil
			end
			local a, s, d = u16(f + 0x46), u16(f + 0x62), u16(f + 0x7A)
			if a & 0xFE3F ~= 0x1C00 or s & 0xFE3F ~= 0x1E00 or d & 0xFE3F ~= 0x1C00 then return nil end
			return { [0] = ((a >> 6) & 7) % 4, [1] = (4 - ((s >> 6) & 7)) % 4, [2] = ((d >> 6) & 7) % 4 }
		end
		-- The room's tables, read out of the loaded overlay through the code that consumes them:
		-- { turn = { [type] = quarter turns }, shut = { [state] = { [tile key] = true } } }.
		function suny.data(room)
			local f = A.SunyshoreGymCheckCollision
			-- push {r4-r7}; ldr r0,[r0,#4]; ldr r2,[r0,#0x24]; movs r4,#0x14 (list stride);
			-- ldrb r0,[r2,#0x11] (room); ldrb r2,[r2,#0x13] (state); the three pool loads; ldrb r2,[r7,r0]
			-- (the region's x, the first byte the game compares).
			if u16(f) ~= 0xB4F0 or u16(f + 2) ~= 0x6840 or u16(f + 8) ~= 0x6A42 or u16(f + 0x0A) ~= 0x2414
				or u16(f + 0x0C) ~= 0x7C50 or u16(f + 0x0E) ~= 0x7CD2 or u16(f + 0x14) ~= 0x4C14
				or u16(f + 0x1A) ~= 0x4C14 or u16(f + 0x26) ~= 0x4812 or u16(f + 0x34) ~= 0x5C3A then
				return bad("collision code identity", string.format("%04X", u16(f)))
			end
			local lists, regions = u32(f + 0x68), u32(f + 0x70)
			if u32(f + 0x6C) ~= lists + 4 then return bad("collision literal") end
			local saved = suny.saved_data
			if not (saved and saved.lists == lists and saved.regions == regions) then
				saved = { lists = lists, regions = regions }
				suny.saved_data = saved
			end
			if saved[room] then return saved[room] end
			local turn = turns()
			if not turn then return bad("press code identity") end
			local e = lists + room * 0x14
			if not inram(e) or not inram(e + 0x13) or not inram(regions + room * 4 + 3) then return bad("tables unreadable") end
			local n, rp = s32(e), u32(regions + room * 4)
			if n < 1 or n > 64 then return bad("region count", tostring(n)) end
			local out = { turn = turn, shut = {} }
			for s = 0, 3 do
				local lp, shut = u32(e + 4 + s * 4), {}
				if not inram(lp) or not inram(lp + n - 1) then return bad("region list", tostring(s)) end
				for i = 0, n - 1 do
					local r = rp + u8(lp + i) * 4
					if not inram(r) or not inram(r + 3) then return bad("region", tostring(u8(lp + i))) end
					local x, z, w, l = u8(r), u8(r + 1), u8(r + 2), u8(r + 3)
					if w < 1 or l < 1 or x + w > 32 or z + l > 32 then return bad("region extent", tostring(u8(lp + i))) end
					for dx = 0, w - 1 do for dz = 0, l - 1 do shut[tkey(x + dx, z + dz)] = true end end
				end
				out.shut[s] = shut
			end
			saved[room] = out
			return out
		end
		-- The validated live puzzle, or nil and a reason:
		-- { room, state, data, buttons = { { x, z, key, turn } }, at = { [tile key] = button }, sig }.
		function suny.snapshot(fs, cache)
			cache = cache or {}
			if not suny.active(fs, cache) then return nil, "inactive" end
			local room = cache.sunyshore_room
			if u32(fs + 0xC) ~= u32(A.sSaveDataPtr) then return bad("save owner") end
			local misc = save_page(10, 0x794, "Sunyshore Gym")
			if not misc or not inram(misc + 0x70B) then return bad("persisted feature span") end
			if u32(misc + 0x700) ~= 5 then return bad("persisted feature type", tostring(u32(misc + 0x700))) end
			local state = u32(misc + 0x704)
			if state > 3 or u32(misc + 0x708) ~= room then
				return bad("persisted state", string.format("state %d room %d", state, u32(misc + 0x708)))
			end
			-- The copy the collision function reads (there is no back-pointer to check: Init never
			-- writes SunyshoreGymSystem.fieldSystem). It must agree with the save.
			local field = u32(fs + 4)
			if not inram(field) or not inram(field + 0x27) then return bad("field manager") end
			local gym = u32(field + 0x24)
			if not inram(gym) or not inram(gym + 0x1B) or u8(gym + 0x11) ~= room or u8(gym + 0x13) ~= state then
				return bad("gym system", inram(gym) and inram(gym + 0x13) and string.format("room %d state %d", u8(gym + 0x11), u8(gym + 0x13)) or nil)
			end
			local data = suny.data(room)
			if not data then return nil, "data" end
			if story_var(0x4000) ~= 0 then return bad("button var", tostring(story_var(0x4000))) end
			-- Buttons are the live coord events (MapHeaderData +0C count, +1C list, stride 0x10: script,
			-- x, z, width, length, y, value, var). Any other trigger would run a script the plan cannot
			-- model, so it refuses rather than walk over it.
			local mhd = u32(fs + 0x14)
			if not inram(mhd) then return bad("map header data") end
			local n, p = u32(mhd + 0x0C), u32(mhd + 0x1C)
			if n == 0 or n > 64 or not inram(p) or p < mhd + 0x20 or p + n * 0x10 > mhd + 0x820 then
				return bad("coord event list", tostring(n))
			end
			local buttons, at = {}, {}
			for i = 0, n - 1 do
				local c = p + i * 0x10
				local x, z, kind = u16(c + 2), u16(c + 4), SCRIPT_TYPE[room][u16(c)]
				if kind == nil or u16(c + 0x0E) ~= 0x4000 or u16(c + 0x0C) ~= 0 or u16(c + 6) ~= 1 or u16(c + 8) ~= 1 then
					return bad("unknown coord event", string.format("%d,%d script %d", x, z, u16(c)))
				end
				local key = tkey(x, z)
				if at[key] then return bad("duplicate button", x..","..z) end
				local button = { x = x, z = z, key = key, turn = data.turn[kind] }
				buttons[#buttons + 1], at[key] = button, button
			end
			suny.error = nil
			return { room = room, state = state, data = data, buttons = buttons, at = at, sig = state }
		end
		-- The tiles the gears close in the cache's state: the search's own state when it set one, else
		-- the live state, read once per cache (terrain.query's identity includes it). nil = unknown.
		function suny.shut(fs, cache)
			if cache.sunyshore_state == nil then
				local snap = suny.snapshot(fs, cache)
				cache.sunyshore_state = snap and snap.state or false
				cache.sunyshore_data = snap and snap.data or nil
			end
			if cache.sunyshore_state == false or not cache.sunyshore_data then return nil end
			return cache.sunyshore_data.shut[cache.sunyshore_state]
		end
		-- Occupancy plus every button but `except`: a walking leg must not press one by passing over it.
		function suny.blocked(snap, occ, except)
			local out = {}
			for k in pairs(occ) do out[k] = true end
			for _, b in ipairs(snap.buttons) do if b.key ~= except then out[b.key] = true end end
			return out
		end
		-- A terrain cache in which the gears stand in `state`.
		function suny.state_cache(snap, state, motion)
			return { motion = motion, sunyshore_room = snap.room, sunyshore_state = state,
				sunyshore_data = snap.data, eterna_map = false }
		end
	end

	-- Exact native metadata is cheap to compare on a key press. Attributes and
	-- BDHC buffers are written only by load/reset; dynamic plates remain live.
	-- Field exits also discard this cache, covering reused allocation addresses.
	-- Evidence: research/re/report-20260916-platinum-nav-performance.md.
	function terrain.query(fs)
		local fresh = {}
		local m = terrain.map(fs, fresh)
		local ids = {}
		local function add(v) ids[#ids + 1] = tostring(v) end
		for _, name in ipairs({ "fs", "tcm", "ld", "mm", "ta", "mw", "mh", "mid", "dh", "dw",
			"lw", "lh", "tx", "tz", "ox", "oy", "oz" }) do add(m[name]) end
		for _, slot in ipairs(m.slots or {}) do
			for i = 1, 3 do add(slot[i]) end
			local lm, valid, cell = table.unpack(slot)
			if valid == 1 then
				-- MapMatrix_GetLandDataIDByIndex2 (02039DEC) consumes +A92+2*cell.
				-- Story changes can replace land files without replacing the matrix.
				if m.mw and cell >= 0 and cell < m.mw * m.mh and cell < 900
					and inram(m.mm + 0xA92 + cell * 2 + 1) then add(u16(m.mm + 0xA92 + cell * 2))
				else add(false) end
				local b = u32(lm + 0x85C)
				add(b); add(u32(lm + 0x858))
				if inram(b) and inram(b + 0x1F) then
					for off = 0, 0x1C, 4 do add(u32(b + off)) end
				end
			end
		end
		for cell = 0, (m.blocks and m.mw * m.mh or 0) - 1 do add(m.blocks[cell]) end
		if m.tcm == A.sTerrainCollision then
			local dm = u32(fs + 0xA0)
			add(dm)
			if inram(dm) and inram(dm + 7) then add(s32(dm)); add(u32(dm + 4)) end
			local plates = terrain.dynamic(fs, fresh)
			add(plates and #plates or false)
			for _, plate in ipairs(plates or {}) do for i = 1, 5 do add(plate[i]) end end
		end
		fresh.eterna_map = map_id(fs) == 67
		add(fresh.eterna_map)
		if fresh.eterna_map then
			local state = eterna.snapshot(fs,fresh)
			add(state and state.state or false); add(state and state.gym or false)
		end
		-- Sunyshore Gym: a press turns the gears without touching the land, so the state is identity.
		if terrain.sunyshore.active(fs, fresh) then
			local snap = terrain.sunyshore.snapshot(fs, fresh)
			add(snap and snap.state or false)
		end
		local key = table.concat(ids, ":")
		local cache = terrain.saved
		if not cache or cache.identity ~= key then
			cache = fresh; cache.identity = key; terrain.saved = cache
		end
		-- Gear is mutable even while standing still. It belongs to the search,
		-- not to the lifetime of the loaded terrain.
		cache.bike_gear, cache.height_errors, cache.honey, cache.motion = nil, nil, nil, nil
		cache.dw, cache.dw_why, cache.dw_map = nil, nil, nil   -- the Distortion World snapshot is per press
		-- Scripts can rewrite the parsed warp events without a map change.
		cache.warp_events, cache.traps, cache.panels, cache.lift = nil, nil, nil, nil
		return cache
	end

	-- ── WHAT THE BEHAVIOR BYTE MEANS ────────────────────────────────────────────────────────────
	--
	-- GENERATED by research/re/gen_pt_tiles.py — do not hand-edit; re-run it with --inject.
	-- ⭐ AND EVERY VALUE IN IT IS PROVED AGAINST THE CARTRIDGE, not taken from the enum's position.
	-- The generator reads the decompilation's `enum TileBehavior` for the NAMES, then disassembles the
	-- game's own predicate for each one — `TileBehavior_IsJumpEast` and its siblings each compile to a
	-- comparison against a literal byte — and refuses to emit anything the two disagree on. An
	-- off-by-one here does not crash: it routes a blind player into a ledge he cannot climb back up.
	-- SURFABLE is the exception and is read from the 256-byte `sTileBehaviorFlags` table at 0x020ED8C4,
	-- because `TileBehavior_IsSurfable` is a flag lookup rather than a comparison (that difference
	-- produced the generator's own first wrong answer; its header records it).
	-- Declared OUT HERE, above the marker: everything between the markers is overwritten.
	local LEDGE, LEDGE_SPAN, BLOCKED, SURFABLE, DOORWAY, B_WATERFALL, B_ICE
	--[[ TILES:BEGIN ]]
	LEDGE = {
		[0x38]="east", [0x39]="west", [0x3A]="north", [0x3B]="south", [0x5A]="north", [0x5B]="south", [0x5C]="west", [0x5D]="east",
	}
	LEDGE_SPAN = {
		[0x38]=2, [0x39]=2, [0x3A]=2, [0x3B]=2, [0x5A]=3, [0x5B]=3, [0x5C]=3, [0x5D]=3,
	}
	BLOCKED = {
		[0x30] = { east=true },
		[0x31] = { west=true },
		[0x32] = { north=true },
		[0x33] = { south=true },
		[0x34] = { north=true, east=true },
		[0x35] = { north=true, west=true },
		[0x36] = { south=true, east=true },
		[0x37] = { south=true, west=true },
		[0x49] = { north=true, south=true },
		[0x4A] = { east=true, west=true },
	}
	SURFABLE = { [0x10]=true, [0x11]=true, [0x12]=true, [0x13]=true, [0x14]=true, [0x15]=true, [0x19]=true, [0x22]=true, [0x2A]=true, [0x50]=true, [0x51]=true, [0x52]=true, [0x53]=true, [0x73]=true, [0x78]=true, [0x7C]=true, }
	DOORWAY = { [0x69]=true, }
	B_WATERFALL, B_ICE = 0x13, 0x20
	--[[ TILES:END ]]

	-- Can the player step from (x,z) to the adjacent tile in `dir` (0 up/north, 1 down/south,
	-- 2 left/west, 3 right/east)? true / false / nil, with nil meaning "cannot see it" exactly as
	-- tile_walk does.
	--
	-- ⛔ THE COLLISION BIT IS NOT THE WHOLE PERMISSION, and this is Gen V's "second permission layer"
	-- in Gen IV clothing. A BLOCK_* tile is perfectly standable and still refuses to be crossed from
	-- one side — `TILE_BEHAVIOR_BLOCK_NORTHWARD` and friends, ten of them. A router that reads only
	-- bit 15 walks straight through those, which in Gen V cost a whole test round in Dragonspiral.
	--
	-- ⛔⛔ AND THE BLOCK RULE IS TWO-SIDED, WHICH IS NOT WHAT THE NAMES SUGGEST. I wrote this the
	-- obvious way first — "does the tile I am stepping onto block movement in the direction I am
	-- going" — and the engine says something else entirely. `sub_02064004` (map_object_move.c:705-722)
	-- reads TWO behaviors and applies OPPOSITE tests to them:
	--     v1 = the tile you are STANDING ON        -> Unk_020EE76C[dir](v1)   same direction
	--     v2 = the tile you are MOVING TO          -> Unk_020EE77C[dir](v2)   the OPPOSITE direction
	-- and the two tables (map_object_move.c:725-737) are exactly each other's mirror: index 0 is
	-- `BlocksMovementNorthward` in the first and `BlocksMovementSouthward` in the second. It is a WALL
	-- ON AN EDGE, not a property of a tile — so leaving a tile through its north face and entering the
	-- next through its south face are two different permissions, and both must hold. Checking only the
	-- destination with the same direction, which is what I had, gets both halves wrong at once and
	-- would have routed straight through half the walls in the game. This is CLAUDE.md Rule 6 exactly:
	-- a fact proved in one direction used as though it held in both.
	-- ⚠ The engine ALSO refuses when the destination behavior is unreadable (`v2 ==
	-- GetNullTileBehaviorID()` -> blocked), which is the same fail-closed answer we give.
	--
	-- ⏳ LEDGES ARE TREATED AS WALLS FOR NOW, DELIBERATELY. `PlayerAvatar_WillJump` (player_move.c
	-- 1956-1993) shows the ledge is the tile you step ONTO and the jump carries you past it, and there
	-- is a second family (`..._TWICE`) that carries you further — but exactly how far each lands is in
	-- the movement-action code and is NOT yet established here. Until it is, a ledge is impassable in
	-- every direction: routes get longer, and never wrong. ⛔ Do not "fix" this by assuming a span;
	-- guessing it is how the router would confidently walk him off a cliff he cannot get back up.
	local STEPD = { [0] = { 0, -1 }, [1] = { 0, 1 }, [2] = { -1, 0 }, [3] = { 1, 0 } }
	local STEPNAME = { [0] = "north", [1] = "south", [2] = "west", [3] = "east" }
	local STEPOPP = { [0] = 1, [1] = 0, [2] = 3, [3] = 2 }
	local function bike_slope(behavior) return behavior == 0xD9 or behavior == 0xDA end
	-- Native water permission is separate from bit15 collision. Carry mode and
	-- elevated-bridge status through each search path; a Surf dismount becomes
	-- walking, and bridge status changes only after entering the destination.
	-- MapObject_IsOnWater 0206406C; DetermineElevatedBridgeStatus 02063DDC.
	function terrain.motion(fs, cache)
		if cache.motion ~= nil then return cache.motion or nil end
		cache.motion = false
		local mo = terrain.player_object(fs,cache)
		local mode = player_state(fs)
		if not mo or (mode ~= 0 and mode ~= 1 and mode ~= 2) then
			return terrain.fail(cache,"unsupported movement mode")
		end
		local manager = u32(mo+0xB4)
		if manager ~= u32(fs+FS_OBJMAN) or not inram(manager+0x12B) or u32(manager+0x128) ~= fs then
			return terrain.fail(cache,"movement object owner")
		end
		cache.motion = mode | ((u32(mo) >> 26) & 4)
		return cache.motion
	end
	function terrain.bridge_after(motion, behavior)
		if behavior == 0x70 then return (motion & 3) | 4 end
		if behavior >= 0x71 and behavior <= 0x7D then return motion end
		return motion & 3
	end
	function terrain.water(behavior, motion)
		if behavior == 0x73 or behavior == 0x78 or behavior == 0x7C then return (motion & 4) == 0 end
		return SURFABLE[behavior] and true or false
	end
	function terrain.enter_motion(motion, behavior)
		local water = terrain.water(behavior,motion)
		if water and (motion & 3) ~= 2 then return nil end
		if not water and (motion & 3) == 2 then motion = motion & 4 end
		return terrain.bridge_after(motion,behavior)
	end

	function terrain.motion_move(motion, from, to, dir)
		if (motion & 4) ~= 0 then
			local ns = to >= 0x76 and to <= 0x79
			local ew = to >= 0x7A and to <= 0x7D
			if (ns or ew) and ((motion & 3) ~= 1 or (ns and dir >= 2) or (ew and dir < 2)) then return nil end
			if (motion & 3) == 1 then
				if from >= 0x76 and from <= 0x79 and dir >= 2 then return nil end
				if from >= 0x7A and from <= 0x7D and dir < 2 then return nil end
			end
		end
		return terrain.enter_motion(motion,to)
	end

	local function step_ok(fs, x, z, dir, cache, y, slope_entry, motion)
		cache = cache or {}
		local d = STEPD[dir]; if not d then return nil end
		local from = tile_attrs(fs, x, z, cache)
		local to = tile_attrs(fs, x + d[1], z + d[2], cache)
		if not (from and to) then return nil end           -- either end unreadable: cannot judge
		-- Canalave Gym: the gym's own per-floor map replaces the land collision (terrain.canalave).
		if terrain.canalave.active(fs, cache) then
			y = y or terrain.seed(fs, x, z, cache)
			local walk = y and terrain.canalave.walk(x + d[1], z + d[2], y, cache)
			if walk == nil then return nil end
			if not walk then return false end
		-- Sunyshore Gym: an arm the gears have turned away collides before the land is asked.
		elseif terrain.sunyshore.active(fs, cache) then
			local shut = terrain.sunyshore.shut(fs, cache)
			if shut == nil then return nil end
			if shut[tkey(x + d[1], z + d[2])] or (to & ATTR_COLLIDE) ~= 0 then return false end
		elseif (to & ATTR_COLLIDE) ~= 0 then return false end
		local bf, bt = from & ATTR_BEHAVIOR, to & ATTR_BEHAVIOR
		if eterna.active(fs,cache) then
			local state = eterna.snapshot(fs,cache)
			if not state then return nil end
			if eterna.jump(state,x,z,dir) then return false end
		end
		motion = motion or terrain.motion(fs,cache)
		if motion == nil then return nil end
		local next_motion = terrain.motion_move(motion,bf,bt,dir)
		if next_motion == nil then return false end
		if not slope_entry and (bike_slope(bf) or bike_slope(bt)) then return false end
		-- A LEDGE IS NOT AN ORDINARY STEP. Approached in the direction it opens it is a JUMP, which
		-- ledge_jump below resolves; approached any other way the engine falls through to exactly
		-- this ordinary test, and every retail ledge tile has bit 15 set — so the line above has
		-- already refused it as the wall it is. Nothing extra is needed here, and adding it back
		-- would make the jump unreachable.
		-- ⛔ ICE IS NOT AN ORDINARY FLOOR AND MUST NOT BE ROUTED OVER (codex-review, confirmed). On ice
		-- one press carries you until you hit something, so the search's assumption — that you can stop
		-- and turn on every tile — is false, and a "3 up" whose corner falls in the middle of an ice run
		-- is an instruction the player cannot carry out. Refused in BOTH directions: stepping ONTO ice,
		-- and stepping anywhere while already ON it, because a route that begins mid-slide is measured
		-- from a tile he is still being carried off.
		-- One press as an edge to the tile the slide actually stops on is terrain.snowpoint's search,
		-- which asks this function for single steps with `snowpoint_ice` set on its own cache.
		-- Everywhere else the trade stands: routes near ice are longer or refused, and never wrong.
		if (bt == B_ICE or bf == B_ICE) and not cache.snowpoint_ice then return false end
		-- ⛔ A WATERFALL TILE IS NEVER A STEP. From below, the fall is higher than the water (the height
		-- rule, or bit 15, refuses it); from above it is level, and pressing south onto it while surfing
		-- with Waterfall in the party is the DESCENT (ov5_021E04A8, ov5 field input), which moves two
		-- tiles down the fall. Either way a route over it is wrong; the fall is used only from a
		-- terrain.waterfall_spots end, as a move.
		if bt == B_WATERFALL then return false end
		local out = BLOCKED[bf]                            -- leaving THIS tile that way
		if out and out[STEPNAME[dir]] then return false end
		local into = BLOCKED[bt]                           -- entering THAT tile from this side, i.e.
		if into and into[STEPNAME[STEPOPP[dir]]] then return false end   -- its OPPOSITE face
		y = y or terrain.seed(fs, x, z, cache)
		-- Pastoria Gym's gates compare the height the player stands at NOW, not the destination's.
		if y ~= nil and pastoria.active(fs, cache) then
			local rules = pastoria.rules(cache)
			if not rules then return nil end
			local need = rules[bt]
			if need ~= nil and y ~= need then return false end
		end
		local ny, source = terrain.height(fs, x + d[1], z + d[2], y, cache)
		if not ny then return nil end
		if math.abs(ny - y) >= 0x14000 or (source == 2 and bt == 0x59) then return false end
		return true, ny, next_motion
	end

	function terrain.discovery_step(fs,x,z,dir,cache,from,to)
		local motion = terrain.motion(fs,cache)
		if motion == nil then return nil end
		local modes = (motion & 3) == 2 and {2,0} or {motion & 3}
		local bridges = from >= 0x71 and from <= 0x7D and {0,4} or {from == 0x70 and 4 or 0}
		local unknown = false
		for _,mode in ipairs(modes) do
			for _,bridge in ipairs(bridges) do
				local candidate = mode | bridge
				if terrain.motion_move(candidate,from,to,dir) ~= nil then
					local ok = step_ok(fs,x,z,dir,cache,nil,nil,candidate)
					if ok then return true end
					if ok == nil then unknown = true end
				end
			end
		end
		if unknown then return nil end
		return false
	end

	-- ── WHO IS STANDING WHERE ───────────────────────────────────────────────────────────────────
	--
	-- ⛔ PEOPLE AND GROUND ITEMS BLOCK THEIR TILE, AND THE TILEMAP DOES NOT SAY SO. Gen V shipped a
	-- router without this and Ola walked into it immediately ("it thinks tiles with an npc on them are
	-- walkable, but that is wrong, same with items"). The engine agrees: `BerryPatches_CheckCollision`
	-- asks `TerrainCollisionManager_CheckCollision` AND THEN `sub_0206326C(fieldSystem->mapObjMan, x,
	-- z, 0)` (retail 0x0205605c-0x02056064), and treats a hit from either as a collision.
	--
	-- ⛔⛔ AND IT IS NOT THE SAME TEST THE NAV LIST USES — I had this wrong first time. The obvious
	-- candidate is `sub_0206326C`, the "who is on this tile" helper that BerryPatches_CheckCollision
	-- calls; it tests bit 0 and the CURRENT position and nothing else. But the PLAYER'S OWN movement
	-- goes through `sub_02063F00`, and that is a different rule, read out of the cartridge:
	--     0x02063F24  cmp against self          — an object never blocks itself
	--     0x02063F28-0x02063F2A  status & 1     — must be active
	--     0x02063F32-0x02063F38  `movs r1,#1 ; lsls r1,#0x12` = 1 << 18, and it must be CLEAR
	--     0x02063F42/0x02063F4A  current x and z, and then the PREVIOUS pair as well
	-- Two of those matter and neither is guessable:
	--   * BIT 18, not bit 9. The list's visibility rule (active, not script-hidden, not an unresolved
	--     clone) is a different question with a different answer, and using it here would let the
	--     router walk through something the engine will stop it on. Two small-integer flag spaces that
	--     are not the same space — CLAUDE.md Rule 7, in its quietest form.
	--   * THE PREVIOUS TILE COUNTS. A person mid-step occupies BOTH the tile they left and the one
	--     they are entering, so a route planned through the tile behind a walking NPC is a route into
	--     them. Gen V recorded exactly this and it is true here too.
	-- ⚠ NOT REPLICATED: the engine also ignores an object more than two Y units away. Terrain
	-- routing now carries height, but this occupancy snapshot still combines actors by X/Z.
	-- It can over-block stacked ground; adding a layer-aware actor snapshot needs its own trace.
	--   MapObject +0x58 xPrev, +0x60 zPrev (MapObject_GetXPrev 0x02063008 `ldr r0,[r0,#0x58]`,
	--   MapObject_GetZPrev 0x02063018 `ldr r0,[r0,#0x60]`).
	--
	-- The enumeration itself is the array walk below: `maxObjects` entries of a flat array.
	--   FieldSystem       +0x38  mapObjMan     `ldr r0,[r7,#0x38]` at 0x0205605c, immediately before
	--                                          the call — the same instruction that proves the call.
	--   MapObjectManager  +0x04  maxObjects    MapObjectMan_GetMaxObjects 0x02062824 `ldr r0,[r0,#4]`
	--   MapObjectManager  +0x124 mapObj[]      MapObjectMan_GetMapObject  0x02062878
	--                                          `movs r1,#0x49 ; lsls r1,#2 ; ldr r0,[r0,r1]`
	--   MapObject         +0x00  status        MapObject_CheckStatus 0x020628d0 `ldr r0,[r0] ; ands`
	--                                          MAP_OBJ_STATUS_0 = 1 << 0
	--   MapObject         +0x64 / +0x6C  x / z, and the stride is 0x128 (the struct's own size).
	-- ⚠ The stride is the one number here NOT read from an instruction — it is the struct's declared
	-- size — so it is checked instead by a different route: four independent offsets inside MapObject
	-- (+0x28, +0x2C, +0x64, +0x6C) were each read from their own accessor and every one lands exactly
	-- where the declared field order puts it, which cannot happen if the layout differs.

	-- The set of tiles a live map object is standing on, as tkey -> true. `skip` is a tile to leave
	-- out — the goal, because "walk to that person" means stopping beside them, so the person must not
	-- make their own tile unreachable.
	-- ⛔ THE PLAYER IS ONE OF THE 64 SLOTS, and leaving him in would block his own tile. The engine
	-- gets away with never excluding him because it only ever asks about the tile AHEAD; we ask about
	-- whole regions, and a start tile marked solid quietly poisons both the flood and any route that
	-- needs to come back through where he is standing.
	-- ⚠ THERE IS NO LONGER A "GOAL EXEMPTION". There used to be one, so a route could reach the tile a
	-- person was standing on — which was the wrong endpoint in the first place (see goal_for). An
	-- occupied tile is now simply occupied, for everyone.
	-- ── LEDGES: ONE ACTION THAT CROSSES MORE THAN ONE TILE ──────────────────────────────────────
	--
	-- ⛔ THE TRIGGER IS THE TILE YOU STEP ONTO, NOT THE ONE YOU LEAVE, and the jump carries you PAST
	-- it. `PlayerAvatar_WillJump` (retail 0x02060CE4, src/player_move.c:1956-1993) forms the adjacent
	-- coordinate — `bl 0x02063020` for x, `bl 0x0206419C` for dx, added at 0x02060D20 — reads THAT
	-- tile's behavior at 0x02060D3E and asks one direction-specific predicate. So an ordinary jump
	-- finishes two tiles from where it began and a JUMP_*_TWICE three, and both are ONE movement
	-- action, not two or three presses (report-20260905-pt-ledges.md).
	--
	-- ⚠ AND THE TWO FAMILIES DO NOT SHARE AN ORDER — ordinary is east/west/north/south (0x38-0x3B),
	-- twice is north/south/west/east (0x5A-0x5D). Both tables come from the generator, which proves
	-- every value against the game's own predicate, so nothing here derives a direction from
	-- base + dir. Rule 7, in the one place where getting it wrong sends someone off a cliff.
	--
	-- ⛔ THE TWICE FAMILY IS DELIBERATELY CLOSED. Its jumps only exist in the Distortion World, whose
	-- movement runs on a three-dimensional platform lookup with a floor ORIENTATION we have not
	-- traced — and unlike ordinary ledges those gaps are jumpable both ways, so a router that offered
	-- them would be routing through a world it cannot read. Refusing them costs a shortcut in one
	-- late-game area; offering them wrongly costs the player a wall.
	--
	-- ⚠ TWO THINGS HERE ARE STRICTER THAN THE ENGINE, and both are deliberate. The engine applies NO
	-- collision, occupancy or height veto to the tiles a jump crosses or lands on — it simply moves
	-- you — but we refuse a landing we cannot read, and one that is solid or occupied. Every retail
	-- ledge lands on open ground, so this costs nothing real; what it buys is that a route we cannot
	-- verify is refused rather than walked. Fail closed, as everything in this file does.
	--
	-- ⚠ SURFING CANNOT JUMP. The decision helper itself is state-blind, but the consumer that turns
	-- its answer into a movement action only does so while walking, running or cycling
	-- (PLAYER_AVATAR_WALKING 0, CYCLING 1, SURFING 2 — constants/player_avatar.h:7-11). An
	-- unreadable state refuses, like everything else.
	-- ⛔ AN ALLOW-LIST, NOT A DENY-LIST (codex-review, confirmed). Writing this as "not nil and not
	-- SURFING" let every OTHER state jump — and PlayerAvatarState has twenty of them: fishing, using
	-- a field move, the Poketch, saving, the Distortion World. Only the two states whose movement
	-- handlers actually consume a jump may have one (PLAYER_AVATAR_WALKING 0 and CYCLING 1,
	-- constants/player_avatar.h:7-11); everything else, readable or not, refuses. That is the
	-- difference between "we could read a number" and "we know what the number means" — Rule 5's
	-- readability-is-not-a-type-check, applied to a state rather than a pointer.
	local PA_WALK, PA_BIKE = 0, 1
	local function ledge_jump(fs, x, z, dir, cache, pstate, y, motion)
		local d = STEPD[dir]; if not d then return nil end
		if cache and cache.no_ledges then return nil end           -- a flood that must not jump (refresh)
		if pstate ~= PA_WALK and pstate ~= PA_BIKE then return nil end
		if eterna.active(fs,cache) then
			cache = cache or {}
			local state = eterna.snapshot(fs,cache)
			if not state then return nil end
			local span,lx,lz = eterna.jump(state,x,z,dir)
			if span then
				if tile_walk(fs,lx,lz,cache) ~= true then return nil end
				y = y or terrain.seed(fs,x,z,cache)
				local ny = terrain.height(fs,lx,lz,y,cache)
				if not ny then return nil end
				motion = motion or terrain.motion(fs,cache)
				if motion == nil then return nil end
				return span,lx,lz,ny,terrain.bridge_after(motion,tile_behavior(fs,lx,lz,cache))
			end
		end
		if bike_slope(tile_behavior(fs, x, z, cache)) then return nil end
		local bt = tile_behavior(fs, x + d[1], z + d[2], cache)
		if not bt then return nil end                      -- cannot read the trigger: no claim
		if LEDGE[bt] ~= STEPNAME[dir] then return nil end  -- not a ledge, or not this way round
		local span = LEDGE_SPAN[bt]
		-- The twice family only in the Distortion World's own searches, which set dw_twice.
		if span ~= 2 and not (span == 3 and cache and cache.dw_twice) then return nil end
		local lx, lz = x + d[1] * span, z + d[2] * span
		if tile_walk(fs, lx, lz, cache) ~= true then return nil end
		cache = cache or {}
		y = y or terrain.seed(fs, x, z, cache)
		local ny = terrain.height(fs, lx, lz, y, cache)
		if not ny then return nil end
		motion = motion or terrain.motion(fs,cache)
		if motion == nil then return nil end
		return span, lx, lz, ny, terrain.bridge_after(motion,tile_behavior(fs,lx,lz,cache))
	end

	-- PlayerAvatar_TileMove_BikeSlope 0205f808 forces movement from D9/DA.
	-- North needs cycling speed >=3; fourth gear adds one speed level per normal
	-- step (020608e4/020603bc). Include three uninterrupted entry steps, then the
	-- two forced steps, as one hold instruction. A run-up can turn north after
	-- two east/west steps: FourthGear's moving state preserves speed through a
	-- direction change (02060850). South needs no bicycle. The
	-- cartridge's 17 slopes are D9 directly above DA; never invent a stopping
	-- point or a turn inside that pair. The forced steps bypass normal height
	-- collision, like ledges, but their terrain and occupancy must still be known.
	local function slope_move(fs, x, z, dir, cache, pstate, y, occ, motion)
		if not STEPD[dir] then return nil end
		if pstate ~= PA_WALK and pstate ~= PA_BIKE then return nil end
		if dir ~= 1 and pstate ~= PA_BIKE then return nil end
		if bike_slope(tile_behavior(fs, x, z, cache)) then return nil end
		local down = dir == 1
		local path = down and {1,1,1} or {dir,dir,0,0,0}
		local d, entry = STEPD[dir], down and 1 or 3
		local ex, ez = down and x or x + d[1]*2, down and z+1 or z+d[2]*2-1
		local first, second = down and 0xD9 or 0xDA, down and 0xDA or 0xD9
		if tile_behavior(fs, ex, ez, cache) ~= first
			or tile_behavior(fs, ex, ez + (down and 1 or -1), cache) ~= second then return nil end
		if not down then
			if pstate ~= PA_BIKE then return nil end
			if cache.bike_gear == nil then
				-- GetCyclingGear 0205ec88 -> PlayerData 0205ec0c (+38) -> u16+0.
				local pa = u32(fs + FS_AVATAR)
				if not (inram(pa) and inram(pa + 0x3B)) then return terrain.fail(cache, "bike avatar unreadable") end
				local data = u32(pa + 0x38)
				if not (inram(data) and inram(data + 1)) then return terrain.fail(cache, "bike gear data unreadable") end
				local gear = u16(data)
				if gear > 1 then return terrain.fail(cache, "bike gear invalid") end
				cache.bike_gear = gear
			end
			if cache.bike_gear ~= 1 then return nil end
		end
		motion = motion or terrain.motion(fs,cache)
		if motion == nil then return nil end
		local cx, cz, cy = x, z, y
		for hop, move in ipairs(path) do
			local delta = STEPD[move]
			local nx, nz = cx + delta[1], cz + delta[2]
			local bt = tile_behavior(fs, nx, nz, cache)
			if not bt or occ[tkey(nx, nz)] then return nil end
			if hop < entry and bike_slope(bt) then return nil end
			if hop == #path and (bike_slope(bt) or bt == B_ICE or LEDGE[bt]) then return nil end
			if hop <= entry then
				local ok
				ok, cy, motion = step_ok(fs, cx, cz, move, cache, cy, true, motion)
				if not ok then return nil end
			else
				if tile_walk(fs, nx, nz, cache) ~= true then return nil end
				cy = terrain.height(fs, nx, nz, cy, cache)
				if cy == nil then return nil end
				motion = terrain.bridge_after(motion,bt)
			end
			cx, cz = nx, nz
		end
		return #path, cx, cz, cy, path, motion
	end

	local function occupied(fs)
		local occ, mm = {}, u32(fs + FS_OBJMAN)
		local gates = {}
		local pmo
		do
			local pa = u32(fs + FS_AVATAR)
			if inram(pa) then pmo = u32(pa + PA_OBJ) end
		end
		-- ⛔ THE SECOND RETURN IS "DID I ACTUALLY READ THIS", AND IT IS NOT OPTIONAL. An empty table on
		-- its own cannot tell "nobody is about" from "the manager was unreadable", and a router that
		-- confuses those walks confidently through whoever it could not see. Every caller must decide
		-- what to do with a false; none may treat it as an empty room.
		if not inram(mm) then dbg("ow: no mapObjMan"); return occ, false end
		if u32(mm + MOM_FS) ~= fs then dbg("ow: mapObjMan belongs to another field"); return occ, false end
		local n = s32(mm + MOM_MAX)
		if n ~= MOM_EXPECT then dbg("ow: bad maxObjects"); return occ, false end
		local arr = u32(mm + MOM_ARRAY)
		if not (inram(arr) and inram(arr + n * MO_STRIDE - 1)) then
			dbg("ow: mapObj array unreadable"); return occ, false
		end
		if not inram(pmo) then dbg("ow: no player object"); return occ, false end
		for i = 0, n - 1 do
			local o = arr + i * MO_STRIDE
			local st = u32(o + MO_STATUS)
			if o ~= pmo and (st & MO_INUSE) ~= 0 and (st & MO_NOCOLLIDE) == 0 then
				local x,z = s32(o + MO_X),s32(o + MO_Z)
				local previous = tkey(s32(o + MO_XPREV),s32(o + MO_ZPREV))
				local key,gfx = tkey(x,z),u32(o + MO_GFX)
				-- Bit 4 is a Strength boulder: not removed like the other two but pushed, so the
				-- reachability flood opens it only in a direction it can be pushed (reach_from), and
				-- routes through it come from the push planner (terrain.strength), never from pf_plan's
				-- remove-the-obstacle hypothetical.
				local bit = gfx == 0x56 and 1 or gfx == 0x55 and 2 or gfx == 0x54 and 4 or nil
				-- Only stationary, visible HM actors can be hypothetical gates.
				-- A second occupant always wins, regardless of actor-array order.
				-- ⛔ AN OBSTACLE IN A CELL THAT IS NOT LOADED HAS NO HEIGHT YET, AND IS STILL A GATE.
				-- MapObject_RecalculateObjectHeight (map_object_move.c:914) sets MAP_OBJ_STATUS_12
				-- (0x1000) when GetHeight finds no loaded BDHC, leaving pos.y at the spawn value;
				-- sub_020634DC retries every frame and the object settles once its cell loads. This
				-- used to exclude such actors, so every boulder, rock and tree in the far half of a
				-- two-cell room was a plain wall: Mt. Coronet 1F hid the west Route 211 exit from the
				-- B1F stairs and listed it a few steps south (3 November). `pending` marks them;
				-- terrain.rest_y gives the surface they will settle on.
				if bit and previous == key and (st & (MO_HIDDEN | MO_CLONE)) == 0 and not occ[key] then
					gates[key] = {bit=bit,name=HM_NAME[gfx],actor=o,x=x,z=z,y=s32(o + 0x74),
						pending=(st & 0x1000) ~= 0}
				else gates[key] = nil end
				if previous ~= key then gates[previous] = nil end
				occ[key],occ[previous] = true,true
			end
		end
		return occ, true, gates
	end

	-- ── A* ──────────────────────────────────────────────────────────────────────────────────────
	-- Four-neighbour, Manhattan heuristic, permissions from step_ok. Bounded hard: this runs on a KEY
	-- PRESS, never per frame (Rule 3), and an unbounded flood over a whole outdoor matrix would be a
	-- visible freeze rather than a slow answer.
	-- ⛔ AN UNKNOWN TILE IS IMPASSABLE HERE. step_ok answers nil for anything it cannot see, and for
	-- ROUTING that has to mean "no" — the alternative is the Gen V fail-open that walked Ola up a
	-- cliff. The reachability FILTER takes the opposite view of the same nil (see reach_from), because
	-- there the question is "may I offer this to him", and hiding a real exit is the worse mistake.
	-- Owner snapshots and decoded planes avoid repeated emulator calls; navigation shares
	-- that geometry with the route. Equal-f heap ties favour the node nearer the goal.
	-- Offline timings and memory-call counts are in the 20260916 navigation report.
	--
	-- ⭐⭐ AND IT PREFERS STRAIGHT LINES, WHICH IS NOT A REFINEMENT — IT IS THE FEATURE. A plain A*
	-- returns any shortest path, and on open ground "any" means a STAIRCASE: the first version of this
	-- came back with "2 down, 1 right, 1 down, 1 right" for a route that is honestly "2 right, 3 down".
	-- Both are five steps; one is two instructions and the other is four, and the difference is the
	-- whole experience of following a route by ear. (Caught by the offline harness before it ever
	-- reached Ola, which is exactly what the harness is for.)
	-- So the cost is `KSTEP per step plus 1 per turn`, and the node includes THE DIRECTION IT WAS
	-- ENTERED BY — without that a turn is not even a well-defined property of a node. KSTEP is large
	-- enough that a step always outweighs every turn a route could contain, so this never trades a
	-- longer walk for a tidier one: it is a tie-break, not a preference. The heuristic is scaled to
	-- match and so stays admissible.
	local PF_LIMIT = 12000                     -- expansions; ~3 windows' worth of tiles
	local KSTEP = 1 << 14                      -- >> any achievable turn count, so steps always win
	local NODIR = 4                            -- "we started here", which turns from nothing
	-- FieldMap_ChangeZone replaces native events on every matrix-header crossing.
	-- A route cannot use another header as a detour or as a streaming frontier.
	-- Only the selected connection's final tile may leave the current header.
	function terrain.route_scope(fs, sx, sz, gx, gz, destination, cache)
		local m, here = terrain.map(fs, cache), map_id(fs)
		if not here then dbg("route scope: location owner unreadable"); return nil end
		if not m.mw or m.mw < 1 or m.mh < 1 or m.mw > 30 or m.mh > 30
			or m.dw ~= m.mw or m.dh ~= m.mh then dbg("route scope: matrix dimensions invalid"); return nil end
		if not inram(m.mm+6+m.mw*m.mh*2-1) then dbg("route scope: header grid unreadable"); return nil end
		local tx,tz = 0,0
		if m.tcm == A.sTerrainCollision then
			if m.lw ~= m.mw or m.lh ~= m.mh or not m.tx or not m.tz then dbg("route scope: land owner invalid"); return nil end
			tx,tz = m.tx,m.tz
		elseif m.tcm ~= A.sSimpleTerrainCollis then dbg("route scope: collision owner unsupported"); return nil end
		local headers = {}
		local function header(x,z)
			x,z = x-tx,z-tz
			if x < 0 or z < 0 or x >= m.mw*TILES or z >= m.mh*TILES then return nil end
			local cell = x//TILES + z//TILES*m.mw
			if headers[cell] == nil then headers[cell] = u16(m.mm+6+cell*2) end
			return headers[cell]
		end
		if header(sx,sz) ~= here then dbg("route scope: start header mismatch"); return nil end
		return function(x,z,terminal)
			local id = header(x,z)
			return id == here or terminal and x == gx and z == gz
				and destination ~= nil and destination > 0 and destination < MH_COUNT and id == destination
		end
	end

	local function pf_astar(fs, sx, sz, gx, gz, occ, cache, scope)
		if sx == gx and sz == gz then return {} end
		cache = cache or {}
		cache.height_errors = nil
		local frontier = false
		local sy = terrain.seed(fs, sx, sz, cache)
		if sy == nil then return nil, "terrain" end
		local initial_motion = terrain.motion(fs,cache)
		if initial_motion == nil then return nil,"terrain" end
		-- A step ending on a warp tile warps: only the goal may be one (terrain.traps).
		local traps = terrain.traps(fs, cache)
		-- Each tile can have several surfaces. Intern (tile, height, entry direction)
		-- into a numeric heap id; an upper walkway must never inherit a lower route.
		local node_ids, nodes = {}, {}
		local function nkey(x, z, y, dir, motion)
			local tk, hk = tkey(x, z), (y * 8 + dir) * 8 + motion
			local row = node_ids[tk]
			if not row then row = {}; node_ids[tk] = row end
			if not row[hk] then
				local id = #nodes + 1
				row[hk], nodes[id] = id, { x, z, dir, y, motion }
			end
			return row[hk]
		end
		local sk = nkey(sx, sz, sy, NODIR, initial_motion)
		local g, came, dirs, spans, slopes = { [sk] = 0 }, {}, {}, {}, {}
		-- A plain binary heap keyed on f: Lua has no priority queue and table.sort per pop would turn
		-- an O(n log n) search into O(n^2 log n) on exactly the big outdoor maps that need it most.
		local heap, hn = {}, 0
		-- Equal-cost frontier nodes nearer the goal avoid expanding a whole open
		-- rectangle. Step/turn costs and the heuristic are unchanged.
		local function before(a, b) return a.f < b.f or (a.f == b.f and a.g > b.g) end
		local function push(k, f, gv)
			hn = hn + 1; heap[hn] = { k = k, f = f, g = gv }
			local i = hn
			while i > 1 do
				local p = i // 2
				if not before(heap[i], heap[p]) then break end
				heap[p], heap[i] = heap[i], heap[p]; i = p
			end
		end
		local function pop()
			if hn == 0 then return nil end
			local top = heap[1]
			heap[1] = heap[hn]; heap[hn] = nil; hn = hn - 1
			local i = 1
			while true do
				local l, r, m = i * 2, i * 2 + 1, i
				if l <= hn and before(heap[l], heap[m]) then m = l end
				if r <= hn and before(heap[r], heap[m]) then m = r end
				if m == i then break end
				heap[m], heap[i] = heap[i], heap[m]; i = m
			end
			return top.k, top.g
		end
		local function xz(n)
			return table.unpack(nodes[n])
		end
		-- ⚠ THE HEURISTIC STAYS EXACTLY AS IT WAS, AND THAT IS A MEASURED DECISION RATHER THAN AN
		-- OVERSIGHT — the note is here because the textbook answer is wrong for this router.
		--
		-- A* only guarantees the shortest route while its estimate never EXCEEDS the true remaining
		-- cost, and a ledge jump closes TWO tiles of Manhattan distance for one action — so strictly
		-- the estimate should halve. It was written that way first, and the harness refused it: the
		-- long-route test across a big open map stopped finding a route at all, because halving the
		-- estimate turns A* most of the way back into Dijkstra and the expansion budget runs out.
		-- A route not found is far worse than a route one action longer.
		--
		-- What the estimate actually costs us: it is EXACT wherever no jump is available, which is
		-- almost everywhere, and it can overestimate by one step per jump the remaining path could
		-- have used. That does not stop jumps being taken — a jump successor still gets a strictly
		-- lower f than the walk beside it, so the search prefers it — it only means that on a route
		-- where several ledges compete, A* may settle for one that walks round instead of proving
		-- the very shortest. Bounded, understood, and the opposite trade to the one that fails.
		local function hcost(x1, z1)
			return (math.abs(gx - x1) + math.abs(gz - z1)) * KSTEP
		end
		local function path(n)
			local moves, cur = {}, n
			while cur ~= sk do
				moves[#moves + 1] = { dirs[cur], spans[cur] or 1, nodes[cur][4], slopes[cur], nodes[cur][5] }
				cur = came[cur]
			end
			for i = 1, #moves // 2 do
				moves[i], moves[#moves - i + 1] = moves[#moves - i + 1], moves[i]
			end
			return moves
		end
		local goal_unloaded = not cache.hm_offline and terrain.unloaded(fs, gx, gz, cache)
		local start_h = hcost(sx, sz)
		push(sk, hcost(sx, sz), 0)
		local seen = 0
		while seen < PF_LIMIT do
			local n, gv = pop(); if not n then break end
			-- ⛔ A STALE HEAP RECORD IS NOT AN EXPANSION. Improving a node pushes a second entry and
			-- leaves the old one behind; popping that later would re-expand the node AND spend one of
			-- the budget, so a big search could exhaust its limit on duplicates and then give up on a
			-- graph it never finished (codex-review, confirmed). The g it was pushed with identifies it.
			-- ⚠ HONESTLY: THIS ONE HAS NO TEST, and that is a deliberate choice rather than an
			-- oversight. Its only observable effect is at the exact expansion-limit boundary — with the
			-- guard the search finishes, without it the same search gives up — so a discriminating
			-- fixture would have to be tuned to straddle PF_LIMIT and would then break on any change to
			-- KSTEP, the heuristic or the limit itself. A brittle test that passes for the wrong reason
			-- is worse than a stated gap, so this is the stated gap. The reasoning is checkable; the
			-- change is two words and cannot make a correct search incorrect.
			if gv == g[n] then
			seen = seen + 1
			local cx, cz, cdir, cy, motion = xz(n)
			if cx == gx and cz == gz then
				return path(n)
			end
			local base = g[n]
			for dir = 0, 3 do
				local d = STEPD[dir]
				if goal_unloaded and n ~= sk and hcost(cx, cz) < start_h
					and hcost(cx + d[1], cz + d[2]) < hcost(cx, cz)
					and (not scope or scope(cx+d[1],cz+d[2],true))
					and terrain.unloaded(fs, cx + d[1], cz + d[2], cache) then
					-- Every edge in this prefix has passed the normal collision and
					-- height checks. Do not search all four cells for an unloaded goal.
					return path(n), "partial"
				end
				-- ⭐ ONE ACTION, ONE EDGE, WHATEVER DISTANCE IT COVERS. A ledge jump is a single
				-- press that lands two tiles away, so it costs KSTEP once — the same as a step —
				-- and the successor is the LANDING. Charging it two steps would make the router
				-- prefer walking round a ledge it should hop.
				local span, nx, nz, ny, next_motion = ledge_jump(fs, cx, cz, dir, cache, motion & 3, cy, motion)
				local slope
				if not span then
					span, nx, nz, ny, slope, next_motion = slope_move(fs, cx, cz, dir, cache, motion & 3, cy, occ, motion)
				end
				if span then
					-- ⚠ The landing must be free of people as well: ledge_jump has already proved
					-- it is standable ground, and this is the same occupancy rule every other
					-- successor obeys.
				else
					nx, nz = cx + d[1], cz + d[2]
					local ok
					ok, ny, next_motion = step_ok(fs, cx, cz, dir, cache, cy, nil, motion)
					-- An unknown step into a cell that is simply not loaded is not a wall; the
					-- search that stops there has proved nothing (see the reason below).
					if ok == nil and not frontier and not cache.hm_offline
						and terrain.unloaded(fs, nx, nz, cache) then frontier = true end
					if not ok then nx = nil end
				end
				if nx and traps[tkey(nx, nz)] and not (nx == gx and nz == gz) then nx = nil end
				if nx and scope then
					local x,z = cx,cz
					for hop = 1,span or 1 do
						local delta = STEPD[slope and slope[hop] or dir]
						x,z = x+delta[1],z+delta[2]
						if not scope(x,z,hop == (span or 1)) then nx = nil; break end
					end
				end
				if nx then
					local nn = nkey(nx, nz, ny, slope and slope[#slope] or dir, next_motion)
					local cost = base + KSTEP * (slope and span or 1) + ((cdir ~= NODIR and cdir ~= dir) and 1 or 0)
					if (g[nn] == nil or g[nn] > cost) and not occ[tkey(nx, nz)] then
						g[nn] = cost
						came[nn], dirs[nn] = n, dir
						spans[nn] = span
						slopes[nn] = slope
						push(nn, cost + hcost(nx, nz), cost)
					end
				end
			end
			end
		end
		-- ⛔ TWO DIFFERENT FAILURES, AND THEY MUST NOT SOUND THE SAME. Running out of budget is a fact
		-- about US; emptying the queue is a fact about the WORLD. Only the second justifies telling the
		-- player he cannot get somewhere.
		-- ⛔ AND A QUEUE THAT EMPTIED AGAINST AN UNLOADED CELL IS NOT THE WORLD. LandData loads cells by
		-- the player's quadrant, so in a two-cell room the far cell is missing from the outer half of
		-- the near one; "exhausted" there told the player a door across the cell line could not be
		-- reached (Mt. Coronet 2F and 1F, 3 November). It is "terrain", which pf_plan_direct answers
		-- with a prefix planned on the cartridge's geometry (pf_loaded_prefix).
		local reason = (seen >= PF_LIMIT) and "limit"
			or ((frontier or next(cache.height_errors or {})) and "terrain" or "exhausted")
		local reached
		if reason == "exhausted" then
			-- The loaded search graph is known for this plan. Loaded endpoints
			-- outside it cannot succeed either; a budget or terrain failure
			-- provides no such proof. Goals test X/Z, across all reached states.
			reached = {}
			for id in pairs(g) do
				local n = nodes[id]
				reached[tkey(n[1], n[2])] = true
			end
		end
		return nil, reason, reached
	end

	-- Every tile you can walk to from here, as tkey -> true. Bounded the same way and for the same
	-- reason. Used ONLY by the nav list's reachability filter.
	local REACH_LIMIT = 12000
	local function reach_from(fs, sx, sz, occ, cache, gates)
		cache = cache or {}
		cache.height_errors = nil
		local sy = terrain.seed(fs, sx, sz, cache)
		if sy == nil then return {}, false end
		local motion = terrain.motion(fs,cache)
		if motion == nil then return {},false end
		local seen, q, head = { [tkey(sx, sz)] = gates and 0 or true }, { { sx, sz, sy, motion } }, 1
		local layers = { [tkey(sx, sz)] = { [sy*8+motion] = true } }
		local n, frontier = 0, false
		-- ⛔ THE FLOOD MUST ASK EXACTLY THE ROUTER'S QUESTION, LEDGES INCLUDED. If it did not, a place
		-- reachable only over a ledge would be filtered out of the list as unreachable while the
		-- router would happily have routed to it — the list and the route disagreeing about the same
		-- world, which is the one thing this pair must never do. Read once per flood, as in pf_astar.
		local pstate = motion & 3
		local gear = false
		if pstate == PA_BIKE then
			local pa = u32(fs + FS_AVATAR)
			local data = inram(pa) and inram(pa + 0x3B) and u32(pa + 0x38) or 0
			gear = inram(data) and inram(data + 1) and u16(data) or -1
		end
		local last = gates and cache.hm_reach or cache.reach
		local same = last and last.x == sx and last.z == sz and last.y == sy
			and last.state == motion and last.gear == gear
		if same then
			for k in pairs(occ) do if not last.occ[k] then same = false; break end end
			if same then for k in pairs(last.occ) do if not occ[k] then same = false; break end end end
		end
		if same and gates then
			for key,gate in pairs(gates) do
				if not last.gates or not last.gates[key] or last.gates[key].bit ~= gate.bit then same = false; break end
			end
			if same then for key in pairs(last.gates) do if not gates[key] then same = false; break end end end
		end
		if same then return last.seen, last.complete end
		local pending, phase = {}, false
		local scope = cache.hm_scope
		-- A warp tile is reached but not walked through: the step onto it warps (terrain.traps).
		local traps, start = terrain.traps(fs, cache), tkey(sx, sz)
		-- A Strength boulder opens only when walking into it pushes it: an ordinary step, and the push
		-- legal (terrain.strength.push_ok). Walking on along the same line pushes it again, so that way
		-- the player reaches a LINE of tiles ending one short of where the boulder comes to rest. On
		-- every one of them the line's own direction is closed to the ordinary flood: the boulder is
		-- the next tile, and the line already holds what pushing it reaches. Without that, a boulder in a one-tile
		-- corridor looked like a door: Mt. Coronet 1F's boulder at (18,43) can only be pushed down a
		-- corridor whose corner it then fills, yet the tunnel exit beyond was offered from Route 211
		-- and P spent its whole search proving it unreachable (2 November, in game).
		-- Still generous on purpose: what stops a boulder leaves out other boulders (they can move
		-- too), its resting tile stays open to the flood from other sides, and an unreadable push keeps
		-- the line open. Cut and Rock Smash obstacles do stop it, as in the planner. The planner
		-- decides the rest.
		-- Walking back along a line keeps the boulder ahead, so a step from a line tile onto another
		-- tile of the SAME line keeps its closed direction; stepping off sideways leaves the boulder
		-- behind, which the flood then treats as gone. A node's [6] is its line's id (lines[id] is
		-- the direction); line_of[tile][id] marks membership. Ids, not directions: two boulders side
		-- by side pushed the same way make two parallel lines, and Victory Road 2F's stack of three
		-- needs the second one entered from the first (one of the review's puzzles hid otherwise).
		local fixed, lines, line_of = nil, {}, {}
		local function push_line(gate, dir, x, z, y, m, mask)
			if not fixed then
				fixed = {}
				for key in pairs(occ) do
					local other = gates[key]
					if not (other and other.bit == 4) then fixed[key] = true end
				end
			end
			local strength, d = terrain.strength, STEPD[dir]
			local by = strength.push_ok(fs, gate.x, gate.z, terrain.rest_y(fs, gate, cache), dir, fixed, cache)
			if by == false then return nil end
			local bx, bz, out = gate.x + d[1], gate.z + d[2], {}
			local id = #lines + 1
			lines[id] = dir
			while true do
				if by == nil then out[#out + 1] = { x, z, y, m, mask }; return out end
				local nby, ok, ny, nm = strength.push_ok(fs, bx, bz, by, dir, fixed, cache)
				if nby ~= false and (not scope or scope(bx, bz, false)) then
					ok, ny, nm = step_ok(fs, x, z, dir, cache, y, nil, m)
				end
				out[#out + 1] = { x, z, y, m, mask, id }
				local k = tkey(x, z)
				line_of[k] = line_of[k] or {}
				line_of[k][id] = true
				if not ok or #out >= 64 then return out end
				x, z, y, m = bx, bz, ny, nm
				bx, bz, by = bx + d[1], bz + d[2], nby
			end
		end
		-- A visit with a closed direction is superseded by an open one; two on different lines
		-- together close nothing (each opens what the other closes).
		-- ⭐ AND A CHEAPER REQUIREMENT IS A BETTER VISIT. The label says which moves a place needs, so a
		-- surface first reached needing Strength is visited again when it turns out Rock Smash alone
		-- will do: fewer moves first, then Cut and Rock Smash before Strength (pf_plan tries them in
		-- that order). Without this the label was whichever way the flood happened to arrive first,
		-- and Mt. Coronet B1F said "Strength" for a door that needs only Rock Smash.
		local vmask = {}
		local function bits(m) return (m & 1) + ((m >> 1) & 1) + ((m >> 2) & 1) end
		local function cheaper(m, than) return bits(m) < bits(than) or (bits(m) == bits(than) and m < than) end
		local function visit(node)
			local key, layer = tkey(node[1], node[2]), node[3] * 8 + node[4]
			local row, m = layers[key], node[5] or 0
			local was, vm = row and row[layer], vmask[key] and vmask[key][layer]
			if not (gates and vm and cheaper(m, vm)) then
				if was == true or (was ~= nil and was == node[6]) then return false end
				if was ~= nil then node[6] = nil end
			end
			row = row or {}; layers[key] = row
			row[layer] = node[6] or true
			if gates then
				vmask[key] = vmask[key] or {}; vmask[key][layer] = m
				if seen[key] == nil or cheaper(m, seen[key]) then seen[key] = m end
			else seen[key] = true end
			q[#q + 1] = node
			return true
		end
		while (head <= #q or (not phase and #pending > 0)) and n < REACH_LIMIT do
			if head > #q then
				phase = true
				for _, node in ipairs(pending) do visit(node) end
				if head > #q then break end
			end
			local cur = q[head]; head = head + 1; n = n + 1
			local ck = tkey(cur[1], cur[2])
			for dir = 0, (traps[ck] and ck ~= start) and -1 or 3 do
				local d = STEPD[dir]
				if dir ~= (cur[6] and lines[cur[6]]) and (not scope or scope(cur[1]+d[1],cur[2]+d[2],false)) then
				if not cache.hm_offline and terrain.unloaded(fs, cur[1] + d[1], cur[2] + d[2], cache) then frontier = true end
				local span, nx, nz, ny, next_motion = ledge_jump(fs, cur[1], cur[2], dir, cache, cur[4] & 3, cur[3], cur[4])
				if not span then
					local slope
					span, nx, nz, ny, slope, next_motion = slope_move(fs, cur[1], cur[2], dir, cache, cur[4] & 3, cur[3], occ, cur[4])
				end
				local stepped = false
				if not span then
					local ok
					ok, ny, next_motion = step_ok(fs, cur[1], cur[2], dir, cache, cur[3], nil, cur[4])
					if ok then nx, nz, stepped = cur[1] + d[1], cur[2] + d[2], true end
				end
				local nk = nx and tkey(nx, nz)
				-- Back along a line, the boulder's first tile included, is a walk, not another push.
				local closed = cur[6] ~= nil and nk and line_of[nk] and line_of[nk][cur[6]] and cur[6] or nil
				local gate = not closed and gates and nk and gates[nk]
				local line
				if gate and gate.bit == 4 then
					line = stepped and push_line(gate, dir, nx, nz, ny, next_motion, (cur[5] or 0) | 4)
					if not line then gate = nil end
				end
				if nk and (not scope or scope(nx,nz,false)) and (not occ[nk] or gate or closed) then
					local mask = (cur[5] or 0) | (gate and gate.bit or 0)
					for _, node in ipairs(line or { { nx, nz, ny, next_motion, mask, closed } }) do
						if gate and not phase then pending[#pending+1] = node else visit(node) end
					end
				end
				end
			end
		end
		-- ⛔ SECOND VALUE: IS THIS ANSWER WORTH ANYTHING? Not just "did it finish" — a flood that
		-- finished having reached NOWHERE has proved nothing at all, and filtering on it hides the
		-- entire list. That is not hypothetical: standing on ICE, step_ok refuses every direction
		-- (the slide is not modelled yet), so the flood ends after one tile, reports itself complete,
		-- and every door and person in the room silently disappears (codex-review verification pass).
		-- Any movement rule we have not modelled — ice today, ledges, height — produces the same shape,
		-- so the test is on the RESULT rather than on a list of known gaps.
		local reached = 0
		for _ in pairs(seen) do reached = reached + 1 end
		local complete = (n < REACH_LIMIT) and reached > 1 and not frontier and not next(cache.height_errors or {})
		local result = { x = sx, z = sz, y = sy, state = motion, gear = gear,
			occ = occ, seen = seen, complete = complete, gates = gates }
		if gates then cache.hm_reach = result else cache.reach = result end
		return seen, complete
	end

	-- HoneyTree_TryInteract (021EFB40) tests model 26 through the loaded
	-- prop managers, rather than the MapObject list. These labels describe art.
	local honey = { name = "Honey tree", rom = {} }

	function honey.map(fs, cache)
		local m = terrain.map(fs, cache)
		if m.tcm ~= A.sTerrainCollision or not m.mw or not m.mh
			or m.mw < 1 or m.mh < 1 or m.mw > 30 or m.mh > 30
			or m.dw ~= m.mw or m.dh ~= m.mh or m.lw ~= m.mw or m.lh ~= m.mh
			or not m.slots or not inram(m.mm + 0xA92 + m.mw*m.mh*2 - 1) then
			dbg("honey trees: map owner or dimensions invalid"); return nil
		end
		return m
	end

	function honey.cell(m, cell, cache)
		cache.honey = cache.honey or {}
		local hit = cache.honey[cell]
		if hit then return hit.points, hit.resident end
		local lm, resident
		for _, slot in ipairs(m.slots) do
			if slot[3] == cell and slot[2] ~= 0 then
				if resident or slot[2] ~= 1 then
					dbg("honey trees: ambiguous loaded cell"); return nil, true
				end
				lm, resident = slot[1], true
			end
		end
		if not resident then return nil, false end
		if not inram(lm + 0x86B) then dbg("honey trees: loaded owner unreadable"); return nil, true end
		local manager = u32(lm + 0x868)
		if not inram(manager) or not inram(manager + 32*0x8C - 1) then
			dbg("honey trees: prop manager unreadable"); return nil, true
		end
		local points = {}
		for i = 0, 31 do
			local prop = manager + i*0x8C
			-- Native collision uses the model and position, not render flags or Y.
			if s32(prop) == 26 then points[#points + 1] = {s32(prop+0x68), s32(prop+0x70)} end
		end
		cache.honey[cell] = {points=points, resident=true}
		return points, true
	end

	function honey.archive(id)
		if honey.rom[id] then return honey.rom[id] end
		local base, size = PM.rom_member("fielddata/land_data/land_data.narc", id, 16)
		if not base then return nil end
		local attrs, bytes = PM.rom_read(base,4), PM.rom_read(base+4,4)
		if not attrs or not bytes or attrs ~= 0x800 or bytes % 0x30 ~= 0
			or not size or 16+attrs+bytes > size then
			dbg("honey trees: cartridge prop section invalid"); return nil
		end
		local points = {}
		for i = 0, math.min(bytes // 0x30, 32) - 1 do
			local at = base + 16 + attrs + i*0x30
			if PM.rom_read(at,4) == 26 then
				local x, z = PM.rom_read(at+4,4), PM.rom_read(at+12,4)
				if not x or not z then return nil end
				if x >= 0x80000000 then x = x-0x100000000 end
				if z >= 0x80000000 then z = z-0x100000000 end
				points[#points + 1] = {x,z}
			end
		end
		-- Immutable cartridge data only. Live prop positions are read each query.
		honey.rom[id] = points
		return points
	end

	function honey.list(fs, cache)
		cache = cache or {}
		local out, seen, here = {}, {}, map_id(fs)
		local m = honey.map(fs, cache)
		if not m or not here then return out end
		for cell = 0, m.mw*m.mh - 1 do
			local header = cache.matrix_headers and cache.matrix_headers[cell] or u16(m.mm+6+cell*2)
			if header == here then
				local points, resident = honey.cell(m, cell, cache)
				if not resident then points = honey.archive(u16(m.mm+0xA92+cell*2)) end
				for _, point in ipairs(points or {}) do
					local wx = point[1] + (cell%m.mw*32+16)*65536
					local wz = point[2] + (cell//m.mw*32+16)*65536
					if wx >= 0 and wz >= 0 and wx < m.mw*32*65536 and wz < m.mh*32*65536 then
						local key = "H"..cell..":"..wx..":"..wz
						if not seen[key] then
							seen[key] = true
							out[#out+1] = {name=honey.name, key=key, x=wx//65536, z=wz//65536,
								honey={cell=cell, wx=wx, wz=wz}}
						end
					end
				end
			end
		end
		return out
	end

	function honey.present(fs, e, cache)
		cache = cache or {}
		local m, h = honey.map(fs, cache), e.honey
		if not m or h.cell < 0 or h.cell >= m.mw*m.mh
			or u16(m.mm+6+h.cell*2) ~= map_id(fs) then return false end
		local points, resident = honey.cell(m, h.cell, cache)
		if not points then return nil, not resident end
		for _, point in ipairs(points) do
			if point[1]+(h.cell%m.mw*32+16)*65536 == h.wx
				and point[2]+(h.cell//m.mw*32+16)*65536 == h.wz then return true end
		end
		return false
	end

	-- ── WHERE A ROUTE TO SOMETHING ACTUALLY ENDS ────────────────────────────────────────────────
	--
	-- ⛔⛔ YOU DO NOT WALK ONTO A PERSON, AN ITEM OR A TREE — you stop BESIDE them and press A. The
	-- first version of this routed to the entry's exact tile and exempted that tile from occupancy so
	-- the search could reach it, which produced a route whose last instruction the player physically
	-- cannot follow and which therefore never announces arrival. (Found by the codex-review, and it is
	-- right: the mutation test I wrote for "the goal is exempt from occupancy" was encoding the wrong
	-- endpoint rather than proving the right one. A test can lock in a bug as easily as a fix.)
	--
	-- A DOORWAY is the opposite case: you stand ON it, which is how the engine notices you took it
	-- (`MapHeaderData_GetIndexOfWarpEventAtPos` is asked about the player's OWN tile). So there is one
	-- rule that covers both without needing to know which kind of thing this is: **end on the entry's
	-- own tile when that is somewhere you could stand, and otherwise on the nearest side of it.**
	-- ⚠ AND REACHABILITY ASKS THE SAME QUESTION. Both use this, so the list can never offer something
	-- the router then refuses, and the router can never aim somewhere the list did not mean.
	-- ⏳ Not modelled: a wall sign the game will only read from one specific side. Stopping beside it
	-- is right in every case; the FACING may not be, and that is part of the sign-text round.
	-- ⛔⛔ AND IT RETURNS EVERY CANDIDATE, NOT ONE. Committing to the geometrically nearest side and
	-- then asking only about that side is wrong in both directions at once (codex-review verification
	-- pass, confirmed): a person against a wall whose near side is fenced off but whose far side is
	-- open gets HIDDEN from the list and REFUSED by the router, even though there is a perfectly good
	-- way to them. So the endpoints are enumerated once, here, and the two callers each do their own
	-- job with the same set — the filter keeps the entry if ANY candidate is reachable, and the router
	-- tries them in order and takes the first that yields a route.
	--
	-- ⚠ THE ENTRY'S OWN TILE, WHEN IT IS VALID, IS THE ONLY CANDIDATE. That is the doorway case, and
	-- it is not a preference: a warp fires because the player is STANDING ON IT
	-- (`MapHeaderData_GetIndexOfWarpEventAtPos` is asked about his own tile), so a route that stopped
	-- politely beside a door would never go through it.
	--
	-- Second return: `certain` — true when every side was positively read and positively rejected, so
	-- an empty list really means "there is nowhere to stand next to this". False when some side could
	-- not be read at all, which is not the same claim and must not be filtered on.
	local function goals_for(fs, e, occ, px, pz, cache, discovery)

		cache = cache or {}
		if e.clue then
			local clue=hearthome.snapshot(fs)
			if not clue or clue.key~=e.clue then return {},true end
			local walk=tile_walk(fs,clue.x,clue.z,cache)
			return walk==true and not occ[tkey(clue.x,clue.z)] and {{clue.x,clue.z}} or {},walk~=nil
		end
		e = eterna.effective(fs,e,cache)
		if not e then return {},true end
		-- Discovery resolves distant approaches from cartridge attributes. It
		-- never supplies route geometry or turns unknown heights into a route.
		local function attrs(x,z)
			if discovery then return terrain.discovery_attrs(fs,x,z,cache) end
			return tile_attrs(fs,x,z,cache)
		end
		local function walk_at(_,x,z)
			local a = attrs(x,z)
			if a == nil then return nil end
			return (a & ATTR_COLLIDE) == 0
		end
		local function behavior_at(_,x,z)
			local a = attrs(x,z)
			return a and (a & ATTR_BEHAVIOR)
		end
		if e.door_bg then
			local live = windworks_door(fs)
			if not live or live.door_bg ~= e.door_bg or live.x ~= e.x or live.z ~= e.z then return {},true end
			local x,z = e.x,e.z+1
			local walk = walk_at(fs,x,z,cache)
			if walk == true and not occ[tkey(x,z)] then return {{x,z,e.x,e.z}},true end
			return {},walk ~= nil
		end
		if e.honey then
			local present, unloaded = honey.present(fs, e, cache)
			if present == false or (not present and not unloaded) then return {}, present == false end
			local h, out, certain = e.honey, {}, present == true
			-- Inclusive native hitbox: a boundary point may have four approaches.
			-- All require facing north; the prop's rendered height is irrelevant.
			for x = math.ceil(h.wx/65536)-1, h.wx//65536 do
				for z = math.ceil(h.wz/65536), h.wz//65536+1 do
					if x >= 0 and z >= 1 then
						local walk = walk_at(fs, x, z, cache)
						if walk == nil then certain = false end
						if walk ~= false and not occ[tkey(x,z)] then out[#out+1] = {x,z,x,z-1} end
					end
				end
			end
			table.sort(out, function(a,b)
				local da, db = math.abs(a[1]-px)+math.abs(a[2]-pz), math.abs(b[1]-px)+math.abs(b[2]-pz)
				if da ~= db then return da < db end
				if a[1] ~= b[1] then return a[1] < b[1] end
				return a[2] < b[2]
			end)
			return out, certain
		end
		if e.bg_stand then
			-- An interaction spot: the tiles from which facing it runs it (PM.spot.stand).
			local out, certain = {}, true
			for _, d in ipairs(e.bg_stand) do
				local x, z = e.x + d[1], e.z + d[2]
				local walk = walk_at(fs, x, z, cache)
				if walk == nil then certain = false end
				if walk ~= false and not occ[tkey(x, z)] then out[#out + 1] = { x, z } end
			end
			table.sort(out, function(a, b)
				local da, db = math.abs(a[1]-px) + math.abs(a[2]-pz), math.abs(b[1]-px) + math.abs(b[2]-pz)
				if da ~= db then return da < db end
				if a[1] ~= b[1] then return a[1] < b[1] end
				return a[2] < b[2]
			end)
			return out, certain
		end
		if e.surf or e.climb or e.waterfall then
			-- Every unoccupied shore of the body, with the water it faces kept as the target; a Rock
			-- Climb wall's ends and a waterfall's the same way, with the wall or the fall tile faced.
			local out, certain = {}, true
			for _, s in ipairs(e.surf or e.climb or e.waterfall) do
				local walk = walk_at(fs, s[1], s[2], cache)
				if walk == nil then certain = false end
				if walk ~= false and not occ[tkey(s[1], s[2])] then out[#out + 1] = { s[1], s[2], s[3], s[4] } end
			end
			table.sort(out, function(a, b)
				local da, db = math.abs(a[1]-px) + math.abs(a[2]-pz), math.abs(b[1]-px) + math.abs(b[2]-pz)
				if da ~= db then return da < db end
				if a[1] ~= b[1] then return a[1] < b[1] end
				return a[2] < b[2]
			end)
			return out, certain
		end
		if e.warps or e.spots then
			local out, certain = {}, true
			local rules = e.warps and terrain.warp_rules(cache)
			for _, spot in ipairs(e.warps or e.spots) do
				local x, z = spot.x or spot[1], spot.z or spot[2]
				local walk = walk_at(fs, x, z, cache)
				local allowed = walk ~= false
				if e.connection and allowed then
					local from = walk_at(fs, spot[3], spot[4], cache)
					if from == false then allowed = false
					elseif from and walk then
						local from_behavior = behavior_at(fs,spot[3],spot[4],cache)
						local to_behavior = behavior_at(fs,x,z,cache)
						local cross
						if from_behavior and to_behavior then
							cross = terrain.discovery_step(fs,spot[3],spot[4],e.direction,cache,from_behavior,to_behavior)
						end
						allowed = cross ~= false
						if cross == nil then certain = false end
					else certain = false end
				end
				if walk == nil then certain = false end
				local b = e.warps and walk ~= nil and behavior_at(fs, x, z, cache)
				if e.warps and walk == false and DOORWAY[b] then
					-- Field_CheckMapTransition accepts a blocked DOOR ahead of the
					-- player. Other solid warp tiles (inactive lake rows) are not doors.
					local sides, sure = goals_for(fs, spot, occ, px, pz, cache, discovery)
					certain = certain and sure
					for _, side in ipairs(sides) do out[#out + 1] = {side[1], side[2], x, z} end
				elseif walk and rules and rules.step[b] then
					-- A WALK-IN warp (lake and cave entrances, escalators, a panel to another map): the
					-- step that ENDS on it warps (Field_CheckTransition). Like a door, the route stops
					-- on the tile before it with the warp as the target, so arriving says which way the
					-- last step goes (the player, 7 November); the player's own step goes through.
					-- Every side from which that step is legal, never another warp a step would fire.
					if not occ[tkey(x, z)] then
						local traps = terrain.traps(fs, cache)
						for dir = rules.sideways[b] and 2 or 0, 3 do
							local d = STEPD[dir]
							local sx, sz = x - d[1], z - d[2]
							local sw = walk_at(fs, sx, sz, cache)
							local sb = sw and behavior_at(fs, sx, sz, cache)
							if sw == nil or (sw and not sb) then certain = false
							elseif sw and not occ[tkey(sx, sz)] and not traps[tkey(sx, sz)] then
								local cross = terrain.discovery_step(fs, sx, sz, dir, cache, sb, b)
								if cross == nil then certain = false end
								if cross ~= false then out[#out + 1] = {sx, sz, x, z} end
							end
						end
					end
				elseif allowed and not occ[tkey(x, z)] then
					-- A PRESS warp you stand on (exit mats, gate edges, stairs) keeps its own tile as the
					-- endpoint; the target is the tile beyond it in the press direction, so arriving
					-- says which way to press, as a door does (the player, 7 November).
					local face = walk and rules and rules.face[b]
					out[#out + 1] = face and {x, z, x + STEPD[face][1], z + STEPD[face][2]} or {x, z}
				end
			end
			table.sort(out, function(a, b)
				local da = math.abs(a[1]-px) + math.abs(a[2]-pz)
				local db = math.abs(b[1]-px) + math.abs(b[2]-pz)
				if da ~= db then return da < db end
				if a[1] ~= b[1] then return a[1] < b[1] end
				return a[2] < b[2]
			end)
			return out, certain
		end
		if not e.actor and not e.pc and not e.hidden and walk_at(fs, e.x, e.z, cache) == true and not occ[tkey(e.x, e.z)] then
			return { { e.x, e.z } }, true
		end
		local out, certain = {}, true
		local actor_y
		-- Heights for discovery come from the cartridge where a cell is not loaded, when the caller
		-- has the whole-area cache (refresh's hm_discovery leaves it on the query cache).
		local hcache = discovery and cache.hm_geometry or cache
		if e.actor then
			if not inram(e.actor + 0x78) or (u32(e.actor) & 0x80001) ~= 1 then return {}, true end
			-- Native height recalculation keeps bit12 set while its cell is
			-- unavailable. That is unknown height, not an inaccessible actor.
			-- With the cartridge's surfaces it is the one the actor will settle on (terrain.rest_y),
			-- so its sides can be judged by floor as for any other actor; an item beside a boulder in
			-- the far half of Mt. Coronet B1F was offered as plainly reachable from a side on another
			-- floor (3 November harness).
			if (u32(e.actor) & 0x1000) ~= 0 then
				if not discovery then return {},false end
				if hcache ~= cache then
					actor_y = terrain.height(fs, e.x, e.z, s32(e.actor + 0x74), hcache)
				end
				if not actor_y then certain = false end
			else actor_y = s32(e.actor + 0x74) end
		end
		for dir = 0, 3 do
			local d = STEPD[dir]
			local nx, nz = e.x + d[1], e.z + d[2]
			-- sub_0203C9D4 looks past exactly one TABLE (80), in any facing direction.
			-- The PC tile (83) instead runs its script only when the player faces north.
			-- Both the filter and the route must aim at the square where interaction works.
			if e.actor and behavior_at(fs, nx, nz, cache) == 0x80 then
				nx, nz = nx + d[1], nz + d[2]
			end
			if not e.pc or dir == 1 then
				local w = walk_at(fs, nx, nz, cache)
				if w == nil then certain = false
				elseif w and not occ[tkey(nx, nz)] then
					local same_floor = true
					if actor_y then
						-- sub_0203C9B0 compares sub_020630DC for both objects: signed pos.y
						-- at +74, arithmetic shift by 3, then C division by FX32_ONE.
						local y = terrain.height(fs, nx, nz, actor_y, hcache)
						if y == nil then certain, same_floor = false, discovery and true or false
						else same_floor = math.modf((y // 8) / 4096) == math.modf((actor_y // 8) / 4096) end
					end
					if same_floor then out[#out + 1] = { nx, nz } end
				end
			end
		end
		table.sort(out, function(a, b)                        -- nearest first, with a total order so
			local da = math.abs(a[1] - px) + math.abs(a[2] - pz)   -- the choice cannot wobble
			local db = math.abs(b[1] - px) + math.abs(b[2] - pz)
			if da ~= db then return da < db end
			if a[1] ~= b[1] then return a[1] < b[1] end
			return a[2] < b[2]
		end)
		return out, certain
	end

	-- ── THE ROUTE, AND FOLLOWING IT ─────────────────────────────────────────────────────────────
	--
	-- ⭐ THE WORDS ARE BLACK AND WHITE'S, TO THE LETTER. "To <name>. 3 up", then "5 right" as each
	-- corner is reached, "Recalculating. …" when the plan changes under you, "Arrived at <name>" at the
	-- end. Ola has walked hundreds of these; the tool must not develop a Gen IV accent.
	-- ⚠ AND THE TURN WORDS ARE UP/DOWN/LEFT/RIGHT, NOT COMPASS POINTS — deliberately different from
	-- the bearings the nav list speaks. The list answers "where is it" (3 north, 2 east); the route
	-- answers "which way do I press now". Mixing the two vocabularies is how a turn instruction starts
	-- sounding like a description.
	local PFWORD = { [0] = "arriba", [1] = "abajo", [2] = "izquierda", [3] = "derecha" }

	-- Build a route: the tile sequence, plus the spoken instruction that begins at each corner.
	-- Returns nil when there is no way through.
	local function pf_build(fs, sx, sz, gx, gz, name, occ, cache, destination)
		cache = cache or {}
		local scope = terrain.route_scope(fs,sx,sz,gx,gz,destination,cache)
		if not scope then return nil,"terrain" end
		local moves, why, reached = pf_astar(fs, sx, sz, gx, gz, occ, cache, scope)
		if not moves then return nil, why, reached end
		-- `tiles` holds one entry per ACTION — where the player stands before each press and after
		-- the last — while `transit` holds the tiles a jump passes THROUGH. The engine writes the
		-- trigger coordinate the instant the jump begins (0x02065E42), so without transit the
		-- follower would see a tile that is not on the route and re-plan in mid-air.
		local sy = terrain.seed(fs, sx, sz, {})
		if sy == nil then return nil, "terrain" end
		local motion = terrain.motion(fs,{})
		if motion == nil then return nil,"terrain" end
		local tiles, transit, crossings, x, z = { { sx, sz, sy, motion } }, {}, {}, sx, sz
		for n, m in ipairs(moves) do
			crossings[n] = {}
			for hop = 1, m[2] do
				local d = STEPD[m[4] and m[4][hop] or m[1]]
				x, z = x + d[1], z + d[2]
				if hop < m[2] then
					local key = tkey(x, z)
					transit[key], crossings[n][key] = true, true
				end
			end
			tiles[#tiles + 1] = { x, z, m[3], m[5] }
		end
		-- Runs of the same direction collapse into one instruction, which is the whole point: "5 up"
		-- rather than five separate nudges. Indexed by the tile the run STARTS at, so the follower can
		-- speak it at exactly the moment he arrives there.
		-- ⚠ THE COUNT IS PRESSES, NOT TILES. A jump is one press that covers two tiles, so a run of
		-- three actions ending in a hop is "3 up" and not "4 up" — the number has to be what the
		-- player does, not what the ground does.
		local segs, i = {}, 1
		while i <= #moves do
			if moves[i][4] then
				local path, parts, n = moves[i][4], {}, 1
				while n <= #path do
					local last = n + 1
					while last <= #path and path[last] == path[n] do last = last + 1 end
					parts[#parts+1] = PFWORD[path[n]] .. " durante " .. (last-n) .. " casillas"
					n = last
				end
				segs[i] = "Cuesta en bici. Mantén " .. table.concat(parts, ", luego ") .. " sin parar"
				i = i + 1
			else
			local j = i
			while j <= #moves and not moves[j][4] and moves[j][1] == moves[i][1] do j = j + 1 end
			segs[i] = (j - i) .. " " .. PFWORD[moves[i][1]]
			i = j
			end
		end
		local at_tile = {}
		for n, tile in ipairs(tiles) do
			local key = tkey(tile[1], tile[2])
			at_tile[key] = at_tile[key] or {}
			at_tile[key][#at_tile[key] + 1] = n
		end
		return { name = name, gx = gx, gz = gz, tiles = tiles, at_tile = at_tile,
		         transit = transit, crossings = crossings, segs = segs,
		         idx = 1, total = #moves, partial = why == "partial" }
	end

	-- A frontier must lie on a possible route, not merely closer by Manhattan
	-- distance. Streets can require a detour away from an unloaded destination.
	-- Cartridge geometry chooses the corridor; only its verified live prefix is spoken.
	local function pf_loaded_prefix(fs, px, pz, entry, occ, cache)
		if cache.hm_offline or entry.connection then return nil end
		local discovery = terrain.hm_discovery(fs,px,pz,cache)
		if not discovery then return nil end
		local candidates = goals_for(fs,entry,occ,px,pz,discovery)
		for _,goal in ipairs(candidates) do
			local scope = terrain.route_scope(fs,px,pz,goal[1],goal[2],nil,discovery)
			local moves = scope and pf_astar(fs,px,pz,goal[1],goal[2],occ,discovery,scope)
			if moves then
				local x,z = px,pz
				for _,move in ipairs(moves) do
					local before_x,before_z = x,z
					for hop=1,move[2] do
						local d = STEPD[move[4] and move[4][hop] or move[1]]
						x,z = x+d[1],z+d[2]
						if terrain.unloaded(fs,x,z,cache) then
							-- A ledge/slope is one action: never stop inside its transit.
							if before_x == px and before_z == pz then return nil end
							local r = pf_build(fs,px,pz,before_x,before_z,entry.label or entry.name,occ,cache)
							if r and not r.partial then
								r.key,r.entry,r.partial = entry.key,entry,true
								r.tx,r.tz = goal[3] or entry.x,goal[4] or entry.z
								return r
							end
							return nil
						end
					end
				end
			end
		end
		return nil
	end

	local function pf_plan_direct(fs, px, pz, entry, occ, cache)
		cache = cache or {}
		local distant = not cache.hm_offline and terrain.unloaded(fs,entry.x,entry.z,cache)
		if distant then
			local prefix = pf_loaded_prefix(fs,px,pz,entry,occ,cache)
			if prefix then return prefix end
		end
		local cands, certain = goals_for(fs, entry, occ, px, pz, cache)
		-- A distant door or interaction target has no verified endpoint yet.
		-- Approach its loaded frontier, then resolve the actual endpoint again.
		if not entry.warps and not entry.spots and not entry.surf and not entry.climb and not entry.waterfall and not entry.honey and not cache.hm_offline and terrain.unloaded(fs, entry.x, entry.z, cache) then
			cands = { { entry.x, entry.z } }
		end
		local partial, why, reached
		for _, c in ipairs(cands) do
			local key = tkey(c[1], c[2])
			-- A scoped search excludes other foreign endpoints by policy. Only
			-- their source-side tiles can share its exhausted reachability proof.
			local d = entry.connection and STEPD[entry.direction]
			local reached_key = d and tkey(c[1]-d[1],c[2]-d[2]) or key
			local unloaded = terrain.unloaded(fs, c[1], c[2], cache)
			-- An unloaded endpoint can still yield a useful loaded prefix.
			-- After finding one, other unloaded endpoints cannot improve it to a
			-- complete route. Still try loaded alternatives before choosing the prefix.
			if not (partial and unloaded) and (not reached or reached[reached_key] or unloaded)
				and not (cache.reach and cache.reach.complete and not cache.reach.seen[key]) then
				local r, reason, known = pf_build(fs, px, pz, c[1], c[2], entry.label or entry.name, occ, cache, entry.connection and entry.dz or nil)
				reached = known or reached
				if r then
					r.key, r.tx, r.tz, r.entry = entry.key, entry.x, entry.z, entry
					if entry.warps or entry.spots or entry.surf or entry.climb or entry.waterfall or entry.honey or entry.door_bg then r.tx, r.tz = c[3] or c[1], c[4] or c[2] end
					if entry.honey and honey.present(fs, entry, cache) ~= true then r.partial = true end
					if not r.partial then return r end
					partial = partial or r
				end
				if reason == "limit" or reason == "terrain" then why = reason end
			end
		end
		-- Also when no approach could be read at all: a target on the cell line can have its approach
		-- tiles in the cell that is not loaded (Mt. Coronet B1F, the item at (29,32) from the south).
		if not partial and not distant and (why == "terrain" or (why == nil and not certain)) then
			local prefix = pf_loaded_prefix(fs,px,pz,entry,occ,cache)
			if prefix then return prefix end
		end
		return partial, why or (certain and "exhausted" or "terrain")
	end

	-- ── WARP TILES AND WARP PANELS ──────────────────────────────────────────────────────────────
	-- Which tiles move the player, from the game's own code (src/overlay005/field_control.c).
	-- A warp needs a warp event on the tile (Field_MapConnection) AND a behavior that fires it:
	--   * on the step that ENDS on it (Field_CheckTransition, run by Field_ProcessStep): entrance
	--     north 0x64, warp north 0x6E, warp panel 0x67, escalator 0x6B, escalator flip-face 0x6A;
	--   * on a press toward a solid door ahead, or out of the tile the player stands on in the
	--     tile's own direction (Field_CheckMapTransition): door 0x69, entrance and warp east, west
	--     and south, stairs east and west.
	-- So a warp event on any other open tile never fires: it is only where a warp from elsewhere
	-- puts the player (Galactic HQ 1F (41,14), the Elite Four rooms, the Battle Frontier). And a
	-- route must never cross a step-triggered tile it is not going to: the step that ends there
	-- teleports the player off the route. The behaviors are read out of the predicates
	-- (`cmp r0,#behavior ; bne +2 ; movs r0,#1 ; bx lr`); any other shape answers nil.
	-- `face` is the press that takes a press-triggered open tile, by behavior, and `sideways` the
	-- step-triggered tiles that fire only on an east or west step. Both are aligned with the predicate
	-- lists in A, from the consumers (retail ov5, byte-identical in the follower patch):
	-- Field_CheckMapTransition compares the pressed direction after each predicate — entrance/warp
	-- east `cmp r0,#3` 021D25E6, west `#2` 021D2608, south `#1` 021D262A, stairs east `#3` 021D2642,
	-- stairs west `#2` 021D265A (DIR_NORTH 0, SOUTH 1, WEST 2, EAST 3, the PFWORD indices); and
	-- Field_CheckTransition takes the escalators only when the player faces west or east.
	function terrain.warp_rules(cache)
		if cache and cache.warp_rules ~= nil then return cache.warp_rules or nil end
		local WARP_PRESS_FACE = { false, 3, 2, 1, 3, 2, 1, 3, 2 }
		local WARP_STEP_SIDEWAYS = { false, false, false, true, true }
		local rules = { step = {}, trigger = {}, face = {}, sideways = {} }
		local function read(list, into, by_index, values)
			for i, f in ipairs(list) do
				if (u16(f) & 0xFF00) ~= 0x2800 or u16(f + 2) ~= 0xD101 or u16(f + 4) ~= 0x2001 or u16(f + 6) ~= 0x4770 then
					dbg(string.format("warps: tile predicate at %08X has an unknown shape", f)); return false
				end
				local b = u16(f) & 0xFF
				if into then into[b] = true end
				if values[i] then by_index[b] = values[i] end
				rules.trigger[b] = true
			end
			return true
		end
		local ok = #A.WarpStepPredicates == #WARP_STEP_SIDEWAYS and #A.WarpPressPredicates == #WARP_PRESS_FACE
			and read(A.WarpStepPredicates, rules.step, rules.sideways, WARP_STEP_SIDEWAYS)
			and read(A.WarpPressPredicates, nil, rules.face, WARP_PRESS_FACE)
		local panel = A.TileBehaviorIsWarpPanel
		if ok then rules.panel = u16(panel) & 0xFF; ok = rules.step[rules.panel] == true end
		if cache then cache.warp_rules = ok and rules or false end
		return ok and rules or nil
	end
	-- Is this warp event offered in the list? Not an open tile whose behavior never fires a warp,
	-- which is only where a warp from elsewhere lands; nor a warp panel to elsewhere in this map,
	-- which the router steps on for the player (terrain.panel_search). Unknown answers yes.
	function terrain.offered_warp(fs, x, z, dest, cache)
		local rules = terrain.warp_rules(cache)
		local a = rules and terrain.discovery_attrs(fs, x, z, cache)
		if not a then return true end
		local b = a & ATTR_BEHAVIOR
		if (a & ATTR_COLLIDE) == 0 and not rules.trigger[b] then return false end
		return not (b == rules.panel and dest == map_id(fs))
	end
	-- The map's warp events as the parser left them: { x, z, dest header, dest warp, index }.
	function terrain.warp_events(fs, cache)
		if cache.warp_events ~= nil then return cache.warp_events or nil end
		cache.warp_events = false
		local mhd = u32(fs + FS_MHD)
		if not inram(mhd) then return nil end
		local n, p = u32(mhd + MHD_WARPN), u32(mhd + MHD_WARPP)
		if n > 0 and not (inram(p) and p >= mhd + MHD_BUF and p + n * WARP_STRIDE <= mhd + MHD_BUF + MHD_BUFLEN) then
			return nil
		end
		local out = {}
		for i = 0, n - 1 do
			local e = p + i * WARP_STRIDE
			out[#out + 1] = { u16(e), u16(e + 2), u16(e + 4), u16(e + 6), i }
		end
		cache.warp_events = out
		return out
	end
	-- tkey -> warp event, for every tile a step must not end on unless it is the goal. The native
	-- lookup returns the FIRST event at a coordinate. Unknown rules or events: no traps (as before).
	function terrain.traps(fs, cache)
		if cache.traps then return cache.traps end
		local traps, rules, events = {}, terrain.warp_rules(cache), terrain.warp_events(fs, cache)
		if rules and events then
			for _, w in ipairs(events) do
				local k = tkey(w[1], w[2])
				if traps[k] == nil then
					local a = terrain.discovery_attrs(fs, w[1], w[2], cache)
					traps[k] = (a ~= nil and rules.step[a & ATTR_BEHAVIOR] == true) and w or false
				end
			end
			for k, v in pairs(traps) do if not v then traps[k] = nil end end
		end
		-- An armed platform lift is a step-triggered tile too: the step that ends on it rides.
		local lift = terrain.lift(fs, cache)
		if lift then traps[lift.key] = traps[lift.key] or { lift.x, lift.z } end
		cache.traps = traps
		return traps
	end
	-- Warp panels that lead elsewhere in THIS map (the Galactic HQ's floors): { x, z, lx, lz }, the
	-- landing being the destination warp's own tile (Location_Set with that event's x/z).
	function terrain.panels(fs, cache)
		if cache.panels then return cache.panels end
		local out, rules, events, here = {}, terrain.warp_rules(cache), terrain.warp_events(fs, cache), map_id(fs)
		if rules and events and here then
			local seen = {}
			for _, w in ipairs(events) do
				local k = tkey(w[1], w[2])
				if not seen[k] then
					seen[k] = true
					local a = terrain.discovery_attrs(fs, w[1], w[2], cache)
					local land = events[w[4] + 1]
					if w[3] == here and land and a and (a & ATTR_BEHAVIOR) == rules.panel then
						out[#out + 1] = { x = w[1], z = w[2], lx = land[1], lz = land[2] }
					end
				end
			end
		end
		-- A platform lift lands on its own trigger tile, at the plate's other height.
		local lift = terrain.lift(fs, cache)
		if lift then out[#out + 1] = { x = lift.x, z = lift.z, lx = lift.x, lz = lift.z, lift = lift } end
		cache.panels = out
		return out
	end
	-- ── PLATFORM LIFTS: the Pokémon League's elevator halls ─────────────────────────────────────
	-- src/platform_lift.c and the halls' scripts and events. Each hall's OnTransition runs
	-- InitPersistedMapFeaturesForPlatformLift (feature 7, Misc +0x700; +0x704 u16 floorID 0 bottom
	-- 1 top, +0x706 u16 lift id, +0x70C kind 1 League), and PlatformLift_DynamicMapFeaturesInit puts
	-- dynamic plate 0 on the lift (sPerMapPlatformLiftConfiguration[id]: stride 0x18, +0/+4 the two
	-- floor heights, +8/+C the plate's first tile, +0x10 preventGoingDown). Stepping onto the 1x1
	-- coord event on the plate (sub_0203CC14: tile match and var == value; it runs before any warp,
	-- Field_ProcessStep) runs TriggerPlatformLift: the plate and the player rise to the other floor,
	-- and only then does DynamicTerrainHeightManager_SetHeight move the plate (FINISH_MOVING). The
	-- League halls then set the var, so the lift rides once and only up (preventGoingDown).
	-- Only the League's lifts (kind 1) are modelled: Iron Island's coord scripts run other commands
	-- before the lift in the follower patch (scr_seq 327/329/330), and the Champion's room has no
	-- coord event. The League halls' events, scripts, headers and matrix, and this code and table,
	-- are byte-identical in both cartridges (research/re/pt-platform-lift-20261105).
	-- Returns { x, z, key, plates } (the trigger tile, and the dynamic plates as the ride leaves
	-- them), or nil: no armed lift here, or one that cannot be verified (logged once by reason).
	function terrain.lift(fs, cache)
		if cache.lift ~= nil then return cache.lift or nil end
		cache.lift = false
		local function bad(why)
			if terrain.lift_error ~= why then dbg("platform lift: " .. why) end
			terrain.lift_error = why
			return nil
		end
		local f = A.PlatformLiftTrigger
		-- `movs r1,#feature` (PersistedMapFeatures_GetBuffer), `movs r0,#0x18` (the stride), and the
		-- three pool loads of the table: +0x10 preventGoingDown, +4 the top floor, +0 the bottom one.
		if u16(f + 0x0C) >> 8 ~= 0x21 or u16(f + 0x16) ~= 0x2018 or u16(f + 0x1C) ~= 0x4819
			or u16(f + 0x56) ~= 0x480D or u16(f + 0x6E) ~= 0x4809 then
			return bad("lift code identity")
		end
		local feature, base = u16(f + 0x0C) & 0xFF, u32(f + 0x94)
		if u32(f + 0x84) ~= base + 0x10 or u32(f + 0x8C) ~= base + 4 then return bad("lift table literals") end
		if u32(fs + 0xC) ~= u32(A.sSaveDataPtr) then return nil end
		local misc = save_page(SD_MISC, SD_MISC_SIZE, "platform lift")
		if not misc or not inram(misc + 0x70F) then return nil end
		if u32(misc + 0x700) ~= feature then terrain.lift_error = nil; return nil end   -- not a lift hall
		local floor, id, kind = u16(misc + 0x704), u16(misc + 0x706), u32(misc + 0x70C)
		if kind ~= 1 then return nil end
		if floor > 1 or id > 8 then return bad("persisted lift " .. floor .. "/" .. id) end
		local e = base + id * 0x18
		if not inram(e) or not inram(e + 0x17) then return bad("lift table unreadable") end
		local heights, sx, sz = { [0] = s32(e), [1] = s32(e + 4) }, s32(e + 8), s32(e + 0xC)
		if u32(e + 0x10) ~= 0 and floor == 1 then return nil end           -- up, and it stays up
		local plates = terrain.dynamic(fs, cache)
		if not plates then return bad("dynamic plates unreadable") end
		local plate
		for i, p in ipairs(plates) do
			if p[1] == sx and p[2] == sz then
				if plate then return bad("two plates on the lift") end
				plate = i
			end
		end
		if not plate then return bad("no plate on the lift") end
		local pl = plates[plate]
		if pl[5] ~= heights[floor] then return bad("lift moving") end
		-- The trigger: the one armed coord event on the plate (MapHeaderData +0C count, +1C list,
		-- stride 0x10: script, x, z, width, length, y, value, var).
		local mhd = u32(fs + FS_MHD)
		if not inram(mhd) then return bad("map header data") end
		local n, list = u32(mhd + 0x0C), u32(mhd + 0x1C)
		if n > 64 or (n > 0 and not (inram(list) and list >= mhd + MHD_BUF and list + n * 0x10 <= mhd + MHD_BUF + MHD_BUFLEN)) then
			return bad("coord event list")
		end
		local trigger
		for i = 0, n - 1 do
			local c = list + i * 0x10
			local x, z, w, l = u16(c + 2), u16(c + 4), u16(c + 6), u16(c + 8)
			if x < pl[1] + pl[3] and x + w > pl[1] and z < pl[2] + pl[4] and z + l > pl[2] then
				local v = story_var(u16(c + 0x0E))
				if v == nil then return bad("coord event var unreadable") end
				if v == u16(c + 0x0C) then
					if trigger or w ~= 1 or l ~= 1 then return bad("coord events on the lift") end
					trigger = { x = x, z = z }
				end
			end
		end
		if not trigger then return nil end                                -- already ridden
		local after = {}
		for i, p in ipairs(plates) do after[i] = { p[1], p[2], p[3], p[4], i == plate and heights[1 - floor] or p[5] } end
		terrain.lift_error = nil
		cache.lift = { x = trigger.x, z = trigger.z, key = tkey(trigger.x, trigger.z), plates = after }
		return cache.lift
	end
	-- Breadth-first over warp panels: flood from where the player stands, then from each landing a
	-- panel in that flood leads to, fewest panels first. Floods use the whole-area geometry
	-- (terrain.hm_discovery) because a two-cell floor loads only its near cell, and a fresh copy of
	-- the cache each, so no flood's memo stands in for another's start.
	-- Without `entry`: the union of everything reached and whether every flood was complete (the
	-- list). With it: the first panel of the shortest chain that reaches one of the entry's approach
	-- tiles, or nil when none does or no panel is needed. nil also when the map has no such panel.
	function terrain.panel_search(fs, px, pz, occ, cache, entry)
		local panels = terrain.panels(fs, cache)
		if #panels == 0 then return nil end
		local base = terrain.hm_discovery(fs, px, pz, cache) or cache
		local goals
		if entry then
			goals = {}
			for _, c in ipairs(goals_for(fs, entry, occ, px, pz, base, true)) do
				local x, z = c[1], c[2]
				if entry.connection then x, z = x - STEPD[entry.direction][1], z - STEPD[entry.direction][2] end
				goals[tkey(x, z)] = true
			end
		end
		local union, complete = {}, true
		local queue, head, visited = { { x = px, z = pz } }, 1, { [tkey(px, pz)] = true }
		while head <= #queue and head <= 32 do
			local node = queue[head]; head = head + 1
			local c = {}
			for k, v in pairs(base) do if k ~= "reach" and k ~= "hm_reach" then c[k] = v end end
			-- A lift's landing: the world as the ride leaves it, the player on the plate.
			if node.lift then
				c.height_dynamic, c.height_tiles, c.ride = node.lift.plates, nil, { x = node.x, z = node.z }
			end
			local seen, ok = reach_from(fs, node.x, node.z, occ, c)
			if not ok then complete = false end
			for k in pairs(seen) do union[k] = true end
			if goals then
				-- Reached from where the player stands: no panel is needed, so none is offered.
				for k in pairs(goals) do if seen[k] then return node.first end end
			end
			for _, p in ipairs(panels) do
				-- A lift lands where it starts, so it is visited as itself, not by its landing tile.
				local lk = p.lift or tkey(p.lx, p.lz)
				-- The panel under a landing's own feet only leads back where that landing came from.
				-- Under the player's feet it is a real way out, taken by stepping off and back on.
				local back = head > 2 and p.x == node.x and p.z == node.z
				if seen[tkey(p.x, p.z)] and not visited[lk] and not back then
					visited[lk] = true
					queue[#queue + 1] = { x = p.lx, z = p.lz, first = node.first or p, lift = p.lift }
				end
			end
		end
		if goals then return nil end
		return union, complete and head > #queue
	end

	-- The route's continuation across a warp: the warp reloads the map, and every map object is
	-- created again, possibly in another slot of the manager. So a person or item is remembered by
	-- its local id and map (MapObject +0x08/+0x0C), not by address, and found again on landing.
	function terrain.panel_intent(fs, r)
		local e = r.entry
		local intent = { entry = e, fs = fs, panel = { x = r.panel.x, z = r.panel.z } }
		if e.actor then intent.localid, intent.mapid = u32(e.actor + MO_LOCALID), u32(e.actor + MO_MAPID) end
		return intent
	end
	-- The intent's entry in the reloaded map, or nil when its object is no longer there.
	function terrain.panel_entry(fs, intent)
		local e = intent.entry
		if not e.actor then return e end
		local mm = u32(fs + FS_OBJMAN)
		if not inram(mm) or u32(mm + MOM_FS) ~= fs or s32(mm + MOM_MAX) ~= MOM_EXPECT then
			dbg("warp panel: object manager unreadable"); return nil
		end
		local arr = u32(mm + MOM_ARRAY)
		if not (inram(arr) and inram(arr + MOM_EXPECT * MO_STRIDE - 1)) then dbg("warp panel: object array unreadable"); return nil end
		for i = 0, MOM_EXPECT - 1 do
			local o = arr + i * MO_STRIDE
			local st = u32(o + MO_STATUS)
			if (st & MO_INUSE) ~= 0 and (st & MO_HIDDEN) == 0 and (st & MO_CLONE) == 0
				and u32(o + MO_LOCALID) == intent.localid and u32(o + MO_MAPID) == intent.mapid then
				local copy = {}
				for k, v in pairs(e) do copy[k] = v end
				copy.actor, copy.key, copy.x, copy.z = o, "O" .. o, s32(o + MO_X), s32(o + MO_Z)
				if sel_key == e.key then sel_key = copy.key end
				return copy
			end
		end
		dbg("warp panel: the target object is gone")
		return nil
	end

	-- ── VEILSTONE GYM: the next bag to kick on the way to a target ─────────────────────────────
	-- The slide is VeilstoneGym_GetTileFlags (0224BA0C) / CalculateDistanceBagWillTravel (0224BAA0)
	-- run forward: behaviors 2/3/5 refuse an axis or west, 4 is a stop the bag can leave again, a 1
	-- ahead stops it, and a standing stack ahead stops it AND is toppled (MovePunchingBag 0224BCA8).
	-- Neither the player nor another bag enters that test, exactly as in the native code.
	-- ⭐ THE SEARCH IS OVER WHOLE PUZZLE STATES — every bag, every stack, and which area the player
	-- can walk to — because one kick can only be judged by the kicks it makes possible. Areas are
	-- walked as a graph: tiles no bag or stack can ever occupy are merged into components once,
	-- and only the possible bag tiles and stack tiles stay single nodes, so each state costs about
	-- seventy node visits instead of five hundred tile visits.
	-- Best-first on kicks + 1.5 * standing stacks. That weight is a tie-break toward toppling, not an
	-- optimality proof; offline, it matched breadth-first kick counts on every sampled state
	-- (research/re/pt-veilstone-gym-20261030). A bounded state count keeps a hopeless puzzle (never
	-- observed) to one short pause and a "Can't reach".
	-- Occupancy without the bags and stacks: what the puzzle itself can clear. The list offers
	-- everything behind them, and the planner moves them itself. Takes a validated snapshot; a caller
	-- without one cannot tell the puzzle from a wall and must not judge reachability across it.
	function veilstone.relax(snap, occ)
		local own, relaxed = {}, {}
		for _, b in ipairs(snap.bags) do own[tkey(b.x, b.z)] = true end
		for _, s in ipairs(snap.stacks) do own[tkey(s.x, s.z)] = true end
		for k in pairs(occ) do if not own[k] then relaxed[k] = true end end
		return relaxed
	end
	local VEIL_LIMIT, VEIL_WEIGHT = 9000, 1.5
	local VEIL_STEP = { [0] = -32, 32, -1, 1 }
	function veilstone.steps(fs, cache)
		if cache.veil_steps then return cache.veil_steps end
		local steps = {}
		for i = 0, 1023 do
			local x, z = i % 32, i // 32
			if tile_walk(fs, x, z, cache) then
				for d = 0, 3 do
					local nx, nz = x + STEPD[d][1], z + STEPD[d][2]
					-- The gym is one 32x32 map; nothing beyond it belongs to the puzzle. An unknown step
					-- (walkable attributes with no floor, outside the gym walls) is impassable, as in A*.
					if nx >= 0 and nx <= 31 and nz >= 0 and nz <= 31 and step_ok(fs, x, z, d, cache) then
						steps[i*4+d] = true
					end
				end
			end
		end
		cache.veil_steps = steps
		return steps
	end
	function veilstone.solve(beh, steps, bags, stacks, fixed, start, goals)
		local nb, ns = #bags, #stacks
		local stackat = {}
		for k, s in ipairs(stacks) do stackat[s] = k end
		local function flags(mask, i, d)
			local f, b = 0, beh[i]
			if b == 4 then f = 4
			elseif (b == 2 and d < 2) or (b == 3 and d >= 2) or (b == 5 and d == 2) then f = 1 end
			local n = i + VEIL_STEP[d]
			if beh[n] == 1 then f = f | 1 end
			local s = stackat[n]
			if s and mask & (1 << (s-1)) ~= 0 then f = f | 2 end
			return f
		end
		local function slide(mask, i, d)
			local f = flags(mask, i, d)
			if f ~= 0 and f ~= 4 then return nil end
			repeat i = i + VEIL_STEP[d]; f = flags(mask, i, d) until f ~= 0
			return i, (f & 2) ~= 0 and stackat[i+VEIL_STEP[d]] or nil
		end
		-- Every tile a bag could ever stop on, whichever stacks stand: the stop with none standing,
		-- or any tile before it with a stack ahead. A superset is harmless; a missing tile is not.
		local dyn, all = {}, (1 << ns) - 1
		for _, s in ipairs(stacks) do dyn[s] = true end
		for k = 1, nb do
			local todo, seen = { bags[k] }, { [bags[k]] = true }
			while #todo > 0 do
				local i = table.remove(todo)
				dyn[i] = true
				for d = 0, 3 do
					local f, at = flags(0, i, d), i
					if f == 0 or f == 4 then
						repeat
							at = at + VEIL_STEP[d]
							f = flags(0, at, d)
							if (f ~= 0 or stackat[at+VEIL_STEP[d]]) and not seen[at] then
								seen[at] = true; todo[#todo+1] = at
							end
						until f ~= 0
					end
				end
			end
		end
		local node, n = {}, 0
		for i = 0, 1023 do
			if not node[i] and not fixed[i] and not dyn[i] then
				local open = false
				for d = 0, 3 do open = open or steps[i*4+d] == true end
				if open then
					n = n + 1; node[i] = n
					local q, h = { i }, 1
					while h <= #q do
						local c = q[h]; h = h + 1
						for d = 0, 3 do
							local j = c + VEIL_STEP[d]
							-- Merge only two-way edges; a one-way edge stays an edge between nodes.
							if steps[c*4+d] and steps[j*4+(d ~ 1)] and not node[j] and not fixed[j] and not dyn[j] then
								node[j] = n; q[#q+1] = j
							end
						end
					end
				end
			end
		end
		for i in pairs(dyn) do if not fixed[i] then n = n + 1; node[i] = n end end
		local adj, edge = {}, {}
		for k = 1, n do adj[k] = {} end
		for i, a in pairs(node) do
			for d = 0, 3 do
				if steps[i*4+d] then
					local b = node[i+VEIL_STEP[d]]
					if b and b ~= a and not edge[a*4096+b] then
						edge[a*4096+b] = true; adj[a][#adj[a]+1] = b
					end
				end
			end
		end
		local goal = {}
		for _, g in ipairs(goals) do if node[g] then goal[node[g]] = true end end
		if not node[start] then return nil, "terrain" end
		local block, seen, q, gen = {}, {}, {}, 0
		for k = 1, n do block[k], seen[k] = 0, 0 end
		local function flood(pos, mask, p)
			gen = gen + 1
			for k = 1, nb do if node[pos[k]] then block[node[pos[k]]] = gen end end
			for k = 1, ns do
				if mask & (1 << (k-1)) ~= 0 and node[stacks[k]] then block[node[stacks[k]]] = gen end
			end
			local s = node[p]
			seen[s], q[1] = gen, s
			local h, t, rep, reached = 1, 1, s, false
			while h <= t do
				local c = q[h]; h = h + 1
				if c < rep then rep = c end
				if goal[c] then reached = true end
				local a = adj[c]
				for x = 1, #a do
					local m = a[x]
					if seen[m] ~= gen and block[m] ~= gen then seen[m] = gen; t = t + 1; q[t] = m end
				end
			end
			return rep, reached
		end
		local function standing(mask)
			local c = 0
			while mask > 0 do c = c + (mask & 1); mask = mask >> 1 end
			return c
		end
		local pos0, mask0 = { table.unpack(bags) }, all
		local rep, reached = flood(pos0, mask0, start)
		if reached then return {} end
		local states = { { pos = pos0, mask = mask0, p = start, depth = 0 } }
		local known = { [table.concat(pos0, ",") .. "|" .. mask0 .. "|" .. rep] = true }
		local heap = {}
		local function push(id, pr)
			heap[#heap+1] = { pr, id }
			local i = #heap
			while i > 1 do
				local p = i // 2
				if heap[p][1] <= heap[i][1] then break end
				heap[p], heap[i] = heap[i], heap[p]; i = p
			end
		end
		local function pop()
			local top, last = heap[1], table.remove(heap)
			if #heap > 0 then
				heap[1] = last
				local i = 1
				while true do
					local l, r, m = 2*i, 2*i+1, i
					if l <= #heap and heap[l][1] < heap[m][1] then m = l end
					if r <= #heap and heap[r][1] < heap[m][1] then m = r end
					if m == i then break end
					heap[m], heap[i] = heap[i], heap[m]; i = m
				end
			end
			return top[2]
		end
		push(1, VEIL_WEIGHT * standing(mask0))
		while #heap > 0 do
			if #states > VEIL_LIMIT then return nil, "limit" end
			local id = pop()
			local st = states[id]
			flood(st.pos, st.mask, st.p)
			local g, moves = gen, {}
			for k = 1, nb do
				local b = st.pos[k]
				for d = 0, 3 do
					local stand = b - VEIL_STEP[d]
					local sn = node[stand]
					-- The kick is a held direction toward the bag from any reachable tile beside it;
					-- HitPunchingBag runs before the collision test, so no step permission applies.
					if sn and seen[sn] == g then
						local to, top = slide(st.mask, b, d)
						if to then moves[#moves+1] = { k, d, stand, to, top } end
					end
				end
			end
			for _, m in ipairs(moves) do
				local k, d, stand, to, top = m[1], m[2], m[3], m[4], m[5]
				local pos = { table.unpack(st.pos) }
				pos[k] = to
				local mask = top and (st.mask & ~(1 << (top-1))) or st.mask
				local r2, g2 = flood(pos, mask, stand)
				local key = table.concat(pos, ",") .. "|" .. mask .. "|" .. r2
				if not known[key] then
					known[key] = true
					states[#states+1] = { pos = pos, mask = mask, p = stand, depth = st.depth + 1,
						parent = id, move = { bag = k, dir = d, stand = stand } }
					if g2 then
						local plan, at = {}, #states
						while states[at].parent do table.insert(plan, 1, states[at].move); at = states[at].parent end
						return plan
					end
					push(#states, st.depth + 1 + VEIL_WEIGHT * standing(mask))
				end
			end
		end
		return nil, "exhausted"
	end
	-- The first kick of a plan to `entry`, or nil and a reason. {} would mean no kick is needed.
	function veilstone.next_kick(fs, px, pz, entry, occ, cache)
		local snap = veilstone.snapshot(fs)
		if not snap then return nil, "terrain" end
		if px < 0 or px > 31 or pz < 0 or pz > 31 then return nil, "terrain" end
		local steps = veilstone.steps(fs, cache)
		local bags, stacks, fixed = {}, {}, {}
		for _, b in ipairs(snap.bags) do bags[#bags+1] = b.x + b.z*32 end
		for _, s in ipairs(snap.stacks) do stacks[#stacks+1] = s.x + s.z*32 end
		local relaxed = veilstone.relax(snap, occ)
		for i = 0, 1023 do if relaxed[tkey(i % 32, i // 32)] then fixed[i] = true end end
		local goals = {}
		for _, c in ipairs(goals_for(fs, entry, relaxed, px, pz, cache)) do
			if c[1] >= 0 and c[1] <= 31 and c[2] >= 0 and c[2] <= 31 then goals[#goals+1] = c[1] + c[2]*32 end
		end
		if #goals == 0 then return nil, "exhausted" end
		local plan, why = veilstone.solve(snap.beh, steps, bags, stacks, fixed, px + pz*32, goals)
		if not plan then dbg("Veilstone Gym: no plan (" .. tostring(why) .. ")"); return nil, why end
		local first = plan[1]
		if not first then return {} end
		local bag = snap.bags[first.bag]
		return { x = first.stand % 32, z = first.stand // 32, dir = first.dir,
			bx = bag.x, bz = bag.z, sig = snap.sig, kicks = #plan }
	end

	-- ── CANALAVE GYM: four floors and twenty-four moving platforms ───────────────────────────────
	-- src/overlay008/gym_features.c. Two native rules, both modelled here from the running cartridge:
	--  * Walking: CanalaveGym_DynamicMapFeaturesCheckCollision (ov8 0224AAFC) REPLACES the land
	--    collision with sCanalaveGymCollisionMaps[floor][x + z*32], floor = (height >> 16) / 10.
	--    The four floors are BDHC planes 0, 10, 20 and 30 tiles up, so step_ok's height rule keeps a
	--    walk on one floor; step_ok asks canalave_walk for the collision (see there).
	--  * Riding: every completed step runs CanalaveGym_CheckIfPlayerOnPlatform (Field_ProcessStep):
	--    standing on the square a platform occupies on your floor moves it to its other end with you
	--    on it and toggles its bit in the persisted platformStates (Misc +0x704; feature id 3 at
	--    +0x700). sCanalavePlatformPaths (ov8 0224CB68, stride 0x10): +4 position A {x, y, z},
	--    +7 position B, +A floor A, +B floor B; y is in tiles (0/10/20/30).
	-- Objects collide only within two height units (sub_02063F00), so trainers block their own
	-- floor only. Platform rides are field tasks: the router is idle until they finish.
	-- ov8's Canalave code and tables, the gym's land data and events and arm9's start table are
	-- byte-identical in the follower patch (research/re/pt-canalave-gym-20261102).
	terrain.canalave = {}
	do
		local canalave = terrain.canalave
		local FLOOR = 0xA0000              -- ten tiles of fx32 height
		local function bad(why, detail)
			if canalave.error ~= why then dbg("Canalave Gym: "..why..(detail and (" ("..detail..")") or "")) end
			canalave.error = why
			return nil, why
		end
		function canalave.active(fs, cache)
			cache = cache or {}
			if cache.canalave_map == nil then cache.canalave_map = map_id(fs) == 35 end
			return cache.canalave_map
		end
		function canalave.floor(y)
			if y == nil or y < 0 then return nil end
			local f = (y // 0x10000) // 10
			return f <= 3 and f or nil
		end
		-- The static tables, read out of the loaded overlay through the code that consumes them.
		function canalave.data()
			local f = A.CanalaveGymCheckCollision
			-- push {r4-r6,lr}; movs r1,#10 (the floor divisor); lsls r0,r5,#10 (floor stride);
			-- lsls r0,r6,#5 (row stride); ldrb r1,[r5,r4] (the byte the game reads).
			if u16(f) ~= 0xB570 or u16(f + 0x0C) ~= 0x210A or u16(f + 0x22) ~= 0x02A8
				or u16(f + 0x26) ~= 0x0170 or u16(f + 0x36) ~= 0x5D29 then
				return bad("collision code identity", string.format("%04X", u16(f)))
			end
			local coll, paths = u32(A.CanalaveGymCollisionLiteral), u32(A.CanalaveGymPathsLiteral)
			local saved = canalave.saved_data
			if saved and saved.coll == coll and saved.paths == paths then return saved end
			if not inram(coll) or not inram(coll + 4095) or not inram(paths) or not inram(paths + 24 * 16 - 1) then
				return bad("tables unreadable")
			end
			local out = { coll = coll, paths = paths, map = {}, platforms = {} }
			for fl = 0, 3 do
				local row = {}
				for i = 0, 1023 do row[i] = u8(coll + fl * 1024 + i) end
				out.map[fl] = row
			end
			for i = 0, 23 do
				local p = paths + i * 16
				local a = { u8(p + 4), u8(p + 5), u8(p + 6) }
				local b = { u8(p + 7), u8(p + 8), u8(p + 9) }
				local fa, fb = u8(p + 10), u8(p + 11)
				if fa > 3 or fb > 3 or a[2] ~= fa * 10 or b[2] ~= fb * 10 or a[1] > 31 or a[3] > 31
					or b[1] > 31 or b[3] > 31 or out.map[fa][a[1] + a[3] * 32] ~= 0 or out.map[fb][b[1] + b[3] * 32] ~= 0 then
					return bad("platform table", tostring(i))
				end
				out.platforms[i] = { a = a, b = b, fa = fa, fb = fb }
			end
			canalave.saved_data = out
			return out
		end
		-- True/false for the gym's own collision at a tile and height, nil when unknown.
		function canalave.walk(x, z, y, cache)
			local d = cache and cache.canalave_data
			if d == nil then
				d = canalave.data() or false
				if cache then cache.canalave_data = d end
			end
			local f = canalave.floor(y)
			if not d or not f then return nil end
			if x < 0 or z < 0 or x > 31 or z > 31 then return false end
			return d.map[f][x + z * 32] == 0
		end
		-- The live puzzle: { mask, floor, data, at = { [floor] = { [tile key] = platform } }, sig }.
		function canalave.snapshot(fs, cache)
			cache = cache or {}
			if not canalave.active(fs, cache) then return nil, "inactive" end
			if u32(fs + 0xC) ~= u32(A.sSaveDataPtr) then return bad("save owner") end
			local misc = save_page(10, 0x794, "Canalave Gym")
			if not misc or not inram(misc + 0x707) then return bad("persisted feature span") end
			if u32(misc + 0x700) ~= 3 then return bad("persisted feature type", tostring(u32(misc + 0x700))) end
			local mask = u32(misc + 0x704)
			if mask >= 1 << 24 then return bad("platform states", string.format("%08X", mask)) end
			local data = canalave.data()
			if not data then return nil, "data" end
			local mo = terrain.player_object(fs, cache)
			local floor = mo and canalave.floor(s32(mo + 0x74))
			if not floor then return bad("player floor") end
			canalave.error = nil
			return { mask = mask, floor = floor, data = data, sig = mask }
		end
		function canalave.platform_at(snap, mask, x, z, f)
			for i = 0, 23 do
				local p = snap.data.platforms[i]
				local pos = (mask >> i) & 1 == 1 and p.b or p.a
				if pos[1] == x and pos[3] == z and pos[2] == f * 10 then return i end
			end
			return nil
		end
		-- Objects on each floor (the game's own height window), as { [floor] = { [tile key] = true } }.
		function canalave.occupancy(fs)
			local occ, mm = { [0] = {}, {}, {}, {} }, u32(fs + FS_OBJMAN)
			local pa = u32(fs + FS_AVATAR)
			local pmo = inram(pa) and u32(pa + PA_OBJ) or nil
			if not inram(mm) or u32(mm + MOM_FS) ~= fs or s32(mm + MOM_MAX) ~= MOM_EXPECT then return nil end
			local arr = u32(mm + MOM_ARRAY)
			if not (inram(arr) and inram(arr + MOM_EXPECT * MO_STRIDE - 1)) then return nil end
			for i = 0, MOM_EXPECT - 1 do
				local o = arr + i * MO_STRIDE
				local st = u32(o + MO_STATUS)
				if o ~= pmo and (st & MO_INUSE) ~= 0 and (st & MO_NOCOLLIDE) == 0 then
					local f = canalave.floor(s32(o + 0x74))
					if f then
						occ[f][tkey(s32(o + MO_X), s32(o + MO_Z))] = true
						occ[f][tkey(s32(o + MO_XPREV), s32(o + MO_ZPREV))] = true
					end
				end
			end
			return occ
		end
		-- Breadth-first over (tile, floor, platform states): fewest steps, rides counted as steps.
		-- `goals` = { [floor] = { [tile key] = true } }, or nil to flood. Returns the state path.
		canalave.LIMIT = 60000
		function canalave.search(snap, sx, sz, occ, goals)
			local d = snap.data
			local start = { sx, sz, snap.floor, snap.mask }
			local function id(s) return ((s[4] * 4 + s[3]) * 32 + s[1]) * 32 + s[2] end
			local prev, states, q, head = {}, {}, { start }, 1
			states[id(start)] = start
			local seen = {}
			while head <= #q do
				if head > canalave.LIMIT then return nil, "limit" end
				local s = q[head]; head = head + 1
				local x, z, f, m = s[1], s[2], s[3], s[4]
				seen[tkey(x, z)] = true
				if goals and goals[f] and goals[f][tkey(x, z)] then
					local path, k = {}, id(s)
					while k do table.insert(path, 1, states[k]); k = prev[k] end
					return path
				end
				for dir = 0, 3 do
					local nx, nz = x + STEPD[dir][1], z + STEPD[dir][2]
					if nx >= 0 and nz >= 0 and nx <= 31 and nz <= 31 and d.map[f][nx + nz * 32] == 0
						and not occ[f][tkey(nx, nz)] then
						local i = canalave.platform_at(snap, m, nx, nz, f)
						local n
						if i then
							local p = d.platforms[i]
							local to = (m >> i) & 1 == 1 and p.a or p.b
							n = { to[1], to[3], to[2] // 10, m ~ (1 << i), nx, nz }
						else n = { nx, nz, f, m } end
						local nid = id(n)
						if not states[nid] then states[nid], prev[nid] = n, id(s); q[#q + 1] = n end
					end
				end
			end
			if goals then return nil, "exhausted" end
			return seen
		end
		-- The next leg toward `entry`: { x, z, key, sig } for a platform to step onto, { last = true,
		-- x, z } when the goal is reachable without riding, or nil and a reason.
		function canalave.next_leg(fs, px, pz, entry, snap, cache)
			local occ = canalave.occupancy(fs)
			if not occ then return nil, "terrain" end
			local gf = 0
			if entry.actor then
				if not inram(entry.actor + 0x78) or (u32(entry.actor) & 0x1000) ~= 0 then return nil, "terrain" end
				gf = canalave.floor(s32(entry.actor + 0x74))
				if not gf then return nil, "terrain" end
			end
			local goals, any = { [gf] = {} }, false
			for _, c in ipairs(goals_for(fs, entry, occ[gf], px, pz, cache)) do
				if snap.data.map[gf][c[1] + c[2] * 32] == 0 then goals[gf][tkey(c[1], c[2])] = c; any = true end
			end
			if not any then return nil, "exhausted" end
			local path, why = canalave.search(snap, px, pz, occ, goals)
			if not path then dbg("Canalave Gym: no plan (" .. tostring(why) .. ")"); return nil, why end
			for i = 2, #path do
				if path[i][5] then
					-- Riding back the platform you are standing on: the leg is the step off (path[i-1]),
					-- and arriving there says which way to step back on.
					if path[i][5] == px and path[i][6] == pz then
						return { x = path[i - 1][1], z = path[i - 1][2], back = { x = px, z = pz },
							key = tkey(path[i - 1][1], path[i - 1][2]), sig = snap.sig, occ = occ }
					end
					return { x = path[i][5], z = path[i][6], key = tkey(path[i][5], path[i][6]), sig = snap.sig, occ = occ }
				end
			end
			local last = path[#path]
			return { last = true, x = last[1], z = last[2], goal = goals[gf][tkey(last[1], last[2])], occ = occ }
		end
		-- Occupancy for a walking leg on the player's floor: people there, and every platform on this
		-- floor except the one the leg ends on (stepping on one rides it).
		-- Is the player on the floor of `e` (its actor's floor; the ground floor for anything else)?
		function canalave.same_floor(fs, e)
			local snap = canalave.snapshot(fs, {})
			if not snap then return false end
			local f = 0
			if e.actor and inram(e.actor + 0x78) then f = canalave.floor(s32(e.actor + 0x74)) end
			return f == snap.floor
		end
		function canalave.blocked(snap, occ, except)
			local out = {}
			for k in pairs(occ[snap.floor]) do out[k] = true end
			for i = 0, 23 do
				local p = snap.data.platforms[i]
				local pos = (snap.mask >> i) & 1 == 1 and p.b or p.a
				local k = tkey(pos[1], pos[3])
				if pos[2] == snap.floor * 10 and k ~= except then out[k] = true end
			end
			return out
		end
	end

	-- ── SNOWPOINT GYM: ice, slopes and snowballs ────────────────────────────────────────────────
	-- src/player_move.c (PlayerAvatar_TileMove_Ice and its helpers) and src/overlay005/ov5_021DFB54.c
	-- (ov5_021E06A8); research/re/report-20261103-platinum-snowpoint-gym.md. One press on ice is one
	-- action, ending where the game brings the player to rest:
	--  * From rest the first step is an ordinary walk. On ice, at each tile centre the game moves on in
	--    the MOVING direction (input is ignored) until a collision stops it; a collision while climbing
	--    sends the player one tile back instead. Reaching a tile that is not ice ends the slide.
	--  * Speed 0-3, cleared when a slide ends: the height a quarter tile ahead
	--    (PlayerAvatar_CheckIceHeightChange) takes one off going up — below 0 the player slides one
	--    tile back — and adds one going down.
	--  * Arriving at a tile mid-slide with speed 1+ deletes a snowball directly ahead
	--    (ov5_021E06A8, from FieldInput_Process before the move is made). Snowballs are event objects
	--    with no flag: they are all back the next time the gym loads.
	-- The search is breadth-first over (rest tile, snowballs broken): fewest presses. Each press is
	-- simulated with step_ok's own collision and height rules plus the objects in their height window
	-- (sub_02063F00). The data and every function used are identical on the follower patch, except
	-- that its PlayerAvatar_SetMovement calls go through a guard applying the same movement unless
	-- the patch's own status bit 30 is set (research/re/pt-snowpoint-gym-20261103).
	terrain.snowpoint = {}
	do
		local snow = terrain.snowpoint
		local W, LIMIT, MO_YTILE = 32, 120000, 0x68      -- MapObject_GetY 02063030 `ldr r0,[r0,#0x68]`
		local function bad(why, detail)
			if snow.error ~= why then dbg("Snowpoint Gym: "..why..(detail and (" ("..detail..")") or "")) end
			snow.error = why
			return nil, why
		end
		-- MapObject_SetY: (pos.y >> 3) / FX32_ONE, an arithmetic shift and then C division.
		local function ytile(y)
			local v = y // 8
			return v >= 0 and v // 0x1000 or -((-v) // 0x1000)
		end
		function snow.active(fs, cache)
			cache = cache or {}
			if cache.snowpoint_map == nil then cache.snowpoint_map = map_id(fs) == 167 end
			return cache.snowpoint_map
		end
		-- The rules' constants, read out of the code that applies them; any other shape fails closed.
		function snow.rules()
			local ice = A.TileBehaviorIsIce
			-- cmp r0,#ice ; bne +2 ; movs r0,#1 ; bx lr
			if (u16(ice) & 0xFF00) ~= 0x2800 or u16(ice + 2) ~= 0xD101 or u16(ice + 4) ~= 0x2001 then
				return bad("ice predicate identity", string.format("%04X", u16(ice)))
			end
			local behavior = u16(ice) & 0xFF
			if behavior ~= B_ICE then return bad("ice behavior", string.format("%02X", behavior)) end
			-- PlayerAvatar_GetTileMovement walks sTileBehaviorCheckTable; ice is entry 0, and its tile
			-- movement indexes sTileMovementFunctions.
			local move = u32(A.TileBehaviorCheckTable + 4)
			if u32(A.TileBehaviorCheckTable) ~= ice + 1 or move > 5
				or u32(A.TileMovementFunctions + move * 4) ~= A.PlayerTileMoveIce + 1 then
				return bad("tile movement table")
			end
			-- TileMove_Ice: push {r3-r7,lr}; `cmp r0,#0` on the collision (+30); `cmp r7,#1` = climbing (+3A).
			local f = A.PlayerTileMoveIce
			if u16(f) ~= 0xB5F8 or u16(f + 0x30) ~= 0x2800 or u16(f + 0x3A) ~= 0x2F01 then
				return bad("ice movement identity")
			end
			-- CheckIceHeightChange: `movs r2,#1 ; lsls r2,r2,#n` is the sample distance; a lower point
			-- ahead answers 2 (`movs r0,#2`, +54) and a higher one 1 (+58).
			local h = A.PlayerIceHeightChange
			local shift = u16(h + 0x2E)
			if u16(h) ~= 0xB570 or u16(h + 0x28) ~= 0x2201 or (shift & 0xF83F) ~= 0x0012
				or u16(h + 0x54) ~= 0x2002 or u16(h + 0x58) ~= 0x2001 then
				return bad("ice slope identity")
			end
			-- UpdateIceSpeedFromHeightChange: 1 (up) `subs r1,#1 ; bpl`, 2 (down) `adds r1,#1`, capped.
			local s = A.PlayerIceSpeed
			local cap = u16(s + 0x1E) & 0xFF
			if u16(s + 0x0C) ~= 0x2C01 or u16(s + 0x10) ~= 0x1E49 or u16(s + 0x12) ~= 0xD507
				or u16(s + 0x18) ~= 0x2C02 or u16(s + 0x1C) ~= 0x1C49 or u16(s + 0x1E) ~= 0x2900 | cap
				or u16(s + 0x20) ~= 0xDD00 or u16(s + 0x22) ~= 0x2100 | cap or cap == 0 then
				return bad("ice speed identity")
			end
			-- ov5_021E06A8: `cmp r0,#n ; bge` on the speed, then `cmp r0,#gfx` on the object ahead.
			local b = A.FieldSnowballBreak
			if u16(b) ~= 0xB510 or (u16(b + 0x0A) & 0xFF00) ~= 0x2800 or u16(b + 0x0C) ~= 0xDA01
				or (u16(b + 0x2C) & 0xFF00) ~= 0x2800 or u16(b + 0x2E) ~= 0xD001 then
				return bad("snowball code identity")
			end
			snow.error = nil
			return { ice = behavior, sample = 1 << ((shift >> 6) & 0x1F), cap = cap,
				breaks = u16(b + 0x0A) & 0xFF, ball = u16(b + 0x2C) & 0xFF }
		end
		-- Rest: PlayerAvatar_GetMoveState (0205EB0C `ldr r0,[r0,#0x14]`) is NONE and AVATAR_MOVE_FORCED,
		-- movementFlag bit 0 (PlayerAvatar_CheckForcedMovement 0205EF58), is clear. Between the steps of
		-- a slide both still say moving. ⛔ AND ON ICE THE IGNORE-TILE FLAG (bit 1) MUST BE SET: a trainer
		-- who sees the player on the first ice tile stops him before TileMove_Ice has run
		-- (PlayerAvatar_ClearMoveState 0205F56C zeroes the move state, the forced bit was never set),
		-- and once the battle is over the game slides him on by itself (independent review, 3 November).
		-- Every slide that ends on ice sets the flag (player_move.c:557, 571, 591).
		function snow.at_rest(fs)
			local pa = u32(fs + FS_AVATAR)
			if not (inram(pa) and inram(pa + 0x17)) then return false end
			local flags = u32(pa)
			if u32(pa + 0x14) ~= 0 or (flags & 1) ~= 0 then return false end
			if (flags & 2) ~= 0 then return true end
			local mo = u32(pa + PA_OBJ)
			if not (inram(mo) and inram(mo + MO_STRIDE - 1)) then return false end
			local a = tile_attrs(fs, s32(mo + MO_X), s32(mo + MO_Z), {})
			return a ~= nil and (a & ATTR_BEHAVIOR) ~= B_ICE
		end
		-- The live puzzle: the player, the snowballs still standing and everyone else.
		function snow.snapshot(fs, rules)
			local q = terrain.query(fs)
			local m = terrain.map(fs, q)
			if not m or m.mw ~= 1 or m.mh ~= 1 then return bad("matrix layout") end
			local pa = u32(fs + FS_AVATAR)
			local pmo = inram(pa) and u32(pa + PA_OBJ) or nil
			if not (pmo and inram(pmo) and inram(pmo + MO_STRIDE - 1)) then return bad("player object") end
			local mm = u32(fs + FS_OBJMAN)
			if not inram(mm) or u32(mm + MOM_FS) ~= fs or s32(mm + MOM_MAX) ~= MOM_EXPECT then
				return bad("object manager")
			end
			local arr = u32(mm + MOM_ARRAY)
			if not (inram(arr) and inram(arr + MOM_EXPECT * MO_STRIDE - 1)) then return bad("object array") end
			local balls, list, people, ids = {}, {}, {}, {}
			for i = 0, MOM_EXPECT - 1 do
				local o = arr + i * MO_STRIDE
				local st = u32(o + MO_STATUS)
				if o ~= pmo and (st & MO_INUSE) ~= 0 and (st & MO_NOCOLLIDE) == 0 then
					local x, z, yt = s32(o + MO_X), s32(o + MO_Z), s32(o + MO_YTILE)
					if u32(o + MO_GFX) == rules.ball then
						list[#list + 1] = { x = x, z = z, yt = yt, key = tkey(x, z) }
					else
						-- sub_02063F00 also tests the tile a person is leaving.
						people[tkey(x, z)] = yt
						people[tkey(s32(o + MO_XPREV), s32(o + MO_ZPREV))] = yt
						ids[#ids + 1] = x .. "," .. z .. "," .. yt
					end
				end
			end
			table.sort(list, function(a, b) return a.key < b.key end)
			for n, ball in ipairs(list) do
				ball.i = n - 1
				balls[ball.key] = ball
				ids[#ids + 1] = "b" .. ball.x .. "," .. ball.z
			end
			if #list > 40 then return bad("snowball count") end
			local px, pz, py = s32(pmo + MO_X), s32(pmo + MO_Z), s32(pmo + 0x74)
			if px < 0 or pz < 0 or px >= W or pz >= W then return bad("player outside the gym") end
			snow.error = nil
			return { px = px, pz = pz, py = py, balls = balls, list = list, people = people,
				sig = q.identity .. "|" .. px .. "," .. pz .. "," .. py .. "|" .. table.concat(ids, ";") }
		end
		-- Geometry lives as long as the terrain does (terrain.query's identity), in tables indexed by
		-- tile i = z * 32 + x and k = i * 4 + direction: ice[i], the surface height y[i], and for each
		-- direction step_ok's answer ok[k] (on a cache of its own, the only one where ice is walkable),
		-- the height reached ny[k] and the slope test sl[k]. One surface per tile: a second height for
		-- a tile fails closed ("layered ice"); this gym has one.
		local function geometry(fs, rules)
			local q = terrain.query(fs)
			local g = q.snowpoint_geo
			if not g or g.ice_id ~= rules.ice or g.sample ~= rules.sample then
				g = { c = { snowpoint_ice = true }, ice = {}, y = {}, done = {}, ok = {}, ny = {}, sl = {},
					ice_id = rules.ice, sample = rules.sample }
				q.snowpoint_geo = g
			end
			g.c.bike_gear, g.c.height_errors, g.c.honey, g.c.motion = nil, nil, nil, nil
			g.unknown, g.layered = false, false
			return g
		end
		-- Fill tile i's tables (its height g.y[i] is already known), with the snapshot's people (pb[k])
		-- and snowballs on the tile ahead (ba[k] index, bw[k] index when within the height window,
		-- else -1) in `t`. Every height a step reaches is recorded for the tile it reaches. False when
		-- the ground cannot be read or a tile turns out to have two surfaces.
		local function fill(g, t, fs, i)
			local y, x, z = g.y[i], i % W, i // W
			if g.ice[i] == nil then
				local a = tile_attrs(fs, x, z, g.c)
				if a == nil then g.unknown = true; return false end
				g.ice[i] = (a & ATTR_BEHAVIOR) == g.ice_id
			end
			if not g.done[i] then
				for d = 0, 3 do
					local k = i * 4 + d
					local ok, ny = step_ok(fs, x, z, d, g.c, y)
					-- PlayerAvatar_CheckIceHeightChange: the surface a quarter tile ahead.
					local h = terrain.height(fs, x, z, y, g.c, STEPD[d][1] * g.sample, STEPD[d][2] * g.sample)
					g.ok[k], g.ny[k], g.sl[k] = ok, ny, h and (h > y and 1 or h < y and -1 or 0)
				end
				g.done[i] = true
			end
			local yt = ytile(y)
			for d = 0, 3 do
				local k = i * 4 + d
				if g.ok[k] then
					local j = i + STEPD[d][2] * W + STEPD[d][1]
					local known = g.y[j]
					if known == nil then g.y[j] = g.ny[k]
					elseif known ~= g.ny[k] then g.layered = true; return false end
				end
				local key = tkey(x + STEPD[d][1], z + STEPD[d][2])
				local p, b = t.people[key], t.balls[key]
				t.pb[k] = p ~= nil and math.abs(p - yt) < 2
				t.ba[k] = b and b.i or -1
				t.bw[k] = (b and math.abs(b.yt - yt) < 2) and b.i or -1
			end
			t.filled[i] = true
			return true
		end
		-- One press from rest at tile i toward d. Returns the tile the game stops the player at, the
		-- snowballs broken after it and the kind of move ("walk", "slide", "back"); nil when the first
		-- step is refused or the way cannot be read. A step is stopped by step_ok, a person in the
		-- height window (pb) or a snowball still standing there (bw); ok[k] == nil is unknown ground.
		local function press(g, t, fs, rules, i, d, mask)
			local filled, ice, ok, sl, pb, bw, ba = t.filled, g.ice, g.ok, g.sl, t.pb, t.bw, t.ba
			if not filled[i] and not fill(g, t, fs, i) then return nil end
			local k = i * 4 + d
			if ok[k] == nil then g.unknown = true; return nil end
			if not ok[k] or pb[k] or (bw[k] >= 0 and (mask >> bw[k]) & 1 == 0) then return nil end
			local step_i = STEPD[d][2] * W + STEPD[d][1]
			i = i + step_i
			if not filled[i] and not fill(g, t, fs, i) then return nil end
			if not ice[i] then return i, mask, "walk" end
			local speed, forced, breaks, cap = 0, false, rules.breaks, rules.cap
			for _ = 1, 4 * W do
				k = i * 4 + d
				if forced and speed >= breaks and ba[k] >= 0 then mask = mask | (1 << ba[k]) end
				if not ice[i] then return i, mask, "slide" end
				local h, go = sl[k], ok[k]
				if h == nil or go == nil then g.unknown = true; return nil end
				local hit = not go or pb[k] or (bw[k] >= 0 and (mask >> bw[k]) & 1 == 0)
				local back = false
				if hit then
					if h ~= 1 then return i, mask, "slide" end
					back = true
				elseif h == 1 then
					speed = speed - 1
					if speed < 0 then back = true end
				elseif h == -1 and speed < cap then speed = speed + 1 end
				if back then
					local o = i * 4 + STEPOPP[d]
					if ok[o] == nil then g.unknown = true; return nil end
					if not ok[o] or pb[o] or (bw[o] >= 0 and (mask >> bw[o]) & 1 == 0) then return i, mask, "slide" end
					i = i - step_i
					if not filled[i] and not fill(g, t, fs, i) then return nil end
					return i, mask, "back"
				end
				forced = true
				i = i + step_i
				if not filled[i] and not fill(g, t, fs, i) then return nil end
			end
			return bad("slide does not end")
		end
		-- Every rest state reachable from the snapshot, breadth first: keys mask * 1024 + tile.
		local function explore(fs, snap, rules)
			local q = terrain.query(fs)
			local sig = snap.sig .. "|" .. rules.ice .. "," .. rules.sample .. "," .. rules.cap .. ","
				.. rules.breaks .. "," .. rules.ball
			local saved = snow.tree
			if saved and saved.sig == sig and saved.q == q then return saved end
			local g = geometry(fs, rules)
			local t = { people = snap.people, balls = snap.balls, filled = {}, pb = {}, ba = {}, bw = {} }
			local start = snap.pz * W + snap.px
			local known = g.y[start]
			if known == nil then g.y[start] = snap.py
			elseif known ~= snap.py then return bad("layered ice", "start") end
			if not fill(g, t, fs, start) then
				return bad(g.layered and "layered ice" or "start unreadable")
			end
			local parent, how, order, head = { [start] = false }, {}, { start }, 1
			while head <= #order do
				if head > LIMIT then return bad("search limit") end
				local k = order[head]; head = head + 1
				local i, mask = k % 1024, k // 1024
				for d = 0, 3 do
					local j, nmask = press(g, t, fs, rules, i, d, mask)
					if j then
						local nk = nmask * 1024 + j
						if parent[nk] == nil then parent[nk], how[nk] = k, d; order[#order + 1] = nk end
					end
				end
				if g.layered then return bad("layered ice") end
			end
			local tree = { sig = sig, q = q, parent = parent, how = how, order = order, start = start,
				unknown = g.unknown, g = g, t = t }
			snow.tree = tree
			return tree
		end
		-- The list's reachability: every tile the player can come to rest on, or nil to stand down.
		function snow.flood(fs)
			if not snow.at_rest(fs) then return nil end
			local rules = snow.rules()
			local snap = rules and snow.snapshot(fs, rules)
			local tree = snap and explore(fs, snap, rules)
			if not tree then return nil end
			if tree.unknown then dbg("Snowpoint Gym: unreadable ground in the flood"); return nil end
			local seen = {}
			for _, k in ipairs(tree.order) do
				local i = k % 1024
				seen[tkey(i % W, i // W)] = true
			end
			return seen
		end
		-- Snowballs are the planner's to break, never destinations (player, 3 November).
		function snow.unlisted(objects)
			local rules = snow.rules()
			if not rules then return objects end
			local out = {}
			for _, e in ipairs(objects) do
				if not (e.actor and inram(e.actor + MO_GFX + 3) and u32(e.actor + MO_GFX) == rules.ball) then
					out[#out + 1] = e
				end
			end
			return out
		end
		-- The route to `target` from where the player rests: one action per press. Slides speak their
		-- direction alone and are judged at rest (pf_follow, `slides`); walks merge into "2 up" as
		-- pf_build's do. `balls[n]` is the snowball mask expected after action n - 1.
		function snow.route(fs, px, pz, entry, target, occ, cache)
			-- Mid-slide there is no rest state to plan from: "can't route yet", never "can't reach".
			if not snow.at_rest(fs) then bad("player moving"); return nil, "terrain" end
			local rules = snow.rules()
			if not rules then return nil, "terrain" end
			local snap = snow.snapshot(fs, rules)
			if not snap then return nil, "terrain" end
			if snap.px ~= px or snap.pz ~= pz then return bad("player position") end
			local tree, why = explore(fs, snap, rules)
			if not tree then return nil, why == "search limit" and "limit" or "terrain" end
			local goals, any = {}, false
			for _, c in ipairs(goals_for(fs, target, occ, px, pz, cache)) do
				if c[1] >= 0 and c[2] >= 0 and c[1] < W and c[2] < W then
					goals[c[2] * W + c[1]] = goals[c[2] * W + c[1]] or c
					any = true
				end
			end
			if not any then return nil, "exhausted" end
			local hit
			for _, k in ipairs(tree.order) do
				if goals[k % 1024] then hit = k; break end
			end
			if not hit then
				dbg("Snowpoint Gym: no plan (" .. #tree.order .. " states)")
				return nil, tree.unknown and "terrain" or "exhausted"
			end
			local chain, k = {}, hit
			while k ~= tree.start do table.insert(chain, 1, k); k = tree.parent[k] end
			local g, t = tree.g, tree.t
			local motion = terrain.motion(fs, {})
			if motion == nil then return nil, "terrain" end
			local tiles, crossings, slides, masks = { { px, pz, snap.py, motion } }, {}, {}, { [1] = 0 }
			local moves, i, mask = {}, snap.pz * W + snap.px, 0
			for n, nk in ipairs(chain) do
				local d = tree.how[nk]
				local j, nmask, kind = press(g, t, fs, rules, i, d, mask)
				if not j or nmask * 1024 + j ~= nk then return bad("plan replay", tostring(n)) end
				moves[n] = { d = d, kind = kind }
				tiles[n + 1] = { j % W, j // W, g.y[j], motion }
				crossings[n], slides[n], masks[n + 1] = {}, kind ~= "walk", nmask
				i, mask = j, nmask
			end
			local segs, n = {}, 1
			while n <= #moves do
				local mv = moves[n]
				if mv.kind == "walk" then
					local last = n
					while last <= #moves and moves[last].kind == "walk" and moves[last].d == mv.d do last = last + 1 end
					segs[n] = (last - n) .. " " .. PFWORD[mv.d]
					n = last
				else
					segs[n] = PFWORD[mv.d]
					n = n + 1
				end
			end
			local at_tile = {}
			for m, t in ipairs(tiles) do
				local key = tkey(t[1], t[2])
				at_tile[key] = at_tile[key] or {}
				at_tile[key][#at_tile[key] + 1] = m
			end
			dbg("Snowpoint Gym: " .. #moves .. " presses, " .. #tree.order .. " states")
			return { name = entry.label or entry.name, gx = tiles[#tiles][1], gz = tiles[#tiles][2],
				tiles = tiles, at_tile = at_tile, transit = {}, crossings = crossings, segs = segs,
				idx = 1, total = #moves, partial = false, slides = slides,
				snow = { list = snap.list, masks = masks }, goal = goals[hit % 1024] }
		end
		-- At route tile `at`: are exactly the snowballs the plan expects still standing?
		function snow.matches(fs, pf, at)
			local want = pf.snow.masks[at]
			if want == nil then return true end
			local rules = snow.rules()
			local snap = rules and snow.snapshot(fs, rules)
			if not snap then return false end
			local standing = 0
			for _, ball in ipairs(pf.snow.list) do
				if (want >> ball.i) & 1 == 0 then
					standing = standing + 1
					if not snap.balls[ball.key] then return false end
				end
			end
			return #snap.list == standing
		end
		-- N dump: one line.
		function snow.describe(fs)
			local rules = snow.rules()
			if not rules then return "Snowpoint Gym: " .. tostring(snow.error) end
			local snap = snow.snapshot(fs, rules)
			if not snap then return "Snowpoint Gym: " .. tostring(snow.error) end
			return string.format("Snowpoint Gym: %d snowballs, %s, rules ice %02X sample %X cap %d break %d ball %02X",
				#snap.list, snow.at_rest(fs) and "at rest" or "moving", rules.ice, rules.sample, rules.cap,
				rules.breaks, rules.ball)
		end
	end

	-- ── PASTORIA GYM: which button to step on next ──────────────────────────────────────────────
	-- A uniform-cost search over (tile, height, water level). Steps are step_ok at that level's
	-- plate height (pastoria.level_cache); stepping onto a button of another level is the press:
	-- the player stops there at the height he stepped onto, and the level changes. Cost 16 per step
	-- and 1 more per press, so the fewest steps win and presses only break ties (no plan here needs
	-- 16 presses). The movement state stays the starting one: the gym has no Surf, bridge or slope
	-- behaviors (only 0x00, 0x56-0x59 and the door 0x65). On retail geometry
	-- from the entrance this is six presses (research/re/pt-pastoria-gym-20261031).
	-- `goals` = { [level] = { [tile key] = true } }, or nil to flood every reachable tile.
	pastoria.LIMIT = 30000
	function pastoria.search(fs, snap, sx, sz, occ, goals, actor_y, cache)
		local live = cache or {}
		local motion = terrain.motion(fs, live)
		if motion == nil then return nil, "terrain" end
		local sy = terrain.seed(fs, sx, sz, live)
		if sy == nil then return nil, "terrain" end
		local caches = {}
		for l = 0, 2 do caches[l] = pastoria.level_cache(snap, l, motion) end
		local ys, ny_count, states, dist, prev = {}, 0, {}, {}, {}
		local function id(x, z, y, l)
			local yi = ys[y]
			if not yi then ny_count = ny_count + 1; yi = ny_count; ys[y] = yi end
			return (tkey(x, z) * 4096 + yi) * 4 + l
		end
		local buckets, low, high, n = {}, 0, 0, 0
		local start = id(sx, sz, sy, snap.level)
		states[start], dist[start], buckets[0] = { sx, sz, sy, snap.level }, 0, { start }
		local seen, reached, unknown = { [tkey(sx, sz)] = true }, 1, 0
		while low <= high do
			local bucket = buckets[low]
			local cur = bucket and table.remove(bucket)
			if not cur then buckets[low] = nil; low = low + 1
			elseif dist[cur] == low then
				n = n + 1
				if n > pastoria.LIMIT then return nil, "limit" end
				local s = states[cur]
				local x, z, y, l = s[1], s[2], s[3], s[4]
				if goals and goals[l][tkey(x, z)]
					and (not actor_y or math.modf((y // 8) / 4096) == math.modf((actor_y // 8) / 4096)) then
					local path, k = {}, cur
					while k do table.insert(path, 1, states[k]); k = prev[k] end
					return path
				end
				for dir = 0, 3 do
					local ok, ny = step_ok(fs, x, z, dir, caches[l], y, nil, motion)
					if ok == nil then unknown = unknown + 1 end
					if ok then
						local nx, nz = x + STEPD[dir][1], z + STEPD[dir][2]
						local key = tkey(nx, nz)
						if not occ[key] then
							local b, nl, cost = snap.at[key], l, low + 16
							if b and b.level ~= l then nl, cost = b.level, cost + 1 end
							local nid = id(nx, nz, ny, nl)
							if not dist[nid] or cost < dist[nid] then
								dist[nid], prev[nid], states[nid] = cost, cur, { nx, nz, ny, nl }
								buckets[cost] = buckets[cost] or {}
								table.insert(buckets[cost], nid)
								if cost > high then high = cost end
								if not seen[key] then seen[key] = true; reached = reached + 1 end
							end
						end
					end
				end
			end
		end
		if goals then return nil, unknown > 0 and "terrain" or "exhausted" end
		return seen, reached, unknown
	end

	-- Every tile some sequence of presses reaches: what the list may offer. nil when unknown.
	-- Kept in the navigation cache (its identity includes the plate height) per start and occupancy.
	function pastoria.flood(fs, snap, px, pz, occ, cache)
		local keys = {}
		for k in pairs(occ) do keys[#keys + 1] = k end
		table.sort(keys)
		local sig = px .. ":" .. pz .. ":" .. snap.sig .. ":" .. table.concat(keys, ",")
		local hit = cache.pastoria_flood
		if hit and hit.sig == sig then return hit.seen end
		-- An unknown step means the flood cannot prove what it did not reach: stand the filter down.
		local seen, reached, unknown = pastoria.search(fs, snap, px, pz, occ, nil, nil, cache)
		if not seen or reached < 2 or unknown > 0 then
			dbg("Pastoria Gym: flood " .. tostring(reached) .. " tiles, " .. tostring(unknown) .. " unknown steps"); return nil
		end
		cache.pastoria_flood = { sig = sig, seen = seen }
		return seen
	end

	-- The next press on the way to `entry`: { x, z, key, sig, presses }, {} when none is needed,
	-- or nil and a reason.
	function pastoria.next_button(fs, px, pz, entry, occ, snap, cache)
		local actor_y
		if entry.actor then
			if not inram(entry.actor + 0x78) or (u32(entry.actor) & 0x1000) ~= 0 then return nil, "terrain" end
			actor_y = s32(entry.actor + 0x74)
		end
		local motion = terrain.motion(fs, cache)
		if motion == nil then return nil, "terrain" end
		local goals, any = {}, false
		for l = 0, 2 do
			goals[l] = {}
			for _, c in ipairs(goals_for(fs, entry, occ, px, pz, pastoria.level_cache(snap, l, motion))) do
				goals[l][tkey(c[1], c[2])] = true; any = true
			end
		end
		if not any then return nil, "exhausted" end
		local path, why = pastoria.search(fs, snap, px, pz, occ, goals, actor_y, cache)
		if not path then dbg("Pastoria Gym: no plan (" .. tostring(why) .. ")"); return nil, why end
		local presses, first = 0, nil
		for i = 2, #path do
			if path[i][4] ~= path[i - 1][4] then
				presses = presses + 1
				first = first or path[i]
			end
		end
		if not first then return {} end
		return { x = first[1], z = first[2], key = tkey(first[1], first[2]), sig = snap.sig, presses = presses }
	end

	-- ── SUNYSHORE GYM: which button to step on next ─────────────────────────────────────────────
	-- Pastoria's search over (tile, height, state): steps are step_ok in that state's cache
	-- (terrain.sunyshore.state_cache), and stepping onto any button is its press: the player stays
	-- on it and the state turns by the button's type. Cost 16 per step and 1 more per press, so the
	-- fewest steps win and presses break ties. A press always changes the state (a quarter or half
	-- turn), which is how a path's presses are found again.
	-- `goals` = { [state] = { [tile key] = true } }, or nil to flood every reachable tile.
	terrain.sunyshore.LIMIT = 30000
	function terrain.sunyshore.search(fs, snap, sx, sz, occ, goals, actor_y, cache)
		local live = cache or {}
		local motion = terrain.motion(fs, live)
		if motion == nil then return nil, "terrain" end
		local sy = terrain.seed(fs, sx, sz, live)
		if sy == nil then return nil, "terrain" end
		local caches = {}
		for s = 0, 3 do caches[s] = terrain.sunyshore.state_cache(snap, s, motion) end
		local ys, ny_count, states, dist, prev = {}, 0, {}, {}, {}
		local function id(x, z, y, s)
			local yi = ys[y]
			if not yi then ny_count = ny_count + 1; yi = ny_count; ys[y] = yi end
			return (tkey(x, z) * 4096 + yi) * 4 + s
		end
		local buckets, low, high, n = {}, 0, 0, 0
		local start = id(sx, sz, sy, snap.state)
		states[start], dist[start], buckets[0] = { sx, sz, sy, snap.state }, 0, { start }
		local seen, reached, unknown = { [tkey(sx, sz)] = true }, 1, 0
		while low <= high do
			local bucket = buckets[low]
			local cur = bucket and table.remove(bucket)
			if not cur then buckets[low] = nil; low = low + 1
			elseif dist[cur] == low then
				n = n + 1
				if n > terrain.sunyshore.LIMIT then return nil, "limit" end
				local st = states[cur]
				local x, z, y, s = st[1], st[2], st[3], st[4]
				if goals and goals[s][tkey(x, z)]
					and (not actor_y or math.modf((y // 8) / 4096) == math.modf((actor_y // 8) / 4096)) then
					local path, k = {}, cur
					while k do table.insert(path, 1, states[k]); k = prev[k] end
					return path
				end
				for dir = 0, 3 do
					local ok, ny = step_ok(fs, x, z, dir, caches[s], y, nil, motion)
					if ok == nil then unknown = unknown + 1 end
					if ok then
						local nx, nz = x + STEPD[dir][1], z + STEPD[dir][2]
						local key = tkey(nx, nz)
						if not occ[key] then
							local b, ns, cost = snap.at[key], s, low + 16
							if b then ns, cost = (s + b.turn) % 4, cost + 1 end
							local nid = id(nx, nz, ny, ns)
							if not dist[nid] or cost < dist[nid] then
								dist[nid], prev[nid], states[nid] = cost, cur, { nx, nz, ny, ns }
								buckets[cost] = buckets[cost] or {}
								table.insert(buckets[cost], nid)
								if cost > high then high = cost end
								if not seen[key] then seen[key] = true; reached = reached + 1 end
							end
						end
					end
				end
			end
		end
		if goals then return nil, unknown > 0 and "terrain" or "exhausted" end
		return seen, reached, unknown
	end

	-- Every tile some sequence of presses reaches: what the list may offer. nil when unknown.
	-- Kept in the navigation cache (its identity includes the state) per start and occupancy.
	function terrain.sunyshore.flood(fs, snap, px, pz, occ, cache)
		local keys = {}
		for k in pairs(occ) do keys[#keys + 1] = k end
		table.sort(keys)
		local sig = px .. ":" .. pz .. ":" .. snap.sig .. ":" .. table.concat(keys, ",")
		local hit = cache.sunyshore_flood
		if hit and hit.sig == sig then return hit.seen end
		-- An unknown step means the flood cannot prove what it did not reach: stand the filter down.
		local seen, reached, unknown = terrain.sunyshore.search(fs, snap, px, pz, occ, nil, nil, cache)
		if not seen or reached < 2 or unknown > 0 then
			dbg("Sunyshore Gym: flood " .. tostring(reached) .. " tiles, " .. tostring(unknown) .. " unknown steps"); return nil
		end
		cache.sunyshore_flood = { sig = sig, seen = seen }
		return seen
	end

	-- The next press on the way to `entry`: { x, z, key, sig, presses } to walk onto a button, the
	-- same with `back` = the button underfoot when the next press is that one again (the leg is the
	-- step off), {} when no press is needed, or nil and a reason.
	function terrain.sunyshore.next_button(fs, px, pz, entry, occ, snap, cache)
		local actor_y
		if entry.actor then
			if not inram(entry.actor + 0x78) or (u32(entry.actor) & 0x1000) ~= 0 then return nil, "terrain" end
			actor_y = s32(entry.actor + 0x74)
		end
		local motion = terrain.motion(fs, cache)
		if motion == nil then return nil, "terrain" end
		local goals, any = {}, false
		for s = 0, 3 do
			goals[s] = {}
			for _, c in ipairs(goals_for(fs, entry, occ, px, pz, terrain.sunyshore.state_cache(snap, s, motion))) do
				goals[s][tkey(c[1], c[2])] = true; any = true
			end
		end
		if not any then return nil, "exhausted" end
		local path, why = terrain.sunyshore.search(fs, snap, px, pz, occ, goals, actor_y, cache)
		if not path then dbg("Sunyshore Gym: no plan (" .. tostring(why) .. ")"); return nil, why end
		local presses, first = 0, nil
		for i = 2, #path do
			if path[i][4] ~= path[i - 1][4] then
				presses = presses + 1
				first = first or i
			end
		end
		if not first then return {} end
		local p = path[first]
		if p[1] == px and p[2] == pz then
			local off = path[first - 1]
			return { x = off[1], z = off[2], key = tkey(off[1], off[2]), back = { x = px, z = pz },
				sig = snap.sig, presses = presses }
		end
		return { x = p[1], z = p[2], key = tkey(p[1], p[2]), sig = snap.sig, presses = presses }
	end

	-- ── STRENGTH BOULDERS: PUSH THEM OUT OF THE WAY ─────────────────────────────────────────────
	-- The push, from the cartridge (pret/pokeplatinum src/overlay005/ov5_021DFB54.c, retail ov5):
	--  * Field input (field_control.c) passes PLAYER_EVENT_USED_STRENGTH while the system flag
	--    SystemFlag_HandleStrengthActive checks is set. That flag is cleared on every map change
	--    (FieldSystem_InitFlagsOnMapChange / _InitFlagsWarp) and set by the Strength field script,
	--    whether started from the party menu or by pressing A at a boulder.
	--  * ov5_021DFF1C (021DFF1C): moving state 1, the object one tile ahead found by sub_0206326C
	--    (first active object at that x/z), graphics `cmp r0,#0x54`, then sub_02063EBC for the
	--    boulder one tile on with bit 0 (movement range) masked off (`bics r0,r1`, r1 = 1). Any
	--    other bit refuses: sub_02063E18 = WillMapObjectCollide (the boulder's own height against
	--    the destination, 0x14000, collision bit, dynamic-height behavior 0x59), sub_02064004 (the
	--    two-sided directional blocks and behavior 0xFF) and sub_02063F00 (another object there).
	--  * ov5_021DFFBC: the boulder walks one tile (WALK_SLOW toward the press); the player walks on
	--    the spot and stays where they are. The walk ends with MapObject_UpdateCoords, so a boulder
	--    at rest has previous == current again. The push is a field task, so the route re-plans
	--    when it ends (on_exit). Pushed positions are not saved: they reset when the map reloads.
	-- Follower patch: every function above is byte-identical except one call inside sub_02063E18,
	-- whose object test moves to 0x023CBA98. That copy still skips no-collide (bit 18) objects except
	-- the follower (local id 0xFD) against a mover other than the player, so the follower can stop a
	-- boulder. It trails one tile behind the player, and the destination is two tiles ahead of the
	-- player, so it is never there; occupancy here keeps skipping bit 18 as before.
	-- Outside the Distortion World (its falling boulders, ov5_021DFB54.c 523-531, are not modelled;
	-- the router does not route there) Platinum has no Strength holes (Black and White's puzzle): a
	-- boulder only ever needs moving aside. So the planner searches boulder layouts — the fewest pushes after which ordinary
	-- walking reaches the target — and hands back only the first push: where to stand and which
	-- way. Each push re-plans, as Black and White does. Best-first on pushes plus a lower bound: the
	-- fewest boulder tiles any walk to the target crosses, each needing at least one push.
	terrain.strength = {}
	do
		local strength = terrain.strength
		-- Layout budget: the retail rooms' largest complete searches are 4,177 layouts (Mt. Coronet
		-- 1F, proving a one-way puzzle has no way back) and 3,065 (Victory Road 1F), about a third of a
		-- second offline; every solvable target in them needs far fewer (pt-strength-20261102).
		local ST_NODES, ST_FLOODS = 12000, 5000
		-- The interaction height: C truncation of (pos.y >> 3) / 4096, as pf_plan's Cut/Smash stop.
		function strength.level(y)
			local q = math.modf((y // 8) / 4096)
			return q
		end
		-- The height a gate actor has or will have: its own for a settled actor; for one still waiting
		-- for its cell (pending, MAP_OBJ_STATUS_12) the surface GetHeight will choose, the one nearest
		-- its spawn height, read through `cache` (the cartridge where the cell is not loaded). nil when
		-- that surface cannot be read.
		function terrain.rest_y(fs, gate, cache)
			if not gate.pending then return gate.y end
			return terrain.height(fs, gate.x, gate.z, gate.y, cache)
		end
		-- Is Strength switched on in this map? true / false / nil. The flag id is read out of
		-- SystemFlag_HandleStrengthActive itself (`ldr r3,=HandleFlag+1 ; ldr r2,=id ; bx r3`).
		function strength.active()
			local f = A.SystemFlagHandleStrengthActive
			if u16(f) ~= 0x4B01 or u16(f + 2) ~= 0x4A02 or u16(f + 4) ~= 0x4718
				or u32(f + 8) ~= A.HandleFlag + 1 then
				dbg("Strength: flag code has an unknown shape"); return nil
			end
			return story_flag(u32(f + 0xC))
		end
		-- Can the boulder at (x, z), height y, be pushed one tile in `dir`? Its new height, false, or
		-- nil when the ground cannot be read. `blocked` holds tiles another object stands on.
		function strength.push_ok(fs, x, z, y, dir, blocked, cache)
			local d = STEPD[dir]
			local nx, nz = x + d[1], z + d[2]
			if blocked[tkey(nx, nz)] then return false end
			if y == nil then return nil end
			local from, to = tile_attrs(fs, x, z, cache), tile_attrs(fs, nx, nz, cache)
			if not (from and to) then return nil end
			if (to & ATTR_COLLIDE) ~= 0 then return false end
			local bf, bt = from & ATTR_BEHAVIOR, to & ATTR_BEHAVIOR
			if bt == 0xFF then return false end
			local out, into = BLOCKED[bf], BLOCKED[bt]
			if (out and out[STEPNAME[dir]]) or (into and into[STEPNAME[STEPOPP[dir]]]) then return false end
			local ny, source = terrain.height(fs, nx, nz, y, cache)
			if not ny then return nil end
			if math.abs(ny - y) >= 0x14000 or (source == 2 and bt == 0x59) then return false end
			return ny
		end
		-- Every surface the player could walk to with no boulder anywhere, by the same moves as
		-- reach_from: nodes {x, z, y, motion}, and per node its moves with the tiles each passes.
		function strength.graph(fs, sx, sz, base, cache, scope)
			local sy, motion = terrain.seed(fs, sx, sz, cache), terrain.motion(fs, cache)
			if sy == nil or motion == nil then return nil, "terrain" end
			local ids, nodes, at, adj = {}, {}, {}, {}
			local function id(x, z, y, m)
				local k = tkey(x, z)
				local row = ids[k]
				if not row then row = {}; ids[k] = row; at[k] = {} end
				local l = y * 8 + m
				if row[l] then return row[l], false end
				local n = #nodes + 1
				row[l], nodes[n] = n, { x, z, y, m }
				at[k][#at[k] + 1] = n
				return n, true
			end
			local start = id(sx, sz, sy, motion)
			local q, head = { start }, 1
			while head <= #q do
				if #nodes > ST_NODES then return nil, "limit" end
				local n = q[head]; head = head + 1
				local x, z, y, m = nodes[n][1], nodes[n][2], nodes[n][3], nodes[n][4]
				local out = {}
				for dir = 0, 3 do
					local d = STEPD[dir]
					local span, nx, nz, ny, nm = ledge_jump(fs, x, z, dir, cache, m & 3, y, m)
					local path
					if not span then
						span, nx, nz, ny, path, nm = slope_move(fs, x, z, dir, cache, m & 3, y, base, m)
					end
					if not span then
						local ok
						ok, ny, nm = step_ok(fs, x, z, dir, cache, y, nil, m)
						if ok then span, nx, nz = 1, x + d[1], z + d[2] end
					end
					if nx and not base[tkey(nx, nz)] and scope(nx, nz, false) then
						local cross, cx, cz = {}, x, z
						for hop = 1, span do
							local s = STEPD[path and path[hop] or dir]
							cx, cz = cx + s[1], cz + s[2]
							cross[hop] = tkey(cx, cz)
						end
						if cx == nx and cz == nz then
							local to, new = id(nx, nz, ny, nm)
							out[#out + 1] = to; out[#out + 1] = cross
							if new then q[#q + 1] = to end
						end
					end
				end
				adj[n] = out
			end
			return { nodes = nodes, at = at, adj = adj, start = start }
		end
		-- The fewest pushes after which walking reaches a goal node: a list of {rock, dir, stand}
		-- (the first is the one to do now), {} when walking already does, or nil and a reason.
		-- `rocks` are {x, z, y}; `base` is everything else that stops a boulder.
		function strength.solve(fs, g, goal, rocks, base, cache)
			local nodes, at, adj = g.nodes, g.at, g.adj
			local mark, dist, gen, floods = {}, {}, 0, 0
			-- 0-1 breadth-first: a move costs 1 when it passes a boulder tile. Level 0 is where the
			-- player can walk now; the first level holding a goal is the bound. Returns the region's
			-- smallest node (its identity) and the bound, nil when no walk reaches a goal at all.
			local function flood(rk, from)
				floods, gen = floods + 1, gen + 1
				local cur, nxt, lv, rep, h = { from }, {}, 0, from, nil
				mark[from], dist[from] = gen, 0
				while #cur > 0 do
					local i = 1
					while i <= #cur do
						local n = cur[i]; i = i + 1
						if dist[n] == lv then
							if lv == 0 and n < rep then rep = n end
							if not h and goal[n] then h = lv end
							local a = adj[n]
							for j = 1, #a, 2 do
								local m, cross, c = a[j], a[j + 1], 0
								for t = 1, #cross do if rk[cross[t]] then c = 1; break end end
								local dm = lv + c
								if mark[m] ~= gen or dist[m] > dm then
									mark[m], dist[m] = gen, dm
									if c == 0 then cur[#cur + 1] = m else nxt[#nxt + 1] = m end
								end
							end
						end
					end
					if h then break end
					cur, nxt, lv = nxt, {}, lv + 1
				end
				return rep, h
			end
			local function set(pos)
				local s = {}
				for k = 1, #pos do s[pos[k]] = true end
				return s
			end
			local function name(pos, rep)
				local s = { table.unpack(pos) }
				table.sort(s)
				return table.concat(s, ",") .. "|" .. rep
			end
			local pos0, ys0 = {}, {}
			for k, r in ipairs(rocks) do pos0[k], ys0[k] = tkey(r.x, r.z), r.y end
			local rep, h = flood(set(pos0), g.start)
			if not h then return nil, "exhausted", floods end
			if h == 0 then return {}, nil, floods end
			local states, known, heap = { { pos = pos0, ys = ys0, p = g.start, depth = 0 } }, { [name(pos0, rep)] = true }, {}
			local function push(i, pr)
				heap[#heap + 1] = { pr, i }
				local c = #heap
				while c > 1 do
					local p = c // 2
					if heap[p][1] <= heap[c][1] then break end
					heap[p], heap[c] = heap[c], heap[p]; c = p
				end
			end
			local function pop()
				local top, last = heap[1], table.remove(heap)
				if #heap > 0 then
					heap[1] = last
					local c = 1
					while true do
						local l, r, m = 2 * c, 2 * c + 1, c
						if l <= #heap and heap[l][1] < heap[m][1] then m = l end
						if r <= #heap and heap[r][1] < heap[m][1] then m = r end
						if m == c then break end
						heap[m], heap[c] = heap[c], heap[m]; c = m
					end
				end
				return top[2]
			end
			-- Priority: pushes so far plus the bound, ties to the smaller bound (it is below 256).
			push(1, h * 256 + h)
			local terr = {}
			while #heap > 0 do
				local st = states[pop()]
				local rk = set(st.pos)
				flood(rk, st.p)
				local here, moves = gen, {}
				for k = 1, #st.pos do
					local key, y = st.pos[k], st.ys[k]
					local x, z = key // 0x10000 - 0x8000, key % 0x10000 - 0x8000
					for d = 0, 3 do
						local s = STEPD[d]
						local stand
						-- Stand on the far side, on the boulder's own floor (pressing A to use Strength
						-- compares the two heights), somewhere the player can walk to now.
						for _, n in ipairs(at[tkey(x - s[1], z - s[2])] or {}) do
							if mark[n] == here and dist[n] == 0 and strength.level(nodes[n][3]) == strength.level(y) then
								stand = n; break
							end
						end
						local dest = tkey(x + s[1], z + s[2])
						if stand and not rk[dest] then
							local tk = key * 4 + d .. ":" .. y
							local ny = terr[tk]
							if ny == nil then ny = strength.push_ok(fs, x, z, y, d, base, cache) or false; terr[tk] = ny end
							if ny then moves[#moves + 1] = { k, d, stand, dest, ny } end
						end
					end
				end
				for _, mv in ipairs(moves) do
					if floods >= ST_FLOODS then return nil, "limit", floods end
					local pos, ys = { table.unpack(st.pos) }, { table.unpack(st.ys) }
					pos[mv[1]], ys[mv[1]] = mv[4], mv[5]
					local r2, h2 = flood(set(pos), mv[3])
					local nm = name(pos, r2)
					if h2 and not known[nm] then
						known[nm] = true
						local child = { pos = pos, ys = ys, p = mv[3], depth = st.depth + 1, parent = st,
							move = { rock = mv[1], dir = mv[2], stand = mv[3] } }
						states[#states + 1] = child
						if h2 == 0 then
							local plan = {}
							while child.parent do table.insert(plan, 1, child.move); child = child.parent end
							return plan, nil, floods
						end
						push(#states, (child.depth + h2) * 256 + h2)
					end
				end
			end
			return nil, "exhausted", floods
		end
		-- The first push of a plan to `entry`: {x, z (where to stand), dir, rock, pushes}, {} when no
		-- push is needed, or nil and a reason ("exhausted" means no sequence of pushes reaches it).
		function strength.next_push(fs, px, pz, entry, occ, cache)
			if eterna.active(fs, cache) or veilstone.active(fs) or pastoria.active(fs, cache)
				or terrain.canalave.active(fs, cache) then return nil end
			local _, ok, gates = occupied(fs)
			if not ok then dbg("Strength: occupancy unreadable"); return nil, "terrain" end
			local rocks, base = {}, {}
			for _, gate in pairs(gates) do if gate.bit == 4 then rocks[#rocks + 1] = gate end end
			if #rocks == 0 then return nil end
			table.sort(rocks, function(a, b) return a.actor < b.actor end)
			for key in pairs(occ) do base[key] = true end
			for _, r in ipairs(rocks) do base[tkey(r.x, r.z)] = nil end
			-- Cut and Rock Smash obstacles: open to the walk, because clearing one never closes
			-- anything (pf_plan clears one that stands on the way first), but still solid to a
			-- boulder: the object test refuses a push into one until it is cleared.
			local held = {}
			for key, gate in pairs(gates) do
				if gate.bit ~= 4 then base[key] = nil; held[key] = true end
			end
			for key in pairs(base) do held[key] = true end
			-- ⛔ THE WHOLE ROOM, NOT THE LOADED PART OF IT. LandData loads cells by the player's quadrant
			-- (land_data.c LandData_CalculateLoadedMapMatrixIndexes), so in a two-cell room the far cell
			-- is simply missing while the player stands in the outer half of the near one. Searched on
			-- live data alone, a puzzle that crosses the cell line looked impossible: Mt. Coronet 1F
			-- between the halves of Route 211, back from B1F at (11,10), said "I can't route" to both
			-- exits (in game, 3 November). Geometry that cannot change comes from the cartridge where
			-- a cell is not loaded (hm_discovery, as the list's flood and Pastoria Gym do); loaded cells,
			-- heights of moving plates and every object stay live.
			local dc = terrain.hm_discovery(fs, px, pz, cache)
			local gc = dc or cache
			-- Boulders in a cell that is not loaded are still waiting for their height.
			for _, r in ipairs(rocks) do r.y, r.pending = terrain.rest_y(fs, r, gc), false end
			local scope = dc and dc.hm_scope or terrain.route_scope(fs, px, pz, px, pz, nil, cache)
			if not scope then dbg("Strength: no route scope"); return nil, "terrain" end
			local g, why = strength.graph(fs, px, pz, base, gc, scope)
			if not g then dbg("Strength: no walking graph (" .. tostring(why) .. ")"); return nil, why end
			local goal, any = {}, false
			for _, c in ipairs(goals_for(fs, entry, base, px, pz, gc, dc ~= nil)) do
				local x, z = c[1], c[2]
				if entry.connection then x, z = x - STEPD[entry.direction][1], z - STEPD[entry.direction][2] end
				for _, n in ipairs(g.at[tkey(x, z)] or {}) do goal[n], any = true, true end
			end
			if not any then dbg("Strength: the target is off the walking graph"); return nil, "exhausted", dc ~= nil end
			local plan, why2, floods = strength.solve(fs, g, goal, rocks, held, gc)
			if not plan then
				dbg("Strength: no plan (" .. tostring(why2) .. ", " .. tostring(floods) .. " layouts)")
				-- Third value: the search saw the whole room, so "exhausted" is a proof.
				return nil, why2, dc ~= nil
			end
			dbg("Strength: " .. #plan .. " pushes, " .. tostring(floods) .. " layouts searched")
			local first = plan[1]
			if not first then return {} end
			local stand = g.nodes[first.stand]
			return { x = stand[1], z = stand[2], dir = first.dir, rock = rocks[first.rock], pushes = #plan }
		end
	end

	-- ── THE DISTORTION WORLD (PT-NAV-DW-01) ─────────────────────────────────────────────────────
	-- research/re/report-20261104-platinum-distortion-world.md holds the evidence for every number
	-- here; research/re/distortion-world/ holds the dumps. Overlay 9, its tables and the floor
	-- archives are identical in the follower patch except the slab object's local id, which nothing
	-- here uses.
	--
	-- ⭐ TWO MOVEMENT MODELS, AND THE PLAYER AVATAR SAYS WHICH (PlayerAvatar +0x00 & 0x1F00, an exact
	-- match, PlayerAvatar_MapDistortionState 0x0205F108). 0x100 is ORDINARY GROUND: the land data,
	-- BDHC height, ledges and water exactly as everywhere else, so step_ok and ledge_jump answer it,
	-- plus the 3-tile gap jumps (behaviors 0x5A-0x5D), which exist only here. 0x200/0x400/0x800/0x1000
	-- are a FLOATING PLATFORM (floor, west wall, east wall, ceiling): one 32x32 grid per platform,
	-- bit 15 collision, low byte behavior, out of bounds solid, no height test.
	-- ⛔ WALKING OFF AN EDGE NEVER CHANGES THE SURFACE. Only a jump point (a fixed box plus a pressed
	-- button), a ferry or lift event, an elevator slab or a waterfall does; each is an edge here.
	-- ⛔ AND THE BUTTONS ARE NOT THE COMPASS ON A WALL. The step vectors come from the game's own four
	-- tables (sDistortionStepDirection*), so a route is a list of BUTTONS, which is what PFWORD speaks.
	--
	-- Chain: FieldSystem +0x04 -> +0x24 = DistWorldSystem (read 0x02250F92, cleared on free 0x02249AFE,
	-- so it does not dangle). The slot is shared with other dynamic-map features, so it is accepted
	-- only with persisted feature 9 at Misc +0x700, its back-pointer, its persisted-data pointer
	-- (Misc +0x704) and its own map id.
	--   +0x1644 map file: map id, +0x1648 platform section, +0x164C jump section, +0x165C buffer
	--   +0x1660 platforms: current index, +0x1664 count, +0x1668 templates (0x14), +0x1670 grid
	--   +0x1674 jump points: count, +0x1678 templates (0x28)
	--   +0x16D0 moving-platform animators, 32 x 0x24 (valid, map, tile x/y/z, dir 0 up 1 down 2 ferry)
	-- Only the current platform's grid is in RAM; the others are read from the cartridge's own
	-- fielddata/tornworld/tw_arc_attr.narc (member = template +0x02), checked against the live grid.
	terrain.dw = {}
	do
		local dw = terrain.dw
		local C = {
			MAPS = { [573]=true, [574]=true, [575]=true, [576]=true, [577]=true, [579]=true,
				[580]=true, [581]=true, [582]=true, [583]=true },
			B5F = 579, B6F = 580, B7F = 581, GIRATINA = 582, TURNBACK = 583,
			-- 0 floor, 1 west wall, 2 east wall, 3 ceiling (FloatingPlatformKind); 4 ordinary ground,
			-- which is also the jump-point kind meaning "back to the ground".
			STATE = { [0x100] = 4, [0x200] = 0, [0x400] = 1, [0x800] = 2, [0x1000] = 3 },
			GROUND = 4, FEATURE = 9, SIZE = 0x1E74,
			PROGRESS = 0x4055,          -- VAR_DISTORTION_WORLD_PROGRESS
			LOCALID_PLAYER = 0xFF, JUMP_ACTION = 117,  -- MOVEMENT_ACTION_JUMP_DISTORTION_WORLD_NORTH..EAST
			-- Compiled into DistWorld_HandlePlayerMoved / _HandlePlayerPositionChanged /
			-- _HandlePlayerMovementEnd (ov9 #defines WATERFALL_*, *_TELEPORT_TILE_*): a slide fires on
			-- RIGHT while surfing there; the B7F tile on arriving facing up or pressing up (progress at
			-- least 10, WON_CYRUS_BATTLE); the Giratina room's on arriving facing down or pressing down.
			SLIDES = { [577] = { x = 104, y = 170, z0 = 76, z1 = 79, word = "down" },
			           [579] = { x = 104, y = 128, z0 = 76, z1 = 79, word = "up" } },
			PASSAGES = { [581] = { x = 89, y = 65, z = 57, button = 0, progress = 10 },
			             [582] = { x = 15, y = 1, z = 25, button = 1, progress = 0 } },
			-- DistWorld_DynamicMapFeaturesCheckCollision 0x02249E50: the solid tile beyond each.
			SOLID = { [581] = { x = 89, z = 56 }, [582] = { x = 15, z = 26 } },
			-- The two map-object portals (scripts "Will you leap into the portal?"); the 1F portal is
			-- an interaction spot named through PM.spot.names.
			PORTALS = { [582] = 131, [583] = 128 },
			KSTEP = 1 << 14, LIMIT = 90000, FLOOD = 60000,
		}
		-- Mod-owned words. "Rock slab" is Cynthia's word for it (bank distortion_world_1f, "This rock
		-- slab... It appears to move if you step on a certain spot."); "Portal" is every portal
		-- message's own word; up, down, "Passage" and "Event" are ours (the player's choices, 4 November).
		-- No comma before the direction ("Rock slab down", "Surf 1 up"): the player's call, 4 November.
		dw.text = { slab = "Losa de roca", up = "arriba", down = "abajo", passage = "Pasaje", portal = "Portal", event = "Evento" }
		dw.grids = {}            -- cartridge platform grids by member: immutable, kept for the session

		local function pkey(x, y, z) return (x * 1024 + y) * 1024 + z end
		dw.pkey = pkey
		-- The follower's key for a node. ⛔ ON THE GROUND THE HEIGHT IS LEFT OUT: height calculation
		-- runs there, so x and z change when a step starts and the half-tile y only when pos.y crosses
		-- a boundary partway through it (MapObject_RecalculateObjectHeight); a key with y would see a
		-- tile on no route for those frames. pf_follow's fixed-point tie-break still tells levels apart.
		-- On a platform height calculation is off and y changes only by climbing, so it stays.
		local function fkey(x, y, z, ground) return pkey(x, ground and 0 or y, z) end
		dw.fkey = fkey
		local function s16(a) local v = u16(a); return v >= 0x8000 and v - 0x10000 or v end
		-- A three-dimensional key back to the two-dimensional one the boulder code compares.
		local function flat(k) return tkey(k // 0x100000, k % 1024) end

		local function bad(cache, why)
			if dw.error ~= why then dbg("Distortion World: " .. why) end
			dw.error = why
			if cache then cache.dw, cache.dw_why = false, why end
			return nil, why
		end

		function dw.active(fs, cache)
			if cache and cache.dw_map ~= nil then return cache.dw_map end
			local on = C.MAPS[map_id(fs) or -1] == true
			if cache then cache.dw_map = on end
			return on
		end

		-- The game's step vector for a button on a surface kind (0..3; ground walks as a floor).
		function dw.steps()
			if dw.step_table ~= nil then return dw.step_table or nil end
			dw.step_table = false
			local t = {}
			for kind = 0, 3 do
				t[kind] = {}
				for b = 0, 3 do
					local a = A.DistortionStepTables + kind * 0x20 + b * 8
					local v = { s16(a), s16(a + 2), s16(a + 4) }
					if math.abs(v[1]) + math.abs(v[2]) + math.abs(v[3]) ~= 1 then
						return bad(nil, "step table " .. kind .. " has an unknown shape")
					end
					t[kind][b] = v
				end
			end
			t[C.GROUND] = t[0]
			dw.step_table = t
			return t
		end

		-- The validated snapshot this press works from, or nil and a named reason.
		function dw.sys(fs, cache)
			cache = cache or {}
			if cache.dw ~= nil then return cache.dw or nil, cache.dw_why end
			local map = map_id(fs)
			if not C.MAPS[map or -1] then return bad(cache, "not a Distortion World map") end
			local misc = save_page(SD_MISC, SD_MISC_SIZE, "Distortion World")
			if not misc or not inram(misc + 0x713) then return bad(cache, "misc save page unreadable") end
			if u32(misc + 0x700) ~= C.FEATURE then return bad(cache, "persisted feature is not the Distortion World") end
			local sub = u32(fs + 0x04)
			if not (inram(sub) and inram(sub + 0x27)) then return bad(cache, "field sub-system unreadable") end
			local d = u32(sub + 0x24)
			if not (inram(d) and inram(d + C.SIZE - 1)) then return bad(cache, "system unreadable") end
			if u32(d) ~= fs then return bad(cache, "system back-pointer") end
			if u32(d + 0x04) ~= misc + 0x704 then return bad(cache, "persisted data pointer") end
			if u32(d + 0x1644) ~= map then return bad(cache, "map file belongs to another floor") end
			local steps = dw.steps()
			if not steps then return bad(cache, "step tables unreadable") end
			local pa = u32(fs + FS_AVATAR)
			if not (inram(pa) and inram(pa + PA_OBJ + 3)) then return bad(cache, "player avatar unreadable") end
			local kind = C.STATE[u32(pa) & 0x1F00]
			if not kind then return bad(cache, "player surface state " .. (u32(pa) & 0x1F00)) end
			local mo = u32(pa + PA_OBJ)
			if not (inram(mo) and inram(mo + MO_STRIDE - 1)) or (u32(mo) & MO_INUSE) == 0 then
				return bad(cache, "player object unreadable")
			end
			local motion = terrain.motion(fs, cache)
			if motion == nil then return bad(cache, "player movement mode") end
			local S = { fs = fs, d = d, map = map, misc = misc, kind = kind, mo = mo, steps = steps,
				x = s32(mo + 0x64), y = s32(mo + 0x68) // 2, z = s32(mo + 0x6C), yfx = s32(mo + 0x74),
				motion = motion, progress = story_var(C.PROGRESS), puzzle = u32(misc + 0x704 + 0x0C) }
			-- Platforms of this floor.
			local section, buffer = u32(d + 0x1648), u32(d + 0x165C)
			local count, tpl, cur = s32(d + 0x1664), u32(d + 0x1668), s32(d + 0x1660)
			S.plats, S.nplats = {}, count
			if count < 0 or count > 16 then return bad(cache, "platform count " .. count) end
			if count > 0 then
				if section ~= buffer + 0x14 or tpl ~= section + 4 or s32(section) ~= count
					or not inram(tpl + count * 0x14 - 1) then return bad(cache, "platform section") end
				for i = 0, count - 1 do
					local t = tpl + i * 0x14
					local p = { i = i, kind = s16(t), attr = u16(t + 2),
						sx = s16(t + 4), sy = s16(t + 6), sz = s16(t + 8),
						wx = s16(t + 0xA), wy = s16(t + 0xC), wz = s16(t + 0xE),
						tcv = u16(t + 0x10), tch = u16(t + 0x12) }
					if p.kind < 0 or p.kind > 3 or p.wx < 0 or p.wy < 0 or p.wz < 0
						or p.tcv < 1 or p.tch < 1 or p.tcv * p.tch * 2 > 0x800 then
						return bad(cache, "platform template " .. i)
					end
					S.plats[i] = p
				end
				local grid, size = u32(d + 0x1670), u32(d + 0x166C)
				if cur >= 0 and cur < count and size == 0x800 and inram(grid) and inram(grid + size - 1) then
					S.cur, S.live = cur, grid
				end
			end
			if kind ~= C.GROUND then
				if not S.cur or S.plats[S.cur].kind ~= kind then return bad(cache, "current platform disagrees with the player") end
			end
			-- Jump points of this floor.
			local jsec, jn, jt = u32(d + 0x164C), s32(d + 0x1674), u32(d + 0x1678)
			S.jumps = {}
			if jn < 0 or jn > 64 then return bad(cache, "jump point count " .. jn) end
			if jn > 0 then
				if jt ~= jsec + 4 or s32(jsec) ~= jn or not inram(jt + jn * 0x28 - 1) then
					return bad(cache, "jump point section")
				end
				for i = 0, jn - 1 do
					local t = jt + i * 0x28
					local j = { b = s16(t + 2), sx = s16(t + 8), sy = s16(t + 0xA), sz = s16(t + 0xC),
						wx = s16(t + 0xE), wy = s16(t + 0x10), wz = s16(t + 0x12),
						dx = s16(t + 0x14), dy = s16(t + 0x16), dz = s16(t + 0x18),
						kind = s16(t + 0x24), plat = u16(t + 0x26) }
					if j.b < 0 or j.b > 3 or j.kind < 0 or j.kind > 4
						or (j.kind ~= C.GROUND and not S.plats[j.plat]) then
						return bad(cache, "jump point " .. i)
					end
					S.jumps[#S.jumps + 1] = j
				end
			end
			-- Elevator slabs and ferry platforms present on this floor right now.
			S.slabs = {}
			for i = 0, 31 do
				local a = d + 0x16D0 + i * 0x24
				if u8(a) == 1 and u16(a + 2) == map then
					local dir = u16(a + 0xE)
					if dir > 2 then return bad(cache, "moving platform direction") end
					if dir < 2 then
						S.slabs[#S.slabs + 1] = { x = s16(a + 6), y = s16(a + 8), z = s16(a + 0xA), dir = dir, key = "DS" .. i }
					end
				end
			end
			S.slab_at = {}
			for _, s in ipairs(S.slabs) do S.slab_at[pkey(s.x, s.y, s.z)] = s end
			local events, why = dw.events(map, S)
			if not events then return bad(cache, why) end
			S.events = events
			cache.dw = S
			return S
		end

		-- A pointer into overlay 9's own read-only data.
		local function ov9(p) return p >= A.DistWorldOverlay and p < A.DistWorldOverlay + A.DistWorldOverlaySize end

		-- This floor's coordinate events (sMapEvents, read live): each is a trigger tile and, when its
		-- commands carry the player (a ferry or a lift), where the player ends up. The landing is the
		-- trigger plus every MOVE_PLATFORM that moves the player plus every player jump (3 tiles,
		-- MovementAction_JumpDistortionWorld*); the surface is the first platform of any kind holding
		-- the tile after the last carrying move, else the ground (EventCmdMovePlatform_EndMovement).
		function dw.events(map, S)
			local list
			for i = 0, 15 do
				local e = A.DistWorldMapEvents + i * 8
				local id = u32(e)
				if id == MH_COUNT then break end
				if not C.MAPS[id] or not ov9(u32(e + 4)) then return nil, "event table shape" end
				if id == map then list = u32(e + 4); break end
			end
			local out = {}
			if not list then return out end
			for i = 0, 63 do
				local e = list + i * 0x10
				if not ov9(e) then return nil, "event list bounds" end
				local cmds = u32(e + 0xC)
				if cmds == 0 then return out end
				if not ov9(cmds) then return nil, "event commands pointer" end
				local ev = { x = s16(e), y = s16(e + 2), z = s32(e + 4), cond = u16(e + 8), val = u16(e + 0xA) }
				local x, y, z, carried, jumped, cascade, scene = ev.x, ev.y, ev.z, nil, false, false, false
				for k = 0, 31 do
					local c = cmds + k * 8
					local kind, params = u32(c), u32(c + 4)
					if kind == 18 then break end              -- EVENT_CMD_END
					if kind > 18 or (params ~= 0 and not ov9(params)) then return nil, "event command shape" end
					if kind == 1 and u16(params + 2) == 1 then             -- MOVE_PLATFORM, movePlayer
						x, y, z = x + s16(params + 6), y + s16(params + 8), z + s16(params + 0xA)
						carried = { x, y, z }
					elseif kind == 0 and u32(params) == C.LOCALID_PLAYER then  -- SET_MAP_OBJECT_ANIMATION
						local action = u32(params + 4) - C.JUMP_ACTION
						if action < 0 or action > 3 then return nil, "event moves the player unexpectedly" end
						local v = S.steps[0][action]
						x, z, jumped = x + v[1] * 3, z + v[3] * 3, true
					elseif kind == 4 or kind == 10 then cascade = true       -- CASCADE_UP / _DOWN
					elseif kind == 5 or kind == 6 or kind == 7 or kind == 11 then scene = true
					end
				end
				-- A cascade leaves the floor: a stop, never an edge. A jump with no carrying move
				-- keeps whatever surface the player arrived on.
				-- A story scene: a script, a progress step, Giratina's shadow or arrival, gated on the
				-- story's progress (conditions 3-5). Listed only in Giratina's room (dw.entries).
				ev.scene = scene and ev.cond >= 3 and ev.cond <= 5
				if cascade then ev.stop = true
				elseif carried or jumped then
					ev.land = { x, y, z }
					if carried then ev.plat = dw.plat_at(S, carried[1], carried[2], carried[3], nil) or -1 end
				end
				out[#out + 1] = ev
			end
			return nil, "event list unterminated"
		end

		-- CheckFlagCondition (ov9:9670) for the conditions a story event can carry; nil when unsure.
		function dw.condition(S, ev)
			local c, v, p = ev.cond, ev.val, S.progress
			if c == 0 then return true end
			if c == 1 or c == 2 then return ((S.puzzle >> v) & 1 == 1) == (c == 2) end
			if p == nil then return nil end
			if c == 3 then return p == v elseif c == 4 then return p <= v elseif c == 5 then return p >= v end
			return nil
		end

		local function inside(p, x, y, z)
			return x >= p.sx and x <= p.sx + p.wx and y >= p.sy and y <= p.sy + p.wy and z >= p.sz and z <= p.sz + p.wz
		end
		-- The first template (list order) holding the tile, of `kind` if given (FindAndPrepareNew...).
		function dw.plat_at(S, x, y, z, kind)
			for i = 0, S.nplats - 1 do
				local p = S.plats[i]
				if inside(p, x, y, z) and (kind == nil or p.kind == kind) then return i end
			end
			return nil
		end

		-- One platform's attribute halfword at a tile, or 0xFFFE out of bounds, nil unreadable.
		-- GetCurrentFloatingPlatformTileAttributes ov9:9568: grid[v + h * tileCountVertical].
		function dw.pattr(S, i, x, y, z)
			local p = S.plats[i]
			if not p then return nil end
			if not inside(p, x, y, z) then return 0xFFFE end
			local v
			if p.kind == 0 then v = x - p.sx
			elseif p.kind == 1 then v = p.wy - (y - p.sy)
			elseif p.kind == 2 then v = y - p.sy
			else v = p.wx - (x - p.sx) end
			local idx = v + (z - p.sz) * p.tcv
			if v < 0 or v >= p.tcv or idx < 0 or idx >= p.tcv * p.tch then return 0xFFFE end
			if i == S.cur and S.live then return u16(S.live + idx * 2) end
			local g = dw.grid(S, p.attr)
			if not g then return nil end
			local a = g.t[idx]
			if a == nil then a = PM.rom_read(g.base + idx * 2, 2); g.t[idx] = a or false end
			return a or nil
		end

		-- A cartridge grid, accepted only after it matched the live one while that platform was current.
		function dw.grid(S, attr)
			local g = dw.grids[attr]
			if g == nil then
				local base, size = PM.rom_member("fielddata/tornworld/tw_arc_attr.narc", attr, 0x800)
				g = base and size == 0x800 and { base = base, t = {} } or false
				dw.grids[attr] = g
			end
			if not g then return nil end
			if g.ok == nil and S.cur and S.live and S.plats[S.cur].attr == attr then
				g.ok = true
				for i = 0, 0x3FF do
					local a = g.t[i]
					if a == nil then a = PM.rom_read(g.base + i * 2, 2); g.t[i] = a or false end
					if a ~= u16(S.live + i * 2) then g.ok = false; break end
				end
				if not g.ok then dbg("Distortion World: cartridge grid " .. attr .. " differs from the live one") end
			end
			-- Never checked yet: trusted, because the archive is identical in both cartridges and the
			-- first time that platform is current the check runs. A mismatch closes it for good.
			if g.ok == false then return nil end
			return g
		end

		-- Who stands where, in three dimensions (sub_02063F00: x and z current or previous, and the
		-- object's half-tile height within 2 of the asked one). Objects of the preloaded next floor
		-- carry that floor's map id and are left out.
		function dw.occupants(S)
			if S.occ then return S.occ, S.occ_ok end
			local occ, mm, ok = {}, u32(S.fs + FS_OBJMAN), true
			local n, arr = s32(mm + MOM_MAX), u32(mm + MOM_ARRAY)
			if not inram(mm) or u32(mm + MOM_FS) ~= S.fs or n ~= MOM_EXPECT or not inram(arr + n * MO_STRIDE - 1) then
				ok = false
			else
				for i = 0, n - 1 do
					local o = arr + i * MO_STRIDE
					local st = u32(o + MO_STATUS)
					if o ~= S.mo and (st & MO_INUSE) ~= 0 and (st & MO_NOCOLLIDE) == 0 and u32(o + MO_MAPID) == S.map then
						local y = s32(o + 0x68)
						for _, k in ipairs({ tkey(s32(o + MO_X), s32(o + MO_Z)), tkey(s32(o + MO_XPREV), s32(o + MO_ZPREV)) }) do
							occ[k] = occ[k] or {}
							occ[k][#occ[k] + 1] = { y = y, o = o }
						end
					end
				end
			end
			S.occ, S.occ_ok = occ, ok
			return occ, ok
		end
		function dw.occupied(S, x, y, z, skip)
			local list = dw.occupants(S)[tkey(x, z)]
			if not list then return false end
			for _, e in ipairs(list) do
				if e.o ~= skip and math.abs(e.y - y * 2) < 2 then return true end
			end
			return false
		end

		-- A node: x, y (tile), z, p (platform index, -1 ground), m (motion), f (ground fx32 height).
		local function nkey(n) return ((pkey(n.x, n.y, n.z) * 32 + (n.p + 1)) * 8) + (n.m & 7) end
		dw.nkey = nkey
		local function ground_y(f) return (f // 0x8000) // 2 end
		dw.ground_y = ground_y

		-- A node on the ground at a tile reached by a jump or a ride: the surface nearest the tile
		-- height the game moved the player to, accepted within one tile of it.
		function dw.ground(W, x, y, z, m)
			local f = terrain.height(W.fs, x, z, y * 0x10000, W.cache)
			if not f or math.abs(ground_y(f) - y) > 1 then return nil end
			return { x = x, y = ground_y(f), z = z, p = -1, m = m, f = f }
		end

		-- The start node: where the player stands now.
		function dw.start(S)
			local p = S.kind == C.GROUND and -1 or S.cur
			return { x = S.x, y = S.y, z = S.z, p = p, m = S.motion, f = S.kind == C.GROUND and S.yfx or nil }
		end

		-- Every press from node n: calls out(button, node, kind, transit) for moves that keep the
		-- route going, and stop(button, kind, data) for presses that end it here (a slab ride, a
		-- slide, a passage, Surf). `W` carries the world (fs, cache, S, surf allowed, goal tiles).
		function dw.moves(W, n, out, stop)
			local S, fs, cache = W.S, W.fs, W.cache
			local kind = n.p < 0 and C.GROUND or S.plats[n.p].kind
			local steps = S.steps[kind]
			local surfing = (n.m & 3) == 2
			for b = 0, 3 do
				-- 1. A jump point fires on the press, before any step (FindFloatingPlatformJumpPointAt).
				local jumped = false
				for _, j in ipairs(S.jumps) do
					if j.b == b and n.x >= j.sx and n.x <= j.sx + j.wx and n.y >= j.sy and n.y <= j.sy + j.wy
						and n.z >= j.sz and n.z <= j.sz + j.wz then
						jumped = true
						local x, y, z = n.x + j.dx, n.y + j.dy, n.z + j.dz
						if j.kind == C.GROUND then
							local to = dw.ground(W, x, y, z, n.m & 3)
							if to then out(b, to, "point") end
						else
							out(b, { x = x, y = y, z = z, p = j.plat, m = n.m & 3 }, "point")
						end
						break
					end
				end
				-- 2. A slide: RIGHT while surfing on the waterfall's column.
				local slide = C.SLIDES[S.map]
				if not jumped and slide and b == 3 and surfing and n.x == slide.x and n.y == slide.y
					and n.z >= slide.z0 and n.z <= slide.z1 then
					stop(b, "slide", slide)
					jumped = true
				end
				-- 3. A passage pressed into its solid tile.
				local pass = C.PASSAGES[S.map]
				if not jumped and pass and b == pass.button and n.x == pass.x and n.y == pass.y and n.z == pass.z
					and (S.progress or -1) >= pass.progress then
					stop(b, "passage", pass)
					jumped = true
				end
				if not jumped then
					if kind == C.GROUND then dw.ground_moves(W, n, b, out, stop)
					else dw.platform_moves(W, n, b, kind, steps[b], out, stop) end
				end
			end
		end

		-- Where a step ends: a slab rides, a coordinate event carries or plays, a passage teleports.
		-- Returns true when the move was consumed (an edge or a stop), false for an ordinary arrival.
		function dw.arrive(W, n, b, to, kind, transit, out, stop)
			local S = W.S
			local k = pkey(to.x, to.y, to.z)
			local slab = S.slab_at[k]
			if slab then stop(b, "slab", slab, to); return true end
			-- HandleEventAt runs the FIRST event whose tile and condition match, and only that one.
			for _, ev in ipairs(S.events) do
				local ok = ev.x == to.x and ev.y == to.y and ev.z == to.z and dw.condition(S, ev)
				if ok == nil and (ev.land or ev.stop) then return true end    -- cannot judge it: refuse
				if ok then
					if ev.land then
						local l, p = ev.land, ev.plat or to.p
						local node
						if p >= 0 then node = { x = l[1], y = l[2], z = l[3], p = p, m = to.m }
						else
							node = dw.ground(W, l[1], l[2], l[3], to.m)
							if not node then return true end
						end
						local t = transit or {}
						t[#t + 1] = fkey(to.x, to.y, to.z, to.p < 0)
						out(b, node, "ferry", t)
						return true
					elseif ev.stop then return true
					end
					break                                    -- a story script: an ordinary arrival
				end
			end
			local pass = C.PASSAGES[S.map]
			if pass and to.x == pass.x and to.y == pass.y and to.z == pass.z and b == pass.button
				and (S.progress or -1) >= pass.progress then
				stop(b, "passage", pass, to)
				return true
			end
			return false
		end

		function dw.ground_moves(W, n, b, out, stop)
			local S, fs, cache = W.S, W.fs, W.cache
			local d = STEPD[b]
			local m = n.m
			-- Gap jumps and ledges. The Giratina room's Cynthia rule (DistWorld_IsBlockedByCynthia):
			-- after the battle the jump whose trigger is (15,15) going south is refused.
			if not (S.map == C.GIRATINA and S.progress == 14 and b == 1 and n.x == 15 and n.z + 1 == 15) then
				local span, lx, lz, ly, lm = ledge_jump(fs, n.x, n.z, b, cache, m & 3, n.f, m)
				if span then
					local to = { x = lx, y = ground_y(ly), z = lz, p = -1, m = lm, f = ly }
					if not dw.occupied(S, lx, to.y, lz, W.skip) then
						local t = {}
						for hop = 1, span - 1 do t[hop] = fkey(n.x + d[1] * hop, n.y, n.z + d[2] * hop, true) end
						if not dw.arrive(W, n, b, to, "jump", t, out, stop) then out(b, to, "jump", t) end
					end
					return
				end
			end
			local nx, nz = n.x + d[1], n.z + d[2]
			local solid = C.SOLID[S.map]
			if solid and solid.x == nx and solid.z == nz then return end
			local ok, ny, nm = step_ok(fs, n.x, n.z, b, cache, n.f, nil, m)
			if ok then
				local to = { x = nx, y = ground_y(ny), z = nz, p = -1, m = nm, f = ny }
				if dw.occupied(S, nx, to.y, nz, W.skip) then return end
				if not dw.arrive(W, n, b, to, "step", nil, out, stop) then out(b, to, "step") end
				return
			end
			-- Surf: facing water from the shore while walking (Field_TileBehaviorToScript).
			if W.surf and (m & 3) == 0 then
				local a = tile_attrs(fs, nx, nz, cache)
				if a and terrain.is_water(a) and not dw.occupied(S, nx, n.y, nz, W.skip) then
					local f = terrain.height(fs, nx, nz, n.f, cache)
					if f then stop(b, "surf", { x = nx, y = ground_y(f), z = nz, p = -1, m = 2, f = f }) end
				end
			end
		end

		function dw.platform_moves(W, n, b, kind, v, out, stop)
			local S = W.S
			local x, y, z = n.x + v[1], n.y + v[2], n.z + v[3]
			local p = n.p
			local a = dw.pattr(S, p, x, y, z)
			-- Off the current floor platform: the first FLOOR template holding the tile takes over
			-- (SetMovement_DistortionFloor and its permissive kind test at 0x0224C354). Walls and
			-- the ceiling never hand over.
			if a == 0xFFFE and kind == 0 then
				local other = dw.plat_at(S, x, y, z, nil) and dw.plat_at(S, x, y, z, 0)
				if other then p, a = other, dw.pattr(S, other, x, y, z) end
			end
			if a == nil or a == 0xFFFF or a == 0xFFFE then return end
			local behavior, surfing = a & 0xFF, (n.m & 3) == 2
			-- Gap jump on a floating floor: the jump-twice behavior for this button, 3 tiles.
			if kind == 0 and not surfing and LEDGE_SPAN[behavior] == 3 and LEDGE[behavior] == STEPNAME[b] then
				local lx, lz = n.x + v[1] * 3, n.z + v[3] * 3
				local lp = dw.pattr(S, p, lx, n.y, lz) == 0xFFFE and dw.plat_at(S, lx, n.y, lz, 0) or p
				local la = dw.pattr(S, lp, lx, n.y, lz)
				if la and la < 0xFFFE and (la & ATTR_COLLIDE) == 0 and not dw.occupied(S, lx, n.y, lz, W.skip) then
					local to = { x = lx, y = n.y, z = lz, p = lp, m = n.m }
					local t = { fkey(n.x + v[1], n.y, n.z + v[3]), fkey(n.x + v[1] * 2, n.y, n.z + v[3] * 2) }
					if not dw.arrive(W, n, b, to, "jump", t, out, stop) then out(b, to, "jump", t) end
				end
				return
			end
			if (a & ATTR_COLLIDE) ~= 0 then return end
			local water = SURFABLE[behavior] == true
			if dw.occupied(S, x, y, z, W.skip) then return end
			if water and not surfing then
				if W.surf then stop(b, "surf", { x = x, y = y, z = z, p = p, m = 2 }) end
				return
			end
			if surfing and not water then return end       -- leaving the water on a platform: not modelled
			local to = { x = x, y = y, z = z, p = p, m = n.m }
			if not dw.arrive(W, n, b, to, "step", nil, out, stop) then out(b, to, "step") end
		end

		-- The world a search runs in.
		function dw.world(fs, S, cache)
			cache.dw_twice, cache.dw_ground = true, true
			return { fs = fs, S = S, cache = cache, surf = PM.field_move_badge(A.FieldMovesCheckSurf) == true }
		end

		-- Breadth-first over every node the player can reach as they are now: positions stood on,
		-- tiles faced (for people and objects), and the stops reached. Bounded; `complete` says
		-- whether the whole floor was seen.
		-- ⛔ IT DOES NOT CROSS WATER, the rule everywhere else (reach_from and pf_astar move with the
		-- player's own motion, and walking never enters water): on land you see the land you are on,
		-- its Surf spots included, and nothing beyond them. A Surf move only records where it could be
		-- used (`surfs`), which is how water on a platform gets its Surf spot (dw.platform_surf).
		function dw.flood(W)
			local seen, faced, faced2, stops, shore, surfs = {}, {}, {}, {}, {}, {}
			local start = dw.start(W.S)
			local q, head, mark = { start }, 1, { [nkey(start)] = true }
			local complete, cur = true, nil
			local function add(_, to)
				local k = nkey(to)
				if not mark[k] then mark[k] = true; q[#q + 1] = to end
			end
			local function stop(b, kind, data, to)
				stops[kind] = stops[kind] or {}
				stops[kind][#stops[kind] + 1] = { data = data, at = to }
				if kind == "surf" then surfs[#surfs + 1] = { n = cur, b = b, w = data } end
			end
			while head <= #q do
				if head > C.FLOOD then complete = false; break end
				local n = q[head]; head = head + 1
				cur = n
				seen[pkey(n.x, n.y, n.z)] = true
				if n.p < 0 and (n.m & 3) == 0 then shore[tkey(n.x, n.z)] = true end
				local kind = n.p < 0 and C.GROUND or W.S.plats[n.p].kind
				for b = 0, 3 do
					local v = W.S.steps[kind][b]
					faced[pkey(n.x + v[1], n.y + v[2], n.z + v[3])] = true
					faced2[tkey(n.x + v[1], n.z + v[3])] = true
				end
				dw.moves(W, n, add, stop)
			end
			return { seen = seen, faced = faced, faced2 = faced2, stops = stops, shore = shore, surfs = surfs, complete = complete }
		end

		-- Surf spots for water on a platform (the B4F ceiling), which terrain.surf_spots cannot see:
		-- it reads the land data. Same shape and rule as there, one entry per body of water: every
		-- tile the flood stood on facing that water, as {stand x, z, water x, z, y = stand height,
		-- b = the button that faces it}. Ground water keeps terrain.surf_spots.
		function dw.platform_surf(S, F)
			local body, bodies = {}, {}
			for _, s in ipairs(F.surfs) do
				local w = s.w
				if w.p >= 0 then
					local k = pkey(w.x, w.y, w.z)
					local id = body[k]
					if not id then
						-- Flood this platform's water from here, by the platform's own steps.
						id = #bodies + 1
						bodies[id] = { first = k, ends = {} }
						body[k] = id
						local q, h = { w }, 1
						local steps = S.steps[S.plats[w.p].kind]
						while h <= #q and h <= C.FLOOD do
							local n = q[h]; h = h + 1
							for b = 0, 3 do
								local v = steps[b]
								local x, y, z = n.x + v[1], n.y + v[2], n.z + v[3]
								local nk = pkey(x, y, z)
								local a = not body[nk] and dw.pattr(S, w.p, x, y, z)
								if a and a < 0xFFFE and (a & ATTR_COLLIDE) == 0 and SURFABLE[a & 0xFF] == true then
									body[nk] = id; q[#q + 1] = { x = x, y = y, z = z }
								end
							end
						end
					end
					local e = bodies[id].ends
					e[#e + 1] = { s.n.x, s.n.z, w.x, w.z, y = s.n.y, b = s.b }
				end
			end
			local out = {}
			for _, bd in ipairs(bodies) do
				local best, bdist
				for _, e in ipairs(bd.ends) do
					local d = math.abs(e[1] - S.x) + math.abs(e[2] - S.z)
					if not bdist or d < bdist then best, bdist = e, d end
				end
				out[#out + 1] = { name = HM_NAME.surf, key = "dwsurf" .. bd.first, x = best[1], z = best[2],
					surf = bd.ends, dw = { found = true } }
			end
			return out
		end

		-- ── On the water: only what the water reaches, and the ways off it ─────────────────────────
		-- The same rule as everywhere else (terrain.afloat, the player's choice): while surfing, the
		-- lists keep what can be reached without leaving the water, and the ways ashore are added to
		-- Transitions, one per landmass you could walk around on, named by the place. Here the water
		-- is whatever this floor's own moves keep afloat (the ground's water and the B4F ceiling's),
		-- and a landing is every move that ends walking.
		function dw.afloat(W)
			local start = dw.start(W.S)
			local faced, faced2, stops, landings = {}, {}, {}, {}
			local q, head, mark = { start }, 1, { [nkey(start)] = true }
			local function add(_, to)
				if (to.m & 3) ~= 2 then
					if to.p < 0 then landings[nkey(to)] = to end
					return
				end
				local k = nkey(to)
				if not mark[k] then mark[k] = true; q[#q + 1] = to end
			end
			local function stop(_, kind, data) stops[kind] = stops[kind] or {}; stops[kind][#stops[kind] + 1] = data end
			while head <= #q do
				if head > C.FLOOD then return nil end
				local n = q[head]; head = head + 1
				local kind = n.p < 0 and C.GROUND or W.S.plats[n.p].kind
				for b = 0, 3 do
					local v = W.S.steps[kind][b]
					faced[pkey(n.x + v[1], n.y + v[2], n.z + v[3])] = true
					faced2[tkey(n.x + v[1], n.z + v[3])] = true
				end
				dw.moves(W, n, add, stop)
			end
			-- Group the landings by the land you could walk between them on (no Surf, no rides).
			local walk = { fs = W.fs, S = W.S, cache = W.cache, surf = false }
			local keys = {}
			for k in pairs(landings) do keys[#keys + 1] = k end
			table.sort(keys)
			local grouped, entries, name = {}, {}, place_name(W.S.map) or ""
			for _, k in ipairs(keys) do
				if not grouped[k] then
					local land, lq, lh = { [k] = true }, { landings[k] }, 1
					while lh <= #lq do
						if lh > C.FLOOD then return nil end
						local n = lq[lh]; lh = lh + 1
						dw.moves(walk, n, function(_, to, how)
							local tk = nkey(to)
							if how ~= "ferry" and how ~= "point" and to.p < 0 and not land[tk] then land[tk] = true; lq[#lq + 1] = to end
						end, function() end)
					end
					local spots = {}
					for _, k2 in ipairs(keys) do
						if not grouped[k2] and land[k2] then
							grouped[k2] = true
							local l = landings[k2]
							spots[#spots + 1] = { l.x, l.z, l.y }
						end
					end
					entries[#entries + 1] = { name = name, key = "land" .. k, spots = spots, landing = true }
				end
			end
			return { faced = faced, faced2 = faced2, stops = stops, entries = entries }
		end

		-- Least presses (a turn costs 1, a step KSTEP), Dijkstra over node + last button. `goal(n)`
		-- answers a button to face (or true) when n finishes the route; `want(kind, data)` accepts a
		-- stop as the finish. Returns the path as moves and how it ends.
		function dw.search(W, goal, want)
			local start = dw.start(W.S)
			local heap, nodes, best, prev = {}, {}, {}, {}
			local function push(id, c)
				heap[#heap + 1] = { id, c }
				local i = #heap
				while i > 1 do
					local up = i // 2
					if heap[up][2] <= heap[i][2] then break end
					heap[up], heap[i] = heap[i], heap[up]; i = up
				end
			end
			local function pop()
				local top = heap[1]
				local last = table.remove(heap)
				if #heap > 0 then
					heap[1] = last
					local i = 1
					while true do
						local l, r, s = i * 2, i * 2 + 1, i
						if heap[l] and heap[l][2] < heap[s][2] then s = l end
						if heap[r] and heap[r][2] < heap[s][2] then s = r end
						if s == i then break end
						heap[s], heap[i] = heap[i], heap[s]; i = s
					end
				end
				return top
			end
			local sid = nkey(start) * 5 + 4
			nodes[sid], best[sid] = { n = start, b = 4 }, 0
			push(sid, 0)
			local expanded = 0
			while #heap > 0 do
				local top = pop()
				local id, c = top[1], top[2]
				if c == best[id] then
					local cur = nodes[id]
					local face = goal(cur.n)
					if face then return dw.path(prev, nodes, id), { face = face ~= true and face or nil } end
					expanded = expanded + 1
					if expanded > C.LIMIT then return nil, "limit" end
					local finish
					local function edge(b, to, kind, transit, extra)
						local cost = c + C.KSTEP * (kind == "ferry" and 2 or 1) + ((cur.b ~= 4 and cur.b ~= b) and 1 or 0)
						local nid = nkey(to) * 5 + b
						if best[nid] == nil or cost < best[nid] then
							best[nid], nodes[nid] = cost, { n = to, b = b }
							prev[nid] = { id, b, kind, transit }
							push(nid, cost)
						end
					end
					-- A route never crosses water either: Surf is a stop it does not take.
					local function stop(b, kind, data, to)
						if not finish and want(kind, data, cur.n, b) then finish = { b = b, kind = kind, data = data, to = to } end
					end
					dw.moves(W, cur.n, edge, stop)
					if finish then
						local path = dw.path(prev, nodes, id)
						return path, { stop = finish }
					end
				end
			end
			return nil, "exhausted"
		end

		function dw.path(prev, nodes, id)
			local path = {}
			while prev[id] do
				local p = prev[id]
				table.insert(path, 1, { b = p[2], kind = p[3], transit = p[4], to = nodes[id].n })
				id = p[1]
			end
			return path
		end

		-- The route the follower walks: one tile per press (keyed in three dimensions), a run of the
		-- same button spoken once. A path stops at its first Surf: the move is named on arrival and
		-- the route re-plans afloat once the Surf script hands the frame back.
		function dw.route(W, entry, path, finish)
			local S = W.S
			local start = dw.start(S)
			local function yfx(n) return n.f or n.y * 0x10000 end
			local tiles = { { start.x, start.z, yfx(start), start.m, k = fkey(start.x, start.y, start.z, start.p < 0) } }
			local moves, transit, crossings, face, ride = {}, {}, {}, finish.face, nil
			for _, mv in ipairs(path) do
				moves[#moves + 1] = mv
				local i = #moves
				crossings[i] = {}
				for _, k in ipairs(mv.transit or {}) do transit[k], crossings[i][k] = true, true end
				local n = mv.to
				tiles[#tiles + 1] = { n.x, n.z, yfx(n), n.m, k = fkey(n.x, n.y, n.z, n.p < 0) }
			end
			local stop = finish.stop
			if stop then
				if stop.kind == "slab" then
					-- The last press steps onto it, which is the ride itself; it has its own sound, so
					-- arriving is silent (the player, 4 November).
					moves[#moves + 1] = { b = stop.b, kind = "step", to = stop.to }
					ride = true
					crossings[#moves] = {}
					tiles[#tiles + 1] = { stop.to.x, stop.to.z, yfx(stop.to), stop.to.m, k = fkey(stop.to.x, stop.to.y, stop.to.z, stop.to.p < 0) }
				else face = stop.b end
			end
			-- Stepping onto a story scene starts it: no arrival line either (the player, 4 November).
			if entry.dw and entry.dw.scene then ride = true end
			local segs, i = {}, 1
			while i <= #moves do
				local j = i
				while j <= #moves and moves[j].b == moves[i].b and (j == i or moves[j - 1].kind ~= "ferry") do j = j + 1 end
				segs[i] = (j - i) .. " " .. PFWORD[moves[i].b]
				i = j
			end
			local at_tile = {}
			for n, t in ipairs(tiles) do
				at_tile[t.k] = at_tile[t.k] or {}
				at_tile[t.k][#at_tile[t.k] + 1] = n
			end
			return { name = entry.label or entry.name, tiles = tiles, at_tile = at_tile, transit = transit,
				crossings = crossings, segs = segs, idx = 1, total = #moves, partial = false,
				key = entry.key, entry = entry, dw = true, face = face, ride = ride }
		end

		-- Where the player stands, as the follower keys it.
		function dw.here(fs)
			local pa = u32(fs + FS_AVATAR)
			local mo = inram(pa) and u32(pa + PA_OBJ)
			if not (mo and inram(mo + 0x6F)) then return nil end
			return fkey(s32(mo + 0x64), s32(mo + 0x68) // 2, s32(mo + 0x6C), (u32(pa) & 0x1F00) == 0x100)
		end

		-- What finishing at an entry means. Slabs, slides and passages are stops; everything else is
		-- standing beside it and facing it (an interaction spot only from the sides it accepts).
		function dw.goal(S, entry)
			local g = entry.dw
			if g and g.slab then
				return function() return nil end,
					function(kind, data) return kind == "slab" and data.x == g.slab.x and data.y == g.slab.y and data.z == g.slab.z end
			elseif g and g.slide then
				return function() return nil end, function(kind) return kind == "slide" end
			elseif g and g.passage then
				-- Like a door: stop on the tile before it, facing it; the player's own step goes through
				-- (the player, 4 November). A route never crosses the passage tile itself (dw.arrive).
				local pass = g.passage
				local v = S.steps[C.GROUND][pass.button]
				local open = (S.progress or -1) >= pass.progress       -- B7F's opens after the battle
				-- Standing ON the passage tile counts too: the warp drops the player there, and pressing
				-- toward the passage from it fires as well (DistWorld_HandlePlayerMovementEnd), so it is
				-- "You're there, 1 down", not a detour off and back (the player, 4 November).
				return function(n)
					if not open or n.p >= 0 or n.y ~= pass.y then return nil end
					if (n.x + v[1] == pass.x and n.z + v[3] == pass.z) or (n.x == pass.x and n.z == pass.z) then return pass.button end
					return nil
				end, function() return false end
			elseif g and g.scene then
				-- Stepping onto the spot plays the scene.
				return function(n)
					for _, t in ipairs(g.scene) do
						if n.x == t[1] and n.y == t[2] and n.z == t[3] then return true end
					end
					return nil
				end, function() return false end
			end
			-- A way ashore: finish walking on any of its landing tiles.
			if entry.landing and entry.spots then
				return function(n)
					if n.p >= 0 or (n.m & 3) ~= 0 then return nil end
					for _, sp in ipairs(entry.spots) do
						if n.x == sp[1] and n.z == sp[2] and (sp[3] == nil or n.y == sp[3]) then return true end
					end
					return nil
				end, function() return false end
			end
			-- A Surf spot (or a Rock Climb end) is {stand x, z, water x, z} pairs: finish STANDING on a
			-- shore tile, walking, facing its water — not beside the shore tile (terrain.surf_spots).
			local ends = entry.surf or entry.climb
			if ends then
				return function(n)
					if (n.m & 3) ~= 0 then return nil end
					for _, e in ipairs(ends) do
						if e.b then
							if n.p >= 0 and n.x == e[1] and n.z == e[2] and n.y == e.y then return e.b end
						elseif n.p < 0 and n.x == e[1] and n.z == e[2] then
							for b = 0, 3 do
								if STEPD[b][1] == e[3] - e[1] and STEPD[b][2] == e[4] - e[2] then return b end
							end
						end
					end
					return nil
				end, function() return false end
			end
			-- ⛔ A PERSON IS WHERE THEY ARE NOW, not where the list saw them. B7F's scene moves Cynthia one
			-- tile west and walks Cyrus into the tile she left; a re-plan aimed at her listed tile ended
			-- facing Cyrus ("Arrived at Cynthia, 1 up", then his battle). Read the object itself.
			local ex, ey, ez = entry.x, nil, entry.z
			if entry.actor and inram(entry.actor + 0x6F) and (u32(entry.actor) & MO_INUSE) ~= 0 then
				ex, ey, ez = s32(entry.actor + MO_X), s32(entry.actor + 0x68) // 2, s32(entry.actor + MO_Z)
			end
			local allowed
			if entry.bg_stand then
				allowed = {}
				for _, s in ipairs(entry.bg_stand) do
					for b = 0, 3 do
						if STEPD[b][1] == -s[1] and STEPD[b][2] == -s[2] then allowed[b] = true end
					end
				end
			end
			-- ⛔ THE FACED TILE MUST MATCH EXACTLY, HEIGHT INCLUDED (Field_DistortionInteract: player
			-- y + step == object y / 2, on the ground as on a wall). One tile of slack stopped a route
			-- on the B2F wall one tile below Cynthia, where "1 right" faced bare wall.
			local function goal(n)
				local kind = n.p < 0 and C.GROUND or S.plats[n.p].kind
				for b = 0, 3 do
					local v = S.steps[kind][b]
					if n.x + v[1] == ex and n.z + v[3] == ez and (not allowed or allowed[b])
						and (ey == nil and v[2] == 0 or ey ~= nil and n.y + v[2] == ey) then
						return b
					end
				end
				return nil
			end
			return goal, function() return false end
		end

		-- pf_plan's answer in the Distortion World.
		function dw.plan(fs, px, pz, entry, cache)
			local S = dw.sys(fs, cache)
			if not S then return nil, "terrain" end                 -- dw.sys named its reason
			local _, occ_ok = dw.occupants(S)
			if not occ_ok then dbg("Distortion World route: object manager unreadable"); return nil, "terrain" end
			local W = dw.world(fs, S, cache)
			if entry.actor and u32(entry.actor + MO_GFX) == GFX_HM_LO and (S.map == C.B5F or S.map == C.B6F) then
				return dw.puzzle(W, entry)
			end
			local goal, want = dw.goal(S, entry)
			-- "here" carries a button only when there is one to face; a landing has none.
			local here = goal(dw.start(S))
			if here then return nil, "here", math.type(here) == "integer" and here or nil end
			local path, how = dw.search(W, goal, want)
			if not path then dbg("Distortion World route to " .. (entry.label or entry.name) .. ": " .. how); return nil, how end
			return dw.route(W, entry, path, how)
		end

		-- ── The boulder puzzle (B5F holes, B6F pits) ─────────────────────────────────────────────
		-- A boulder walked into moves one tile when the far tile is clear, or, only here, when it is a
		-- fall location (ov5_021DFF1C -> DistWorld_WillBoulderBeAtFallLocation; sBoulderFallLocations,
		-- read live: u32 map, s16 x, s16 z, u32 flag). On B5F every hole drops the boulder to B6F. On
		-- B6F a pit with a flag is the right one (its bit in the persisted puzzle word turns on when
		-- filled); a pit without (-1) sends the boulder back to B5F, so it is never a destination.
		-- The plan is the fewest pushes, then the fewest steps, to any open target; only the first
		-- push is handed out and each push re-plans, as the Strength planner does.
		function dw.falls(S)
			local holes = {}
			for i = 0, 31 do
				local e = A.DistWorldBoulderFalls + i * 0xC
				local map = u32(e)
				if map == MH_COUNT then return holes end
				if not C.MAPS[map] then return nil end
				if map == S.map then
					local flag = u32(e + 8)
					local good = S.map == C.B5F or flag < 32
					local filled = flag < 32 and (S.puzzle >> flag) & 1 == 1
					holes[tkey(s16(e + 4), s16(e + 6))] = { x = s16(e + 4), z = s16(e + 6), good = good and not filled }
				end
			end
			return nil
		end

		-- The local ids of the boulders that sit in a correct pit: this floor's object events
		-- (sMapObjectEvents; DistWorldObjectEvent = u16 flagCond, u16 value, u16, u16, then the
		-- ObjectEvent: localID +0x08, graphicsID +0x0A) wearing the boulder and shown only once a
		-- CORRECT pit's flag is set (FLAG_COND_BOULDER_PUZZLE_TRUE with a flag sBoulderFallLocations
		-- gives a pit; the boulders still outside use the same condition with their own flags). ⛔ A SETTLED BOULDER IS NOT ON ITS PIT:
		-- the push walks it onto the pit, then DistWorldFallingBoulder_TickToCorrectPit moves it one tile
		-- further and renames it to this id; on reload they spawn beyond the pits, two tiles down. The
		-- id is the game's own marker, so it is what says a boulder is done.
		function dw.settled(map)
			dw.settled_ids = dw.settled_ids or {}
			if dw.settled_ids[map] ~= nil then return dw.settled_ids[map] or nil end
			dw.settled_ids[map] = false
			local pits = {}
			for i = 0, 31 do
				local e = A.DistWorldBoulderFalls + i * 0xC
				local id = u32(e)
				if id == MH_COUNT then break end
				if not C.MAPS[id] then return nil end
				if id == map and u32(e + 8) < 32 then pits[u32(e + 8)] = true end
			end
			for i = 0, 15 do
				local e = A.DistWorldMapObjectEvents + i * 8
				local id = u32(e)
				if id == MH_COUNT then break end
				if not C.MAPS[id] or not ov9(u32(e + 4)) then return nil end
				if id == map then
					local ids, list = {}, u32(e + 4)
					for k = 0, 63 do
						local ev = u32(list + k * 4)
						if ev == 0 then dw.settled_ids[map] = ids; return ids end
						if not ov9(ev) then return nil end
						if u16(ev) == 2 and pits[u16(ev + 2)] and u16(ev + 0xA) == GFX_HM_LO then ids[u16(ev + 8)] = true end
					end
					return nil
				end
			end
			dw.settled_ids[map] = {}
			return dw.settled_ids[map]
		end

		function dw.puzzle(W, entry)
			local S, fs, cache = W.S, W.fs, W.cache
			local rock = entry.actor
			if (u32(rock) & MO_INUSE) == 0 or u32(rock + MO_MAPID) ~= S.map or u32(rock + MO_GFX) ~= GFX_HM_LO then
				return nil, "done"
			end
			local settled = dw.settled(S.map)
			if not settled then dbg("Distortion World puzzle: object event table unreadable"); return nil, "terrain" end
			if settled[u32(rock + MO_LOCALID)] then return nil, "done" end
			local holes = dw.falls(S)
			if not holes then dbg("Distortion World puzzle: fall table unreadable"); return nil, "terrain" end
			local bx, bz, by = s32(rock + MO_X), s32(rock + MO_Z), s32(rock + 0x74)
			-- Walking graph with the boulder lifted out; other objects stay where they are.
			local G = { ids = {}, nodes = {}, adj = {} }
			local start = dw.start(S)
			if start.p >= 0 or (start.m & 3) ~= 0 then dbg("Distortion World puzzle: not walking on the ground"); return nil, "terrain" end
			local function gid(n)
				local k = nkey(n)
				local id = G.ids[k]
				if id then return id, false end
				id = #G.nodes + 1
				G.ids[k], G.nodes[id] = id, n
				return id, true
			end
			local sid = gid(start)
			local q, head = { sid }, 1
			local W2 = { fs = fs, S = S, cache = cache, surf = false, skip = rock }
			local rkey = tkey(bx, bz)
			while head <= #q do
				if #G.nodes > 20000 then dbg("Distortion World puzzle: walking graph too large"); return nil, "limit" end
				local id = q[head]; head = head + 1
				local n = G.nodes[id]
				local out = {}
				dw.moves(W2, n, function(b, to, kind, transit)
					if to.p < 0 and kind ~= "ferry" and kind ~= "point" then
						local cross = { tkey(to.x, to.z) }
						for _, k in ipairs(transit or {}) do cross[#cross + 1] = flat(k) end
						local tid, new = gid(to)
						out[#out + 1] = { tid, b, cross }
						if new then q[#q + 1] = tid end
					end
				end, function() end)
				G.adj[id] = out
			end
			-- The player tiles reachable with the boulder at bk, from node `from`.
			local function region(bk, from)
				local seen, list, i = { [from] = true }, { from }, 1
				while i <= #list do
					local id = list[i]; i = i + 1
					for _, e in ipairs(G.adj[id] or {}) do
						local blocked = false
						for _, k in ipairs(e[3]) do
							if k == bk then blocked = true; break end
						end
						if not blocked and not seen[e[1]] then seen[e[1]] = true; list[#list + 1] = e[1] end
					end
				end
				return seen
			end
			local at = {}
			for id, n in ipairs(G.nodes) do at[tkey(n.x, n.z)] = at[tkey(n.x, n.z)] or id end
			-- Breadth-first over boulder positions (pushes), each with the region the player is in.
			local visited, queue, qh = {}, { { bx, bz, by, sid, nil } }, 1
			visited[rkey .. ":" .. sid] = true
			while qh <= #queue do
				if qh > 4000 then dbg("Distortion World puzzle: too many boulder positions"); return nil, "limit" end
				local cur = queue[qh]; qh = qh + 1
				local cx, cz, cy, from = cur[1], cur[2], cur[3], cur[4]
				local reg = region(tkey(cx, cz), from)
				for dir = 0, 3 do
					local d = STEPD[dir]
					local sx, sz = cx - d[1], cz - d[2]
					local sid2 = at[tkey(sx, sz)]
					if sid2 and reg[sid2] then
						local tx, tz = cx + d[1], cz + d[2]
						local hole = holes[tkey(tx, tz)]
						local ny
						if hole then
							if hole.good then
								local first = cur[5] or { x = sx, z = sz, dir = dir }
								return dw.push_route(W, entry, first)
							end
						elseif not dw.occupied(S, tx, ground_y(cy), tz, rock) then
							local blocked = {}
							ny = terrain.strength.push_ok(fs, cx, cz, cy, dir, blocked, cache)
						end
						if ny then
							local nid = at[tkey(cx, cz)]
							local vk = tkey(tx, tz) .. ":" .. (nid or 0)
							if nid and not visited[vk] then
								visited[vk] = true
								queue[#queue + 1] = { tx, tz, ny, nid, cur[5] or { x = sx, z = sz, dir = dir } }
							end
						end
					end
				end
			end
			dbg("Distortion World puzzle: no sequence of pushes reaches an open pit")
			return nil, "exhausted"
		end

		-- Walk to the pushing tile; arriving names Strength until it is on, then the press.
		function dw.push_route(W, entry, first)
			local S = W.S
			local goal = function(n) return n.p < 0 and n.x == first.x and n.z == first.z and true or nil end
			local start = dw.start(S)
			local path, how
			if start.x == first.x and start.z == first.z then path, how = {}, {}
			else path, how = dw.search(W, goal, function() return false end) end
			if not path then dbg("Distortion World puzzle: no walk to the pushing tile: " .. how); return nil, how end
			local r = dw.route(W, entry, path, { face = first.dir })
			r.face = first.dir
			r.strength = { dir = first.dir, need = terrain.strength.active() ~= true }
			return r
		end

		-- The Transitions this floor adds: slabs present now, the waterfall slide, the passage and
		-- the map-object portals.
		function dw.entries(fs, S)
			local out = {}
			for _, s in ipairs(S.slabs) do
				out[#out + 1] = { name = dw.text.slab .. " " .. (s.dir == 0 and dw.text.up or dw.text.down),
					key = s.key, x = s.x, z = s.z, dw = { slab = s } }
			end
			local slide = C.SLIDES[S.map]
			if slide then
				out[#out + 1] = { name = HM_NAME.waterfall .. " " .. dw.text[slide.word], key = "DW",
					x = slide.x + 1, z = (slide.z0 + slide.z1) // 2, dw = { slide = slide } }
			end
			-- Giratina's room: the next story scene, so the way forward is listed before Giratina is
			-- there to walk to (the player's choice, 4 November: this room only, the next scene only).
			-- Its conditions are exact progress values, so the scenes that can play now are one beat.
			if S.map == C.GIRATINA then
				local tiles, best, bd = {}, nil, nil
				for _, ev in ipairs(S.events) do
					if ev.scene and dw.condition(S, ev) == true then
						tiles[#tiles + 1] = { ev.x, ev.y, ev.z }
						local d = math.abs(ev.x - S.x) + math.abs(ev.z - S.z)
						if not bd or d < bd then best, bd = ev, d end
					end
				end
				if best then
					out[#out + 1] = { name = dw.text.event, key = "DE", x = best.x, z = best.z, dw = { scene = tiles }, objects = true }
				end
			end
			local pass = C.PASSAGES[S.map]
			if pass and (S.progress or -1) >= pass.progress then
				out[#out + 1] = { name = dw.text.passage, key = "DP", x = pass.x, z = pass.z, dw = { passage = pass } }
			end
			return out
		end

		-- Kept out of every list here: the preloaded next floor's objects, invisible helpers (the
		-- slab objects, the pit markers; graphics OBJ_EVENT_GFX_INVISIBLE 0x2000) and a boulder that
		-- already sits in a pit (dw.settled). The two portal objects are listed by dw.portals instead.
		function PM.dw_skip(fs, o, gfx)
			local map = map_id(fs)
			if not C.MAPS[map or -1] then return false end
			if u32(o + MO_MAPID) ~= map or gfx == 0x2000 then return true end
			if gfx == GFX_HM_LO and map == C.B6F then
				local settled = dw.settled(map)
				if settled and settled[u32(o + MO_LOCALID)] then return true end
			end
			return false
		end
		function dw.portals(fs, S)
			local out, id = {}, C.PORTALS[S.map]
			if not id then return out end
			local mm = u32(fs + FS_OBJMAN)
			local n, arr = s32(mm + MOM_MAX), u32(mm + MOM_ARRAY)
			if n ~= MOM_EXPECT or not inram(arr + n * MO_STRIDE - 1) then return out end
			for i = 0, n - 1 do
				local o = arr + i * MO_STRIDE
				if (u32(o) & MO_INUSE) ~= 0 and (u32(o) & MO_HIDDEN) == 0 and u32(o + MO_MAPID) == S.map
					and u32(o + MO_LOCALID) == id then
					out[#out + 1] = { name = dw.text.portal, key = "O" .. o, x = s32(o + MO_X), z = s32(o + MO_Z), actor = o }
				end
			end
			return out
		end

		-- The lists' reachability here: an entry stays when a route could finish at it, judged by the
		-- same moves the router uses. Anything the flood could not settle stays (fail open).
		function dw.filter(fs, lists, cache)
			local S = dw.sys(fs, cache)
			if not S then return end
			for _, e in ipairs(dw.entries(fs, S)) do
				local c = e.objects and "Objects" or "Transitions"
				lists[c][#lists[c] + 1] = e
			end
			for _, e in ipairs(dw.portals(fs, S)) do lists.Transitions[#lists.Transitions + 1] = e end
			local _, occ_ok = dw.occupants(S)
			if not occ_ok then dbg("nav: Distortion World occupancy unreadable — not filtering"); return end
			local W = dw.world(fs, S, cache)
			if (S.motion & 3) == 2 then
				local A = dw.afloat(W)
				if not A then
					-- Nothing provable means nothing listed afloat (terrain.afloat's rule).
					dbg("nav: Distortion World water flood ran out of room")
					for c in pairs(lists) do lists[c] = {} end
					return
				end
				for c, list in pairs(lists) do
					local keep = {}
					for _, e in ipairs(list) do
						local ok
						if e.dw then ok = e.dw.slide and A.stops.slide ~= nil
						elseif e.actor and inram(e.actor + 0x6B) then ok = A.faced[pkey(e.x, s32(e.actor + 0x68) // 2, e.z)]
						else ok = A.faced2[tkey(e.x, e.z)] end
						if ok then keep[#keep + 1] = e end
					end
					lists[c] = keep
				end
				local px, pz = S.x, S.z
				for _, e in ipairs(A.entries) do
					local best, bd
					for _, sp in ipairs(e.spots) do
						local d = math.abs(sp[1] - px) + math.abs(sp[2] - pz)
						if not bd or d < bd then best, bd = sp, d end
					end
					e.x, e.z = best[1], best[2]
					lists.Transitions[#lists.Transitions + 1] = e
				end
				return true
			end
			local F = dw.flood(W)
			if not F.complete then dbg("nav: Distortion World flood ran out of room — not filtering"); return end
			for _, e in ipairs(dw.platform_surf(S, F)) do lists.HM[#lists.HM + 1] = e end
			local slabs, slide, pass = {}, false, false
			for _, s in ipairs(F.stops.slab or {}) do slabs[s.data.key] = true end
			slide = F.stops.slide ~= nil
			pass = F.stops.passage ~= nil
			for c, list in pairs(lists) do
				local keep = {}
				for _, e in ipairs(list) do
					local ok
					if e.dw and e.dw.scene then
						for _, t in ipairs(e.dw.scene) do ok = ok or F.seen[pkey(t[1], t[2], t[3])] end
					elseif e.dw then ok = e.dw.found or (e.dw.slab and slabs[e.dw.slab.key]) or (e.dw.slide and slide) or (e.dw.passage and pass)
					elseif e.surf or e.climb then
						for _, s in ipairs(e.surf or e.climb) do ok = ok or F.shore[tkey(s[1], s[2])] end
					elseif e.actor and inram(e.actor + 0x6B) then
						ok = F.faced[pkey(e.x, s32(e.actor + 0x68) // 2, e.z)]
					else ok = F.faced2[tkey(e.x, e.z)] end
					if ok then keep[#keep + 1] = e end
				end
				lists[c] = keep
			end
			return true
		end
	end

	local function pf_plan(fs, px, pz, entry, occ, cache)
		cache = cache or {}
		-- The Distortion World plans over its own surfaces, jump points and rides (terrain.dw).
		if terrain.dw.active(fs, cache) then return terrain.dw.plan(fs, px, pz, entry, cache) end
		local target,state,prerequisite = eterna.effective(fs,entry,cache)
		if not target then return nil,"terrain" end
		-- Canalave Gym: plan over floors and platform states; walk the first leg on this floor, ending
		-- on the next platform to ride (silent, like a Pastoria button) or at the goal itself.
		local canalave = terrain.canalave
		if canalave.active(fs, cache) then
			local snap = canalave.snapshot(fs, cache)
			if not snap then return nil, "terrain" end
			local leg, why = canalave.next_leg(fs, px, pz, target, snap, cache)
			if not leg then return nil, why end
			if leg.last and leg.x == px and leg.z == pz then return nil, "here" end
			local r = pf_build(fs, px, pz, leg.x, leg.z, entry.label or entry.name,
				canalave.blocked(snap, leg.occ, leg.key), cache)
			if not r or r.partial then return nil, "terrain" end
			r.key, r.entry = entry.key, entry
			if leg.last then
				r.tx, r.tz = entry.x, entry.z
				if entry.warps or entry.spots or entry.surf or entry.climb or entry.waterfall or entry.door_bg then
					r.tx, r.tz = leg.goal[3] or leg.goal[1], leg.goal[4] or leg.goal[2]
				end
			elseif leg.back then
				r.tx, r.tz, r.reride = leg.back.x, leg.back.z, leg
			else
				r.tx, r.tz, r.lift = leg.x, leg.z, leg
			end
			return r
		end
		-- Snowpoint Gym: every press from where the player rests, slides and walks alike.
		if terrain.snowpoint.active(fs, cache) then
			local r, why = terrain.snowpoint.route(fs, px, pz, entry, target, occ, cache)
			if not r then return nil, why end
			r.key, r.entry, r.tx, r.tz = entry.key, entry, entry.x, entry.z
			if entry.warps or entry.spots or entry.surf or entry.climb or entry.waterfall or entry.door_bg then
				r.tx, r.tz = r.goal[3] or r.goal[1], r.goal[4] or r.goal[2]
			end
			return r
		end
		-- Pastoria Gym: no route at the current level may step on an armed button, and a gym that
		-- cannot be verified is not routed through at all, because a button walked over moves the water.
		-- Both cells are planned in a level cache (see pastoria.level_cache), so a route never stops
		-- at the loading frontier of a two-cell gym.
		local pas, base_occ, gym_cache = nil, occ, cache
		if pastoria.active(fs, cache) then
			pas = pastoria.snapshot(fs, cache)
			local motion = pas and terrain.motion(fs, cache)
			if not pas or motion == nil then return nil, "terrain" end
			occ = pastoria.blocked(pas, occ)
			gym_cache = pastoria.level_cache(pas, pas.level, motion)
		end
		-- Sunyshore Gym: every button is armed, so no route in the current state may cross one, and a
		-- gym that cannot be verified is not routed through at all.
		local suny
		if terrain.sunyshore.active(fs, cache) then
			suny = terrain.sunyshore.snapshot(fs, cache)
			if not suny then return nil, "terrain" end
			occ = terrain.sunyshore.blocked(suny, occ)
		end
		local r,why,reached = pf_plan_direct(fs,px,pz,target,occ,gym_cache)
		-- Cut and Rock Smash: a hypothetical route with those obstacles removed (a cleared tree or rock
		-- leaves its tile open; a boulder does not, so bit 4 stays in the way) stops before the first.
		local current,hm_ok,hm_gates,hm_relaxed,hm_cache
		local function hm_setup()
			if current then return hm_ok end
			local all
			current,hm_ok,all = occupied(fs)
			hm_gates,hm_relaxed,hm_cache = {},{},{}
			for key,gate in pairs(all or {}) do if gate.bit ~= 4 then hm_gates[key] = gate end end
			for key in pairs(current) do if not hm_gates[key] then hm_relaxed[key] = true end end
			for key,value in pairs(cache) do if key ~= "reach" then hm_cache[key] = value end end
			hm_ok = hm_ok and next(hm_gates) ~= nil
			return hm_ok
		end
		local function hm_stop(tiles)
			for i,tile in ipairs(tiles) do
				local gate = hm_gates[tkey(tile[1],tile[2])]
				if gate then
					local before = tiles[i-1]
					-- A jump/slope may cross an actor without a valid interaction stop.
					if not (before and math.abs(before[1]-tile[1])+math.abs(before[2]-tile[2]) == 1) then return nil end
					local stop = pf_build(fs,px,pz,before[1],before[2],entry.label or entry.name,current,{},nil)
					local accepted = false
					-- A pending actor has no interaction height yet; its approaches are judged by the
					-- ground alone (goals_for's discovery form) and the height check below uses rest_y.
					for _,c in ipairs(goals_for(fs,gate,current,px,pz,{},gate.pending)) do
						if c[1] == before[1] and c[2] == before[2] then accepted = true; break end
					end
					local endpoint = stop and stop.tiles[#stop.tiles]
					local actor_y = gate.pending and terrain.rest_y(fs, gate, hm_cache) or s32(gate.actor + 0x74)
					if stop and not stop.partial and accepted and endpoint and actor_y
						and math.modf((endpoint[3] // 8) / 4096) == math.modf((actor_y // 8) / 4096) then
						stop.key,stop.entry,stop.tx,stop.tz = entry.key,entry,gate.x,gate.z
						stop.hm = gate
						return stop
					end
					-- The stop is in a cell not loaded yet: walk the loaded part toward it and re-plan
					-- there, when the obstacle has its height and the stop can be checked.
					if terrain.unloaded(fs, before[1], before[2], cache) then
						local walk = pf_plan_direct(fs,px,pz,{name=entry.label or entry.name,key=entry.key,x=before[1],z=before[2]},current,{})
						if walk and walk.partial then
							walk.key,walk.entry,walk.tx,walk.tz = entry.key,entry,entry.x,entry.z
							return walk
						end
					end
					return nil, "gate"
				end
			end
			return nil, "none"
		end
		-- "terrain" too: with a cell not loaded the live search cannot prove anything, and the
		-- hypothetical is planned on the cartridge's geometry where cells are missing. A partial
		-- hypothetical that crosses no obstacle yet is the walk toward it.
		if not r and (why == "exhausted" or why == "terrain") and hm_setup() then
			local hypothetical = pf_plan_direct(fs,px,pz,target,hm_relaxed,hm_cache)
			if hypothetical then
				local none
				r, none = hm_stop(hypothetical.tiles)
				if not r and none == "none" and hypothetical.partial then r = hypothetical end
				if r then why,reached = nil,nil end
			end
		end
		-- Warp panels within this map (the Galactic HQ): when walking cannot get there, walk onto the
		-- first panel of the shortest chain. Stepping on is silent; the next leg is planned and
		-- spoken after the player lands (pf_follow, the panel intent). A panel under the player's
		-- own feet is taken by stepping off first: a one-step leg that re-plans silently on arrival.
		if not r and (why == "exhausted" or why == "terrain") then
			local hop = terrain.panel_search(fs, px, pz, occ, cache, target)
			if hop and hop.x then
				local name = entry.label or entry.name
				local w
				if hop.x == px and hop.z == pz then
					for dir = 0, 3 do
						local d = STEPD[dir]
						local nx, nz = px + d[1], pz + d[2]
						if not w and not occ[tkey(nx, nz)] and not terrain.traps(fs, cache)[tkey(nx, nz)]
							and step_ok(fs, px, pz, dir, cache) and step_ok(fs, nx, nz, STEPOPP[dir], cache) then
							w = pf_build(fs, px, pz, nx, nz, name, occ, cache)
							if w and (w.partial or w.total ~= 1) then w = nil end
						end
					end
					if w then w.step_off = true end
				else
					w = pf_plan_direct(fs, px, pz, { name = name, key = entry.key, x = hop.x, z = hop.z }, occ, cache)
					if w and not w.partial then w.panel = hop end
				end
				if w then
					w.key, w.entry, w.tx, w.tz = entry.key, entry, hop.x, hop.z
					r, why, reached = w, nil, nil
				end
			end
		end
		-- Strength: only when walking cannot get there. Walk to the far side of the next boulder to
		-- push; arriving there names the move until Strength is on, then the press (pf_follow). The
		-- search counts Cut and Rock Smash obstacles as cleared, since clearing one never closes
		-- anything; when one stands on the walk to the pushing tile, that obstacle comes first.
		-- "terrain" too: the target or the puzzle may lie in a cell that is not loaded, which the
		-- search reads from the cartridge. A refusal then keeps the original answer. And a PARTIAL
		-- route (walking toward a cell that is not loaded) is checked as well: it only says the
		-- unknown might connect, while the search sees the whole room and knows when a boulder has
		-- to move first; then the push plan replaces it.
		local blind = r and r.partial and not r.hm
		if (not r and (why == "exhausted" or why == "terrain")) or blind then
			local strength = terrain.strength
			local push, reason, whole = strength.next_push(fs, px, pz, target, occ, cache)
			local before = r
			if push and push.x then
				local rock, name = push.rock, entry.label or entry.name
				-- The walk to the pushing tile. When it crosses a cell not yet loaded (the tile itself
				-- or only the way to it), the loaded part of the walk planned on the cartridge's
				-- geometry: a partial route, re-planned on arrival as cells load.
				local function walk(o, c)
					local w = pf_build(fs, px, pz, push.x, push.z, name, o, c)
					if w and not w.partial then return w end
					local p = pf_plan_direct(fs, px, pz, { name = name, key = entry.key, x = push.x, z = push.z }, o, c)
					if p and p.partial then return p end
				end
				r = walk(occ, cache)
				if not r and hm_setup() then
					local hypothetical = walk(hm_relaxed, hm_cache)
					if hypothetical then
						local none
						r, none = hm_stop(hypothetical.tiles)
						if not r and none == "none" and hypothetical.partial then r = hypothetical end
					end
				end
				local endpoint = r and not r.hm and not r.partial and r.tiles[#r.tiles]
				if r and r.hm then
					dbg("Strength: " .. r.hm.name .. " first, on the way to the pushing tile")
					why, reached = nil, nil
				elseif r and r.partial then
					dbg("Strength: walking toward a pushing tile in a cell not yet loaded")
					r.key, r.entry, r.tx, r.tz = entry.key, entry, entry.x, entry.z
					why, reached = nil, nil
				elseif endpoint and endpoint[1] == push.x and endpoint[2] == push.z
					and strength.level(endpoint[3]) == strength.level(rock.y) then
					r.key, r.entry, r.tx, r.tz = entry.key, entry, rock.x, rock.z
					r.strength = { dir = push.dir, need = strength.active() ~= true, pushes = push.pushes }
					why, reached = nil, nil
				elseif blind then
					dbg("Strength: no walk to the pushing tile; keeping the partial route")
					r = before
				else
					-- The planner and the router disagree about the walk: a statement about us.
					dbg("Strength: no walk to the pushing tile")
					r, why = nil, "terrain"
				end
			elseif reason == "exhausted" and whole then
				-- No sequence of pushes reaches it anywhere in the room: say so, rather than walk
				-- toward a cell that is not loaded and refuse there.
				r, why = nil, "exhausted"
			elseif blind then
				r = before
			elseif push or reason == "limit" or reason == "terrain" then
				-- {} means the search can walk there while the router could not: a statement about us.
				why = push and "terrain" or reason
			end
		end
		-- Veilstone Gym: walk to the next bag the puzzle needs and stop there; the arrival names the bag.
		-- "terrain" counts too: column 24 is walkable with no floor, so every search touching the
		-- column-23 rail reports an unknown step, which the solver already treats as a wall.
		if not r and (why == "exhausted" or why == "terrain") and veilstone.active(fs) then
			local kick, reason = veilstone.next_kick(fs,px,pz,target,occ,cache)
			if kick and kick.x then
				r = pf_build(fs,px,pz,kick.x,kick.z,entry.label or entry.name,occ,cache)
				if r and not r.partial then
					r.key,r.entry,r.tx,r.tz,r.kick = entry.key,entry,kick.bx,kick.bz,kick
					why,reached = nil,nil
				else r = nil end
			elseif reason == "limit" or reason == "terrain" then why = reason end
		end
		-- Pastoria Gym: walk ONTO the next button the plan needs; stepping there is the press. The
		-- arrival is silent (the player's choice, 2026-10-31) and the shared gym wait resumes once
		-- the water has settled.
		if not r and (why == "exhausted" or why == "terrain") and pas then
			local press, reason = pastoria.next_button(fs,px,pz,target,base_occ,pas,cache)
			if press and press.x then
				r = pf_build(fs,px,pz,press.x,press.z,entry.label or entry.name,pastoria.blocked(pas,base_occ,press.key),gym_cache)
				if r and not r.partial then
					r.key,r.entry,r.tx,r.tz,r.button = entry.key,entry,press.x,press.z,press
					why,reached = nil,nil
				else r = nil end
			elseif reason == "limit" or reason == "terrain" then why = reason end
		end
		-- Sunyshore Gym: walk ONTO the next button (silent, as Pastoria's), or off the one underfoot
		-- when the plan presses it again; the gym wait speaks the next leg once the gears have stopped.
		if not r and (why == "exhausted" or why == "terrain") and suny then
			local press, reason = terrain.sunyshore.next_button(fs,px,pz,target,base_occ,suny,cache)
			if press and press.x then
				r = pf_build(fs,px,pz,press.x,press.z,entry.label or entry.name,terrain.sunyshore.blocked(suny,base_occ,press.key),cache)
				if r and not r.partial and r.total > 0 then
					r.key,r.entry = entry.key,entry
					if press.back then r.tx,r.tz,r.suny_back = press.back.x,press.back.z,press
					else r.tx,r.tz,r.suny_button = press.x,press.z,press end
					why,reached = nil,nil
				else r = nil end
			elseif reason == "limit" or reason == "terrain" then why = reason end
		end
		if r and state ~= nil then
			entry.eterna_script,entry.eterna_id,entry.eterna_fs = u32(entry.actor+MO_SCRIPT),u32(entry.actor+MO_LOCALID),fs
			r.entry,r.key = entry,entry.key
			r.gym_stage,r.gym_prerequisite = state,prerequisite
		end
		return r,why,reached
	end

	local pf = nil                -- the live route, or nil
	-- ⛔ ARMED WHENEVER THIS MODULE LOSES THE FRAME WITH A ROUTE RUNNING (a battle, a conversation, a
	-- menu, a cutscene). Ola asked for this in Gen V and the reason generalises: coming back, he has
	-- not MOVED, so a follower that only speaks on movement leaves him standing in silence with no
	-- instruction until he takes a step in some arbitrary direction. On the first frame we have
	-- control again, re-plan from where he stands and say the next turn.
	local pf_reenter = false

	-- Drive the turn-by-turn. Called every frame this module owns, but does nothing at all unless a
	-- route exists — the `not pf` test is the first thing in it, so the idle cost is one comparison.
	local function pf_follow(fs, px, pz)
		if not pf then return end
		-- Snowpoint Gym: a slide passes tiles it does not stop on, and one that climbs and falls back
		-- passes its own end, so nothing is judged until the game has brought the player to rest.
		-- A Distortion World route keys tiles in three dimensions: on a wall only the height changes.
		local hk = tkey(px, pz)
		if pf.dw then hk = terrain.dw.here(fs); if not hk then return end end
		if pf.slides then
			if pf.slides[pf.idx] and not terrain.snowpoint.at_rest(fs) then return end
		elseif pf.crossings[pf.idx] and pf.crossings[pf.idx][hk] then return end
		local candidates = pf.at_tile[hk]
		local at = candidates and candidates[1]
		if candidates and #candidates > 1 then
			-- Revisited tiles can differ by height, bridge layer or Surf mode.
			-- Match the live movement state before choosing the nearest surface.
			local cache = {}
			local mo, motion = terrain.player_object(fs,cache),terrain.motion(fs,cache)
			if not mo or motion == nil then return end
			local y, best, distance = s32(mo + 0x74), math.huge, math.huge
			at = nil
			for _, n in ipairs(candidates) do
				if pf.tiles[n][4] == motion then
					local dy, dn = math.abs(pf.tiles[n][3] - y), math.abs(n - pf.idx)
					-- A tie of equal distance goes forward: the tile ahead, not the one left behind.
					if dy < best or (dy == best and (dn < distance or (dn == distance and n > at))) then at,best,distance = n,dy,dn end
				end
			end
		end
		-- Snowpoint Gym: the right tile with the wrong snowballs standing is a different puzzle.
		if at and at ~= pf.idx and pf.snow and not terrain.snowpoint.matches(fs, pf, at) then at = nil end
		if at == #pf.tiles then
			if pf.partial then
				local loading, reason = terrain.loading(fs)
				if loading == nil then
					dbg("Platinum route: " .. reason)
					say("Todavía no encuentro ruta hasta " .. (pf.name or "destino")); pf = nil; return
				elseif loading then return end
				local occ, ok = occupied(fs)
				if not ok then return end
				local r = pf_plan(fs, px, pz, pf.entry, occ)
				if r and r.total > 0 then
					pf = r; say(r.segs[1]); return
				elseif r then pf = r
				else
					say("Todavía no encuentro ruta hasta " .. (pf.name or "destino")); pf = nil; return
				end
			end
			if pf.entry.honey and honey.present(fs, pf.entry, {}) ~= true then
				say("Todavía no encuentro ruta hasta " .. (pf.name or "destino")); pf = nil; return
			end
			-- On a warp panel: silent. The warp is a field task, so the module loses the frame and
			-- the panel intent plans the next leg from the landing.
			if pf.panel then
				eterna.intent = terrain.panel_intent(fs, pf)
				pf = nil
				return
			end
			-- Stepped off the panel underfoot: the next leg is the step back onto it.
			if pf.step_off then
				local occ, ok = occupied(fs)
				if not ok then return end                     -- cannot see the room: next frame
				local r, why = pf_plan(fs, px, pz, pf.entry, occ)
				if r then pf = r; if r.segs[1] then say(r.segs[1]) end
				elseif why == "limit" or why == "terrain" then say("Todavía no encuentro ruta hasta " .. (pf.name or "destino")); pf = nil
				else say("No se puede llegar a " .. (pf.name or "destino") .. " desde aquí"); pf = nil end
				return
			end
			-- ⭐ ARRIVING BESIDE SOMETHING IS NOT ARRIVING AT IT (Ola, 2026-09-06: "when we say arrived
			-- at, we should also include a speech thing for where it is... if it's left, right, up or
			-- down"). A route ENDS on a tile you can stand on, and the thing itself is usually the
			-- tile beyond — a person, a sign, a door you have to face. Without this the instruction
			-- runs out one step early and leaves you turning on the spot to find them.
			-- ⚠ AND IT IS THE SAME SENTENCE, not a second one: two speech calls would let the first be
			-- cut off by the second, and the direction is part of what arriving means.
			-- ⚠ THE OFFSET IS ALSO THE HONEST ANSWER WHEN THE TARGET HAS MOVED. Black and White found
			-- this the hard way: people walk, and a gym leader can be relocated by a script, so a
			-- route born a few seconds ago can end beside where somebody USED to be. Saying "3 up and
			-- 1 right" makes that visible instead of sounding like a clean arrival. Same wording as
			-- Black and White's, deliberately — the two games must not describe this differently.
			-- Stepping onto a slab or a passage is the ride itself: silent, like a warp panel.
			if pf.ride then pf = nil; return end
			local off = ""
			if pf.dw then
				if PFWORD[pf.face] then off = ", 1 " .. PFWORD[pf.face] end
			elseif pf.tx and pf.tz and not (pf.tx == px and pf.tz == pz) then
				local parts = {}
				local dx, dz = pf.tx - px, pf.tz - pz
				if dz < 0 then parts[#parts + 1] = (-dz) .. " arriba"
				elseif dz > 0 then parts[#parts + 1] = dz .. " abajo" end
				if dx < 0 then parts[#parts + 1] = (-dx) .. " izquierda"
				elseif dx > 0 then parts[#parts + 1] = dx .. " derecha" end
				if #parts > 0 then off = ", " .. table.concat(parts, " and ") end
			end
			if pf.hm then
				if not pf.hm_wait then
					-- No comma before the direction: "Cut 1 up", "Surf 1 up" (the player, 4 November).
					say(pf.hm.name .. off:sub(2))
					pf.hm_wait = true
				end
				return
			end
			-- Beside a boulder to push: the move name and where the boulder is until Strength is on
			-- ("Strength 1 up", the Cut and Rock Smash wording), then the press alone ("1 up"), which
			-- is an ordinary step's wording because the press is one: the boulder moves and the
			-- player stays. The push and the Strength script are field tasks; on_exit re-plans.
			if pf.strength then
				if not pf.strength_said then
					local line = pf.strength.need and (HM_NAME[0x54] .. off:sub(2)) or off:sub(3)
					if line ~= "" then say(line) end
					pf.strength_said = true
				end
				return
			end
			if pf.reride then
				-- Off the platform: the next step is back onto it, which is the ride. Say which way.
				local b, word = pf.reride.back, nil
				if b.z < pz then word = PFWORD[0] elseif b.z > pz then word = PFWORD[1]
				elseif b.x < px then word = PFWORD[2] else word = PFWORD[3] end
				say("1 " .. word)
				eterna.intent = {entry=pf.entry,fs=fs,canalave=pf.reride.sig,stay={[tkey(px,pz)]=true,[tkey(b.x,b.z)]=true}}
				pf = nil
				return
			end
			if pf.lift then
				-- Stepping onto the platform is the ride. Silent; the gym wait speaks the next leg.
				eterna.intent = {entry=pf.entry,fs=fs,canalave=pf.lift.sig,stay={[tkey(px,pz)]=true}}
				pf = nil
				return
			end
			if pf.button then
				-- Standing on the button is the press; nothing is said. The press script takes the frame,
				-- on_exit arms the re-plan, and the gym wait speaks the next leg once the water settles.
				eterna.intent = {entry=pf.entry,fs=fs,pastoria=pf.button.sig,stay={[tkey(px,pz)]=true}}
				pf = nil
				return
			end
			-- Sunyshore Gym: on the button is the press, silent; off the button underfoot, the next step
			-- is back onto it, so say which way. The gears turn inside the press script, and the gym
			-- wait speaks the next leg when the player has control again.
			if pf.suny_button or pf.suny_back then
				local leg = pf.suny_button or pf.suny_back
				if pf.suny_back then
					local b = leg.back
					say("1 " .. PFWORD[(b.z < pz and 0) or (b.z > pz and 1) or (b.x < px and 2) or 3])
				end
				eterna.intent = {entry=pf.entry,fs=fs,sunyshore=leg.sig,stay={[tkey(px,pz)]=true}}
				if pf.suny_back then eterna.intent.stay[tkey(leg.back.x,leg.back.z)] = true end
				pf = nil
				return
			end
			if pf.kick then
				-- The bag is the tile ahead: walking into it is the kick. The original goal waits for
				-- the slide to finish (the bag task takes the frame, on_exit arms the re-plan).
				say(veilstone.text.bag .. off)
				eterna.intent = {entry=pf.entry,fs=fs,veil=pf.kick.sig}
				pf = nil
				return
			end
			if pf.gym_prerequisite then
				-- Keep the interaction direction in the route; only the selected goal is an arrival.
				say((off ~= "" and off:sub(3) .. ", " or "") .. "A")
				eterna.intent = {entry=pf.entry,state=pf.gym_stage,fs=fs}
			else
				say("Has llegado a " .. (pf.name or "destino") .. off, not (pf.entry and pf.entry.clue))
				eterna.intent = nil
			end
			pf = nil
			return
		end
		-- ⛔ MID-JUMP IS NOT OFF-ROUTE. A ledge jump writes the trigger coordinate as the animation
		-- starts, so for a frame or two he stands on a tile the route never lists as a stopping
		-- place. Treated as a deviation it would re-plan from inside the jump and say
		-- "Recalculating" every single time he hopped a ledge.
		if not at and pf.transit and pf.transit[hk] then return end
		-- ⚠ GOING BACKWARDS COUNTS AS A DEVIATION, deliberately. He is still on the route, but the
		-- instruction he last heard is now wrong about how far is left — and re-planning from where he
		-- stands is both correct and the only thing that gives him a fresh, usable instruction.
		if not at or at < pf.idx then                         -- off the path: re-plan and say so
			-- Snowpoint Gym: a stray press onto the ice slides on; re-plan where it ends.
			if pf.slides and not terrain.snowpoint.at_rest(fs) then return end
			-- Pastoria Gym: the coordinates change when a step STARTS and the button fires when it
			-- ends, so a stray step onto an armed button would re-plan at the old level and then be
			-- overruled by the water. Treat it as a planned press: silent, and the gym wait re-plans.
			if terrain.canalave.active(fs, {}) and pf.entry then
				local snap = terrain.canalave.snapshot(fs, {})
				if snap and terrain.canalave.platform_at(snap, snap.mask, px, pz, snap.floor) then
					eterna.intent = {entry=pf.entry,fs=fs,canalave=snap.sig,stay={[tkey(px,pz)]=true}}
					pf = nil
					return
				end
			end
			if pastoria.active(fs, {}) and pf.entry then
				local snap = pastoria.snapshot(fs, {})
				local b = snap and snap.at[tkey(px, pz)]
				if b and b.level ~= snap.level then
					eterna.intent = {entry=pf.entry,fs=fs,pastoria=snap.sig,stay={[tkey(px,pz)]=true}}
					pf = nil
					return
				end
			end
			-- Sunyshore Gym: the same for any button, since every one is armed.
			if terrain.sunyshore.active(fs, {}) and pf.entry then
				local snap = terrain.sunyshore.snapshot(fs, {})
				if snap and snap.at[tkey(px, pz)] then
					eterna.intent = {entry=pf.entry,fs=fs,sunyshore=snap.sig,stay={[tkey(px,pz)]=true}}
					pf = nil
					return
				end
			end
			-- Rule 9: name where a Distortion World route was left, in three dimensions.
			if pf.dw then
				local mo = terrain.player_object(fs, {})
				dbg(string.format("Distortion World route: off at (%d,%d,%d) state 0x%X motion %s, expected tile %d de %d",
					px, mo and s32(mo + 0x68) // 2 or -1, pz, u32(u32(fs + FS_AVATAR)) & 0x1F00,
					tostring(terrain.motion(fs, {})), pf.idx, #pf.tiles))
			end
			-- Only HERE is the object walk worth doing: following a straight leg needs no occupancy.
			local occ, occ_ok = occupied(fs)
			if not occ_ok then return end                     -- cannot see the room: try again next frame
			local r, why, face = pf_plan(fs, px, pz, pf.entry, occ)
			if r then
				pf = r
				say("Recalculando. " .. (r.segs[1] or ""))
			elseif why == "done" then pf = nil              -- the boulder went down its hole
			elseif why == "here" then
				say("Has llegado a " .. (pf.name or "destino") .. (PFWORD[face] and (", 1 " .. PFWORD[face]) or ""))
				pf = nil
			elseif why == "limit" or why == "terrain" then
				say("Todavía no encuentro ruta hasta " .. (pf.name or "destino"))
				pf = nil
			else
				say("No se puede llegar a " .. (pf.name or "destino") .. " desde aquí")
				pf = nil
			end
			return
		end
		if at ~= pf.idx then
			pf.idx = at
			-- ⚠ SPEAK ONLY AT A CORNER. `segs` has an entry only where a run begins, so walking the
			-- middle of a straight leg says nothing — which is what makes the instruction usable
			-- instead of a metronome.
			if pf.segs[at] then say(pf.segs[at]) end
		end
	end

	-- ── KEEPING THE LIST CURRENT ────────────────────────────────────────────────────────────────
	--
	-- Nothing here runs until a navigation key is pressed. Parsed events and live actors
	-- are refreshed together, because
	-- scripts can relocate an entrance without changing the map header.
	--
	-- ⭐ REACHABILITY IS NOT A REFINEMENT, IT IS THE POINT (Ola, through the whole Gen V arc: "I want
	-- you to only see what you can reach from where you currently are located"). An entry you cannot
	-- walk to is worse than no entry at all — it is a promise the router then breaks, and the player
	-- has no way to tell "that door is behind a wall" from "the tool is wrong".
	-- ⛔ AND THE FILTER FAILS OPEN, DELIBERATELY AND ONLY IN ONE DIRECTION. An entry is dropped only
	-- when we can positively see that none of its approach tiles is in the flood. If the flood could
	-- not be built, or the entry sits on ground we cannot read, it STAYS. Hiding a real exit is the one
	-- mistake this must never make: a door wrongly listed costs one "Can't reach"; a door wrongly
	-- hidden is a way out the player cannot know exists.
	-- ⚠ THE APPROACH TILES, NOT THE ENTRY'S OWN TILE. A doorway is usually a BLOCKED tile you step
	-- into rather than stand on, so its own tile is never in the flood; the tile beside it is what says
	-- whether you can get there. Same for a person, whose tile is occupied by definition.
	-- ⭐ IT ASKS EXACTLY THE QUESTION THE ROUTER WILL ASK: not "is this entry near anything I can walk
	-- to" but "is the tile a route to it would END on somewhere I can walk to". One definition,
	-- goal_for, so the list and the router can never disagree about what an entry means.
	local function reachable_filter(fs, list, seen, occ, px, pz, cache)
		local keep = {}
		for _, e in ipairs(list) do
			local cands, certain = goals_for(fs, e, occ, px, pz, cache, true)
			-- ⛔ ANY candidate reaching is enough — one unreachable side says nothing about the others.
			local component = cache and cache.discovery_component
			if component then
				local possible = {}
				for _, c in ipairs(cands) do
					local x,z = c[1],c[2]
					if e.connection then x,z = x-STEPD[e.direction][1],z-STEPD[e.direction][2] end
					if component[tkey(x,z)] then possible[#possible+1] = c end
				end
				if #cands > 0 and #possible == 0 then certain = true end
				cands = possible
			end
			local mask
			for _, c in ipairs(cands) do
				local value = cache and cache.hm_seen and cache.hm_seen[tkey(c[1],c[2])]
				if value ~= nil and (mask == nil or value < mask) then mask = value end
			end
			if seen then
				for _,c in ipairs(cands) do if seen[tkey(c[1],c[2])] then mask = 0; break end end
			end
			e.gate = nil
			if mask and mask > 0 then
				local words = {}
				for _, pair in ipairs({{1,0x56},{2,0x55},{4,0x54}}) do
					if (mask & pair[1]) ~= 0 then words[#words+1] = HM_NAME[pair[2]] end
				end
				e.gate = table.concat(words, ", ")
			end
			local ok = mask ~= nil or (not seen and #cands > 0)
			if seen then
				for _, c in ipairs(cands) do ok = ok or (seen[tkey(c[1], c[2])] and true or false) end
			end
			-- ⛔ AND AN EMPTY CANDIDATE LIST IS TWO DIFFERENT THINGS. If every side was READ and every
			-- side was blocked, there is genuinely nowhere to stand and the entry is noise. If some
			-- side could not be read at all, that is not a finding — keep it. Hiding a real exit is the
			-- one mistake this filter must never make.
			if ok or (#cands == 0 and not certain) then keep[#keep + 1] = e end
		end
		return keep
	end

	-- ── THE OTHER HALF OF "Transitions": SEAMLESS MAP EDGES ─────────────────────────────────────
	--
	-- ⛔ THIS IS WHY THE LIST WAS EMPTY ON EVERY ROUTE (Ola, 2026-09-05). Routes do not join through
	-- doors: the overworld is one MapMatrix of 32x32-tile cells, each cell naming the map header it
	-- holds, and walking from a cell holding Route 201 into the cell beside it holding Route 202 IS
	-- the transition. `FieldMap_ChangeZone` (0x021D11CC) does exactly that and nothing else — it
	-- divides the player's position into a cell and asks the matrix what lives there.
	--
	--   FieldSystem +0x2C  MapMatrix     width u8 +0x00, height u8 +0x01, matrixID u8 +0x02, then
	--                                    MapMatrixData at +0x04 (its own height/width bytes, note the
	--                                    REVERSED order) so the row-major u16 grid of map header ids
	--                                    begins at +0x06. MapMatrix_GetMapHeaderIDAtCoords
	--                                    (0x02039E30) indexes it `x + y * width`, `ldrh r0,[r0,#6]`.
	--   FieldSystem +0x28  LandDataManager   offsetTileX +0x10C / offsetTileZ +0x114, subtracted from
	--                                    the tile before the division — the same normalisation the
	--                                    streamed collision read does, and non-zero only in the
	--                                    Distortion World.
	--
	-- ⛔ RAW ADJACENCY IS NOT A TRANSITION, and offering it would be exactly the promise the
	-- reachability filter exists to stop us making. A cell edge can be a cliff, a river or the back of a
	-- building for its whole length. So each shared edge is intersected with the tiles that are
	-- actually WALKABLE on OUR side, and an edge with none is not offered at all — fail closed.
	--
	-- ⭐ THE ENTRY SITS ON THE FAR SIDE OF THE EDGE, one tile into the destination. That is not a
	-- detail: standing on our last tile does nothing, and it is the STEP ACROSS that changes the map,
	-- so a route that stopped on our side would announce arrival somewhere the player has not got to.
	-- Unloaded endpoints retain their real coordinates. The router follows a verified
	-- loaded prefix and resolves the crossing again after streaming, never stopping early.
	--
	-- ⚠ ONE ENTRY PER (DESTINATION, DIRECTION), NOT PER CELL. A long route can border its neighbour
	-- across several cells, and hearing "Route 205" four times is noise. The KEY is therefore stable
	-- while the POSITION is the crossing nearest the player, which is the one they want; the key is
	-- what the selection and a live route follow, so a moving position cannot lose either.
	--
	-- ⚠ AND THIS IS BUILT FRESH EVERY PRESS RATHER THAN CACHED WITH THE MAP'S EVENTS, which looks
	-- wasteful and is not: loaded terrain takes precedence over the cartridge's boundary
	-- attributes. Only immutable ROM attributes are cached, within the current geometry query.
	-- ⛔⛔ 900, AND IT IS NOT 225. MAP_MATRIX_MAX_SIZE is MAP_MATRIX_MAX_WIDTH * MAP_MATRIX_MAX_HEIGHT
	-- = 30 * 30 (constants/field/map_matrix.h:4-6). I first wrote 225 here, which is
	-- TERRAIN_ATTRIBUTES_MAP_MATRIX_COUNT — a bound on a completely different table that happens to
	-- sit a few lines away in this file. Rule 7 in its quietest form: two small integers from two id
	-- spaces. It would not have crashed or spoken anything wrong. It would have refused EVERY
	-- connection in the game, because matrix 0 — the one carrying every route and town in Sinnoh — is
	-- exactly 30 by 30 = 900 cells, and the only other matrix above 225 does not exist. Measured over
	-- fielddata/mapmatrix/map_matrix.narc, all 289 of them, rather than reasoned about.
	-- ⚠ AND NO FIXTURE OF A CONVENIENT SIZE COULD HAVE SHOWN IT: an 8x8 test matrix passes either
	-- way. The harness now builds one at the real 30x30 for exactly this reason.
	-- ⛔⛔ MOST OF THE MAP MATRIX IS NOT MAP. Header 0 is MAP_HEADER_EVERYWHERE, the filler the grid
	-- uses for every cell that is not somewhere — and in matrix 0, the one carrying the whole of
	-- Sinnoh, **728 of the 900 cells hold it** (counted over every member of
	-- fielddata/mapmatrix/map_matrix.narc). It is the sea and the void around the region.
	-- ⚠ THE ENGINE HAS NO SUCH CHECK and does not need one: FieldMap_ChangeZone (0x021D11CC) reads
	-- whatever the cell holds, because the terrain out there is not somewhere the player can walk.
	-- WE need it, because our own side of that boundary can perfectly well be open — and without
	-- this every coastal route would offer a transition to header 0, whose name the game gives as
	-- "Mystery Zone". A door to nowhere is exactly the promise the reachability filter exists to
	-- stop us making.
	local MM_NOWHERE = 0
	local MM_W, MM_H, MM_IDS, MM_MAXDIM = 0x00, 0x01, 0x06, 30
	local MM_D_H, MM_D_W = 0x04, 0x05        -- MapMatrixData's own pair, in the OPPOSITE order
	-- Cartridge attributes are only for conservative discovery. Routes still use
	-- resident collision and height. Land loaders copy immutable NARC attributes;
	-- loaded RAM takes precedence, including a map's current land-data IDs.
	function terrain.discovery_attrs(fs, x, z, cache)
		local live = tile_attrs(fs, x, z, cache)
		if live ~= nil then return live end
		return terrain.rom_attrs(fs,x,z,cache)
	end
	function terrain.rom_attrs(fs,x,z,cache)
		local m = terrain.map(fs, cache)
		if not terrain.unloaded(fs, x, z, cache) or not PM.rom_member or not m.mw or not m.mh then return nil end
		local fx, fz = x - m.tx, z - m.tz
		if fx < 0 or fz < 0 or fx >= m.mw*TILES or fz >= m.mh*TILES then return nil end
		local cell = fx//TILES + (fz//TILES)*m.mw
		if not inram(m.mm + 0xA92 + cell*2 + 1) then return nil end
		local id = u16(m.mm + 0xA92 + cell*2)
		cache.connection_rom = cache.connection_rom or {}
		local member = cache.connection_rom[id]
		if member == nil then
			local base = PM.rom_member("fielddata/land_data/land_data.narc", id, 0x810)
			if base and PM.rom_read(base, 4) == BLOCK_BYTES then member = {base=base+0x10,tiles={}}
			else member = false end
			cache.connection_rom[id] = member
		end
		if not member then return nil end
		local tile = (fz%TILES)*TILES + fx%TILES
		local value = member.tiles[tile]
		if value == nil then value = PM.rom_read(member.base + tile*2, 2); member.tiles[tile] = value end
		return value
	end


	-- Read the same BDHC sections as BDHC_LoadHeader/PrepareBuffers in bdhc.c.
	-- This is static geometry for discovery; loaded buffers and live plates win.
	function terrain.rom_bdhc(fs,cell,cache)
		local m = terrain.map(fs,cache)
		if not PM.rom_member or not m.mw or cell < 0 or cell >= m.mw*m.mh
			or not inram(m.mm+0xA92+cell*2+1) then return terrain.fail(cache,"ROM land owner invalid") end
		local id = u16(m.mm+0xA92+cell*2)
		cache.rom_bdhc = cache.rom_bdhc or {}
		local hit = cache.rom_bdhc[id]
		if hit ~= nil then return hit or terrain.fail(cache,"ROM BDHC unavailable") end
		cache.rom_bdhc[id] = false
		local base,size = PM.rom_member("fielddata/land_data/land_data.narc",id,0x10)
		if not base then return terrain.fail(cache,"ROM land member unavailable") end
		local offset = 0x10
		for i=0,2 do
			local bytes = PM.rom_read(base+i*4,4)
			if not bytes or bytes > size-offset then return terrain.fail(cache,"ROM land section bounds") end
			offset = offset+bytes
		end
		local length = PM.rom_read(base+12,4)
		if not length or length < 16 or length > size-offset or length > 0x9010
			or PM.rom_read(base+offset,4) ~= 0x43484442 then return terrain.fail(cache,"ROM BDHC header invalid") end
		local counts,pointers,at = {},{},0
		for i,stride in ipairs({8,12,4,8,8,2}) do
			local n = PM.rom_read(base+offset+2+i*2,2)
			if not n or n*stride > length-16-at then return terrain.fail(cache,"ROM BDHC section bounds") end
			counts[i],pointers[i] = n,at; at = at+n*stride
		end
		if counts[5] < 1 or at ~= length-16 then return terrain.fail(cache,"ROM BDHC size invalid") end
		-- Copy the bounded immutable payload once. Failed reads never reach plane arithmetic.
		local words = {}
		for i=0,at-1,2 do
			local value = PM.rom_read(base+offset+16+i,2)
			if value == nil then return terrain.fail(cache,"ROM BDHC payload unreadable") end
			words[i] = value
		end
		local function read16(p) return words[p] end
		local function read32(p)
			local v = words[p] | (words[p+2]<<16)
			return v >= 0x80000000 and v-0x100000000 or v
		end
		local out = {p=pointers,n=counts,finish=at,scanlines={},strips={},plates={},u16=read16,s32=read32}
		cache.rom_bdhc[id] = out
		return out
	end

	function terrain.hm_discovery(fs,px,pz,cache)
		-- Dynamic-map collision callbacks need their own model. Do not substitute ROM for them.
		if u32(fs+0xC) ~= u32(A.sSaveDataPtr) then return nil end
		local misc = save_page(SD_MISC,SD_MISC_SIZE,"HM discovery")
		if not misc or not inram(misc+0x703) or u32(misc+0x700) ~= 0 then return nil end
		local _,identity = terrain.area_tiles(fs,cache)
		if not identity then return nil end
		local c = cache.hm_geometry
		if not c or c.hm_identity ~= identity then
			c = {hm_offline=true,map=terrain.map(fs,cache),hm_identity=identity}
		end
		c.height_errors,c.motion,c.bike_gear = nil,nil,nil
		c.warp_events,c.traps,c.panels,c.lift = nil,nil,nil,nil
		c.hm_scope = terrain.route_scope(fs,px,pz,px,pz,nil,c)
		if not c.hm_scope then return nil end
		cache.hm_geometry = c
		return c
	end

	-- Snapshot only the current header's cells, not the visible streaming window.
	-- Cartridge attributes are a discovery source; routes still need live height.
	function terrain.area_tiles(fs, cache)
		local m,here = terrain.map(fs,cache),map_id(fs)
		if not here or here == MM_NOWHERE or not m.mw or m.mw < 1 or m.mh < 1
			or m.mw > MM_MAXDIM or m.mh > MM_MAXDIM or m.dw ~= m.mw or m.dh ~= m.mh
			or not inram(m.mm+0xA92+m.mw*m.mh*2-1) then return nil end
		local tx,tz = 0,0
		if m.tcm == A.sTerrainCollision then
			if m.lw ~= m.mw or m.lh ~= m.mh or not m.tx or not m.tz then return nil end
			tx,tz = m.tx,m.tz
		elseif m.tcm ~= A.sSimpleTerrainCollis then return nil end
		local headers = cache.matrix_headers
		if not headers then
			headers = {}
			for cell=0,m.mw*m.mh-1 do headers[cell] = u16(m.mm+MM_IDS+cell*2) end
			cache.matrix_headers = headers
		end
		local cells,identity = {},{here}
		for cell=0,m.mw*m.mh-1 do
			if headers[cell] == here then
				cells[#cells+1] = cell; identity[#identity+1] = cell
				identity[#identity+1] = u16(m.mm+0xA92+cell*2)
			end
		end
		if #cells == 0 or #cells*TILES*TILES > REACH_LIMIT then return nil end
		local key = table.concat(identity,":")
		local last = cache.area_tiles
		if last and last.key == key then return last.attrs,key end
		local attrs = {}
		for _,cell in ipairs(cells) do
			for z=tz+(cell//m.mw)*TILES,tz+(cell//m.mw+1)*TILES-1 do
				for x=tx+(cell%m.mw)*TILES,tx+(cell%m.mw+1)*TILES-1 do
					local value = terrain.discovery_attrs(fs,x,z,cache)
					if value == nil then dbg("nav: area attributes unavailable"); return nil end
					attrs[tkey(x,z)] = value
				end
			end
		end
		cache.area_tiles = {key=key,attrs=attrs}
		return attrs,key
	end

	-- A missing path in this superset proves disconnection across the whole area.
	-- Preserve ledge direction, bridge state and Surf dismounting. Heights, actors,
	-- ice and bicycle slopes remain optimistic here and cannot supply route edges.
	function terrain.map_component(fs, sx, sz, cache)
		-- Dynamic callbacks can override solid attributes; their native feature
		-- must have a dedicated model before an attribute-only proof is safe.
		if u32(fs+0xC) ~= u32(A.sSaveDataPtr) then dbg("nav: component save owner"); return nil end
		local misc = save_page(SD_MISC,SD_MISC_SIZE,"nav component")
		if not misc or not inram(misc+0x703) or u32(misc+0x700) ~= 0 then return nil end
		local attrs,area = terrain.area_tiles(fs,cache)
		local motion = terrain.motion(fs,cache)
		if not attrs or motion == nil or not attrs[tkey(sx,sz)] then return nil end
		local key = area..":"..sx..":"..sz..":"..motion
		local last = cache.map_component
		if last and last.key == key then return last.seen end
		local seen = terrain.walk_flood(function(x,z) return attrs[tkey(x,z)] end, sx, sz, motion)
		if not seen then dbg("nav: area component limit"); return nil end
		cache.map_component = {key=key,seen=seen}
		return seen
	end

	-- The attribute-only step flood behind map_component and the ways off the water: collision,
	-- the two-sided directional blocks, ledges one way, and the carried movement mode (a Surf
	-- dismount becomes walking; walking never enters water). Heights stay optimistic. `get(x, z)`
	-- returns a tile's u16 attributes or nil. Returns the reached tkeys, or nil past REACH_LIMIT.
	function terrain.walk_flood(get, sx, sz, motion)
		local start = tkey(sx,sz)
		if not get(sx,sz) then return {} end
		local seen,layers = {[start]=true},{[start]=1<<motion}
		local queue,head = {{sx,sz,motion}},1
		while head <= #queue do
			if head > REACH_LIMIT then return nil end
			local x,z,current = table.unpack(queue[head]); head = head+1
			local from = get(x,z) & ATTR_BEHAVIOR
			for dir=0,3 do
				local d = STEPD[dir]
				local nx,nz = x+d[1],z+d[2]
				local a = get(nx,nz)
				if a then
					local to = a & ATTR_BEHAVIOR
					local out,into = BLOCKED[from],BLOCKED[to]
					local allowed = (a & ATTR_COLLIDE) == 0
						and not (out and out[STEPNAME[dir]]) and not (into and into[STEPNAME[STEPOPP[dir]]])
					local next_motion = allowed and terrain.motion_move(current,from,to,dir) or nil
					if LEDGE[to] == STEPNAME[dir] and (current & 3) ~= 2 then
						nx,nz = x+d[1]*LEDGE_SPAN[to],z+d[2]*LEDGE_SPAN[to]
						local landing = get(nx,nz)
						next_motion = landing and terrain.bridge_after(current,landing & ATTR_BEHAVIOR) or nil
					end
					local k = tkey(nx,nz)
					if next_motion ~= nil and ((layers[k] or 0) & (1<<next_motion)) == 0 then
						layers[k] = (layers[k] or 0) | (1<<next_motion)
						seen[k] = true; queue[#queue+1] = {nx,nz,next_motion}
					end
				end
			end
		end
		return seen
	end

	-- ── SURF SPOTS: one HM entry per body of water in the whole map ─────────────────────────────
	-- Black and White's design (the player's choice, 2026-08-26, carried over 2026-11-02): one "Surf" per body of
	-- water, never one per shore tile, listed only once HM03 is in the bag, and only while walking —
	-- afloat, ways IN are noise. Whole map, not the loaded window, the same way area-wide
	-- transitions work (terrain.area_tiles: live tiles where loaded, the cartridge's land files
	-- elsewhere).
	-- THE GAME'S RULE IS SIMPLER THAN GEN V'S. Field_TileBehaviorToScript (overlay 5,
	-- field_control.c:688-695) offers Surf when the faced tile is surfable and PlayerAvatar_CanUseSurf
	-- (ov5_021DFB54.c:641) allows it: TileBehavior_IsSurfable(faced) and not standing on an ELEVATED
	-- bridge. There are no blocked shore tiles in between as in Unova: you stand on land and face the
	-- water. Water is walkable terrain (bit 15 clear) whose permission is the surfable flag, which is
	-- how terrain.water and the router already model it. Bridge tiles 0x70-0x7D are never offered as
	-- a place to stand, because whether one is elevated is a live object status, not map data.
	-- Each body carries every shore tile in `surf` = {stand x, z, water x, z}; goals_for offers the
	-- unoccupied ones nearest first, so the route ends on the nearest shore it can reach, and the
	-- arrival says which way the water is ("Arrived at Surf, 1 up").
	-- The bodies are static map data: cached per area identity, so a key press only re-measures
	-- which shore is nearest.
	-- Open water: walkable (bit 15 clear) with the surfable flag. A waterfall tile is surfable but
	-- climbing it needs Waterfall, so it divides one body of water from another.
	function terrain.is_water(a)
		return a ~= nil and (a & ATTR_COLLIDE) == 0 and SURFABLE[a & ATTR_BEHAVIOR] == true
			and (a & ATTR_BEHAVIOR) ~= B_WATERFALL
	end
	function terrain.surf_spots(fs, px, pz, cache)
		if (terrain.motion(fs, cache) or 2) & 3 == 2 then return {} end      -- afloat or unknown
		if not PM.field_move_badge(A.FieldMovesCheckSurf) then return {} end -- unknown answers no
		local attrs, area = terrain.area_tiles(fs, cache)
		if not attrs then return {} end
		local saved = terrain.surf_saved
		if not (saved and saved.area == area) then
			local water = terrain.is_water
			local seen, bodies = {}, {}
			for k, a in pairs(attrs) do
				if water(a) and not seen[k] then
					seen[k] = true
					local queue, head, shore, first = { k }, 1, {}, k
					while head <= #queue do
						local c = queue[head]; head = head + 1
						if c < first then first = c end
						local wx, wz = c // 0x10000 - 0x8000, c % 0x10000 - 0x8000
						for dir = 0, 3 do
							local d = STEPD[dir]
							local nk = tkey(wx + d[1], wz + d[2])
							local n = attrs[nk]
							if water(n) then
								if not seen[nk] then seen[nk] = true; queue[#queue + 1] = nk end
							elseif n and (n & ATTR_COLLIDE) == 0 then
								local b = n & ATTR_BEHAVIOR
								if not (b >= 0x70 and b <= 0x7D) then
									shore[#shore + 1] = { wx + d[1], wz + d[2], wx, wz }
								end
							end
						end
					end
					if #shore > 0 then bodies[#bodies + 1] = { key = "surf" .. first, surf = shore } end
				end
			end
			table.sort(bodies, function(a, b) return a.key < b.key end)
			saved = { area = area, bodies = bodies }
			terrain.surf_saved = saved
		end
		local out = {}
		for _, b in ipairs(saved.bodies) do
			local best, bd
			for _, s in ipairs(b.surf) do
				local d = math.abs(s[1] - px) + math.abs(s[2] - pz)
				if not bd or d < bd then best, bd = s, d end
			end
			out[#out + 1] = { name = HM_NAME.surf, key = b.key, x = best[1], z = best[2], surf = b.surf }
		end
		return out
	end

	-- ── ROCK CLIMB: one HM entry per climbable wall in the whole map ────────────────────────────
	-- The player's design (2026-11-03): one "Rock Climb" per wall, whichever end the player is at,
	-- listed only with the Icicle Badge, like a Surf spot: the route ends on the nearest end the
	-- player can reach and the arrival says which way to face ("Arrived at Rock Climb, 1 up").
	-- What lies beyond a wall is deliberately NOT offered: it shows up once the player stands on that
	-- side, and the side left behind drops out. Nothing extra does that — every retail climb tile has
	-- collision bit 15 set, so the walk flood and the router already treat the wall as a wall.
	-- THE GAME'S RULE. Field_TileBehaviorToScript (ov5 021D271C) runs FieldMoves_RockyWall when
	-- PlayerAvatar_CanUseRockClimb (021E0760) accepts the FACED tile: TileBehavior_IsRockClimbNorthSouth
	-- facing north or south, TileBehavior_IsRockClimbEastWest facing east or west. The script then wants
	-- Rock Climb in the party and the Icicle Badge (FieldMoves_CheckRockClimb 02070DA0, `movs r1,#6`);
	-- the badge alone gates the list, as for Surf (the player's choice, 2026-11-02). Standing on a
	-- bridge does not matter here, unlike Surf.
	-- THE CLIMB (ov5 SubTask_RockClimb_*, 021E07CC-021E0950) moves the player without any collision
	-- test: hop one tile onto the wall (JUMP_NEAR_FAST, 2 units x 8 frames), walk one tile whatever it
	-- is, keep walking while the tile ahead is a climb tile of the same axis, then hop one tile off. So
	-- a run of n >= 2 tiles lands n + 1 tiles from where the player stood, and a one-tile wall (Valor
	-- Lakefront has three) lands 3 away. An end is offered only when that landing is readable, open
	-- ground: Mt. Coronet's summit has a two-tile wall that would land inside solid rock.
	-- Each wall is one connected group of climb tiles of one axis; `climb` holds every end as
	-- {stand x, z, wall x, z}, the same shape as a Surf body's shores, so goals_for and the arrival
	-- treat both alike. Stand tiles come from this map only; a wall or a landing across a map edge
	-- is read from the cartridge (Route 213's wall at (721,800) lands in Valor Lakefront). Static map
	-- data: cached per area identity.
	-- Behavior -> its two facing directions, read out of the two predicates
	-- (`cmp r0,#behavior ; bne +2 ; movs r0,#1 ; bx lr`); any other shape fails closed.
	function terrain.climb_axes()
		local axes = {}
		for _, p in ipairs({ { A.TileBehaviorIsRockClimbNS, 0, 1 }, { A.TileBehaviorIsRockClimbEW, 2, 3 } }) do
			local f = p[1]
			if (u16(f) & 0xFF00) ~= 0x2800 or u16(f + 2) ~= 0xD101 or u16(f + 4) ~= 0x2001 or u16(f + 6) ~= 0x4770 then
				dbg(string.format("Rock Climb: tile predicate at %08X has an unknown shape", f)); return nil
			end
			axes[u16(f) & 0xFF] = { [p[2]] = true, [p[3]] = true }
		end
		if not next(axes, next(axes)) then dbg("Rock Climb: both predicates test one behavior"); return nil end
		return axes
	end
	function terrain.climb_spots(fs, px, pz, cache)
		if (terrain.motion(fs, cache) or 2) & 3 == 2 then return {} end           -- afloat or unknown
		if not PM.field_move_badge(A.FieldMovesCheckRockClimb) then return {} end -- unknown answers no
		local axes = terrain.climb_axes()
		if not axes then return {} end
		local attrs, area = terrain.area_tiles(fs, cache)
		if not attrs then return {} end
		local saved = terrain.climb_saved
		if not (saved and saved.area == area) then
			local function get(x, z)
				local a = attrs[tkey(x, z)]
				if a == nil then a = terrain.discovery_attrs(fs, x, z, cache) end
				return a
			end
			local function climbs(x, z, b)
				local a = get(x, z)
				return a ~= nil and (a & ATTR_BEHAVIOR) == b
			end
			local wall_of, walls, unread, solid = {}, {}, 0, 0
			for k, a in pairs(attrs) do
				if (a & ATTR_COLLIDE) == 0 then
					local sx, sz = k // 0x10000 - 0x8000, k % 0x10000 - 0x8000
					for dir = 0, 3 do
						local d = STEPD[dir]
						local tx, tz = sx + d[1], sz + d[2]
						local t = get(tx, tz)
						local b = t and (t & ATTR_BEHAVIOR)
						if b and axes[b] and axes[b][dir] then
							-- The climb as the task runs it: hop on, one walk, the run, hop off.
							local x, z, n = tx + d[1], tz + d[2], 0
							while n < 64 and climbs(x + d[1], z + d[2], b) do x, z, n = x + d[1], z + d[2], n + 1 end
							local land = n < 64 and get(x + d[1], z + d[2]) or nil
							if land == nil then unread = unread + 1
							elseif (land & ATTR_COLLIDE) ~= 0 then solid = solid + 1
							else
								local tk = tkey(tx, tz)
								local w = wall_of[tk]
								if not w then
									-- The whole wall: every climb tile of this axis joined to this one.
									w = { first = tk, climb = {} }
									local queue, head = { { tx, tz } }, 1
									wall_of[tk] = w
									while head <= #queue and head <= 256 do
										local cx, cz = queue[head][1], queue[head][2]; head = head + 1
										for nd = 0, 3 do
											local nx, nz = cx + STEPD[nd][1], cz + STEPD[nd][2]
											local nk = tkey(nx, nz)
											if not wall_of[nk] and climbs(nx, nz, b) then
												wall_of[nk] = w; queue[#queue + 1] = { nx, nz }
												if nk < w.first then w.first = nk end
											end
										end
									end
									walls[#walls + 1] = w
								end
								w.climb[#w.climb + 1] = { sx, sz, tx, tz }
							end
						end
					end
				end
			end
			if unread + solid > 0 then
				dbg(string.format("Rock Climb: %d wall ends not offered (%d landings unreadable, %d solid)",
					unread + solid, unread, solid))
			end
			-- A total order, so an equally near end cannot change between rebuilds.
			for _, w in ipairs(walls) do
				w.key = "climb" .. w.first
				table.sort(w.climb, function(a, b)
					local ka, kb = tkey(a[1], a[2]), tkey(b[1], b[2])
					if ka ~= kb then return ka < kb end
					return tkey(a[3], a[4]) < tkey(b[3], b[4])
				end)
			end
			table.sort(walls, function(a, b) return a.first < b.first end)
			saved = { area = area, walls = walls }
			terrain.climb_saved = saved
		end
		local out = {}
		for _, w in ipairs(saved.walls) do
			local best, bd
			for _, s in ipairs(w.climb) do
				local d = math.abs(s[1] - px) + math.abs(s[2] - pz)
				if not bd or d < bd then best, bd = s, d end
			end
			out[#out + 1] = { name = HM_NAME.climb, key = w.key, x = best[1], z = best[2], climb = w.climb }
		end
		return out
	end

	-- ── WATERFALL: one HM entry per waterfall, while surfing ─────────────────────────────────────
	-- The player's design (2026-11-04): Waterfall spots appear in the list while surfing, only with
	-- the badge that allows the move, and, as for Rock Climb, nothing on the other side of a fall is
	-- offered: an entry carries only the ends on the water the player is on (terrain.afloat), and the
	-- floods never cross a fall (terrain.is_water and step_ok refuse the fall tile).
	-- THE GAME'S RULES (pret/pokeplatinum; addresses retail). Every waterfall in the game is a row of
	-- fall tiles one tile deep, higher water to the north.
	--  * Up: facing the fall and pressing A, Field_TileBehaviorToScript runs FieldMoves_Waterfall, which
	--    wants Waterfall in the party and BADGE_ID_BEACON (FieldMoves_CheckWaterfall 02070CF8,
	--    `movs r1,#7`); facing north, FieldTask_UseWaterfall ascends two tiles north
	--    (SubTask_Waterfall_InitAscent: MapObject_GetDzFromDir(DIR_NORTH) << 1).
	--  * Down: pressing south while surfing, facing south, with the fall to the south and Waterfall in
	--    the party descends two tiles south (ov5_021E04A8; no badge is asked for there). The list still
	--    gates on the badge, the player's choice.
	-- An end is {stand x, z, fall x, z}, the Rock Climb shape, so goals_for and the arrival ("Arrived
	-- at Waterfall, 1 up" / "1 down") need nothing new. It is offered only when the stand and landing
	-- tiles are open water. The behavior is read from TileBehavior_IsWaterfall and must agree with the
	-- table's B_WATERFALL; any other shape fails closed. Static map data: cached per area identity.
	function terrain.waterfall_behavior()
		local f = A.TileBehaviorIsWaterfall
		if (u16(f) & 0xFF00) ~= 0x2800 or u16(f + 2) ~= 0xD101 or u16(f + 4) ~= 0x2001 or u16(f + 6) ~= 0x4770 then
			dbg(string.format("Waterfall: tile predicate at %08X has an unknown shape", f)); return nil
		end
		if u16(f) & 0xFF ~= B_WATERFALL then dbg("Waterfall: tile predicate disagrees with the tile table"); return nil end
		return B_WATERFALL
	end
	function terrain.waterfall_spots(fs, px, pz, cache)
		if ((terrain.motion(fs, cache) or 0) & 3) ~= 2 then return {} end          -- surfing only; unknown answers no
		if terrain.dw.active(fs, cache) then return {} end                         -- its own lists (terrain.dw)
		if not PM.field_move_badge(A.FieldMovesCheckWaterfall) then return {} end  -- unknown answers no
		local fall = terrain.waterfall_behavior()
		if not fall then return {} end
		local attrs, area = terrain.area_tiles(fs, cache)
		if not attrs then return {} end
		local water = terrain.afloat(fs, px, pz, cache)
		if not water then return {} end
		local saved = terrain.waterfall_saved
		if not (saved and saved.area == area) then
			local function get(x, z) return attrs[tkey(x, z)] end
			local function is_fall(a) return a ~= nil and (a & ATTR_BEHAVIOR) == fall end
			local fall_of, falls, dropped = {}, {}, 0
			for k, a in pairs(attrs) do
				if is_fall(a) and not fall_of[k] then
					-- The whole fall: every fall tile joined to this one.
					local f = { first = k, ends = {} }
					local queue, head = { k }, 1
					fall_of[k] = f
					while head <= #queue do
						local c = queue[head]; head = head + 1
						if c < f.first then f.first = c end
						local cx, cz = c // 0x10000 - 0x8000, c % 0x10000 - 0x8000
						for dir = 0, 3 do
							local nk = tkey(cx + STEPD[dir][1], cz + STEPD[dir][2])
							if not fall_of[nk] and is_fall(attrs[nk]) then fall_of[nk] = f; queue[#queue + 1] = nk end
						end
						-- Up from the water below (landing above), down from the water above (landing below).
						for _, side in ipairs({ { 1, -1 }, { -1, 1 } }) do
							if terrain.is_water(get(cx, cz + side[1])) then
								if terrain.is_water(get(cx, cz + side[2])) then
									f.ends[#f.ends + 1] = { cx, cz + side[1], cx, cz }
								else dropped = dropped + 1 end
							end
						end
					end
					falls[#falls + 1] = f
				end
			end
			if dropped > 0 then dbg(string.format("Waterfall: %d ends not offered (landing is not open water)", dropped)) end
			for _, f in ipairs(falls) do
				f.key = "waterfall" .. f.first
				table.sort(f.ends, function(a, b)
					local ka, kb = tkey(a[1], a[2]), tkey(b[1], b[2])
					if ka ~= kb then return ka < kb end
					return tkey(a[3], a[4]) < tkey(b[3], b[4])
				end)
			end
			table.sort(falls, function(a, b) return a.first < b.first end)
			saved = { area = area, falls = falls }
			terrain.waterfall_saved = saved
		end
		local out = {}
		for _, f in ipairs(saved.falls) do
			local here, best, bd = {}, nil, nil
			for _, s in ipairs(f.ends) do
				if water.body[tkey(s[1], s[2])] then
					here[#here + 1] = s
					local d = math.abs(s[1] - px) + math.abs(s[2] - pz)
					if not bd or d < bd then best, bd = s, d end
				end
			end
			if best then
				out[#out + 1] = { name = HM_NAME.waterfall, key = f.key, x = best[1], z = best[2], waterfall = here }
			end
		end
		return out
	end

	-- ── ON THE WATER: only what the water reaches, and the ways off it ───────────────────────────
	-- Black and White's rule (the player's choice, 2026-08-31, carried over 2026-11-02): "when you are on the water
	-- ... only transitions that get me off the water or if there truly is a transition you access
	-- from the water itself." So while surfing:
	--   * the body of water you are on is flooded over the whole map (terrain.area_tiles; the live
	--     window when the map is too large for that);
	--   * every entry in every list survives only if one of its approach tiles is on that water — a
	--     door or a person ashore is not, a swimmer or a route edge across the water is;
	--   * the ways ashore are added to Transitions: every land tile the engine lets you step onto from
	--     that water (the router's own dismount rule: collision, directional blocks, terrain.motion_move),
	--     grouped by which ones you could walk between, one entry per separate landmass, named by the
	--     map you are on (questions_surf.md: localized route or place name; "list the shore you came
	--     from"; "transitions"). Each carries all of its landing tiles, so the route goes to the nearest.
	-- Nothing provable means nothing listed: afloat, an unknown is never kept (Black and White's rule).
	function terrain.afloat(fs, px, pz, cache)
		local attrs, area = terrain.area_tiles(fs, cache)
		local get = attrs and function(x, z) return attrs[tkey(x, z)] end
			or function(x, z) return tile_attrs(fs, x, z, cache) end
		if not terrain.is_water(get(px, pz)) then dbg("nav: afloat on a tile that is not water"); return nil end
		local saved = terrain.afloat_saved
		if attrs and saved and saved.area == area and saved.body[tkey(px, pz)] then return saved end
		local body, queue, head, anchor = { [tkey(px, pz)] = true }, { { px, pz } }, 1, tkey(px, pz)
		local landings = {}
		while head <= #queue do
			if head > REACH_LIMIT then dbg("nav: water flood limit"); return nil end
			local x, z = queue[head][1], queue[head][2]; head = head + 1
			local from = get(x, z) & ATTR_BEHAVIOR
			for dir = 0, 3 do
				local d = STEPD[dir]
				local nx, nz = x + d[1], z + d[2]
				local k, a = tkey(nx, nz), get(nx, nz)
				if terrain.is_water(a) then
					if not body[k] then body[k] = true; queue[#queue + 1] = { nx, nz }; if k < anchor then anchor = k end end
				elseif a and (a & ATTR_COLLIDE) == 0 then
					local to = a & ATTR_BEHAVIOR
					local out, into = BLOCKED[from], BLOCKED[to]
					local m = not (out and out[STEPNAME[dir]]) and not (into and into[STEPNAME[STEPOPP[dir]]])
						and terrain.motion_move(2, from, to, dir)
					if m and (m & 3) ~= 2 and not landings[k] then landings[k] = { nx, nz, m } end
				end
			end
		end
		-- One entry per landmass you could walk around on.
		local group, entries, name = {}, {}, place_name(map_id(fs)) or ""
		local keys = {}
		for k in pairs(landings) do keys[#keys + 1] = k end
		table.sort(keys)
		for _, k in ipairs(keys) do
			if not group[k] then
				local l = landings[k]
				local land = terrain.walk_flood(get, l[1], l[2], l[3])
				if not land then dbg("nav: landing flood limit"); return nil end
				local spots = {}
				for _, k2 in ipairs(keys) do
					if not group[k2] and (k2 == k or land[k2]) then
						group[k2] = true; spots[#spots + 1] = { landings[k2][1], landings[k2][2] }
					end
				end
				entries[#entries + 1] = { name = name, key = "land" .. k, spots = spots, landing = true }
			end
		end
		saved = { area = area, body = body, entries = entries, anchor = anchor }
		if attrs then terrain.afloat_saved = saved end
		return saved
	end
	-- Keep what the water reaches: an approach tile on the body (for a map edge, the tile on this side).
	function terrain.afloat_filter(fs, list, water, occ, px, pz, cache)
		local keep = {}
		if not water then return keep end
		for _, e in ipairs(list) do
			local ok = e.landing
			if not ok then
				local cands = goals_for(fs, e, occ, px, pz, cache, true)
				for _, c in ipairs(cands) do
					local x, z = c[1], c[2]
					if e.connection then x, z = x - STEPD[e.direction][1], z - STEPD[e.direction][2] end
					if water.body[tkey(x, z)] then ok = true; break end
				end
			end
			if ok then keep[#keep + 1] = e end
		end
		return keep
	end

	local function build_connections(fs, px, pz, cache)
		cache = cache or {}
		local L = { Transitions = {} }
		local here = map_id(fs)
		local mm = u32(fs + FS_MATRIX)
		if not here then dbg("nav: no map id for connections"); return L end
		-- ⚠ BOTH ENDS OF EVERY RANGE WE READ, not just the base (codex-review, confirmed).
		-- ⛔ BUT NOT FOR THE REASON I FIRST WROTE HERE, AND THE CORRECTION MATTERS. I said an
		-- out-of-range read is "a Lua error that kills every reader". It is not: core/mem.lua's u8,
		-- u16 and u32 each check `inrange(offset, width)` and answer **0** rather than calling
		-- BizHawk at all — a fail-closed shape that file adopted after its own review, for exactly
		-- this reason. So the real risk is quieter and worth naming properly: a wild pointer reads as
		-- a tidy row of ZEROES, and zero is a legal-looking dimension. These guards exist so such a
		-- pointer is REFUSED rather than believed, not to prevent a crash that cannot happen.
		-- ⚠ AND THE LOWER HALF OF THIS PAIR HAS NO DISCRIMINATING TEST, which is worth saying rather
		-- than implying. `inram(mm)` and `inram(mm + MM_D_W)` can only disagree for a pointer landing
		-- in the five bytes below the RAM base, and there the dimension bytes read 0 anyway and the
		-- `mw < 1` test below refuses them. It is kept because it states the intent of the range, not
		-- because a fixture could ever prove it — the same call, and the same reasoning, as the
		-- `mw < 1` line further down. (Mutation-checked: removing it leaves all 306 checks green.)
		if not (inram(mm) and inram(mm + MM_D_W)) then
			dbg("nav: map matrix unreadable"); return L
		end
		local mw, mh = u8(mm + MM_W), u8(mm + MM_H)
		-- ⛔ BOTH DIMENSIONS, NOT JUST THEIR PRODUCT. MAP_MATRIX_MAX_SIZE is
		-- MAP_MATRIX_MAX_WIDTH * MAP_MATRIX_MAX_HEIGHT and the two bounds are 30 apiece
		-- (constants/field/map_matrix.h:4-6), so a product test alone accepts 225 by 4 — shaped
		-- nothing like a real matrix and perfectly capable of walking a plausible-looking grid.
		if mw < 1 or mh < 1 or mw > MM_MAXDIM or mh > MM_MAXDIM then
			dbg("nav: map matrix dimensions out of range"); return L
		end
		-- ⭐ AND THE STRUCTURE CARRIES ITS OWN TYPE CHECK, FREE. MapMatrix_Load copies the loaded
		-- file's dimensions into the object's own fields (`mapMatrix->height = mapMatrix->data.height;
		-- ->width = ->data.width`, src/map_matrix.c:84-92), so +0x00/+0x01 and the data block's own
		-- pair at +0x04/+0x05 must agree — and note the pair is stored in the OPPOSITE order. Two
		-- bytes that must equal two other bytes is exactly the "guard the use, not just the pointer"
		-- test Rule 5 asks for, and it costs one comparison.
		if u8(mm + MM_D_H) ~= mh or u8(mm + MM_D_W) ~= mw then
			dbg("nav: map matrix does not agree with its own data block"); return L
		end
		if not inram(mm + MM_IDS + mw * mh * 2 - 1) then
			dbg("nav: map matrix grid runs past RAM"); return L
		end
		if not cache.matrix_headers then
			cache.matrix_headers = {}
			for cell = 0, mw * mh - 1 do cache.matrix_headers[cell] = u16(mm + MM_IDS + cell * 2) end
		end
		local headers = cache.matrix_headers
		local offx, offz = 0, 0
		if u32(fs + FS_TCM) == A.sTerrainCollision then
			local ld = u32(fs + FS_LAND)
			if not (inram(ld + LDM_OFFX) and inram(ld + LDM_OFFZ + 3)) then
				dbg("nav: land manager offsets unreadable"); return L
			end
			offx, offz = s32(ld + LDM_OFFX), s32(ld + LDM_OFFZ)
		end
		-- Discover distant boundaries from the loaded cartridge, not just the four
		-- resident cells. MapMatrix_GetLandDataIDByIndex2 (02039E06) reads +A92;
		-- TerrainAttributes_Load (02054CA6) reads member+10, length800. These
		-- attributes never enter the route/height cache. Loaded RAM takes precedence.
		if not inram(mm + 0xA92 + mw * mh * 2 - 1) then
			dbg("nav: land ID grid runs past RAM"); return L
		end
		local function boundary_attrs(x, z)
			return terrain.discovery_attrs(fs, x, z, cache)
		end
		local function can_cross(ox, oz, dir)
			local d = STEPD[dir]
			local a, b = boundary_attrs(ox, oz), boundary_attrs(ox+d[1], oz+d[2])
			if not a or not b or (a & ATTR_COLLIDE) ~= 0 or (b & ATTR_COLLIDE) ~= 0 then return false end
			local from, to = a & ATTR_BEHAVIOR, b & ATTR_BEHAVIOR
			if from == B_ICE or to == B_ICE or bike_slope(from) or bike_slope(to) then return false end
			local out, into = BLOCKED[from], BLOCKED[to]
			if (out and out[STEPNAME[dir]]) or (into and into[STEPNAME[STEPOPP[dir]]]) then return false end
			-- Discovery permits any possible arrival bridge/mode state. Actual
			-- A* carries and verifies the state used to cross this boundary.
			local motion = terrain.motion(fs,cache)
			if motion == nil then return false end
			if from < 0x70 or from > 0x7D then
				if terrain.motion_move(motion & 3,from,to,dir) == nil then return false end
			end
			local ok = terrain.discovery_step(fs,ox,oz,dir,cache,from,to)
			return ok ~= false
		end
		-- best[key] = the nearest crossing found so far for that destination and direction.
		local best, order = {}, {}
		for cz = 0, mh - 1 do
			for cx = 0, mw - 1 do
				if headers[cx + cz * mw] == here then
					for dir = 0, 3 do
						local d = STEPD[dir]
						local nx, nz = cx + d[1], cz + d[2]
						if nx >= 0 and nz >= 0 and nx < mw and nz < mh then
							local nid = headers[nx + nz * mw]
							if nid ~= here and nid ~= MM_NOWHERE and nid < MH_COUNT then
								-- The 32 tiles of the shared edge, on OUR side, and the tile each
								-- one steps onto.
								for t = 0, TILES - 1 do
									local ox, oz                     -- our tile
									if d[1] ~= 0 then
										ox = offx + cx * TILES + (d[1] > 0 and TILES - 1 or 0)
										oz = offz + cz * TILES + t
									else
										ox = offx + cx * TILES + t
										oz = offz + cz * TILES + (d[2] > 0 and TILES - 1 or 0)
									end
									local cross = can_cross(ox, oz, dir)
									if cross then
										local ax, az = ox + d[1], oz + d[2]
										local dist = math.abs(ax - px) + math.abs(az - pz)
										local key = "C" .. nid .. "." .. dir
										local b = best[key]
										if not b then
											order[#order + 1] = key
											b = { dz = nid, key = key, spots = {}, direction = dir }
											best[key] = b
										end
										-- ⛔ EVERY CROSSING IS KEPT, NOT JUST THE NEAREST
										-- (codex-review, confirmed). Committing to the geometrically
										-- nearest tile and asking about that one only is a mistake
										-- this file has already made once, at goals_for: the near
										-- opening can be behind a wall while a farther one along the
										-- same boundary is wide open, and the entry would then be
										-- filtered away as unreachable. The bearing still names the
										-- nearest — that is what "where is it" means — but the
										-- router and the filter get the whole set.
										-- Preserve both sides for live revalidation during replans.
										-- The endpoint stays across the edge, even before it loads.
										b.spots[#b.spots + 1] = { ax, az, ox, oz }
										if b.dist == nil or dist < b.dist then
											b.x, b.z, b.dist = ax, az, dist
										end
									end
								end
							end
						end
					end
				end
			end
		end
		for _, key in ipairs(order) do
			local b = best[key]
			local nm = door_name(b.dz)
			if nm then
				L.Transitions[#L.Transitions + 1] = { name = nm, key = b.key,
					x = b.x, z = b.z, dz = b.dz, spots = b.spots,
					connection = true, direction = b.direction }
			end
		end
		return L
	end

	local function build_pc(fs, px, pz, cache)
		local out = {}
		cache = cache or {}
		local area = terrain.area_tiles(fs,cache)
		if area then
			for key,a in pairs(area) do
				if (a & ATTR_BEHAVIOR) == 0x83 then
					local x,z = key//0x10000-0x8000,key%0x10000-0x8000
					out[#out+1] = {name="PC",key="PC"..key,x=x,z=z,pc=true}
				end
			end
		else
			-- Keep resident discoveries when the area snapshot is unavailable.
			for z=pz-20,pz+20 do
				for x=px-20,px+20 do
					if tile_behavior(fs,x,z,cache) == 0x83 then
						out[#out+1] = {name="PC",key="PC"..tkey(x,z),x=x,z=z,pc=true}
					end
				end
			end
		end
		return out
	end

	local function refresh(fs, px, pz)
		local id = map_id(fs)
		if not id then return false end
		if not (statics and list_map == id) then
			list_map = id
			terrain.saved = nil
			-- A new map is a different set of doors and people, so start at the top of the list and
			-- name the category again on the next press. ⚠ `ci` is deliberately NOT reset: the
			-- category is restored from want_cat below, and it must survive exactly this rebuild.
			ii, entered = 1, false
		end
		-- Native scripts can move parsed warps and BG events without a map change.
		-- The event buffer is bounded to 0x800 bytes; refresh it on navigation keys.
		local cache = terrain.query(fs)
		statics = build_static(fs, function(x, z, dest) return not terrain.offered_warp(fs, x, z, dest, cache) end)
		-- ⚠ MERGED FRESH EVERY PRESS, never filtered in place. `statics` is an immutable snapshot of
		-- the map's events for this key press. `lists` adds the live objects, so nothing is
		-- lost as reachability changes, and a door hidden by a wall this second is offered again the
		-- second the wall opens. Signs come from BOTH halves and are concatenated.
		local live = build_live(fs)
		if terrain.snowpoint.active(fs, cache) then live.Objects = terrain.snowpoint.unlisted(live.Objects) end
		for _, e in ipairs(terrain.surf_spots(fs, px, pz, cache)) do live.HM[#live.HM + 1] = e end
		for _, e in ipairs(terrain.climb_spots(fs, px, pz, cache)) do live.HM[#live.HM + 1] = e end
		for _, e in ipairs(terrain.waterfall_spots(fs, px, pz, cache)) do live.HM[#live.HM + 1] = e end
		local clue = hearthome.entry(fs)
		if clue then live.Objects[#live.Objects+1] = clue end
		for _, e in ipairs(dowsing.list(fs)) do live.Items[#live.Items + 1] = e end
		for _, e in ipairs(build_pc(fs, px, pz, cache)) do live.Objects[#live.Objects + 1] = e end
		-- The THIRD source, and it is neither static nor live in the senses above: the map matrix
		-- cannot change while you stand in it, but which of its cells are loaded can, so this is
		-- rebuilt with the live half rather than cached with the events. See build_connections.
		local conn = build_connections(fs, px, pz, cache)
		live["Honey trees"] = honey.list(fs, cache)
		lists = {}
		for _, c in ipairs(CATS) do
			local out = {}
			for _, e in ipairs(statics[c] or {}) do
				if e.warps then
					local nearest, distance
					for _, tile in ipairs(e.warps) do
						local d = math.abs(tile.x-px) + math.abs(tile.z-pz)
						if not distance or d < distance then nearest, distance = tile, d end
					end
					out[#out + 1] = {name=e.name, key=e.key, dz=e.dz,
						x=nearest.x, z=nearest.z, warps=e.warps}
				else out[#out + 1] = e end
			end
			for _, e in ipairs(live[c] or {}) do out[#out + 1] = e end
			for _, e in ipairs(conn[c] or {}) do out[#out + 1] = e end
			lists[c] = out
		end
		local occ, occ_ok, gates = occupied(fs)
		-- The Distortion World adds its slabs, slides, passage and portals and judges reachability
		-- with its own moves (terrain.dw.filter); none of the floods below know its surfaces.
		if terrain.dw.active(fs, cache) then
			terrain.dw.filter(fs, lists, cache)
			local was = active[ci]
			active = {}
			for _, c in ipairs(CATS) do if #lists[c] > 0 then active[#active + 1] = c end end
			apply_want(was)
			sort_cat(px, pz)
			if sel_key then
				local found
				for i, e in ipairs(cur_list()) do if e.key == sel_key then found = i; break end end
				if found then ii = found elseif entered then ii, entered = 1, false end
			end
			return true, cache, occ, occ_ok
		end
		-- Veilstone Gym's bags and stacks hide nothing the route planner can reach by kicking them.
		-- An unverifiable gym is unknown ground, not a wall: the filter stands down rather than hide
		-- the trainers and the leader behind objects it cannot classify.
		local reach_occ, veil_unknown = occ, false
		if veilstone.active(fs) then
			local snap = veilstone.snapshot(fs)
			if snap then reach_occ = veilstone.relax(snap, occ) else veil_unknown = true end
		end
		-- Pastoria Gym: the list offers what some sequence of presses reaches, which is the planner's
		-- own flood over all three levels. An unverifiable gym stands the filter down, as Veilstone's.
		local pas_seen
		if occ_ok and pastoria.active(fs, cache) then
			local snap = pastoria.snapshot(fs, cache)
			if snap then
				reach_occ = pastoria.blocked(snap, occ)
				pas_seen = pastoria.flood(fs, snap, px, pz, occ, cache)
			end
			veil_unknown = pas_seen == nil
		end
		-- Sunyshore Gym: the same, over the four rotation states.
		if occ_ok and terrain.sunyshore.active(fs, cache) then
			local snap = terrain.sunyshore.snapshot(fs, cache)
			if snap then
				reach_occ = terrain.sunyshore.blocked(snap, occ)
				pas_seen = terrain.sunyshore.flood(fs, snap, px, pz, occ, cache)
			end
			veil_unknown = pas_seen == nil
		end
		-- ⛔ A FLOOD THAT RAN OUT OF ROOM MUST NOT FILTER ANYTHING. reach_from is bounded, and on the
		-- whole-matrix path a big enough map can genuinely hit that bound — at which point everything
		-- past the frontier looks unreachable purely because we stopped looking. Filtering on a partial
		-- answer would hide real exits, which is the single failure this filter must never commit; so a
		-- truncated flood stands down completely and the console says so.
		-- Canalave Gym: the list offers what some sequence of rides reaches, on any floor.
		if occ_ok and terrain.canalave.active(fs, cache) then
			local snap = terrain.canalave.snapshot(fs, cache)
			local cocc = snap and terrain.canalave.occupancy(fs)
			pas_seen = cocc and terrain.canalave.search(snap, px, pz, cocc) or nil
			veil_unknown = pas_seen == nil
		end
		-- Snowpoint Gym: what some sequence of presses comes to rest beside, from the planner's own search.
		if occ_ok and terrain.snowpoint.active(fs, cache) then
			pas_seen = terrain.snowpoint.flood(fs)
			veil_unknown = pas_seen == nil
		end
		local seen, complete = reach_from(fs, px, pz, reach_occ, cache)
		local whole_cache
		if pas_seen then seen, complete = pas_seen, true end
		-- Warp panels within this map (the Galactic HQ): the list offers whatever a chain of them
		-- reaches, the player's choice (2026-11-03), as the router steps onto them itself.
		local panel_map = false
		if occ_ok and not pas_seen and not veil_unknown then
			local union, whole = terrain.panel_search(fs, px, pz, reach_occ, cache)
			if union then
				panel_map = true
				if whole then
					for k in pairs(seen or {}) do union[k] = true end
					seen, complete = union, true
				else complete = false end
			end
		end
		cache.hm_seen = nil
		local hm_note
		if occ_ok and next(gates) then
			local discovery = terrain.hm_discovery(fs,px,pz,cache)
			local gated, finished = reach_from(fs, px, pz, occ, discovery or cache, gates)
			if finished then cache.hm_seen = gated end
			hm_note = string.format("HM flood %s, %s", discovery and "whole area" or "loaded cells only",
				finished and "complete" or "incomplete")
		end
		-- ⛔ A MAP OF SEVERAL CELLS LOADS ONLY THE ONES NEAR THE PLAYER, so there the live flood stops
		-- at the loaded edge and the filter used to stand down, and the attribute-only component that
		-- replaced it walks through people and closed doors: Galactic HQ B2F offered the Galactic Key
		-- behind its locked door from the warehouse stairs. The whole-area geometry (the cartridge
		-- where a cell is not loaded) floods it with the same occupancy; only a complete answer filters.
		-- ⚠ ONLY WHERE THE WHOLE MATRIX IS THIS ONE MAP (an interior). That flood keeps to the current
		-- map (route_scope), while outdoors the walkable ground can loop through a neighbouring map's
		-- cells; there it hid Eterna City's route edges and distant doors that the unscoped live flood
		-- and the component correctly keep (pt-area-visibility harness).
		-- ⚠ AND NOT WHEN AN OBSTACLE'S FAR SIDE IS UNKNOWN. This flood treats Cut trees, Rock Smash
		-- rocks and boulders as walls; what lies beyond them is restored only by the gated flood's
		-- labels (cache.hm_seen), so with obstacles about it applies only once that flood finished
		-- (independent review: Victory Road's gated flood can run out of room where this one does not).
		if occ_ok and not complete and not pas_seen and not veil_unknown and not panel_map
			and (not next(gates or {}) or cache.hm_seen) then
			local dc = terrain.hm_discovery(fs, px, pz, cache)
			local headers, here = cache.matrix_headers, map_id(fs)
			for _, h in pairs(headers or {}) do if h ~= here then dc = nil end end
			if dc and headers then
				local c = {}
				for k, v in pairs(dc) do if k ~= "reach" and k ~= "hm_reach" then c[k] = v end end
				local whole, ok = reach_from(fs, px, pz, reach_occ, c)
				if ok then
					for k in pairs(seen or {}) do whole[k] = true end
					seen, complete = whole, true
					whole_cache = dc
				end
			end
		end
		-- Victory Road: the same flood again without ledge jumps. What the ordinary flood reaches and
		-- this one does not is reached only by jumping down a ledge, and is marked (terrain.ledge_word).
		-- It is the same question the filter asks, from the same caches: the live one, plus the
		-- whole-area one when that is what completed the answer. Anything uncertain marks nothing.
		local ledge_free
		if complete and occ_ok and not veil_unknown and not pas_seen and not panel_map
			and seen and terrain.ledge_maps[map_id(fs)] then
			local function free(base)
				local c = { no_ledges = true }
				for k, v in pairs(base) do if k ~= "reach" and k ~= "hm_reach" and k ~= "no_ledges" then c[k] = v end end
				return reach_from(fs, px, pz, reach_occ, c)
			end
			local live, live_ok = free(cache)
			if whole_cache then
				local whole, whole_ok = free(whole_cache)
				if whole_ok then
					for k in pairs(live) do whole[k] = true end
					ledge_free = whole
				end
			elseif live_ok then ledge_free = live end
			if not ledge_free then dbg("nav: ledge-free flood incomplete — no Ledge marks") end
		end
		-- The attribute-only component knows nothing of warp panels, so it cannot prove a panel map.
		cache.discovery_component = not complete and occ_ok and not panel_map and terrain.map_component(fs, px, pz, cache) or nil
		-- ⛔ AND AN UNREADABLE ACTOR MANAGER STANDS THE FILTER DOWN TOO. `occ` empty could mean "nobody
		-- about" or "we could not read the manager", and those are not the same claim — filtering on
		-- the second would hide entries on the strength of a failed read.
		if not complete or not occ_ok or veil_unknown then
			dbg(veil_unknown and "nav: gym puzzle unverified — not filtering"
				or complete and "nav: occupancy unreadable — not filtering"
				or "nav: reachability told us nothing — not filtering")
			seen = nil
		end
		-- On the water, the lists are what the water reaches plus the ways ashore (terrain.afloat).
		local afloat = ((terrain.motion(fs, cache) or 0) & 3) == 2
		local water = afloat and terrain.afloat(fs, px, pz, cache) or nil
		if water then
			for _, e in ipairs(water.entries) do
				local best, bd
				for _, s in ipairs(e.spots) do
					local d = math.abs(s[1] - px) + math.abs(s[2] - pz)
					if not bd or d < bd then best, bd = s, d end
				end
				lists.Transitions[#lists.Transitions + 1] = { name = e.name, key = e.key, spots = e.spots,
					landing = true, x = best[1], z = best[2] }
			end
		end
		local was = active[ci]
		active = {}
		for _, c in ipairs(CATS) do
			if afloat then lists[c] = terrain.afloat_filter(fs, lists[c], water, reach_occ, px, pz, cache)
			else
				local before = lists[c]
				lists[c] = reachable_filter(fs, before, seen, reach_occ, px, pz, cache)
				if ledge_free and seen then
					for _, e in ipairs(lists[c]) do
						local full, plain = false, false
						for _, g in ipairs(goals_for(fs, e, reach_occ, px, pz, cache, true)) do
							local x, z = g[1], g[2]
							if e.connection then x, z = x - STEPD[e.direction][1], z - STEPD[e.direction][2] end
							full = full or seen[tkey(x, z)] ~= nil
							plain = plain or ledge_free[tkey(x, z)] ~= nil
						end
						if full and not plain then e.gate = (e.gate and (e.gate .. ", ") or "") .. terrain.ledge_word end
					end
				end
				-- ⭐ WHICH DOORS THE FILTER HID, IN THE CONSOLE (Rule 9). A missing exit is the one thing
				-- the player cannot report precisely, so the log names it, once per change.
				if c == "Transitions" and #lists[c] < #before then
					local kept, gone = {}, {}
					for _, e in ipairs(lists[c]) do kept[e] = true end
					for _, e in ipairs(before) do
						if not kept[e] then gone[#gone + 1] = string.format("%s (%d,%d)", e.name, e.x, e.z) end
					end
					local note = string.format("nav: hidden from (%d,%d): %s; %s", px, pz, table.concat(gone, ", "),
						hm_note or "no HM flood")
					if note ~= terrain.hidden_note then terrain.hidden_note = note; dbg(note) end
				end
			end
			if #lists[c] > 0 then active[#active + 1] = c end
		end
		apply_want(was)
		sort_cat(px, pz)
		-- Put `ii` back on the entry he was actually on, wherever the re-sort moved it to.
		if sel_key then
			local l, found = cur_list(), nil
			for i, e in ipairs(l) do if e.key == sel_key then found = i; break end end
			if found then ii = found
			elseif entered then ii, entered = 1, false end   -- it is gone: make the next press say so
		end
		return true, cache, occ, occ_ok
	end

	-- "<name>, <bearing>, X of Y" — Black and White's line, unchanged. `label` carries the duplicate
	-- number ("Potion 2") when a category holds the same word twice, and is plain `name` otherwise;
	-- falling back to `name` keeps this honest if a list is ever spoken before sort_cat numbered it.
	local function item_line(e, idx, n, px, pz)
		return (e.label or e.name) .. (e.gate and (", " .. e.gate) or "") .. ", " .. dirword(px, pz, e.x, e.z) .. ", " .. idx .. " de " .. n
	end
	local function announce_item(px, pz, interrupt)
		local l = cur_list(); if #l == 0 then return end
		if ii < 1 then ii = #l elseif ii > #l then ii = 1 end     -- the list wraps, both ways
		sel_key = l[ii].key                                       -- this is now the remembered one
		say(item_line(l[ii], ii, #l, px, pz), interrupt)
	end
	-- Landing on a category: its name INTERRUPTS, the item it lands on QUEUES behind it (Ola,
	-- 2026-08-04). Changing category IS navigation, so it must cut off whatever was still being said —
	-- but the item belongs to the same press and must not cut the category off in turn.
	local function announce_cat(px, pz)
		say(({ Transitions = "Salidas", NPCs = "Personas", Items = "Objetos", HM = "Obstáculos MO", Signs = "Carteles", Objects = "Objetos del entorno", ["Honey trees"] = "Árboles de miel" })[cur_cat()] or cur_cat(), true)
		local l = cur_list()
		if #l > 0 then
			sel_key = l[1].key
			say(item_line(l[1], 1, #l, px, pz), false)
		end
	end
	local function switch_cat(dir, px, pz)
		if #active == 0 then return end
		ci = ((ci - 1 + dir) % #active) + 1
		ii = 1
		sort_cat(px, pz)
		want_cat = active[ci]                  -- an actual press: THIS is the remembered choice
		announce_cat(px, pz)
	end

	-- ⛔ HOW MANY TIMES EACH KEY HAS REACHED THIS MODULE. When p "does nothing", there are two
	-- completely different worlds — the press never got here, or it got here and every branch said
	-- no — and from outside they are identical. One counter each settles it in the dump.
	local presses = { I = 0, O = 0, J = 0, K = 0, L = 0, P = 0, C = 0, N = 0 }

	-- ── N: THE DIAGNOSTIC DUMP ──────────────────────────────────────────────────────────────────
	--
	-- ⛔⛔ INSTRUMENTS BEAT INFERENCE, and this exists because of the alternative. Ola reported
	-- 2026-09-05 that the nav list and the place names worked but p produced no route, and there are
	-- at least six hops that would each produce exactly that symptom while looking identical from
	-- outside — the reachability filter FAILS OPEN when the ground cannot be read, so a completely
	-- dead terrain chain still shows a full, correct-looking list and refuses every route. Five
	-- reasoning attempts is what the Gen V equivalent cost before someone printed the values.
	--
	-- So: one key, every hop in order, to the Lua console only — it never speaks. The first line that
	-- reads "nil" or "UNKNOWN" is the bug.
	-- ⭐ IT WRITES A FILE AND SAYS SO. A console-only dump gives a blind player no way to tell it ran
	-- (Ola, 2026-09-05: "making me confused on if I actually dumped or not"), and a console is a bad
	-- place to read one from. Same convention as Black and White's building dump — append to a file,
	-- speak one short line — and the writer itself now lives in core/dump.lua because it is the same
	-- job in every game, which was his suggestion.
	local dump_seq = 0
	local function dump(fs, px, pz)
		dump_seq = dump_seq + 1
		local out = {}
		local function dbg(line) out[#out + 1] = line end     -- shadows the console logger on purpose
		dbg(string.format("==== overworld dump #%d ====", dump_seq))
		-- ⛔ THE PRESS COUNTS COME FIRST, because they answer a question nothing else can: if P reads
		-- 0 here after he has pressed p, the key never reached this module and every terrain number
		-- below is beside the point.
		local pk = {}
		for _, k in ipairs({ "I", "O", "J", "K", "L", "P", "C", "N" }) do
			pk[#pk + 1] = string.format("%s=%d", k, presses[k])
		end
		dbg("key presses this module has seen: " .. table.concat(pk, " "))
		if pastoria.active(fs, {}) then
			local snap, why = pastoria.snapshot(fs, {})
			local armed = 0
			for _, b in ipairs(snap and snap.buttons or {}) do if b.level ~= snap.level then armed = armed + 1 end end
			dbg(snap and string.format("Pastoria Gym: level %d, %d buttons, %d armed", snap.level, #snap.buttons, armed)
				or ("Pastoria Gym: unverified (" .. tostring(why) .. ")"))
		end
		if terrain.snowpoint.active(fs, {}) then dbg(terrain.snowpoint.describe(fs)) end
		if terrain.sunyshore.active(fs, {}) then
			local snap, why = terrain.sunyshore.snapshot(fs, {})
			dbg(snap and string.format("Sunyshore Gym: room %d, state %d, %d buttons", snap.room + 1, snap.state, #snap.buttons)
				or ("Sunyshore Gym: unverified (" .. tostring(why) .. ")"))
		end
		local tcm = u32(fs + FS_TCM)
		local mode = (tcm == A.sTerrainCollision and "streamed")
			or (tcm == A.sSimpleTerrainCollis and "whole-matrix") or "UNKNOWN"
		dbg(string.format("fs=%08X  terrainCollisionMan=%08X (%s)", fs, tcm, mode))
		dbg(string.format("expected: streamed=%08X  whole-matrix=%08X",
			A.sTerrainCollision, A.sSimpleTerrainCollis))
		local mm2, ta = u32(fs + FS_MATRIX), u32(fs + FS_TATTR)
		dbg(string.format("mapMatrix=%08X %dx%d   terrainAttributes=%08X", mm2,
			inram(mm2) and u8(mm2 + 0) or -1, inram(mm2) and u8(mm2 + 1) or -1, ta))
		local ld = u32(fs + FS_LAND)
		-- ⚠ +0xC0/+0xC4 are the MAP MATRIX's dimensions, not a window's — the old model's word for them
		-- was "window", and a diagnostic that names a thing wrongly costs the next reader a wrong theory.
		dbg(string.format("landDataMan=%08X  offsetTile %d,%d  matrix %dx%d maps  (%d loaded slots)",
			ld, inram(ld) and s32(ld + LDM_OFFX) or -1, inram(ld) and s32(ld + LDM_OFFZ) or -1,
			inram(ld) and s32(ld + LDM_W) or -1, inram(ld) and s32(ld + LDM_H) or -1, LOADED_SLOTS))
		-- ⭐ THE FOUR LOADED MAPS, EACH WITH THE CELL IT SAYS IT HOLDS. This is the line that mattered:
		-- the maps are a window that ROTATES as you walk, so the one you are standing on can be in any
		-- slot, and reading slot 0 got unwritten memory (0xFFFF) in Ola's bedroom.
		-- ⛔⛔ THE DUMP MUST DO THE READER'S ARITHMETIC, NOT ITS OWN. This block used to compute the
		-- cell from the raw tile and the MapMatrix's width, which is what the READ used to do — so
		-- after the read moved to the land manager's offsets and width, the diagnostic quietly
		-- disagreed with the code it exists to explain, and would have pointed the next
		-- investigation at the wrong slot. It is also no longer gated on the MapMatrix being
		-- readable: the streamed read does not need it, so a broken matrix must not delete the one
		-- section of the dump that would say so (codex-review, confirmed).
		if inram(ld) then
			local mw, mh = s32(ld + LDM_W), s32(ld + LDM_H)
			local fx, fz = px - s32(ld + LDM_OFFX), pz - s32(ld + LDM_OFFZ)
			local pcell = -1
			if fx >= 0 and fz >= 0 and mw >= 1 and mh >= 1
				and fx < mw * TILES and fz < mh * TILES then
				pcell = (fx // TILES) + (fz // TILES) * mw
			end
			dbg(string.format("player tile (%d,%d) -> fixed (%d,%d) -> matrix cell %d  (manager %dx%d)",
				px, pz, fx, fz, pcell, mw, mh))
			local matched = false
			for i = 0, LOADED_SLOTS - 1 do
				local lm = u32(ld + LDM_ATTRS + i * 4)
				local hit = inram(lm) and inram(lm + LM_VALID + 3)
					and s32(lm + LM_CELL) == pcell and u32(lm + LM_VALID) ~= 0
				matched = matched or hit
				dbg(string.format("  loaded map %d: %08X  cell=%s valid=%s%s", i, lm,
					inram(lm) and tostring(s32(lm + LM_CELL)) or "-",
					inram(lm) and tostring(u32(lm + LM_VALID)) or "-",
					hit and "   <-- the one under you" or ""))
			end
			-- ⭐ SAY IT OUT LOUD WHEN NOTHING MATCHES. That is the failure this whole key exists for,
			-- and leaving the reader to spot an absent arrow is how it went unnoticed the first time.
			if not matched then
				dbg("  NO LOADED MAP CLAIMS THAT CELL — every tile here will read UNKNOWN")
			end
		else
			dbg("no landDataMan — the streamed read cannot work at all")
		end

		local a = tile_attrs(fs, px, pz)
		dbg(string.format("player tile (%d,%d) attrs=%s walk=%s", px, pz,
			a and string.format("%04X", a) or "nil", tostring(tile_walk(fs, px, pz))))
		for dir = 0, 3 do
			local d = STEPD[dir]
			local na = tile_attrs(fs, px + d[1], pz + d[2])
			dbg(string.format("  %-5s (%d,%d) attrs=%s step=%s", STEPNAME[dir],
				px + d[1], pz + d[2], na and string.format("%04X", na) or "nil",
				tostring(step_ok(fs, px, pz, dir))))
		end
		local occ, ok = occupied(fs)
		local n = 0; for _ in pairs(occ) do n = n + 1 end
		dbg(string.format("occupancy ok=%s  %d tiles blocked", tostring(ok), n))

		-- ⭐ EVERY LIVE OBJECT, RAW. This half answers a different question from the terrain half, and
		-- it is here because Ola reported something listed as a Sign that he thought was actually the
		-- rival (2026-09-05). Which of these an object IS cannot be settled by reading the ROM — the
		-- graphics id is the only classifier the engine itself uses — so the way to settle it is to
		-- stand next to the thing and print what the game says about it.
		local mm3 = u32(fs + FS_OBJMAN)
		if inram(mm3) then
			local arr, cnt = u32(mm3 + MOM_ARRAY), s32(mm3 + MOM_MAX)
			if inram(arr) and cnt == MOM_EXPECT then
				local pa = u32(fs + FS_AVATAR)
				local pmo = inram(pa) and u32(pa + PA_OBJ) or nil
				for i = 0, cnt - 1 do
					local o = arr + i * MO_STRIDE
					local st = u32(o + MO_STATUS)
					if (st & MO_INUSE) ~= 0 then
						local gfx = u32(o + MO_GFX)
						local kind = (o == pmo and "PLAYER")
							or (gfx == GFX_BALL and "item")
							or (gfx >= GFX_HM_LO and gfx <= GFX_HM_HI and "HM")
							or (gfx >= GFX_SIGN_LO and gfx <= GFX_SIGN_HI and "SIGN")
							or (gfx == GFX_DETACHED and "no-graphics") or "person"
						dbg(string.format(
							"  obj %2d gfx=%3X %-11s (%d,%d) status=%08X local=%d trainer=%d script=%d",
							i, gfx, kind, s32(o + MO_X), s32(o + MO_Z), st,
							u32(o + MO_LOCALID), u32(o + MO_TRAINER), u32(o + MO_SCRIPT)))
					end
				end
			end
		end
		local l = cur_list()
		local e = (#l > 0 and ii >= 1 and ii <= #l) and l[ii] or nil
		if e then
			local cands, certain = goals_for(fs, e, occ, px, pz)
			local cs = {}
			for _, c in ipairs(cands) do cs[#cs + 1] = string.format("(%d,%d)", c[1], c[2]) end
			dbg(string.format("selected '%s' at (%d,%d)  endpoints=[%s] certain=%s",
				tostring(e.label or e.name), e.x, e.z, table.concat(cs, " "), tostring(certain)))
			for _, c in ipairs(cands) do
				local r, why = pf_build(fs, px, pz, c[1], c[2], "probe", occ)
				dbg(string.format("  -> (%d,%d): %s", c[1], c[2],
					r and (r.total .. " moves, first '" .. tostring(r.segs[1]) .. "'")
					  or ("none (" .. tostring(why) .. ")")))
			end
		else
			dbg("no entry selected (open the list with j/k/l first)")
		end
		dbg("")
		local nm2 = area_name(map_id(fs))
		dumpf.write("platinum-dump.txt", out,
			string.format("%s, dump %d", nm2 or "unknown area", dump_seq), say)
	end

	-- HandleFieldInput can run a pending on-frame cutscene before accepting input.
	-- Native movement pauses and init-table consumers: 02063410, 02062DE8,
	-- 0203F638; MapHeaderData_GetInitScriptBytes reads fs+14 -> header+820.
	local map_notice = {}
	function map_notice.fail(reason)
		if map_notice.error ~= reason then dbg("map announcement: " .. reason) end
		map_notice.error = reason
		return false
	end
	function map_notice.ready(fs, id)
		local avatar = u32(fs + FS_AVATAR)
		if not inram(avatar + 0x33) then return map_notice.fail("player avatar unreadable") end
		local object = u32(avatar + 0x30)
		if not inram(object) or not inram(object + MO_STRIDE - 1) then
			return map_notice.fail("player object unreadable")
		end
		local status = u32(object)
		if status & MO_INUSE == 0 then return map_notice.fail("player object inactive") end
		if status & 0x40 ~= 0 then return false end -- native PauseMovement
		local manager = u32(object + 0xB4)
		if not inram(manager) or not inram(manager + 0x12B) then
			return map_notice.fail("object manager unreadable")
		end
		if manager ~= u32(fs + FS_OBJMAN) or u32(manager + 0x128) ~= fs then
			return map_notice.fail("player owner mismatch")
		end
		if u32(manager) & 2 ~= 0 then return false end -- native StopAllMovement
		local header = u32(fs + 0x14)
		if not inram(header) or not inram(header + 0x91F) then
			return map_notice.fail("map initialization data unreadable")
		end
		local cached = map_notice.cache
		if not cached or cached.fs ~= fs or cached.id ~= id or cached.header ~= header then
			-- Bounded native data structure, decoded once per map/field ownership period.
			local first, limit, records = header + 0x820, header + 0x920, {}
			local p, found = first, false
			while p < limit do
				local kind = u8(p)
				if kind == 0 then found = true; break end
				if p + 5 > limit then return map_notice.fail("truncated initialization entry") end
				if kind == 1 then
					local offset = u32(p + 1)
					if offset == 0 then found = true; break end
					p = p + 5 + offset
					if p < first or p >= limit then return map_notice.fail("initialization branch outside buffer") end
					while p < limit do
						-- Retail 0203F672 checks the low byte before reading the u16 variable.
						if u8(p) == 0 then found = true; break end
						if p + 6 > limit then return map_notice.fail("truncated initialization condition") end
						records[#records + 1] = {u16(p), u16(p + 2), u16(p + 4)}
						p = p + 6
					end
					break
				end
				p = p + 5
			end
			if not found then return map_notice.fail("unterminated initialization data") end
			cached = {fs=fs, id=id, header=header, records=records}
			map_notice.cache = cached
		end
		-- Current save identity is the field consumer's save pointer, not a stale static.
		if #cached.records > 0 and u32(fs + 0x0C) ~= u32(A.sSaveDataPtr) then
			return map_notice.fail("field save owner mismatch")
		end
		for _, row in ipairs(cached.records) do
			local lhs, rhs = story_var(row[1]), story_var(row[2])
			-- Out-of-range persistent variables and script-local scratch are unknown here.
			if lhs == nil or rhs == nil then return map_notice.fail("initialization variable unavailable") end
			if lhs == rhs then
				-- First matching row ends native lookup, including the 0xFFFF sentinel.
				map_notice.error = nil
				return row[3] == 0xFFFF
			end
		end
		map_notice.error = nil
		return true
	end

	-- ── THE MODULE ──────────────────────────────────────────────────────────────────────────────
	local prev_place, prev_id

	MODULES[#MODULES + 1] = {
		name = "overworld",
		detect = function() return field_ready() ~= nil end,
		-- ⚠ NOTHING IS RESET ON ENTER. Coming back from a conversation or a menu is not arriving
		-- somewhere new, and re-announcing the place every time a message box closes would make the
		-- overworld unusable. `prev_place` is a memory of the WORLD, not of this module's turn at the
		-- frame, so it deliberately outlives both.
		update = function(pressed)
			local fs = field_ready()
			if not fs then return end
			local id = map_id(fs)
			terrain_notice = grass_boundary(fs, id)
			hearthome.step(fs,id)
			local radar_controls = dowsing.step(fs, pressed)

			-- ⭐ ANNOUNCE ON A CHANGE OF NAME, NOT A CHANGE OF MAP. Gen V settled this and Gen IV needs
			-- it more, not less: a town is many map headers (Twinleaf is 411 plus six houses, all
			-- carrying label 1), so announcing per header would say "Twinleaf Town" through every door.
			-- ⭐ AND GEN IV NAMES MORE THAN GEN V DID. 125 of bank 433's 126 names are used by some
			-- header, and notable interiors carry their OWN label — header 8 is "Poketch Co." — so this
			-- one rule gives named buildings for free where Gen V needed a hand-curated table. A house
			-- the game does not name keeps its town's name and therefore stays silent, which is the
			-- same behaviour Ola already knows.
			local nm = area_name(id)
			-- ⛔ TWO KNOWN, DIFFERENT IDS — never one known and one nil. A transient bad read would
			-- otherwise look exactly like walking through a door and would silently destroy a live
			-- route (codex-review verification pass). An unreadable id changes nothing at all.
			if id and prev_id ~= id then
				local was_known = prev_id ~= nil
				prev_id = id
				terrain.saved = nil
				-- ⛔ A ROUTE DOES NOT SURVIVE A DOORWAY. Its goal is a pair of TILE COORDINATES, and
				-- those mean something completely different in the map you have just walked into — so
				-- a route kept across a map change would quietly re-plan towards whatever happens to
				-- be at those coordinates here. Dropped silently, because the place name that follows
				-- already says he is somewhere new; announcing the cancellation as well would be the
				-- tool talking about itself.
				if was_known then pf, pf_reenter, eterna.intent, eterna.reenter = nil, false, nil, false end
			end
			if id and nm and nm ~= prev_place and map_notice.ready(fs, id) then
				prev_place = nm
				say(nm)
			end

			if radar_controls then return end

			-- ⛔ NOTHING BELOW RUNS ON AN IDLE FRAME. Navigation's player read, object walk and search
			-- are all gated behind "a route is live, or a key was pressed" — Rule 3 is about what the
			-- tool costs when the player is simply walking, which is nearly all of the time.
			for k in pairs(presses) do if pressed[k] then presses[k] = presses[k] + 1 end end
			local navkey = pressed["I"] or pressed["O"] or pressed["J"] or pressed["K"] or pressed["L"]
			if not (pf or (eterna.intent and (eterna.reenter or eterna.intent.stay)) or navkey or pressed["P"] or pressed["C"] or pressed["N"] or pressed["D"]) then return end

			local px, pz, face = player(fs)
			if not px then return end

			-- The shared gym wait: Eterna's resumes on a clock stage, Veilstone's when a kick moved something,
			-- Pastoria's when a press has changed the level and the water has stopped moving.
			if eterna.intent and eterna.intent.panel and (eterna.reenter or navkey or pressed["P"]) then
				-- Warp panel: once the warp has put the player somewhere else in this map (the warp
				-- is a field task, so this frame is after it), plan the next leg from the landing.
				local back = eterna.reenter
				eterna.reenter = false
				local intent = eterna.intent
				if intent.fs ~= fs then eterna.intent = nil
				-- Back on the frame while still on the panel: something ran before the warp (a coord
				-- event comes first in Field_ProcessStep), so plan again from here, which steps off and on.
				elseif back or px ~= intent.panel.x or pz ~= intent.panel.z then
					local occ, ok = occupied(fs)
					if ok then
						eterna.intent = nil
						local name = intent.entry.label or intent.entry.name
						local entry = terrain.panel_entry(fs, intent)
						local r, why2
						if entry then r, why2 = pf_plan(fs, px, pz, entry, occ, {}) end
						if r then pf = r; if r.segs[1] then say(r.segs[1]) end
						elseif why2 == "limit" or why2 == "terrain" then say("Todavía no encuentro ruta hasta " .. name)
						else say("No se puede llegar a " .. name .. " desde aquí") end
					else eterna.reenter = true end
				end
			elseif eterna.intent and eterna.intent.canalave and (eterna.reenter or navkey or pressed["P"]) then
				-- Canalave Gym: once the platform has stopped (a ride is a field task, so this frame is
				-- after it), plan the next leg from wherever it put the player.
				eterna.reenter = false
				local intent = eterna.intent
				local snap = terrain.canalave.snapshot(fs, {})
				if not snap or intent.fs ~= fs then eterna.intent = nil
				elseif snap.sig ~= intent.canalave then
					local occ, ok = occupied(fs)
					if ok then
						local r, why2 = pf_plan(fs, px, pz, intent.entry, occ, {})
						eterna.intent = nil
						local name = intent.entry.label or intent.entry.name
						if r then pf = r; say(r.segs[1] or "continúa")
						elseif why2 == "limit" or why2 == "terrain" then say("Todavía no encuentro ruta hasta " .. name)
						else say("No se puede llegar a " .. name .. " desde aquí") end
					else eterna.reenter = true end
				end
			elseif eterna.intent and eterna.intent.pastoria and (eterna.reenter or navkey or pressed["P"]) then
				eterna.reenter = false
				local intent = eterna.intent
				local query = {}
				local snap, why = pastoria.snapshot(fs, query)
				if intent.fs ~= fs or not pastoria.active(fs, query) then eterna.intent = nil
				elseif not snap then
					if why == "water moving" then eterna.reenter = true else eterna.intent = nil end
				elseif snap.sig ~= intent.pastoria then
					local occ,ok = occupied(fs)
					if ok then
						local r,why2 = pf_plan(fs,px,pz,intent.entry,occ,query)
						eterna.intent = nil
						local name = intent.entry.label or intent.entry.name
						if r then pf = r; say(r.segs[1] or "continúa")
						elseif why2 == "limit" or why2 == "terrain" then say("Todavía no encuentro ruta hasta " .. name)
						else say("No se puede llegar a " .. name .. " desde aquí") end
					else eterna.reenter = true end
				end
			elseif eterna.intent and eterna.intent.sunyshore and (eterna.reenter or navkey or pressed["P"]) then
				-- Sunyshore Gym: the press stored the new state before the gears turned, and they turn
				-- inside the press script, so the first frame with control after it is the time to plan.
				eterna.reenter = false
				local intent = eterna.intent
				local query = {}
				local snap = terrain.sunyshore.snapshot(fs, query)
				if not snap or intent.fs ~= fs then eterna.intent = nil
				elseif snap.sig ~= intent.sunyshore then
					local occ, ok = occupied(fs)
					if ok then
						local r, why2 = pf_plan(fs, px, pz, intent.entry, occ, query)
						eterna.intent = nil
						local name = intent.entry.label or intent.entry.name
						if r then pf = r; say(r.segs[1] or "continúa")
						elseif why2 == "limit" or why2 == "terrain" then say("Todavía no encuentro ruta hasta " .. name)
						else say("No se puede llegar a " .. name .. " desde aquí") end
					else eterna.reenter = true end
				end
			elseif eterna.intent and eterna.intent.veil and (eterna.reenter or navkey or pressed["P"]) then
				eterna.reenter = false
				local intent = eterna.intent
				local query = {}
				local snap = veilstone.snapshot(fs)
				if not snap or intent.fs ~= fs then eterna.intent = nil
				elseif snap.sig ~= intent.veil then
					local occ,ok = occupied(fs)
					if ok then
						local r,why = pf_plan(fs,px,pz,intent.entry,occ,query)
						eterna.intent = nil
						local name = intent.entry.label or intent.entry.name
						if r then pf = r; if r.segs[1] or not (r.kick or r.strength) then say(r.segs[1] or "continúa") end
						elseif why == "limit" or why == "terrain" then say("Todavía no encuentro ruta hasta " .. name)
						else say("No se puede llegar a " .. name .. " desde aquí") end
					else eterna.reenter = true end
				end
			elseif eterna.intent and (eterna.reenter or navkey or pressed["P"]) then
				eterna.reenter = false
				local intent = eterna.intent
				local query = {}
				local state = eterna.snapshot(fs,query)
				local target = state and eterna.effective(fs,intent.entry,query)
				if not state or not target or intent.fs ~= fs then eterna.intent = nil
				elseif state.state > intent.state then
					local occ,ok = occupied(fs)
					if ok then
						local r = pf_plan(fs,px,pz,intent.entry,occ,query)
						eterna.intent = nil
						if r then pf = r; say(r.segs[1] or "continúa")
						else say("Todavía no encuentro ruta hasta " .. (intent.entry.label or intent.entry.name)) end
					else eterna.reenter = true end
				elseif state.state < intent.state then eterna.intent = nil end
			end
			-- A gym wait for a press or a ride is tied to the tiles where it can still happen (the
			-- button or platform, and the tile beside it when the next step is back onto it). Walking
			-- anywhere else is leaving the route, so it re-plans the way any route does. A press or a
			-- ride takes the frame (on_exit arms reenter), so this never runs in its place.
			if eterna.intent and eterna.intent.stay and not eterna.reenter and not pressed["P"]
				and eterna.intent.fs == fs and not eterna.intent.stay[tkey(px, pz)] then
				local occ, ok = occupied(fs)
				if ok then
					local intent = eterna.intent
					eterna.intent = nil
					local name = intent.entry.label or intent.entry.name
					local r, why2 = pf_plan(fs, px, pz, intent.entry, occ, {})
					if r then pf = r; say("Recalculando. " .. (r.segs[1] or ""))
					elseif why2 == "limit" or why2 == "terrain" then say("Todavía no encuentro ruta hasta " .. name)
					else say("No se puede llegar a " .. name .. " desde aquí") end
				end
			end

			-- C: where am I, exactly. Says the place first so the answer stands alone.
			-- ⚠ "X" and "Y" are what Black and White say, and the axis names stay identical across the
			-- games on purpose even though this engine calls the second one Z — the player is learning
			-- one tool, not two.
			if pressed["C"] then
				say(string.format("%s. X %d, Y %d, facing %s.",
					nm or "Unknown area", px, pz, FACEWORD[face] or "?"))
			end

			-- N: the diagnostic dump. Console only, never spoken — it is an instrument, not a reader.
			if pressed["N"] then dump(fs, px, pz) end

			-- ⛔ IN DEEP FOG OR AN UNLIT CAVE THE LIST AND THE ROUTER STAND DOWN (PM.covered), as
			-- Black and White does for its dark caves: every nav key and P answer with the one line,
			-- and a route already running is dropped with it (a saved state can put one there).
			-- P on a running route still says "Guiado desactivado", so a route can always be cancelled.
			-- Place names, C and N keep working. Read only on a key press or while a route is live.
			if pf or eterna.intent or navkey or pressed["P"] then
				local covered = PM.covered()
				if covered then
					local running = pf or eterna.intent
					pf, pf_reenter, eterna.intent, eterna.reenter = nil, false, nil, false
					if running and pressed["P"] then say("Guiado desactivado", true)
					elseif running or navkey or pressed["P"] then say(covered, true) end
					return
				end
			end

			-- The route. ⚠ OCCUPANCY IS BUILT ONLY WHEN A PLAN IS ACTUALLY MADE, not on every frame of
			-- following one: walking the middle of a straight leg needs no object walk at all, and
			-- doing it anyway was a 64-slot read per frame whose answer was thrown away (codex-review,
			-- confirmed). `pf_reenter` re-plans and re-announces on the frame we get control back after
			-- a conversation, a battle or a menu, because the player has not MOVED and a follower that
			-- only speaks on movement would leave him standing in silence.
			if pf and pf.entry and pf.entry.hidden and not dowsing.available(fs, pf.entry) then
				pf, pf_reenter = nil, false
				say(dowsing.text.stopped, true)
			end
			if pf then
				if pf_reenter and pf.slides and not terrain.snowpoint.at_rest(fs) then
					-- Snowpoint Gym: back from a battle mid-slide, wait until the slide has ended.
				elseif pf_reenter then
					pf_reenter = false
					local occ, occ_ok = occupied(fs)
					local r, why, face
					if occ_ok then
						r, why, face = pf_plan(fs, px, pz, pf.entry, occ)
					end
					-- A kick from where the player stands says nothing here; the follower names the bag.
					if r then pf = r; if r.segs[1] or not (r.kick or r.strength or r.hm) then say(r.segs[1] or "continúa") end
					elseif why == "done" then pf = nil
					elseif why == "here" then
						say("Has llegado a " .. (pf.name or "destino") .. (PFWORD[face] and (", 1 " .. PFWORD[face]) or ""))
						pf = nil
					elseif occ_ok and (why == "limit" or why == "terrain") then
						-- Ran out of room; that is about us, not about the world.
						say("Todavía no encuentro ruta hasta " .. (pf.name or "destino")); pf = nil
					elseif occ_ok then
						say("No se puede llegar a " .. (pf.name or "destino") .. " desde aquí"); pf = nil
					else
						-- Unreadable occupancy is not a reason to claim he cannot get there; keep the
						-- route and try again next frame.
						pf_reenter = true
					end
				else
					pf_follow(fs, px, pz)
				end
			end

			-- ── THE NAV KEYS ────────────────────────────────────────────────────────────────────
			local cache, nav_occ, nav_occ_ok
			if navkey or pressed["P"] then
				-- A slow press prints to the console and nowhere else, exactly as Black and White does
				-- it: a lag report needs a number beside it, and the player must never hear about it.
				local t0 = os.clock and os.clock()
				local ok
				ok, cache, nav_occ, nav_occ_ok = refresh(fs, px, pz)
				if t0 then
					local ms = (os.clock() - t0) * 1000
					if ms > 50 then dbg(string.format("nav: SLOW refresh %d ms", math.floor(ms + 0.5))) end
				end
				-- ⛔ A FAILED REFRESH IS NOT AN EMPTY ROOM, AND P MUST NOT ACT ON A STALE ONE. If the
				-- map could not be identified, the lists still describe wherever we were last — so
				-- routing from them would aim at coordinates in another place entirely. Say nothing,
				-- do nothing, and log it (codex-review, confirmed).
				if not ok then
					dbg("nav: refresh failed — no list this press")
					return
				end
				if #active == 0 then
					if navkey then say("No hay nada cerca", true) end
					return
				end
				-- ⛔ P MUST NOT ACT ON A LIST WHOSE MEANING HAS CHANGED SILENTLY. `entered` is false
				-- exactly when the category was rebuilt or restored under him, and until he has heard
				-- what he is on, a route started from it would be a route to something he never chose.
				-- So P falls back to naming the list first, which is one press, and then works.
				if not entered then
					entered = true
					-- ⭐ AND OPENING THE LIST ON A CATEGORY COUNTS AS BEING IN IT, IF HE HAS NO
					-- PREFERENCE YET (codex-review, and Ola's own words: "if you were in npc"). Without
					-- this, a player whose first category happens to be NPCs — because it is the only
					-- one in the room — browses it with j/k/l, walks somewhere that also has doors, and
					-- is put back on Transitions, which is exactly the complaint. ⛔ ONLY when there is
					-- no preference: a category he was merely FALLEN BACK to must still never overwrite
					-- one he actually chose, which is the whole point of want_cat.
					want_cat = want_cat or cur_cat()
					announce_cat(px, pz)
					-- ⛔ AND IT MUST NOT SWALLOW A `p`. The review was right that p could otherwise
					-- route from a list whose meaning had silently changed — but making p announce and
					-- RETURN was the wrong cure: `entered` also goes false whenever the active category
					-- shifts under him, which in a town with people walking about can happen at any
					-- moment, so p would be eaten at unpredictable times and the whole pathfinder would
					-- look broken. Naming the list and then routing anyway satisfies both halves: he
					-- always hears what he is on before the route, and the press always does something.
					if navkey then return end          -- a nav key's whole job was to land here
				end
				if navkey then
					if pressed["O"] then switch_cat(1, px, pz)
					elseif pressed["I"] then switch_cat(-1, px, pz)
					elseif pressed["J"] then ii = ii - 1; announce_item(px, pz, true)
					elseif pressed["L"] then ii = ii + 1; announce_item(px, pz, true)
					elseif pressed["K"] then announce_item(px, pz, true) end
				end
			end

			-- D: describe the person the list is on (core/describe.lua), the entry last heard, by the
			-- identity the list itself gave them when it named them (`describe` on the entry). Its
			-- object is re-checked live (still in use, not hidden) so a person who has left says nothing.
			if pressed["D"] then
				local l = cur_list()
				local e = (#l > 0 and ii >= 1 and ii <= #l) and l[ii] or nil
				local o = e and e.describe and e.actor
				local st = o and inram(o + MO_STATUS + 3) and u32(o + MO_STATUS)
				if not (st and (st & MO_INUSE) ~= 0 and (st & MO_HIDDEN) == 0) then
					dbg("describe: no named person on this entry")
				elseif not describe_trainer(e.describe) then
					dbg("describe: no description for " .. e.describe)
				end
			end

			-- P: route to the entry the list is on. Pressing it again on the same thing cancels.
			if pressed["P"] then
				local l = cur_list()
				local e = (#l > 0 and ii >= 1 and ii <= #l) and l[ii] or nil
				local occ, occ_ok = nav_occ, nav_occ_ok
				if eterna.intent and e and eterna.intent.entry.key ~= e.key then
					eterna.intent,eterna.reenter = nil,false
				end
				if not e then
					say("Abre primero la lista de navegación y luego pulsa P", true)
				-- ⛔ CANCELLING COMES FIRST AND ASKS NOTHING ELSE. It is matched on the entry's stable
				-- IDENTITY, not on coordinates: a person walks, so a coordinate comparison stops
				-- recognising its own route within a second or two and "press p again to turn it off"
				-- silently stops working (codex-review verification pass). Cancelling must never depend
				-- on the ground being readable or on anyone being where they were.
				elseif (pf and pf.key and pf.key == e.key) or (eterna.intent and eterna.intent.entry.key == e.key) then
					pf, pf_reenter, eterna.intent, eterna.reenter = nil, false, nil, false
					say("Guiado desactivado", true)
				elseif e.hidden and not dowsing.available(fs, e) then
					say("No se puede llegar a " .. (e.label or e.name) .. " desde aquí", true)
				elseif not occ_ok then
					-- Cannot see who is standing where: refuse rather than route through them.
					say("Todavía no encuentro ruta hasta " .. (e.label or e.name), true)
				else
					local dwmap = terrain.dw.active(fs, cache)
					local cands, certain = {}, true
					if not dwmap then cands, certain = goals_for(fs, e, occ, px, pz, cache) end
					local here, beside = false, nil
					for _, c in ipairs(cands) do
						if px == c[1] and pz == c[2] then
							here = true
							-- A transition's endpoint faces its warp: "You're there, 1 down".
							if e.warps and c[3] and not beside then
								local dx, dz = c[3] - px, c[4] - pz
								beside = dz < 0 and 0 or dz > 0 and 1 or dx < 0 and 2 or dx > 0 and 3 or nil
							end
						end
					end
					if here and terrain.canalave.active(fs, cache) and not terrain.canalave.same_floor(fs, e) then here = false end
					if here and not terrain.unloaded(fs, e.x, e.z, cache)
						and not (map_id(fs) == 67 and e.actor and ({[4]=true,[5]=true,[6]=true,[7]=true})[u32(e.actor+MO_SCRIPT)]) then
						if e.hidden then
							local dx, dz = e.x - px, e.z - pz
							local direction = dx < 0 and "left" or dx > 0 and "right" or dz < 0 and "up" or "down"
							say("Has llegado a " .. (e.label or e.name) .. ", 1 " .. direction, true)
						else say("Has llegado" .. (PFWORD[beside] and (", 1 " .. PFWORD[beside]) or ""), true) end
					else
						local r, why, face = pf_plan(fs, px, pz, e, occ, cache)
						if r then
							pf = r
							say("Hacia " .. (e.label or e.name) .. (r.segs[1] and (". " .. r.segs[1]) or ""), true)
						elseif why == "here" then
							say("Has llegado" .. (PFWORD[face] and (", 1 " .. PFWORD[face]) or ""), true)
						elseif why == "limit" or why == "terrain" or not certain then
							-- The search ran out of room, or a side could not be read. Both are
							-- statements about US, and neither justifies one about the world.
							say("Todavía no encuentro ruta hasta " .. (e.label or e.name), true)
						else
							say("No se puede llegar a " .. (e.label or e.name) .. " desde aquí", true)
						end
					end
				end
			end
		end,
		-- ⛔ ARM THE RE-PLAN WHENEVER THIS MODULE LOSES THE FRAME WITH A ROUTE LIVE. A battle, a
		-- conversation, a menu — on the way back he has not moved, so without this he is left standing
		-- with no instruction until he takes a step in some arbitrary direction.
		on_exit = function()
			map_notice.cache = nil
			dowsing.pending, dowsing.rt, dowsing.keyboard = nil, false, false
			if dowsing.touching then touch.cancel(); dowsing.touching = nil end
			if not field_map_live() then dowsing.owner, dowsing.ping = nil, nil end
			if pf then pf_reenter = true end
			if eterna.intent then eterna.reenter = true end
			lists, statics = nil, nil          -- rebuild on the next press: everything has moved
			terrain.saved = nil
		end,
	}
	local update = MODULES[#MODULES].update
	MODULES[#MODULES].update = function(pressed)
		terrain_notice = nil
		update(pressed)
		if terrain_notice then say("") end
	end
end)()

-- 11) THE STARTER SELECTION — Rowan's briefcase, and the last hard stop in the opening.
--
-- Ola, 2026-09-06: "the starter selection when interacting with the briefcase ... nothing in there
-- speaks." Without it he cannot choose a starter unaided.
--
-- ⭐ IT IS A CHILD APPLICATION, NOT A SCRIPT WINDOW. Route 201's briefcase script reaches
-- `StartChooseStarterScene`, which leaves its own FieldTask alive and paused and launches overlay
-- 78 (`choose_starter`) as a FIELD CHILD. So `sApplication.currApplication` still names the FIELD —
-- the trap CLAUDE.md warns about — and the child hangs off the field process manager:
--   sApplication +0x04 -> ApplicationManager   (the FIELD)
--   ApplicationManager +0x1C -> FieldSystem
--   FieldSystem +0x00 -> FieldProcessManager
--   FieldProcessManager +0x04 -> the CHILD ApplicationManager
--   child +0x1C -> ChooseStarterApp
-- ⛔ AND ITS TEXT NEVER TOUCHES msgBuf. The overlay owns its own Window and prints bank 360 into it
-- directly, so the field dialogue reader cannot see a word of this screen. Every line here is baked
-- out of the cartridge by research/re/gen_pt_starter_text.py — bank 360 for the screen's own script
-- and bank 412 for the species names.
--
-- Full RE: research/re/report-20260906-pt-starter-select.md. Anchors verified against Ola's own
-- cartridge: the template at 0x020EA1F8 reads {0x021d0d81, 0x021d0ef5, 0x021d0fa9, 0x0000004e},
-- and 0x4E is the overlay id 78.
;(function()
	local STARTER
--[[ STARTERTEXT:BEGIN ]]
	STARTER = {
		intro = "¡Mira! ¡Poké Balls! ¡En cada una hay un Pokémon!",
		prompt = "¡Venga! ¿Cuál quieres?",
		ask = { "¡Pokémon Hojita TURTWIG! ¿Quieres este Pokémon?", "¡Pokémon Chimpancé CHIMCHAR! ¿Quieres este Pokémon?", "¡Pokémon Pingüino PIPLUP! ¿Quieres este Pokémon?" },
		name = { "TURTWIG", "CHIMCHAR", "PIPLUP" },
	}
	--[[ STARTERTEXT:END ]]

	-- The two words for the confirmation. ⚠ OURS, not the game's — the same allowed exception, and
	-- the same two words, the save screen already uses and Ola has confirmed in game.
	local YESNO = { [0] = "Sí", [1] = "No" }

	-- The screen's own state machine (choose_starter_app.c:95-120, 199-207).
	local ST_CHOICE, ST_STEP, ST_DISABLE, ST_CURSOR, ST_MENU = 0x00, 0x04, 0x08, 0x54, 0xB8
	local CHOOSE, CONFIRM = 3, 4          -- choiceStep: CHOICE_STEP_CHOOSE_POKEBALL / _CONFIRM_
	local MENU_ROW = 0x15                 -- the Menu's highlighted row, 0 = Yes

	-- ⭐ THE APP, OR NIL — identity first, never a buffer sniff.
	local function app()
		local top = u32(A.sApplication + 0x04)
		if not inram(top) then return nil end
		if u32(top + 0x04) ~= A.ExecuteFieldProcesses then return nil end
		if u32(top + 0x10) ~= 2 then return nil end
		local fs = u32(top + 0x1C)
		if not inram(fs) then return nil end
		local pm = u32(fs + 0x00)
		if not inram(pm) then return nil end
		if u32(pm + 0x00) ~= 0 then return nil end     -- the field itself is not driving a child
		local ch = u32(pm + 0x04)
		if not inram(ch) then return nil end
		-- ⛔ IDENTITY IS THE CALLBACK TUPLE **AND** THE OVERLAY ID. Mutually exclusive overlays reuse
		-- the same RAM, so a main-callback address alone is not an identity here — the same warning
		-- the Pokédex arc produced in Gen V, and the reason this checks both.
		if u32(ch + 0x00) ~= A.ChooseStarter_Init then return nil end
		if u32(ch + 0x04) ~= A.ChooseStarter_Main then return nil end
		if u32(ch + 0x08) ~= A.ChooseStarter_Exit then return nil end
		if u32(ch + 0x0C) ~= 78 then return nil end
		if u32(ch + 0x10) ~= 2 then return nil end     -- execState: main is running
		if u32(ch + 0x14) ~= 2 then return nil end     -- procState: CHOOSE_STARTER_MAIN_LOOP
		local a = u32(ch + 0x1C)
		if not inram(a + ST_MENU + 3) then return nil end
		return a
	end

	-- What is on screen, as the screen's own two step counters say. Returning the pair rather than a
	-- name keeps every decision below on the game's own state and none on what we last said.
	local function phase(a)
		return u32(a + ST_CHOICE), u32(a + ST_STEP), u32(a + ST_DISABLE)
	end

	-- ⛔⛔ MODULE PRIORITY, AND WHY THIS ONE IS NOT STARVED (CLAUDE.md Rule 2). context_of() takes
	-- the FIRST module whose detect matches, and the field-dialogue module is registered long before
	-- this one. The briefcase's own script stays ALIVE AND PAUSED for the whole of this screen
	-- (report-20260906-pt-starter-select.md), so a script manager still exists and dialogue's first
	-- two gates could pass. What stops it is the COMMIT GATE added the same day: dialogue now also
	-- requires either a live printer or a script paused on the PRINT callback, and this script is
	-- paused on the starter wait instead. ⚠ That is a real dependency between two modules, so it is
	-- written down: if this screen ever goes silent, check dialogue's gate before anything here.
	local said_phase, said_cursor, said_row, was_confirm
	MODULES[#MODULES + 1] = {
		name = "starter selection",
		detect = function() return app() ~= nil end,
		on_exit = function() said_phase, said_cursor, said_row, was_confirm = nil, nil, nil, nil end,
		-- The Pokémon in the ball under the cursor, for D (core/describe.lua): GetSelectedSpecies
		-- (choose_starter_app.c:1750-1768) maps CURSOR_POSITION_LEFT/CENTER/RIGHT (0/1/2) to
		-- STARTER_OPTION_0/1/2 = Turtwig 387, Chimchar 390, Piplup 393 — the same order as
		-- STARTER.name. Only while the cursor is settled on a ball or its confirmation is asking.
		describe = function()
			local a = app()
			if not a then return nil end
			local c, st, dis = phase(a)
			if dis ~= 0 or not ((c == CHOOSE and st == 8) or (c == CONFIRM and st == 3)) then return nil end
			return ({ 387, 390, 393 })[u32(a + ST_CURSOR) + 1]
		end,
		update = function()
			local a = app()
			if not a then return end
			local c, st, dis = phase(a)
			local key = c .. "." .. st

			-- ⭐ THE OPENING LINES, each of which REPLACES the one before it in the same window, so
			-- each interrupts (CLAUDE.md Rule 1: interrupt what has replaced what came before).
			if c == CHOOSE and st == 4 and said_phase ~= key then
				said_phase = key
				say(STARTER.intro)
			elseif c == CHOOSE and st == 6 and said_phase ~= key then
				said_phase = key
				say(STARTER.prompt)

			-- ⭐ THE THREE BALLS. Substep 8 is the settled state: the cursor is revealed and
			-- `disableCursorMovement` is clear, which is the game's own "you may move now"
			-- (IsSelectionMade, choose_starter_app.c:935-965). Requiring it costs at most the one
			-- transition frame and guarantees the ball we name is the one under the cursor.
			-- ⛔ COMING BACK FROM "No" THE PROMPT IS ON SCREEN AGAIN, AND IT HAS REPLACED THE
			-- QUESTION — so it interrupts, and the ball then queues behind it. Without this the ball
			-- was announced with a QUEUE flag straight after the confirmation, so the obsolete
			-- question could keep speaking over the screen the player had already left
			-- (codex-review 2026-09-06). The transition is the screen's own: choiceStep leaves
			-- CONFIRM and comes back to CHOOSE at substep 7, before the settled 8.
			elseif c == CHOOSE and was_confirm and (st == 7 or st == 8) then
				was_confirm = false
				said_phase, said_cursor = nil, nil
				say(STARTER.prompt)

			elseif c == CHOOSE and st == 8 and dis == 0 then
				local cur = u32(a + ST_CURSOR)
				local nm = STARTER.name[cur + 1]
				if nm and (said_phase ~= key or said_cursor ~= cur) then
					-- The first one QUEUES: the prompt is still on screen and this joins it. Moving
					-- the cursor INTERRUPTS, so holding a direction collapses to where you stopped.
					local first = said_phase ~= key
					said_phase, said_cursor = key, cur
					say(nm .. ", " .. (cur + 1) .. " de 3", not first)
				end

			-- ⭐ THE CONFIRMATION. Its question already names the Pokémon and its category, so there
			-- is nothing to add to it — bank 360 entry 1 + cursor, in the game's own words.
			elseif c == CONFIRM and st == 3 and dis == 0 then
				was_confirm = true
				local menu = u32(a + ST_MENU)
				local row = inram(menu + MENU_ROW) and u8(menu + MENU_ROW) or nil
				if said_phase ~= key then
					said_phase, said_row = key, nil
					say(STARTER.ask[u32(a + ST_CURSOR) + 1] or STARTER.prompt)
				end
				if row and YESNO[row] and said_row ~= row then
					-- Queues behind the question the first time (it appeared with it), interrupts
					-- afterwards because the highlight replaced the old one.
					local first = said_row == nil
					said_row = row
					say(YESNO[row] .. ", " .. (row + 1) .. " de 2", not first)
				end
			end
			-- ⚠ NOTHING IS SAID ON YES. The overlay fades out and the field's own dialogue reader
			-- picks the scene up again after ReturnToField; announcing anything here would talk over
			-- the cry the game plays and then over Rowan's next line.
		end,
	}
end)()

-- 12/13) THE BATTLE MENUS — the command menu (Fight/Bag/Pokémon/Run) and the move menu.
--
-- Full RE: research/re/report-20260906-pt-battle-menus.md (Codex), every hop proven against Ola's
-- cartridge. One persistent object drives both:
--   BattleSystem +0x19C -> BattleSubscreen
-- proven at the point of use by BattleSystem_GetBattleSubscreen (0x0223E02C), which is
-- `movs r1,#0x67 ; lsls r1,r1,#2 ; ldr r0,[r0,r1]` — 0x67 * 4 = 0x19C.
-- ⭐ BattleSubscreen +0x00 IS A BACK-POINTER TO ITS OWN BattleSystem (stored by BattleSubscreen_New,
-- `ldr r0,[sp,#0xC] ; str r0,[r6]` at 0x022687D6), which makes the chain self-validating for free:
-- if the word we land on does not point back at where we came from, it is not this object.
--
-- ⛔ WHICH MENU IS UP IS A CONFIG INDEX, NOT THE UNION'S CONTENTS. `activeMenuConfigIndex` is the
-- signed byte at +0x68B, written by BattleSubscreen_SetupBackground alongside the 0x22-byte copy of
-- the menu's data into +0x1C. 1-4 are the normal command menu (1/2 open it, 3/4 redraw it), 5/6 the
-- first-battle tutorial with only FIGHT, 7/8 Safari, 9/10 Pal Park, and 11 the move menu. We claim
-- ONLY 1-4 and 11 and stay silent on the rest, because a Safari menu announced as Fight/Bag/
-- Pokémon/Run would be four wrong words rather than a missing feature.
--
-- ⛔⛔ THE INPUT GATE, WHICH IS THE ONE THAT WOULD OTHERWISE COST OLA A TEST ROUND (Rule 8). Gen V
-- hit this three times: backing out of a menu makes the game SELECT the last row before closing,
-- and the screen stays current for tens of frames while it animates shut, so the reader announces
-- "Run" on every retreat. A one-frame defer cannot fix it. Platinum's own predicate is three words:
--   +0x6DC  cursor.isActive     must be non-zero — BattleSystem_MenuKeys will not act on the cursor
--                               until this is set, and on the frame A or B IS accepted
--                               BattleSystem_MenuInput clears the whole four-byte MenuCursor
--                               (0x02269308) in that SAME call. So it goes 1 -> 0 exactly when the
--                               player commits, which is why no amount of deferring could work.
--   +0x68E  isPanelSliding      0 while the panel is not sliding in (0x02269260 rejects input on it)
--   +0x0C   menuTransitionTask  NULL until a selection starts the close animation, and
--                               StartMenuTransitionTask stores it inside the accepting call
-- Any one of the three going the wrong way means "not taking input", and together they cover both
-- the opening slide and the closing one.
--
-- ⭐ THE WORDS ARE BAKED, AND THEY HAVE TO BE. The subscreen builds each label into a String, gives
-- it to a font object and frees it — the Rule 6 shape exactly — so there is nothing live to read.
-- research/re/gen_pt_battle_menu_text.py takes them from the cartridge: bank 368 entries 924-928 for
-- the commands and 938 for "PP", bank 647 for move names indexed by move id, bank 624 for type
-- names indexed by type id, and /poketool/waza/pl_waza_tbl.narc record +4 for each move's type
-- (the menu draws the type as an ICON, so there is no text on screen to read).
;(function()
	local CUR_Y, CUR_X = 0x6DD, 0x6DE            -- MenuCursor.y / .x
	local MOVE_ID, MOVE_PP, MOVE_MAXPP = 0x1C, 0x24, 0x28   -- MoveSelectData
	-- hasCancelButton: BattleSubscreen_DrawActionMenu (overlay 16) draws bank 368 entry 928 CANCEL
	-- in the RUN square and stores 1 here when isWaitingForPartner (+0x6E1) is set — the second
	-- Pokémon of a double battle — else entry 927 RUN and 0 (`strb r1,[r5,r0]` 0x0226972C, literal
	-- 0x68F at 0x02269884).
	local CANCEL_FLAG = 0x68F
--[[ BATTLEMENUTEXT:BEGIN ]]
	BTLTEXT = {
		cmd = { "Luchar", "Mochila", "Pokémon", "Huir", "Salir" },
		pp = "PP",
		types = { [0] = "Normal", "Lucha", "Volador", "Veneno", "Tierra", "Roca", "Bicho", "Fantasma", "Acero", "???", "Fuego", "Agua", "Planta", "Eléctrico", "Psíquico", "Hielo", "Dragón", "Siniestro" },
		stats = { "PS máximos", "Ataque", "Defensa", "Ataque especial", "Defensa especial", "Velocidad" },
		moves = {
			[1] = "Destructor", [2] = "Golpe Karate", [3] = "Doblebofetón", [4] = "Puño Cometa", [5] = "Megapuño", [6] = "Día de Pago", [7] = "Puño Fuego", [8] = "Puño Hielo",
			[9] = "Puño Trueno", [10] = "Arañazo", [11] = "Agarre", [12] = "Guillotina", [13] = "V. Cortante", [14] = "Danza Espada", [15] = "Corte", [16] = "Tornado",
