			[318] = "Fuerte viento con polvo de escamas. Puede subir todas las características del atacante.",
			[319] = "Horrible chirrido metálico que baja mucho la Def. Esp.",
			[320] = "Agradable melodía que adormece al rival.",
			[321] = "Hace reír para bajar el Ataque y la Defensa.",
			[322] = "Sube la Defensa y la Def. Esp. propias con energía mística.",
			[323] = "Chorro de agua. Cuantos menos PS tenga el usuario, menos dañino será.",
			[324] = "Rayo siniestro de luz. Puede causar confusión.",
			[325] = "Puñetazo ineludible procedente de las sombras.",
			[326] = "Energía muy extraña que puede hacer retroceder al enemigo.",
			[327] = "Gancho ascendente de gran ímpetu.",
			[328] = "Enreda en un remolino de arena de 2 a 5 turnos.",
			[329] = "Ataque de frío polar que debilita al rival si le alcanza.",
			[330] = "Ataque con agua lodosa que puede bajar la precisión.",
			[331] = "Dispara rápido de 2 a 5 ráfagas de semillas de manera consecutiva.",
			[332] = "El usuario lanza un ataque muy rápido e ineludible.",
