			[372] = "Si el rival ya ha sufrido daño en ese turno, la fuerza del ataque se duplica.",
			[373] = "Impide al rival usar el objeto que lleva. Su entrenador tampoco puede usar objetos sobre él.",
			[374] = "Lanza contra el rival el objeto que lleva. La fuerza del ataque y su efecto varían según el objeto.",
			[375] = "Usa su poder mental para transferir al rival sus problemas de estado.",
			[376] = "Cuantos menos PP tenga el movimiento, mayor será la fuerza para atacar.",
			[377] = "Impide al rival usar movimientos de cura durante cinco turnos.",
			[378] = "Abraza fuerte al rival y lo estruja. Cuantos más PS tenga el rival, más fuerza tendrá el ataque.",
			[379] = "Usa sus poderes mentales para intercambiar su característica de Ataque por Defensa.",
			[380] = "El usuario arroja sus jugos biliares al rival, lo que anula el efecto de la habilidad en uso.",
			[381] = "Lanza al cielo un conjuro que impide al rival asestar golpes críticos.",
			[382] = "Trata de adelantarse al movimiento que pretende usar el rival y lo lanza primero con más fuerza.",
			[383] = "Imita el movimiento usado justo antes. El movimiento falla si no se ha usado aún ninguno.",
			[384] = "El usuario emplea su poder mental para intercambiar cambios en Ataque y At. Esp. con el rival.",
			[385] = "El usuario emplea su poder mental para intercambiar cambios en Defensa y Def. Esp. con el rival.",
			[386] = "La fuerza del ataque aumenta cuanto más se ha fortalecido el rival con cambios de características.",
			[387] = "Este movimiento solo puede usarse tras haber usado todos los demás conocidos por el Pokémon.",
			[388] = "Se planta una semilla en el rival que le causa pesar. Evita el sueño gracias a la habilidad Insomnio.",
			[389] = "Permite atacar primero. Falla si el rival no está preparando ningún mov. de ataque.",
			[390] = "Lanza una trampa de púas tóxicas a los pies del rival. El veneno afecta a los Pokémon que entran.",
			[391] = "Usa la fuerza mental para intercambiar con el rival los cambios en las características.",
			[392] = "Un manto de agua cubre al Pokémon que lo usa. Recupera algunos PS en cada turno.",
			[393] = "Levita gracias a un campo magnético generado por electricidad durante 5 turnos.",
			[394] = "El Pokémon se cubre de llamas y carga contra el rival, aunque él también recibe daños.",
			[395] = "Ataca al rival con una onda de choque y puede llegar a paralizarlo.",
			[396] = "Libera una descarga de la fuerza del aura desde su interior. Es infalible.",
			[397] = "Reduce la resistencia puliendo su cuerpo. Aumenta la Velocidad considerablemente.",
			[398] = "Pincha al rival con un tentáculo o brazo envenenado. Puede llegar a envenenar al rival.",
			[399] = "Libera una horrible aura llena de malos pensamientos y puede hacer retroceder al rival.",
			[400] = "Ataca al rival a la primera oportunidad. Suele ser crítico.",
			[401] = "Ataca agitando la cola como si fuera una ola rabiosa en una fiera tormenta.",
			[402] = "Lanza al enemigo una descarga de semillas explosivas desde arriba.",
			[403] = "Ataca con una hoja de aire que corta hasta los cielos. También puede hacer retroceder al rival.",
			[404] = "Cruza las guadañas o las garras para atacar al rival como si fueran unas tijeras.",
			[405] = "El movimiento de las alas crea una onda sónica dañina. Puede también disminuir la Def. Esp. del rival.",
			[406] = "Abre mucho la boca y libera una onda de choque que ataca al rival.",
			[407] = "Ataca de forma brutal mientras intimida al rival. También puede hacerlo retroceder.",
			[408] = "Ataca con un rayo de luz que centellea como si lo formaran miles de joyas.",
			[409] = "Un golpe que drena energía. El Pokémon recupera la mitad de los PS arrebatados al rival.",
			[410] = "Gira los puños y libera una onda de vacío contra el rival. Este movimiento siempre va primero.",
			[411] = "Agudiza la concentración mental y libera su poder. Puede disminuir la Def. Esp. del rival.",
