		[706] = { -- species_pokedex_entry_en
			[1] = "Después de nacer, crece alimentándose de las semillas de su lomo.",
			[2] = "Cuando el bulbo de su lomo se hincha, desprende un dulce aroma para indicar el florecimiento.",
			[3] = "Después de un día de lluvia, la flor de su lomo tiene un aroma más potente y atrae a otros Pokémon.",
			[4] = "La llama de la punta de su cola indica su salud. Si CHARMANDER está sano, arderá con más fuerza.",
			[5] = "En las montañas rocosas donde viven los CHARMELEON, sus colas ardientes brillan como estrellas.",
			[6] = "Se dice que el fuego de CHARIZARD arde con más fuerza si ha vivido duras batallas.",
			[7] = "Se protege con su caparazón y luego contraataca lanzando agua a presión cuando tiene oportunidad.",
			[8] = "Se dice que vive 10000 años. Su peluda cola es un símbolo de longevidad.",
			[9] = "Los chorros de agua que lanza por los tubos de su caparazón pueden atravesar el acero.",
			[10] = "Su antena roja desprende un gran hedor para repeler a los enemigos. Crece mudándose repetidamente.",
			[11] = "Su frágil cuerpo está recubierto de una coraza dura como el acero. Permanece quieto en su desarrollo.",
			[12] = "Adora el néctar de las flores. Puede localizar hasta las más pequeñas cantidades de polen.",
			[13] = "Come el equivalente a su peso en hojas todos los días. Se defiende con el aguijón de su cabeza.",
			[14] = "Se esconde de sus atacantes entre las ramas de los árboles mientras espera a evolucionar.",
			[15] = "Atacan volando alrededor del objetivo y usando su aguijón venenoso antes de huir.",
			[16] = "Es manso y prefiere evitar los problemas. Sin embargo, si le molestan atacará ferozmente.",
			[17] = "Sobrevuela su extenso territorio en busca de presas y ataca con sus poderosas garras.",
			[18] = "Aleteando con toda su fuerza, PIDGEOT crea corrientes de aire capaces de doblar grandes árboles.",
			[19] = "Su capacidad de adaptación le permite vivir en cualquier lugar. Es tremendamente cauteloso.",
			[20] = "Lima sus colmillos royendo objetos duros. Con ellos puede destruir incluso paredes de hormigón.",
			[21] = "Agita continuamente sus alitas para volar. Busca presas entre la hierba con su pico.",
			[22] = "Tiene energía para volar todo el día con sus grandes alas. Lucha con su afilado pico.",
			[23] = "Se mueve por la hierba en silencio y sorprende a sus presas atacando por detrás.",
			[24] = "ARBOK intimida a sus presas con el dibujo de su panza y luego las asfixia con su cuerpo.",
			[25] = "A veces utiliza la electricidad de sus mejillas para recargar a un PIKACHU amigo que esté débil.",
			[26] = "Su cola descarga electricidad al suelo y eso le protege de los calambrazos.",
			[27] = "Vive en zonas áridas donde casi no llueve. Se enrosca formando una bola para defenderse.",
			[28] = "Se hace una bola y se lanza rodando hacia los enemigos para clavarles sus afiladas púas.",
			[29] = "Aunque no le gusta luchar, una sola gota del veneno de sus púas puede resultar fatal.",
			[30] = "Saca las púas de su cuerpo si siente peligro. Sus púas crecen más despacio que las de NIDORINO.",
			[31] = "Tiene el cuerpo cubierto de duras escamas. Protege a su cría con toda su fuerza.",
			[32] = "Saca las orejas por encima de la hierba para explorar el territorio. Le protege su cuerno venenoso.",
			[33] = "Se muestra violento y ataca a los enemigos con un cuerno que desprende veneno.",
			[34] = "Un golpe de su poderosa cola puede partir un poste de teléfono como si fuese una cerilla.",
			[35] = "Se dice que la felicidad llegará a quien vea a un grupo de CLEFAIRY bailando a la luz de la luna llena.",
			[36] = "Es muy prudente y rara vez se deja ver. Su oído es tan fino que puede oír caer una aguja a 1 km.",
			[37] = "Controla bolas de fuego. A medida que crece, sus seis colas se multiplican.",
			[38] = "Se dice que sus nueve colas están revestidas de poder místico. Puede vivir mil años.",
			[39] = "Cuando mueve sus grandes ojos redondos, comienza a cantar una nana que duerme al enemigo.",
			[40] = "Tiene un pelaje muy agradable al tacto. Puede hinchar su cuerpo tragando aire.",
			[41] = "Utiliza las ondas ultrasónicas que emite con la boca para orientarse y evitar obstáculos.",
			[42] = "Sus afilados colmillos atraviesan las pieles más duras y tienen orificios para chupar sangre.",
			[43] = "Suele plantarse en el suelo durante el día. Por la noche se desplaza esparciendo semillas.",
			[44] = "La miel que emana de su boca posee un hedor capaz de derribar enemigos a 2 km de distancia.",
			[45] = "Sus pétalos son los más grandes del mundo. Cuando anda desprende un terrible polen alergénico.",
			[46] = "En el lomo de PARAS crecen unas setas parasitarias llamadas tochukaso.",
			[47] = "PARASECT está dominado por un hongo parásito mayor que él. Dispersa esporas venenosas.",
			[48] = "Sus grandes ojos son en realidad grupos de ojos diminutos. Por la noche se siente atraído por la luz.",
			[49] = "Agita las alas para dispersar un polvillo de escamas que libera toxinas si toca la piel.",
			[50] = "Este Pokémon vive a oscuras bajo tierra, por lo que la luz solar le espanta.",
			[51] = "Sus tres cabezas se mueven por turnos para excavar la tierra a una profundidad de unos 100 km.",
			[52] = "Es de naturaleza nocturna. Le atraen los objetos brillantes.",
			[53] = "Es un Pokémon muy arrogante. El tamaño de la joya de su frente da mucho que hablar.",
			[54] = "Sus grandes habilidades le provocan un constante dolor de cabeza. A veces usa poderes misteriosos.",
			[55] = "Sus desarrolladas extremidades y aletas le permiten nadar de forma elegante.",
			[56] = "Vive en colonias en los árboles. Si uno se enfada, el resto de la manada ataca sin motivo.",
			[57] = "Se molesta si le miras a los ojos. Se enfada si corres. Se enfurece si le golpeas.",
			[58] = "Pokémon de naturaleza leal. Permanece quieto en espera de órdenes de su entrenador.",
			[59] = "Su aspecto regio y orgulloso se ha ganado el corazón de la gente hace tiempo.",
			[60] = "Su piel es tan fina que permite ver sus órganos. Le cuesta andar con sus nuevas patas.",
			[61] = "El dibujo espiral de su panza ondea levemente. Si se mira fijamente, provoca somnolencia.",
			[62] = "Tiene músculos muy desarrollados. Es capaz de nadar en el océano sin descanso.",
			[63] = "Sus poderes psíquicos causan un desgaste tan grande para su mente que precisa dormir 18 horas al día.",
			[64] = "Mira su cuchara de plata fijamente para concentrarse. Mientras lo hace, emite más ondas alfa.",
			[65] = "Se dice que creó las cucharas que lleva en las manos con sus poderes psíquicos.",
			[66] = "No alcanza mucha altura, pero tiene fuerza suficiente para levantar y derribar a varios GEODUDE a la vez.",
			[67] = "Levanta pesos descomunales para mantenerse en forma y usa su fuerza para ayudar a las personas.",
			[68] = "Tiene cuatro musculosos brazos con los que golpea y destroza al enemigo a una velocidad increíble.",
			[69] = "Prefiere los lugares cálidos y húmedos. Captura presas con sus rápidas lianas.",
			[70] = "Este Pokémon parece una planta. Captura a sus presas usando polvo tóxico cuando están desprevenidas.",
			[71] = "Su boca segrega un fluido de olor parecido a la miel: un potente ácido que disuelve cualquier cosa.",
			[72] = "Como su cuerpo se compone casi en exclusiva de agua, se reseca si sale de ella.",
			[73] = "Extiende sus 80 tentáculos para formar una red venenosa de la que es muy difícil escapar.",
			[74] = "En reposo parece una roca normal, pero si se pisa por error, responde agitando los puños con agresividad.",
			[75] = "Se desplaza rodando por caminos de montaña. Cuando coge velocidad, es difícil frenar su avance.",
			[76] = "Ni siquiera la dinamita puede dañar su cuerpo rocoso. Muda la piel una vez al año.",
			[77] = "Cuando nace, apenas puede tenerse en pie. Pero va fortaleciendo las patas en cuanto empieza a galopar.",
			[78] = "Cuando galopa, su ardiente crin centellea y le da un aspecto aún más impresionante.",
			[79] = "A pesar de su lentitud, tiene una gran habilidad para pescar con la cola, que es insensible al dolor.",
			[80] = "Normalmente se muestra torpe, aunque espabila si el SHELLDER de su cola le muerde.",
			[81] = "Cuanto más rápido rotan las unidades laterales, mayor fuerza magnética generan.",
			[82] = "Surgen cuando aparecen manchas en el sol. Los televisores no funcionan bien en su presencia.",
			[83] = "No puede vivir sin el palo que lleva. Por eso lo protege de sus atacantes con todas sus fuerzas.",
			[84] = "Parece que los cerebros de sus dos cabezas se comunican por telepatía.",
			[85] = "Cuando un DODUO evoluciona, una de sus cabezas se divide en dos. Corre a unos 60 km por hora.",
			[86] = "Este Pokémon vive en icebergs. Nada en el mar y usa el cuerno de su cabeza para romper el hielo.",
			[87] = "Está cubierto de un luminoso pelaje blanco que lo camufla en la nieve.",
			[88] = "Emergió del lodo que se formó en agua contaminada expuesta a los rayos X lunares. Vive en la basura.",
			[89] = "Su cuerpo segrega un fluido tóxico que elimina la vida vegetal cuando la toca.",
			[90] = "Nada hacia atrás abriendo y cerrando su concha. Su gran lengua siempre queda colgando.",
			[91] = "En la lucha se protege cerrando su concha y lanzando pinchos a sus oponentes.",
			[92] = "Nació a partir de gases venenosos que asfixiarían a cualquiera que se viera envuelto en ellos.",
			[93] = "Le gusta acechar en la oscuridad y tocar el hombro a sus víctimas, que se quedan temblando para siempre.",
			[94] = "Esa mirada fija que flota en la oscuridad es de algún GENGAR que disfruta maldiciendo a la gente.",
			[95] = "Se desplaza excavando en la tierra a 80 km por hora a la vez que se alimenta de rocas.",
			[96] = "Puede oler los sueños de la gente con su gran nariz. Le encantan los sueños divertidos.",
			[97] = "Mirar su péndulo puede inducir al sueño en tres segundos, incluso si acabas de despertarte.",
			[98] = "Vive en madrigueras excavadas en playas arenosas. Sus pinzas vuelven a crecer si se rompen.",
			[99] = "La pinza mayor tiene 10000 caballos de potencia, pero es tan grande que le cuesta usarla.",
			[100] = "Parece una Poké Ball. Es muy peligroso, ya que puede lanzar descargas o explotar si se toca.",
			[101] = "Se lo lleva el viento si se hincha con la electricidad que almacena.",
			[102] = "Estos seis huevos se comunican por telepatía. Si se separan se pueden reunir rápidamente.",
			[103] = "Se le llama la “selva andante”. Si una cabeza crece demasiado, se cae y forma un EXEGGCUTE.",
			[104] = "Llora cuando se acuerda de su madre fallecida. Cuando lo hace, sus llantos resuenan en su cráneo.",
			[105] = "Este Pokémon salvaje maneja huesos constantemente desde su nacimiento y los usa como armas.",
			[106] = "Sus piernas se extienden hasta doblar su longitud para sorprender a enemigos desprevenidos.",
			[107] = "Los potentes golpes de sus brazos pueden pulverizar el hormigón. Descansa tras luchar tres minutos.",
			[108] = "Cuando extiende la lengua, que mide 2 metros, se le agita la cola. Puede que estén conectadas.",
			[109] = "Los gases de su cuerpo le permiten flotar. Estos gases, además de oler mal, también son explosivos.",
			[110] = "Crece alimentándose de los gases emanados por la basura. Se han dado raros casos de trillizos.",
			[111] = "Puede destruir cualquier cosa con sus potentes placajes. Le falta inteligencia para ser de utilidad.",
			[112] = "Al ponerse en pie liberó dos patas y eso desarrolló su inteligencia. Pero se le olvidan las cosas.",
			[113] = "Un generoso Pokémon que pone huevos muy nutritivos y los da a personas o Pokémon heridos.",
			[114] = "Las lianas azules que envuelven su cuerpo están cubiertas de vello. Se dice que tiene cosquillas.",
			[115] = "Lleva a su cría en la bolsa de su panza. Solo deja que su cría salga a jugar cuando no siente peligro.",
			[116] = "Hace su nido entre los corales. Si se siente en peligro, escupe tinta y huye.",
			[117] = "Se protege con sus púas. Sus aletas y huesos son muy valorados por la medicina tradicional.",
			[118] = "Resulta muy elegante cuando nada con las aletas desplegadas, pero causa estragos con su cuerno.",
			[119] = "En otoño gana algo de peso para atraer a posibles parejas y se cubre de llamativos colores.",
			[120] = "Puede recuperar las extremidades que pierde si mantiene intacto su núcleo rojo, que brilla en la noche.",
			[121] = "El centro de su cuerpo alberga un órgano que emite extrañas señales de radio en la noche.",
			[122] = "Crea paredes invisibles deteniendo moléculas con las imperceptibles vibraciones de sus dedos.",
			[123] = "Las cortantes guadañas de sus antebrazos se vuelven más afiladas cada vez que cortan objetos duros.",
			[124] = "Sus gritos se parecen al lenguaje humano, pero es imposible entender lo que dice.",
			[125] = "Gira los brazos para preparar sus puñetazos. A veces tarda tanto que se le escapan los enemigos.",
			[126] = "Cuando respira profundamente se forman olas de calor alrededor de su cuerpo que dificultan la visión.",
			[127] = "Atrapa presas con sus pinzas hasta que las parte en dos. Lanza lejos lo que no puede quebrar.",
			[128] = "Cuando elige una presa, ataca sin pensárselo. Este Pokémon es famoso por su carácter violento.",
			[129] = "Si vive mucho puede llegar a saltar montañas con Salpicadura, pero el movimiento no sirve para nada más.",
			[130] = "Cuando empieza a agitarse puede quemarlo todo, incluso en medio de la más violenta tormenta.",
			[131] = "Le encanta surcar los mares con gente y Pokémon en su lomo. Entiende el lenguaje humano.",
			[132] = "Puede alterar por completo su estructura celular para emular cualquier objeto que vea.",
			[133] = "Su composición genética es algo irregular, por eso cambia de forma muy rápido y por diversas causas.",
			[134] = "Su composición celular es similar a la de las moléculas de agua, por eso se mimetiza tan bien con ella.",
			[135] = "Si se agita, usa electricidad para convertir su pelaje en afiladísimas púas y dispararlas en racimos.",
			[136] = "Calienta el aire que inhala en su saca de fuego y lo lleva a más de 1700 grados de temperatura.",
			[137] = "Un Pokémon creado por el hombre con avanzados medios tecnológicos. Puede viajar por el ciberespacio.",
			[138] = "Fue recuperado a partir de un fósil gracias a la ciencia moderna. Solía nadar en antiguos mares.",
			[139] = "Se cree que este Pokémon se extinguió porque su concha espiral creció demasiado.",
			[140] = "Se cree que habitó las playas hace 300 millones de años. Se protege con una dura concha.",
			[141] = "Se cree que este Pokémon cambió de hábitat y pasó del mar a la tierra buscando nuevas presas.",
			[142] = "Este Pokémon surcó los cielos en la época de los dinosaurios. Sus colmillos son muy afilados.",
			[143] = "Cuando tiene la tripa llena no puede ni mover un dedo. En ese momento de letargo puedes saltar en su tripa.",
			[144] = "Legendario Pokémon pájaro capaz de generar ventiscas congelando la humedad del aire.",
			[145] = "Legendario Pokémon pájaro del que se dice que vive en los nubarrones. Controla los rayos eléctricos.",
			[146] = "Uno de los legendarios Pokémon pájaro. Dicen que su presencia anuncia la llegada de la primavera.",
			[147] = "Se le llama el “Pokémon espejismo” porque son muy pocos los que lo han visto. Se encontró su muda.",
			[148] = "Si su cuerpo está rodeado de un aura, el tiempo cambia de repente. Se dice que vive en mares y lagos.",
			[149] = "Se dice que vive en algún lugar del mar. Guía a las tripulaciones de los barcos hundidos a la costa.",
			[150] = "Pokémon creado por recombinación genética de MEW. Se dice que es el más salvaje de los Pokémon.",
			[151] = "Varios científicos lo consideran el antecesor de los Pokémon porque usa todo tipo de movimientos.",
			[152] = "Con la hoja de su cabeza puede medir la temperatura y la humedad. Le encanta tomar el sol.",
			[153] = "Su cuello desprende un dulce aroma que anima a quien lo huele.",
			[154] = "Su aliento tiene la maravillosa capacidad de revivir plantas y flores muertas.",
			[155] = "Es un Pokémon muy tímido. Si se asusta, las llamas de su lomo arden con más fuerza.",
			[156] = "Intimida a sus enemigos con el calor de sus llamas. Arde con mayor fuerza cuando va a luchar.",
			[157] = "Ataca con llamaradas. Con ellas crea reflejos de calor para ocultarse.",
			[158] = "Tiene costumbre de morderlo todo con sus poderosas mandíbulas, incluso entrenadores.",
			[159] = "Cuando muerde algo, no lo suelta hasta que pierde sus colmillos. Estos se regeneran rápidamente.",
			[160] = "Se suele mover lento, pero alcanza velocidades de vértigo al atacar y morder a sus enemigos.",
			[161] = "Es de naturaleza nerviosa. Se alza sobre su cola para otear grandes extensiones.",
			[162] = "Acurruca a sus crías para que duerman. Acorrala a los enemigos con su enorme velocidad.",
			[163] = "Da la hora con gran exactitud. En algunos países se le considera toda una autoridad por su sabiduría.",
			[164] = "Tiene los ojos muy desarrollados y puede ver con increíble claridad en la oscuridad más densa.",
			[165] = "Es tan temeroso que no se mueve si no es en grupo. Comunica sus sentimientos con olores.",
			[166] = "Se nutre de la luz de las estrellas. Cuanto más estrellada es la noche, más crecen los dibujos de su lomo.",
			[167] = "Pone trampas tejiendo una red de seda fina y resistente y luego espera inmóvil a su presa.",
			[168] = "Pega hilos de seda a sus presas y las libera para seguirlas más tarde y localizar también a sus amigos.",
			[169] = "La transformación de sus patas traseras en alas mejoró su vuelo, pero anda muy mal.",
			[170] = "Libera cargas eléctricas positivas y negativas con sus antenas para aturdir a sus enemigos.",
			[171] = "La luz de LANTURN se puede ver desde lo más profundo. Se le llama la “estrella de alta mar”.",
			[172] = "Las bolsas de electricidad de sus mejillas son muy pequeñas. La mínima fuga le provoca una descarga.",
			[173] = "Se le suele ver cuando el cielo se llena de estrellas fugaces. Se dice que llega montado en una de ellas.",
			[174] = "Su cuerpo es suave y está hinchado. Cuando empieza a botar, no puede parar.",
			[175] = "Transforma la bondad y la alegría de los demás en felicidad y la almacena en su cascarón.",
			[176] = "Para compartir su felicidad, vuela por el mundo en busca de gente de buen corazón.",
			[177] = "Recoge alimento de los cactos evitando los pinchos. Se mueve dando saltos.",
			[178] = "Este extraño Pokémon puede ver el pasado y el futuro. Se pasa el día mirando al sol.",
			[179] = "Su pelaje lanudo dobla su volumen al acumular electricidad estática. Tocarlo puede dar calambre.",
			[180] = "Cuando su pelaje se carga de electricidad, su cola se enciende. Lanza pelo que explota al impacto.",
			[181] = "La punta de su cola brilla. Antiguamente la gente enviaba señales con ella.",
			[182] = "Cuando acaba la estación de las lluvias, sale al sol e inicia una peculiar danza.",
			[183] = "No se ahoga ni en las corrientes más fuertes porque la punta de su cola está llena de aceite y flota.",
			[184] = "Puede pasarse todo el día en el agua porque puede tragar y almacenar un gran volumen de aire.",
			[185] = "Para evitar que le ataquen se limita a imitar un árbol. Odia el agua y huye de la lluvia.",
			[186] = "Agrupa a otros Pokémon para liderarlos. Los POLIWAG obedecen su voz.",
			[187] = "Flotan en el aire. Se dice que cuando los HOPPIP se reúnen, es que la primavera está al caer.",
			[188] = "Florece en épocas cálidas. Flota en el aire para absorber toda la luz solar que puede.",
			[189] = "Los vientos estacionales lo llevan por todo el mundo, donde suelta sus esporas para reproducirse.",
			[190] = "Vive en las copas de los árboles. Puede usar su cola como si fuera una mano más.",
			[191] = "Cae de repente del cielo por las mañanas. Los años de veranos suaves su número se multiplica.",
			[192] = "Obtiene energía de la luz solar. Este Pokémon es famoso por su heliotropismo.",
			[193] = "Puede mantenerse en un punto fijo del aire agitando mucho las alas. Vigila su territorio sobrevolándolo.",
			[194] = "Cuando anda por la tierra cubre su cuerpo con una capa venenosa para mantener hidratada su piel.",
			[195] = "Es de naturaleza sencilla. Cuando nada se choca de cabeza contra barcos o rocas y no le importa.",
			[196] = "Su pelaje es tan sensible que puede percibir cualquier cambio en el aire y predecir el tiempo.",
			[197] = "Si se expone al aura de la luna, los anillos de su cuerpo relucen y adquiere un poder misterioso.",
			[198] = "Si algún incauto logra detectarlo, se verá abocado a perseguirlo hasta perderse en las montañas.",
			[199] = "Al ser mordido por un SHELLDER desarrolló una inteligencia propia de un ganador del premio Nobel.",
			[200] = "Sorprende a la gente en mitad de la noche y acumula su miedo como energía.",
			[201] = "Si están en solitario no pasa nada, pero si se juntan dos o más, se dice que surge un extraño poder.",
			[202] = "Siempre intenta ocultar su cola, por lo que muchos creen que contiene un secreto.",
			[203] = "La cabeza de su cola también tiene un pequeño cerebro, así que puede combatir por delante o por detrás.",
			[204] = "Es como una piña piñonera. Su coraza lo protege de los pájaros que lo picotean por error.",
			[205] = "Se protege con su concha de acero de tal manera que solo se pueden ver sus ojos.",
			[206] = "Cava el suelo con su cola para construir su madriguera. Puede volar distancias cortas.",
			[207] = "Se desliza y sorprende a sus enemigos lanzándose directamente a la cara para clavarles su aguijón.",
			[208] = "Se cree que su cuerpo se ha ido transformando desde dentro por el hierro que acumula comiendo tierra.",
			[209] = "Los Pokémon pequeños huyen al ver su cara agresiva. No obstante, para muchas féminas es mono.",
			[210] = "A pesar de su aspecto, es muy tímido. Sin embargo, cuando se enfada ataca con sus colmillos.",
			[211] = "Lanza púas venenosas en todas direcciones. Debido a su forma redonda, es muy mal nadador.",
			[212] = "Intimida a los enemigos con los dibujos de ojos de sus pinzas, que agita amenazadoramente.",
			[213] = "Almacena bayas en su caparazón, que más tarde fermentan para producir deliciosos zumos.",
			[214] = "Le encanta la miel y usa su cuerno para voltear a cualquiera que se acerque a ella.",
			[215] = "Es muy inteligente. Se empareja para robar huevos: uno distrae a los padres y el otro se los lleva.",
			[216] = "Deja que la miel se le pegue a las garras para lamerla más tarde. Cada una de ellas sabe diferente.",
			[217] = "Araña los árboles de su territorio que dan bayas y frutas que le gustan para marcarlos.",
			[218] = "Su cuerpo se compone de magma. Si deja de moverse, se enfría y se endurece.",
			[219] = "Su cuerpo está a una temperatura de 10000 grados. De las fisuras de su cuerpo escapan llamas.",
			[220] = "Tiene una nariz muy sensible. Puede localizar setas, bayas y hasta aguas termales bajo el hielo.",
			[221] = "Su tupido pelaje le protege del frío. Sus colmillos de hielo se endurecen cuando nieva.",
			[222] = "Muchos viven en los cristalinos mares del sur. Son incapaces de vivir en aguas contaminadas.",
			[223] = "Escupe potentes chorros de agua que siempre dan en el blanco, incluso en la profundidad del mar.",
			[224] = "Le gusta acechar desde agujeros en las rocas. Escupe tinta a sus presas asomando solo la boca.",
			[225] = "Lleva alimentos en su saco. Le gusta compartir su comida con los montañistas perdidos.",
			[226] = "Nada con gran elegancia e ignora a los REMORAID que se aferran a sus aletas buscando restos de comida.",
			[227] = "Una armadura de hierro cubre por completo su cuerpo. Vuela a más de 300 km por hora.",
			[228] = "Tiene suficiente inteligencia para cazar en manada. Se comunica con los demás a través de gritos.",
			[229] = "Las llamas que respira cuando se enfada contienen toxinas. Si causan una quemadura, dolerá toda la vida.",
			[230] = "Vive en cavernas del fondo marino y crea grandes remolinos cuando se mueve.",
			[231] = "A pesar de su tamaño reducido, es tan fuerte que puede llevar a un humano a su espalda con facilidad.",
			[232] = "Se enrolla sobre sí mismo y se lanza rodando contra el enemigo. Puede derribar casas de un golpe.",
			[233] = "Fue mejorado para posibilitar la exploración de otros planetas. Pero no estaba a la altura.",
			[234] = "Mirar a su cornamenta provoca una extraña sensación de pérdida de equilibrio.",
			[235] = "Marca su territorio usando su cola a modo de pincel. Ha hecho más de 5000 marcas diferentes.",
			[236] = "Famoso por su disposición a la lucha. Siempre tiene heridas por luchar con enemigos más grandes.",
			[237] = "Gira a gran velocidad al luchar. La fuerza centrífuga multiplica su poder de destrucción por diez.",
			[238] = "Analiza todo tocándolo con los labios. Así puede recordar las cosas que le gustan y disgustan.",
			[239] = "Entre sus cuernos pasa una débil corriente eléctrica. Quien ponga ahí la mano se dará un calambrazo.",
			[240] = "Su sangre es como magma y su temperatura corporal puede alcanzar los 600 grados.",
			[241] = "Se dice que si un niño bebe leche de MILTANK crecerá y se convertirá en un adulto sano y campechano.",
			[242] = "Los huevos que pone están llenos de felicidad. Solo con probar un poquito de uno, cualquiera sonríe.",
			[243] = "Dicen que apareció con un relámpago. Puede lanzar rayos desde las nubes de su lomo.",
			[244] = "Se dice que, cuando ruge, un volcán entra en erupción en algún punto del globo.",
			[245] = "Recorre el mundo para purificar agua contaminada. Corre veloz con el viento del norte.",
			[246] = "Este Pokémon come tierra. Cuando se come una montaña, se echa a dormir para crecer.",
			[247] = "Su cuerpo es duro como la roca. Se autopropulsa como un cohete soltando los gases de su interior.",
			[248] = "Puede alterar el paisaje derribando montañas y enterrando ríos. Da mucho trabajo a los cartógrafos.",
			[249] = "Duerme en una dorsal marina. Si bate sus alas puede causar tormentas de cuarenta días.",
			[250] = "Su plumaje tiene siete colores. Se dice que verlo proporciona felicidad eterna.",
			[251] = "Puede viajar en el tiempo, pero se dice que solo aparece en tiempos de paz.",
			[252] = "Las plantas de sus pies tienen púas diminutas que le permiten andar por paredes y techos.",
			[253] = "Vive en selvas frondosas. Salta de rama en rama para acercarse a sus presas.",
			[254] = "Las hojas de sus brazos pueden cortar gruesos árboles. Invencible en los combates en la jungla.",
			[255] = "En su interior arde una llama que mantiene su cuerpo caliente. Tira bolas de fuego a 1000 grados.",
			[256] = "Su habilidad le permite dar diez patadas por segundo. Lanza potentes gritos para intimidar.",
			[257] = "Sus puños están envueltos en llamas. Con sus golpes puede quemar a sus rivales.",
			[258] = "La aleta de su cabeza detecta las corrientes de agua y los peligros. Tiene fuerza para levantar rocas.",
			[259] = "Sus piernas robustas impiden que pierda el equilibrio y caiga, incluso en el barro. Duerme bajo la arena.",
			[260] = "Puede nadar y arrastrar un barco grande. Golpea a sus enemigos con sus gruesos brazos.",
			[261] = "Es muy persistente. Si se fija en una presa, no la dejará hasta que caiga agotada.",
			[262] = "Ataca a sus presas en manada. Nunca desobedece las órdenes de un entrenador avezado.",
			[263] = "Se mueve en zigzag. Se le da bien encontrar objetos ocultos en la hierba e incluso enterrados.",
			[264] = "Carga contra sus enemigos a más de 100 km por hora. Como solo va en línea recta, falla a menudo.",
			[265] = "Es el blanco favorito de muchos Pokémon pájaro. Se defiende con el veneno de las púas de su cola.",
			[266] = "Se agarra con su seda a las ramas de un árbol y espera su evolución bebiendo agua de lluvia.",
			[267] = "Aunque no lo parece, es un Pokémon agresivo. Si se le molesta cuando recoge polen, atacará.",
			[268] = "Jamás olvida a quienes lo atacaron mientras estaba en su capullo. Cuando evoluciona busca venganza.",
			[269] = "Bate las alas para esparcir polvo tóxico. De noche se come las hojas de los árboles de las avenidas.",
			[270] = "Parece una planta acuática. Hace de ferry para los Pokémon que no saben nadar.",
			[271] = "Tiene carácter travieso. Si ve un pescador, tira del anzuelo para confundirlo.",
			[272] = "Cuando oye música alegre sus músculos se llenan de energía y no puede evitar ponerse a bailar.",
			[273] = "Cuando cuelga de las ramas parece una bellota. Le encanta asustar a otros Pokémon.",
			[274] = "Cuando usa la hoja de su cabeza como flauta asusta a la gente. Vive en lo más profundo de los bosques.",
			[275] = "Con sus abanicos puede provocar vientos de 30 m por segundo capaces de levantar casas.",
			[276] = "Es un Pokémon valiente que no teme a los rivales fuertes. Vuela en busca de climas templados.",
			[277] = "Vuela en círculos en busca de presas. Cuando ve una, se lanza sin dudarlo.",
			[278] = "Aprovecha las corrientes ascendentes para ganar altura. Suele llevar comida en el pico.",
			[279] = "Transporta a pequeños Pokémon y huevos en su pico hasta lugares seguros.",
			[280] = "Si sus cuernos perciben emociones positivas de personas o Pokémon, su cuerpo se calienta un poco.",
			[281] = "Si su entrenador está contento, se llena de energía y baila de forma alegre dando giros.",
			[282] = "Para proteger a su entrenador emplea todo su poder psíquico en crear un pequeño agujero negro.",
			[283] = "Parece que patina sobre el agua. Atrae a las presas con el suave aroma de su cabeza.",
			[284] = "Sus antenas tienen dibujos de ojos, mientras que sus alas le permiten volar en cualquier dirección.",
			[285] = "Lanza esporas venenosas desde la parte superior de la cabeza. Inhalarlas es muy doloroso.",
			[286] = "Sus cortos brazos se expanden cuando da puñetazos. Tiene una técnica pugilística muy depurada.",
			[287] = "Pasa la mayor parte del día repanchingado. Entra sueño solo de verlo.",
			[288] = "Su corazón late a un ritmo diez veces más rápido de lo normal. No se está quieto ni un instante.",
			[289] = "El Pokémon más perezoso del mundo. Si está tumbado, es que reúne fuerzas para contraatacar.",
			[290] = "Crece bajo tierra y explora el entorno con sus antenas, que sustituyen a ojos atrofiados.",
			[291] = "Se mueve tan rápido que a veces resulta invisible. Le atrae la savia de los árboles.",
			[292] = "Es el caparazón de un bicho que cobró vida. Si alguien lo mira por la espalda, le robará el alma.",
			[293] = "Suele murmurar a un volumen casi inaudible, pero cuando se asusta grita con el volumen de un reactor.",
			[294] = "Las ondas de sus gritos pueden voltear un camión. Patea el suelo para ganar potencia.",
			[295] = "Su aullido se puede oír a 10 km. Emite todo tipo de sonidos desde los tubos de su cuerpo.",
			[296] = "Endurece su cuerpo golpeando grandes árboles. Cerca de su hogar suele haber árboles golpeados.",
			[297] = "Le encanta enfrentarse a Pokémon grandes y probar su fuerza. Sus brazos pueden derribar un camión.",
			[298] = "Su cola rebota como una pelota. Para luchar contra enemigos más grandes, la agita en el aire.",
			[299] = "Se protege del peligro aumentando su magnetismo y atrayendo objetos de hierro hacia sí.",
			[300] = "No puede evitar ir tras las cosas que se mueven. Hasta corre en círculos persiguiéndose la cola.",
			[301] = "Tiene mucho éxito entre las entrenadoras por su suave pelaje. No vive en un sitio fijo.",
			[302] = "Se oculta en cavernas oscuras. De tanto comer gemas sus ojos son piedras preciosas.",
			[303] = "Las grandes fauces de su cabeza están formadas por cuernos. Puede romper el hierro con ellas.",
			[304] = "Suele vivir en lugares inaccesibles de las montañas, pero el hambre lo empuja a comer raíles y coches.",
			[305] = "Extrae hierro para alimentarse y usa su cuerpo de acero para luchar y conseguir territorio.",
			[306] = "Mientras busca hierro para comer, excava túneles en la roca con sus potentes cuernos de acero.",
			[307] = "Se entrena en la profundidad de las montañas. Cuando aumenta su poder espiritual con meditación, levita.",
			[308] = "Cuando ayuna adquiere la habilidad de ver el aura de sus adversarios.",
			[309] = "Estimula sus músculos y aumenta sus reflejos con la electricidad que almacena su pelaje.",
			[310] = "Descarga electricidad desde su melena. Crea nubarrones desde los que lanza rayos.",
			[311] = "Anima a sus compañeros con pompones de chispas. Roba energía de los postes telefónicos.",
			[312] = "Le gusta animar a sus amigos. Si pierden, su cuerpo suelta cada vez más chispas.",
			[313] = "Se comunica con otros iluminando su cola por la noche. Le encanta el suave aroma de ILLUMISE.",
			[314] = "Su suave aroma guía a VOLBEAT para que haga señales luminosas en el cielo nocturno.",
			[315] = "Si goza de mejor salud, el aroma de sus flores será más agradable. Es un aroma que relaja a la gente.",
			[316] = "Casi todo su cuerpo es estómago. Sus potentes jugos gástricos disuelven rápido cualquier cosa.",
			[317] = "Se traga cualquier cosa de una pieza. Sus poros segregan fluidos tóxicos que dañan a sus enemigos.",
			[318] = "Rodean a los enemigos que osan invadir su territorio. Sus afilados colmillos dañan los barcos.",
			[319] = "Con sus colmillos puede atravesar el acero. Nada a 120 km por hora. Le llaman el “terror de los mares”.",
			[320] = "En días soleados se tumba en las playas para jugar y botar como una pelota. Lanza agua por la nariz.",
			[321] = "Es el más grande de los Pokémon. Puede nadar a una profundidad de 3000 m aguantando la respiración.",
			[322] = "En su joroba almacena magma ardiente que se enfría cuando llueve y lo ralentiza.",
			[323] = "Tiene volcanes en el lomo. Si el magma se acumula en su cuerpo, se sacude y estalla con violencia.",
			[324] = "Quema carbón en su caparazón para obtener energía. Si le atacan, echa un denso humo negro.",
			[325] = "Bota continuamente usando su cola como muelle. Salta para mantener el latido de su corazón.",
			[326] = "Usa perlas negras para potenciar sus poderes psíquicos. Con su raro baile controla a los rivales.",
			[327] = "No hay dos SPINDA que tengan idénticos pelajes. Su tambaleo al bailar confunde a los rivales.",
			[328] = "Cava fosas cóncavas en el desierto y espera en el fondo a que las presas caigan en ellas.",
			[329] = "Agita violentamente sus alas para crear ondas ultrasónicas que provocan dolores de cabeza.",
			[330] = "Levanta tormentas de arena con sus alas. Se le conoce como el “alma del desierto”.",
			[331] = "Habita en el desierto. Aguanta treinta días sin agua gracias a la que almacena en su cuerpo.",
			[332] = "Es un Pokémon nocturno. Busca presas agotadas por el calor diurno del desierto.",
			[333] = "Si su cuerpo o su entorno no están limpios, no puede relajarse. Utiliza sus alas para limpiar la suciedad.",
			[334] = "Si establece un vínculo con una persona, la envuelve con sus alas y le canta en susurros.",
			[335] = "Hace muchos años que se enfrenta a SEVIPER. Su arma más eficaz son sus zarpas afiladas.",
			[336] = "Se ha enfrentado durante muchos años a ZANGOOSE. Usa rocas para mantener afilada su cola.",
			[337] = "Se piensa que está muy influido por las fases lunares, ya que solo actúa en noches de luna llena.",
			[338] = "Una nueva especie de Pokémon que se rumorea procede del Sol. Emite luz al girar.",
			[339] = "Su escurridizo cuerpo es difícil de agarrar. En cierta región se dice que ha nacido de barro endurecido.",
			[340] = "Protege su territorio por encima de todo. Si se acerca un enemigo, ataca con violentas sacudidas.",
			[341] = "Su organismo le permite adaptarse a cualquier entorno. Sus pinzas nunca sueltan a su presa.",
			[342] = "Este malandrín usa sus pinzas para atosigar y expulsar a los otros Pokémon que viven en su estanque.",
			[343] = "Se mueve girando sobre su eje. Es un extraño Pokémon que fue encontrado en unas viejas ruinas.",
			[344] = "Este Pokémon es una vieja figurilla de barro que cobró vida mediante la exposición a extraños rayos de luz.",
			[345] = "Vivió en los fondos marinos hace unos 100 millones de años y fue recreado científicamente.",
			[346] = "Vive en el fondo de los mares de aguas templadas. Emerge para cazar cuando baja la marea.",
			[347] = "Este Pokémon fue recreado a partir de restos fósiles. Vivía en el mar y cazaba con sus pinzas.",
			[348] = "Tras evolucionar, este Pokémon fue a tierra firme. Una dura coraza protege todo su cuerpo.",
			[349] = "Su apariencia deja bastante que desear, pero es muy resistente y puede sobrevivir con poca agua.",
			[350] = "Sus preciosas escamas tienen todos los colores del arco iris y cambian de color según el ángulo de visión.",
			[351] = "La meteorología determina su aspecto. Hace poco se ha sabido que sus células son como el agua.",
			[352] = "Puede mudar el color de su cuerpo a voluntad, pero el dibujo en zigzag de su panza nunca desaparece.",
			[353] = "Les atraen los sentimientos de rencor y celos. Suelen vivir cerca de las casas de gente vengativa.",
			[354] = "Este muñeco se convirtió en un Pokémon cuando lo tiraron a la basura. Busca a su antiguo dueño.",
			[355] = "Le encanta atravesar paredes para asustar a los niños malos y hacerles llorar.",
			[356] = "Busca fuegos fatuos y los absorbe con su cuerpo hueco. Lo que pasa dentro luego es un misterio.",
			[357] = "Como solo comía un tipo de fruta, al final acabó creciéndole en el cuello.",
			[358] = "Sus gritos resuenan en su cuerpo hueco y emergen como hermosas notas que aturden a los enemigos.",
			[359] = "Cuando se supo que presentía los desastres con su cuerno, tuvo que buscar refugio en las montañas.",
			[360] = "Se fortalecen empujándose unos a otros en grupos. Les encantan los dulces.",
			[361] = "Se dice que se reúnen en grupos bajo hojas gigantescas y viven allí en total armonía.",
			[362] = "Impide que sus presas se escapen congelando la humedad del aire en un instante.",
			[363] = "Rueda por los témpanos de hielo hasta la orilla, ya que su cuerpo no está bien adaptado para nadar.",
			[364] = "Suele hacer girar objetos en su nariz. De esta forma aprende texturas y olores.",
			[365] = "Rompe el hielo con sus colmillos. Su gruesa capa de grasa le protege del frío y de los enemigos.",
			[366] = "Durante toda su vida, crea una sola perla que, según se dice, aumenta los poderes psíquicos.",
			[367] = "Vive en los fondos marinos. Atrae a sus confiadas presas con la cola, que tiene forma de pez.",
			[368] = "Vive en el fondo del mar. En primavera, su cuerpo rosado adquiere colores más vivos.",
			[369] = "Un Pokémon raro descubierto en una exploración marina. No ha cambiado en más de 100 millones de años.",
			[370] = "Vive en mares cálidos. Se dice que, si una pareja lo encuentra, será bendecida con amor eterno.",
			[371] = "Sueña con volar algún día, por lo que siempre practica saltando desde acantilados.",
			[372] = "Las células han empezado a cambiar dentro de su dura concha, que se separa cuando evoluciona.",
			[373] = "Siempre soñó con volar, por lo que su estructura celular cambió y le crecieron alas.",
			[374] = "Se comunican mediante pulsos magnéticos. Cuando van en grupos, se mueven al unísono.",
			[375] = "Lo forman dos BELDUM unidos. Puede chocarse con un avión sin que su cuerpo de acero sufra ni rasguño.",
			[376] = "Está formado por varios METANG. Con cuatro cerebros, tiene la inteligencia de un superordenador.",
			[377] = "Su cuerpo está hecho de roca. Si se astilla durante el combate, emplea piedras para repararlo.",
			[378] = "Su cuerpo está hecho con hielo de la glaciación. Controla aire gélido a 200 grados bajo cero.",
			[379] = "Su cuerpo ha estado sometido a la presión subterránea durante miles de años y no puede arañarse.",
			[380] = "Su cuerpo está cubierto de un plumón que refleja la luz de forma que se vuelve invisible.",
			[381] = "Es un Pokémon muy inteligente. Puede adelantar a aviones a reacción plegando las alas.",
			[382] = "Se dice que aumentó el nivel del mar a base de aguaceros. Ha estado durmiendo en una fosa marina.",
			[383] = "Ha estado durmiendo en magma subterráneo desde que luchó contra KYOGRE en tiempos remotos.",
			[384] = "Vive en la capa de ozono sobre las nubes y no puede ser visto desde el suelo.",
			[385] = "Se dice que puede otorgar cualquier deseo durante una semana cada mil años.",
			[386] = "Surgió a raíz de la mutación de ADN de un virus alienígena que cayó a la Tierra en un meteorito.",
			[387] = "La concha de su espalda es de tierra. Si está sano, la concha de TURTWIG debería estar húmeda.",
			[388] = "Sabe dónde encontrar manantiales de agua pura y lleva a los Pokémon amigos hasta allí en su lomo.",
			[389] = "Algunos Pokémon nacen en la espalda de un TORTERRA y pasan allí toda su vida.",
			[390] = "Es muy ágil. Antes de dormir apaga la llama de su cola para no provocar un incendio.",
			[391] = "Controla hábilmente la intensidad del fuego de su cola para mantener al enemigo a una distancia ideal.",
			[392] = "Utiliza movimientos de combate únicos con fuego en manos y pies. Se enfrenta a cualquier enemigo.",
			[393] = "No se le da bien lo de andar, se cae mucho. Pero su orgullo le hace sacar pecho como si nada.",
			[394] = "Como cada uno se considera el más importante, jamás podrán formar un grupo.",
			[395] = "Si alguien hiere su orgullo, le desgarra con unas alas que podrían cortar un témpano de hielo.",
			[396] = "Son débiles individualmente, por eso forman grupos. Pero si el grupo crece demasiado, se pelean.",
			[397] = "Son conscientes de su debilidad, así que siempre viven en grupo. Si se encuentran solos, lloran a gritos.",
			[398] = "Jamás deja de atacar, aunque le hayan herido. Le preocupa mucho la forma de su cresta.",
			[399] = "Un estudio comparativo reveló que los incisivos de BIDOOF crecen a la misma velocidad que los de RATTATA.",
			[400] = "Un río en el que un BIBAREL cree una presa jamás se desbordará. Por esa razón la gente los aprecia.",
			[401] = "Tiene las patas cortas. Cada vez que se tropieza, sus antenas chocan y suenan como un xilófono.",
			[402] = "Hay un pueblo en el que celebran un concurso basado en la increíble variedad de sus gritos.",
			[403] = "La extensión y contracción de sus músculos genera electricidad. Brilla cuando está en peligro.",
			[404] = "Por las puntas de sus garras pasa una fuerte corriente eléctrica. El mínimo roce debilita al enemigo.",
			[405] = "Puede ver claramente a través de las paredes para buscar a sus presas o a sus crías.",
			[406] = "Es muy sensible a los cambios de temperatura. Se dice que si le da el sol, su capullo florece.",
			[407] = "Cada una de sus manos contiene toxinas diferentes, pero ambas tienen un poder casi mortífero.",
			[408] = "Vivía en la jungla hace 100 millones de años. Apartaba los árboles del camino a cabezazos.",
			[409] = "Su cráneo es de 30 cm de grosor. Si dos de ellos se dan un cabezazo no les ocurrirá nada.",
			[410] = "Gracias a su imponente protección facial, puede comer hierba y bayas donde quiera sin que le molesten.",
			[411] = "Se alineaban y creaban una barrera que ningún enemigo podía cruzar. Así protegían a sus crías.",
			[412] = "Aunque nazca en un lugar en el que no haya muchos materiales, siempre consigue crearse un caparazón.",
			[413] = "Cuando evoluciona incorpora a su cuerpo los materiales del entorno. Por eso hay muchas variantes.",
			[414] = "Le gusta la miel de flores, pero no le gusta recogerla. Se dedica a robársela a COMBEE.",
			[415] = "El trío se forma al nacer y se pasa la vida recogiendo miel de las flores para satisfacer a VESPIQUEN.",
			[416] = "Libera feromonas para hacer que las larvas de su panal hagan lo que diga cuando combate.",
			[417] = "A veces se ve a dos frotándose las bolsas de las mejillas para compartir electricidad almacenada.",
			[418] = "Para impulsarse por el agua gira sus dos colas como una hélice. Así también corta las algas del camino.",
			[419] = "Se le ve en los puertos pesqueros, ayudando a rescatar a personas o trasladando presas.",
			[420] = "Esta pequeña esfera está llena de nutrientes y está tan rica que los STARLY siempre intentan comérsela.",
			[421] = "Cuando detecta luz solar fuerte, despliega los pétalos y absorbe todos los rayos posibles.",
			[422] = "No hay que apretarle muy fuerte, ya que si lo haces, secreta un misterioso fluido morado.",
			[423] = "Hace mucho tiempo tenía todo el lomo cubierto con una concha. Aún hay trazas de ella en sus células.",
			[424] = "Tiene dos colas muy útiles y hábiles para manejar cosas, así que rara vez utiliza las manos.",
			[425] = "Por esa forma que tiene de flotar sin rumbo, en un cuento se le apodó “Globo aeroerrático”.",
			[426] = "Al anochecer se reúnen en grupos y vuelan a la deriva. Cuando alguien los ve, desaparecen.",
			[427] = "Lleva las orejas enrolladas. Cuando las extiende, golpea con tal fuerza que incluso puede romper rocas.",
			[428] = "Sus orejas son muy delicadas. Si alguien las toca con brusquedad, recibirá una espléndida patada.",
			[429] = "Sus gritos parecen cánticos. Se dice que en alguna rara ocasión han imbuido felicidad a quien los oía.",
			[430] = "Si uno lanza un grito profundo, los demás acuden. Por eso se le llama también “Invocador de la noche”.",
			[431] = "Oculta una tendencia rencorosa que le hace arañar la nariz de su entrenador si no le da de comer.",
			[432] = "Rodea su cuerpo con las colas para parecer más grande. Si fija la mirada, no se perderá un detalle.",
			[433] = "Tiene una esfera en la boca. Cuando salta, la esfera rebota y emite un zumbido.",
			[434] = "Expulsa un fluido maloliente por sus cuartos traseros. El hedor repele Pokémon en un radio de 2 km.",
			[435] = "Ataca emitiendo un fluido maloliente por la punta de su cola. Los ataques aéreos le confunden.",
			[436] = "Algunos investigadores creen que antiguamente este Pokémon reflejaba las cosas como un espejo.",
			[437] = "Traía lluvias abriendo portales a otro mundo. Era adorado como propiciador de buenas cosechas.",
			[438] = "Prefiere entornos áridos. Sus ojos expulsan agua para ajustar sus niveles de hidratación corporal.",
			[439] = "Cuando tiene a alguien delante imita su expresión y movimientos para entender sus sentimientos.",
			[440] = "Se pasea por ahí con una roquita. A veces se cuela entre los pies de los demás y hace que tropiecen.",
			[441] = "Su lengua es como la de cualquier persona, así que puede imitar muy bien el habla humana.",
			[442] = "Por sus constantes fechorías se le acabó uniendo a una Piedra Espíritu con un misterioso hechizo.",
			[443] = "Ataca usando su enorme boca y, con lo torpe que es, también se suele dañar con sus potentes ataques.",
			[444] = "Le gustan las cosas brillantes. Busca tesoros en cuevas y se lleva el botín a su nido.",
			[445] = "Se dice que, cuando va a velocidad máxima, sus alas crean cuchillas de viento que talan cualquier árbol.",
			[446] = "En su desesperación por engullir comida, se suele olvidar de la que esconde debajo de su pelaje.",
			[447] = "Tiene un poder peculiar: puede ver emociones como el odio y la alegría en forma de ondas.",
			[448] = "Si se ha entrenado bien, puede percibir auras e identificar y asimilar sentimientos a 1 km.",
			[449] = "Cierra la nariz y luego atraviesa la arena con total tranquilidad. Suele formar colonias de diez individuos.",
			[450] = "Mantiene la boca abierta para mostrar su fuerza. Se enfada con sorprendente rapidez.",
			[451] = "Aferra las presas con las garras de la cola y les inyecta veneno. Sobrevive un año sin comida.",
			[452] = "Tiene una complexión muy fuerte de la que se enorgullece. Derriba a sus enemigos sin usar toxinas.",
			[453] = "Rara vez combate limpio, pero es para asegurar su supervivencia. Es muy popular como mascota.",
			[454] = "Almacena veneno en una bolsa de la garganta. Cuando croa, este se agita para lograr mayor potencia.",
			[455] = "Se cuelga de los árboles en los pantanos. Atrae a sus presas con su dulce olor y las engulle.",
			[456] = "La línea que le recorre el costado puede almacenar luz solar. Brilla con mucha fuerza por la noche.",
			[457] = "Se arrastra por el fondo marino con sus largas aletas frontales. Compite con LANTURN por la comida.",
			[458] = "La gente organiza excursiones para ver a este Pokémon retozando por las olas con REMORAID.",
			[459] = "Siente mucha curiosidad por los humanos. Si uno encuentra huellas en la nieve, acuden todos a mirar.",
			[460] = "Aparece con las flores de nieve y se retira cuando se les caen los pétalos. No se sabe adónde va.",
			[461] = "Su carácter se volvió aún más vil con la evolución. Se comunica marcando rocas con sus garras.",
			[462] = "Un grupo de investigadores intentó provocar su evolución por medios artificiales, pero fracasó.",
			[463] = "Su larga lengua está siempre llena de babas. El contacto con su saliva causa entumecimiento.",
			[464] = "Si tensa y expande los músculos muy rápido, puede disparar las rocas que tenga en la mano como misiles.",
			[465] = "Sus brazos están hechos de plantas que se agarran a las cosas. Si se le cortan vuelven a crecer enseguida.",
			[466] = "Ignora los ataques del enemigo y se acerca para clavarle las colas y darle una descarga de alto voltaje.",
			[467] = "Cuando lanza sus bolas de fuego a 2000 grados, su cuerpo adquiere un tono blanquecino por el calor.",
			[468] = "Congenia muy bien con las personas que respetan los derechos de los demás y evitan riñas innecesarias.",
			[469] = "Pasa volando a gran velocidad al lado de sus enemigos y los destroza con su potente mandíbula.",
			[470] = "Prácticamente no combate. Sus células parecidas a las vegetales le permiten hacer la fotosíntesis.",
			[471] = "Controla su temperatura corporal para congelar el ambiente y causar ráfagas de nieve en polvo.",
			[472] = "Si da con una corriente de aire buena, por mínima que sea, puede dar la vuelta al globo sin aletear.",
			[473] = "Se encontró un ejemplar congelado hace 10000 años en una excavación. ¡Y se despertó!",
			[474] = "Se modificó su programación para que pudiera trabajar en dimensiones alienígenas. Pero no funcionó.",
			[475] = "Cuando quiere proteger a alguien, extiende los codos como si fueran espadas y lucha con fiereza.",
			[476] = "Con el magnetismo que emana, controla tres pequeñas unidades llamadas Mini-Narices.",
			[477] = "Se dice que recoge en su cuerpo flexible a los espíritus extraviados y los guía hasta casa.",
			[478] = "Congela a sus presas con su aliento gélido de 50 grados bajo cero. Se dice que luego las expone.",
			[479] = "Con su cuerpo eléctrico puede infiltrarse en algunas máquinas para controlarlas y causar daños.",
			[480] = "Voló y las personas adquirieron la capacidad para resolver problemas. Así nació la sabiduría.",
			[481] = "Voló y los humanos aprendieron sobre la felicidad y la tristeza de vivir. Así nacieron las emociones.",
			[482] = "Voló y los humanos lograron la determinación para hacer cosas. Así nació la voluntad.",
			[483] = "Un Pokémon legendario de Sinnoh. Se dice que el tiempo avanza con cada latido de su corazón.",
			[484] = "Un Pokémon legendario de Sinnoh. Se dice que el espacio se vuelve más estable con cada respiración suya.",
			[485] = "Su cuerpo es de rugoso acero, pero su propio calor corporal lo ha derretido en algunos puntos.",
			[486] = "Se dice que usó rocas, magma y un hielo especial de montaña para crear Pokémon con su aspecto.",
			[487] = "Fue desterrado por su violencia. Observa el mundo en silencio desde el Mundo Distorsión.",
			[488] = "En las noches de media luna, la aurora de su cola se extiende y ondea más hermosa que nunca.",
			[489] = "Va a la deriva por mares cálidos. Siempre vuelve a donde nació, por mucho que se haya alejado.",
			[490] = "Nace con un maravilloso poder que le permite establecer vínculos con cualquier tipo de Pokémon.",
			[491] = "Para protegerse causa pesadillas a los que le rodean. Pero no lo hace con intención de hacer daño.",
			[492] = "Todas las flores de su cuerpo florecen si se le abraza con amor y percibe gratitud.",
			[493] = "Se dice que surgió de un huevo en un lugar en el que no había nada. Y luego dio forma al mundo.",
		},
		[701] = { -- species_pokedex_entry_fr
			[1] = "Au matin de sa vie, la graine sur son dos lui fournit les éléments dont il a besoin pour grandir.",
			[2] = "Lorsque le bourgeon sur son dos éclot, il répand un doux parfum pour célébrer sa floraison.",
			[3] = "Le parfum de sa fleur se fait plus pénétrant les lendemains de pluie. Cela appâte les autres Pokémon.",
			[4] = "La flamme de sa queue symbolise sa vitalité. Elle est intense quand il est en bonne santé.",
			[5] = "La nuit, la queue ardente du REPTINCEL brille comme une étoile dans son repaire montagneux.",
			[6] = "On raconte que la flamme du DRACAUFEU s’intensifie après un combat difficile.",
			[7] = "Il se réfugie dans sa carapace et réplique en éclaboussant l’ennemi à la première occasion.",
			[8] = "On prétend qu’il vit 10 000 ans. Sa queue duveteuse est un symbole de longévité populaire.",
			[9] = "Les trombes d’eau projetées par les canons de sa carapace peuvent percer le métal le plus résistant.",
			[10] = "Ses antennes rouges libèrent une puanteur qui repousse l’ennemi. Il grandit par mues régulières.",
			[11] = "Son corps frêle est protégé par sa carapace d’acier. Il encaisse les coups durs en attendant d’évoluer.",
			[12] = "Il raffole du nectar des fleurs. Il est capable de repérer la plus petite quantité de pollen.",
			[13] = "Il mange chaque jour son poids en feuilles. Il utilise l’aiguillon sur sa tête pour repousser l’ennemi.",
			[14] = "Il se cache sous les feuilles et les branches pour fuir les prédateurs en attendant d’évoluer.",
			[15] = "Il virevolte rapidement autour de l’ennemi et frappe de son dard empoisonné avant de décamper.",
			[16] = "Ce Pokémon docile préfère éviter le combat. Toutefois, il se montre très féroce quand on l’agresse.",
			[17] = "Il survole son vaste territoire en quête d’une proie avant de fondre sur elle toutes griffes en avant.",
			[18] = "En battant des ailes de toutes ses forces, ROUCARNAGE génère une rafale à en déraciner les arbres.",
			[19] = "D’une prudence extrême, sa nature robuste lui permet de s’adapter à tous les terrains.",
			[20] = "Il grignote sans cesse pour apaiser la poussée de ses crocs. Il peut transpercer un mur de parpaings.",
			[21] = "Il fait battre vigoureusement ses petites ailes pour voler et cherche à manger dans l’herbe avec le bec.",
			[22] = "Il a assez d’énergie pour voler toute la journée avec ses grandes ailes. Il frappe de son bec acéré.",
			[23] = "Il se faufile dans l’herbe sans un bruit et frappe dans le dos quand sa proie s’y attend le moins.",
			[24] = "Il utilise la marque sur son ventre pour intimider l’ennemi. Il étouffe l’ennemi pétrifié par la peur.",
			[25] = "Il vit en forêt avec ses pairs. Il accumule l’électricité dans les poches de ses joues.",
			[26] = "Il devient agressif lorsque son corps contient trop d’électricité. Il la décharge par sa queue.",
			[27] = "Il vit sur des terres arides épargnées par la pluie. Il se roule en boule pour se protéger.",
			[28] = "Il se met en boule pour percuter l’ennemi. Ses épines aiguisées font beaucoup de dégâts.",
			[29] = "Bien qu’il rechigne à se battre, une goutte du poison sécrété par ses piquants peut s’avérer fatale.",
			[30] = "Ce Pokémon dresse ses piquants en cas de danger. Ils poussent moins vite que ceux de NIDORINO.",
			[31] = "Son corps est recouvert d’écailles solides. Il donnera sa vie pour secourir les petits de son terrier.",
			[32] = "Il jauge le terrain en laissant ses oreilles dépasser de l’herbe. Il se défend avec sa corne toxique.",
			[33] = "D’un tempérament violent, il empale l’ennemi sur sa corne qui distille un poison puissant.",
			[34] = "Un coup de sa puissante queue peut briser un poteau téléphonique comme une allumette.",
			[35] = "Tout le monde craque pour cet adorable Pokémon. Il vit en groupe dans le calme des montagnes.",
			[36] = "Il joue au bord des lacs déserts les soirs de pleine lune. Rares sont ceux qui l’ont aperçu.",
			[37] = "Il envoie des boules de feu. Avec l’âge, ses six queues en forment de nouvelles.",
			[38] = "On raconte que ses neuf queues détiennent un pouvoir mystique. Il peut vivre pendant mille ans.",
			[39] = "Lorsqu’il roule ses grands yeux ronds, il entonne une berceuse qui endort son auditoire.",
			[40] = "Sa fourrure est d’une douceur incomparable au toucher. Il peut gonfler en aspirant de l’air.",
			[41] = "Bien que dépourvu d’yeux, il repère les obstacles grâce aux ultrasons émis par sa gueule.",
			[42] = "Il aime le sang des humains et des Pokémon. Il erre la nuit en quête d’un cou où planter ses crocs.",
			[43] = "En journée, il plante ses pieds- racines dans le sol. La nuit, il se promène en semant des graines.",
			[44] = "L’odeur du nectar de sa bouche est si répugnante qu’elle agresse les narines à deux kilomètres.",
			[45] = "Ses pétales sont les plus grands du monde. Il marche en répandant un pollen extrêmement allergène.",
			[46] = "Des champignons appelés “tochukaso” poussent sur son dos. Ils évoluent avec le PARAS hôte.",
			[47] = "Un champignon parasite plus gros que PARASECT contrôle son corps. Il répand des spores empoisonnées.",
			[48] = "Ses grands yeux sont en fait des amas d’yeux minuscules. La nuit, il est attiré par la lumière.",
			[49] = "Il répand ses écailles poudreuses en battant des ailes. Elles sont toxiques au toucher.",
			[50] = "Un Pokémon qui vit sous terre. Habitué aux souterrains, il fuit la lumière du jour.",
			[51] = "Ses trois têtes creusent le sol à tour de rôle. Il peut atteindre des profondeurs de 100 kilomètres.",
			[52] = "Son regard s’anime à la vue d’un objet brillant. C’est un Pokémon nocturne.",
			[53] = "Un Pokémon très snob. La taille du joyau qui orne son front alimente bien des débats parmi ses fans.",
			[54] = "Quand son mal de crâne empire, il développe d’étranges pouvoirs dont il ne se souvient jamais.",
			[55] = "Un habitant des lacs. Il nage plus vite qu’un champion humain de natation.",
			[56] = "Ils vivent en colonies sylvestres. Quand un FEROSINGE s’énerve, toute la colonie suit son exemple.",
			[57] = "Il grogne quand on le toise, rugit quand on s’enfuit et devient fou de rage quand on le frappe.",
			[58] = "Un Pokémon très loyal. Il restera immobile jusqu’à ce que son Dresseur lui donne un ordre.",
			[59] = "Son port altier et son attitude fière ont depuis longtemps conquis le cœur des hommes.",
			[60] = "Sa peau est si mince qu’on voit ses organes internes. Il tient à peine sur ses nouveaux pieds.",
			[61] = "La spirale qui orne son ventre ondule doucement. Celui qui la fixe est saisi d’une étrange torpeur.",
			[62] = "Il possède de sacrés biscoteaux. Il peut parcourir sans relâche l’Océan Pacifique.",
			[63] = "Il dort 18 heures par jour. Même éveillé, il ne prend pas la peine de se lever pour se téléporter.",
			[64] = "Une ombre inquiétante obscurcit l’écran télé quand il s’approche. Le malheur frappe celui qui la voit.",
			[65] = "Grâce à sa mémoire exceptionnelle, il n’a rien oublié depuis sa naissance. Il a un Q.I. de 5 000.",
			[66] = "Il muscle son corps en soulevant régulièrement un GRAVALANCH. Il est rompu à tous les arts martiaux.",
			[67] = "La force herculéenne du MACHOPEUR est très dangereuse. Il utilise une ceinture pour contenir son énergie.",
			[68] = "Ses quatre bras frappent à une vitesse aveuglante. Il peut porter 1 000 coups en deux secondes.",
			[69] = "Il préfère les climats chauds et humides. Ses lianes peuvent capturer une proie en un clin d’œil.",
			[70] = "Un Pokémon végétal. Il capture les proies étourdies en les endormant à l’aide d’une poudre toxique.",
			[71] = "Sa bouche sécrète un fluide à l’odeur de miel, qui s’avère être un acide extrêmement corrosif.",
			[72] = "Son corps est principalement composé d’eau. Ses yeux cristallins projettent d’étranges rayons.",
			[73] = "Ses 80 tentacules ligotent ses proies et les retiennent jusqu’à ce que son poison fasse effet.",
			[74] = "Nombre d’entre eux vivent sur des chemins montagneux où ils restent enfouis à épier les alpinistes.",
			[75] = "GRAVALANCH creuse son terrier à flanc de montagne en perçant des galeries horizontales.",
			[76] = "Il mue une fois par an. Son corps rocailleux est si dur qu’il résiste même à la dynamite.",
			[77] = "La crinière et la queue ardentes lui donnant sa superbe poussent une heure après sa naissance.",
			[78] = "Son galop dépasse les 240 km/h. Il file comme une flèche, laissant flotter sa crinière ardente.",
			[79] = "Bien que lent, c’est un pêcheur adroit qui utilise sa queue. Elle est insensible aux morsures.",
			[80] = "Ce grand benêt connaît des éclairs de lucidité lorsque le KOKIYAS de sa queue se met à mordre.",
			[81] = "Ses extrémités génèrent les vagues électromagnétiques qui le font voler. Il se nourrit d’électricité.",
			[82] = "Il est formé de trois MAGNETI liés par magnétisme. En groupe, ils déclenchent un orage magnétique.",
			[83] = "Il ne peut pas vivre sans son légume, c’est pourquoi il le protégera au péril de sa vie.",
			[84] = "Ses deux cerveaux semblent communiquer leurs émotions grâce à un lien télépathique.",
			[85] = "Quand DODUO connaît cette étrange évolution, l’une de ses têtes se dédouble. Il atteint les 60 km/h.",
			[86] = "Un habitant des icebergs. En mer, il utilise la corne sur sa tête pour briser la banquise.",
			[87] = "Son corps est couvert d’un grand manteau blanc qui, dans la neige, le dissimule aux yeux des prédateurs.",
			[88] = "Il est né d’un torrent de boue exposé aux rayons X de la lune. Il vit dans les ordures.",
			[89] = "Son corps exsude un fluide toxique qui tue instantanément les plantes et les arbres au contact.",
			[90] = "Il nage à reculons en ouvrant et en refermant ses deux coquilles. Il laisse traîner sa large langue.",
			[91] = "Il se défend en fermant sa coquille et projette des piquants qui repoussent ses agresseurs.",
			[92] = "Le corps de ce Pokémon est composé de gaz à 95%. Une bourrasque suffit à le disperser.",
			[93] = "Il peut traverser n’importe quel obstacle. Il rôde dans les murs pour surveiller ses ennemis.",
			[94] = "On dit que lorsqu’ECTOPLASMA se cache dans l’ombre, la température alentour chute de 5 °C.",
			[95] = "Il provoque des secousses sismiques en creusant. Il peut atteindre les 80 km/h.",
			[96] = "Son grand nez lui permet de lire les rêves d’autrui. Il adore les songes amusants.",
			[97] = "La vue de son pendule oscillant endort en trois secondes, même quand on vient de se réveiller.",
			[98] = "Il creuse son terrier sur des plages sablonneuses. Ses pinces repoussent si on les brise.",
			[99] = "Sa grande pince possède une puissance de 10 000 chevaux. Son poids la rend difficile à manier.",
			[100] = "Il ressemble à une Poké Ball. Ce Pokémon dangereux peut exploser ou s’électrifier au toucher.",
			[101] = "Il se laisse porter par les vents lorsque son corps est gonflé d’électricité à en éclater.",
			[102] = "Ces six œufs communiquent par télépathie. Ils peuvent se réunir rapidement si on les sépare.",
			[103] = "On l’appelle “jungle sur pattes”. Si une tête devient trop grosse, elle tombe et produit un NOEUNOEUF.",
			[104] = "Il pleure en pensant à sa mère disparue, et ses larmes résonnent dans son crâne creux.",
			[105] = "Ce Pokémon sauvage possède des os depuis sa naissance. Il s’en sert pour combattre avec dextérité.",
			[106] = "Ses pattes élastiques s’allongent, ce qui ne manque jamais de surprendre au premier combat.",
			[107] = "Même le béton cède sous ses poings dévastateurs. Au combat, il s’essouffle au bout de 3 minutes.",
			[108] = "Il n’utilise pas ses mains mais sa langue qui fait deux fois sa taille. Sa salive est une colle puissante.",
			[109] = "Il flotte en retenant des gaz plus légers que l’air. Ceux-ci sont explosifs, en plus d’être fétides.",
			[110] = "Il grandit en absorbant les gaz des détritus. Des triplés existent, bien qu’ils soient fort rares.",
			[111] = "Sa peau est très épaisse et sa charge peut détruire un immeuble. Dommage qu’il soit stupide.",
			[112] = "Son cerveau s’est développé depuis qu’il tient debout. Sa corne peut traverser la pierre la plus dure.",
			[113] = "Il est censé apporter la joie. Ce Pokémon charitable offre ses œufs aux blessés.",
			[114] = "Il s’abrite derrière des lianes bleues. Nul n’a jamais vu le visage qu’elles dissimulent.",
			[115] = "Il élève ses petits dans sa poche ventrale. Il attend d’être en lieu sûr pour les laisser jouer dehors.",
			[116] = "Il niche à l’ombre du corail. Quand il se sent menacé, il disparaît dans un nuage d’encre opaque.",
			[117] = "Son épine dorsale le protège. Ses os et ses nageoires sont très prisés en médecine traditionnelle.",
			[118] = "Il nage élégamment en agitant sa nageoire caudale comme si c’était une robe. Il a l’allure d’une reine.",
			[119] = "Il niche dans des rochers du ruisseau qu’il évide avec sa corne. Il donnerait sa vie pour ses œufs.",
			[120] = "Même amoché, son corps se régé- nère tant que le noyau rouge est intact. Le noyau s’illumine à minuit.",
			[121] = "Un noyau rouge trône en son centre. Il envoie des signaux radio mystérieux vers le ciel nocturne.",
			[122] = "Un expert de la pantomime dont les gestes façonnent de solides murs invisibles.",
			[123] = "Ses coups de faux sont pratiquement imparables. Il se déplace comme un ninja.",
			[124] = "Son cri ressemble à des paroles humaines. Mais nul n’est jamais parvenu à les comprendre.",
			[125] = "Ce Pokémon dévore l’électricité des centrales. Il est responsable de la majorité des coupures de courant.",
			[126] = "Il est né au milieu d’un volcan. Son corps est couvert de flammes qui flambent comme un soleil.",
			[127] = "Il serre les proies dans ses pinces pour les trancher en deux. S’il n’y arrive pas, il les jette au loin.",
			[128] = "Après avoir choisi sa cible, il fonce dessus tête baissée. Il est réputé pour sa nature violente.",
			[129] = "Ce Pokémon est réputé pour être le plus faible au monde. Nul ne sait comment son espèce perdure.",
			[130] = "Lorsqu’il apparaît, sa rage ne cesse qu’après qu’il a rasé les plaines et montagnes alentour.",
			[131] = "Il aime naviguer en portant des humains et des Pokémon sur son dos. Il comprend le langage humain.",
			[132] = "Il a la capacité de modifier sa structure cellulaire pour prendre l’apparence de ce qu’il voit.",
			[133] = "Un Pokémon rare qui s’adapte aux environnements hostiles en variant ses formes évolutives.",
			[134] = "Il a évolué pour s’adapter au milieu aquatique. Il peut se fondre et disparaître dans l’élément liquide.",
			[135] = "Il contrôle une puissance de 10 000 volts. Il peut hérisser sa fourrure comme s’il s’agissait de piquants.",
			[136] = "Son corps contient une glande enflammée. Sa température monte à 900 °C avant le combat.",
			[137] = "Le premier Pokémon artificiel au monde. Il a le pouvoir d’arpenter l’espace électronique.",
			[138] = "Un Pokémon ramené à la vie par la science à partir d’un fossile. Il peuplait autrefois les mers.",
			[139] = "On pense que ce Pokémon a disparu parce que sa coquille en spirale était devenue trop grosse.",
			[140] = "On pense qu’il peuplait les plages il y a 300 millions d’années. Il est protégé par une coquille robuste.",
			[141] = "On pense que ce Pokémon est venu sur la terre ferme pour suivre l’évolution de ses proies.",
			[142] = "Un Pokémon qui arpentait le ciel au temps des dinosaures. Ses crocs sont pareils à des scies.",
			[143] = "Son estomac peut digérer n’importe quel type de nourriture, même quand elle est moisie ou pourrie.",
			[144] = "Un Pokémon Oiseau légendaire. Il peut provoquer des blizzards en gelant l’humidité de l’air.",
			[145] = "Un Pokémon Oiseau légendaire dont on dit qu’il vit dans les nuages d’orage. Il contrôle la foudre.",
			[146] = "L’un des Pokémon Oiseaux légendaires. On dit que sa venue annonce l’arrivée du printemps.",
			[147] = "On l’appelle “Pokémon mirage” en raison de sa rareté. On a découvert sa mue.",
			[148] = "La météo change brusquement quand il est entouré d’une aura. On dit qu’il peuple les mers et les lacs.",
			[149] = "On raconte qu’il vit quelque part en mer. Il guide les équipages naufragés jusqu’à la terre ferme.",
			[150] = "Un Pokémon conçu en réorganisant les gènes de MEW. On raconte qu’il s’agit du Pokémon le plus féroce.",
			[151] = "Nombre de scientifiques voient en lui l’ancêtre des Pokémon car il maîtrise toutes leurs capacités.",
			[152] = "Il jauge la température et l’humidité grâce à la feuille sur sa tête. Il raffole des bains de soleil.",
			[153] = "Le collier de bourgeons à son cou répand un arôme épicé qui vous donne du tonus.",
			[154] = "Son souffle a l’incroyable capacité de ranimer les plantes et les fleurs flétries.",
			[155] = "Ce Pokémon est un grand timide. Les flammes sur son dos s’intensifient lorsqu’il prend peur.",
			[156] = "La chaleur de ses flammes intimide l’ennemi. Elles s’intensifient lorsqu’il se prépare à combattre.",
			[157] = "Il attaque en projetant des flammes. Il se dissimule derrière les vagues de chaleur qu’il produit.",
			[158] = "Il broie tout ce qu’il trouve avec ses mâchoires puissantes. Même son Dresseur doit s’en méfier.",
			[159] = "Quand il mord, il ne lâche pas prise avant que ses crocs se brisent. Ils repoussent par la suite.",
			[160] = "Ce Pokémon à l’air pataud est capable d’attaquer à la vitesse de l’éclair pour mordre sa proie.",
			[161] = "Ce Pokémon très nerveux prend appui sur sa queue pour observer ses alentours.",
			[162] = "La femelle s’enroule autour des petits pour les bercer. Il accule l’ennemi grâce à sa vitesse.",
			[163] = "Il se tient toujours sur un pied. Il ne prend jamais appui sur les deux, même en cas d’attaque.",
			[164] = "Ses yeux sont particuliers. La plus petite source de lumière leur permet de distinguer les objets.",
			[165] = "Il est si timide qu’il ne se déplace qu’au milieu d’un essaim. Il exprime ses émotions par l’odeur.",
			[166] = "Il tire sa force de la lumière des étoiles. Plus il y en a et plus ses motifs dorsaux sont grands.",
			[167] = "Il tisse une toile fine mais solide pour poser des pièges et se poste dans l’attente d’une proie.",
			[168] = "Il attache un fil à sa proie avant de la libérer. Il s’en servira pour la retrouver, elle et ses amis.",
			[169] = "Il vole rapidement et sans faire de bruit grâce à ses quatre ailes. C’est un Pokémon nocturne.",
			[170] = "Il envoie des décharges électriques positives et négatives du bout des antennes pour paralyser sa proie.",
			[171] = "La lumière de LANTURN surgit des profondeurs. On le surnomme “étoile des profondeurs”.",
			[172] = "Les poches sur ses joues sont encore trop petites pour accumuler beaucoup d’électricité.",
			[173] = "Sa silhouette rappelle une étoile. On dit qu’il descend sur terre en chevauchant une étoile filante.",
			[174] = "Son corps est doux et élastique. Quand il commence à rebondir, on ne peut plus l’arrêter.",
			[175] = "On prétend que sa coquille est remplie de bonheur, qu’il partage avec les êtres au cœur pur.",
			[176] = "On dit qu’il apparaît aux êtres bons pour répandre un duvet brillant appelé “poudre de joie”.",
			[177] = "Il mange des cactus en prenant soin d’éviter les bourgeons et les épines. Il ne tient pas en place.",
			[178] = "Cet étrange Pokémon peut voir l’avenir et le passé. Il guette sans cesse la course du soleil.",
			[179] = "Sa laine fournie enfle lorsqu’il accumule de l’électricité statique. Son contact peut choquer.",
			[180] = "Sa queue s’allume lorsque sa laine se charge d’électricité. Il projette des poils électrifiés.",
			[181] = "Le bout de sa queue brille avec intensité. Jadis, on s’en servait pour envoyer des signaux.",
			[182] = "A la fin de la saison des pluies, il sort danser en plein air, attiré par la chaleur du soleil.",
			[183] = "Il plonge sous l’eau en utilisant sa queue comme un flotteur. Il aime les plantes du fond des rivières.",
			[184] = "Il peuple les lacs et les mers. Sous l’eau, ses motifs et ses couleurs brouillent la vue de l’ennemi.",
			[185] = "On pourrait le prendre pour un arbre, mais il est plus proche d’une pierre. L’eau est son point faible.",
			[186] = "Il rassemble ses pairs pour les commander. Il utilise son cri pour diriger PTITARD.",
			[187] = "Il dérive avec le vent. Sa présence en nombre dans les champs et les montagnes annonce le printemps.",
			[188] = "Il fleurit lorsque les températures remontent. Il flotte dans le ciel pour absorber les rayons du soleil.",
			[189] = "Poussé par les vents saisonniers, il fait le tour du globe en semant des spores de coton.",
			[190] = "Il utilise sa queue pour cueillir les fruits inaccessibles. Elle est plus agile que ses mains.",
			[191] = "Il tombe du ciel sans crier gare en matinée. On en croise énormément l’année suivant un été froid.",
			[192] = "Les rayons du soleil lui donnent de l’énergie. Il est connu pour migrer vers les régions ensoleillées.",
			[193] = "Il voit à 360 degrés sans avoir à tourner la tête. Il ne loupe jamais une proie, même dans son dos.",
			[194] = "Il vit en eau froide. Il dort à demi enfoui dans la boue au fond de l’eau.",
			[195] = "C’est un grand paresseux qui attend au fond de la rivière qu’une proie lui tombe dans le bec.",
			[196] = "Son pelage a l’aspect et la texture du velours. L’orbe à son front luit quand il utilise ses pouvoirs psy.",
			[197] = "La lumière de la lune a modifié le code génétique d’EVOLI. Il hante les ombres en quête d’une proie.",
			[198] = "On dit que rencontrer un CORNEBRE la nuit est signe de mauvais augure.",
			[199] = "La morsure de KOKIYAS a fait de lui un génie dont l’intelligence rivalise avec celle d’un prix Nobel.",
			[200] = "Il adore se faufiler derrière les gens la nuit pour les effrayer avec son cri strident.",
			[201] = "Il rappelle une écriture ancienne. Reste à savoir qui du langage ou de ZARBI est apparu en premier.",
			[202] = "Il cherche désespérément à cacher sa queue noire. Certains pensent qu’elle renferme un secret.",
			[203] = "Sa queue contient un minuscule cerveau. Elle mord l’ennemi qui essaie de le frapper dans le dos.",
			[204] = "Il ressemble à une pomme de pin. Sa carapace le protège des Pokémon Oiseau qui le picorent par erreur.",
			[205] = "Il est prisonnier d’une coquille d’acier. Ses yeux vigilants sont la seule partie visible de son corps.",
			[206] = "Son nid est un véritable labyrinthe qu’il creuse à l’aide de sa queue. Il sait à peine voler.",
			[207] = "Il chevauche les vents en tendant ses membres pour frapper depuis le ciel. Il vise toujours au visage.",
			[208] = "Grâce à la température élevée et la haute pression souterraines, son corps est plus dur que le métal.",
			[209] = "Son visage horrible fait fuir les petits Pokémon. Par contre, les femmes le trouvent mignon.",
			[210] = "En dépit des apparences, c’est un grand timide. Quand il s’énerve, il mord de ses énormes crocs.",
			[211] = "Il envoie ses piquants empoisonnés à la ronde. Sa forme sphérique en fait un piètre nageur.",
			[212] = "Son corps est dur comme l’acier. Il intimide ses ennemis en levant ses pinces pareilles à des yeux.",
			[213] = "Il stocke des Baies sous sa carapace. Elles fermentent et produisent des jus délicieux.",
			[214] = "Il arpente la forêt en quête de sève, son mets favori. Il est assez fort pour projeter l’ennemi.",
			[215] = "Il se nourrit d’œufs volés dans des nids. Ses griffes crochues percent les défenses de l’ennemi.",
			[216] = "Il baigne ses griffes dans le miel pour les lécher. Chaque paire de pattes a un goût unique.",
			[217] = "Il marque de ses griffes les arbres de son territoire qui portent des Baies ou des fruits.",
			[218] = "Son corps est fait de magma. S’il cesse de bouger, il refroidit et durcit.",
			[219] = "Sa température corporelle avoisine les 10 000 °C. Des flammes fusent des fissures de sa coquille.",
			[220] = "Il adore les champignons qui poussent sous l’herbe morte. Il trouve aussi des sources chaudes.",
			[221] = "Il ne voit rien à cause de sa fourrure touffue et se repère à l’aide de son nez délicat.",
			[222] = "On en trouve beaucoup dans les mers claires du sud. On dirait qu’il ne peut pas vivre en eau polluée.",
			[223] = "Il crache un puissant jet d’eau pour abattre les proies volantes.",
			[224] = "Il hante les fissures dans la roche et les trous au fond de la mer. Ses ventouses ne lâchent jamais prise.",
			[225] = "Il dépose sa nourriture dans sa queue enroulée. Il l’offre souvent aux gens égarés en montagne.",
			[226] = "Lorsque la mer est calme, il arrive de croiser un banc de DEMANTA nageant comme s’ils volaient.",
			[227] = "Son corps est prisonnier d’une armure dure comme l’acier, mais il vole à plus de 300 km/h.",
			[228] = "Il exprime ses émotions en modulant son cri. Ce Pokémon rusé chasse en meute pour abattre ses proies.",
			[229] = "Jadis, les gens prenaient son étrange hurlement pour l’appel de la Faucheuse.",
			[230] = "Chacun de ses déplacements provoque des tourbillons. Il vit dans les grottes sous-marines.",
			[231] = "Il est fort malgré son aspect ramassé. Il n’a aucun mal à porter un humain adulte sur son dos.",
			[232] = "Il attaque en se roulant en boule pour percuter l’ennemi. Il peut abattre une maison d’un seul coup.",
			[233] = "On lui a installé un logiciel de terraformation pour lui permettre de travailler dans l’espace.",
			[234] = "Quiconque observe ses antennes ressent une sensation étrange, comme si leur centre l’attirait.",
			[235] = "Il marque son territoire en maniant sa queue comme un pinceau. On dénombre plus de 5 000 marques.",
			[236] = "Il est réputé pour sa combativité. Il se blesse toujours en défiant des ennemis plus grands.",
			[237] = "Il combat en tournoyant comme une toupie. La force centrifuge décuple sa puissance destructrice.",
			[238] = "Il goûte à tout du bout des lèvres. Elles gardent en mémoire ses goûts et ses dégoûts.",
			[239] = "Il génère de l’électricité en battant des bras, mais il n’a aucun moyen de stocker cette énergie.",
			[240] = "Sa température corporelle avoisine les 600 °C. Son souffle est jaune quand il est en bonne santé.",
			[241] = "On raconte que les enfants élevés au lait d’ECREMEUH deviennent des adultes braves et robustes.",
			[242] = "Ce Pokémon au cœur d’or soigne les Pokémon malades. Il ressent la tristesse d’autrui.",
			[243] = "On prétend qu’il est tombé avec la foudre. Il peut lancer des éclairs grâce aux nuages sur son dos.",
			[244] = "On raconte qu’à chaque fois qu’il rugit, un volcan entre en éruption quelque part.",
			[245] = "Il parcourt le vaste monde pour purifier les eaux polluées. Il accompagne le vent du nord.",
			[246] = "Un Pokémon qui se nourrit de terre. Après avoir dévoré une montagne, il s’endort pour grandir.",
			[247] = "Son corps est dur comme la pierre souterraine. Il file comme une fusée en expulsant des gaz.",
			[248] = "Lorsqu’il est en colère, il abat des montagnes et enterre des fleuves. On doit alors modifier les cartes.",
			[249] = "Il dort dans une faille des grands fonds. Ses battements d’ailes génèrent une tempête de 40 jours.",
			[250] = "Ses plumes possèdent sept couleurs. On prétend que sa vue apporte la joie éternelle.",
			[251] = "Il a le pouvoir de voyager dans le temps. Cependant, on dit qu’il n’apparaît qu’en temps de paix.",
			[252] = "Ses plantes de pieds sont couvertes d’épines lui permettant de marcher au mur et au plafond.",
			[253] = "Il vit dans les jungles denses. Il saute de branche en branche pour approcher de sa proie.",
			[254] = "Les feuilles sur ses bras peuvent trancher des troncs épais. C’est le meilleur combattant des jungles.",
			[255] = "Ses câlins réchauffent car il renferme une fournaise. Il envoie des boules de feu à 1 000 °C.",
			[256] = "Ce maître du coup de pied peut donner 10 coups par seconde. Ses cris aigus intimident l’ennemi.",
			[257] = "Des flammes fusent de ses poignets et ses coups brûlent l’ennemi.",
			[258] = "Il analyse le courant grâce à la nageoire sur sa tête. Il est assez fort pour soulever des rochers.",
			[259] = "Ses jambes robustes lui donnent un bon appui, même dans la boue. Il dort enfoui dans la saleté.",
			[260] = "Il peut traîner un grand bateau en nageant. Il assomme l’ennemi d’un grand coup de ses bras épais.",
			[261] = "Un Pokémon très obstiné qui poursuit sa proie jusqu’à ce qu’elle soit épuisée.",
			[262] = "Il traque ses proies en groupe. Il ne désobéira jamais aux ordres d’un bon Dresseur.",
			[263] = "Il marche en zigzaguant et n’a pas son pareil pour trouver des objets dans l’herbe ou sous terre.",
			[264] = "Il fonce sur sa proie à plus de 100 km/h. Mais il ne peut pas dévier sa course et loupe souvent sa cible.",
			[265] = "Il adore manger des feuilles. Si un ETOURMI l’attaque, il riposte avec les piquants de son postérieur.",
			[266] = "Il s’accroche en enroulant sa soie autour des branches. Il reste immobile en attendant d’évoluer.",
			[267] = "Il est très agressif. Il pique sa proie avec son long museau étroit et absorbe sa vitalité.",
			[268] = "Il est au chaud dans son cocon. Ses cellules produisent l’énergie nécessaire à son évolution.",
			[269] = "Ce Pokémon nocturne est attiré par les lueurs de la ville et aime les feuilles des arbres urbains.",
			[270] = "Il ressemble à une plante aquatique et fait la navette pour les Pokémon qui ne savent pas nager.",
			[271] = "C’est un mauvais plaisantin. Quand il repère un pêcheur, il tire sur sa ligne pour le déranger.",
			[272] = "Ses muscles se tonifient au son d’une musique entraînante. Il ne peut pas s’empêcher de danser.",
			[273] = "Il ressemble à un gland pendu à une branche. Il adore effrayer les autres Pokémon.",
			[274] = "Le son de sa flûte d’herbe déstabilise l’auditeur. Il vit au plus profond des forêts.",
			[275] = "D’un coup de sa feuille éventail, il génère des bourrasques de 30 m/s capables de souffler une maison.",
			[276] = "Ce Pokémon téméraire n’a pas peur d’affronter des ennemis puissants. Il vole en quête de climats chauds.",
			[277] = "Il vole en cercle en quête d’une proie. Dès qu’il l’a repérée, il fond sur elle en un éclair.",
			[278] = "Il niche sur les falaises escarpées face à la mer. Il vole en altitude grâce aux courants ascendants.",
			[279] = "Il trempe son grand bec dans la mer pour charrier de l’eau et de nombreuses proies.",
			[280] = "Il perçoit les émotions humaines grâce aux cornes sur sa tête. On dit qu’il apprécie la joie de vivre.",
			[281] = "Il est très à l’écoute des émotions de son Dresseur. Il danse quand il est d’humeur joyeuse.",
			[282] = "Il donnera sa vie pour protéger un Dresseur dévoué. Il a la capacité de prédire l’avenir.",
			[283] = "Il semble patiner sur l’eau. Le parfum diffusé par le sommet de sa tête sert à attirer ses proies.",
			[284] = "Des motifs en forme d’yeux ornent ses antennes. Ses 4 ailes l’aident à voler dans toutes les directions.",
			[285] = "Le sommet de sa tête libère des spores empoisonnées. Il est dangereux de les inhaler.",
			[286] = "Ses petits bras s’étendent quand il donne un coup de poing. Son talent égale celui d’un boxeur pro.",
			[287] = "Il passe le plus clair de son temps affalé. Rien qu’à le voir, on a envie de bâiller.",
			[288] = "Son cœur bat dix fois plus vite que la normale, c’est pourquoi il ne tient pas en place.",
			[289] = "Le Pokémon le plus fainéant du monde. Il s’allonge pour économiser ses forces et contre-attaquer.",
			[290] = "Il grandit sous terre et se repère grâce à ses antennes car ses yeux sont quasiment aveugles.",
			[291] = "Il bouge si vite que l’œil a parfois du mal à le suivre. Ils se regrou- pent près de la sève des arbres.",
			[292] = "Une carapace d’insecte laissée à l’abandon. On dit qu’il vole l’âme de celui qui regarde à l’intérieur.",
			[293] = "En temps normal, son cri est pareil à un murmure. Effrayé, il atteint le volume d’un avion à réaction.",
			[294] = "L’onde de choc provoquée par son cri peut renverser un camion. Il trépigne pour augmenter sa force.",
			[295] = "Son hurlement s’entend à 10 km à la ronde. Ses orifices émettent toutes sortes de bruits.",
			[296] = "Il fortifie son corps en fonçant sur des arbres épais. Son nid est entouré d’arbres abattus.",
			[297] = "Il aime mesurer sa force à celle des plus grands Pokémon. Ses coups de paume peuvent projeter un camion.",
			[298] = "Un Pokémon qui vit près de l’eau. Au sol, il se déplace rapidement en rebondissant sur sa grosse queue.",
			[299] = "Son nez est un aimant, c’est pourquoi ce Pokémon fait toujours face au nord.",
			[300] = "Il poursuit tout ce qui bouge. On le voit parfois courir en cercle, chassant sa propre queue.",
			[301] = "Les femmes Dresseurs raffolent de sa sublime fourrure. Il ne possède pas de nid.",
			[302] = "A force de manger des gemmes, les yeux de ce Pokémon des grottes obscures sont devenus des joyaux.",
			[303] = "Ses cornes forment une grande mâchoire attachée à sa tête. Elle peut broyer des barres de fer.",
			[304] = "Il vit habituellement au cœur des montagnes. Affamé, il dévore parfois des rails et des voitures.",
			[305] = "Il se nourrit du minerai de fer qu’il fore. Il défend son territoire en chargeant avec son corps d’acier.",
			[306] = "Il creuse des galeries à travers la pierre avec ses cornes d’acier pour trouver le fer qu’il apprécie.",
			[307] = "Il ne mange qu’une Baie par jour. La faim lui a forgé une volonté de fer.",
			[308] = "Il a développé son sixième sens grâce au yoga. Ses mouvements sont gracieux.",
			[309] = "Il améliore ses réflexes en stimulant ses muscles grâce à l’électricité dans sa fourrure.",
			[310] = "Il libère l’électricité par sa crinière. Il crée un nuage d’orage pour appeler la foudre.",
			[311] = "Il absorbe l’énergie des poteaux électriques et encourage ses amis avec des pompons d’étincelles.",
			[312] = "Il encourage ses amis. Son corps produit plus d’étincelles quand il est en mauvaise posture.",
			[313] = "Il communique avec ses pairs en allumant son postérieur la nuit. Il adore le doux parfum de LUMIVOLE.",
			[314] = "Il utilise son doux parfum pour aider MUCIOLE à décrire des arabesques dans le ciel nocturne.",
			[315] = "Les ROSELIA élevés avec une eau claire et potable font de ravissantes fleurs bariolées.",
			[316] = "Il est principalement composé d’un estomac dont les sucs digestifs dissolvent tout ce qu’il avale.",
			[317] = "Il avale tout en une bouchée. Ses follicules sécrètent des fluides toxiques qui endorment l’ennemi.",
			[318] = "Il attaque en banc quand on menace son territoire. Ses dents aiguisées peuvent couler un navire.",
			[319] = "Ses crocs lacèrent des feuilles d’acier. Il nage à 120 km/h. On l’appelle “tyran des mers”.",
			[320] = "Par beau temps, il se pose sur les plages pour jouer et rebondir. Il expulse de l’eau par son évent.",
			[321] = "Le plus grand des Pokémon. Il peut plonger à une profondeur de 3 000 m en retenant son souffle.",
			[322] = "Son dos bossu renferme une lave bouillonnante. Elle refroidit par temps de pluie, ce qui le ralentit.",
			[323] = "Il porte des volcans sur son dos. Quand le magma remonte, il frissonne et entre en éruption.",
			[324] = "Il tire son énergie du charbon qu’il brûle dans sa carapace et crache de la suie noire en cas de danger.",
			[325] = "Il utilise sa queue comme un ressort et bondit partout. Chaque nouveau choc fait battre son cœur.",
			[326] = "Les perles noires amplifient ses pouvoirs psy. Sa danse étrange lui permet de contrôler ses ennemis.",
			[327] = "Les motifs sur leur fourrure sont propres à chaque SPINDA. Son pas chancelant le rend difficile à viser.",
			[328] = "Il creuse un trou conique dans le sable du désert et se terre en attendant qu’une proie trébuche.",
			[329] = "Ses violents battements d’ailes génèrent des vagues d’ultrasons qui donnent mal au crâne.",
			[330] = "Son puissant battement d’ailes provoque des tempêtes de sable. On l’appelle “esprit du désert”.",
			[331] = "En stockant l’eau dans son corps, cet habitant du désert peut survivre 30 jours sans boire.",
			[332] = "Il sort la nuit pour chasser. Il traque les proies épuisées après une journée dans le désert.",
			[333] = "Ses ailes sont comme des balles de coton. Perché sur la tête de quelqu’un, on dirait un chapeau.",
			[334] = "En vol, il ressemble à un nuage cotonneux. Il fredonne d’une voix de soprano.",
			[335] = "C’est le rival de SEVIPER depuis des générations. Ses griffes aiguisées sont son meilleur atout.",
			[336] = "Le rival historique de MANGRIFF. Il affûte la lame de sa queue sur les rochers avant le combat.",
			[337] = "On suppose qu’il est lié au cycle lunaire, car il ne sort que les soirs de pleine lune.",
			[338] = "Le bruit court que cette nouvelle espèce vient du soleil. Il produit de la lumière en tournoyant.",
			[339] = "Il enduit son corps d’une substance visqueuse pour glisser et se libérer quand on l’agrippe.",
			[340] = "Il est attaché à son territoire. Il repousse l’ennemi en provoquant des secousses qui portent à 5 km.",
			[341] = "Sa nature robuste lui permet de vivre sur n’importe quel terrain. Ses pinces ne lâchent jamais prise.",
			[342] = "C’est un voyou qui utilise ses pinces pour chasser les autres Pokémon hors de sa mare.",
			[343] = "Il se déplace en tournoyant sur son pied. Ce Pokémon rare fut découvert dans de vieilles ruines.",
			[344] = "Une ancienne figurine d’argile qui s’est animée suite à son exposition à un rayon de lumière étrange.",
			[345] = "Il vivait au fond de la mer il y a 100 millions d’années. La science a permis de le ressusciter.",
			[346] = "Vit dans les hauts-fonds des mers chaudes. Il déterre sa proie du sable quand la marée se retire.",
			[347] = "Un ancêtre Pokémon réanimé à partir d’un fossile. Il vivait en mer et chassait avec ses pinces.",
			[348] = "Il a gagné la côte après son évolution. Une armure robuste recouvre son corps.",
			[349] = "Il est connu pour son teint maladif. Bien que nombreux, ces Pokémon se regroupent aux mêmes endroits.",
			[350] = "On raconte qu’il surgit du fond des lacs pour calmer les esprits quand les gens se querellent.",
			[351] = "Son aspect change avec la météo. On a récemment découvert que ses molécules étaient pareilles à l’eau.",
			[352] = "Il change de couleur à volonté, mais le motif en zigzag qui orne son ventre reste le même.",
			[353] = "Il aime le goût de la vengeance. Ils vivent en rangs sous les gouttières des gens vindicatifs.",
			[354] = "Une poupée mue par la tristesse qui la ronge depuis qu’on l’a délaissée. Elle recherche son propriétaire.",
			[355] = "Il poursuit assidûment sa proie, où qu’elle aille. Il n’abandonne sa traque qu’au lever du soleil.",
			[356] = "Son corps est creux. On raconte que celui qui regarde à l’intérieur finira aspiré par le néant.",
			[357] = "A force de manger son fruit préféré, il a fini par pousser autour de son cou.",
			[358] = "Son langage comporte sept cris. Il les utilise pour faire vibrer l’air et projeter son ennemi.",
			[359] = "Il pressent les catastrophes et n’apparaît aux gens que pour les prévenir d’un danger imminent.",
			[360] = "Il se muscle en bousculant ses semblables lors de mêlées. Il raffole des fruits sucrés.",
			[361] = "Selon un vieux dicton des régions enneigées: “STALGAMIN dans la maison, richesse à l’horizon”.",
			[362] = "Il gèle l’humidité de l’air pour former une armure de glace protectrice autour de son corps.",
			[363] = "Il gagne la côte en roulant sur les blocs de glace car sa morphologie n’est pas adaptée à la nage.",
			[364] = "Il fait souvent tourner des objets sur son museau pour connaître leur odeur et leur texture.",
			[365] = "Il brise la glace avec ses grosses défenses. Sa graisse le protège du froid, mais aussi des attaques.",
			[366] = "Il ne produit qu’une perle durant son existence. On raconte qu’elle amplifie les pouvoirs psychiques.",
			[367] = "Il vit loin sous la mer. Il appâte les proies crédules avec sa queue qui rappelle un petit poisson.",
			[368] = "Au printemps, son corps rose se fait plus vif sans que l’on sache pourquoi. Il vit au fond de la mer.",
			[369] = "Un Pokémon rare aperçu lors d’une exploration sous-marine. Il n’a pas évolué depuis 100 millions d’années.",
			[370] = "Un habitant des mers chaudes. On dit que le couple qui tombe sur ce Pokémon connaîtra l’amour éternel.",
			[371] = "Il rêve de pouvoir voler un jour. Pour l’heure, il s’entraîne en sautant du haut des falaises.",
			[372] = "Ses cellules ont commencé à changer dans sa robuste coquille. Il la perd en évoluant.",
			[373] = "A force de rêver de pouvoir voler, sa structure cellulaire a évolué et il s’est vu pousser des ailes.",
			[374] = "Il dialogue avec les siens par impulsions magnétiques. En bande, ils se déplacent à l’unisson.",
			[375] = "Il est formé de deux TERHAL soudés. Son corps de fer résiste à un choc avec un avion à réaction.",
			[376] = "Il est né de la fusion de plusieurs METANG. Ses quatre cerveaux en font l’égal d’un superordinateur.",
			[377] = "Tout son corps est fait de roche. S’il s’ébrèche au combat, il utilise des pierres pour le réparer.",
			[378] = "Son corps est fait de glace datant de l’ère glaciaire. Il contrôle un air gelé de -200 °C.",
			[379] = "Son corps invulnérable fut forgé par la pression souterraine durant des dizaines de milliers d’années.",
			[380] = "Son corps est recouvert d’un duvet qui reflète la lumière et le rend invisible.",
			[381] = "Un Pokémon très intelligent. Il peut voler plus vite qu’un avion à réaction en repliant ses ailes.",
			[382] = "On dit qu’il a fait monter les eaux en causant des pluies diluviennes. Il somnolait dans une fosse marine.",
			[383] = "Il dormait dans le magma souterrain depuis sa lutte féroce contre KYOGRE, il y a longtemps de cela.",
			[384] = "Il vit dans la couche d’ozone, au dessus des nuages. Il est invisible depuis le sol.",
			[385] = "On raconte qu’une fois tous les mille ans, il a la capacité d’exaucer tous les vœux durant une semaine.",
			[386] = "Il vient d’un virus extraterrestre arrivé avec une météorite et ayant subi une mutation génétique.",
			[387] = "La coquille sur son dos est faite de terre. Elle durcit lorsqu’il s’abreuve. Il vit le long des lacs.",
			[388] = "Il vit en forêt près de l’eau. En journée, il la quitte pour dorer sa carapace feuillue au soleil.",
			[389] = "Il arrive que de petits Pokémon se rassemblent sur son dos immobile pour y faire leur nid.",
			[390] = "Il escalade prestement les falaises escarpées et vit sur les sommets. Sa flamme s’éteint quand il dort.",
			[391] = "Pour intimider ses agresseurs, il gonfle les flammes de sa queue pour paraître plus grand.",
			[392] = "Il pratique un art martial spécial qui utilise tous ses membres. Sa flamme ne s’éteint jamais.",
			[393] = "Il est fier et déteste accepter la nourriture qu’on lui offre. Son pelage épais le protège du froid.",
			[394] = "Il vit seul, à l’écart de ses pairs. Chaque individu est convaincu d’être meilleur que les autres.",
			[395] = "Les trois cornes de son bec sont le symbole de sa force. Celles du chef sont plus grosses que les autres.",
			[396] = "Ils volent en nombre. Bien que minuscule, il bat des ailes avec une vigueur impressionnante.",
			[397] = "Il survole les forêts et les champs en quête de Pokémon Insecte. Ils forment de grandes volées.",
			[398] = "Un Pokémon sauvage qui a le courage de défier des ennemis beaucoup plus grands que lui.",
			[399] = "Rien ne peut perturber ses nerfs d’acier. Il est plus agile et énergique qu’il n’y paraît.",
			[400] = "Il construit des barrages de boue et d’écorce le long des fleuves. C’est un ouvrier de renom.",
			[401] = "Quand il bascule sa tête d’avant en arrière, ses antennes se heurtent dans un son de xylophone.",
			[402] = "Il croise ses bras affûtés devant son torse pour crier. Il compose tout un tas de mélodies.",
			[403] = "Sa fourrure étincelle en cas de danger. Il profite du fait que l’ennemi est aveuglé pour s’enfuir.",
			[404] = "L’électricité libérée par ses griffes peut assommer l’ennemi. Il vit en petits groupes.",
			[405] = "Ses yeux voient à travers tout. Il repère les proies cachées derrière un objet pour les capturer.",
			[406] = "En hiver, son bourgeon se referme pour résister au froid. Il s’ouvre au printemps et libère du pollen.",
			[407] = "Il attire ses proies avec son doux parfum et les achève grâce aux fouets d’épines de ses bras.",
			[408] = "Il vivait dans la jungle il y a environ 100 millions d’années. Son crâne est dur comme du fer.",
			[409] = "Son violent coup de tête est assez puissant pour pulvériser les matériaux les plus résistants.",
			[410] = "Un Pokémon qui vivait dans la jungle il y a 100 millions d’années. Son visage est très dur.",
			[411] = "Il résiste à toute attaque frontale. C’est un Pokémon docile qui se nourrit d’herbe et de Baies.",
			[412] = "Pour se protéger des vents glacés de l’hiver, il s’est tissé une cape de feuilles et de brindilles.",
			[413] = "Quand CHENITI a évolué, sa cape a fusionné avec son corps. CHENISELLE ne s’en sépare jamais.",
			[414] = "Il aime le nectar des fleurs et n’hésite pas à voler celui que récupère APITRINI.",
			[415] = "Un Pokémon qui en regroupe trois autres. Il est toujours occupé à apporter du nectar à APIREINE.",
			[416] = "Son abdomen est un rayon où vivent ses larves, élevées avec le nectar récolté par APITRINI.",
			[417] = "Il roule des boules de poils pleines d’électricité statique et les range dans des souches avec des Baies.",
			[418] = "Sa bouée est pareille à un collier gonflable. Quand il flotte, il garde la tête à l’air libre.",
			[419] = "Il flotte grâce à sa bouée très développée. Il vole au secours des gens sur le point de se noyer.",
			[420] = "La petite boule renferme les délicieux nutriments sucrés dont il a besoin pour évoluer.",
			[421] = "Il fleurit lorsque le soleil est au beau fixe. Il cherche à prendre sa revanche sur une vie de bourgeon.",
			[422] = "Sa couleur et sa forme varient selon les régions. On en recense deux types à Sinnoh.",
			[423] = "Son corps pliable est dépourvu d’os. Lorsqu’on tranche un de ses membres, il repousse immédiatement.",
			[424] = "Il se nourrit de noix qu’il épluche avec ses deux queues habiles. Il utilise de moins en moins ses bras.",
			[425] = "Un Pokémon né de l’esprit des gens et des Pokémon. Il aime les saisons chaudes et humides.",
			[426] = "Il somnole la journée et s’envole en grands groupes le soir venu. Nul ne sait où ils vont.",
			[427] = "Il frappe l’ennemi en déroulant violemment ses oreilles. Cela peut faire pleurer un adulte.",
			[428] = "Un Pokémon extrêmement prudent. Il couvre son corps de ses oreilles pelucheuses en cas de danger.",
			[429] = "Son cri rappelle une incantation. Ceux qui l’entendent souffrent de migraines et d’hallucinations.",
			[430] = "Ce Pokémon nocturne évolue en grandes volées escortées par des CORNEBRE.",
			[431] = "Il griffe quand il est en colère et ronronne quand il est heureux. Certains aiment ce côté lunatique.",
			[432] = "Cette brute arrogante n’hésite pas à voler le nid d’autres Pokémon pour s’y installer.",
			[433] = "Il émet des cris en agitant l’orbe à l’arrière de sa gorge. Il avance par bonds désordonnés.",
			[434] = "Il se protège en expulsant un fluide nocif par son derrière. La puanteur dure 24 heures.",
			[435] = "Il attaque en projetant un liquide fétide du bout de sa queue. Il peut tirer à 50 mètres.",
			[436] = "Il rappelle des objets trouvés dans des sépultures anciennes. Nul ne sait s’ils sont liés.",
			[437] = "La découverte d’un de ces Pokémon sur un site de fouilles après 2 000 ans de sommeil a fait sensation.",
			[438] = "On dirait qu’il pleure constamment. En fait, il régule ses fluides corporels en éliminant le surplus.",
			[439] = "Il imite ses ennemis. Une fois imités, ils ne peuvent plus quitter ce Pokémon des yeux.",
			[440] = "Ce Pokémon aime ce qui est rond et blanc et transporte un caillou en forme d’œuf pour imiter LEVEINARD.",
			[441] = "On peut lui enseigner quelques mots. S’il s’agit d’un groupe, ils retiendront les mêmes phrases.",
			[442] = "Un Pokémon composé de 108 esprits. Il provient d’une fissure dans une clé de voûte étrange.",
			[443] = "Il niche dans les petits trous horizontaux des murs des grottes. Il bondit pour saisir sa proie.",
			[444] = "Selon une croyance ancienne, on peut utiliser ses écailles pour guérir les maladies incurables.",
			[445] = "Quand il se recroqueville et étend ses ailes, on dirait un chasseur. Sa vitesse est supersonique.",
			[446] = "Il avale son poids en nourriture chaque jour. Il avale tout sans prendre le temps de mâcher.",
			[447] = "Son aura s’intensifie pour prévenir son entourage quand il a peur ou qu’il est triste.",
			[448] = "Il ressent les auras de tout. Il comprend le langage humain.",
			[449] = "Il vit dans des endroits arides. Il exsude du sable granuleux au lieu de transpirer.",
			[450] = "Il emmagasine du sable qu’il expulse en tornades par les pores de sa peau pour attaquer.",
			[451] = "Il saisit sa proie avec les pinces de sa queue, lui injecte un poison et la retient jusqu’à ce qu’il agisse.",
			[452] = "Il peut réduire une voiture en pièces avec ses pinces. Le bout de ses pinces contient du poison.",
			[453] = "Ses joues contiennent des glandes toxiques. Il attaque par surprise et utilise son toucher empoisonné.",
			[454] = "Les griffes de ses poings sécrètent une toxine si atroce qu’une simple égratignure peut s’avérer fatale.",
			[455] = "Il attire sa proie avec sa salive odorante avant de la croquer. Il lui faut une journée pour l’avaler.",
			[456] = "Après une longue exposition au soleil, les motifs de ses nageoires caudales luisent à la nuit tombée.",
			[457] = "Il vit au plus profond de l’océan. Il attire sa proie en illuminant les motifs de ses 4 nageoires.",
			[458] = "Un Pokémon amical qui analyse les mouvements subtils de l’eau de mer grâce à ses deux antennes.",
			[459] = "Il vit sur les monts enneigés. Ignorant des coutumes humaines, il lui arrive d’être très indiscret.",
			[460] = "C’est l’abominable homme des neiges. Il ensevelit les montagnes sous ses blizzards.",
			[461] = "Ils vivent par groupe de 4 ou 5 en région froide et chassent de façon très organisée.",
			[462] = "Il a évolué suite à son exposition à un champ magnétique spécial. Ses 3 unités génèrent du magnétisme.",
			[463] = "Il enroule tout dans sa langue extensible. Ceux qui l’approchent finissent couverts de bave.",
			[464] = "Il bande ses muscles pour projeter des pierres ou des RACAILLOU depuis le creux de ses paumes.",
			[465] = "Il ligote sa proie en étirant ses bras en lianes. Il ne craint pas de perdre un bras face à un ennemi.",
			[466] = "Il place le bout de ses deux queues sur son ennemi et libère une décharge de 20 000 volts.",
			[467] = "Il projette des boules de feu de 2 000 °C à bout de bras. Il vit dans les cratères volcaniques.",
			[468] = "Il n’apparaît jamais en temps de conflit. Récemment, il se fait plus rare.",
			[469] = "Les ondes de choc qu’il génère en battant des ailes infligent de graves blessures internes.",
			[470] = "Il utilise la photosynthèse comme une plante. C’est pourquoi il est toujours entouré d’air pur.",
			[471] = "Il peut geler sa fourrure pour se protéger en rendant ses poils aussi durs que des piquants.",
			[472] = "Il guette sa proie, pendu à une branche la tête en bas, et s’en saisit à la première occasion.",
			[473] = "Ses défenses spectaculaires sont glacées. Il a failli disparaître dans la canicule suivant l’ère glaciaire.",
			[474] = "Un logiciel supplémentaire fut installé pour l’améliorer. Mais depuis, il se comporte bizarrement.",
			[475] = "Il frappe avec les grandes lames à ses coudes. Son talent d’escrimeur n’a d’égal que sa courtoisie.",
			[476] = "Son corps libère une puissante force magnétique. Il dirige trois petites unités appelées Mini-nez.",
			[477] = "L’antenne sur sa tête capte les ondes radio du monde des esprits lui ordonnant d’y porter des gens.",
			[478] = "MOMARTIK gèle ses ennemis grâce à son souffle à -50 °C. Ça ne se voit pas, mais son corps est creux.",
			[479] = "Son corps est fait de plasma. Il cause de gros dégâts en infiltrant des appareils électroniques.",
			[480] = "On l’appelle “être du savoir”. On raconte que son regard a le pouvoir d’effacer la mémoire.",
			[481] = "On l’appelle “être de l’émotion”. Il enseigne aux hommes la beauté de la tristesse, la douleur et la joie.",
			[482] = "On l’appelle “être de la volonté”. Il dort au fond d’un lac pour maintenir l’équilibre du monde.",
			[483] = "Il peut contrôler le temps. Les mythes de Sinnoh en parlent comme d’une divinité ancienne.",
			[484] = "Il peut modeler l’espace. Les mythes de Sinnoh en parlent comme d’une divinité ancienne.",
			[485] = "Il hante les grottes volcaniques. Il rampe au mur et au plafond grâce à ses pieds en forme de croix.",
			[486] = "Une légende tenace veut que ce Pokémon ait traîné les continents en les attachant à des cordes.",
			[487] = "Un Pokémon censé vivre dans un monde à l’opposé du nôtre. Il apparaît dans un cimetière ancien.",
			[488] = "Ses ailes libèrent un rideau de particules brillantes. Ce Pokémon symboliserait le croissant de lune.",
			[489] = "Un Pokémon des mers chaudes. Il gonfle la bouée sur sa tête et dérive en quête de vivres.",
			[490] = "Né dans les profondeurs froides de l’océan, il parcourt un long chemin pour gagner son lieu de naissance.",
			[491] = "Il a la capacité de bercer les gens pour les faire rêver. Il se montre durant les nuits de nouvelle lune.",
			[492] = "Il vit dans les champs de fleurs et se cache en s’enroulant pour imiter une plante fleurie.",
			[493] = "La mythologie le décrit comme le Pokémon qui a façonné l’univers avec ses 1 000 bras.",
		},
		[702] = { -- species_pokedex_entry_de
			[1] = "Nach der Geburt nimmt es für eine Weile Nährstoffe über den Samen auf seinem Rücken auf.",
			[2] = "Sobald die Knospe auf seinem Rücken ein süßes Aroma abgibt, steht die Blüte kurz bevor.",
			[3] = "Nach einem Regentag riecht die Blume auf seinem Rücken intensiver. Das Aroma zieht andere Pokémon an.",
			[4] = "Lodert die Flamme auf seiner Schweifspitze hell, ist GLUMANDA gesund.",
			[5] = "GLUTEXO leben in den Bergen. Die Flammen auf ihren Schweifspitzen leuchten in der Nacht wie Sterne.",
			[6] = "Man sagt, GLURAKs Feuer lodert stärker, wenn es harte Kämpfe überstanden hat.",
			[7] = "Es zieht sich in seinen Panzer zurück und greift dann mit Wasserstrahlen seine Gegner an.",
			[8] = "Man sagt, es werde 10 000 Jahre alt. Sein buschiger Schweif ist ein Symbol für langes Leben.",
			[9] = "Der Wasserstrahl, der aus den Wasserdüsen schießt, kann sogar Stahlwände durchdringen.",
			[10] = "Seine roten Antennen sondern einen Gestank ab, der Feinde verjagt. Es wächst, indem es sich häutet.",
			[11] = "Der stahlharte Panzer schützt seinen zarten Körper. Es wartet geduldig auf seine Entwicklung.",
			[12] = "Es liebt Blütenhonig. Es findet selbst Blumen, die sehr wenig Pollen haben.",
			[13] = "Es frisst täglich sein Gewicht in Blättern. Die Nadel auf seinem Kopf dient der Verteidigung.",
			[14] = "Während es auf seine Entwicklung wartet, versteckt es sich unter Blättern und zwischen Ästen.",
			[15] = "Sein bester Angriff: Schnell auf den Gegner zufliegen, mit Giftstacheln zustechen und davonfliegen.",
			[16] = "Reizt man dieses an sich gutmütige Pokémon, wehrt es sich wütend.",
			[17] = "Auf der Suche nach Nahrung, die es mit scharfen Krallen schlägt, fliegt es durch riesiges Territorium.",
			[18] = "Schlägt TAUBOSS mit ganzer Kraft seine Flügel, beugen sich selbst große Bäume durch den Windstoß.",
			[19] = "Es strotzt vor Lebenskraft und kann in jeder Umgebung leben. Es ist extrem vorsichtig.",
			[20] = "Es wetzt seine ständig wachsenden Zähne an harten Dingen. Es kann Wände aus Beton zernagen.",
			[21] = "Im Flug schlägt es eifrig mit den Flügeln. Mit seinem Schnabel sucht es im Gras nach Beute.",
			[22] = "Es hat genügend Ausdauer, den ganzen Tag zu fliegen. Sein scharfer Schnabel dient als Waffe.",
			[23] = "Es bewegt sich ohne einen Laut durch das Gras und greift seine ahnungslose Beute von hinten an.",
			[24] = "Das Muster auf seinem Bauch schüchtert Gegner ein. Sind sie vor Angst erstarrt, umklammert es sie.",
			[25] = "Es lebt zusammen mit anderen in Wäldern. In seinen Backen- taschen speichert es Elektrizität.",
			[26] = "Bei zu viel Elektrizität im Körper wird es aggressiv. Es entlädt sich über seinen Schweif.",
			[27] = "Es lebt in trockenen Regionen mit wenig Regen. Es rollt sich ein, um sich vor Gegnern zu schützen.",
			[28] = "Es rollt sich zusammen und rollt dann auf Gegner zu, die durch seine Stacheln Schaden nehmen.",
			[29] = "Es mag keine Kämpfe. Ein einziger Tropfen des Gifts aus seinen Widerhaken hat eine fatale Wirkung.",
			[30] = "Bei Gefahr fährt es die Wider- haken am Körper aus. Diese wachsen langsamer als die von NIDORINO.",
			[31] = "Sein ganzer Körper ist mit harten Schuppen bedeckt. Es beschützt sein Junges mit seinem Leben.",
			[32] = "Es untersucht die Umgebung, indem es die Ohren spitzt und lauscht. Sein giftiges Horn schützt es.",
			[33] = "Es ist aggressiv und greift seine Gegner mit dem Horn an, welches bei Berührung Gift absondert.",
			[34] = "Ein Schlag mit seinem gewaltigen Schweif kann einen Telegrafen- masten knicken wie ein Streichholz.",
			[35] = "Es ist bekannt für sein liebens- wertes Wesen. Man sagt, es lebt in der Stille der Berge.",
			[36] = "Man bekommt es selten zu sehen. Bei Vollmond soll es an den Ufern einsam gelegener Seen spielen.",
			[37] = "Es beherrscht Feuerbälle. Während es wächst, teilen sich seine sechs Schweife, um weitere zu bilden.",
			[38] = "Seine neun Schweife sollen mystische Kräfte besitzen. Es kann tausend Jahre leben.",
			[39] = "Sobald es mit seinen großen, runden Augen rollt, fängt es an, ein Lied zu singen und jeder schläft ein.",
			[40] = "Sein feines Fell fühlt sich herrlich an. Es kann sich größer machen, indem es Luft einatmet.",
			[41] = "Obwohl es keine Augen hat, kann es Hindernisse mithilfe von Ultraschallwellen wahrnehmen.",
			[42] = "Es liebt das Blut von Menschen und Pokémon. Nachts fliegt es umher auf der Suche nach Halsvenen.",
			[43] = "Tagsüber verankert es sich mit seinen Wurzelfüßen im Boden. Nachts wandert es und verteilt Samen.",
			[44] = "Der Honig, den es abgibt, riecht so entsetzlich, dass sich sogar Nasen in 2 km Entfernung rümpfen.",
			[45] = "Es besitzt die größten Blätter der Welt. Es verteilt beim Gehen Pollen, die schreckliche Allergien auslösen.",
			[46] = "Auf seinem Rücken wachsen Pilze, die Tochukaso. Sie nehmen an Größe zu, wenn PARAS wächst.",
			[47] = "PARASEK wird von einem Pilz, der größer als das Pokémon ist, kontrolliert. Er gibt Giftsporen ab.",
			[48] = "Seine großen Augen bestehen aus vielen kleinen Augen. Nachts wird es von Licht angezogen.",
			[49] = "Es schlägt mit den Flügeln, um staubartige Schuppen abzusondern. Diese geben bei Kontakt Gift ab.",
			[50] = "Dieses Pokémon lebt unterirdisch. Da es an Dunkelheit gewöhnt ist, schreckt helles Licht es ab.",
			[51] = "Die drei Köpfe bewegen sich abwech- selnd, um sich durch harte Erde in Tiefen von bis zu 100 km zu graben.",
			[52] = "Ein nachtaktives Pokémon. Sieht es etwas Schimmerndes, fangen seine Augen an zu glänzen.",
			[53] = "Ein sehr stolzes Pokémon. Für Fans ist die Größe des Juwels auf seiner Stirn Anlass für Diskussionen.",
			[54] = "Werden seine konstant vorhandenen Kopfschmerzen stärker, entwickelt es seltsame Kräfte.",
			[55] = "Dieses Pokémon lebt in Seen. Es schwimmt schneller als der schnellste menschliche Schwimmer.",
			[56] = "Es lebt mit anderen in Baumkronen. Wird eines von ihnen wütend, werden alle anderen auch wütend.",
			[57] = "Siehst du ihm in die Augen, wird es wütend. Rennst du weg, wird es noch wütender. Ärgerst du es...",
			[58] = "Ein loyales Pokémon. Es wird erst dann aktiv, wenn sein Trainer ihm Anweisungen gegeben hat.",
			[59] = "Mit seiner stolzen und königlichen Erscheinung gewinnt es die Herzen der Menschen.",
			[60] = "Seine Haut ist so dünn, dass man die inneren Organe sehen kann. Es hat Schwierigkeiten beim Laufen.",
			[61] = "Das Spiralmuster auf seinem Bauch dreht sich langsam. Starrt man darauf, wird einem schwindelig.",
			[62] = "Es hat extrem starke Muskeln und kann durch den Ozean schwimmen, ohne sich ausruhen zu müssen.",
			[63] = "18 Stunden am Tag schläft es. Und wenn es wach ist, teleportiert es sich, während es sitzen bleibt.",
			[64] = "Wenn sich auf deinem Fernsehbild- schirm ein Schatten zeigt, ist es in der Nähe. Und das bringt Unglück.",
			[65] = "Es besitzt ein fantastisches Ge- dächtnis und erinnert sich an alles seit seiner Geburt. IQ: Über 5 000.",
			[66] = "Es hebt GEOROK hoch, um seinen Körper zu trainieren. Außerdem übt es sich in jeder Art v. Kampfsport.",
			[67] = "MASCHOCKs unbegrenzte Kraft ist gefährlich, daher trägt es einen Gürtel, der die Kraft unterdrückt.",
			[68] = "Mit seinen vier Armen schlägt es blitzschnell zu. Es kann in zwei Sekunden 1 000-mal zuschlagen.",
			[69] = "Es bevorzugt heiße und feuchte Umgebungen. Seine Beute fängt es blitzschnell mit seinen Ranken.",
			[70] = "Ein Pokémon, das wie eine Pflanze aussieht. Es fängt Beute, indem es giftigen Puder darüber verteilt.",
			[71] = "In seinem Maul sammelt sich eine Flüssigkeit, die nach Honig riecht, in Wahrheit aber ätzend ist.",
			[72] = "Sein Körper besteht aus Wasser. Aus seinen kristallartigen Augen verschießt es eigenartige Strahlen.",
			[73] = "Es besitzt 80 Tentakel, um Beute zu fangen und festzuhalten. Diese wird durch Gift geschwächt.",
			[74] = "Viele von ihnen leben auf Bergpfaden, halb vergraben und Bergsteiger beobachtend.",
			[75] = "GEOROK leben an steilen Felsvorsprüngen. Sie graben dazu viele Löcher aus.",
			[76] = "Einmal im Jahr wechselt es seine Haut. Seinem Körper kann selbst Dynamit nichts anhaben.",
			[77] = "Bereits eine Stunde nach seiner Geburt wachsen seine feurige Mähne und sein feuriger Schweif.",
			[78] = "Seine Mähne lodert auf, wenn es mit 240 km/h pfeilschnell galoppiert.",
			[79] = "Es ist langsam, hat aber ein Talent, mit seinem Schweif zu fischen. Beißt etwas an, tut es ihm nicht weh.",
			[80] = "Ein begriffsstutziges Pokémon. Beißt das MUSCHAS am Schweif zu, scheint es Intelligenz zu gewinnen.",
			[81] = "Die Vorrichtungen an seinem Körper generieren elektromagnetische Wellen, die es schweben lassen.",
			[82] = "Eigentlich sind es drei MAGNETILO, die durch Magnetismus verbunden sind.",
			[83] = "Ohne seinen Stock kann es nicht leben. Daher beschützt es den Stock mit seinem Leben.",
			[84] = "Die Gehirne der beiden Köpfe kommunizieren ihre Gefühle über Telepathie.",
			[85] = "Entwickelt sich DODU, teilt sich einer der Köpfe in zwei. Es kann sich mit 60 km/h fortbewegen.",
			[86] = "Dieses Pokémon lebt auf Eisbergen. Es schwimmt im Eiswasser und bricht das Eis mithilfe seines Horns.",
			[87] = "Sein Körper ist mit einem weißen Fell bedeckt, das es im Schnee fast unsichtbar für Gegner macht.",
			[88] = "Es wurde geboren, als Schlamm von den Strahlen des Mondes getroffen wurde. Es erscheint, wo Unrat ist.",
			[89] = "Sein Körper sondert eine giftige Substanz ab, die bei Kontakt Pflanzen und Bäume vernichtet.",
			[90] = "Es schwimmt rückwärts, indem es seine Schale öffnet und schließt. Es zeigt immer seine breite Zunge.",
			[91] = "Im Kampf schließt es seine Schale, um sich zu schützen. Es schießt mit Stacheln auf seine Gegner.",
			[92] = "Der Körper des Pokémon besteht zu 95 % aus Gasen, die fortgeweht werden, wenn starker Wind geht.",
			[93] = "Es kann sich durch jedes Hindernis bewegen. Es versteckt sich in Wänden, um Gegner zu beobachten.",
			[94] = "Es versteckt sich im Schatten. Man sagt, wenn sich ein GENGAR ver- steckt, kühlt es sich um 5 Grad ab.",
			[95] = "Wenn es sich unter dem Boden mit bis zu 80 km/h bewegt, verursacht es Erschütterungen.",
			[96] = "Mit seiner großen Nase kann es die Träume anderer erkennen. Es liebt lustige Träume.",
			[97] = "Ein Blick auf das Pendel versetzt einen in 3 Sekunden in Schlaf, selbst wenn man gar nicht müde ist.",
			[98] = "Es lebt in Höhlen am Strand. Seine Scheren wachsen nach, wenn es sie im Kampf verliert.",
			[99] = "Die großen Scheren haben eine Stärke von 10 000 PS. Aber sie sind schwer und kaum zu handhaben.",
			[100] = "Sieht aus wie ein Pokéball. Es ist gefährlich, da es bei Berührung explodieren kann.",
			[101] = "Es lässt sich vom Wind treiben, wenn es so voller Elektrizität ist, dass es fast explodiert.",
			[102] = "Die sechs Eier kommunizieren telepathisch. Werden sie getrennt, finden sie sich schnell wieder.",
			[103] = "Man nennt es den “Laufenden Dschungel”. Wird ein Kopf zu groß, fällt er ab und wird zu einem OWEI.",
			[104] = "Denkt es an seine verstorbene Mutter, weint es, wobei der Schädel auf seinem Kopf hohl klingt.",
			[105] = "Von Geburt an trägt dieses wilde Pokémon Knochen. Es setzt sie talentiert als Waffen ein.",
			[106] = "Seine Beine können die doppelte Länge annehmen. Gegner, die das nicht wissen, erschrecken.",
			[107] = "Die Schläge, die es austeilt, können Beton pulverisieren. Es muss sich im Kampf alle 3 Minuten ausruhen.",
			[108] = "Statt Händen verwendet es seine Zunge, die zweimal so groß wie sein Körper und klebrig ist.",
			[109] = "Gase, die leichter als Luft sind, lassen es schweben. Diese Gase stinken und sind explosiv.",
			[110] = "Es wächst, indem es Gase aufnimmt, die aus dem Müll aufsteigen. Selten kann man Drillinge von ihnen finden.",
			[111] = "Sein Körper ist von einer dicken Haut umgeben und es kann wackelige Gebäude zum Einsturz bringen.",
			[112] = "Sein Gehirn entwickelt sich, wenn es sich auf die Hinterbeine stellt. Mit dem Horn bohrt es durch Gestein.",
			[113] = "Man sagt, es bringe Glück. Es ist sehr mitfühlend und teilt seine Eier mit Verletzten.",
			[114] = "Es ist von blauen Ranken umgeben. Niemand hat jemals das Gesicht dieses Pokémon gesehen.",
			[115] = "Sein Nachwuchs wächst in seinem Beutel heran. Nur wenn es sicher ist, darf das Junge aus dem Beutel.",
			[116] = "Im Schatten von Korallen legt es sein Nest an. Bei Gefahr versprüht es Tinte und flieht.",
			[117] = "Seine Stacheln schützen es. Seine Flossen und Knochen werden bei der Herstellung von Medizin verwendet.",
			[118] = "Es schwimmt elegant und bewegt seine Hinterflosse wie ein Kleid. Es sieht aus wie eine Königin.",
			[119] = "Es baut Nester, indem es Steine im Fluss mit seinem Horn aushöhlt. Es verteidigt seine Eier mit dem Leben.",
			[120] = "Wird sein Körper verletzt, kann es sich regenerieren, sofern der rote Kern intakt ist.",
			[121] = "In der Körpermitte befindet sich ein roter Kern, der mysteriöse Radiowellen in die Nacht sendet.",
			[122] = "Ein Experte der Pantomime. Es kann unsichtbare, aber solide Wände allein durch Gesten erzeugen.",
			[123] = "Es ist fast unmöglich, seinen Sensen auszuweichen, da es mit der Schnelligkeit eines Ninja zuschlägt.",
			[124] = "Sein Ruf klingt wie menschliche Sprache. Trotzdem ist nicht zu verstehen, was es sagt.",
			[125] = "Die Hälfte aller Stromausfälle wird durch dieses PKMN ausgelöst, das in E-Werken Elektrizität frisst.",
			[126] = "Es wurde bei einem Vulkanausbruch geboren. Sein Körper ist von hellen Flammen umgeben.",
			[127] = "Es hält seine Beute mit seiner Zange fest und teilt sie dann. Was es nicht teilen kann, wirft es fort.",
			[128] = "Sobald es einen Gegner ins Visier genommen hat, rennt es mit dem Kopf voran auf ihn zu.",
			[129] = "Man sagt, es sei das schwächste PKMN der Welt. Niemand weiß, wie es bisher überleben konnte.",
			[130] = "Sobald es erscheint, nimmt seine Wut nicht eher ab, bis es die Felder und Berge ringsum zerstört hat.",
			[131] = "Es liebt es, das Meer mit PKMN und Menschen auf dem Rücken zu über- queren. Es versteht die Menschen.",
			[132] = "Es kann seine Zellstruktur so verändern, dass es sich in alles verwandeln kann, was es sieht.",
			[133] = "Ein seltenes PKMN, das sich seiner Umgebung anpasst, indem es sich in unterschiedlicher Form entwickelt.",
			[134] = "Es hat sich so entwickelt, dass es im Wasser leben kann. Im Wasser selbst wird es unsichtbar.",
			[135] = "Es kontrolliert 10 000 Volt. Es kann sein Fell so aufstellen, dass es wie scharfe Nadeln wirkt.",
			[136] = "In seinem Körper befindet sich eine Flamme. Seine Körpertemperatur liegt vor dem Kampf bei 900 Grad.",
			[137] = "Das erste künstlich erzeugte PKMN der Welt. Es kann durch elektronischen Raum reisen.",
			[138] = "Dieses PKMN wurde von der modernen Wissenschaft aus einem Fossil ge- schaffen. Es lebte im urzeitl. Meer.",
			[139] = "Man geht davon aus, dass das PKMN ausgestorben ist, weil seine spiral- förmige Schale zu groß wurde.",
			[140] = "Man geht davon aus, dass dieses PKMN vor 300 Millionen Jahren die Strände bevölkerte.",
			[141] = "Man geht davon aus, dass dieses PKMN an Land kam, weil seine Beute ebenfalls irgendwann an Land lebte.",
			[142] = "Dieses PKMN flog zu Zeiten der Dinosaurier am Himmel. Seine Zähne sind wie Sägeblätter.",
			[143] = "Sein Magen kann jede Art von Nahrung verdauen, selbst wenn sie verschimmelt und verdorben ist.",
			[144] = "Ein Legendäres Vogel-Pokémon. Es kann Blizzards verursachen, indem es Feuchtigkeit gefriert.",
			[145] = "Ein Legendäres Vogel-Pokémon, das in Gewitterwolken leben soll. Es kontrolliert Blitze.",
			[146] = "Eines der Legendären Vogel- Pokémon. Es wird als Bote des Frühlings angesehen.",
			[147] = "Man nennt es “Illusion-Pokémon”, denn nur wenige haben es gesehen. Nur seine Haut wurde oft gefunden.",
			[148] = "Erscheint um seinen Körper eine Aura, gibt es einen Wetterwechsel. Es soll in Seen und Meeren leben.",
			[149] = "Man sagt, es lebe in den Meeren. Es bringt Schiffbrüchige sicher an Land.",
			[150] = "Die Gene von MEW wurden neu angeordnet, wodurch dieses PKMN entstand. Es hat ein wildes Herz.",
			[151] = "Es beherrscht alle möglichen Attacken, daher sieht man in ihm den Vorfahren aller Pokémon.",
			[152] = "Mit dem Blatt auf seinem Kopf bestimmt es die Temperatur und Feuchtigkeit. Es liebt Sonnenbäder.",
			[153] = "Die Knospen an seinem Hals geben ein würziges Aroma ab, das andere aufheitert.",
			[154] = "Mit seinem Atem kann es tote Pflanzen und Blumen zu neuem Leben erwecken.",
			[155] = "Erschrickt sich dieses scheue PKMN, lodern die Flammen auf seinem Rücken kräftiger.",
			[156] = "Es bedroht seine Gegner mit der Hitze seiner Flammen. Ist es kampfbereit, lodern sie stärker.",
			[157] = "Es greift seine Gegner mit Feuer an. Dabei entsteht ein Hitze- flimmern, in dem es sich versteckt.",
			[158] = "Es hat die Angewohnheit, nach allem zu schnappen, was es sieht. Selbst seine Trainer müssen aufpassen.",
			[159] = "Hat es einmal zugebissen, lässt es erst los, wenn es seine Zähne verliert, die schnell nachwachsen.",
			[160] = "Eigentlich bewegt es sich langsam, doch seine Beute greift es blitzschnell an.",
			[161] = "Ein sehr nervöses PKMN. Es steht auf seinem Schweif und betrachtet seine Umgebung ganz genau.",
			[162] = "Es rollt sich um seine Jungen, wenn diese schlafen sollen. Gegnern begegnet es mit Schnelligkeit.",
			[163] = "Es steht ständig auf einem Fuß. Selbst wenn es angreift, stellt es sich nicht auf beide Beine.",
			[164] = "Seine Augen sind etwas Besonderes. Sie können selbst bei schwächstem Licht alles erkennen.",
			[165] = "Es ist so scheu, dass es sich nur dann bewegt, wenn es sich in einem Schwarm befindet.",
			[166] = "Es zieht Energie aus dem Licht der Sterne. Je mehr Sterne zu sehen sind, desto größer ist sein Muster.",
			[167] = "Es baut eine Falle, indem es ein Netz mit dünner, starker Seide spinnt. Es wartet still auf Beute.",
			[168] = "Es befestigt Seide an der Beute und lässt sie frei. Es folgt dem Seiden- faden zur Beute u. ihren Freunden.",
			[169] = "Seine vier Flügel erlauben es dem PKMN, schneller und leiser zu fliegen. Es ist nachtaktiv.",
			[170] = "Über seine Antennen entlädt es Elektrizität, mit der es seinen Gegnern einen Schlag versetzt.",
			[171] = "LANTURNs Licht kann aus großen Tiefen heraufscheinen. Man nennt es auch “Tiefseestern”.",
			[172] = "Seine Backentaschen sind noch recht klein. Daher kann es nicht allzu viel Elektrizität speichern.",
			[173] = "Seine Silhouette sieht aus wie ein Stern. Man sagt, es würde auf Sternschnuppen reisen.",
			[174] = "Es hat einen weichen, elastischen Körper. Hat es einmal angefangen zu hüpfen, ist es nicht zu stoppen.",
			[175] = "Seine Schale ist mit Glücksgefühlen gefüllt, die es mit gutherzigen Lebewesen teilt.",
			[176] = "Man sagt, es erscheint vor denen, die gutherzig sind, und verteilt glänzenden “Glücksstaub”.",
			[177] = "Es pickt seine Nahrung aus Kakteen, wobei es Knospen und Dornen verschont.",
			[178] = "Dieses PKMN kann die Vergangenheit und die Zukunft sehen. Es beobachtet ständig die Sonne.",
			[179] = "Sein weiches Fell wird doppelt so dick, wenn sich Elektrizität aufbaut.",
			[180] = "Hat es sich mit Elektrizität aufge- laden, leuchtet sein Schweif und es feuert Haare ab, die sich entladen.",
			[181] = "Seine Schweifspitze leuchtet hell. In alten Zeiten hat man mit seiner Hilfe Lichtsignale gegeben.",
			[182] = "Sobald die Regenzeit vorbei ist, wird es von der warmen Sonne nach draußen gezogen, wo es tanzt.",
			[183] = "Seinen Schweif verwendet es als eine Art Rettungsring, wenn es taucht. Es liebt Wasserpflanzen.",
			[184] = "Es lebt in Flüssen und Seen. Im Wasser verwirrt es seine Gegner durch seine Farbe und Muster.",
			[185] = "Auch wenn es wie ein Baum aussieht, ist es eher wie ein Stein o. Fels. Es ist schwach gegenüber Wasser.",
			[186] = "Es versammelt andere PKMN um sich herum und führt sie an. QUAPSEL gehorchen seinem Ruf.",
			[187] = "Es reitet auf dem Wind. Man sagt, wenn sich HOPPSPROSS ver- sammeln, kommt der Frühling bald.",
			[188] = "Sobald es wärmer wird, blüht es auf. Es schwebt am Himmel und nimmt so viel Sonnenlicht auf wie möglich.",
			[189] = "Es lässt sich von den Winden um den Globus tragen und verteilt auf seinem Flug Baumwollsamen.",
			[190] = "Mit dem Schweif pflückt es hochhän- gende Früchte. Mit ihm ist es geschickter als mit den Händen.",
			[191] = "Morgens fällt es plötzlich aus dem Himmel. War der Sommer kalt, explodiert seine Population.",
			[192] = "Warmes Sonnenlicht gibt ihm Energie. Daher wandert es stets dem Sonnenlicht hinterher.",
			[193] = "Mit seinen Augen hat es einen Blick- winkel von 360 Grad. Es sieht sogar Beute, die sich hinter ihm befindet.",
			[194] = "Es lebt im kalten Wasser. Es vergräbt sich halb im schlammigen Boden, wenn es schlafen will.",
			[195] = "Ein träges PKMN, das auf dem Grund des Flusses liegt und wartet, dass ihm Beute ins Maul schwimmt.",
			[196] = "Sein Fell ist wie Samt. Setzt es Psycho-Kräfte ein, leuchtet die Kugel in seiner Stirn.",
			[197] = "Mondlicht hat die genetische Struktur von EVOLI verändert. Im Dunkeln wartet es auf Beute.",
			[198] = "Sieht man dieses PKMN bei Nacht, sollen merkwürdige Dinge passieren.",
			[199] = "Wird es von MUSCHAS gebissen, wird es so intelligent, dass es sich mit Nobelpreisträgern messen kann.",
			[200] = "Es liebt es, sich nachts an andere heranzuschleichen und sie mit einem schrillen Schrei zu erschrecken.",
			[201] = "Seine Form sieht aus wie antike Schrift. Was war zuerst da? Die Sprache oder ICOGNITO?",
			[202] = "Verzweifelt versucht es, seinen schwarzen Schweif zu verstecken. Er soll ein Geheimnis enthalten.",
			[203] = "Sein Schweif besitzt ebenfalls ein Gehirn. Er beißt jeden Gegner, der sich von hinten heranschleicht.",
			[204] = "Es sieht aus wie ein Tannenzapfen. Seine Schale schützt es vor Vogel- Pokémon, die an ihm picken wollen.",
			[205] = "Dieses PKMN ist von einer Stahlhülle umgeben. Seine stechenden Augen sind alles, was man von ihm sieht.",
			[206] = "Es gräbt sich mit seinem Schweif in die Erde und baut ein labyrinth- artiges Nest. Es kann kaum fliegen.",
			[207] = "Es segelt durch die Lüfte und breitet seine Gliedmaßen aus, um aus der Luft anzugreifen.",
			[208] = "Hoher Druck und hohe Temperaturen haben seinen Körper härter als Stahl werden lassen.",
			[209] = "Kleine PKMN fliehen beim Anblick seines Gesichts. Frauen aber finden es niedlich.",
			[210] = "Es ist trotz seines Äußeren schüchtern. Wird es wütend, schnappt es mit seinen Fängen zu.",
			[211] = "Es verschießt die giftigen Stacheln seines Körpers in alle Richtungen. Es ist kein guter Schwimmer.",
			[212] = "Sein Körper ist stahlhart. Es bedroht seine Gegner, indem es die Augen auf seinen Scheren zeigt.",
			[213] = "In seiner Schale bewahrt es Beeren auf. Diese fermentieren zu einem leckeren Saft.",
			[214] = "Auf der Suche nach Baumsaft durch- streift es die Wälder. Es ist stark genug, um Gegner wegzuschleudern.",
			[215] = "Es ernährt sich von Eiern, die es aus Nestern stiehlt. Beute greift es mit seinen scharfen Krallen an.",
			[216] = "Es lässt Honig in seine Pranken eindringen, so dass es immer welchen dabeihat.",
			[217] = "Es durchstreift sein Revier und markiert Bäume, die Früchte oder Beeren tragen, mit Kratzern.",
			[218] = "Sein Körper besteht aus Magma. Bleibt es nicht ständig in Bewegung, kühlt es aus und verhärtet sich.",
			[219] = "Seine Körpertemperatur beträgt etwa 10 000 Grad. Aus seiner Schale treten immer wieder Flammen aus.",
			[220] = "Es liebt Pilze, die unter totem Gras wachsen. Auf der Suche nach Nahrung findet es heiße Quellen.",
			[221] = "Sein dichtes Fell verdeckt seine Augen. Es untersucht seine Umgebung mit seiner Nase.",
			[222] = "Viele von ihnen leben in den sauberen Seen im Süden. In ver- schmutzten können sie nicht leben.",
			[223] = "Es spritzt Wasser mit Hochdruck aus seinem Maul und schießt damit auf fliegende Beute.",
			[224] = "Es lebt in Gesteinsritzen und Löchern auf dem Meeresboden. Mit Saugnäpfen hält es Beute fest.",
			[225] = "Im eingerollten Schweif transpor- tiert es Futter, das es mit denen teilt, die sich verlaufen haben.",
			[226] = "Wenn das Meer ruhig ist, kann man vielleicht einen Schwarm MANTAX sehen, die schnell vorbeischwimmen.",
			[227] = "Es wird komplett von einer eisen- harten Rüstung geschützt. Wenn es fliegt, erreicht es bis zu 300 km/h.",
			[228] = "Durch unterschiedliche Schreie drückt es seine Gefühle aus. Diese PKMN jagen im Verbund nach Beute.",
			[229] = "In alten Zeiten glaubte man, das Heulen dieses PKMN sei der Ruf des Todes.",
			[230] = "Es lebt in Höhlen auf dem Meeres- grund. Jedes Mal, wenn es sich bewegt, entsteht ein Strudel.",
			[231] = "Trotz seiner geringen Größe ist es stark. Es kann einen Erwachsenen mühelos auf dem Rücken tragen.",
			[232] = "Wenn es angreift, rollt es sich zusammen und auf den Gegner zu. Es kann Häuser zum Einsturz bringen.",
			[233] = "Interstellare Software wurde installiert, so dass dieses PKMN sich auch im All bewegen kann.",
			[234] = "Starrt man auf sein Geweih, bekommt man das seltsame Gefühl, in dessen Mitte gezogen zu werden.",
			[235] = "Sein Revier markiert es mit seinem pinselartigen Schweif. Es kennt mehr als 5 000 Markierungen.",
			[236] = "Es ist bekannt für seine Kampfbe- gierde. Es erholt sich ständig von Verletzungen.",
			[237] = "Es kämpft, während es sich wie ein Kreisel dreht. Die Zentrifugalkraft erhöht die Kampfkraft um 10.",
			[238] = "Dieses PKMN berührt alles mit den Lippen. Diese merken sich, was es mag und nicht mag.",
			[239] = "Es bewegt seine Arme und generiert damit Elektrizität. Diese kann es aber nicht speichern.",
			[240] = "Seine Körpertemperatur liegt bei etwa 600 Grad. Ist es gesund, atmet es gelbe Flammen aus.",
			[241] = "Man sagt, dass Kinder, die MILTANKs Milch trinken, zu gesunden Erwachsenen heranwachsen.",
			[242] = "Dieses gutherzige PKMN pflegt kranke PKMN gesund. Es spürt die Traurigkeit anderer Lebewesen.",
			[243] = "Dieses PKMN ist der personifizierte Blitz. Es kann aus den Wolken über seinem Rücken Blitze schleudern.",
			[244] = "Man sagt, wenn es brüllt, bricht irgendwo in der Welt ein Vulkan aus.",
			[245] = "Es wandert beständig in der Welt herum, um verunreinigtes Wasser zu reinigen. Es zieht mit dem Nordwind.",
			[246] = "Dieses PKMN frisst das Erdreich. Hat es einen Berg verspeist, schläft es ein, um zu wachsen.",
			[247] = "Sein Körper ist hart wie Fels. Es lässt mit Hochdruck Gas ab, um wie eine Rakete nach oben zu schießen.",
			[248] = "Bei einem Tobsuchtsanfall zerstört es ganze Gebirge und legt Flüsse trocken.",
			[249] = "Es schläft in einem Tiefseegraben. Schwingt es seine Flügel, entsteht ein Sturm, der 40 Tage dauert.",
			[250] = "Seine Federn besitzen 7 Farben. Man sagt, dass demjenigen, der es sieht, ewiges Glück beschieden ist.",
			[251] = "Es kann durch die Zeit reisen, aber es erscheint nur zu friedlichen Zeiten.",
			[252] = "Seine Fußsohlen sind mit kleinen Stacheln bedeckt, so dass es an Wänden und Decken Halt findet.",
			[253] = "Es lebt im dichten Dschungel. Es springt von Ast zu Ast, wenn es sich einer Beute nähert.",
			[254] = "Die Blätter an seinen Armen können dicke Bäume fällen. Im Dschungel- kampf gibt es kein stärkeres PKMN.",
			[255] = "In seinem Inneren lodert ein Feuer. Es schleudert 1 000 Grad heiße Feuerbälle.",
			[256] = "Es kann 10 Tritte pro Sekunde aus- teilen. Es gibt schrille Schreie von sich, um Gegner einzuschüchtern.",
			[257] = "Aus seinen Handgelenken kommt Feuer, das seine Knöchel umhüllt. Schläge verbrennen den Gegner.",
			[258] = "Die Flosse auf seinem Kopf prüft die Strömung des Wassers. Dieses PKMN kann Felsen heben.",
			[259] = "Seine kräftigen Beine geben ihm sicheren Halt. Es gräbt sich in Dreck ein, wenn es schlafen will.",
			[260] = "Es kann im Schwimmen ein großes Schiff ziehen. Seine Gegner schlägt es mit Schlägen seiner Arme zurück.",
			[261] = "Ein beharrliches PKMN, das seine Beute jagt, bis diese erschöpft ist.",
			[262] = "Es jagt seine Beute im Rudel. Den Befehlen eines erfahrenen Trainers wird es stets folgen.",
			[263] = "Es läuft im Zickzack. Es hat das Talent, Items im Gras, aber auch im Boden, zu finden.",
			[264] = "Es stürzt sich mit 100 km/h auf Beute. Aber es kann nur geradeaus laufen und die Jagd misslingt oft.",
			[265] = "Es isst am liebsten Blätter. Wird es von einem STARALILI angegriffen, verteidigt es sich mit Stacheln.",
			[266] = "Es bindet sich mit Seidenfäden an Ästen fest und wartet so starr auf seine Entwicklung.",
			[267] = "Es besitzt ein aggressives Wesen. Es sticht seinen Rüssel in seine Beute und saugt sie aus.",
			[268] = "In seinem Kokon ist es heiß. Seine Körperzellen produzieren die Hitze, damit es sich entwickeln kann.",
			[269] = "Nachtaktives PKMN, das vom Licht der Stadt angezogen wird und dort die Blätter der Bäume frisst.",
			[270] = "Es sieht aus wie eine Wasser- pflanze. Es dient den PKMN, die nicht schwimmen können, als Fähre.",
			[271] = "Es hat ein spitzbübisches Wesen. Sieht es einen Angler, zieht es an der Angelschnur, um ihn zu ärgern.",
			[272] = "Hört es fröhliche Musik, füllen sich seine Muskeln mit Energie. Es muss dann einfach tanzen.",
			[273] = "Es sieht aus wie eine Eichel, die am Baum hängt. Es liebt es, andere PKMN zu erschrecken.",
			[274] = "Der Ton seiner Grasflöte beunruhigt die, die ihn hören. Es lebt tief in den Wäldern.",
			[275] = "Seine großen Fächer erzeugen Böen, die eine Geschwindigkeit von 30 m/sek erreichen können.",
			[276] = "Es ist sehr mutig und stellt sich auch starken Gegnern. Es sucht ständig nach warmen Regionen.",
			[277] = "Es fliegt auf der Suche nach Beute ständig umher. Findet es Beute, stürzt es sich im Sturzflug auf sie.",
			[278] = "Es baut sein Nest auf steilen Klippen. Es nutzt die Aufwinde, um in größerer Höhe fliegen zu können.",
			[279] = "Es taucht seinen großen Schnabel ins Wasser und fängt so eine Menge Beute.",
			[280] = "Mit dem Horn kann es menschliche Gefühle wahrnehmen. Es erscheint fröhlichen Menschen.",
			[281] = "Es nimmt die Gefühle seines Trainers deutlich wahr. Wenn es glücklich ist, tanzt es.",
			[282] = "Es wird seinen Trainer mit dem Leben beschützen, wenn es ihm vertraut. Es kann in die Zukunft blicken.",
			[283] = "Scheinbar reitet es auf dem Wasser. Es lockt seine Beute mit einem süßen Duft an.",
			[284] = "Seine Antenne besitzt ein Augen- muster. Seine vier Flügel erlauben es, in alle Richtungen zu fliegen.",
			[285] = "Es setzt an seinem Kopf Giftsporen frei. Werden diese eingeatmet, verursachen sie Schmerzen.",
			[286] = "Seine kurzen Arme dehnen sich aus, wenn es zuschlägt. Seine Technik ähnelt der von Profi-Boxern.",
			[287] = "Es verbringt fast den ganzen Tag mit Faulenzen und Schlafen. Selbst sein Anblick macht bereits müde.",
			[288] = "Sein Herz schlägt schneller als das anderer Lebewesen. Daher kann es nicht für einen Moment still sitzen.",
			[289] = "Das faulste PKMN der Welt. Wenn es faulenzt, sammelt es in Wahrheit Energie, um zuzuschlagen.",
			[290] = "Es wächst unterirdisch heran und nimmt seine Umgebung mit Antennen wahr, da es nahezu blind ist.",
			[291] = "Es bewegt sich so schnell, dass es manchmal unsichtbar zu sein scheint. Es liebt Baumsaft.",
			[292] = "Ein weggeworfener Käferpanzer, der zum Leben erwachte. Schaut man hinein, stiehlt es einem die Seele.",
			[293] = "Normalerweise klingen seine Rufe wie Gemurmel. Hat es aber Angst, ist es so laut wie ein Flugzeug.",
			[294] = "Die Schockwellen, die durch sein Rufen entstehen, können einen LKW umkippen.",
			[295] = "Sein Heulen hört man in 10 km Entfernung. Es gibt alle Arten von Geräuschen von sich.",
			[296] = "Es stärkt seinen Körper, indem es gegen Bäume rennt. In seiner Nähe finden sich viele umgekippte Bäume.",
			[297] = "Es liebt das Kräftemessen mit großen PKMN. Mit seinem Armwurf kann es LKW durch die Luft werfen.",
			[298] = "Dieses PKMN lebt am Wasser. An Land bewegt es sich schnell, indem es auf seinem großen Schweif hüpft.",
			[299] = "Seine Nase ist ein Magnet. Daher sieht das PKMN immer nach Norden.",
			[300] = "Es muss Dinge, die sich bewegen, einfach jagen. Es rennt oft im Kreis und jagt seinen eigenen Schweif.",
			[301] = "Dieses PKMN ist bei weiblichen Trainern aufgrund seines Fells beliebt.",
			[302] = "Es versteckt sich im Dunkeln von Höhlen. Seine Augen sind Edelsteine.",
			[303] = "Auf seinem Kopf befindet sich ein riesiger Kiefer, der aus Hörnern besteht. Er kann Eisen zermalmen.",
			[304] = "Normalerweise lebt es in dunklen Bergen. Ist es hungrig, frisst es auch Eisenbahnschienen und Autos.",
			[305] = "Es ernährt sich von Eisenerz. Um sein Revier zu sichern, setzt es seinen harten Körper ein.",
			[306] = "Auf der Suche nach Eisen, seiner Nahrung, gräbt es mit seinen Stahl- hörnern sogar Tunnel durch Felsen.",
			[307] = "Es isst gerade mal eine Beere am Tag. Durch Hunger wird sein Geist ruhiger und schärfer.",
			[308] = "Mit Yoga-Training hat es seinen 6. Sinn geschärft. Seine Bewegungen sind sehr elegant.",
			[309] = "Die Elektrizität, die es im Fell speichert, nutzt es, um seine Muskeln zu stimulieren.",
			[310] = "Aus seiner Mähne entlädt es Elekt- rizität. Es generiert eine Gewitter- wolke, aus der es Blitze entlädt.",
			[311] = "Es feuert Freunde mit Pompons an, die aus Funken bestehen. Es holt sich Energie aus Telegrafenmasten.",
			[312] = "Es feuert Freunde an. Sind diese im Begriff zu verlieren, gibt sein Körper immer mehr Funken ab.",
			[313] = "Es kommuniziert mit anderen, indem es sein Hinterteil zum Leuchten bringt. Es liebt ILLUMISEs Duft.",
			[314] = "Sein süßer Duft leitet VOLBEAT an, Zeichen aus Licht an den Nachthimmel zu malen.",
			[315] = "ROSELIA, die mit klarem Wasser aufgezogen wurden, bekommen Blüten in leuchtenden Farben.",
			[316] = "Sein Körper besteht fast nur aus Magen. Seine starken Verdauungs- säfte zersetzen alles sehr schnell.",
			[317] = "Es verschluckt alles in einem Stück und sondert giftige Stoffe ab, mit denen es Gegner besprüht.",
			[318] = "Sie begegnen jedem Gegner, der in ihr Revier eindringt, im Schwarm. Ihre Zähne durchdringen alles.",
			[319] = "Seine Zähne durchdringen sogar Eisen. Es schwimmt mit 120 km/h und wird “Tyrann des Meeres” genannt.",
			[320] = "An sonnigen Tagen trifft man diese Pokémon an Stränden, wo sie wie Bälle herumhüpfen.",
			[321] = "Das größte PKMN. Es kann mit nur einem Atemzug in Tiefen bis 3 000 Meter tauchen.",
			[322] = "In seinem Rücken speichert es sehr heißes Magma. Regnet es, kühlt das Magma ab und es wird langsamer.",
			[323] = "Auf seinem Rücken befinden sich Vulkane. Magma bildet sich in seinem Körper, die irgendwann ausbricht.",
			[324] = "In seinem Panzer verbrennt es Kohle und gewinnt daraus Energie. Bei Gefahr sondert es Ruß ab.",
			[325] = "Es hüpft beständig umher, wobei es seinen Schweif als Feder verwendet. Nur so bleibt sein Herz aktiv.",
			[326] = "Mit schwarzen Perlen verstärkt es seine Psycho-Kräfte. Mit einem Tanz kontrolliert es seine Gegner.",
			[327] = "Das Muster eines PANDIR ist wie ein Fingerabdruck. Sein Taumeln senkt die gegn. Zielsicherheit.",
			[328] = "Es baut im Wüstensand eine Fallgrube, setzt sich in ihr auf den Boden und wartet auf Beute.",
			[329] = "Es schlägt wild mit den Flügeln. So entstehen Ultraschallwellen, die Kopfschmerzen verursachen.",
			[330] = "Mit mächtigem Flügelschlag verur- sacht es einen Sandsturm. Es wird “Geist der Wüste” genannt.",
			[331] = "Dieser Wüstenbewohner speichert Wasser in seinem Körper. So kann er 30 Tage ohne Wasser überleben.",
			[332] = "Ein nachtaktives PKMN, das Beute sucht, die durch die Tageshitze der Wüste bereits erschöpft ist.",
			[333] = "Seine Flügel sehen aus wie Baum- wolle. Legt es sie jemandem auf den Kopf, sehen sie wie ein Wollhut aus.",
			[334] = "Im Flug sieht es aus wie eine watteweiche Wolke. Es singt mit einer Sopranstimme.",
			[335] = "Seit Generationen ist es mit VIPITIS verfeindet. Seine scharfen Klauen sind seine stärksten Waffen.",
			[336] = "Seit Generationen ist es mit SENGO verfeindet. Es wetzt seinen scharfen Schweif an Felsen.",
			[337] = "Da es in Vollmondnächten aktiv wird, sagt man ihm nach, mit den Mond- phasen in Verbindung zu stehen.",
			[338] = "Eine neue PKMN-Spezies, von der man annimmt, sie käme von der Sonne. Sie strahlt Licht ab.",
			[339] = "Es bedeckt seinen Körper mit einer schleimigen Substanz und kann sich so aus Umklammerungen winden.",
			[340] = "Es verteidigt sein Revier, indem es Erschütterungen auslöst, die noch in 5 km Entfernung zu spüren sind.",
			[341] = "Ein robustes PKMN, das sich jeder Umgebung anpassen kann. Seine Zangen geben keine Beute frei.",
			[342] = "Dieser Grobian ergreift andere PKMN mit seinen Scheren und wirft sie aus seinem Teich.",
			[343] = "Es bewegt sich, indem es sich auf seinem Fuß dreht. Ein seltenes PKMN, das in alten Ruinen lebte.",
			[344] = "Eine antike Lehmstatue, die durch ein mysteriöses Licht zum Leben erwacht ist.",
			[345] = "Vor 100 Millionen Jahren lebte dieses PKMN auf dem Meeresgrund. Die Wissenschaft belebte es neu.",
			[346] = "Es lebt in seichten Stellen warmer Meere. Bei Ebbe sucht es im Sand nach Beute.",
			[347] = "Ein Vorfahre der PKMN, der aus einem Fossil neu belebt wurde. Es lebte im Meer und jagte mit Klauen.",
			[348] = "Nach seiner Entwicklung ging es an Land. Sein Körper ist von einer robusten Rüstung umgeben.",
			[349] = "Seine lumpige Gestalt ist berühmt. Es lebt mit anderen in Gruppen an bestimmten Orten.",
			[350] = "Wenn sich jemand streitet, steigt es aus den Tiefen des Sees empor, um die Streitenden zu beruhigen.",
			[351] = "Seine Gestalt ändert sich mit dem Wetter. Vor kurzem entdeckte man, dass seine Moleküle wie Wasser sind.",
			[352] = "Es kann nach Belieben seine Farbe ändern. Nur das gezackte Muster auf seinem Bauch bleibt gleich.",
			[353] = "Es liebt Rachegefühle. Diese PKMN hängen sich an Dachrinnen von Häu- sern, in denen Rachsüchtige leben.",
			[354] = "Dieses PKMN war eine Puppe, die weggeworfen wurde. Es sucht nun das Kind, das dies getan hat.",
			[355] = "Verbissen verfolgt es seine Beute überallhin. Doch sobald die Sonne aufgeht, ist die Jagd vorbei.",
			[356] = "Sein Körper ist hohl. Man sagt, dass diejenigen, die in den Körper blicken, hineingezogen werden.",
			[357] = "Da es ausschließlich seine Lieb- lingsfrucht frisst, begann diese, um seinen Hals herumzuwachsen.",
			[358] = "Um die Gegner fortzuwehen, setzt es die Luft mit Schreien in Bewegung.",
			[359] = "Es spürt drohende Katastrophen und erscheint nur dann, wenn es andere vor der Gefahr warnen will.",
			[360] = "Es wird stärker, indem es andere ständig anrempelt. Es liebt Süßigkeiten.",
			[361] = "Im Land des Schnees sagt eine Legende, dass in ein Haus Wohl- stand einzieht, wenn es darin lebt.",
			[362] = "Um sich zu schützen, umgibt es seinen Körper mit einer Rüstung aus Eis.",
			[363] = "Es rollt über Eisschollen, um Land zu erreichen, da sein Körper zum Schwimmen nicht geeignet ist.",
			[364] = "Es balanciert Dinge auf seiner Nase. Dabei lernt es etwas über die Beschaffenheit und den Geruch.",
			[365] = "Mit seinen Stoßzähnen bricht es durch Eis. Eine Speckschicht schützt es vor Kälte und Angriffen.",
			[366] = "In seinem Leben erschafft es eine einzige Perle. Diese soll Psycho- Kräfte verstärken.",
			[367] = "Es lebt tief im Meer. Sein Schweif ist wie ein kleiner Fisch geformt. Mit ihm lockt es Beute an.",
			[368] = "Es lebt auf dem Grund des Meeres. Im Frühling wirkt die Farbe seines Körpers viel kräftiger.",
			[369] = "Tiefseeforscher fanden dieses seltene PKMN, das sich in 100 Mio. Jahren nicht verändert hat.",
			[370] = "Es lebt in warmen Meeren. Man sagt, dass Verliebte, die es sehen, mit ewiger Liebe gesegnet sind.",
			[371] = "Es träumt davon, eines Tages fliegen zu können und springt daher jeden Tag von hohen Klippen.",
			[372] = "Die Zellen seines Panzers fingen an, sich zu verändern. Er fällt ab, sobald sich das PKMN entwickelt.",
			[373] = "Seine Zellstruktur änderte sich, es wuchsen ihm Flügel, da es immer davon träumte, fliegen zu können.",
			[374] = "Es kommuniziert mit anderen durch magnetische Impulse. Im Schwarm bilden sie eine perfekte Einheit.",
			[375] = "Das PKMN besteht aus zwei TANHEL. Es bekommt selbst dann keinen Kratzer, wenn ein Jet es streift.",
			[376] = "Mehrere METANG bilden dieses PKMN. Mit seinen 4 Gehirnen besitzt es die Intelligenz eines Supercomputers.",
			[377] = "Sein Körper besteht aus Stein. Bricht im Kampf etwas heraus, wird es durch Stein wieder ersetzt.",
			[378] = "Sein Körper besteht aus Eis aus der Eiszeit. Es kontrolliert gefrorene Luft, die minus 200 Grad kalt ist.",
			[379] = "Im Laufe der Jahrtausende, die es unterirdisch lebte, wurde sein Körper durch Druck u. Wärme hart.",
			[380] = "Sein Körper ist mit Daunen bedeckt, die das Licht so brechen, dass das PKMN unsichtbar wird.",
			[381] = "Ein hochintelligentes PKMN. Wenn es im Flug seine Flügel nach hinten legt, ist es schneller als ein Jet.",
			[382] = "Man sagt, es habe die Meere ver- größert, indem es es regnen ließ. Es schlief in einem Meeresgraben.",
			[383] = "Es hat seit dem Kampf gegen KYOGRE in Magma unter dem Erdboden geschlafen.",
			[384] = "Es lebt in der Ozonschicht hoch über den Wolken und kann vom Boden aus nicht gesehen werden.",
			[385] = "Man sagt, es kann alle tausend Jahre für eine Woche jeden Wunsch erfüllen.",
			[386] = "Ein außerirdischer Virus kam mit einem Meteor auf die Erde. Seine DNA mutierte. So entstand DEOXYS.",
			[387] = "Es besteht aus Erdreich. Trinkt es Wasser, verhärtet sich der Panzer auf seinem Rücken. Es lebt an Seen.",
			[388] = "Es lebt in der Nähe von Wasser in Wäldern. Tagsüber verlässt es diese, um ein Sonnenbad zu nehmen.",
			[389] = "Kleine PKMN fangen manchmal an, auf dem bewegungslosen Rücken Nester zu bauen.",
			[390] = "Es klettert behände steile Felsen hinauf, um auf Bergen zu leben. Sein Feuer ist aus, wenn es schläft.",
			[391] = "Um Angreifer abzuschrecken, verstärkt es das Feuer auf seinem Schweif, wodurch es größer wirkt.",
			[392] = "Es kämpft auf besondere Art, indem es alle Gliedmaßen einsetzt. Sein Feuer erlischt nie.",
			[393] = "Es ist sehr stolz und nimmt daher kein Futter von anderen an. Seine dicken Daunen schützen vor Kälte.",
			[394] = "Es lebt allein, entfernt von anderen. Jedes von ihnen denkt, es sei das bedeutendste unter ihnen.",
			[395] = "Die 3 Hörner, die aus dem Schnabel wachsen, stehen für Kraft. Ein Anführer hat die größten Hörner.",
			[396] = "Ihr Schwarm ist stets groß. Obwohl es kleine PKMN sind, schwingen sie ihre Flügel mit enormer Kraft.",
			[397] = "Auf der Suche nach Käfer-PKMN fliegt es über Wiesen und Wälder. Es bleibt in einem großen Schwarm.",
			[398] = "Es hat ein wildes Wesen. Mutig fordert es immer wieder Gegner heraus, die viel größer sind.",
			[399] = "Es hat Nerven wie Drahtseile, nichts kann es erschüttern. Es ist agiler und aktiver, als es scheint.",
			[400] = "Es baut sein Nest, indem es in Flüssen Dämme aus Schlamm und Ästen baut. Ein fleißiger Arbeiter.",
			[401] = "Es schüttelt seinen Kopf, so dass die beiden Antennen sich berühren und wie ein Xylophon klingen.",
			[402] = "Wenn es ruft, verschränkt es seine messerartigen Arme vor der Brust. Es komponiert aus dem Stegreif.",
			[403] = "In Gefahr blendet es seinen Gegner mit seinem Fell und flieht, während der Gegner einen Moment blind ist.",
			[404] = "Seine Krallen geben Elektrizität ab, die stark genug ist, jemanden bewusstlos zu machen.",
			[405] = "Mit seinen Augen kann es durch alles hindurch sehen. So findet es auch Beute, die sich versteckt hat.",
			[406] = "Im Winter schließt es die Knospe. Im Frühjahr öffnet es die Knospe und gibt Pollen ab.",
			[407] = "Mit einem süßen Duft lockt es Beute an, die es dann mit den dornigen Ranken in seinen Armen schlägt.",
			[408] = "Vor über 100 Millionen Jahren lebte es in den Dschungeln. Sein Schädel ist hart wie Eisen.",
			[409] = "Sein kräftiger Kopfstoß hat genug Kraft, um selbst die stabilsten Dinge zu zerschmettern.",
			[410] = "Vor über 100 Millionen Jahren lebte es in den Dschungeln. Seine Gesichtshaut ist extrem hart.",
			[411] = "Jeder Frontalangriff wird abge- schmettert. Dieses friedliche PKMN ernährt sich von Gras und Beeren.",
			[412] = "Um sich vor dem eisigen Winterwind zu schützen, legt es sich unter einen Umhang aus Ästen und Laub.",
			[413] = "Als sich BURMY entwickelte, wurde sein Umhang Teil des Körpers. Es legt den Umhang niemals ab.",
			[414] = "Es liebt Honig und stiehlt den Honig, der von WADRIBIE gesammelt wurde.",
			[415] = "Ein PKMN, geformt aus 3 einzelnen PKMN. Fleißig bringt es Blütenhonig zu HONWEISEL.",
			[416] = "Ihr Bauch ist die Wabe für die Larven. Sie füttert ihre Larven mit dem Honig, den WADRIBIE sammelt.",
			[417] = "Es bildet ein Fellknäuel, der vor statischer Energie knistert. Es speichert die Energie in Bäumen.",
			[418] = "Es hat eine Art Rettungsring um den Hals. Wenn es schwimmt, gerät sein Kopf niemals unter Wasser.",
			[419] = "Es treibt mithilfe einer Art Rettungsring auf dem Wasser und hilft dem, der zu ertrinken droht.",
			[420] = "Das kleine Bällchen enthält alles, was es für die Entwicklung braucht. Es ist süß und lecker.",
			[421] = "In Zeiten mit viel Sonnenschein blüht es auf. Es holt nach, was ihm als Knospe verwehrt blieb.",
			[422] = "Sein Aussehen ist von Region zu Region unterschiedlich. In Sinnoh finden sich zwei Arten.",
			[423] = "Es hat einen biegsamen Körper ohne einen Knochen. Wird ein Körperteil abgetrennt, wächst er nach.",
			[424] = "Wenn es hungrig ist, knackt es Nüsse mit seinen beiden Schweifen. Nur selten verwendet es die Arme.",
			[425] = "Ein PKMN, entstanden aus den Gefühlen von Menschen und PKMN. Es mag feuchte Jahreszeiten.",
			[426] = "Tagsüber treibt es faul vor sich hin, nachts fliegt es mit anderen umher. Niemand weiß wohin.",
			[427] = "Es entrollt seine Ohren sehr schnell, um seine Gegner schmerzhaft zu schlagen.",
			[428] = "Ein sehr vorsichtiges PKMN. Nimmt es Gefahr wahr, schützt es seinen Körper mit seinen weichen Ohren.",
			[429] = "Seine Rufe klingen wie Beschwö- rungen. Die, die sie hören, kriegen Kopfschmerzen und Halluzinationen.",
			[430] = "Ein nachtaktives PKMN, das sich in Schwärmen mit KRAMURX durch die Nacht bewegt.",
			[431] = "Es schlägt mit Krallen zu oder schnurrt, je nachdem, ob es gerade wütend oder zutraulich ist.",
			[432] = "Dieses PKMN ist ein Grobian, der sich in die Nester anderer PKMN ein- nistet und sie sich damit aneignet.",
			[433] = "Es ruft, indem es eine Kugel in seiner Kehle bewegt. Es bewegt sich mit eiligen Hopsern fort.",
			[434] = "Um sich zu schützen, versprüht es eine Substanz aus seinem Hinterleib, die 24 Stunden stinkt.",
			[435] = "Über seine Schweifspitze versprüht es eine übelriechende Substanz. Die Reichweite liegt bei über 50 Metern.",
			[436] = "Sein Körper sieht aus, als seien Teile davon in alten Gräbern gefunden worden.",
			[437] = "Dieses PKMN fand man bei Grabungen auf einer Baustelle, an deren Ort es 2 000 Jahre geschlafen hatte.",
			[438] = "Es sieht aus, als würde es immer weinen. Dabei reguliert es nur seinen Wasserhaushalt.",
			[439] = "Es ahmt seinen Gegner nach. Der kann den Blick danach nicht von ihm abwenden.",
			[440] = "Es liebt runde, weiße Dinge. Es trägt einen eiförmigen Stein bei sich, und imitiert damit CHANEIRA.",
			[441] = "Es kann die menschliche Sprache lernen. Versammeln sie sich, bringen sie sich alle dasselbe bei.",
			[442] = "Ein PKMN, das aus 108 Geistern besteht. Es ist an einen Spalt in einem mysteriösen Stein gebunden.",
			[443] = "Es nistet in kleinen Löchern in Höhlenwänden. Es springt Beute, die sich zu nah heranwagt, an.",
			[444] = "Es gibt einen uralten Glauben, dass Medizin, die aus seinen Schuppen gewonnen wird, alles heilen kann.",
			[445] = "Spannt es seinen Körper und seine Flügel, sieht es aus wie ein Jet. Es fliegt mit Schallgeschwindigkeit.",
			[446] = "Einmal am Tag verschlingt es eine Nahrungsmenge, die seinem Gewicht entspricht. Und das ohne zu kauen.",
			[447] = "Die Aura, die dieses PKMN umgibt, verstärkt sich, wenn es zeigen will, dass es ängstlich oder traurig ist.",
			[448] = "Es besitzt die Fähigkeit, die Aura aller Dinge zu spüren. Es versteht die menschliche Sprache.",
			[449] = "Es lebt in ausgetrockneten Gebieten. Statt zu schwitzen, sondert sein Körper Sand ab.",
			[450] = "Es wirbelt im Körper gespeicherten Sand durch Öffnungen und generiert so einen Sandwirbelsturm.",
			[451] = "Es greift seine Beute mit den Krallen an seinem Schweif und ver- giftet sie. Dann wartet es ab...",
			[452] = "In seinen Armen steckt so viel Kraft, dass es mit seinen giftigen Krallen Autos zerquetschen kann.",
			[453] = "In seinen Backen sammelt sich Gift. Es versucht, Beute zu überraschen und mit Giftfingern zu schnappen.",
			[454] = "Die Gelenke an seinen Klauen geben ein so starkes Gift ab, dass selbst ein kleiner Kratzer fatal ist.",
			[455] = "Sein süßlich riechender Speichel zieht Beute an, die es frisst. Es braucht einen Tag, sie zu fressen.",
			[456] = "Wurden die Flossen lange dem Sonnenlicht ausgesetzt, leuchten sie in der Dunkelheit.",
			[457] = "Es lebt tief auf dem Meeresboden. Das blinkende Muster auf seinen vier Rückenflossen zieht Beute an.",
			[458] = "Ein freundliches PKMN, das mit seinen zwei Antennen die Strömungen des Meeres erkennt.",
			[459] = "Es lebt im Schnee der Berge. Es hatte bisher kaum Kontakt zu Men- schen und ist daher sehr neugierig.",
			[460] = "Es löst in den Bergen, wo ewiger Schnee liegt, Blizzards aus. Es ist ein scheußlicher Schneemann.",
			[461] = "Es lebt in kalten Gebieten in Gruppen von 4 oder 5 PKMN, die bei der Jagd großes Geschick zeigen.",
			[462] = "Es entwickelte sich, als es einem besonderen Magnetfeld ausgesetzt wurde.",
			[463] = "Es umklammert Dinge mit seiner dehnbaren Zunge. Kommt man ihm zu nahe, wird man eingespeichelt.",
			[464] = "Es legt Steine in die Löcher seiner Hände und wirft sie mit Muskelkraft. Auch KLEINSTEIN werden verwendet.",
			[465] = "Es umwickelt Beute, indem es seine Arme, die aus Ranken bestehen, verlängert.",
			[466] = "Es berührt den Gegner mit seinen beiden Schweifspitzen und entlädt dann über 20 000 Volt.",
			[467] = "Aus den Enden seiner Arme schießen Feuerbälle mit 2 000 Grad. Es lebt in Vulkankratern.",
			[468] = "Es zeigt sich niemals dort, wo es Streitigkeiten gibt. In letzter Zeit wurde es nur selten gesehen.",
			[469] = "Durch die Bewegung seiner Flügel entstehen Schockwellen, die dem Gegn. innere Verletzungen zufügen.",
			[470] = "Genau wie ein Pflanze führt es die Photosynthese aus. Deshalb ist es ständig von reiner Luft umgeben.",
			[471] = "Will es sich schützen, kann es sein Fell gefrieren, so dass jedes Haar wie eine Nadel absteht.",
			[472] = "Es hängt kopfüber von einem Ast und beobachtet seine Beute. Bei Gelegenheit stürzt es sich auf sie.",
			[473] = "Die beeindruckenden Stoßzähne dieser PKMN sind aus Eis. Nach der Eiszeit nahm ihre Population ab.",
			[474] = "Zusätzliche Software wurde instal- liert, um das PKMN zu verbessern. Seitdem benimmt es sich seltsam.",
			[475] = "Es kämpft, indem es die Schwerter an seinen Ellbogen verlängert. Es ist ein Meister des Kampfes.",
			[476] = "Es gibt starken Magnetismus ab. Es steuert drei kleine Einheiten, die sich Mininasen nennen.",
			[477] = "Die Antenne auf seinem Kopf empfängt Radiowellen aus einer anderen Dimension.",
			[478] = "Sein eisiger Atem mit minus 50 Grad friert Gegner ein. Was aussieht wie sein Körper, ist tatsächlich hohl.",
			[479] = "Sein Körper besteht aus Plasma. Mit ihm kann es in elektrische Geräte eindringen und für Chaos sorgen.",
			[480] = "“Das wissende Wesen”. Es soll die Erinnerungen derer löschen, die ihm in die Augen sehen.",
			[481] = "“Das fühlende Wesen”. Es lehrt die Menschen die Ideale von Trauer, Schmerz und Freude.",
			[482] = "“Das starke Wesen”. Es schläft auf dem Grund eines Sees und hält so die Welt in Balance.",
			[483] = "Es besitzt die Macht, die Zeit zu kontrollieren. In den Mythen von Sinnoh erscheint es als Gottheit.",
			[484] = "Es hat die Macht, den Raum zu krümmen. In den Mythen von Sinnoh erscheint es als Gottheit.",
			[485] = "Es lebt in vulkanischen Höhlen. Mit seinen kreuzförmigen Klauen kann es sogar an der Decke laufen.",
			[486] = "Es gibt eine Legende, wonach dieses PKMN die Kontinente mit einem Seil gezogen hat.",
			[487] = "Ein PKMN, von dem man sagt, es lebt in der Spiegelwelt unserer Welt. Es erscheint auf alten Friedhöfen.",
			[488] = "Seine Flügel geben schimmernde Partikel ab, wie einen Schleier. Man sagt, es steht für die Mondsichel.",
			[489] = "Es lebt in warmen Meeren. Geht es auf Nahrungssuche, füllt es den Beutel auf seinem Kopf mit Luft.",
			[490] = "Geboren auf dem Meeresboden, legt es große Entfernungen zurück, um dorthin zurückzukehren.",
			[491] = "Es kann andere in Schlaf ver- setzen und ihnen Träume geben. Es ist nur bei Neumond aktiv.",
			[492] = "Es lebt auf Blumenwiesen und rollt sich ein, um wie eine Blume auszu- sehen u. nicht entdeckt zu werden.",
			[493] = "Die Mythologie nennt dieses PKMN als Former des Universums, wobei es seine tausend Arme eingesetzt hat.",
		},
		[703] = { -- species_pokedex_entry_it
			[1] = "Dopo la nascita, cresce traendo nutrimento dal seme piantato sul suo dorso.",
			[2] = "Quando il bocciolo che ha sul dorso si gonfia, emana un dolce profumo. È indice dell’imminente fioritura.",
			[3] = "Dopo la pioggia, il fiore sul suo dorso emana un profumo più intenso e attira gli altri Pokémon.",
			[4] = "La fiamma sulla punta della coda indica la sua vitalità. Se sta bene, la fiamma è più ardente.",
			[5] = "Sui monti rocciosi, sua dimora, la coda di CHARMELEON brilla come una stella nella notte.",
			[6] = "Pare che la temperatura della fiamma di CHARIZARD aumenti dopo che ha affrontato dure lotte.",
			[7] = "Si ritira nel suo guscio e, alla prima occasione, contrattacca colpendo il nemico con spruzzi d’acqua.",
			[8] = "Pare che viva 10000 anni. Ha la coda ricoperta da una folta pelliccia, indice di longevità.",
			[9] = "I getti d’acqua lanciati dai cannoni sul suo guscio riescono a perforare persino l’acciaio.",
			[10] = "Dalle antenne rosse emana un puzzo che respinge il nemico. Cresce cambiando più volte la pelle.",
			[11] = "Ha una corazza dura come l’acciaio che protegge il suo fragile corpo. Attende immobile di evolversi.",
			[12] = "Adora il nettare dei fiori e riesce a localizzare i campi in cui si trova anche una minima quantità di polline.",
			[13] = "Divora ogni giorno una quantità di foglie pari al suo peso. Respinge i nemici con l’aculeo sulla testa.",
			[14] = "Si nasconde dai predatori dietro le foglie e fra i rami, in attesa dell’evoluzione.",
			[15] = "Vola intorno al nemico ad alta velocità, attacca con i pungiglioni avvelenati e si allontana rapido.",
			[16] = "È docile e preferisce evitare i conflitti. Ma se viene disturbato, contrattacca ferocemente.",
			[17] = "Sorvola il suo ampio territorio a caccia di prede, afferrandole con i suoi artigli affilati.",
			[18] = "Sbattendo le ali a più non posso, PIDGEOT crea un vento tanto forte da piegare alberi possenti.",
			[19] = "Un’incredibile vitalità gli permette di adattarsi a qualsiasi tipo di habitat. È estremamente cauto.",
			[20] = "Si affila le zanne in perenne crescita rosicchiando cose dure. Riesce a frantumare persino i muri.",
			[21] = "Sbatte con foga le sue alette per sollevarsi in volo. Cerca le prede beccando nell’erba.",
			[22] = "Le sue ampie ali robuste gli permet- tono di volare tutto il giorno. Combatte usando il becco aguzzo.",
			[23] = "Striscia nell’erba senza fare il minimo rumore e colpisce alle spalle le prede ignare del pericolo.",
			[24] = "Prima paralizza i nemici con il terri- ficante disegno che ha sul ventre, poi gli si avvinghia intorno.",
			[25] = "Vive nelle foreste insieme agli altri. Immagazzina elettricità nelle sacche sulle guance.",
			[26] = "Diventa aggressivo se accumula in sé troppa carica elettrica. Scarica l’elettricità dalla coda.",
			[27] = "Vive in zone aride con precipitazioni minime. Si arrotola come se fosse una palla per difendersi dai nemici.",
			[28] = "Si arrotola come una palla e rotola sul dorso verso i nemici. Gli aculei aguzzi provocano gravi danni.",
			[29] = "Non ama combattere, ma anche una sola goccia del veleno che secerne dagli aculei può essere fatale.",
			[30] = "Quando avverte il pericolo, rizza gli aculei, che fuoriescono più lentamente di quelli di NIDORINO.",
			[31] = "Una robusta armatura ricopre l’intero corpo. Protegge i propri cuccioli a costo della vita.",
			[32] = "Esamina l’ambiente circostante ten- dendo le orecchie fuori dall’erba. Si protegge con il corno velenoso.",
			[33] = "Ha un temperamento violento e infilza i nemici con il corno, che, all’impatto, rilascia veleno.",
			[34] = "Con un solo colpo della potente coda può abbattere un palo del te- lefono come se fosse un fiammifero.",
			[35] = "È molto amato per la sua indole docile. Si pensa che viva in gruppo nella quiete delle montagne.",
			[36] = "Si vedono raramente. Pare che nelle notti di luna piena vadano a giocare in prossimità di laghetti sperduti.",
			[37] = "Controlla palle infuocate. Via via che cresce, dalle sue sei code se ne generano delle altre.",
			[38] = "Si dice che le sue nove code posseggano un potere magico. Vive anche 1000 anni.",
			[39] = "Muove le pupille e comincia a cantare una ninnananna che fa addormentare chiunque l’ascolti.",
			[40] = "Il suo pelo è morbidissimo. Riesce a gonfiarsi e a ingrandirsi semplicemente inalando aria.",
			[41] = "Non ha occhi, ma avverte gli ostacoli con le onde ultrasoniche che emette dalla bocca.",
			[42] = "Ama il sangue umano e quello dei Pokémon. Vola nel buio della notte in cerca di vene da succhiare.",
			[43] = "Durante il giorno, pianta i piedi per terra come se fossero radici. Di notte cammina seminando.",
			[44] = "Il fluido che fuoriesce dalla sua bocca è così puzzolente che si sente anche a 2 km di distanza.",
			[45] = "I suoi petali sono i più grandi al mondo. Mentre cammina diffonde un polline che causa allergie.",
			[46] = "Ha sul dorso dei funghi chiamati tochukaso, che crescono insieme al PARAS su cui si trovano.",
			[47] = "PARASECT è controllato da un fungo ancora più grosso del suo corpo. Diffonde spore velenose.",
			[48] = "I suoi grandi occhi sono in realtà un insieme di tanti piccoli occhi. Di notte, è attirato dalla luce.",
			[49] = "Sbattendo le ali sparge una polvere velenosa a contatto con la pelle.",
			[50] = "Un Pokémon che vive sottoterra. Poiché è abituato a vivere al buio, non sopporta la luce solare.",
			[51] = "Le sue tre teste si muovono a turno per scavare nel duro suolo fino ad una profondità di 100 km.",
			[52] = "È un Pokémon attivo di notte. Se nota qualcosa di luccicante, i suoi occhi cominciano a brillare.",
			[53] = "Un Pokémon molto altezzoso. I fan parlano spesso delle dimensioni del gioiello che ha sulla testa.",
			[54] = "Se la sua costante emicrania peggiora, inizia ad usare poteri misteriosi. Ma poi non se lo ricorda.",
			[55] = "Un Pokémon che vive nei laghi. Nuota più velocemente di un campione di nuoto.",
			[56] = "Vive in colonie sugli alberi. Se uno si adira, l’intera colonia comincia a agire violentemente senza motivo.",
			[57] = "Se lo guardi fisso negli occhi, si adira. Se corri, s’infuria. Se poi lo sconfiggi, s’arrabbia ancor di più.",
			[58] = "Un Pokémon fedele per natura. Rimane immobile finché non riceve ordini dal suo Allenatore.",
			[59] = "Con il suo aspetto fiero ed elegante, è riuscito da tempo a conquistare i cuori della gente.",
			[60] = "La sua pelle è così sottile che si intravedono gli organi. Cammina a fatica sulle zampe poco sviluppate.",
			[61] = "Il disegno spiraliforme sulla pancia ondeggia leggermente. Chi lo fissa, piano piano si assopisce.",
			[62] = "Ha dei muscoli tanto sviluppati da riuscire ad attraversare a nuoto l’Oceano Pacifico senza fermarsi.",
			[63] = "Dorme per 18 ore al giorno. Anche da sveglio, si teletrasporta rimanendo seduto.",
			[64] = "Se lo si avvicina, fa apparire alla televisione un’ombra inquietante che porta sfortuna a chi la guarda.",
			[65] = "La sua incredibile memoria gli fa ricordare ogni evento fin dalla nascita. Il suo QI supera 5000.",
			[66] = "Solleva GRAVELER ripetutamente per mantenersi forte. Conosce ogni tipo di arte marziale.",
			[67] = "La sua incredibile forza può essere molto pericolosa. Indossa una cin- tura per tenerla sotto controllo.",
			[68] = "Tira pugni con le quattro braccia ad una velocità impressionante. Scaglia 1000 pugni ogni 2 secondi.",
			[69] = "Preferisce gli habitat caldi e umidi. Cattura velocemente le prede con i suoi rampicanti.",
			[70] = "Questo Pokémon sembra una pianta. Cattura le prede con una polvere tossica.",
			[71] = "Tiene in bocca un liquido dall’aroma simile al miele, che in realtà è un acido altamente corrosivo.",
			[72] = "Il suo corpo è quasi interamente composto d’acqua. Emette dei raggi misteriosi dagli occhi cristallini.",
			[73] = "Ha 80 tentacoli per intrappolare la preda e non la rilascia finché il veleno non l’ha indebolita.",
			[74] = "Molti vivono sui sentieri montani e se ne stanno mezzi infossati nel terreno ad osservare gli scalatori.",
			[75] = "Costruisce la sua tana in fessure scavate nelle pareti di precipizi e dirupi scoscesi.",
			[76] = "Muta il guscio una volta all’anno. Il suo corpo duro come la roccia non è scalfito neanche dalla dinamite.",
			[77] = "Un’ora dopo la nascita, gli crescono criniera e coda, che gli donano un aspetto solenne.",
			[78] = "Galoppa alla velocità di 240 km/h. Corre come una freccia facendo ondeggiare la criniera ardente.",
			[79] = "Anche se è lento, è abile a pescare con la coda. Non avverte alcun dolore se gliela mordono.",
			[80] = "Non è molto perspicace, ma sembra aguzzare l’ingegno se lo SHELLDER che ha sulla coda lo morde.",
			[81] = "Gli elementi laterali generano onde magnetiche che lo mantengono in sospeso. Si nutre d’elettricità.",
			[82] = "Pokémon formato da tre MAGNEMITE uniti dalla forza magnetica. Più di tre creano una tempesta magnetica.",
			[83] = "Non può vivere senza lo stelo che tiene con un’ala. Lo difende dagli attacchi a costo della vita.",
			[84] = "I suoi due cervelli si comunicano le emozioni grazie ai poteri telepatici.",
			[85] = "Quando DODUO si evolve in questo strano essere, una delle due teste si divide a metà. Corre a 60 km/h.",
			[86] = "Pokémon che vive sugli iceberg. Nuota spaccando il ghiaccio con la punta che ha sulla testa.",
			[87] = "Ha il corpo ricoperto da una pelliccia bianca che, sulla neve, lo rende meno visibile ai predatori.",
			[88] = "Nacque quando il fango di un fiume sudicio fu esposto ai raggi X della luna. Vive nella sporcizia.",
			[89] = "Dal suo corpo filtra un fluido tos- sico che uccide all’istante piante e alberi con cui viene a contatto.",
			[90] = "Nuota all’indietro aprendo e chiudendo le due valve. La lingua è sempre fuori a penzoloni.",
			[91] = "Quando lotta si protegge tenendo la conchiglia chiusa e spara punte per respingere i nemici.",
			[92] = "Il corpo di questo Pokémon è costi- tuito al 95% da gas che possono ve- nir spazzati via da venti improvvisi.",
			[93] = "Riesce a superare qualsiasi ostacolo. Si nasconde nei muri per osservare il nemico.",
			[94] = "Si nasconde nell’ombra. Pare che nei luoghi in cui GENGAR si cela, la temperatura si abbassi di 5°C.",
			[95] = "Si muove sottoterra provocando scosse e boati. Può raggiungere anche la velocità di 80 km/h.",
			[96] = "Riesce ad indovinare cosa sognano le persone annusandole con il suo grande naso. Ama i sogni divertenti.",
			[97] = "Con il suo pendolo fa addormentare chiunque nel giro di tre secondi, anche chi si è appena svegliato.",
			[98] = "Vive in buche scavate sulle spiagge sabbiose. Le sue chele ricrescono se si spezzano nella lotta.",
			[99] = "La chela più grande ha una potenza di 10000 cavalli, ma è così pesante che non permette di mirare bene.",
			[100] = "Sembra una Poké Ball. Toccandolo si rischia di prendere la scossa e di farlo esplodere.",
			[101] = "Quando ha accumulato elettricità fino quasi a scoppiare, si fa trasportare dal vento.",
			[102] = "Queste sei uova comunicano per telepatia. Si riuniscono subito anche se vengono divise.",
			[103] = "Noto come “Giungla in moto”. Se una testa diventa troppo grande, cade e si trasforma in EXEGGCUTE.",
			[104] = "Piange pensando alla madre defunta e dal teschio che ha in testa pro- viene un rumore sordo e continuo.",
			[105] = "Pokémon selvatico che tiene in mano un osso sin dalla nascita. Lo usa abilmente come arma.",
			[106] = "I suoi arti inferiori si allungano del doppio, il che sbalordisce i nemici che lo vedono per la prima volta.",
			[107] = "Sferra pugni così potenti da polve- rizzare persino il cemento. Si ripo- sa dopo tre minuti di lotta.",
			[108] = "Al posto delle mani usa la sua lingua appiccicosa, lunga il doppio di lui. Con essa afferra qualsiasi cosa.",
			[109] = "Fluttua a mezz’aria grazie ai gas che ha in corpo. Questi sono male- odoranti e altamente esplosivi.",
			[110] = "Cresce nutrendosi dei gas emanati dai rifiuti. Anche se rarissimi, ne hanno trovati in gruppi di tre.",
			[111] = "Ha una pelle molto spessa ed è in grado di abbattere interi edifici. Non è molto sagace.",
			[112] = "Si è alzato sulle zampe posteriori e poi gli si è sviluppato il cervello. Con il corno perfora la roccia.",
			[113] = "Si dice che porti felicità. È molto altruista e condivide le uova con chi è ferito.",
			[114] = "È ricoperto di liane blu. Nessuno ha mai visto il suo volto, poiché è celato dal groviglio di liane.",
			[115] = "Tiene il cucciolo nel marsupio che ha sulla pancia e lo lascia uscire solo quando non ci sono pericoli.",
			[116] = "Crea la sua tana all’ombra dei coralli. Se avverte un pericolo, spruzza inchiostro nero e fugge.",
			[117] = "Si difende con gli aculei. Pinne e ossa sono comunemente usati nella medicina tradizionale.",
			[118] = "Quando nuota, la pinna posteriore sembra un elegante abito da sera. Ha un aspetto regale.",
			[119] = "Con il suo corno, perfora le rocce sul letto dei fiumi per farsi il nido. Difende le uova a costo della vita.",
			[120] = "Se il corpo è lacerato, si rigenera se il nucleo rosso è ancora intat- to. Il nucleo brilla a mezzanotte.",
			[121] = "Al centro del corpo ha un nucleo rosso che diffonde misteriosi segnali radio nel cielo notturno.",
			[122] = "È un esperto di mimica che, con i gesti, riesce ad innalzare pareti invisibili che sembrano reali.",
			[123] = "È quasi impossibile parare gli attacchi sferrati dalle sue falci. Si muove come un ninja.",
			[124] = "Le sue grida ricordano il linguaggio umano, ma è impossibile capire il significato delle sue parole.",
			[125] = "Quando si avvicina alle centrali per nutrirsi dell’elettricità, provoca un black-out.",
			[126] = "È nato dallo zampillo di un vulcano. Ha il corpo ricoperto da fiamme che brillano come i raggi solari.",
			[127] = "Afferra la preda con le pinze e non la molla finché non l’ha tranciata. Se non ci riesce, la scaglia via.",
			[128] = "Dopo aver puntato il nemico, lo carica a testa bassa. È noto per la sua indole violenta.",
			[129] = "Si dice che sia il Pokémon più debole del mondo. Nessuno sa come abbia fatto a sopravvivere.",
			[130] = "La sua ira non si placa finché non ha raso al suolo campi e monti attorno a sé.",
			[131] = "Ama attraversare il mare con persone e Pokémon sul suo dorso. Capisce il linguaggio umano.",
			[132] = "Ha la capacità di modificare la sua struttura cellulare per trasfor- marsi in qualsiasi cosa veda.",
			[133] = "Un Pokémon raro che si adatta agli ambienti più difficili assumendo diverse forme nell’evoluzione.",
			[134] = "Si è evoluto per adattarsi alla vita acquatica. Si può sciogliere nell’acqua diventando invisibile.",
			[135] = "Scarica elettricità a 10000 volt e rizza tutti i peli come se fossero aghi pungenti.",
			[136] = "Nel corpo conserva una tasca ardente. Prima di lottare, la sua temperatura si innalza a 900°C.",
			[137] = "Il primo Pokémon al mondo creato artificialmente. Riesce a muoversi liberamente nel ciberspazio.",
			[138] = "Pokémon rigenerato da un fossile grazie alla scienza moderna. Nuotava nei mari ancestrali.",
			[139] = "Si pensa che questo Pokémon si sia estinto perché la sua conchiglia a spirale è cresciuta troppo.",
			[140] = "Si ritiene che vivesse sulle spiagge 300 milioni di anni fa. È protetto da una conchiglia robusta.",
			[141] = "Pokémon probabilmente giunto sulla terraferma perché le sue prede si erano adattate a vivere lì.",
			[142] = "Un Pokémon che vagava nei cieli nell’era dei dinosauri. Le sue zanne sono affilate come lame.",
			[143] = "Il suo stomaco riesce a digerire qualsiasi tipo di cibo, anche se marcio o ammuffito.",
			[144] = "Un Pokémon uccello leggendario. Riesce a creare bufere di neve congelando l’umidità dell’aria.",
			[145] = "Un Pokémon uccello leggendario. Si dice che viva tra le nubi tempo- ralesche. Controlla i fulmini.",
			[146] = "Un Pokémon uccello leggendario. Si dice che la sua apparizione pre- annunci l’arrivo della primavera.",
			[147] = "Detto “Pokémon miraggio” perché è stato avvistato da pochi. È facile trovare la sua pelle della muta.",
			[148] = "Se il suo corpo emana un’aura, il tempo cambia all’istante. Si dice che viva nei mari e nei laghi.",
			[149] = "Si dice che faccia la sua tana da qualche parte nel mare. Porta a riva le vittime di naufragi.",
			[150] = "Un Pokémon creato usando i geni di MEW. Si dice che fra i Pokémon sia quello con l’animo più crudele.",
			[151] = "Poiché sa usare qualsiasi mossa, molti scienziati ritengono che MEW sia l’antenato di tutti i Pokémon.",
			[152] = "Usa la foglia sulla sua testa per misurare la temperatura e l’umidità. Ama crogiolarsi al sole.",
			[153] = "Le foglie attorno al suo collo emanano un aroma speziato dall’effetto energizzante.",
			[154] = "Il suo respiro ha lo straordinario potere di far tornare rigogliosi piante secche e fiori avvizziti.",
			[155] = "È riservato per natura. Se viene spaventato, le fiamme sul suo dorso bruciano ardentemente.",
			[156] = "Intimorisce i nemici con il calore delle sue fiamme. Se è pronto a lot- tare, le vampate sono più ardenti.",
			[157] = "Attacca usando fiamme esplosive. Si cela in una scintillante nube di calore creata dalle fiamme roventi.",
			[158] = "Ha l’abitudine di mordere ogni cosa con le potenti mandibole. Neppure il suo Allenatore è al sicuro!",
			[159] = "Quando azzanna il nemico, non molla la presa finché non gli cadono le zanne, che però ricrescono subito.",
			[160] = "Di solito si muove lentamente, ma quando attacca e morde la preda si muove ad una velocità incredibile.",
			[161] = "Ha un’indole alquanto nervosa. Sta ritto sulla punta della coda per riuscire a sorvegliare ampie aree.",
			[162] = "Si addormenta avvolto nell’esile corpo della madre. Mette all’angolo i nemici con movimenti rapidi.",
			[163] = "Sta sempre ritto su un piede solo e non mette giù l’altro neppure quando viene attaccato.",
			[164] = "Ha una vista acutissima, tanto da riuscire a scorgere oggetti anche con la luce più fioca.",
			[165] = "È tanto timido da non muoversi se non è in gruppo. Trasmette le sue emozioni emanando una fragranza.",
			[166] = "La luce delle stelle è la sua fonte d’energia. Un cielo più stellato fa ingrandire i disegni sul suo dorso.",
			[167] = "Tesse una trappola con un filo di seta, sottile ma robusto. Attende la preda senza muoversi.",
			[168] = "Aggancia la preda con un filo di se- ta e la lascia andare. Poi segue il filo e la trova quando è in gruppo.",
			[169] = "Le sue quattro ali gli permettono di volare più velocemente e più silenziosamente. È attivo di notte.",
			[170] = "Dalle antenne emette scariche elettriche positive e negative con le quali colpisce i nemici.",
			[171] = "La sua luce è visibile anche quando si trova in profondità. È sopranno- minato “Stella degli abissi”.",
			[172] = "Le sacche che ha sulle guance sono ancora piccole e non riescono a immagazzinare molta elettricità.",
			[173] = "La sua sagoma ricorda quella di una stella. Si ritiene che giunga a cavallo di stelle cadenti.",
			[174] = "Ha un corpo morbido ed elastico. Quando comincia a saltellare è praticamente impossibile fermarlo.",
			[175] = "Pare che il suo guscio immagazzini felicità, che condivide poi con le persone gentili.",
			[176] = "Pare che appaia alle persone gentili diffondendo un pulviscolo luminoso detto “Polvere della gioia”.",
			[177] = "Raccoglie cibo dai cactus, evitando agilmente germogli e spine. Si muove saltellando.",
			[178] = "Pokémon enigmatico che vede il passato e prevede il futuro osser- vando il sole tutto il giorno.",
			[179] = "Se il manto è carico d’elettricità, le sue dimensioni raddoppiano e può dare la scossa.",
			[180] = "Se il suo manto è del tutto carico d’elettricità, la coda s’illumina. Lancia peli che danno la scossa.",
			[181] = "La punta della sua coda brilla. In passato, le persone si inviavano segnali usando la luce della coda.",
			[182] = "Quando finisce la stagione delle piogge, lo si vede danzare sotto i caldi raggi del sole.",
			[183] = "Si tuffa in acqua e usa la coda come galleggiante. Ama mangiare le piante che crescono sul fondo dei fiumi.",
			[184] = "Vive nei fiumi e nei laghi. Il suo colore e i disegni confondono i nemici in acqua.",
			[185] = "Ha l’aspetto di un albero, ma il suo corpo è più simile alla roccia. È debole contro l’acqua.",
			[186] = "Ama radunare gruppi e atteggiarsi a capogruppo. I suoi versi richiamano POLIWAG.",
			[187] = "Giunge sospinto dai venti. Si dice che quando HOPPIP appare su campi e monti, la primavera sia in arrivo.",
			[188] = "Il suo fiore sboccia appena l’aria si riscalda. Fluttua nel cielo per assorbire l’energia solare.",
			[189] = "Sospinto dai venti stagionali, gira intorno al globo sparpagliando i suoi semi simili al cotone.",
			[190] = "Usa la coda per raccogliere i frutti che sono fuori portata. La sua coda è più agile delle mani.",
			[191] = "Cade improvvisamente giù dal cielo al mattino. Dopo un’estate fredda, la popolazione di SUNKERN esplode.",
			[192] = "Trae energia dalla luce del sole e si muove di continuo per cercare di assorbirne sempre di più.",
			[193] = "Ha un campo visivo a 360° senza muovere la testa. Riesce a vedere persino le prede alle sue spalle.",
			[194] = "Vive nell’acqua fredda e quando vuole dormire si seppellisce a metà nei fondali melmosi.",
			[195] = "È pigro per natura. Sta sul fondo dei fiumi con la bocca aperta in attesa di afferrare la preda.",
			[196] = "Il suo pelo è simile al velluto. Quando usa i suoi poteri psichici, la sfera che ha sulla fronte brilla.",
			[197] = "La luce lunare ha mutato la struttura genetica di EEVEE. Si cela nel buio in attesa della preda.",
			[198] = "Si dice che l’incontro notturno con questo Pokémon sia un presagio infausto.",
			[199] = "Il morso di SHELLDER gli ha infuso un’intelligenza pari a quella di rinomati scienziati.",
			[200] = "Ama avvicinarsi alle persone in piena notte per terrorizzarle con il suo urlo stridulo.",
			[201] = "È a forma di lettera di un antico alfabeto. È un mistero chi sia ap- parso prima, l’alfabeto o UNOWN.",
			[202] = "Cerca di tenere nascosta la sua coda nera ad ogni costo. Pare che essa celi un segreto.",
			[203] = "Ha due cervelli, uno piccolo anche sulla coda. Morde per respingere i nemici che si avvicinano da dietro.",
			[204] = "Ha l’aspetto di una pigna. Il suo guscio lo protegge dai Pokémon uccello che lo beccano per errore.",
			[205] = "È incassato in una conchiglia d’ac- ciaio. A parte gli occhi scrutatori, nessuno sa cosa ci sia all’interno.",
			[206] = "Scava nel terreno con la coda creando una tana simile a un labi- rinto. Sa spiccare brevissimi voli.",
			[207] = "Si fa trasportare dai venti con le ali spalancate e colpisce la preda dall’alto mirando al volto.",
			[208] = "Temprato dalla pressione e dal calore sotterraneo, il suo corpo è più duro di qualsiasi metallo.",
			[209] = "I Pokémon più piccoli fuggono alla vista della sua faccia terrificante. Ma le donne lo trovano carino.",
			[210] = "Malgrado il suo aspetto, è molto timido. Se si arrabbia, tuttavia, colpisce con le sue enormi zanne.",
			[211] = "Spara i suoi aculei velenosi in tutte le direzioni. Essendo un po’ tondetto, non è un gran nuotatore.",
			[212] = "Ha un corpo duro come l’acciaio. Spaventa i nemici con le chele, su cui sono disegnati degli occhi.",
			[213] = "Conserva nel guscio delle bacche che, quando fermentano, si trasformano in un succo delizioso.",
			[214] = "Si aggira nelle foreste in cerca di linfa, di cui è ghiotto. È tanto forte da scagliare lontano i nemici.",
			[215] = "Mangia uova rubate dai nidi. Attacca i nemici nei punti deboli con i suoi artigli uncinati.",
			[216] = "Si impregna le zampe di miele per poterle leccare in continuazione. Ogni assaggio ha un sapore unico.",
			[217] = "Nel suo territorio, lascia graffi sugli alberi che hanno bacche o frutti deliziosi.",
			[218] = "Nel suo corpo scorre magma. Se non si muove continuamente, il suo corpo si raffredda e s’indurisce.",
			[219] = "Ha una temperatura corporea di circa 10000°C. Dai fori del guscio fuoriescono intense fiammate.",
			[220] = "Ama mangiare i funghi che crescono sotto l’erba secca. Mentre cerca, talvolta trova sorgenti termali.",
			[221] = "Poiché il lungo pelo gli impedisce di vedere, sonda il terreno circo- stante con il sensibilissimo naso.",
			[222] = "Vivono numerosi nei limpidi mari del sud. Pare che non riescano a sopravvivere nelle acque inquinate.",
			[223] = "Emette potenti getti d’acqua con i quali riesce ad abbattere persino le prede in volo.",
			[224] = "Vive nelle spaccature delle rocce e del fondo marino. Con le sue ven- tose afferra saldamente la preda.",
			[225] = "Trascina il cibo avvolgendolo nella coda e ha l’abitudine di condividerlo con chi si perde fra le montagne.",
			[226] = "Quando il mare è calmo, è possibile vedere branchi di MANTINE nuotare leggiadri come se volassero.",
			[227] = "È interamente rivestito da un’armatura dura come l’acciaio. Vola alla velocità di 300 km/h.",
			[228] = "Trasmette i suoi stati d’animo con vari versi. Lavora in gruppo per catturare le prede con l’astuzia.",
			[229] = "Molto tempo fa, si riteneva che le sue urla sinistre coincidessero con la chiamata della morte.",
			[230] = "Vive in caverne sui fondali marini e crea vortici giganteschi ogni volta che si muove.",
			[231] = "Non è molto grande, ma è forte. Può sollevare un adulto e traspor- tarlo sul dorso senza fatica.",
			[232] = "Si arrotola a palla e attacca il nemico. Riesce ad abbattere una casa con un solo colpo.",
			[233] = "Gli è stato installato un programma di sviluppo planetario che lo rende capace di lavorare nello spazio.",
			[234] = "Chi fissa le sue corna riceve una strana sensazione, quasi come se venisse risucchiato.",
			[235] = "Delimita il suo territorio usando la coda come se fosse un pennello. Ha lasciato oltre 5000 segni diversi.",
			[236] = "È famoso per la sua brama di lotta. Subisce sempre ferite dai nemici più forti di lui che sfida.",
			[237] = "Combatte mentre gira come una trottola. La forza centrifuga de- cuplica il suo potere distruttivo.",
			[238] = "Analizza tutto con le labbra e con esse riesce a memorizzare ciò che gli piace e ciò che non gli piace.",
			[239] = "Genera elettricità roteando le braccia. Tuttavia, non riesce ad immagazzinare l’energia creata.",
			[240] = "La sua temperatura corporea è di circa 600°C. Se le fiamme che lancia sono gialle significa che è in forma.",
			[241] = "Si dice che se un bambino beve il latte di MILTANK crescerà bene e da adulto sarà sano e buono.",
			[242] = "Questo Pokémon buono cura i Pokémon malati e li fa guarire. Percepisce la tristezza altrui.",
			[243] = "Pare che sia caduto con un fulmine. Può scagliare saette dalle nuvole di pioggia che ha sul dorso.",
			[244] = "Si dice che quando emette il suo verso, da qualche parte nel mondo un vulcano stia eruttando.",
			[245] = "Corre per tutto il mondo per purificare l’acqua contaminata. Si allontana con i venti del nord.",
			[246] = "Pokémon che mangia la terra. Dopo aver mangiato un’intera montagna, va a dormire per poter crescere.",
			[247] = "Il suo corpo è duro come la roccia. Riesce a muoversi come un razzo espellendo gas con tutta forza.",
			[248] = "Se s’infuria, abbatte le montagne e seppellisce i fiumi. In seguito, le mappe devono essere riscritte.",
			[249] = "Dorme in una fossa negli abissi marini. Con un battito d’ali provoca una tempesta di 40 giorni.",
			[250] = "Le sue piume sono di sette colori. Si dice che chiunque lo veda sarà per sempre felice.",
			[251] = "Ha il potere di viaggiare attraverso il tempo, ma si dice che appaia solo in periodi di pace.",
			[252] = "Le piante dei suoi piedi sono piene di uncini che gli permettono di camminare su muri e soffitti.",
			[253] = "Vive in giungle fitte. Si avvicina alle prede saltando di ramo in ramo.",
			[254] = "Le foglie che crescono sulle sue braccia tagliano anche grandi al- beri. Nel suo habitat, è imbattibile.",
			[255] = "Nel suo corpo brucia una fiamma e abbracciandolo si avverte calore. Lancia palle di fuoco a 1000°C.",
			[256] = "Possiede l’abilità di sferrare anche 10 calci al secondo. Emette urla strazianti per intimorire i nemici.",
			[257] = "Le fiamme che fuoriescono dai suoi polsi gli avvolgono i pugni. Quando colpisce il nemico, lo scotta.",
			[258] = "Con la pinna sulla testa percepi- sce i movimenti dell’acqua e sta in guardia. Riesce a sollevare rocce.",
			[259] = "Grazie alle zampe vigorose, si muove con disinvoltura anche nel fango. Dorme immerso nella melma.",
			[260] = "Nuotando riesce a trainare una grande nave. Con le braccia vigoro- se abbatte i nemici in un sol colpo.",
			[261] = "Pokémon di natura ostinata. Insegue la preda prescelta finché questa non è esausta.",
			[262] = "Caccia le prede in branco. Non disobbedisce mai agli ordini di un Allenatore abile.",
			[263] = "Avanza a zigzag. È bravo a trovare strumenti nell’erba e sul terreno.",
			[264] = "Carica la preda ad una velocità di 100 km/h. Ma dal momento che va solo dritto, sbaglia spesso.",
			[265] = "Ama mangiare le foglie. Se STARLY lo attacca, si difende con gli aculei che ha sulla parte posteriore.",
			[266] = "SILCOON si ancora ai rami con fili di seta. In questa posizione aspetta immobile l’evoluzione.",
			[267] = "Ha un’indole aggressiva. Conficca la sua bocca lunga e sottile nelle prede e ne succhia i fluidi.",
			[268] = "Dentro, il suo bozzolo è caldo. Ogni cellula del suo corpo contribuisce a creare energia per l’evoluzione.",
			[269] = "Pokémon notturno. Attirato dalla luce dei lampioni, divora le foglie degli alberi lungo i viali.",
			[270] = "Sembra una pianta acquatica e viene usato come traghetto dai Pokémon che non sanno nuotare.",
			[271] = "È un po’ dispettoso. Se vede un pescatore, gli tira la lenza solo per dargli fastidio.",
			[272] = "Se ascolta musica allegra, tutto il suo corpo si rivitalizza e non riesce ad evitare di ballare.",
			[273] = "Quando si attacca a un ramo, sembra una vera ghianda. Si diverte a spaventare gli altri Pokémon.",
			[274] = "Il fischio del suo flauto di foglia mette a disagio chi lo sente. Vive nelle foreste più fitte.",
			[275] = "Con le sue foglie provoca raffiche di vento della velocità di 30 m/s che spazzano via interi edifici.",
			[276] = "È molto coraggioso e affronta spavaldo i nemici più forti. Migra verso i paesi caldi.",
			[277] = "Vola in tondo alla ricerca di prede. Quando ne avvista una, si lancia in picchiata per catturarla.",
			[278] = "Nidifica su scogliere a picco sul mare. Si fa trasportare ad alta quota dalle correnti ascensionali.",
			[279] = "Immerge il suo enorme becco nel mare, raccogliendo acqua e numerose prede.",
			[280] = "Percepisce gli stati d’animo delle persone con le corna che ha sul capo. Si mostra alla gente allegra.",
			[281] = "Percepisce molto bene i sentimenti del suo Allenatore. Danza quando si sente felice.",
			[282] = "Difende il suo fidato Allenatore a costo della vita. Ha l’abilità di predire il futuro.",
			[283] = "Cammina a pelo d’acqua. Dall’aculeo sulla testa emana un dolce aroma con cui attira le prede.",
			[284] = "Le sue antenne presentano un motivo ad occhi. Con le quattro ali riesce a volare in ogni direzione.",
			[285] = "Sparge spore tossiche dalla sommità del capo. Se inalate, queste spore provocano dolore in tutto il corpo.",
			[286] = "Tirando pugni, i suoi cortissimi arti si allungano. Usa una tecnica simile a quella dei pugili professionisti.",
			[287] = "Passa quasi tutto il tempo sdraiato. Soltanto a guardarlo si prova sonnolenza.",
			[288] = "Il suo cuore batte 10 volte più velocemente del normale. Non sta fermo neanche un momento.",
			[289] = "Il Pokémon più pigro in assoluto. Stando disteso, in realtà cerca di risparmiare forze per attaccare.",
			[290] = "Cresce sottoterra e, poiché è quasi cieco, usa le antenne per sondare ciò che lo circonda.",
			[291] = "Si muove così in fretta da risultare quasi invisibile. Lo si vede in gruppo attorno agli alberi ricchi di linfa.",
			[292] = "È nato dal guscio vuoto di un inset- to. Pare che chi spia nella fessura sul suo dorso perda l’anima.",
			[293] = "Di solito ha una voce molto tenue, ma se si spaventa, emette un suono assordante quanto un jet.",
			[294] = "Le onde d’urto dei suoi versi ribaltano anche i camion. Pesta i piedi per accumulare energia.",
			[295] = "Le sue urla si sentono a 10 km di distanza. Emette diversi suoni dalle numerose aperture del suo corpo.",
			[296] = "Si rinforza sbattendo contro enormi alberi. Vicino alla sua tana si trovano parecchi alberi abbattuti.",
			[297] = "Ama confrontarsi con Pokémon gros- si. Con uno dei suo schiaffi, può far prendere il volo a un camion.",
			[298] = "Pokémon che vive nell’acqua. Si muove rapidamente sulla terraferma saltellando sulla grossa coda.",
			[299] = "Il suo naso è magnetico. Per questo motivo lo tiene sempre puntato verso nord.",
			[300] = "Non riesce ad evitare di inseguire tutto ciò che si muove e corre in tondo a caccia della propria coda.",
			[301] = "Ha successo fra gli Allenatori di sesso femminile per la sua bellissima pelliccia. Non ha una tana fissa.",
			[302] = "Si cela nell’oscurità delle caverne. Si nutre di gemme e per questo i suoi occhi sono pietre preziose.",
			[303] = "Le sue due enormi mandibole sono corna trasformate. Con esse può masticare persino travi di ferro.",
			[304] = "Vive generalmente sui monti ma, spinto dalla fame, scende per cibarsi di ferrovie e automobili.",
			[305] = "Scava per cercare ferro, di cui si nutre. Si schianta contro gli altri nella lotta per il territorio.",
			[306] = "Cerca ferro da mangiare scavando tunnel nella roccia con le sue corna d’acciaio.",
			[307] = "Mangia solo una bacca al giorno. Resistendo alla fame, il suo spirito viene temprato e rinvigorito.",
			[308] = "Con gli esercizi di yoga ha affinato il sesto senso. I suoi movimenti sono molto eleganti.",
			[309] = "L’elettricità immagazzinata nella pelliccia gli stimola i muscoli e aumenta la sua velocità di reazione.",
			[310] = "Scarica elettricità dalla criniera. Crea nubi temporalesche in cielo che fanno cadere saette.",
			[311] = "Incoraggia gli amici con un vivace scoppiettio di scintille. Assorbe elettricità dai pali telefonici.",
			[312] = "Incoraggia gli amici e, se questi perdono, il suo corpo emette una maggiore quantità di scintille.",
			[313] = "Di notte comunica con gli altri illuminando la sua coda. Ama il dolce aroma di ILLUMISE.",
			[314] = "Con il suo dolce aroma dirige il volo di VOLBEAT, che disegna figure luminose nel cielo stellato.",
			[315] = "ROSELIA, cresciuto bevendo acqua pulita, è noto perché fa crescere fiori dai vividi colori.",
			[316] = "La maggior parte del suo corpo è stomaco. I suoi succhi gastrici dissolvono subito ciò che ingerisce.",
			[317] = "Inghiotte intera qualsiasi cosa. Dai pori traspira un liquido tossico con cui bagna i nemici.",
			[318] = "Attacca in branco chi invade il suo territorio. Le zanne aguzze lacerano anche gli scafi delle navi.",
			[319] = "Con le sue zanne può spezzare il ferro. Nuota a 120 km/h. È noto come il “Tiranno del mare”.",
			[320] = "In giornate soleggiate, gioca rimbalzando sulla spiaggia. Spruzza acqua dalle narici.",
			[321] = "Il Pokémon più grande che esista. Dopo aver inalato aria, si immerge a una profondità di 3000 metri.",
			[322] = "Nella gobba accumula magma. Quando piove, il magma si indurisce e il Pokémon diventa più lento.",
			[323] = "Ha dei vulcani sul dorso. Se il magma nel suo corpo aumenta, trema e poi erutta violentemente.",
			[324] = "Genera energia bruciando carbone all’interno della corazza. Se è in pericolo, emette fuliggine scura.",
			[325] = "Rimbalza costantemente usando la coda come una molla. Il movimento sollecita il cuore e lo fa battere.",
			[326] = "Usa perle nere per amplificare i suoi poteri psichici. Con una danza acquisisce controllo sul nemico.",
			[327] = "Non ci sono due SPINDA con lo stes- so motivo maculato. Il suo passo barcollante confonde i nemici.",
			[328] = "Scava fosse coniche nella sabbia del deserto e attende che le prede cadano in trappola.",
			[329] = "Fa vibrare violentemente le ali generando onde ultrasoniche che provocano il mal di testa.",
			[330] = "Genera tempeste di sabbia con il battito delle ali. È detto anche “Spirito primordiale del deserto”.",
			[331] = "Immagazzina acqua nel corpo e riesce a sopravvivere nel deserto senz’acqua anche per 30 giorni.",
			[332] = "Diventa attivo di notte, quando va a caccia di prede stremate dalla calura del deserto.",
			[333] = "Le sue ali sono come batuffoli. Se si appoggia sulla testa di qualcuno, sembra un cappello di cotone.",
			[334] = "Quando lotta, sembra una morbida nuvola. Canticchia con la sua voce da soprano.",
			[335] = "Da generazioni, è acerrimo nemico di SEVIPER. Gli artigli aguzzi sono le sue armi più potenti.",
			[336] = "È acerrimo nemico di ZANGOOSE. Prima della lotta, affila sulle rocce la sua coda simile ad una spada.",
			[337] = "Diventa attivo nelle notti di luna piena, pertanto si dice che abbia qualche legame con le fasi lunari.",
			[338] = "Nuova specie di Pokémon che si dice provenga dal sole. Emana luce roteando vorticosamente.",
			[339] = "Il suo corpo è ricoperto da una pellicola viscida, che gli permette di sgusciare via, se afferrato.",
			[340] = "Ha un senso del territorio molto sviluppato. Respinge i nemici scate- nando terremoti del raggio di 5 km.",
			[341] = "La sua grande vitalità gli permette di adattarsi ad ogni habitat. Le sue chele non rilasciano mai la preda.",
			[342] = "Pokémon violento che afferra il nemico con le chele e lo scaraventa fuori dal suo stagno.",
			[343] = "Pokémon raro che si muove rotean- do su se stesso. È stato scoperto nei pressi di antiche rovine.",
			[344] = "Pokémon nato da un’antica statuetta d’argilla portata in vita da misteriose radiazioni.",
			[345] = "Viveva sul fondo marino 100 milioni di anni fa ed è stato rigenerato in laboratorio.",
			[346] = "Vive in acque poco profonde nei mari caldi. Con la bassa marea, scava sulla riva in cerca di prede.",
			[347] = "Un antico Pokémon rigenerato da un fossile. Viveva nel mare e catturava le prede con gli artigli.",
			[348] = "Dopo essersi evoluto, è andato a vivere a riva. Tutto il suo corpo è rivestito da un’armatura robusta.",
			[349] = "È noto per il suo aspetto disordi- nato. È molto comune e tende a raggrupparsi nei soliti posti.",
			[350] = "Si dice che sorga dai fondali dei laghi per placare gli animi furiosi delle persone che litigano.",
			[351] = "Il suo aspetto varia con il clima. Recentemente si è scoperto che le sue molecole sono di acqua.",
			[352] = "Può mutare il colore del corpo a piacimento. Tuttavia, il motivo a zigzag sul suo ventre non cambia.",
			[353] = "Si annida sotto le grondaie di case dove vive gente che cova sentimenti di vendetta, che lui adora.",
			[354] = "Un peluche divenuto Pokémon per la rabbia di essere stato buttato via da un bimbo, di cui è alla ricerca.",
			[355] = "Segue ostinatamente la preda ovunque essa vada. Abbandona la caccia solo all’alba.",
			[356] = "Il suo corpo è vuoto. Pare che chiunque si avvicini per guardare dentro venga risucchiato.",
			[357] = "Poiché mangiava sempre i suoi frutti preferiti, questi hanno cominciato a crescergli attorno al collo.",
			[358] = "Le sue urla sono così potenti da far volar via i nemici. Comunica con sette versi differenti.",
			[359] = "Percepisce l’arrivo di disastri na- turali e appare alla gente solo per avvisarla del pericolo imminente.",
			[360] = "Questi Pokémon si allenano in gruppo caricandosi l’un l’altro per rafforzarsi. Amano i frutti dolci.",
			[361] = "Secondo alcune leggende delle regioni fredde, uno SNORUNT porta prosperità alla casa in cui vive.",
			[362] = "Per difendersi, riveste il suo corpo con un’armatura di ghiaccio, fatta congelando l’umidità dell’aria.",
			[363] = "Poiché il suo corpo non è adatto al nuoto, rotola su lastre di ghiaccio per raggiungere la riva.",
			[364] = "Fa roteare oggetti sul naso per controllarne l’odore e la consistenza.",
			[365] = "Frantuma il ghiaccio con le zanne. Lo spesso strato adiposo respinge il freddo e gli attacchi nemici.",
			[366] = "Crea una sola perla in tutta la sua vita. Si dice che questa perla amplifichi i poteri psichici.",
			[367] = "Vive nei mari profondi. Con la coda a forma di pesciolino attrae prede ignare del pericolo.",
			[368] = "Vive sui fondali marini. In primavera il suo corpo rosato diventa più vivido per chissà quale motivo.",
			[369] = "Un Pokémon raro scoperto durante un’esplorazione del mare profondo. È immutato da 100 milioni di anni.",
			[370] = "Vive nei mari caldi. Si dice che le coppie che trovano questo Pokémon riceveranno in dono l’eterno amore.",
			[371] = "Sogna di poter volare un giorno e, pertanto, si allena regolarmente gettandosi da alture.",
			[372] = "Nella sua dura corazza le cellule hanno cominciato a cambiare. Quando si evolve, la corazza cade.",
			[373] = "Il suo forte desiderio di volare ha provocato una mutazione cellulare e gli sono spuntate le ali.",
			[374] = "Comunica con i suoi simili mediante onde magnetiche. I gruppi di BELDUM si muovono in perfetta sintonia.",
			[375] = "È sorto dalla fusione di due BELDUM. Il suo corpo d’acciaio non viene scalfito neanche se urta un jet.",
			[376] = "È formato dalla fusione di due METANG. Ha quattro cervelli e l’intelligenza di un supercomputer.",
			[377] = "È formato interamente da rocce. Se si staccano nella lotta, ne cerca altre per sostituirle.",
			[378] = "Il suo corpo è costituito da ghiac- cio dell’era glaciale. Mantiene l’aria a una temperatura di -200°C.",
			[379] = "La pressione subita sottoterra per decine di migliaia di anni ha reso il suo corpo resistentissimo.",
			[380] = "Questo Pokémon ha il corpo ricoperto di piume che riflettono la luce e lo rendono invisibile.",
			[381] = "Pokémon molto intelligente. Ripiegando indietro le ali, riesce a volare più veloce di un jet.",
			[382] = "Si dice che abbia ampliato i mari provocando piogge torrenziali. Si è assopito in una fossa marina.",
			[383] = "Dopo una lotta colossale contro KYOGRE, si è addormentato sotto terra in mezzo al magma.",
			[384] = "Vive nello strato di ozono oltre le nuvole e non può essere avvistato da terra.",
			[385] = "Ha l’abilità di realizzare ogni desiderio, ma soltanto per una settimana ogni 1000 anni.",
			[386] = "È il risultato della mutazione gene- tica di un virus alieno, giunto sulla terra con un meteorite.",
			[387] = "Il suo guscio, che è fatto di terra, s’indurisce quando il Pokémon beve. Vive sulle rive dei laghi.",
			[388] = "Vive nelle foreste vicino all’acqua, ma esce di giorno per far pren- dere sole alle piante sul guscio.",
			[389] = "Piccoli Pokémon si radunano talvolta sul suo dorso immobile per costruirvi la loro tana.",
			[390] = "Scala agilmente le rocce scoscese e vive in cima ai monti. Prima di dormire spegne le fiamme.",
			[391] = "Per intimorire i nemici che attaccano, intensifica le fiamme sulla coda per apparire più grande.",
			[392] = "Usa un tipo speciale di arte marzia- le che coinvolge tutti gli arti. Le sue fiamme non si estinguono mai.",
			[393] = "È molto orgoglioso e odia accettare cibo dalla gente. Le fitte piume lo proteggono dal freddo.",
			[394] = "Vive da solo lontano dagli altri. Apparentemente ogni esemplare crede di essere il più importante.",
			[395] = "I tre corni che si allungano dal suo becco attestano la sua forza. Il capogruppo ha i corni più grossi.",
			[396] = "Si muove in grandi gruppi. Anche se piccolo, batte le ali in maniera molto energica.",
			[397] = "Vola nelle foreste e nei campi in cerca di Pokémon coleottero. Si muove in grandi gruppi.",
			[398] = "Ha un’indole selvaggia. Sfida coraggiosamente i nemici più grossi di lui.",
			[399] = "Ha i nervi d’acciaio e niente può turbarlo. È più agile e attivo di quanto sembri.",
			[400] = "Sbarra il corso dei fiumi con cor- teccia e fango per farsi la tana. È noto come lavoratore instancabile.",
			[401] = "Muove la testa avanti e indietro e le antenne, scontrandosi, produ- cono un suono simile allo xilofono.",
			[402] = "Quando canta tiene le zampe incrociate al petto. Sa improvvisare melodie.",
			[403] = "In caso di pericolo, la sua pelliccia si illumina. Il nemico rimane acceca- to e lui ne approfitta per fuggire.",
			[404] = "Dagli artigli rilascia un’elettricità talmente intensa da mandare KO il nemico. Vive in piccoli gruppi.",
			[405] = "Vede attraverso qualsiasi cosa. Individua e cattura le prede che si nascondono dietro gli oggetti.",
			[406] = "D’inverno chiude la sua gemma e resiste al freddo. In primavera la gemma si riapre e rilascia polline.",
			[407] = "Attira la preda con un dolce aroma, poi l’abbatte con le fruste spinose celate fra i bouquet delle braccia.",
			[408] = "Viveva nella giungla circa 100 milioni di anni fa. Il suo cranio è duro come il ferro.",
			[409] = "Tira testate talmente potenti da frantumare anche oggetti durissimi.",
			[410] = "Pokémon che viveva nella giungla circa 100 milioni di anni fa. Il suo muso è molto resistente.",
			[411] = "Respinge qualsiasi attacco frontale. È un Pokémon docile che si nutre di erba e di bacche.",
			[412] = "Per ripararsi dal freddo e dai venti invernali si copre con un manto fatto di rami e foglie.",
			[413] = "Con l’evoluzione, il manto di BURMY diventa parte del corpo di questo Pokémon. Non se ne separa mai.",
			[414] = "Ama il nettare dei fiori. Ruba e mangia il nettare raccolto da COMBEE.",
			[415] = "Pokémon formato da altri tre. È sempre impegnato a portare il nettare dei fiori a VESPIQUEN.",
			[416] = "Il suo addome funge da rifugio per le larve, che nutre con il nettare raccolto da COMBEE.",
			[417] = "Forma delle palle di pelo cariche elettrostaticamente e le conserva negli alberi insieme alle bacche.",
			[418] = "Ha un collare che funge da galleg- giante. Quando nuota, la sua testa rimane sempre fuori dall’acqua.",
			[419] = "Nuota con il suo grosso galleg- giante e aiuta a soccorrere chi sta per annegare.",
			[420] = "La pallina contiene i nutrimenti necessari per l’evoluzione. Dicono che sia molto dolce e deliziosa.",
			[421] = "Sboccia quando fa caldo e cerca di godersi fino all’ultimo ogni mo- mento che può passare al sole.",
			[422] = "Forma e colori variano di regione in regione. Pare che nella regione di Sinnoh ne esistano due tipi.",
			[423] = "Ha un corpo flessibile e senza ossa. Qualsiasi parte del corpo che gli venga lacerata ricresce subito.",
			[424] = "Si nutre di nocciole che sbuccia con le due code. Raramente usa le sue vere braccia.",
			[425] = "Pokémon formato dalle anime di persone e Pokémon. Ama le stagioni umide.",
			[426] = "Di giorno fluttua con aria sonnolenta, ma di notte vola via in gruppo. Nessuno sa dove vada.",
			[427] = "Sbaraglia i nemici dispiegando con forza le orecchie arrotolate. Fa piangere di dolore anche gli adulti.",
			[428] = "Pokémon molto cauto. Se percepisce un pericolo, si avvolge nelle sue orecchie morbide e pelose.",
			[429] = "I suoi versi sembrano incantesimi. Chi li sente è tormentato da emicranie e allucinazioni.",
			[430] = "Diventa attivo di notte e lo si vede spesso in compagnia di numerosi MURKROW.",
			[431] = "Se disturbato, tira fuori gli arti- gli; se soddisfatto, fa le fusa. La sua incostanza piace a molti.",
			[432] = "Si introduce sfacciatamente nelle tane degli altri Pokémon rivendicandole poi come proprie.",
			[433] = "Emette versi muovendo la sfera che ha nella gola. Si muove saltellando agilmente.",
			[434] = "Si protegge spruzzando un fluido puzzolente dal posteriore. Il tanfo permane per 24 ore.",
			[435] = "Attacca spruzzando un fluido puzzolente dalla coda. Ha un raggio d’azione di oltre 50 metri.",
			[436] = "Il suo aspetto ricorda alcuni oggetti ritrovati in antiche tombe, ma non si sa se ci sia una relazione.",
			[437] = "Il suo ritrovamento in un cantiere dopo un sonno di 2000 anni fece a suo tempo molto scalpore.",
			[438] = "Sembra che pianga tutto il tempo. In realtà regola il livello dei fluidi del corpo eliminando gli eccessi.",
			[439] = "Imita i movimenti dei nemici. Quando un nemico viene imitato, non riesce più a distogliere lo sguardo da lui.",
			[440] = "Ama gli oggetti bianchi e tondi. Imita CHANSEY trasportando una roccia a forma di uovo.",
			[441] = "Può imparare il linguaggio umano. Se un gruppo si raduna, tutti imparano le stesse parole.",
			[442] = "Pokémon formato da 108 spiriti. È stato imprigionato nella fessura di una Roccianima.",
			[443] = "Nidifica in piccole cavità orizzontali nelle pareti delle grotte. Si avven- ta sulle prede che si avvicinano.",
			[444] = "Molti credono che le medicine fatte con le sue scaglie curino anche i mali incurabili.",
			[445] = "Quando si piega e distende le ali, sembra un jet. Vola a una velocità supersonica.",
			[446] = "Divora quotidianamente una quantità di cibo pari al suo peso mandandolo giù quasi senza masticare.",
			[447] = "L’aura che emana si intensifica per comunicare agli altri se è triste o spaventato.",
			[448] = "È in grado di avvertire l’aura di tutte le cose. Comprende il linguaggio umano.",
			[449] = "Vive in territori aridi. Invece del sudore, espelle dal corpo sabbia granulosa.",
			[450] = "Immagazzina sabbia all’interno del corpo e l’espelle con violenza dai pori, formando enormi vortici.",
			[451] = "Afferra le prede con gli artigli della coda e non si allontana finché il veleno che inietta non agisce.",
			[452] = "Con le zampe può accartocciare una macchina. Le punte degli artigli sono velenose.",
			[453] = "Le sacche delle guance contengono veleno. Infilza i nemici con le sue unghie avvelenate.",
			[454] = "I suoi artigli secernono una tossina così velenosa che persino un graffio può essere letale.",
			[455] = "Attira le prede con il dolce aroma della saliva e poi le ingoia. Impiega un giorno per mangiare una preda.",
			[456] = "Dopo una lunga esposizione al sole, i motivi sulle sue pinne brillano vividamente al calar dell’oscurità.",
			[457] = "Vive negli abissi marini. Attira le prede illuminando i motivi delle sue quattro pinne.",
			[458] = "Pokémon amichevole che con le antenne è in grado di avvertire anche minime correnti marine.",
			[459] = "Vive sui monti innevati. Ha avuto pochi contatti con gli umani, quindi è molto curioso nei loro confronti.",
			[460] = "Crea bufere di neve sui monti ricoperti da nevi perenni. È l’abominevole essere delle nevi.",
			[461] = "Questi Pokémon vivono in zone fred- de in gruppi di quattro o cinque. Insieme sono cacciatori abilissimi.",
			[462] = "Si è evoluto in seguito all’esposi- zione a uno speciale campo magneti- co. Tre unità generano magnetismo.",
			[463] = "Avvolge ogni cosa con la sua lingua allungabile. Chi si avvicina troppo, si ritroverà tutto bagnato di bava.",
			[464] = "Mette rocce nelle cavità dei suoi palmi e le getta con tutta la sua forza. Talvolta lancia GEODUDE.",
			[465] = "Intrappola le prede con gli arti, che sono costituiti da liane. Se ne perde uno, non si turba affatto.",
			[466] = "Tocca il nemico con le sue due code e rilascia una scarica elettrica di oltre 20000 volt.",
			[467] = "Spara palle di fuoco di oltre 2000°C dagli arti superiori. Vive nei crateri dei vulcani.",
			[468] = "Non si presenta mai dove c’è un conflitto. Di recente le sue apparizioni sono diventate rare.",
			[469] = "Agitando le ali crea onde d’urto che infliggono gravi ferite agli organi interni dei nemici.",
			[470] = "Usa la fotosintesi, proprio come una pianta. Pertanto è sempre circondato da aria pulita.",
			[471] = "Come tecnica di difesa, congela completamente la sua pelliccia per far rizzare i peli come aghi.",
			[472] = "Sta appeso ai rami con la testa in giù. Alla prima occasione, si butta a capofitto sulla preda.",
			[473] = "Ha enormi zanne di ghiaccio. La popolazione di questo Pokémon è diminuita alla fine dell’era glaciale.",
			[474] = "È stato aggiunto un software per migliorare le prestazioni di questo Pokémon. Agisce in modo strano.",
			[475] = "Pokémon elegante e ottimo spadaccino, combatte allungando le lame che ha sui gomiti.",
			[476] = "Emana un forte magnetismo da tutto il corpo. Controlla tre piccole unità, dette Mininasi.",
			[477] = "Capta con l’antenna onde che arri- vano dal mondo degli spiriti, che gli ordinano di portare lì le persone.",
			[478] = "Congela i nemici con un alito glaciale a -50°C. Il suo corpo è vuoto.",
			[479] = "Il suo corpo è composto di plasma. È solito infiltrarsi negli strumenti elettronici per provocare caos.",
			[480] = "Noto come “Essere della conoscenza”. Pare che faccia per- dere la memoria a chiunque lo fissi.",
			[481] = "Detto “Essere delle emozioni”. Ha insegnato agli uomini la nobiltà di tristezza, gioia e dolore.",
			[482] = "Detto “Essere della volontà”. Dorme sul fondo di un lago per mantenere il mondo in equilibrio.",
			[483] = "Ha il potere di controllare il tempo. Descritto nei miti della regione di Sinnoh come un’antica divinità.",
			[484] = "Ha l’abilità di distorcere lo spazio. Nella mitologia della regione di Sinnoh è una divinità.",
			[485] = "Vive nelle cavità dei vulcani. Scava con i suoi piedi a croce per scalare pareti e arrampicarsi sui soffitti.",
			[486] = "Una leggenda narra che questo Pokémon abbia trainato i continenti con delle funi.",
			[487] = "Pokémon che vive in un mondo sul lato opposto al nostro. Appare in cimiteri antichi.",
			[488] = "Volando rilascia un velo di particelle brillanti. Si dice che rappresenti la luna crescente.",
			[489] = "Vive nei mari caldi. Sulla testa ha un galleggiante gonfiabile grazie al quale nuota alla ricerca di cibo.",
			[490] = "Nato su freddi fondali marini, per- corre a nuoto lunghe distanze per tornare al suo luogo di nascita.",
			[491] = "Ha l’abilità di far addormentare la gente e farla sognare. È attivo nelle notti di luna nuova.",
			[492] = "Vive nei campi di fiori e cerca di non farsi vedere arrotolandosi per sembrare una pianta fiorita.",
			[493] = "Nella mitologia è descritto come il Pokémon che ha dato forma all’uni- verso con le sue 1000 braccia.",
		},
		[704] = { -- species_pokedex_entry_es
			[1] = "Después de nacer, crece alimentándose de las semillas de su lomo.",
			[2] = "Cuando el bulbo de su lomo se hincha, desprende un dulce aroma para indicar el florecimiento.",
			[3] = "Después de un día de lluvia, la flor de su lomo tiene un aroma más potente y atrae a otros Pokémon.",
			[4] = "La llama de la punta de su cola indica su salud. Si CHARMANDER está sano, arderá con más fuerza.",
			[5] = "En las montañas rocosas donde viven los CHARMELEON, sus colas ardientes brillan como estrellas.",
			[6] = "Se dice que el fuego de CHARIZARD arde con más fuerza si ha vivido duras batallas.",
			[7] = "Se protege con su caparazón y luego contraataca lanzando agua a presión cuando tiene oportunidad.",
			[8] = "Se dice que vive 10000 años. Su peluda cola es un símbolo de longevidad.",
			[9] = "Los chorros de agua que lanza por los tubos de su caparazón pueden atravesar el acero.",
			[10] = "Su antena roja desprende un gran hedor para repeler a los enemigos. Crece mudándose repetidamente.",
			[11] = "Su frágil cuerpo está recubierto de una coraza dura como el acero. Permanece quieto en su desarrollo.",
			[12] = "Adora el néctar de las flores. Puede localizar hasta las más pequeñas cantidades de polen.",
			[13] = "Come el equivalente a su peso en hojas todos los días. Se defiende con el aguijón de su cabeza.",
			[14] = "Se esconde de sus atacantes entre las ramas de los árboles mientras espera a evolucionar.",
			[15] = "Atacan volando alrededor del objetivo y usando su aguijón venenoso antes de huir.",
			[16] = "Es manso y prefiere evitar los problemas. Sin embargo, si le molestan atacará ferozmente.",
			[17] = "Sobrevuela su extenso territorio en busca de presas y ataca con sus poderosas garras.",
			[18] = "Aleteando con toda su fuerza, PIDGEOT crea corrientes de aire capaces de doblar grandes árboles.",
			[19] = "Su capacidad de adaptación le permite vivir en cualquier lugar. Es tremendamente cauteloso.",
			[20] = "Lima sus colmillos royendo objetos duros. Con ellos puede destruir incluso paredes de hormigón.",
			[21] = "Agita continuamente sus alitas para volar. Busca presas entre la hierba con su pico.",
			[22] = "Tiene energía para volar todo el día con sus grandes alas. Lucha con su afilado pico.",
			[23] = "Se mueve por la hierba en silencio y sorprende a sus presas atacando por detrás.",
			[24] = "ARBOK intimida a sus presas con el dibujo de su panza y luego las asfixia con su cuerpo.",
			[25] = "Vive en grupo en los bosques. Almacena electricidad en las bolsas de sus mejillas.",
			[26] = "Se vuelve agresivo si su cuerpo acumula demasiada electricidad, que descarga a través de la cola.",
			[27] = "Vive en zonas áridas donde casi no llueve. Se enrosca formando una bola para defenderse.",
			[28] = "Se hace una bola y se lanza rodando hacia los enemigos para clavarles sus afiladas púas.",
			[29] = "Aunque no le gusta luchar, una sola gota del veneno de sus púas puede resultar fatal.",
			[30] = "Saca las púas de su cuerpo si siente peligro. Sus púas crecen más despacio que las de NIDORINO.",
			[31] = "Tiene el cuerpo cubierto de duras escamas. Protege a su cría con toda su fuerza.",
			[32] = "Saca las orejas por encima de la hierba para explorar el territorio. Le protege su cuerno venenoso.",
			[33] = "Se muestra violento y ataca a los enemigos con un cuerno que desprende veneno.",
			[34] = "Un golpe de su poderosa cola puede partir un poste de teléfono como si fuese una cerilla.",
			[35] = "El preferido de mucha gente por su naturaleza afable. Se cree que vive en grupo en montañas tranquilas.",
			[36] = "Rara vez se le ve. Se dice que en noches de luna llena sale a jugar en lagos solitarios.",
			[37] = "Controla bolas de fuego. A medida que crece, sus seis colas se multiplican.",
			[38] = "Se dice que sus nueve colas están revestidas de poder místico. Puede vivir mil años.",
			[39] = "Cuando mueve sus grandes ojos redondos, comienza a cantar una nana que duerme al enemigo.",
			[40] = "Tiene un pelaje muy agradable al tacto. Puede hinchar su cuerpo tragando aire.",
			[41] = "Aunque carezca de ojos, puede detectar obstáculos con las ondas ultrasónicas que emite su boca.",
			[42] = "Le encanta la sangre, tanto la de Pokémon como la humana. Sale a calmar su sed por la noche.",
			[43] = "Suele plantarse en el suelo durante el día. Por la noche se desplaza esparciendo semillas.",
			[44] = "La miel que emana de su boca posee un hedor capaz de derribar enemigos a 2 km de distancia.",
			[45] = "Sus pétalos son los más grandes del mundo. Cuando anda desprende un terrible polen alergénico.",
			[46] = "En el lomo de PARAS crecen unas setas parasitarias llamadas tochukaso.",
			[47] = "PARASECT está dominado por un hongo parásito mayor que él. Dispersa esporas venenosas.",
			[48] = "Sus grandes ojos son en realidad grupos de ojos diminutos. Por la noche se siente atraído por la luz.",
			[49] = "Agita las alas para dispersar un polvillo de escamas que libera toxinas si toca la piel.",
			[50] = "Este Pokémon vive a oscuras bajo tierra, por lo que la luz solar le espanta.",
			[51] = "Sus tres cabezas se mueven por turnos para excavar la tierra a una profundidad de unos 100 km.",
			[52] = "Es de naturaleza nocturna. Le atraen los objetos brillantes.",
			[53] = "Es un Pokémon muy arrogante. El tamaño de la joya de su frente da mucho que hablar.",
			[54] = "Cuando su jaqueca empeora, usa poderes misteriosos. Sin embargo, nunca recuerda haberlos usado.",
			[55] = "Este Pokémon vive en lagos. En el agua es más rápido que cualquier nadador profesional.",
			[56] = "Vive en colonias en los árboles. Si uno se enfada, el resto de la manada ataca sin motivo.",
			[57] = "Se molesta si le miras a los ojos. Se enfada si corres. Se enfurece si le golpeas.",
			[58] = "Pokémon de naturaleza leal. Permanece quieto en espera de órdenes de su entrenador.",
			[59] = "Su aspecto regio y orgulloso se ha ganado el corazón de la gente hace tiempo.",
			[60] = "Su piel es tan fina que permite ver sus órganos. Le cuesta andar con sus nuevas patas.",
			[61] = "El dibujo espiral de su panza ondea levemente. Si se mira fijamente, provoca somnolencia.",
			[62] = "Tiene músculos muy desarrollados. Es capaz de nadar en el océano sin descanso.",
			[63] = "Duerme 18 horas al día. Cuando está despierto no se levanta ni para teletransportarse.",
			[64] = "Si se acerca uno, una extraña sombra aparece en los televisores. Se dice que verla trae mala suerte.",
			[65] = "Su gran memoria le permite recordar todo desde su nacimiento. Su CI es superior a 5000.",
			[66] = "Levanta un GRAVELER para mantener sus músculos en forma. Domina todas las artes marciales.",
			[67] = "La gran fortaleza de MACHOKE es peligrosa, así que lleva un cinturón que disminuye su energía.",
			[68] = "Golpea con sus cuatro brazos a gran velocidad. Puede dar 1000 golpes en dos segundos.",
			[69] = "Prefiere los lugares cálidos y húmedos. Captura presas con sus rápidas lianas.",
			[70] = "Este Pokémon parece una planta. Captura a sus presas usando polvo tóxico cuando están desprevenidas.",
			[71] = "Su boca segrega un fluido de olor parecido a la miel: un potente ácido que disuelve cualquier cosa.",
			[72] = "Su cuerpo se compone casi en exclusiva de agua. Lanza extraños rayos con sus ojos cristalinos.",
			[73] = "Posee 80 tentáculos con los que aprisiona a sus presas hasta que se debilitan por el veneno.",
			[74] = "Muchos viven en zonas montañosas y permanecen semienterrados mientras miran a los escaladores.",
			[75] = "Muchos GRAVELER hacen agujeros en acantilados escarpados para establecerse dentro de ellos.",
			[76] = "Muda su piel una vez al año. Su cuerpo rocoso es tan duro que ni la dinamita lo daña.",
			[77] = "Sus impresionantes cola y crin de fuego le crecen una hora después de nacer.",
			[78] = "Galopa a casi 240 km por hora. Su crin ardiente parece una flecha cuando corre.",
			[79] = "A pesar de su lentitud, tiene una gran habilidad para pescar con la cola, que es insensible al dolor.",
			[80] = "Normalmente se muestra torpe, aunque espabila si el SHELLDER de su cola le muerde.",
			[81] = "Las unidades laterales crean ondas electromagnéticas que le permiten flotar. Se alimenta de electricidad.",
			[82] = "Realmente son tres MAGNEMITE unidos por un campo magnético. Provocan tormentas magnéticas.",
			[83] = "No puede vivir sin el palo que lleva. Por eso lo protege de sus atacantes con todas sus fuerzas.",
			[84] = "Parece que los cerebros de sus dos cabezas se comunican por telepatía.",
			[85] = "Cuando un DODUO evoluciona, una de sus cabezas se divide en dos. Corre a unos 60 km por hora.",
			[86] = "Este Pokémon vive en icebergs. Nada en el mar y usa el cuerno de su cabeza para romper el hielo.",
			[87] = "Está cubierto de un luminoso pelaje blanco que lo camufla en la nieve.",
			[88] = "Emergió del lodo que se formó en agua contaminada expuesta a los rayos X lunares. Vive en la basura.",
			[89] = "Su cuerpo segrega un fluido tóxico que elimina la vida vegetal cuando la toca.",
			[90] = "Nada hacia atrás abriendo y cerrando su concha. Su gran lengua siempre queda colgando.",
			[91] = "En la lucha se protege cerrando su concha y lanzando pinchos a sus oponentes.",
			[92] = "El cuerpo de este Pokémon está compuesto en un 95% de gases que el viento puede arrastrar.",
			[93] = "Puede atravesar cualquier obstáculo. Atraviesa las paredes para espiar a sus enemigos.",
			[94] = "Se esconde entre las sombras. Se dice que donde GENGAR acecha, la temperatura baja 5 grados.",
			[95] = "Cuando viaja bajo tierra causa temblores y estruendo. Se puede mover a 80 km por hora.",
			[96] = "Puede oler los sueños de la gente con su gran nariz. Le encantan los sueños divertidos.",
			[97] = "Mirar su péndulo puede inducir al sueño en tres segundos, incluso si acabas de despertarte.",
			[98] = "Vive en madrigueras excavadas en playas arenosas. Sus pinzas vuelven a crecer si se rompen.",
			[99] = "La pinza mayor tiene 10000 caballos de potencia, pero es tan grande que le cuesta usarla.",
			[100] = "Parece una Poké Ball. Es muy peligroso, ya que puede lanzar descargas o explotar si se toca.",
			[101] = "Se lo lleva el viento si se hincha con la electricidad que almacena.",
			[102] = "Estos seis huevos se comunican por telepatía. Si se separan se pueden reunir rápidamente.",
			[103] = "Se le llama la “selva andante”. Si una cabeza crece demasiado, se cae y forma un EXEGGCUTE.",
			[104] = "Llora cuando se acuerda de su madre fallecida. Cuando lo hace, sus llantos resuenan en su cráneo.",
			[105] = "Este Pokémon salvaje maneja huesos constantemente desde su nacimiento y los usa como armas.",
			[106] = "Sus piernas se extienden hasta doblar su longitud para sorprender a enemigos desprevenidos.",
			[107] = "Los potentes golpes de sus brazos pueden pulverizar el hormigón. Descansa tras luchar tres minutos.",
			[108] = "En vez de manos usa la lengua, que mide el doble que su cuerpo. Su saliva pegajosa lo atrapa todo.",
			[109] = "Los gases de su cuerpo le permiten flotar. Estos gases, además de oler mal, también son explosivos.",
			[110] = "Crece alimentándose de los gases emanados por la basura. Se han dado raros casos de trillizos.",
			[111] = "Su cuerpo está protegido por una gruesa piel. Puede derribar hasta edificios, pero no es muy listo.",
			[112] = "Su cerebro se desarrolló cuando se levantó sobre dos patas. Con su cuerno puede cavar túneles.",
			[113] = "Se dice que reparte felicidad. Es compasivo y reparte sus huevos entre la gente herida.",
			[114] = "Está envuelto en lianas azules. Nadie ha logrado ver el rostro que se oculta tras ellas.",
			[115] = "Lleva a su cría en la bolsa de su panza. Solo deja que su cría salga a jugar cuando no siente peligro.",
			[116] = "Hace su nido entre los corales. Si se siente en peligro, escupe tinta y huye.",
			[117] = "Se protege con sus púas. Sus aletas y huesos son muy valorados por la medicina tradicional.",
			[118] = "Nada elegantemente moviendo la aleta de su cola como un vestido. Parece una reina.",
			[119] = "Hace su nido en los agujeros que cava con el cuerno. Defiende sus huevos con su vida.",
			[120] = "Puede recuperar las extremidades que pierde si mantiene intacto su núcleo rojo, que brilla en la noche.",
			[121] = "El centro de su cuerpo alberga un órgano que emite extrañas señales de radio en la noche.",
			[122] = "Es un experto mimo que puede crear paredes invisibles pero sólidas solo con sus gestos.",
			[123] = "Es casi imposible evitar el ataque de sus guadañas. Se mueve como un ninja.",
			[124] = "Sus gritos se parecen al lenguaje humano, pero es imposible entender lo que dice.",
			[125] = "La mitad de los apagones los provoca el enorme apetito de este Pokémon que come electricidad.",
			[126] = "Nació en el centro de un volcán. Su cuerpo está cubierto de llamas que brillan como el Sol.",
			[127] = "Atrapa presas con sus pinzas hasta que las parte en dos. Lanza lejos lo que no puede quebrar.",
			[128] = "Cuando elige una presa, ataca sin pensárselo. Este Pokémon es famoso por su carácter violento.",
			[129] = "Se dice que es el Pokémon más débil del mundo. No se sabe cómo ha logrado sobrevivir.",
			[130] = "Cuando se enfada, su rabia solo se disipa tras arrasar los campos y montañas vecinos.",
			[131] = "Le encanta surcar los mares con gente y Pokémon en su lomo. Entiende el lenguaje humano.",
			[132] = "Puede alterar por completo su estructura celular para emular cualquier objeto que vea.",
			[133] = "Un extraño Pokémon que se adapta a los entornos más hostiles gracias a sus diferentes evoluciones.",
			[134] = "Ha evolucionado para adaptarse a la vida acuática. Se mimetiza a la perfección con el agua.",
			[135] = "Lanza rayos de 10000 voltios. Es capaz de convertir su pelaje en púas afiladísimas.",
			[136] = "Almacena llamas en su cuerpo, que alcanza una temperatura de 900 grados antes de un combate.",
			[137] = "Es el primer Pokémon creado de forma artificial. Puede viajar por el ciberespacio.",
			[138] = "Fue recuperado a partir de un fósil gracias a la ciencia moderna. Solía nadar en antiguos mares.",
			[139] = "Se cree que este Pokémon se extinguió porque su concha espiral creció demasiado.",
			[140] = "Se cree que habitó las playas hace 300 millones de años. Se protege con una dura concha.",
			[141] = "Se cree que este Pokémon cambió de hábitat y pasó del mar a la tierra buscando nuevas presas.",
			[142] = "Este Pokémon surcó los cielos en la época de los dinosaurios. Sus colmillos son muy afilados.",
			[143] = "Su estómago puede digerir todo tipo de comida, incluso si está podrida o mohosa.",
			[144] = "Legendario Pokémon pájaro capaz de generar ventiscas congelando la humedad del aire.",
			[145] = "Legendario Pokémon pájaro del que se dice que vive en los nubarrones. Controla los rayos eléctricos.",
			[146] = "Uno de los legendarios Pokémon pájaro. Dicen que su presencia anuncia la llegada de la primavera.",
			[147] = "Se le llama el “Pokémon espejismo” porque son muy pocos los que lo han visto. Se encontró su muda.",
			[148] = "Si su cuerpo está rodeado de un aura, el tiempo cambia de repente. Se dice que vive en mares y lagos.",
			[149] = "Se dice que vive en algún lugar del mar. Guía a las tripulaciones de los barcos hundidos a la costa.",
			[150] = "Pokémon creado por recombinación genética de MEW. Se dice que es el más salvaje de los Pokémon.",
			[151] = "Varios científicos lo consideran el antecesor de los Pokémon porque usa todo tipo de movimientos.",
			[152] = "Con la hoja de su cabeza puede medir la temperatura y la humedad. Le encanta tomar el sol.",
			[153] = "Su cuello desprende un dulce aroma que anima a quien lo huele.",
			[154] = "Su aliento tiene la maravillosa capacidad de revivir plantas y flores muertas.",
			[155] = "Es un Pokémon muy tímido. Si se asusta, las llamas de su lomo arden con más fuerza.",
			[156] = "Intimida a sus enemigos con el calor de sus llamas. Arde con mayor fuerza cuando va a luchar.",
			[157] = "Ataca con llamaradas. Con ellas crea reflejos de calor para ocultarse.",
			[158] = "Tiene costumbre de morderlo todo con sus poderosas mandíbulas, incluso entrenadores.",
			[159] = "Cuando muerde algo, no lo suelta hasta que pierde sus colmillos. Estos se regeneran rápidamente.",
			[160] = "Se suele mover lento, pero alcanza velocidades de vértigo al atacar y morder a sus enemigos.",
			[161] = "Es de naturaleza nerviosa. Se alza sobre su cola para otear grandes extensiones.",
			[162] = "Acurruca a sus crías para que duerman. Acorrala a los enemigos con su enorme velocidad.",
			[163] = "Siempre se yergue sobre una pata. Nunca apoya ambas, ni siquiera al sufrir un ataque.",
			[164] = "Sus ojos son especiales: pueden distinguir objetos siempre y cuando haya algo de luz.",
			[165] = "Es tan temeroso que no se mueve si no es en grupo. Comunica sus sentimientos con olores.",
			[166] = "Se nutre de la luz de las estrellas. Cuanto más estrellada es la noche, más crecen los dibujos de su lomo.",
			[167] = "Pone trampas tejiendo una red de seda fina y resistente y luego espera inmóvil a su presa.",
			[168] = "Pega hilos de seda a sus presas y las libera para seguirlas más tarde y localizar también a sus amigos.",
			[169] = "Sus cuatro alas le permiten volar más rápida y sigilosamente. Es un Pokémon nocturno.",
			[170] = "Libera cargas eléctricas positivas y negativas con sus antenas para aturdir a sus enemigos.",
			[171] = "La luz de LANTURN se puede ver desde lo más profundo. Se le llama la “estrella de alta mar”.",
			[172] = "Las bolsas de sus mejillas son aún demasiado pequeñas para almacenar mucha electricidad.",
			[173] = "Tiene forma de estrella. Se cree que llega cabalgando sobre estrellas fugaces.",
			[174] = "Su cuerpo es suave y está hinchado. Cuando empieza a botar, no puede parar.",
			[175] = "Se dice que su cascarón está lleno de alegría que comparte con las personas de buen corazón.",
			[176] = "Se dice que se aparece a la gente de buen corazón y que esparce un “polvillo de la alegría”.",
			[177] = "Recoge alimento de los cactos evitando los pinchos. Se mueve dando saltos.",
			[178] = "Este extraño Pokémon puede ver el pasado y el futuro. Se pasa el día mirando al sol.",
			[179] = "Su pelaje lanudo dobla su volumen al acumular electricidad estática. Tocarlo puede dar calambre.",
			[180] = "Cuando su pelaje se carga de electricidad, su cola se enciende. Lanza pelo que explota al impacto.",
			[181] = "La punta de su cola brilla. Antiguamente la gente enviaba señales con ella.",
			[182] = "Cuando acaba la estación de las lluvias, sale al sol e inicia una peculiar danza.",
			[183] = "Bucea usando su cola a modo de boya. Le gusta comer las plantas del fondo fluvial.",
			[184] = "Vive en ríos y lagos. En el agua, sus colores y dibujos confunden a los enemigos.",
			[185] = "Aunque parezca un árbol, su cuerpo se asemeja a las rocas y piedras. Es débil frente al agua.",
			[186] = "Agrupa a otros Pokémon para liderarlos. Los POLIWAG obedecen su voz.",
			[187] = "Flotan en el aire. Se dice que cuando los HOPPIP se reúnen, es que la primavera está al caer.",
			[188] = "Florece en épocas cálidas. Flota en el aire para absorber toda la luz solar que puede.",
			[189] = "Los vientos estacionales lo llevan por todo el mundo, donde suelta sus esporas para reproducirse.",
			[190] = "Usa su cola para recoger la fruta que no está a su alcance. Su cola es más hábil que sus manos.",
			[191] = "Cae de repente del cielo por las mañanas. Los años de veranos suaves su número se multiplica.",
			[192] = "Obtiene energía de la luz solar. Este Pokémon es famoso por su heliotropismo.",
			[193] = "Su campo visual es de 360 grados sin girar la cabeza. Detecta hasta las presas que están a su espalda.",
			[194] = "Vive en aguas frías. Para dormir se entierra a medias en el lodo del fondo.",
			[195] = "Es un Pokémon bastante perezoso. Para pescar permanece en el fondo del río con la boca abierta.",
			[196] = "Su pelaje es como el terciopelo. La esfera de su frente brilla cuando usa sus poderes psíquicos.",
			[197] = "Creado cuando la luz lunar alteró la estructura genética de EEVEE. Busca presas en la oscuridad.",
			[198] = "Se dice que ver a este Pokémon por la noche es señal de que van a ocurrir cosas terribles.",
			[199] = "Al ser mordido por un SHELLDER desarrolló una inteligencia propia de un ganador del premio Nobel.",
			[200] = "Le encanta sorprender a la gente de noche y asustarla con sus estridentes gritos.",
			[201] = "Tienen forma de letras antiguas. Se desconoce qué fue antes: si la escritura o los UNOWN.",
			[202] = "Siempre intenta ocultar su cola, por lo que muchos creen que contiene un secreto.",
			[203] = "Su cola tiene un pequeño cerebro y muerde a los enemigos que intentan acercarse por la espalda.",
			[204] = "Es como una piña piñonera. Su coraza lo protege de los pájaros que lo picotean por error.",
			[205] = "Se protege con su concha de acero de tal manera que solo se pueden ver sus ojos.",
			[206] = "Cava el suelo con su cola para construir su madriguera. Puede volar distancias cortas.",
			[207] = "Ataca desde el aire con sus extremidades extendidas. Va directo a la cara de su oponente.",
			[208] = "Su cuerpo es más duro que cualquier metal debido a la gran presión y calor de su hábitat.",
			[209] = "Los Pokémon pequeños huyen al ver su cara agresiva. No obstante, para muchas féminas es mono.",
			[210] = "A pesar de su aspecto, es muy tímido. Sin embargo, cuando se enfada ataca con sus colmillos.",
			[211] = "Lanza púas venenosas en todas direcciones. Debido a su forma redonda, es muy mal nadador.",
			[212] = "Su cuerpo es duro como el acero. Confunde a los rivales con los dibujos de ojos en sus pinzas.",
			[213] = "Almacena bayas en su caparazón, que más tarde fermentan para producir deliciosos zumos.",
			[214] = "Forman grupos en los bosques para buscar savia de árboles, su comida favorita. Puede voltear a su presa.",
			[215] = "Se alimenta de huevos robados en nidos. Clava sus afiladas garras en los puntos débiles de sus rivales.",
			[216] = "Deja que la miel se le pegue a las garras para lamerla más tarde. Cada una de ellas sabe diferente.",
			[217] = "Araña los árboles de su territorio que dan bayas y frutas que le gustan para marcarlos.",
			[218] = "Su cuerpo se compone de magma. Si deja de moverse, se enfría y se endurece.",
			[219] = "Su cuerpo está a una temperatura de 10000 grados. De las fisuras de su cuerpo escapan llamas.",
			[220] = "Le encanta comer las setas que crecen bajo la hierba seca. A veces descubre aguas termales.",
			[221] = "Como su pelaje le impide ver, estudia lo que le rodea con su potente olfato.",
			[222] = "Muchos viven en los cristalinos mares del sur. Son incapaces de vivir en aguas contaminadas.",
			[223] = "Escupe potentes chorros de agua para derribar presas voladoras.",
			[224] = "Se refugia en los agujeros de las rocas y el fondo marino. Sus ventosas son muy potentes.",
			[225] = "Lleva alimentos en su saco. Le gusta compartir su comida con los montañistas perdidos.",
			[226] = "Cuando el mar está en calma, se pueden ver bancos de MANTINE nadando como si volasen.",
			[227] = "Una armadura de hierro cubre por completo su cuerpo. Vuela a más de 300 km por hora.",
			[228] = "Se comunica mediante gritos y colabora en manada para atacar a sus presas.",
			[229] = "Hace mucho, la gente creía que sus horripilantes aullidos eran de la muerte personificada.",
			[230] = "Vive en cavernas del fondo marino y crea grandes remolinos cuando se mueve.",
			[231] = "A pesar de su tamaño reducido, es tan fuerte que puede llevar a un humano a su espalda con facilidad.",
			[232] = "Se enrolla sobre sí mismo y se lanza rodando contra el enemigo. Puede derribar casas de un golpe.",
			[233] = "Tiene instalado un avanzado software astrofísico que le permite trabajar en el espacio.",
			[234] = "Mirar a su cornamenta provoca una extraña sensación de pérdida de equilibrio.",
			[235] = "Marca su territorio usando su cola a modo de pincel. Ha hecho más de 5000 marcas diferentes.",
			[236] = "Famoso por su disposición a la lucha. Siempre tiene heridas por luchar con enemigos más grandes.",
			[237] = "Gira a gran velocidad al luchar. La fuerza centrífuga multiplica su poder de destrucción por diez.",
			[238] = "Analiza todo tocándolo con los labios. Así puede recordar las cosas que le gustan y disgustan.",
			[239] = "Genera electricidad girando los brazos. No obstante, es incapaz de almacenar la energía creada.",
			[240] = "Su temperatura corporal es de unos 600 grados. Si está sano, escupe llamas amarillas.",
			[241] = "Se dice que si un niño bebe leche de MILTANK crecerá y se convertirá en un adulto sano y campechano.",
			[242] = "Este amable Pokémon cuida de Pokémon enfermos y los sana. Puede presentir la tristeza.",
			[243] = "Dicen que apareció con un relámpago. Puede lanzar rayos desde las nubes de su lomo.",
			[244] = "Se dice que, cuando ruge, un volcán entra en erupción en algún punto del globo.",
			[245] = "Recorre el mundo para purificar agua contaminada. Corre veloz con el viento del norte.",
			[246] = "Este Pokémon come tierra. Cuando se come una montaña, se echa a dormir para crecer.",
			[247] = "Su cuerpo es duro como la roca. Se autopropulsa como un cohete soltando los gases de su interior.",
			[248] = "Puede alterar el paisaje derribando montañas y enterrando ríos. Da mucho trabajo a los cartógrafos.",
			[249] = "Duerme en una dorsal marina. Si bate sus alas puede causar tormentas de cuarenta días.",
			[250] = "Su plumaje tiene siete colores. Se dice que verlo proporciona felicidad eterna.",
			[251] = "Puede viajar en el tiempo, pero se dice que solo aparece en tiempos de paz.",
			[252] = "Las plantas de sus pies tienen púas diminutas que le permiten andar por paredes y techos.",
			[253] = "Vive en selvas frondosas. Salta de rama en rama para acercarse a sus presas.",
			[254] = "Las hojas de sus brazos pueden cortar gruesos árboles. Invencible en los combates en la jungla.",
			[255] = "En su interior arde una llama que mantiene su cuerpo caliente. Tira bolas de fuego a 1000 grados.",
			[256] = "Su habilidad le permite dar diez patadas por segundo. Lanza potentes gritos para intimidar.",
			[257] = "Sus puños están envueltos en llamas. Con sus golpes puede quemar a sus rivales.",
			[258] = "La aleta de su cabeza detecta las corrientes de agua y los peligros. Tiene fuerza para levantar rocas.",
			[259] = "Sus piernas robustas impiden que pierda el equilibrio y caiga, incluso en el barro. Duerme bajo la arena.",
			[260] = "Puede nadar y arrastrar un barco grande. Golpea a sus enemigos con sus gruesos brazos.",
			[261] = "Es muy persistente. Si se fija en una presa, no la dejará hasta que caiga agotada.",
			[262] = "Ataca a sus presas en manada. Nunca desobedece las órdenes de un entrenador avezado.",
			[263] = "Se mueve en zigzag. Se le da bien encontrar objetos ocultos en la hierba e incluso enterrados.",
			[264] = "Carga contra sus enemigos a más de 100 km por hora. Como solo va en línea recta, falla a menudo.",
			[265] = "Le encanta comer hojas. Si le ataca un STARLY, se defenderá con sus púas.",
			[266] = "La seda que segrega su cuerpo le permite agarrarse a los árboles y esperar su evolución.",
			[267] = "Es un Pokémon agresivo. Con su boca larga y afilada ataca a sus rivales para drenar sus fluidos.",
			[268] = "Mantiene el calor en su capullo. Dedica todas las células de su cuerpo a evolucionar.",
			[269] = "Pokémon nocturno. Atraído por las luces de la ciudad, se come las hojas y arbustos de las avenidas.",
			[270] = "Parece una planta acuática. Hace de ferry para los Pokémon que no saben nadar.",
			[271] = "Tiene carácter travieso. Si ve un pescador, tira del anzuelo para confundirlo.",
			[272] = "Cuando oye música alegre sus músculos se llenan de energía y no puede evitar ponerse a bailar.",
			[273] = "Cuando cuelga de las ramas parece una bellota. Le encanta asustar a otros Pokémon.",
			[274] = "Cuando usa la hoja de su cabeza como flauta asusta a la gente. Vive en lo más profundo de los bosques.",
			[275] = "Con sus abanicos puede provocar vientos de 30 m por segundo capaces de levantar casas.",
			[276] = "Es un Pokémon valiente que no teme a los rivales fuertes. Vuela en busca de climas templados.",
			[277] = "Vuela en círculos en busca de presas. Cuando ve una, se lanza sin dudarlo.",
			[278] = "Anida en acantilados y alcanza gran altura aprovechando las corrientes ascendentes.",
			[279] = "Hunde su gran pico en el mar para sacar numerosas presas junto con mucha agua.",
			[280] = "Su cuerno le permite presentir las emociones humanas. Se dice que se aparece a la gente amable.",
			[281] = "Puede percibir los sentimientos de su entrenador. Cuando se siente feliz, baila.",
			[282] = "Protegerá al entrenador que le merezca la pena con su último aliento. Puede ver el futuro.",
			[283] = "Parece que patina sobre el agua. Atrae a las presas con el suave aroma de su cabeza.",
			[284] = "Sus antenas tienen dibujos de ojos, mientras que sus alas le permiten volar en cualquier dirección.",
			[285] = "Lanza esporas venenosas desde la parte superior de la cabeza. Inhalarlas es muy doloroso.",
			[286] = "Sus cortos brazos se expanden cuando da puñetazos. Tiene una técnica pugilística muy depurada.",
			[287] = "Pasa la mayor parte del día repanchingado. Entra sueño solo de verlo.",
			[288] = "Su corazón late a un ritmo diez veces más rápido de lo normal. No se está quieto ni un instante.",
			[289] = "El Pokémon más perezoso del mundo. Si está tumbado, es que reúne fuerzas para contraatacar.",
			[290] = "Crece bajo tierra y explora el entorno con sus antenas, que sustituyen a ojos atrofiados.",
			[291] = "Se mueve tan rápido que a veces resulta invisible. Le atrae la savia de los árboles.",
			[292] = "Es el caparazón de un bicho que cobró vida. Si alguien lo mira por la espalda, le robará el alma.",
			[293] = "Suele murmurar a un volumen casi inaudible, pero cuando se asusta grita con el volumen de un reactor.",
			[294] = "Las ondas de sus gritos pueden voltear un camión. Patea el suelo para ganar potencia.",
			[295] = "Su aullido se puede oír a 10 km. Emite todo tipo de sonidos desde los tubos de su cuerpo.",
			[296] = "Endurece su cuerpo golpeando grandes árboles. Cerca de su hogar suele haber árboles golpeados.",
			[297] = "Le encanta enfrentarse a Pokémon grandes y probar su fuerza. Sus brazos pueden derribar un camión.",
			[298] = "Vive cerca del agua. En la tierra se mueve muy rápido botando sobre su gran cola.",
			[299] = "Su nariz es un imán. Por eso el rostro de este Pokémon siempre se orienta al norte.",
			[300] = "No puede evitar ir tras las cosas que se mueven. Hasta corre en círculos persiguiéndose la cola.",
			[301] = "Tiene mucho éxito entre las entrenadoras por su suave pelaje. No vive en un sitio fijo.",
			[302] = "Se oculta en cavernas oscuras. De tanto comer gemas sus ojos son piedras preciosas.",
			[303] = "Las grandes fauces de su cabeza están formadas por cuernos. Puede romper el hierro con ellas.",
			[304] = "Suele vivir en lugares inaccesibles de las montañas, pero el hambre lo empuja a comer raíles y coches.",
			[305] = "Extrae hierro para alimentarse y usa su cuerpo de acero para luchar y conseguir territorio.",
			[306] = "Mientras busca hierro para comer, excava túneles en la roca con sus potentes cuernos de acero.",
			[307] = "Solo come una baya al día. El ayuno fortalece su espíritu y su capacidad de concentración.",
			[308] = "El yoga ha perfeccionado su sexto sentido. Sus movimientos son extremadamente elegantes.",
			[309] = "Estimula sus músculos y aumenta sus reflejos con la electricidad que almacena su pelaje.",
			[310] = "Descarga electricidad desde su melena. Crea nubarrones desde los que lanza rayos.",
			[311] = "Anima a sus compañeros con pompones de chispas. Roba energía de los postes telefónicos.",
			[312] = "Le gusta animar a sus amigos. Si pierden, su cuerpo suelta cada vez más chispas.",
			[313] = "Se comunica con otros iluminando su cola por la noche. Le encanta el suave aroma de ILLUMISE.",
			[314] = "Su suave aroma guía a VOLBEAT para que haga señales luminosas en el cielo nocturno.",
			[315] = "Si este Pokémon crece con agua limpia y potable, le brotarán flores de vivos colores.",
			[316] = "Casi todo su cuerpo es estómago. Sus potentes jugos gástricos disuelven rápido cualquier cosa.",
			[317] = "Se traga cualquier cosa de una pieza. Sus poros segregan fluidos tóxicos que dañan a sus enemigos.",
			[318] = "Rodean a los enemigos que osan invadir su territorio. Sus afilados colmillos dañan los barcos.",
			[319] = "Con sus colmillos puede atravesar el acero. Nada a 120 km por hora. Le llaman el “terror de los mares”.",
			[320] = "En días soleados se tumba en las playas para jugar y botar como una pelota. Lanza agua por la nariz.",
			[321] = "Es el más grande de los Pokémon. Puede nadar a una profundidad de 3000 m aguantando la respiración.",
			[322] = "En su joroba almacena magma ardiente que se enfría cuando llueve y lo ralentiza.",
			[323] = "Tiene volcanes en el lomo. Si el magma se acumula en su cuerpo, se sacude y estalla con violencia.",
			[324] = "Quema carbón en su caparazón para obtener energía. Si le atacan, echa un denso humo negro.",
			[325] = "Bota continuamente usando su cola como muelle. Salta para mantener el latido de su corazón.",
			[326] = "Usa perlas negras para potenciar sus poderes psíquicos. Con su raro baile controla a los rivales.",
			[327] = "No hay dos SPINDA que tengan idénticos pelajes. Su tambaleo al bailar confunde a los rivales.",
			[328] = "Cava fosas cóncavas en el desierto y espera en el fondo a que las presas caigan en ellas.",
			[329] = "Agita violentamente sus alas para crear ondas ultrasónicas que provocan dolores de cabeza.",
			[330] = "Levanta tormentas de arena con sus alas. Se le conoce como el “alma del desierto”.",
			[331] = "Habita en el desierto. Aguanta treinta días sin agua gracias a la que almacena en su cuerpo.",
			[332] = "Es un Pokémon nocturno. Busca presas agotadas por el calor diurno del desierto.",
			[333] = "Sus alas parecen nubes de algodón. Si se posa sobre una cabeza, tiene pinta de gorro.",
			[334] = "Cuando vuela, parece una nube de algodón. Entona bellas melodías con su voz de soprano.",
			[335] = "Hace muchos años que se enfrenta a SEVIPER. Su arma más eficaz son sus zarpas afiladas.",
			[336] = "Se ha enfrentado durante muchos años a ZANGOOSE. Usa rocas para mantener afilada su cola.",
			[337] = "Se piensa que está muy influido por las fases lunares, ya que solo actúa en noches de luna llena.",
			[338] = "Una nueva especie de Pokémon que se rumorea procede del Sol. Emite luz al girar.",
			[339] = "Recubre su cuerpo de una película viscosa que le permite escapar si alguien lo agarra.",
			[340] = "Es muy territorial. Expulsa a los intrusos con unos temblores que se sienten en un radio de 5 km.",
			[341] = "Su organismo le permite adaptarse a cualquier entorno. Sus pinzas nunca sueltan a su presa.",
			[342] = "Este malandrín usa sus pinzas para atosigar y expulsar a los otros Pokémon que viven en su estanque.",
			[343] = "Se mueve girando sobre su eje. Es un extraño Pokémon que fue encontrado en unas viejas ruinas.",
			[344] = "Este Pokémon es una vieja figurilla de barro que cobró vida mediante la exposición a extraños rayos de luz.",
			[345] = "Vivió en los fondos marinos hace unos 100 millones de años y fue recreado científicamente.",
			[346] = "Vive en el fondo de los mares de aguas templadas. Emerge para cazar cuando baja la marea.",
			[347] = "Este Pokémon fue recreado a partir de restos fósiles. Vivía en el mar y cazaba con sus pinzas.",
			[348] = "Tras evolucionar, este Pokémon fue a tierra firme. Una dura coraza protege todo su cuerpo.",
			[349] = "Se caracterizan por su aspecto endeble. Se agrupan en gran número en lugares muy concretos.",
			[350] = "Se dice que emerge del fondo de los lagos cuando la gente discute para apaciguarla.",
			[351] = "La meteorología determina su aspecto. Hace poco se ha sabido que sus células son como el agua.",
			[352] = "Puede mudar el color de su cuerpo a voluntad, pero el dibujo en zigzag de su panza nunca desaparece.",
			[353] = "Les atraen los sentimientos de rencor y celos. Suelen vivir cerca de las casas de gente vengativa.",
			[354] = "Este muñeco se convirtió en un Pokémon cuando lo tiraron a la basura. Busca a su antiguo dueño.",
			[355] = "Persigue a su presa como un perro allá donde vaya. No obstante, abandona la caza al amanecer.",
			[356] = "Su cuerpo está hueco. Se dice que quien mire dentro, será tragado por un agujero negro.",
			[357] = "Como solo comía su fruta favorita, al final terminó creciéndole en su propio cuello.",
			[358] = "Sus gritos sacuden el aire para derribar a los rivales voladores. Habla con siete tipos de gritos.",
			[359] = "Presiente desastres inminentes y se aparece a la gente para advertir del peligro.",
			[360] = "Se fortalecen empujándose unos a otros en grupos. Les encantan los dulces.",
			[361] = "En las zonas nevadas, las leyendas dicen que si un SNORUNT vive en una casa, trae prosperidad.",
			[362] = "Se protege con una armadura de hielo creada por congelación de la humedad del aire.",
			[363] = "Rueda por los témpanos de hielo hasta la orilla, ya que su cuerpo no está bien adaptado para nadar.",
			[364] = "Suele hacer girar objetos en su nariz. De esta forma aprende texturas y olores.",
			[365] = "Rompe el hielo con sus colmillos. Su gruesa capa de grasa le protege del frío y de los enemigos.",
			[366] = "Durante toda su vida, crea una sola perla que, según se dice, aumenta los poderes psíquicos.",
			[367] = "Vive en los fondos marinos. Atrae a sus confiadas presas con la cola, que tiene forma de pez.",
			[368] = "Vive en el fondo del mar. En primavera, su cuerpo rosado adquiere colores más vivos.",
			[369] = "Un Pokémon raro descubierto en una exploración marina. No ha cambiado en más de 100 millones de años.",
			[370] = "Vive en mares cálidos. Se dice que, si una pareja lo encuentra, será bendecida con amor eterno.",
			[371] = "Sueña con volar algún día, por lo que siempre practica saltando desde acantilados.",
			[372] = "Las células han empezado a cambiar dentro de su dura concha, que se separa cuando evoluciona.",
			[373] = "Siempre soñó con volar, por lo que su estructura celular cambió y le crecieron alas.",
			[374] = "Se comunican mediante pulsos magnéticos. Cuando van en grupos, se mueven al unísono.",
			[375] = "Lo forman dos BELDUM unidos. Puede chocarse con un avión sin que su cuerpo de acero sufra ni rasguño.",
			[376] = "Está formado por varios METANG. Con cuatro cerebros, tiene la inteligencia de un superordenador.",
			[377] = "Su cuerpo está hecho de roca. Si se astilla durante el combate, emplea piedras para repararlo.",
			[378] = "Su cuerpo está hecho con hielo de la glaciación. Controla aire gélido a 200 grados bajo cero.",
			[379] = "Su cuerpo ha estado sometido a la presión subterránea durante miles de años y no puede arañarse.",
			[380] = "Su cuerpo está cubierto de un plumón que refleja la luz de forma que se vuelve invisible.",
			[381] = "Es un Pokémon muy inteligente. Puede adelantar a aviones a reacción plegando las alas.",
			[382] = "Se dice que aumentó el nivel del mar a base de aguaceros. Ha estado durmiendo en una fosa marina.",
			[383] = "Ha estado durmiendo en magma subterráneo desde que luchó contra KYOGRE en tiempos remotos.",
			[384] = "Vive en la capa de ozono sobre las nubes y no puede ser visto desde el suelo.",
			[385] = "Se dice que puede otorgar cualquier deseo durante una semana cada mil años.",
			[386] = "Surgió a raíz de la mutación de ADN de un virus alienígena que cayó a la Tierra en un meteorito.",
			[387] = "La concha de su espalda es de tierra y se endurece cuando bebe agua. Vive cerca de los lagos.",
			[388] = "Vive en los bosques cerca del agua. Por el día, sale a que les dé el sol a las plantas de su espalda.",
			[389] = "Algunos Pokémon pequeños se juntan en su espalda para hacer sus nidos.",
			[390] = "Escala acantilados escarpados con agilidad. Vive en las montañas y su fuego se apaga cuando duerme.",
			[391] = "Intimida a sus enemigos desplegando el fuego de su cola para parecer más grande.",
			[392] = "Utiliza un tipo especial de artes marciales con todos sus miembros. Su fuego nunca se extingue.",
			[393] = "Es muy orgulloso, por lo que odia aceptar comida de la gente. Su grueso plumón le protege del frío.",
			[394] = "Vive solo, alejado de los demás. Cada uno piensa que es el más importante.",
			[395] = "Los tres cuernos de su pico son muestra de su fuerza. El líder tiene los cuernos más grandes.",
			[396] = "Viaja en grandes bandadas. Aunque es pequeño, agita las alas con gran fuerza.",
			[397] = "Vuela por bosques y campos en busca de Pokémon de tipo Bicho. Siempre va en bandadas.",
			[398] = "Tiene un carácter salvaje. No duda en desafiar a rivales mucho mayores.",
			[399] = "Tiene nervios de acero y nada puede perturbarlo. Es más ágil y activo de lo que aparenta.",
			[400] = "Para anidar, crea presas en los ríos con maderas y barro. Tiene fama de trabajador.",
			[401] = "Al agitar la cabeza de atrás hacia delante, sus antenas chocan y suenan como un xilófono.",
			[402] = "Cuando llora, cruza sus brazos con forma de cuchillo. Puede improvisar melodías.",
			[403] = "Si siente peligro, todo su pelaje brilla. Aprovecha la ceguera temporal de su rival para huir.",
			[404] = "Sus garras emiten electricidad que puede debilitar a sus rivales. Viven en grupos pequeños.",
			[405] = "Sus ojos pueden ver a través de todo. Localiza a las presas detrás de objetos y las captura.",
			[406] = "En invierno cierra su capullo para protegerse del frío. En primavera, el capullo se abre y esparce polen.",
			[407] = "Atrae a las presas con un dulce aroma y las derrota con los látigos espinosos de sus brazos.",
			[408] = "Vivía en la jungla hace unos 100 millones de años. Su cráneo es tan duro como el hierro.",
			[409] = "Su potente cabezazo puede hacer añicos cualquier cosa.",
			[410] = "Vivía en la jungla hace unos 100 millones de años. Su protección facial es tremendamente dura.",
			[411] = "Repele cualquier ataque frontal. Es muy dócil y se alimenta de hierba y bayas.",
			[412] = "Para protegerse de los vientos fríos invernales, se cubre con un caparazón de ramas y hojas.",
			[413] = "Cuando BURMY evolucionó, su caparazón pasó a formar parte de este Pokémon.",
			[414] = "Le encanta la miel de las flores y roba la que recoge COMBEE.",
			[415] = "Está formado por otros tres Pokémon. Le lleva miel floral a VESPIQUEN.",
			[416] = "Su abdomen es un panal de larvas que alimenta con la miel recogida por COMBEE.",
			[417] = "Crea bolas de pelo que crepitan con electricidad estática. Las almacena en agujeros de árboles.",
			[418] = "Posee un flotador en forma de collar hinchable. Flota en el agua con la cabeza fuera.",
			[419] = "Nada gracias a su flotador. Ayuda en los rescates de gente que se está ahogando.",
			[420] = "La pequeña esfera, dulce y sabrosa, contiene los nutrientes necesarios para evolucionar.",
			[421] = "Florece en épocas de mucha luz solar. Intenta compensar lo que soportó como capullo.",
			[422] = "El color y la forma varían según la región. En Sinnoh, hay dos tipos confirmados.",
			[423] = "Posee un cuerpo flexible sin huesos. Si pierde alguna parte, le vuelve a crecer.",
			[424] = "Para comer, rompe nueces con sus dos colas. Raras veces utiliza sus brazos.",
			[425] = "Está formado por los espíritus de personas y Pokémon. Le encantan las estaciones húmedas.",
			[426] = "Durante el día está somnoliento, pero por la noche sale volando en grupo, aunque nadie sabe adónde.",
			[427] = "Ataca a sus enemigos con un golpe rápido de sus orejas. Sus picotazos son muy dolorosos.",
			[428] = "Es un Pokémon muy precavido. Si siente peligro, se envuelve con el pelaje de sus orejas.",
			[429] = "Sus gritos parecen cánticos. Los que los escuchan padecen migrañas y alucinaciones.",
			[430] = "Está activo por la noche y pulula arrastrando a numerosos MURKROW.",
			[431] = "Araña cuando está enfadado y ronronea cuando está cariñoso. Su imprevisibilidad es famosa.",
			[432] = "Es un bruto descarado que entra en el nido de cualquier Pokémon y se lo apropia.",
			[433] = "Emite chillidos al agitar la esfera de su garganta. Se mueve con enérgicos saltos.",
			[434] = "Se protege expulsando un fluido nocivo por su parte trasera. El hedor dura 24 horas.",
			[435] = "Para atacar, emite un fluido maloliente por la punta de su cola que puede llegar a más de 50 m.",
			[436] = "Se descubrieron herramientas con su forma en tumbas antiguas, pero se desconoce si tiene relación.",
			[437] = "Se produjo un gran revuelo cuando encontraron uno en una obra después de 2000 años durmiendo.",
			[438] = "Parece que siempre está llorando, pero en realidad está eliminando el exceso de fluidos corporales.",
			[439] = "Suele imitar a sus enemigos. Cuando lo hace, su rival no puede apartar los ojos de él.",
			[440] = "Le encantan las cosas blancas y redondas. Imita a CHANSEY llevando una roca con forma de huevo.",
			[441] = "Pueden aprender y hablar lenguas humanas. Si se juntan, todos aprenden las mismas palabras.",
			[442] = "Se formó a partir de 108 espíritus. Está unido a la fisura de una piedra angular mística.",
			[443] = "Anida en pequeños agujeros en las paredes de cuevas. Cuando una presa pasa cerca, salta hacia ella.",
			[444] = "Existe la arraigada creencia de que una medicina hecha de sus escamas puede curarlo todo.",
			[445] = "Cuando despliega su cuerpo y sus alas, parece un avión a reacción. Vuela a velocidad sónica.",
			[446] = "Engulle su peso en comida una vez al día. Se lo traga todo sin apenas masticar.",
			[447] = "Su aura se intensifica para alertar a otros cuando está triste o tiene miedo.",
			[448] = "Puede sentir el aura de todas las cosas. Comprende el lenguaje humano.",
			[449] = "Vive en zonas áridas. En lugar de sudar, su cuerpo expulsa granos de arena.",
			[450] = "Cuando ataca, expulsa arena almacenada en su interior para crear un gran tornado.",
			[451] = "Agarra a sus presas con las garras de la cola y les inyecta veneno. Espera hasta que hace efecto.",
			[452] = "Sus brazos tienen fuerza para destrozar un coche. La punta de sus zarpas segrega veneno.",
			[453] = "Tiene bolsas venenosas en las mejillas. Pilla desprevenidos a sus rivales para pincharles.",
			[454] = "Sus garras segregan una toxina tan potente que un simple arañazo puede ser mortal.",
			[455] = "Atrae a sus presas con saliva de olor dulce y las mastica. Tarda todo un día en comérselas.",
			[456] = "Si se expone mucho al sol, los dibujos de sus aletas brillan en la oscuridad.",
			[457] = "Vive en las profundidades marinas. Atrae a sus presas con parpadeos del dibujo de sus cuatro aletas.",
			[458] = "Un Pokémon amable que captura los débiles flujos de agua marina con sus dos antenas.",
			[459] = "Vive en montañas nevadas. Apenas tiene contacto con los humanos y es muy curioso.",
			[460] = "Es el abominable hombre de las nieves. Produce ventiscas en las montañas cubiertas de nieve.",
			[461] = "Viven en zonas frías y forman grupos de cuatro o cinco para cazar con gran coordinación.",
			[462] = "Evolucionó por la exposición a un campo magnético especial. Tres unidades generan magnetismo.",
			[463] = "Agarra cosas con su lengua extensible. Si te acercas mucho, te deja lleno de babas.",
			[464] = "Pone rocas en los agujeros de sus manos y las lanza con los músculos. Pocas veces ataca a GEODUDE.",
			[465] = "Atrapa a su presa desplegando las ramas de sus brazos, que no le importa perder ante depredadores.",
			[466] = "Toca a su enemigo con las puntas de sus dos colas y le suelta una descarga de más de 20000 voltios.",
			[467] = "Sus brazos disparan bolas de fuego de más de 2000 grados. Vive en cráteres volcánicos.",
			[468] = "Nunca aparece donde hay peleas. Últimamente no se deja ver muy a menudo.",
			[469] = "Agita sus alas para crear ondas de choque que producen lesiones internas a sus rivales.",
			[470] = "Al igual que una planta, hace la fotosíntesis. Como consecuencia, siempre está rodeado de aire puro.",
			[471] = "Para protegerse, puede congelar completamente su pelaje, de modo que los pelos parecen agujas.",
			[472] = "Espera a sus presas colgado de una rama bocabajo. Cuando llega su oportunidad, se lanza en picado.",
			[473] = "Sus impresionantes colmillos están hechos de hielo. Su población se redujo tras la glaciación.",
			[474] = "Se le instaló un software para mejorarlo. Sin embargo, comenzó a comportarse de manera extraña.",
			[475] = "Lucha con las espadas que salen de sus codos. Es un maestro de la cortesía y la esgrima.",
			[476] = "Emana un fuerte magnetismo. Controla tres pequeñas unidades llamadas Mini-Narices.",
			[477] = "La antena de la cabeza captura ondas de radio lejanas que le permiten secuestrar a gente.",
			[478] = "Congela a sus enemigos con un aliento gélido de 50 grados bajo cero. Está hueco por dentro.",
			[479] = "Su cuerpo está hecho de plasma. Puede infiltrarse en dispositivos electrónicos e inutilizarlos.",
			[480] = "Se le conoce como el “ser de la sabiduría”. Se dice que puede borrar la memoria con una mirada.",
			[481] = "Se le conoce como el “ser de la emoción”. Enseñó a los humanos la nobleza del dolor y la alegría.",
			[482] = "Se le conoce como el “ser de la voluntad”. Duerme en el fondo de un lago para equilibrar el mundo.",
			[483] = "Tiene el poder de controlar el tiempo. Aparece en los mitos de Sinnoh como una vieja deidad.",
			[484] = "Tiene la habilidad de distorsionar el espacio. La mitología de Sinnoh lo describe como una deidad.",
			[485] = "Habita cuevas volcánicas. Cava con sus pies en forma de cruz para trepar por techos y paredes.",
			[486] = "Una antigua leyenda afirma que este Pokémon arrastraba continentes con cuerdas.",
			[487] = "Se dice que vive en un mundo en el lado inverso del nuestro. Aparece en viejos cementerios.",
			[488] = "Sus alas emiten un velo de partículas brillantes. Se dice que representa un cuarto lunar.",
			[489] = "Vive en los mares cálidos. Infla el flotador de la cabeza para nadar en busca de comida.",
			[490] = "Nació en el frío fondo marino. Nada grandes distancias para regresar a su lugar de origen.",
			[491] = "Puede adormecer a la gente y hacerle soñar. Está activo en las noches de luna nueva.",
			[492] = "Vive entre las flores. Para evitar ser descubierto, se enrosca como si fuera una planta.",
			[493] = "La mitología lo describe como el Pokémon que dio forma al Universo con sus 1000 brazos.",
		},
		[705] = { -- species_pokedex_entry_jp
			[1] = "うまれてから しばらくの あいだは せなかの タネから えいようを もらって おおきく そだつ。",
			[2] = "せなかの つぼみが ふくらみだすと あまい においが ただよいはじめる。 たいりんの はなが さく まえぶれ。",
			[3] = "あめの ふった よくじつは せなかの はなの かおりが つよまる。かおりに さそわれ ポケモンが あつまる。",
			[4] = "ヒトカゲの しっぽの ほのおは いのちの ともしび。げんきな ときは ほのおも ちからづよく もえあがる。",
			[5] = "リザ－ドが くらす いわやまを よなかに みあげると しっぽの ほのおが ほしのように みえる。",
			[6] = "くるしい たたかいを けいけんした リザ－ドンほど ほのおの おんどが たかくなると いわれている。",
			[7] = "こうらに とじこもり みを まもる。 あいての すきを みのがさず みずを ふきだして はんげきする。",
			[8] = "いちまんねんの じゅみょうを もつと いわれている。ふさふさの しっぽは ながいきの シンボルとして にんき。",
			[9] = "こうらの ロケットほうから ふきだす すいりゅうは ぶあつい てっぱんも いっぱつで つらぬく はかいりょく。",
			[10] = "あかい しょっかくから においを だして てきを おいはらう。 だっぴを くりかえし おおきくなる。",
