			[409] = "きょうれつな ずつきの こうげきは どんなに がんじょうな ものでも いちげきで ふんさいする いりょく。",
			[410] = "およそ １おくねんまえに みつりんで くらしていた ポケモン。 かおの ひふが ひじょうに かたい。",
			[411] = "しょうめんからの こうげきは すべて はねかえす。くさや きのみを たべる おとなしい せいかく。",
			[412] = "つめたい こがらしを ふせぐため こえだや おちばを ざいりょうに ミノを つくり からだを おおう。",
			[413] = "ミノムッチから しんかしたとき ミノが からだの いちぶに なった。 いっしょう ミノを ぬぐことはない。",
			[414] = "はなの ミツが だいすき。 ミツハニ－の あつめた ミツを よこどりして たべてしまう。",
			[415] = "３びきが ひとつになった ポケモン。 ビ－クインのために せっせと はなの あまい ミツを はこぶ。",
			[416] = "どうたいが こどもたちの すあなに なっている。ミツハニ－の あつめた ミツで こどもたちを そだてる。",
			[417] = "せいでんきが たまって パチパチする けだまを だいこうぶつの きのみと いっしょに みきの あなに かくす。",
			[418] = "くびに ある うきぶくろに くうきを ためると うきわのように ふくらむ。 すいめんに かおを だして うかぶ。",
			[419] = "はったつした うきぶくろで うかぶ。 おぼれた ひとを きゅうじょする てつだいを している ポケモンだ。",
			[420] = "しんかに ひつような えいようぶんが ちいさい たまに ためられている。 とても あまくて おいしい らしい。",
			[421] = "ひざしが つよくなると はなひらく。 つぼみの ときに たえしのんだ うっぷんを いっきに はらすのだ。",
			[422] = "せいそくちにより ちがった かたちや いろを している。シンオウちほうでは ２しゅるいが かくにんされている。",
			[423] = "ホネがなく グニャグニャの からだ。 からだの いちぶが ちぎれても すぐに さいせいされて もとどおり。",
			[424] = "２ほんの しっぽで きのみの からを きように むいて たべる。ほんものの うでは ほとんど つかわなくなった。",
			[425] = "ひとや ポケモンの たましいが かたまって うまれた ポケモン。 ジメジメした きせつが だいすき。",
			[426] = "ひるまは ねぼけて うかんでいるが ゆうがた たいぐんで とんでいく。 いきさきは だれも しらない。",
			[427] = "まるめた みみを いきおいよく のばして あいてに たたきつける。 おとなでも とびあがるほど いたい。",
			[428] = "けいかいしんの つよい ポケモン。 きけんを かんじると ふわふわした みみさきの けで からだを つつむ。",
			[429] = "じゅもんのような なきごえを だして みみにした あいてを ずつうや げんかくで くるしめる。",
			[430] = "よるになると かつどうを はじめる。 たくさんの ヤミカラスを ひきつれ むれを つくることで しられる。",
			[431] = "きにいらないと ツメを たてるが たまに のどを ならして あまえる せいかくが いちぶに だいにんきだ。",
			[432] = "ほかの ポケモンの すみかにも かまわず はいりこんで じぶんの ねばしょにしてしまう ずうずうしさ。",
			[433] = "のどの おくで まるい たまを ふるわせて なきごえを だす。 ふわりと はずんで いどうする。",
			[434] = "おしりから きょうれつに くさい えきたいを とばして みを まもる。 においは ２４じかん きえない。",
			[435] = "しっぽの さきから ひどい においの えきたいを とばして こうげきする。 ひきょりは ５０メ－トルいじょう。",
			[436] = "ふるい おはかから ド－ミラ－に そっくりな どうぐが ほりだされたが かんけいは わかっていない。",
			[437] = "２０００ねん いじょう ねむっていた ド－タクンが こうじげんばから ほりだされ だいニュ－スに なった。",
			[438] = "いつも ないているように みえるが たいないの すいぶんを そとに だして ちょうせつしているのだ。",
			[439] = "あいての うごきを モノマネする しゅうせい。まねを された あいては めが はなせなくなる という。",
			[440] = "しろくて まるいものが だいすき。 ラッキ－の まねをして タマゴに そっくりな いしを かかえている。",
			[441] = "ひとの ことばを おぼえて なく。 なかまが いっかしょに あつまると みんな おなじ ことばを おぼえる。",
			[442] = "１０８この たましいが あつまって うまれた ポケモン。かなめいしの ひびわれに つながれている。",
			[443] = "どうくつの ちいさな よこあなを ねぐらにする。えものが ちかづくと すばやく とびだして つかまえる。",
			[444] = "ガバイトの ウロコから つくった くすりが ふじのやまいを なおすと ふるくから しんじられてきた。",
			[445] = "からだを おりたたみ つばさを のばすと まるで ジェットき。 おんそくで とぶことが できる。",
			[446] = "１にち １かい たいじゅうと おなじ りょうの エサを いっきに たべる。 ほとんど かまずに まるのみ。",
			[447] = "からだから はっする はどうは こわいとき かなしいときに つよまり ピンチを なかまに つたえる。",
			[448] = "あらゆる ものが はっする はどうを キャッチする のうりょくを もつ。 ひとの ことばを りかいできる。",
			[449] = "かんそうした とちで くらす。 あせの かわりに すなつぶを からだから ぶんぴつする ポケモン。",
			[450] = "たいないに ためた すなを からだの あなから ふきあげて きょだいな たつまきを つくり こうげきする。",
			[451] = "しっぽの ツメで えものを はさみ どくを おくりこむ。どくが きくまで ぜったいに はなさない しゅうねん。",
			[452] = "りょううでの ツメは じどうしゃを スクラップにする はかいりょく。 ツメの さきから どくを だす。",
			[453] = "ほっぺたに どくぶくろを もつ。 あいての すきを ついて もうどくを にじませている ゆびを つきさす。",
			[454] = "こぶしの トゲからは かすりきずでも いのちを おとすほどの もうどくを ぶんぴつしている。",
			[455] = "あまい においの だえきで えものを おびきよせ おおあごで がぶり。 １にち かけて えものを たべる。",
			[456] = "たいようを いっぱいに あびた おびれの もようは くらくなると あざやかな いろで ひかりだす。",
			[457] = "ふかい うみの そこで くらす。 ４まいの ひれの もようを ひからせ えものを おびきよせる。",
			[458] = "２ほんの しょっかくで かいすいの びみょうな うごきを キャッチする。 ひとなつっこい ポケモン。",
			[459] = "ゆきやまで くらしている。 めったに であわない にんげんを めずらしがって ちかよってくる。",
			[460] = "まんねんゆきの つもる やまで くらし ブリザ－ドを まきおこす。 ゆきおとこの しょうたいだ。",
			[461] = "さむい ちいきで くらす ポケモン。 ４、５ひきの グル－プは みごとな れんけいで えものを おいつめる。",
			[462] = "とくしゅな じばの えいきょうで レアコイルが しんかした。３つの ユニットから じりょくを だす。",
			[463] = "ぐんぐん のびる ベロを なんにでも まきつける。うかつに ちかよると だえきで べとべとに されてしまう。",
			[464] = "いわを てのひらの あなに つめて きんにくの ちからで はっしゃする。 まれに イシツブテを とばす。",
			[465] = "しょくぶつの ツルで できた うでを のばして えものを からめとる。 うでを たべられても へっちゃら。",
			[466] = "２ほんの しっぽの さきを あいてに おしあてて ２まんボルトいじょうの でんりゅうを ながして こうげき。",
			[467] = "うでの さきから せっし２０００どの ひのたまを はっしゃする。 かざんの かこうを すみかにする。",
			[468] = "もめごとの おこる ばしょには けっして あらわれない。ちかごろは すがたを みかけなくなった。",
			[469] = "はばたいたときの しょうげきはで あいての からだの うちがわに ちめいてきな ダメ－ジを あたえる。",
			[470] = "しょくぶつのように こうごうせいを するため リ－フィアの まわりは すんだ くうきに つつまれている。",
			[471] = "ぜんしんの たいもうを こおらせて ハリのように するどく とがらせる。 てきから みを まもる しゅだん。",
			[472] = "しっぽで きのえだに ぶらさがり えものを かんさつする。すきを みて じょうくうから おそいかかる。",
			[473] = "こおりで できた りっぱな キバ。 ひょうがきが おわり あたたかく なったため かずが へってしまった。",
			[474] = "より すぐれた ポケモンに するため プログラムを ついかしたが なぜか おかしな こうどうを はじめた。",
			[475] = "のびちぢみする ひじの かたなで たたかう。いあいの めいしゅ。 れいぎ ただしい ポケモン。",
			[476] = "ぜんしんから つよい じりょくを だしている。３この チビノ－ズと よばれる ユニットを あやつる。",
			[477] = "あたまの アンテナで れいかいからの でんぱを じゅしん。しじを うけて ひとを れいかいへ つれていくのだ。",
			[478] = "マイナス５０どの れいきを はいて あいてを こおらせる。どうたいに みえる ぶぶんは じつは くうどう。",
			[479] = "プラズマで できた からだを もつ。 でんかせいひんに もぐりこみ わるさを することで しられている。",
			[480] = "ちしきのかみ と よばれている。 めを あわせた ものの きおくを けしてしまう ちからを もつという。",
			[481] = "かなしみの くるしさと よろこびの とうとさを ひとびとに おしえた。 かんじょうのかみ と よばれている。",
			[482] = "いしのかみ と よばれている。 みずうみの そこで ねむりつづけ せかいの バランスを とっている。",
			[483] = "じかんを あやつる ちからを もつ。 シンオウちほうでは かみさまと よばれ しんわに とうじょうする。",
			[484] = "くうかんを ゆがめる のうりょくを もち シンオウちほうの しんわでは かみさまとして えがかれている。",
			[485] = "かざんの ほらあなに せいそく。 じゅうじの ツメを くいこませて カベや てんじょうを はいまわる。",
			[486] = "なわで しばった たいりくを ひっぱって うごかしたという でんせつが のこされている。",
			[487] = "このよの うらがわにある せかいに すんでいると いわれる ポケモン。 こだいの はかばに あらわれる。",
			[488] = "ひこうするときは ベ－ルのような はねから ひかる りゅうしを だす。 みかづきのけしんと よばれている。",
			[489] = "あたたかい うみに すむ ポケモン。 あたまの うきぶくろを ふくらませて なみまを ただよい えさを さがす。",
			[490] = "つめたい うみの そこで うまれた。 じぶんが うまれた うみの そこへ ながい きょりを およいで かえる。",
			[491] = "ひとびとを ふかい ねむりに さそい ゆめを みせる のうりょくを もつ。 しんげつの よるに かつどうする。",
			[492] = "はなばたけの なかで くらしているが からだを まるめると はなのように みえるため だれも きづかないのだ。",
			[493] = "１０００ぼんの うでで うちゅうを つくった ポケモンとして しんわに えがかれている。",
		},
