	function PM.text_at(bank, id, args)
		local t = PM.text[bank] and PM.text[bank][id]
		if not t then return nil end
		local missing = false
		t = t:gsub("{(%d+)}", function(k)
			local v = args and args[tonumber(k)]
			if v == nil then missing = true; return "" end
			return tostring(v)
		end)
		return not missing and t or nil
	end

	local failures = {}
	function PM.fail(reason)
		if not failures[reason] then dbg("menus: " .. reason); failures[reason] = true end
		return nil
	end

	-- BoxPokemon_GetDataInternal 020745fe obtains block C in r7, then 02074990
	-- copies its nickname. BoxPokemon_GetDataBlock 0207825c uses personality bits
	-- 13..17, with cases 24..31 repeating 0..7. DecodeData -> EncodeData 0201d5d4
	-- applies the LCG to 64 words at +8, seeded by the checksum at +6.
	local BLOCKS = {{0,1,2,3},{0,1,3,2},{0,2,1,3},{0,3,1,2},{0,2,3,1},{0,3,2,1},
		{1,0,2,3},{1,0,3,2},{2,0,1,3},{3,0,1,2},{2,0,3,1},{3,0,2,1},
		{1,2,0,3},{1,3,0,2},{2,1,0,3},{3,1,0,2},{2,3,0,1},{3,2,0,1},
		{1,2,3,0},{1,3,2,0},{2,1,3,0},{3,1,2,0},{2,3,1,0},{3,2,1,0}}
	function PM.boxdata(mon)
		if not inram(mon) or not inram(mon + 0x87) then return PM.fail("nickname: unreadable Pokemon") end
		local flags, checksum, seed = u16(mon + 4), u16(mon + 6), u16(mon + 6)
		if flags & 4 ~= 0 then return PM.fail("nickname: game marked checksum failure") end
		local words, sum = {}, 0
		for i = 0, 63 do
			local w = u16(mon + 8 + i * 2)
			if flags & 2 == 0 then
				seed = (seed * 0x41C64E6D + 0x6073) & 0xFFFFFFFF
				w = w ~ (seed >> 16)
			end
			words[i], sum = w, (sum + w) & 0xFFFF
		end
		if sum ~= checksum then return PM.fail("nickname: decoded checksum mismatch") end
		local blocks = BLOCKS[((u32(mon) >> 13) & 31) % 24 + 1]
		local function word(block, offset) return words[blocks[block] * 16 + offset // 2] end
		local function byte(block, offset) return (word(block, offset) >> ((offset % 2) * 8)) & 255 end
		local function long(block, offset) return word(block, offset) | (word(block, offset + 2) << 16) end
		return {word=word,byte=byte,long=long,personality=u32(mon)}
	end
	-- GetExpTask 02248e92 loads a search lower bound; 02248eae..ef4
	-- advances to the next participation/Exp. Share recipient. Only 0224996e
	-- writes slot+1 back. Both native party accessors use BattleSystem+68 for
	-- expBattler0; Party_GetPokemonBySlotIndex 0207a11c uses +8+slot*ec.
	battle_levelup_data = function(bs, ctx, start)
		local party = u32(bs + 0x68)
		if not inram(party) or not inram(party + 7) then return PM.fail("battle stats: party owner") end
		local capacity, count = u32(party), u32(party + 4)
		if capacity < 1 or capacity > 6 or count < 1 or count > capacity or start >= count
			or not inram(party + 8 + count * 0xEC - 1) then return PM.fail("battle stats: party bounds") end
		local side = (u32(ctx + 0x74) >> 1) & 1
		local mask = u32(ctx + 0xA4 + side * 4)
		for slot = start, count - 1 do
			local mon = party + 8 + slot * 0xEC
			local data = PM.boxdata(mon)
			if not data then return nil end
			local item = data.word(1, 2)
			if item > 467 then return PM.fail("battle stats: held item") end
			local member = u16(A.ItemArchiveIDs + item * 8)
			local address = PM.rom_member("itemtool/itemdata/pl_item_data.narc", member, 34)
			if not address then return PM.fail("battle stats: item data") end
			local effect = PM.rom_read(address + 2, 1)
			if effect == nil then return PM.fail("battle stats: held effect") end
			if effect == 51 or mask & (1 << slot) ~= 0 then
				-- Pokemon_GetValue 02074480..94 decrypts party+88 using PID,
				-- independently of box data. Consumers 0207452e..4e read totals.
				local words, seed = {}, u32(mon)
				for i = 0, 9 do
					local word = u16(mon + 0x88 + i * 2)
					if u16(mon + 4) & 1 == 0 then
						seed = (seed * 0x41C64E6D + 0x6073) & 0xFFFFFFFF
						word = word ~ (seed >> 16)
					end
					words[i] = word
				end
				local level, hp = words[2] & 255, words[3]
				local stats = {words[4], words[5], words[6], words[8], words[9], words[7]}
				if level < 1 or level > 100 or hp > stats[1] then return PM.fail("battle stats: party values") end
				for _, value in ipairs(stats) do
					if value < 1 or value > 999 then return PM.fail("battle stats: stat value") end
				end
				return stats
			end
		end
		return PM.fail("battle stats: no recipient")
	end
	function PM.boxname(mon)
		local data = PM.boxdata(mon)
		if not data then return nil end
		local out = {}
		-- The getter copies ten words and supplies its own terminator, including
		-- when all ten nickname characters are used (0207499a..020749a4).
		for i = 0, 9 do
			local c = data.word(3, i * 2)
			if c == 0xFFFF then break end
			if not CHARMAP[c] then return PM.fail("nickname: unknown character") end
			out[#out + 1] = CHARMAP[c]
		end
		return name_text(out)
	end

	local message_pages = {}
	function PM.forget_message(owner)
		if owner then message_pages[owner] = nil end
	end
	function PM.message(string, printer, cap, owner)
		local first, last = str_range(string, cap or 1024)
		if not first then return nil end
		local pages = pt_pages(first, last)
		local pr, cursor
		if printer ~= nil then pr, cursor = printer_at(printer, first, last) end
		local shown = page_at(pages, cursor)
		if owner then
			local parts = {}
			for i, page in ipairs(pages) do parts[i] = page.text end
			local full, previous = table.concat(parts, "\1"), message_pages[owner]
			if previous and previous.string == string and previous.full == full
				and not pr then shown = previous.page end
			-- Text_DestroyPrinterTask removes the printer after its last glyph,
			-- while party/Bag questions remain visible with their new choices.
			message_pages[owner] = { string = string, full = full, page = shown }
		end
		local page = pages[shown]
		return page and page.text
	end

	function PM.move(id, pp, maxpp, detail, values)
		local name, data = BTLTEXT.moves[id], values or PM.move_data[id]
		if not name or not data or not pp or not maxpp or pp > maxpp or maxpp > 64 then return nil end
		local out = {name, BTLTEXT.types[data[3]], BTLTEXT.pp .. " " .. pp .. " de " .. maxpp}
		if not out[2] then return nil end
		if detail then
			local t = PM.party_text
			local category = ({[0]=t.MoveCategoryPhysical, t.MoveCategorySpecial, t.MoveCategoryStatus})[data[1]]
			if not category then return nil end
			out[#out + 1] = category
			out[#out + 1] = t.MovePowerLabel .. " " .. (data[2] > 1 and tostring(data[2]) or t.MoveStatNoValue)
			out[#out + 1] = t.MoveAccuracyLabel .. " " .. (data[4] > 0 and tostring(data[4]) or t.MoveStatNoValue)
			out[#out + 1] = PM.text_at(646, id)
		end
		return table.concat(out, ", ")
	end

	-- The main task queue is the owner, not a guessed heap location. Its executor
	-- (0201cdd4) follows manager+0c -> task+08, calling task+14 with task+10.
	-- Cache the live task. Walk this bounded engine list only while acquiring a
	-- submenu or after the previous task was removed; there is no RAM search.
	local cached_task
	function PM.battle_task(bs)
		local manager = u32(A.gSystem + 0x18)
		if not inram(manager) or not inram(manager + 0x33) then return PM.fail("battle submenu: task manager") end
		local maximum, count, array = u16(manager), u16(manager + 2), u32(manager + 0x24)
		if maximum == 0 or maximum > 1024 or count > maximum or not inram(array)
			or not inram(array + maximum * 0x1C - 1) then return PM.fail("battle submenu: task allocation") end
		local sentinel = manager + 4
		local function allocated(task)
			return task and task >= array and task < array + maximum * 0x1C and (task - array) % 0x1C == 0
		end
		local function linked(task)
			if not allocated(task) or u32(task) ~= manager then return false end
			local prev, nextp = u32(task + 4), u32(task + 8)
			return (prev == sentinel or allocated(prev)) and (nextp == sentinel or allocated(nextp))
				and u32(prev + 8) == task and u32(nextp + 4) == task
		end
		local function matches(task)
			if not linked(task) then return false end
			local cb = u32(task + 0x14)
			return cb == A.BattlePartyTask_Tick or cb == A.BattleBagTask_Tick
		end
		if not matches(cached_task) then
			cached_task = nil
			local task, found, n = u32(manager + 0x0C), nil, 0
			while task ~= sentinel do
				n = n + 1
				if n > count or not linked(task) then return PM.fail("battle submenu: broken task links") end
				if matches(task) then
					if found then return PM.fail("battle submenu: ambiguous owners") end
					found = task
				end
				task = u32(task + 8)
			end
			cached_task = found
		end
		if not cached_task or u32(cached_task + 0x18) ~= 0 then return nil end
		local ui = u32(cached_task + 0x10)
		local party = u32(cached_task + 0x14) == A.BattlePartyTask_Tick
		if not inram(ui) or not inram(ui + (party and 0x208F or 0x115B)) then return PM.fail("battle submenu: task parameter") end
		local ctx = u32(ui)
		if not inram(ctx) or not inram(ctx + (party and 0x37 or 0x33)) then return PM.fail("battle submenu: context") end
		if u32(ctx + (party and 8 or 0)) ~= bs then return PM.fail("battle submenu: another BattleSystem") end
		if u8(ctx + (party and 0x36 or 0x26)) ~= 0 then return nil end
		local state = u8(ui + (party and 0x2078 or 0x114A))
		if state == 0 or state >= (party and 25 or 13) then return nil end
		if party and u8(ctx + 0x35) > 3 then return PM.fail("battle party: unknown mode") end
		return {ui=ui, ctx=ctx, party=party, state=state}
	end

	function PM.battle_menu()
		local bs = battle_sys()
		if not bs or u8(bs + SC.MODE) ~= 3 then cached_task = nil; return nil end
		return PM.battle_task(bs)
	end

	-- PokemonSummaryScreen_StatusIconAnimIdx and SUMMARY_CONDITION_* (main.h).
	local STATUS_ICONS = {[0]="Pokérus", "paralizado", "congelado", "dormido", "envenenado", "quemado", "debilitado"}
	function PM.party_mon(ui, slot, summary)
		if slot > 5 then return nil end
		local p = ui + 4 + slot * 0x50
		local species, hp, maxhp = u16(p + 4), u16(p + 0x10), u16(p + 0x12)
		if species == 0 or species > 493 or hp > maxhp then return nil end
		local name = PM.boxname(u32(p))
		if not name then return nil end
		if u8(p + 0x17) & 0x80 ~= 0 then return name end
		local level, gender, status = u8(p + 0x16) & 0x7F, u8(p + 0x17) & 7, (u8(p + 0x17) >> 3) & 15
		if level < 1 or level > 100 or gender > 2 or status > 7 or maxhp == 0 then return nil end
		local t = PM.party_text
		local out = {name, t.PokemonLevelLabel .. " " .. level}
		if gender < 2 then out[#out + 1] = CHARMAP[0x1BB + gender] end
		out[#out + 1] = t.PokemonHPStatLabel .. " " .. hp .. " de " .. maxhp
		if STATUS_ICONS[status] then out[#out + 1] = STATUS_ICONS[status] end
		if summary then
			for _, stat in ipairs({{6,t.PokemonAttackStatLabel},{8,t.PokemonDefenseStatLabel},
				{12,t.PokemonSpAtkStatLabel},{14,t.PokemonSpDefStatLabel},{10,t.PokemonSpeedStatLabel}}) do
				out[#out + 1] = stat[2] .. " " .. u16(p + stat[1])
			end
			local ability = PM.text_at(610, u16(p + 0x18))
			local item = u16(p + 0x1A)
			if not ability or (item ~= 0 and not PM.text_at(392, item)) then return nil end
			out[#out + 1] = ability
			out[#out + 1] = PM.text_at(612, u16(p + 0x18))
			out[#out + 1] = item == 0 and t.PokemonNoItemHeld or PM.text_at(392, item)
			local exp, nextxp = u32(p + 0x1C), u32(p + 0x24)
			if level < 100 and nextxp >= exp then out[#out + 1] = t.PokemonExpToNextLevelLabel .. " " .. (nextxp - exp) end
		end
		return table.concat(out, ", ")
	end

	function PM.party_move(s, slot, detail, contest)
		local party_slot = u8(s.ctx + 0x11)
		if party_slot > 5 or slot > 4 then return nil end
		if slot == 4 then
			local id = u16(s.ctx + 0x24)
			local data = PM.move_data[id]
			if contest then return data and PM.contest_move(id) end
			return data and PM.move(id, data[5], data[5], detail)
		end
		local p = s.ui + 4 + party_slot * 0x50 + 0x30 + slot * 8
		if contest then return PM.contest_move(u16(p)) end
		return PM.move(u16(p), u8(p + 2), u8(p + 3), detail,
			{u8(p + 5), u8(p + 7), u8(p + 4), u8(p + 6)})
	end

	local function cursor(ptr, n)
		if not inram(ptr) or not inram(ptr + 15) or u8(ptr + 8) ~= 1 then return nil end
		local row, mask = u8(ptr + 9), u32(ptr + 12)
		if row >= n or mask & (1 << row) == 0 then return nil end
		return row, mask & ((1 << n) - 1)
	end
	local function ordinal(text, row, mask)
		if not text then return nil end
		local before, total = 0, 0
		for i = 0, 31 do
			if mask & (1 << i) ~= 0 then total = total + 1; if i <= row then before = before + 1 end end
		end
		return text .. ", " .. before .. " de " .. total
	end
	local SCREEN_BUTTONS = {[0]=7,4,4,8,5,5,7,3,7,3}
	local SCREEN_STATE = {[0]=1,2,3,4,5,21,19,20,19,20}
	-- ⛔ CAPACITY 512: the message String is String_Init(0x200) (overlay 13 0x02220F3E-0x02220F4A,
	-- stored at +0x1FB0), and str_range refuses a String whose maxSize exceeds the cap, so the
	-- earlier 256 never read "It won't have any effect." or the can't-switch messages.
	function PM.party_screen(s)
		local ui, ctx, t = s.ui, s.ctx, PM.party_text
		local screen, selected = u8(ui + 0x207A), u8(ctx + 0x11)
		if s.state == 17 or s.state == 18 then
			return "message", PM.message(u32(ui + 0x1FB0), u8(ui + 0x207B), 512, ui)
		end
		if s.state == 22 and u8(ui + 0x2079) == 20 then return "hm", t.HMMovesCantBeForgotten end
		if s.state ~= SCREEN_STATE[screen] then return nil end
		local row, mask = cursor(u32(ui + 0x2088), SCREEN_BUTTONS[screen])
		local page = screen .. ":" .. selected
		local prompt, text
		if screen == 0 then
			prompt = u8(ctx + 0x35) == 2 and t.UseOnWhichPokemon or t.ChooseAPokemon
			if row and row < 6 then
				text = PM.party_mon(ui, row)
				mask = mask & 0x3F
				for i = 0, 5 do if u16(ui + 8 + i * 0x50) == 0 then mask = mask & ~(1 << i) end end
			elseif row == 6 then text = t.CancelMoveButton end
		elseif selected > 5 then return nil
		elseif screen == 1 then
			prompt = PM.party_mon(ui, selected)
			text = ({[0]=t.ShiftButton,t.SummaryButton,t.CheckMovesButton,t.CancelMoveButton})[row]
		elseif screen == 2 then
			prompt = PM.party_mon(ui, selected, true)
			-- Previous/next Pokémon and contest-view buttons are arrow/icon art.
			text = ({[0]="Previous Pokémon","Next Pokémon",t.CheckMovesButton,t.CancelMoveButton})[row]
		elseif screen == 3 or screen == 4 or screen == 5 or screen == 6 or screen == 8 then
			prompt = PM.party_mon(ui, selected)
			local moves = (screen == 6 or screen == 8) and 5 or 4
			if screen == 5 then prompt = t.RestoreWhichMove end
			if row and row < moves then
				text = PM.party_move(s, row, screen == 4, screen == 8)
				mask = mask & ((1 << moves) - 1)
				for i = 0, moves - 1 do if not PM.party_move(s, i) then mask = mask & ~(1 << i) end end
			elseif screen == 3 then
				text = ({[4]="Previous Pokémon", [5]="Next Pokémon", [6]=t.SummaryButton, [7]=t.CancelMoveButton})[row]
			elseif (screen == 6 or screen == 8) and row == 5 then
				text = screen == 8 and "Battle moves" or "Contest moves"
			elseif row then text = t.CancelMoveButton end
		elseif screen == 7 or screen == 9 then
			local move = u8(ctx + 0x34)
			prompt = PM.party_move(s, move, true, screen == 9)
			if row == 0 then text = move == 4 and t.CancelMoveButton or t.ForgetMoveButton
			elseif row == 1 then text = screen == 9 and "Battle moves" or "Contest moves"
			elseif row == 2 then text = t.CancelMoveButton end
		end
		return page, prompt, row, row and ordinal(text, row, mask)
	end

	local function pocket_name(pocket)
		local t = PM.bag_text
		return ({[0]=t.MenuTitleHPPP .. " " .. t.MenuTitleRestore,
			t.MenuTitleStatus .. " " .. t.MenuTitleHealers,t.MenuTitlePokeBalls,
			t.MenuTitleBattleItems,t.ItemUsedLast})[pocket]
	end
	function PM.bag_item(s, pocket, slot, detail)
		if pocket > 4 or slot >= 36 then return nil end
		local p = s.ui + 0x3C + pocket * 144 + slot * 4
		local id, quantity = u16(p), u16(p + 2)
		local name = PM.text_at(392, id)
		if id == 0 or not name or quantity == 0 or quantity > 999 then return nil end
		local out = quantity .. " " .. name
		if detail then
			local desc = PM.text_at(391, id)
			if desc then out = out .. ". " .. desc end
		end
		return out
	end
	-- Message String +0x18 is String_Init(0x200) as well (overlay 13 0x022270E8-0x022270F2), so
	-- the cap is 512 here too ("It's no good!" was refused at 256).
	function PM.bag_screen(s)
		local ui, ctx = s.ui, s.ctx
		if s.state == 9 or s.state == 10 then return "message", PM.message(u32(ui + 0x18), u8(ui + 0x32), 512, ui) end
		local screen, pocket = u8(ui + 0x114C), u8(ui + 0x114D)
		if screen > 2 or pocket > 4 or s.state ~= screen + 1 then return nil end
		local page, count, pages = u8(ctx + 0x2C + pocket), u8(ui + 0x114F + pocket), u8(ui + 0x1154 + pocket)
		if page > 5 or count > 36 or pages > 6 then return nil end
		local row, mask = cursor(u32(ui + 0x34), ({6,9,2})[screen + 1])
		local prompt, text
		if screen == 0 then
			if row == 5 then text = PM.party_text.CancelMoveButton
			elseif row == 4 then
				text = pocket_name(4)
				local item = PM.bag_item(s, 4, 0)
				if item then text = text .. ", " .. item end
			elseif row then text = pocket_name(row) end
		elseif screen == 1 then
			prompt = pocket_name(pocket)
			if row and row < 6 then
				text = PM.bag_item(s, pocket, page * 6 + row)
				if text then text = text .. ", " .. (page * 6 + row + 1) .. " de " .. count end
				return screen .. ":" .. pocket .. ":" .. page, prompt, row, text
			elseif row == 6 then text = "Previous page"
			elseif row == 7 then text = "Next page"
			elseif row == 8 then text = PM.party_text.CancelMoveButton end
		else
			local pos = u8(ctx + 0x27 + pocket)
			if pos >= 6 then return nil end
			prompt = PM.bag_item(s, pocket, page * 6 + pos, true)
			text = row == 0 and PM.bag_text.Use or row == 1 and PM.party_text.CancelMoveButton or nil
		end
		return screen .. ":" .. pocket .. ":" .. page, prompt, row, row and ordinal(text, row, mask)
	end

	-- The field executes its child only after its parent has stopped (0203cf2a).
	-- ApplicationManager_Data 0200682c returns manager+1c; the application's own
	-- state is manager+14. Keep both so the reader can exclude teardown.
	function PM.field_app(main, overlay)
		local fs = field_sys()
		if not fs then return nil end
		local processes = u32(fs)
		if not inram(processes) or not inram(processes + 15) then return PM.fail("field menu: process manager") end
		if u32(processes) ~= 0 then return nil end
		local app = u32(processes + 4)
		local ui = app_at(app, main, overlay)
		if ui then return ui, u32(app + 0x14), app end
		return pc_child_app(main, overlay)
	end

	-- Menu_ProcessInputWithSound 02001cb0..b8: cursor+15, choices+0,
	-- StringList stride 8. The label String and its integrity marker are live.
	function PM.menu(ptr)
		if not inram(ptr) or not inram(ptr + 0x1F) then return nil end
		local row, count = u8(ptr + 0x15), u8(ptr + 9) * u8(ptr + 10)
		local choices, window = u32(ptr), u32(ptr + 4)
		if count < 1 or count > 32 or row >= count or not inram(window)
			or not inram(choices) or not inram(choices + count * 8 - 1) then return PM.fail("choice menu: invalid layout") end
		local first, last = str_range(u32(choices + row * 8), 1024)
		if not first then return nil end
		local pages = pt_pages(first, last)
		local text = pages[1] and pages[1].text
		return row, text and (text .. ", " .. (row + 1) .. " de " .. count), u32(choices + row * 8 + 4)
	end

	-- ListMenu_CalcTrueCursorPos 020014d0 reads u16+2c and u16+2e.
	-- ListMenu_New 0200115a stores the cursor GRAPHIC pointer at +28, then the
	-- two positions at +2c/+2e. Reading the pointer's halves silences the bag.
	-- Read its item value too: the bag has hidden padding rows at both ends, and
	-- TM/HM and berry Close Bag rows deliberately have an empty label String.
	function PM.list(ptr, parent)
		if not inram(ptr) or not inram(ptr + 0x37) then return PM.fail("item list: allocation") end
		if parent and u32(ptr + 0x1C) ~= parent then return PM.fail("item list: another owner") end
		local count, pos = u16(ptr + 0x10), u16(ptr + 0x2C) + u16(ptr + 0x2E)
		local choices = u32(ptr)
		if count < 1 or count > 512 or pos >= count or not inram(choices)
			or not inram(choices + count * 8 - 1) then return PM.fail("item list: invalid bounds") end
		local entry = choices + pos * 8
		local first, last = str_range(u32(entry), 1024)
		local pages = first and pt_pages(first, last)
		return pos, u32(entry + 4), pages and pages[1] and pages[1].text, count
	end

	function PM.form_data(species, form)
		if species<1 or species>493 then return nil end
		local alternate=({[386]={495,3},[413]={498,2},[487]={500,1},[492]={501,1},[479]={502,5}})[species]
		if alternate and form>0 and form<=alternate[2] then species=alternate[1]+form end
		return PM.species_data[species]
	end
	function PM.teach_comment(s,slot)
		local mon=PM.boxdata(u32(s.ctx)+8+236*slot)
		if not mon then return nil end
		if mon.long(2,0x10)&0x40000000~=0 then return PM.field_party_text.UnableToLearn end
		local move,item=u16(s.ctx+0x26),u16(s.ctx+0x24)
		if not BTLTEXT.moves[move] or item<328 or item>427 then return nil end
		for i=0,3 do
			local existing=mon.word(2,i*2)
			if existing==move then return PM.field_party_text.AlreadyLearned end
			if existing==0 then break end
		end
		local data=PM.form_data(mon.word(1,0),mon.byte(2,0x18)>>3)
		if not data then return nil end
		local tm=item-328
		return data[3+tm//32]&(1<<(tm%32))~=0 and PM.field_party_text.AbleToLearn or PM.field_party_text.UnableToLearn
	end
	function PM.field_member(ui, slot)
		if slot > 5 then return nil end
		-- PrintMemberName 02081f48..58 and LoadMember 0207ef14 agree:
		-- inline members +704, stride 2c, name String at +0, present +29.
		local p = ui + 0x704 + slot * 0x2C
		if u8(p + 0x29) ~= 1 then return nil end
		local name = str_name(u32(p), 11)
		if not name then return nil end
		if u8(p + 0x10) == 1 then return name end
		local species, hp, maxhp, level = u16(p + 4), u16(p + 6), u16(p + 8), u16(p + 10)
		local flags = u16(p + 14)
		local gender, status = (flags >> 13) & 3, flags & 0xFFF
		if species < 1 or species > 493 or hp > maxhp or maxhp == 0 or level < 1 or level > 100
			or gender > 2 or status > 7 then return PM.fail("field party: invalid member") end
		local out = {name, PM.party_text.PokemonLevelLabel .. " " .. level}
		if gender < 2 then out[#out + 1] = CHARMAP[0x1BB + gender] end
		out[#out + 1] = PM.party_text.PokemonHPStatLabel .. " " .. hp .. " de " .. maxhp
		if STATUS_ICONS[status] then out[#out + 1] = STATUS_ICONS[status] end
		if u16(p + 12) ~= 0 then
			local item = PM.text_at(392, u16(p + 12))
			if not item then return nil end
			out[#out + 1] = item
		end
		return table.concat(out, ", ")
	end

	function PM.field_party()
		local ui, state = PM.field_app(A.PartyMenu_Main, 0xFFFFFFFF)
		if not ui or state >= 32 then return nil end
		if not inram(ui + 0xB43) then return PM.fail("field party: application data") end
		local ctx = u32(ui + 0x5A4)
		if not inram(ctx) or not inram(ctx + 0x3F) then return PM.fail("field party: arguments") end
		local party = u32(ctx)
		if not inram(party) or not inram(party + 7) or u32(party + 4) > 6 then return PM.fail("field party: party count") end
		return {ui=ui,ctx=ctx,state=state,count=u32(party + 4)}
	end
	local FIELD_PARTY_CHOICES = {[2]=true,[6]=true,[10]=true,[15]=true,[27]=true}
	local FIELD_PARTY_SLOTS = {[1]=true,[4]=true,[8]=true,[21]=true,[28]=true}
	-- PartyMenuCB_LevelUp retains stage0 while drawing numbers into tmpString.
	-- Window_Add precedes those writes; Window_Remove clears the live witness.
	-- Validate the exact 14x12 context window, not the contents of the scratch text.
	function PM.field_levelup_context(s)
		local ui = s.ui
		if s.state ~= 5 or u32(ui+0xB18) ~= A.PartyMenuCB_LevelUp then return nil end
		local stage,slot = u8(ui+0xB2B),u8(ui+0xB29)
		if stage > 6 or slot >= s.count then return stage,nil,slot end
		local window = ui+0x254
		local bg,pixels = u32(window),u32(window+0xC)
		if bg == 0 or u8(window+4) == 0xFF or pixels == 0 then return stage,false,slot end
		if not inram(bg) or bg ~= u32(ui) or not inram(pixels) or not inram(pixels+14*12*32-1)
			or u8(window+4) ~= 0 or u8(window+5) ~= 1 or u8(window+6) ~= 1
			or u8(window+7) ~= 14 or u8(window+8) ~= 12 then
			return stage,nil,slot
		end
		return stage,true,slot
	end
	function PM.field_levelup_screen()
		local s = PM.field_party()
		if not s then return nil end
		local stage,visible = PM.field_levelup_context(s)
		if visible then
			if stage == 0 or stage == 1 then return "field level-up gains" end
			if stage == 2 then return "field level-up totals" end
		end
	end

	local level_owner,level_slot,level_old
	function PM.forget_field_levelup()
		level_owner,level_slot,level_old = nil,nil,nil
	end
	function PM.field_levelup(s)
		local ui = s.ui
		local stage,visible,slot = PM.field_levelup_context(s)
		if stage == nil then
			PM.forget_field_levelup()
			return nil
		end
		if visible == nil then return "level stats",nil end
		-- Only pristine stage0 owns the level-up message and the old stats.
		-- The renderer updates monStats row by row after allocating its window.
		if stage == 0 and visible then return "level stats",nil end
		if stage == 3 or stage == 6 then return "level stats",nil end
		if stage == 4 or stage == 5 then return visible and "level stats" or nil end
		if stage ~= 0 and not visible then return "level stats",nil end
		local stats = {}
		for i=0,5 do
			local value = u16(ui+0xB2C+2*i)
			if value < 1 or value > 999 then return "level stats",nil end
			stats[i+1] = value
		end
		if stage == 0 then level_owner,level_slot,level_old = ui,slot,stats; return nil end
		if stage == 1 and (level_owner ~= ui or level_slot ~= slot or not level_old) then return "level stats",nil end
		local out = {}
		for i=0,5 do
			local value = stage == 1 and stats[i+1]-level_old[i+1] or stats[i+1]
			if value < 0 or (stage == 1 and value > 99) then return "level stats",nil end
			out[#out+1] = PM.text_at(453,185+i) .. " " .. PM.text_at(453,stage == 1 and 191 or 192,{[0]=value})
		end
		return "level stats:" .. stage,table.concat(out,", ")
	end

	function PM.field_party_screen(s)
		local ui, state = s.ui, s.state
		if state == 0 or state == 29 or state == 31 then return nil end
		local levelpage,leveltext=PM.field_levelup(s)
		if levelpage then return levelpage,leveltext end
		local prompt = PM.message(u32(ui + 0x6A4), u8(ui + 0xB28), 1024, ui)
		if FIELD_PARTY_CHOICES[state] then
			local ptr = u32(ui + 0x700)
			local row, text = PM.menu(ptr)
			return "choices:" .. state .. ":" .. ptr, prompt, row, text
		end
		if FIELD_PARTY_SLOTS[state] or (state==30 and u16(ui+0xB2E)==0) then
			local row = u8(ui + 0xB29)
			local text
			if row < 6 then
				text = PM.field_member(ui, row)
				if text and u8(s.ctx+0x20)==6 then
					local comment=PM.teach_comment(s,row)
					if not comment then return nil end
					text=text .. ", " .. comment
				end
				if text then text = text .. ", " .. (row + 1) .. " de " .. s.count end
			elseif row == 6 then text = PM.field_party_text.ConfirmButton
			elseif row == 7 then text = PM.field_party_text.CancelButton end
			return "party:" .. state, prompt, row, text
		end
		return "message", prompt
	end

	function PM.field_bag()
		local ui, state = PM.field_app(A.BagApplication_Main, 84)
		if not ui or state >= 24 then return nil end
		if not inram(ui + 0x4A3) then return PM.fail("field bag: application data") end
		local ctx = u32(ui + 0xC4)
		if not inram(ctx) or not inram(ctx + 0x77) then return PM.fail("field bag: arguments") end
		local pocket = u8(ctx + 0x64)
		if pocket >= u8(ui + 0x424) or pocket > 7 then return PM.fail("field bag: pocket index") end
		local p = ctx + 4 + pocket * 12
		local kind, count = u8(p + 8), u8(p + 9)
		if kind > 7 or count > 168 then return PM.fail("field bag: pocket layout") end
		return {ui=ui,ctx=ctx,state=state,pocket=pocket,kind=kind,p=p,count=count}
	end
	local FIELD_BAG_LIST = {[1]=true,[3]=true,[14]=true,[16]=true,[23]=true}
	local FIELD_BAG_MESSAGE = {[8]=true,[9]=true,[10]=true,[11]=true,[12]=true,[15]=true,
		[19]=true,[20]=true,[21]=true,[22]=true}
	function PM.field_bag_screen(s)
		local ui, ctx, state = s.ui, s.ctx, s.state
		if state == 0 or state == 2 then return nil end
		local pocket = PM.text_at(395, s.kind)
		if not pocket then return nil end
		local prompt, row, text
		if FIELD_BAG_LIST[state] then
			local pos, index, name, count = PM.list(u32(ui + 0x15C), ui)
			if not pos then return nil end
			if count ~= s.count then return PM.fail("field bag: list/pocket count mismatch") end
			prompt = pocket
			if state == 3 then
				local moved = u32(ui + 0x47C)
				local items = u32(s.p)
				if moved >= 165 or not inram(items) or not inram(items + moved * 4 + 3) then return nil end
				local movedName=PM.text_at(392,u16(items+moved*4))
				if not movedName then return nil end
				prompt=PM.field_bag_text.MoveItemWhere:gsub("{0}",function() return movedName end)
			end
			if index == 0xFFFFFFFE then text = PM.field_bag_text.CloseBag
			elseif index < 165 then
				local items = u32(s.p)
				if not inram(items) or not inram(items + index * 4 + 3) then return nil end
				local id, quantity = u16(items + index * 4), u16(items + index * 4 + 2)
				if id == 0 or not name or quantity < 1 or quantity > 999 then return nil end
				if s.kind == 3 then -- TM/HM list draws the machine number and the move name
					local machine = PM.text_at(392, id)
					if not machine then return nil end
					name = machine .. ", " .. name
				end
				text = quantity .. " " .. name
				local n = count - (u8(ctx + 0x65) == 5 and 2 or 3)
				local separator = ", "
				if state ~= 3 then
					local desc = PM.text_at(391, id)
					if desc then text = text .. ". " .. desc; separator = " " end
				end
				text = text .. separator .. (index + 1) .. " de " .. n
			end
			return "items:" .. s.pocket .. ":" .. state, prompt, pos, text
		end
		if state == 4 then
			prompt = PM.text_at(392, u16(ctx + 0x66))
			row, text = PM.menu(u32(ui + 0x158))
		elseif state == 17 then
			-- ⛔ NOT THE LIVE STRING. ShowSaleCountValueWindow (BAG_APP_STATE_WAIT_SELL_HOW_MANY_MSG)
			-- calls BagUI_PrintSellCountAndValue, which formats the count and then the sale value into
			-- the SAME stringBuffer, before `*state` becomes 18. A frame that ends inside that call
			-- reads "$ 350" as a new message: the player's log (7 November) had the question, "$ 350",
			-- then the question again. This state is entered only after the Bag_Text_SellHowMany print
			-- (ProcessItemListInput_SellItems), so its prompt is that entry, exactly as state 18 says it.
			local item = PM.text_at(392, u16(ctx + 0x66))
			local template = PM.field_bag_text.SellHowMany
			if template and item then prompt = template:gsub("{0}", function() return item end) end
		elseif state == 7 or state == 18 then
			local quantity, limit = u16(ui + 0x488), u16(ui + 0x48A)
			if quantity < 1 or quantity > limit or limit > 999 then return nil end
			local item = PM.text_at(392, u16(ctx + 0x66))
			local template = state == 7 and PM.field_bag_text.ThrowAwayHowMany or PM.field_bag_text.SellHowMany
			if template and item then prompt = template:gsub("{0}", function() return item end) end
			row, text = quantity, tostring(quantity) .. " de " .. limit
			if state==18 then
				local price=u32(ui+0x48C)
				if limit>99 or price>999999 or price*quantity>999999 then return nil end
				text=quantity .. ", " .. PM.text_at(7,81,{[0]=price*quantity})
			end
		elseif state == 13 then
			-- HandleItemUsed sets task state 0 before TMHMUseTask replaces the
			-- scratch String (last used for move accuracy) with a visible message.
			local callback, taskstate = u32(ui + 0x484), u8(ui + 0x483)
			if callback == A.BagTMHMUseTask then
				if taskstate > 3 then return PM.fail("field bag: TM task state") end
				if taskstate == 0 then return nil end
				prompt = PM.message(u32(ui + 0x3F8), u8(ui + 0x426), 1024, ui)
				if taskstate == 3 then row, text = PM.menu(u32(ui + 0x158)) end
			elseif callback == A.BagItemUseTask then
				if taskstate > 2 then return PM.fail("field bag: item task state") end
				if taskstate ~= 1 then return nil end
				prompt = PM.message(u32(ui + 0x3F8), u8(ui + 0x426), 1024, ui)
			else return PM.fail("field bag: item-use callback") end
		elseif FIELD_BAG_MESSAGE[state] then
			prompt = PM.message(u32(ui + 0x3F8), u8(ui + 0x426), 1024, ui)
			if state == 9 or state == 20 then row, text = PM.menu(u32(ui + 0x158)) end
		end
		-- These state pairs add controls to the same message. Preserve its queue
		-- when the printer finishes, instead of interrupting it with the first row.
		local phase=({[17]=17,[18]=17,[19]=19,[20]=19,[21]=21,[22]=21})[state] or state
		return "bag:" .. phase, prompt, row, text
	end

