	-- ── THE JOURNAL ────────────────────────────────────────────────────────────────────────────
	-- A field child (sub_0203D30C 0203D30C copies template 020EA2E8 = {021D0D81, 021D0E71,
	-- 021D0EC5, 81} and calls FieldSystem_StartChildProcess), opened on Continue when the last
	-- session is two or more days old, and by the Journal key item. procState: 0 opening fade (page 0
	-- already printed by Init), 1 input, 2/3 page turn (the page byte and the new print happen on the
	-- turn's first frame), 4 closing. JournalManager is 0x1068 bytes: +0x44 journal pages,
	-- +0x4C saveData, s8 page +0x105C (TurnPageRight 021D12FE `ldrsb`/`adds #1`/`strb`).
	-- Every line is drawn from a template and freed (JournalPrinter_PrintEntry), so the page is
	-- rebuilt from the save exactly as journal_printer.c builds it, top to bottom.
	-- Save entry 18 (SaveData_GetJournal 0202B628 `movs r1,#0x12`), ten 0x70-byte pages
	-- (Journal_SaveSize 0202B604 = 0x460; page size 0x468 with SaveTableEntry_BodySize's padding).
	PM.journal_words = {page = "Página %d de %d"}
	function PM.journal_page()
		local ui, state = PM.field_app(A.JournalController_Main, 81)
		if not ui or state > 3 then return nil end
		if not inram(ui + 0x1067) then return PM.fail("journal: application data") end
		if u32(ui + 0x4C) ~= u32(A.sSaveDataPtr) then return PM.fail("journal: save owner") end
		local pages = save_page(18, 0x468, "journal")
		if not pages or u32(ui + 0x44) ~= pages then return PM.fail("journal: pages") end
		local page = u8(ui + 0x105C)
		if page > 9 then return PM.fail("journal: page index") end
		-- JournalController_PageExists: year (bits 0-6), month (7-10) or day (14-18) is set.
		local function exists(n) return u32(pages + n * 0x70) & 0x7C7FF ~= 0 end
		if not exists(page) then return nil end
		-- JournalController_NewDirectionPageExists walks neighbours one at a time from page 0.
		local count = 0
		while count < 10 and exists(count) do count = count + 1 end
		if page >= count then return PM.fail("journal: page beyond the written pages") end
		return {ui = ui, page = page, count = count, base = pages + page * 0x70}
	end
	function PM.journal_screen(s)
		local J = PM.journal_data
		local function fill(id, args)
			local t = J.text[id]
			if not t then return nil end
			local missing = false
			t = t:gsub("{(%d+)}", function(k)
				local v = args and args[tonumber(k)]
				if v == nil then missing = true; return "" end
				return tostring(v)
			end)
			return not missing and t or nil
		end
		local function label_of(map)
			if map >= 0x251 then return nil end
			return u8(A.sMapHeaders + map * 0x18 + 0x12)
		end
		-- StringTemplate_SetLocationName: label 0 or past the bank is "Faraway place".
		local function place(label)
			if not label then return nil end
			if label == 0 or label >= J.place_count then return PM.text_at(434, 2) end
			return PM.text_at(433, label)
		end
		local lines = {}
		local function add(line, what)
			if line then lines[#lines + 1] = line else PM.fail("journal: " .. what) end
		end
		local title = u32(s.base)
		local month, week, day, map = (title >> 7) & 0xF, (title >> 11) & 7, (title >> 14) & 0x1F, title >> 19
		if month < 1 or month > 12 then month = 1 end   -- StringTemplate_SetMonthName's own clamp
		local date = fill(J.date, {[0] = PM.text_at(414, month - 1), [1] = day})
		local weekday = week <= 6 and J.text[J.sunday + week] or nil
		if not date then return nil end
		add(weekday and (date .. ", " .. weekday) or date, "weekday")
		add(fill(J.started, {[0] = place(label_of(map))}), "start location")
		for i = 0, 3 do
			local v = u32(s.base + 4 + i * 4)
			local row = J.location[v & 0x3F]
			if not row then break end              -- NONE, UNUSED and unknown types end the list
			local kind, id, arg = row[1], row[2], v >> 16
			local line
			if kind == "fixed" then line = fill(id)
			elseif kind == "gym" then line = fill(id, {[0] = J.gyms[arg]})
			elseif kind == "gymleader" then line = fill(id, {[0] = J.gyms[arg], [1] = J.trainers[(v >> 6) & 0x3FF]})
			elseif kind == "trainer" then line = fill(id, {[0] = J.trainers[(v >> 6) & 0x3FF]})
			elseif kind == "map" then line = fill(id, {[0] = place(label_of(arg))})
			elseif kind == "cave" then
				line = fill(J.cave_departed[arg] and J.cave.departed or J.cave.through, {[0] = place(arg)})
			elseif kind == "building" then
				line = fill(J.exited[arg] and J.building.exited or J.building.departed, {[0] = place(arg)})
			elseif kind == "item" then line = fill(id, {[0] = PM.text_at(392, arg)}) end
			add(line, "location event " .. (v & 0x3F))
		end
		local result, packed, species = u8(s.base + 0x14), u8(s.base + 0x15), u16(s.base + 0x16)
		if result == 1 or result == 2 then
			local set = result == 1 and J.mon.caught or J.mon.defeated
			local variant, gender = packed & 3, (packed >> 6) & 3
			local id = variant < 2 and set[variant + 1] or gender == 0 and set[3] or gender == 1 and set[4] or set[1]
			add(fill(id, {[0] = PM.text_at(412, species), [1] = J.times[(packed >> 2) & 0xF]}), "Pokemon event")
		end
		local trainer = u16(s.base + 0x18)
		if trainer & 1 ~= 0 then
			local id, label = trainer >> 1, label_of(u16(s.base + 0x1A))
			-- JournalPrinter_PrintTrainerEvent picks its sentence from String_Length of the raw
			-- place and trainer entries; a rival's is the formatted save name's length.
			local name, length = J.trainers[id], label and J.place_len[label]
			if J.rival[id] then
				name = rival_name()
				local misc = save_page(SD_MISC, SD_MISC_SIZE, "journal rival")
				local n = 0
				while misc and n < 8 and u16(misc + SD_MISC_RIVAL + n * 2) ~= 0xFFFF do n = n + 1 end
				length = length and misc and n < 8 and length + n or nil
			else length = length and J.trainer_len[id] and length + J.trainer_len[id] end
			local line
			if name and length then
				local pick = length <= 14 and 1 or length <= 16 and 2 or length <= 19 and 3 or 4
				line = fill(J.trainer[pick], {[0] = place(label), [1] = name})
			end
			add(line, "trainer event")
		end
		for i = 0, 1 do
			local e = s.base + 0x1C + i * 0x2A
			local row = J.online[u8(e)]
			if not row then break end
			local kind, b1 = row[1], u8(e + 1)
			local line
			if kind == "fixed" then line = fill(row[2])
			elseif kind == "battle1" or kind == "battle2" then
				local r = (b1 >> 2) & 0xF
				local id = row[2 + (r < 2 and r or 2)]
				line = fill(id, {[0] = chars_name(e + 2, 8), [1] = kind == "battle2" and chars_name(e + 18, 8) or nil})
			elseif kind == "player" then line = fill(row[2], {[0] = chars_name(e + 2, 8)})
			elseif kind == "trade" then line = fill(row[2], {[0] = chars_name(e + 2, 8), [1] = chars_name(e + 18, 12)})
			elseif kind == "mon" then line = fill(row[2], {[0] = chars_name(e + 18, 12)})
			elseif kind == "number" then line = fill(row[2], {[0] = b1 & 0xF})
			elseif kind == "minigame" then line = fill(row[2], {[0] = J.minigames[b1 & 0xF]}) end
			add(line, "online event " .. u8(e))
		end
		-- Every event line ends in its own punctuation; only the date needs a full stop added.
		local body = lines[1] .. ". " .. table.concat(lines, " ", 2)
		if s.count > 1 then body = string.format(PM.journal_words.page, s.page + 1, s.count) .. ". " .. body end
		return "journal:" .. s.page, body
	end


	function PM.berry()
		local ui,state=PM.field_app(A.BerryTag_Main,85)
		if not ui or state~=1 then return nil end
		if not inram(ui+0x203) then return PM.fail("berry tag: application data") end
		local ctx,data=u32(ui+0x1F8),u32(ui+0x1FC)
		if not inram(ctx+11) or not inram(data+11) then return PM.fail("berry tag: arguments or berry data") end
		local id=u8(ctx+8)
		if id>63 or u32(ctx+4*(id//32))&(1<<(id%32))==0 then return PM.fail("berry tag: berry not in list") end
		return {ui=ui,ctx=ctx,data=data,id=id}
	end
	function PM.berry_screen(s)
		local name,desc=PM.text_at(424,s.id),PM.text_at(423,s.id)
		local size,firm=u16(s.data),u8(s.data+2)
		if not name or not desc or firm>5 or size>9999 then return nil end
		local n,before=0,0
		for i=0,63 do
			if u32(s.ctx+4*(i//32))&(1<<(i%32))~=0 then n=n+1; if i<=s.id then before=before+1 end end
		end
		local inches=(size*1000//254+5)//10
		local out={PM.text_at(398,0),string.format("%02d",s.id+1) .. " " .. name,
			PM.text_at(398,8) .. " " .. PM.text_at(398,9,{[0]=inches//10,[1]=inches%10}),
			PM.text_at(398,10) .. " " .. PM.text_at(398,11+math.max(0,firm-1))}
		for i=0,4 do out[#out+1]=PM.text_at(398,i+1) .. " " .. u8(s.data+6+i) end
		out[#out+1]=desc
		return "berry:" .. s.id,table.concat(out,". ") .. " " .. before .. " de " .. n
	end

	-- Summary's cached display data is populated by SetMonData 0208d1a4 at
	-- ui+250. The actual drawing consumers (02090578, 0209093c, 02091188) use
	-- these same fields. Its temporary Trainer Memo is freed after printing;
	-- reconstruct it with the cartridge templates and the checksum-verified mon.
	function PM.summary()
		local ui, state = PM.field_app(A.PokemonSummaryScreen_Main, 0xFFFFFFFF)
		if not ui then
			local evo, phase = CE.evolution()
			if evo and phase == 23 then
				local app = u32(evo + 0x38)
				ui = app_at(app, A.PokemonSummaryScreen_Main, 0xFFFFFFFF)
				if ui then state = u32(app + 0x14) end
			end
		end
		if not ui or state >= 18 then return nil end
		if not inram(ui + 0x6B3) then return PM.fail("summary: application data") end
		local ctx = u32(ui + 0x24C)
		if not inram(ctx) or not inram(ctx + 0x2F) then return PM.fail("summary: arguments") end
		local count, index, page = u8(ctx + 0x13), u8(ctx + 0x14), u8(ui + 0x6A4)
		local limit = count
		-- Select-move launchers lock navigation with monMax=1 while retaining
		-- the actual party slot. The native data consumer indexes the party.
		if u8(ctx + 0x11) == 1 and u8(ctx + 0x12) == 2 and count == 1 then
			local party = u32(ctx)
			if not inram(party) or not inram(party + 7) then return PM.fail("summary: source party") end
			limit = u32(party + 4)
			if limit == 0 or limit > 6 then return PM.fail("summary: source party count") end
		end
		if count == 0 or count > 30 or index >= limit or page > 7 or u8(ctx + 0x12) > 4 then
			return PM.fail("summary: page or Pokemon index")
		end
		if u8(ctx + 0x15) & (1 << page) == 0 then return nil end
		return {ui=ui,ctx=ctx,state=state,page=page,index=index,count=count,mon=ui+0x250}
	end
	function PM.summary_source(s)
		local kind, first = u8(s.ctx + 0x11), u32(s.ctx)
		if not inram(first) then return PM.fail("summary: Pokemon source") end
		if kind == 1 then
			if not inram(first + 7) or u32(first + 4) > 6 or s.index >= u32(first + 4) then
				return PM.fail("summary: source party count")
			end
			return first + 8 + s.index * 236
		elseif kind == 0 then return first + s.index * 236
		elseif kind == 2 then return first + s.index * 136 end
		return PM.fail("summary: Pokemon source type")
	end
	function PM.met_location(id)
		if id == 0 then return PM.text_at(435, 12) end -- Mystery Zone, game's fallback
		local bank, index = 433, id
		if id >= 3000 then bank,index = 434,id-3000
		elseif id >= 2000 then bank,index = 435,id-2000 end
		return PM.text_at(bank,index) or PM.text_at(434,2)
	end
	function PM.memo(s)
		local source = PM.summary_source(s)
		local d = source and PM.boxdata(source)
		if not d or d.word(1,0) ~= u16(s.mon + 12) then return PM.fail("summary: memo species mismatch") end
		local b,w,l = d.byte,d.word,d.long
		local egg = l(2,0x10) & 0x40000000 ~= 0
		local fateful = b(2,0x18) & 1 ~= 0
		local eggloc, metloc = w(4,0x16),w(4,0x18)
		if eggloc == 3002 and w(2,0x1C) ~= 0 then eggloc = w(2,0x1C) end
		if metloc == 3002 and w(2,0x1E) ~= 0 then metloc = w(2,0x1E) end
		local own = false
		if u32(s.mon + 0x14) == u32(s.ctx + 12) and u8(s.mon + 0x44) == u8(s.ctx + 0x10) then
			local ot, player = str_name(u32(s.mon + 8),8),str_name(u32(s.ui + 0x698),8)
			if not ot or not player then return PM.fail("summary: memo trainer names") end
			own = ot == player
		end
		local status
		if egg then
			if own then status = fateful and (eggloc == 3001 and 20 or 18) or 16
			else status = fateful and 19 or 17 end
		elseif eggloc == 0 then
			if metloc == 55 then status = 15
			elseif fateful then status = own and 7 or 8
			elseif metloc == 2001 then status = 2
			else status = own and 0 or 1 end
		elseif fateful then
			if eggloc == 2002 then status = own and 13 or 14
			elseif eggloc == 3001 then status = own and 11 or 12
			else status = own and 9 or 10 end
		else
			local traded = eggloc == 2000 or eggloc == 2001 or (eggloc >= 2009 and eggloc <= 2011)
			status = traded and (own and 5 or 6) or (own and 3 or 4)
		end
		local function month(n) return PM.text_at(414, (n >= 1 and n <= 12 and n or 1)-1) end
		local args = {[0]=string.format("%02d",b(4,0x13)),month(b(4,0x14)),b(4,0x15),b(4,0x1C)&127,
			PM.met_location(metloc),string.format("%02d",b(4,0x10)),month(b(4,0x11)),b(4,0x12),PM.met_location(eggloc)}
		local out = {}
		if not egg then
			out[#out+1] = PM.text_at(455,24+d.personality%25)
			if status == 15 then
				local version = b(3,0x17)
				local loc = (version == 4 or version == 5) and 2003
					or (version == 7 or version == 8) and 2004
					or (version >= 1 and version <= 3) and 2005 or version == 15 and 2008 or 2007
				args[4] = PM.met_location(loc)
			end
			local info = PM.text_at(455,49+status,args)
			if not info then return nil end
			out[#out+1] = info
			local ivs, best, value = l(2,0x10),d.personality%6,-1
			for i = 0,5 do
				local stat = (d.personality%6+i)%6
				local v = (ivs >> (stat*5)) & 31
				if v > value then best,value = stat,v end
			end
			out[#out+1] = PM.text_at(455,71+best*5+value%5)
			if status <= 8 or status == 15 then
				local flavor = PM.favorite_flavor[d.personality%25+1]
				out[#out+1] = PM.text_at(455,flavor < 0 and 70 or 65+flavor)
			end
		else
			if status == 17 or status == 19 then args[5],args[6],args[7],args[8] = args[0],args[1],args[2],args[4] end
			local info = PM.text_at(455,({[16]=101,102,103,103,104})[status],args)
			if not info then return nil end
			out[#out+1] = info
			local friendship = b(1,12)
			out[#out+1] = PM.text_at(455,friendship <= 5 and 105 or friendship <= 10 and 106 or friendship <= 40 and 107 or 108)
		end
		return table.concat(out," ")
	end
	-- The five contest category labels and graph axes are baked into graphics.
	local CONTEST_TYPES = {[0]="Carisma", "Belleza", "Dulzura", "Ingenio", "Dureza"}
	function PM.contest_move(id)
		local data, name = PM.move_data[id],BTLTEXT.moves[id]
		if not data or not name then return nil end
		local category, points, desc = CONTEST_TYPES[data[7]],PM.appeal[data[6]],PM.text_at(210,45+data[6])
		if not category or not points or not desc then return nil end
		return name .. ", " .. category .. ", " .. PM.summary_text.LabelAppealPoints .. " " .. points .. ". " .. desc
	end
	function PM.summary_move(s, slot, detail)
		if slot > 4 then return nil end
		local id, pp, maxpp
		if slot == 4 then
			id = u16(s.ctx + 0x18)
			if id == 0 then return PM.summary_text.MoveCancel end
			local data = PM.move_data[id]
			if not data then return nil end
			pp,maxpp = data[5],data[5]
		else id,pp,maxpp = u16(s.mon+0x34+slot*2),u8(s.mon+0x3C+slot),u8(s.mon+0x40+slot) end
		if id == 0 then return nil end
		return s.page == 5 and PM.contest_move(id) or PM.move(id,pp,maxpp,detail)
	end
	-- ⚠ Poffin feeding (state 16): a message is printed only when the player presses A or B in
	-- state 16 (PrintContestStatChangeMsgs 0x0208D114 prints the lowest set bit of the change mask
	-- pageState +0x6A6 and clears it), so on entry the summary String still holds whatever the
	-- condition page formatted last. The mask the state was entered with is remembered here; a
	-- cleared bit is the game's own witness that a message is now in the String.
	local summary_feed = {}
	function PM.summary_screen(s)
		local state, m, t = s.state,s.mon,PM.summary_text
		if state ~= 16 then summary_feed.ui = nil
		elseif summary_feed.ui ~= s.ui then summary_feed.ui,summary_feed.mask = s.ui,u8(s.ui+0x6A6) end
		if state < 2 or state == 3 or state == 4 or state == 5 or state == 6 or state == 11 or state == 12 or state == 14 or state == 15 then return nil end
		local name = str_name(u32(m+4),12)
		local species, level, gender = u16(m+12),u8(m+0x12)&127,u8(m+0x13)&3
		if not name or species < 1 or species > 493 or level < 1 or level > 100 or gender > 2 then return nil end
		local flags = u32(m+0x50)
		local egg = flags & 0x10000000 ~= 0
		local heading = name
		if not egg then
			heading = heading .. ", " .. PM.party_text.PokemonLevelLabel .. " " .. level
			-- The symbol is drawn only when hideGender (bit 7 of +0x12) is clear
			-- (PokemonSummaryScreen_PrintNicknameAndGender `lsrs r1,r1,#0x1f ; bne` 0x0208FEDA).
			if gender < 2 and u8(m+0x12) & 0x80 == 0 then heading = heading .. " " .. CHARMAP[gender == 0 and 0x1BB or 0x1BC] end
			-- UpdateStatusIcon 0208ee9c consumes low28; UpdateMiscMonDataSprites
			-- 0208f574 consumes shiny bit29 and cured-Pokerus value2 in bits30–31.
			local status = flags & 0x0FFFFFFF
			if status > 7 or flags >> 30 > 2 then return nil end
			if STATUS_ICONS[status] then heading = heading .. ", " .. STATUS_ICONS[status] end
			if flags & 0x20000000 ~= 0 then heading = heading .. ", shiny" end
			if flags >> 30 == 2 then heading = heading .. ", cured Pokérus" end
		end
		local titles = {t.PageTitleInfo,t.PageTitleMemo,t.PageTitleSkills,t.PageTitleBattleMoves,
			t.PageTitleCondition,t.PageTitleContestMoves,t.PageTitleRibbons,t.PromptExit}
		local title = titles[s.page+1]
		local key = "summary:" .. s.index .. ":" .. s.page .. ":" .. state
		if state == 10 then return key,t.HmMovesCantBeForgotten end
		if state == 16 and u8(s.ui+0x6A6) == summary_feed.mask then return nil end
		if state == 16 or state == 17 then return key,PM.message(u32(s.ui+0x694),255,1024) end
		if state == 7 or state == 8 or state == 9 then
			local cursor = u8(s.ui+0x6A5)&15
			local row = PM.summary_move(s,cursor,true)
			if row then row = row .. ", " .. (cursor+1) .. " de 5" end
			-- The second move selector is a graphic, with no text prompt.
			if state == 8 then title = title .. ", Switch moves" end
			return key,title,cursor,row,s.index,heading
		end
		if state == 13 then
			local id, count = u8(s.ui+0x6B2),u8(s.ui+0x6B1)
			local index = u8(s.ui+0x6AF)+u8(s.ui+0x6B0)*4
			local ribbon = PM.text_at(535,PM.ribbon_names[id])
			-- ⚠ NOT THE SUMMARY STRING. ChangeSelectedRibbon prints the name and description and
			-- THEN the "n / max" index, which formats into the same String +0x694, so after every
			-- move it holds the index number. The description is the one
			-- PokemonSummaryScreen_GetRibbonDescriptionID picks: the table entry, or for a special
			-- ribbon (bit 15) 0x92 + the byte at args +0x20 (specialRibbons) indexed by its low byte.
			local raw, entry = PM.ribbon_desc[id], nil
			if raw and raw & 0x8000 ~= 0 then
				local special = u32(s.ctx+0x20)
				if not inram(special) or not inram(special+(raw & 0xFF)) then return PM.fail("summary: special ribbon bytes") end
				entry = u8(special+(raw & 0xFF))+0x92
			else entry = raw end
			local desc = entry and PM.text_at(535,entry)
			if not ribbon or not desc or index >= count then return nil end
			return key,title,index,ribbon .. ". " .. desc .. " " .. (index+1) .. " de " .. count,s.index,heading
		end
		local out = {title}
		if s.page == 0 then
			local dex = u32(s.ctx+0x1C) == 0 and PM.sinnoh_dex[species] or species
			local ot, kind1, kind2 = str_name(u32(m+8),8),PM.text_at(624,u8(m+0x10)),PM.text_at(624,u8(m+0x11))
			if not dex or not ot or not kind1 or not kind2 then return nil end
			out[#out+1] = t.LabelDexNum .. " " .. (dex == 0 and t.ThreeQuestionMarks or string.format("%03d",dex))
			out[#out+1] = PM.text_at(412,species)
			out[#out+1] = t.LabelType .. " " .. kind1 .. (kind1 ~= kind2 and ", " .. kind2 or "")
			out[#out+1] = t.LabelOTName .. " " .. ot
			out[#out+1] = t.LabelOtId .. " " .. string.format("%05d",u32(m+0x14)&0xFFFF)
			out[#out+1] = t.LabelExp .. " " .. u32(m+0x18)
			local nextxp = level == 100 and 0 or u32(m+0x20)-u32(m+0x18)
			if nextxp < 0 then return nil end
			out[#out+1] = t.LabelExpNextLv .. " " .. nextxp
		elseif s.page == 1 then
			local memo = PM.memo(s)
			if not memo then return nil end
			out[#out+1] = memo
		elseif s.page == 2 then
			local hp,maxhp = u16(m+0x24),u16(m+0x26)
			if hp > maxhp or maxhp == 0 or maxhp > 999 then return nil end
			out[#out+1] = t.LabelHp .. " " .. hp .. " de " .. maxhp
			for i,label in ipairs({t.LabelAttack,t.LabelDefense,t.LabelSpAttack,t.LabelSpDefense,t.LabelSpeed}) do
				out[#out+1] = label .. " " .. u16(m+0x26+i*2)
			end
			local ability, desc = PM.text_at(610,u8(m+0x32)),PM.text_at(612,u8(m+0x32))
			if not ability or not desc then return nil end
			out[#out+1] = t.LabelAbility .. " " .. ability .. ". " .. desc
		elseif s.page == 3 or s.page == 5 then
			for slot = 0,3 do
				if u16(m+0x34+slot*2) ~= 0 then
					local move = PM.summary_move(s,slot,false)
					if not move then return nil end
					out[#out+1] = move
				end
			end
		elseif s.page == 4 then
			for i=0,4 do out[#out+1] = CONTEST_TYPES[i] .. " " .. u8(m+0x45+i) .. " de 255" end
			out[#out+1] = t.LabelSheen .. " " .. u8(m+0x4A) .. " de 255"
			local favorite = PM.text_at(455,166+u8(m+0x4B))
			if favorite then out[#out+1] = t.FavoriteFood .. " " .. favorite end
		elseif s.page == 6 then out[#out+1] = t.LabelRibbonCount .. " " .. u8(s.ui+0x6B1) end
		if not egg and s.page ~= 1 then
			local item = u16(m+14) == 0 and t.None or PM.text_at(392,u16(m+14))
			if not item then return nil end
			out[#out+1] = t.LabelItem .. " " .. item
		end
		return key,table.concat(out,". "),nil,nil,s.index,heading
	end

	-- PokedexMain_Main 021d0e78 dereferences ApplicationManager_Data once more.
	-- Retail allocation is 1d10, NOT the offsets embedded in old C member names.
	-- Main/sub screen managers are +1a30/+1bc0, stride28; four updater owners
	-- live at +1d00. UpdateData calls updater+24 with dataMan+0c and pageData+0.
	function PM.dex()
		local holder,state = PM.field_app(A.PokedexMain_Main,21)
		if not holder or state ~= 1 then return nil end
		local ui = u32(holder)
		if not inram(ui) or not inram(ui+0x1D0F) or u32(ui) ~= 0 or u32(ui+4) ~= 37 then return nil end
		local sort = ui+12
		local count,display,national = u32(sort+0x172C),u32(sort+0x1728),u32(sort+0x1730)
		if count > 493 or display >= count or national > 1 or u32(sort+0xF70) > 493 then
			return PM.fail("Pokedex: sorted list bounds")
		end
		local save = u32(sort)
		if not inram(save) or not inram(save+0x323) or u32(save) ~= 0xBEEFCAFE then return PM.fail("Pokedex: save identity") end
		return {ui=ui,sort=sort,save=save,count=count,display=display,national=national}
	end
	local dex_owner_cache={}
	function PM.dex_pages(s)
		local main,sub = {},{}
		for slot=0,3 do
			local up = u32(s.ui+0x1D00+slot*4)
			if not inram(up) or not inram(up+0x47) then return PM.fail("Pokedex: updater allocation") end
			if u32(up+8) == 2 and u32(up+0x18) == 0 and u32(up+0x1C) == 0 then
				local data,callback=u32(up),u32(up+0x24)
				local cached=dex_owner_cache[slot]
				local first,last=0,17
				if cached and cached.ui==s.ui and cached.data==data and cached.callback==callback
					and u32(cached.manager)==data and u32(cached.manager+12)==callback then first,last=cached.index,cached.index end
				local found
				for i=first,last do
					local manager = s.ui+(i<10 and 0x1A30+i*0x28 or 0x1BC0+(i-10)*0x28)
					if u32(manager) == data and u32(manager+12) == callback then
						if found then return PM.fail("Pokedex: ambiguous page owner") end
						if not inram(data) then return PM.fail("Pokedex: page data") end
						local page = {data=data,work=u32(up+0x14),state=u32(up+12),graphics=u32(up+0x34),gstate=u32(up+0x2C),up=up}
						if i<10 then main[i]=page else sub[i-10]=page end
						found = true
						dex_owner_cache[slot]={ui=s.ui,data=data,callback=callback,index=i,manager=manager}
					end
				end
				if not found then return PM.fail("Pokedex: unowned active updater") end
			end
		end
		return main,sub
	end
	function PM.dex_panel(panel)
		if not inram(panel) or not inram(panel+19) then return PM.fail("Pokedex: cursor panel") end
		local array,cols,rows,col,row = u32(panel),u32(panel+4),u32(panel+8),u32(panel+12),u32(panel+16)
		if cols<1 or rows<1 or cols*rows>36 or col>=cols or row>=rows or not inram(array)
			or not inram(array+cols*rows*28-1) then return PM.fail("Pokedex: cursor layout") end
		return u32(array+(row*cols+col)*28+24)
	end
	function PM.dex_species(s,display)
		local index = display and u32(s.sort+0xF74+s.display*4) or u32(s.sort+0xF6C)
		if display and index == 494 then return 0,0 end
		if index >= u32(s.sort+0xF70) or index >= 493 then return nil end
		local p = s.sort+4+index*8
		local species,status = u32(p),u32(p+4)
		if species<1 or species>493 or status<1 or status>2 then return nil end
		local bit = 1<<((species-1)%8)
		if u8(s.save+0x44+(species-1)//8)&bit==0 then return nil end
		if status==2 and u8(s.save+4+(species-1)//8)&bit==0 then return nil end
		return species,status
	end
	local DEX_SHAPES = {[0]="Ninguna", "Cuatro patas", "Dos patas sin cola", "Dos patas con cola",
		"Serpentina", "Varias alas", "Dos alas", "Cuerpo de insecto", "Cabeza y base", "Cabeza y brazos",
		"Cabeza y patas", "Tentáculos", "Aletas", "Solo cabeza", "Varios cuerpos"} -- silhouette art
	function PM.dex_search(s,main,sub)
		local t,p = PM.dex_text,main.data
		if not inram(p+0x37) or u32(p+4)~=s.sort then return nil end
		local state,method = u32(p+0x30),u32(p+12)
		if method>3 or state>4 then return nil end
		if state==1 or state==2 then return "searching",t.searching end
		if u32(p+0x2C)~=0 then return "no results",t.nonefound end
		if state~=0 or not sub or sub.state~=0 or not inram(sub.work) or not inram(sub.work+0x9B) then return nil end
		local work = sub.work
		if u32(work+0x24)~=method or u32(work+0x28)~=u32(work+0x20) then return nil end
		local button = PM.dex_panel(u32(work+0x18))
		if not button then return nil end
		local order = {t.numerical,t.alphabetical,t.heaviest,t.lightest,t.tallest,t.smallest}
		local names = {t.abc,t.def,t.ghi,t.jkl,t.mno,t.pqr,t.stu,t.vwx,t.yz,t.nonealphabetical}
		local types = {t.normal,t.fight,t.flying,t.poison,t.ground,t.rock,t.bug,t.ghost,t.steel,t.fire,t.water,t.grass,t.electric,t.psychic,t.ice,t.dragon,t.dark}
		local type1,type2 = u32(p+0x18),u32(p+0x1C)
		local selected = {order[u32(p+0x10)+1],names[u32(p+0x14)==0 and 10 or u32(p+0x14)],
			(type1==0 and t.nonetype or types[type1]),DEX_SHAPES[u32(p+0x20)]}
		if not selected[1] or not selected[2] or not selected[3] or not selected[4] or type2>17 then return nil end
		if type2~=0 then selected[3]=selected[3] .. ", " .. types[type2] end
		local prompt = ({t.listing_description,t.alphabetical_description,t.type_description,t.body_description})[method+1]
		local text,count,index
		if button<6 then
			text = ({[0]=t.cancel,t.order,t.name,t.type,t.form,t.ok})[button]
			if button>=1 and button<=4 then text = text .. ", " .. selected[button] end
			count,index = 6,button
		else
			index = button-6
			if method==0 then text,count = order[index+1],6
			elseif method==1 then text,count = names[index+1],10
			elseif method==2 then
				local half=u32(work+0x28)
				if half==0 then text,count = index<9 and types[index+1] or index==9 and t.nonetype or index==10 and t.next or nil,11
				elseif half==1 then text,count = index<8 and types[index+10] or index==8 and t.nonetype or index==9 and t.back or nil,10 end
			else
				local shape=({13,4,12,9,8,3,10,1,6,11,14,2,5,7,0})[index+1]
				text,count = DEX_SHAPES[shape],15
			end
		end
		if text then text = text .. ", " .. (index+1) .. " de " .. count end
		-- Include chosen filters in the change key: pressing A may select an option
		-- without moving the cursor. Re-read that choice when its setting changes.
		local row = button .. ":" .. table.concat(selected,"|")
		return "search:" .. method .. ":" .. u32(work+0x28),prompt,row,text
	end
	function PM.dex_form(s,p,species)
		if not inram(p+23) or u32(p+4)~=s.sort then return nil end
		local cat,count,index = u32(p+12),u32(p+16),u32(p+20)
		if cat>12 or count<1 or count>28 or index>=count then return nil end
		local t,form,text = PM.dex_text
		if cat==0 then
			if index>1 then return nil end
			local bit = 1<<((species-1)%8)
			form = u8(s.save+0x84+index*0x40+(species-1)//8)&bit~=0 and 1 or 0
			text = form==0 and t.male or t.female
		elseif cat==1 then text=t.male
		elseif cat==2 then text=t.female
		elseif cat==3 then text=t.oneform
		elseif cat==8 then
			form=u8(s.save+0x10C+index)
			if form>27 then return nil end
			text=t.oneform .. ", " .. (form<26 and string.char(65+form) or form==26 and "!" or "?")
		elseif cat==9 then
			if index>3 then return nil end
			form=(u32(s.save+(index<2 and 0x40 or 0x80))>>(24+(index%2)*4))&15
			if form>3 then return nil end
			text=PM.text_at(697,111+form)
		elseif cat==12 then
			if index>5 then return nil end
			form=(u32(s.save+0x31C)>>(index*3))&7
			if form>5 then return nil end
			text=PM.text_at(697,119+form)
		else
			local offsets={[4]=0x108,[5]=0x109,[6]=0x10A,[7]=0x10B,[10]=0x320,[11]=0x321}
			local off=offsets[cat]
			if not off then return nil end
			if cat==6 or cat==7 then
				if index>2 then return nil end
				form=(u8(s.save+off)>>(index*2))&3
				if form>2 then return nil end
				text=PM.text_at(697,17+form)
			else
				if index>1 then return nil end
				form=(u8(s.save+off)>>index)&1
				text=PM.text_at(697,(cat==10 and 115 or cat==11 and 117 or 15)+form)
			end
		end
		return index,text and text .. ", " .. (index+1) .. " de " .. count
	end
	function PM.dex_types(s,species)
		local form=0
		if species==386 then form=(u32(s.save+0x40)>>24)&15
		elseif species==413 then form=u8(s.save+0x10B)&3
		elseif species==479 then form=u32(s.save+0x31C)&7
		elseif species==487 then form=u8(s.save+0x321)&1
		elseif species==492 then form=u8(s.save+0x320)&1 end
		local d=PM.form_data(species,form)
		if not d then return nil end
		local a,b=PM.text_at(624,d[1]),PM.text_at(624,d[2])
		if not a or not b then return nil end
		return d[1]==d[2] and a or a .. ", " .. b
	end
	function PM.dex_areas(p)
		local work=p.work
		if p.gstate~=0 or not inram(work+0x33) or u32(work)~=u32(p.data+4) then return nil end
		local hidden={fields={},dungeons={}}
		for _,v in ipairs({{"fields",4,12,50},{"dungeons",8,16,21}}) do
			local ptr,n=u32(work+v[2]),u32(work+v[3])
			if n>v[4] or (n>0 and (not inram(ptr) or not inram(ptr+n-1))) then return PM.fail("Pokedex: hidden encounter list") end
			for i=0,n-1 do hidden[v[1]][u8(ptr+i)]=true end
		end
		local out,spoken={},{}
		for _,v in ipairs({{"dungeons",0x14,21},{"fields",0x1C,50},{"dungeons",0x24,21},{"fields",0x2C,50}}) do
			local ptr,n=u32(work+v[2]),u32(work+v[2]+4)
			if n<1 or n>v[3]+1 or not inram(ptr) or not inram(ptr+4*n-1) or u32(ptr+4*(n-1))~=0 then
				return PM.fail("Pokedex: encounter list bounds or terminator")
			end
			for i=0,n-2 do
				local id=u32(ptr+4*i)
				local label=PM.dex_area_labels[v[1]][id]
				if not label then return PM.fail("Pokedex: unmapped encounter area") end
				if not hidden[v[1]][id] then
					local text=PM.text_at(433,label)
					if not text then return nil end
					if not spoken[label] then out[#out+1]=text; spoken[label]=true end
				end
				hidden[v[1]][id]=true -- regular locations also mask special overlays
			end
		end
		return #out==0 and PM.dex_text.areaunknown or table.concat(out,", ")
	end
	function PM.dex_screen(s)
		local main,sub = PM.dex_pages(s)
		if not main then return nil end
		if main[1] then return PM.dex_search(s,main[1],sub[1]) end
		local species,status = PM.dex_species(s,main[0]~=nil)
		if not species then return nil end
		local t=PM.dex_text
		if main[0] then
			local seen,caught=u32(s.sort+0x1738),u32(s.sort+0x173C)
			if seen>493 or caught>seen then return nil end
			local title = s.national==1 and "National Pokédex" or "Sinnoh Pokédex" -- title graphics
			local prompt = title .. ", " .. t.seen .. " " .. seen .. ", " .. t.obtained .. " " .. caught
			local text = species==0 and t.dash or PM.text_at(412,species)
			if not text then return nil end
			if status==2 then text=text .. ", " .. t.obtained end
			return "Pokedex list:" .. s.national,prompt,s.display,text .. ", " .. (s.display+1) .. " de " .. s.count
		end
		local name=PM.text_at(412,species)
		if not name or species==0 then return nil end
		local row,text,page,prompt
		if main[2] then
			page="entry"
			local shown=status==2 and species or 0
			local hb,wb=u32(A.PokedexMessageBanks+8),u32(A.PokedexMessageBanks)
			if (hb~=709 and hb~=710) or (wb~=707 and wb~=708) then return nil end
			local height,weight,entry=PM.text_at(hb,shown),PM.text_at(wb,shown),shown==0 and "" or PM.text_at(706,shown)
			if not height or not weight or not entry then return nil end
			prompt = name .. ". " .. t.info .. ". " .. t.ht .. " " .. height .. ", " .. t.wt .. " " .. weight .. ". " .. entry
			if shown~=0 then
				local category,types=PM.text_at(711,species),PM.dex_types(s,species)
				if not category or not types then return nil end
				prompt=name .. ", " .. category .. ", " .. types .. ". " .. t.ht .. " " .. height .. ", " .. t.wt .. " " .. weight .. ". " .. entry
			end
		elseif main[4] then
			local p=main[4].data
			if not inram(p+31) or u32(p+4)~=s.sort then return nil end
			local lang=u32(p+24)
			local banks={[1]=705,[2]=706,[3]=701,[4]=703,[5]=702,[7]=704}
			local labels={[1]=t.japanese,[2]=t.english,[3]=t.french,[4]=t.italian,[5]=t.german,[7]=t.spanish}
			local entry=PM.text_at(banks[lang],status==2 and species or 0)
			if not entry or not labels[lang] then return nil end
			local names={[1]=717,[2]=412,[3]=713,[4]=715,[5]=714,[7]=716}
			local categories={[1]=723,[2]=711,[3]=719,[4]=721,[5]=720,[7]=722}
			local foreignName,category=PM.text_at(names[lang],species),PM.text_at(categories[lang],species)
			if not foreignName or not category then return nil end
			page,prompt="foreign:" .. lang,foreignName .. ", " .. labels[lang] .. ", " .. category .. ". " .. entry
		elseif main[3] and main[3].gstate==0 then
			page,prompt="forms",name .. ", " .. t.forms
			row,text=PM.dex_form(s,main[3].data,species)
		elseif main[8] or main[9] then
			local height=main[8]~=nil
			local bank=u32(A.PokedexMessageBanks+(height and 8 or 0))
			if (height and bank~=709 and bank~=710) or (not height and bank~=707 and bank~=708) then return nil end
			local value=PM.text_at(bank,species)
			local trainerGender=u32(s.sort+0x1750)
			if not value or trainerGender>1 then return nil end
			page=height and "height" or "weight"
			prompt=name .. ", " .. (height and t.heightcheck_topscreen or t.weightcheck_topscreen) .. ", " .. value
			prompt=prompt .. ", " .. (height and (trainerGender==0 and t.lucasheight or t.dawnheight) or (trainerGender==0 and t.lucasweight or t.dawnweight))
		elseif main[6] then
			local p=main[6].data
			if not inram(p+11) or u32(p)~=s.sort or u32(p+4)>2 then return nil end
			page,prompt="area:" .. u32(p+4),name .. ", " .. t.area .. ", " .. PM.text_at(697,36+u32(p+4))
			local areas=PM.dex_areas(main[6])
			if not areas then return nil end
			prompt=prompt .. ". " .. areas
		elseif main[7] then page,prompt="cry",name .. ", " .. t.cry end
		if not page then return nil end
		-- The common tab cursor remains active over the entry pages; down transfers
		-- control to the selected page. Its dataMan points to work+14 -> panel.
		local nav=sub[3]
		if nav and inram(nav.data+0x33) and inram(nav.work+0x1B) and u32(nav.data+0x30)==0 then
			local button=PM.dex_panel(u32(nav.work+0x14))
			if button and button<6 then
				row,text="tab:" .. button,({t.info,t.area,t.cry,t.size,t.forms,t.quit})[button+1]
			end
		elseif nav and inram(nav.data+0x33) and u32(nav.data+0x30)==1 and status==2 then
			if main[6] and sub[4] then
				local time=u32(main[6].data+4)
				row,text="time:" .. time,PM.text_at(697,36+time) .. ", " .. (time+1) .. " de 3"
			elseif (main[8] or main[9]) and sub[6] and inram(sub[6].data+15) and u32(sub[6].data+8)==s.sort then
				local selected=u32(sub[6].data+4)
				if selected>1 then return nil end
				row,text="compare:" .. selected,selected==0 and t.weightcheck_topscreen or t.heightcheck_topscreen
			elseif main[7] and sub[5] and inram(sub[5].data+11) and u32(sub[5].data+4)==s.sort then
				row,text="play","Play cry" -- triangle button graphic
			end
		end
		return "Pokedex:" .. page .. ":" .. species,prompt,row,text
	end

	function PM.register(name, detect, read, lead_with_row, queue_initial, on_close)
		local owner, page, prompt, row, queued, subject
		MODULES[#MODULES + 1] = {
			name = name,
			detect = function() return detect() ~= nil end,
			on_exit = function()
				PM.forget_message(owner)
				if on_close then on_close() end
				owner,page,prompt,row,queued,subject = nil,nil,nil,nil,nil,nil
			end,
			update = function()
				local s = detect()
				if not s then return end
				local nextpage, nextprompt, nextrow, text, nextsubject, heading = read(s)
				if not nextpage then return end
				if owner ~= s.ui then
					PM.forget_message(owner)
					owner,page,prompt,row,queued,subject = s.ui,nil,nil,nil,nil,nil
				end
				if page ~= nextpage then page,row,queued = nextpage,nil,nil end
				-- A selected Pokedex tab introduces its contents. Other screens keep
				-- their question/title before the selected item or action.
				local row_first = lead_with_row and lead_with_row(nextrow)
				if row_first and nextrow ~= row then
					row = nextrow
					if text then say(text); queued = true end
				end
				-- Summary's identity header belongs to the Pokemon, not each tab.
				-- Keep the cached prompt without that prefix so the next frame stays silent.
				local newsubject = nextsubject ~= nil and nextsubject ~= subject
				local spoke_prompt = nextprompt and (nextprompt ~= prompt or newsubject)
				if spoke_prompt then
					say(newsubject and (heading .. ", " .. nextprompt) or nextprompt, not (row_first and queued))
					prompt,queued = nextprompt,not row_first
					if newsubject then subject = nextsubject end
				end
				if not row_first and nextrow ~= nil and (nextrow ~= row or spoke_prompt) then
					local first = row == nil
					row = nextrow
					-- A prompt can precede its menu by several frames or survive a native
					-- state change. Only the landing queues; subsequent cursor moves interrupt.
					if text then
						say(text, not (spoke_prompt or first and (queued or nextprompt or queue_initial)))
						queued = nil
					end
				end
			end,
		}
		-- Returned so a caller can attach optional fields, such as `describe` (core/describe.lua).
		return MODULES[#MODULES]
	end
	-- Y-button messages have their own FieldTask and never use ScriptManager.
	-- The state changes only after FieldMessage_Print returns; state2 has already
	-- erased the window and will free the String. Match the active head task.
	function PM.registered_item_message()
		local fs = field_map_live()
		if not fs then return nil end
		local task = u32(fs + 0x10)
		if not inram(task) or not inram(task + 0x1F)
			or u32(task + 4) ~= A.PrintRegisteredKeyItemUseMessage then return nil end
		if u32(task + 0x18) ~= fs then return PM.fail("registered item: task owner") end
		local ui = u32(task + 0x0C)
		if not inram(ui) or not inram(ui + 0x17) then return PM.fail("registered item: data") end
		if u16(ui + 0x16) ~= 1 then return nil end
		return {ui=ui}
	end
	PM.register("registered item message", PM.registered_item_message, function(s)
		return "message", PM.message(u32(s.ui + 0x10), u16(s.ui + 0x14), 128, s.ui)
	end)
	function PM.catch_dex()
		local task = CE.catch_task(13)
		if not task then return nil end
		local ui = u32(task + 0x50)
		if not inram(ui) or not inram(ui + 0x1E7) then return PM.fail("catch Pokedex: data") end
		-- Retail offsets differ from the old offset-like names in the source.
		if u32(ui + 0x1B8) ~= 4 or u32(ui + 0x1E4) ~= 1 then return nil end
		local species, national = u32(ui + 0x1BC), u32(ui + 0x17C)
		if species < 1 or species > 493 or national > 1 or u32(ui + 0x178) ~= species then
			return PM.fail("catch Pokedex: species label")
		end
		return {ui=ui,species=species,national=national}
	end
	function PM.catch_dex_screen(s)
		local species, t = s.species, PM.dex_text
		local hb, wb = u32(A.PokedexMessageBanks + 8), u32(A.PokedexMessageBanks)
		if (hb ~= 709 and hb ~= 710) or (wb ~= 707 and wb ~= 708) then return nil end
		local name, category, data = PM.text_at(412,species), PM.text_at(711,species), PM.form_data(species,0)
		local height, weight, entry = PM.text_at(hb,species), PM.text_at(wb,species), PM.text_at(706,species)
		if not name or not category or not data or not height or not weight or not entry then return nil end
		-- This native page uses base species types, even for alternate forms.
		local first, second = PM.text_at(624,data[1]), PM.text_at(624,data[2])
		if not first or not second then return nil end
		local types = data[1] == data[2] and first or first .. ", " .. second
		local number = s.national == 1 and species or PM.sinnoh_dex[species]
		if not number then return nil end
		local label = number > 0 and string.format("%03d",number) or t.none
		if not label then return nil end
		return "entry", t.registered .. " " .. label .. " " .. name .. ", " .. category .. ", " .. types
			.. ". " .. t.ht .. " " .. height .. ", " .. t.wt .. " " .. weight .. " " .. entry
	end
	function PM.evolution()
		local ui, state = CE.evolution()
		if not ui or state == 22 or state == 23 or state == 24 then return nil end
		return {ui=ui,state=state}
	end
	-- Only post-print states commit a newly formatted String. Keep the module
	-- through animation/preparation frames without reading partial or stale text.
	PM.evolution_messages = {[3]=true,[5]=true,[12]=true,[15]=true,[17]=true,
		[19]=true,[20]=true,[21]=true,[26]=true,[28]=true,[30]=true,
		[33]=true,[34]=true,[35]=true,[36]=true,[37]=true,[38]=true,[44]=true}
	function PM.evolution_screen(s)
		if not PM.evolution_messages[s.state] then return "evolution" end
		local prompt = PM.message(u32(s.ui + 0x10),u8(s.ui + 0x65),320,s.ui)
		-- The stop-learning Yes branch formats its result before leaving state35.
		-- Refuse that in-progress replacement, including a hardware-frame sample
		-- partway through StringTemplate_Format. The committed question is 368[1197].
		if s.state == 35 then
			local move = BTLTEXT.moves[u16(s.ui + 0x6C)]
			local expected = move and PM.text_at(368,1197,{[0]=move})
			if not expected or prompt ~= expected then return "stop learning" end
		end
		local row, text
		if s.state == 21 or s.state == 35 then row,text = PM.menu(u32(s.ui + 0x40)) end
		-- Each Yes/No landing has its own row identity, including a return from
		-- Stop trying to the first question. The registrar queues only its landing.
		local page = (s.state >= 19 and s.state <= 21) and "delete move"
			or (s.state >= 33 and s.state <= 35) and "stop learning" or "evolution"
		return page,prompt,row,text
	end
	PM.register("caught Pokemon entry", PM.catch_dex, PM.catch_dex_screen)
	PM.register("caught Pokemon transfer", function()
		local ui, state = CE.catch_naming()
		if ui and (state == 6 or state == 7) then return {ui=ui} end
	end, function(s)
		return "transfer", PM.message(u32(s.ui + 0x180),u32(s.ui + 0x458),1024,s.ui)
	end)
	PM.register("Pokemon evolution", PM.evolution, PM.evolution_screen)
	PM.register("field party", PM.field_party, PM.field_party_screen, nil, nil, PM.forget_field_levelup)
	PM.register("field bag", PM.field_bag, PM.field_bag_screen)
	-- D on the summary: the Pokémon it is showing, from PokemonSummaryMonData at ui +0x250 (the
	-- same struct PM.summary_screen already reads: species +0x0C, OT id +0x14, moves +0x34). form is
	-- the u16 at +0x4E and the flags word at +0x50 holds isEgg in bit 28 and isShiny in bit 29
	-- (include/applications/pokemon_summary_screen/main.h:391-396). Confirmed on the retail cartridge:
	-- PlayMonCry 0x0208D618 tests `ldr [ui,#0x2A0] ; lsls #3 ; lsrs #31` (isEgg) and passes
	-- `ldrh [ui,#0x29E]` (form) to the cry; PokemonSummaryScreen_UpdateMiscMonDataSprites tests
	-- `lsls #2 ; lsrs #31` (isShiny) of the same word. An Egg says nothing: describing what will
	-- hatch is not what the screen shows.
	PM.register("Pokemon summary", PM.summary, PM.summary_screen).describe = function()
		local s = PM.summary()
		if not s or not inram(s.mon + 0x53) then return nil end
		local flags = u32(s.mon + 0x50)
		if flags & (1 << 28) ~= 0 then return nil end
		return u16(s.mon + 0x0C), u16(s.mon + 0x4E), flags & (1 << 29) ~= 0
	end
	-- D in the Pokédex: the species the list cursor or the open entry is on, through the same
	-- PM.dex_species the reader speaks. No form: which form the entry pages draw is not traced, so
	-- the general look is spoken (and every form, for species whose text is all per-form).
	PM.register("Pokedex", PM.dex, PM.dex_screen, function(row)
		return type(row) == "string" and row:sub(1,4) == "tab:"
	end).describe = function()
		local s = PM.dex()
		if not s then return nil end
		local main = PM.dex_pages(s)
		if not main or main[1] then return nil end      -- the search screen has no Pokémon in focus
		local species = PM.dex_species(s, main[0] ~= nil)
		if not species or species == 0 then return nil end
		return species
	end
	PM.register("Berry Tag", PM.berry, PM.berry_screen)
	PM.register("Journal", PM.journal_page, PM.journal_screen)

	-- ov16 02269dee consumes activeMenuData+0 (subscreen+1c) for the
	-- give-up move name. Cursor_YesNo 0226ca14 and MoveCursor 0226cb10
	-- consume MenuCursor {active,y,x,unused}: y=+6dd, x=+6de.
	function PM.battle_choices(sc, cfg)
		if u8(sc+SC.CUR) ~= 1 then return nil end
		local y,x = u8(sc+0x6DD),u8(sc+0x6DE)
		if cfg == 12 then return PM.battle_targets(sc,x,y) end
		if cfg>=7 and cfg<=10 then
			local row,ids
			if cfg<=8 then
				if x>2 or y>1 then return nil end
				row=({[0]={[0]=0,0,0},[1]={[0]=1,3,2}})[y][x]
				ids={931,932,933,u8(sc+0x68F)==1 and 928 or 927}
			else
				if x~=0 or y>1 then return nil end
				row,ids=y,{1223,u8(sc+0x68F)==1 and 928 or 927}
			end
			local text=PM.text_at(368,ids[row+1])
			return row,text and text .. ", " .. (row+1) .. " de " .. #ids
		end
		local rows = ({[13]={940,941},[14]={1181,1182},[15]={1186,1187},
			[16]={1217,1218},[17]={1215,1216}})[cfg]
		if not rows or x ~= 0 or y > 1 then return nil end
		local args
		if cfg == 15 then
			local move=BTLTEXT.moves[u16(sc+0x1C)]
			if not move then return nil end
			args={[0]=move}
		end
		local text=PM.text_at(368,rows[y+1],args)
		return y,text and text .. ", " .. (y+1) .. " de 2"
	end
	function PM.battle_targets(sc,x,y)
		local layout=u8(sc+0x68C)
		local flags=PM.target_flags[layout+1]
		if not flags then return nil end
		local grouped=layout==1 or layout==2 or layout==3 or layout==5 or layout==7
		if x>(grouped and 0 or 1) or y>(grouped and 1 or 2) then return nil end
		local cancel=y==(grouped and 1 or 2)
		local button=cancel and 4 or ({[0]={[0]=3,1},[1]={[0]=0,2}})[y][x]
		local bs,bytype=u32(sc),{}
		if not inram(bs+0x77) or u32(bs+0x44)~=4 then return nil end
		for id=0,3 do
			local bd=u32(bs+0x34+4*id)
			if not inram(bd+0x195) then return nil end
			local typ=u8(bd+0x195)
			if typ<2 or typ>5 or bytype[typ] then return nil end
			bytype[typ]=id
		end
		local out,count,before={},0,0
		for slot=0,3 do
			local id=bytype[slot+2]
			local p=sc+0x1C+id*8
			if flags[slot+1]==1 and u8(p+1)&4~=0 then
				count=count+1
				if slot<=button then before=before+1 end
				if not cancel and (grouped or slot==button) then
					local gender,partySlot=u8(p+1)&3,u8(p)
					if gender>2 or partySlot>5 then return nil end
					local battleType,partyid=u32(bs+0x2C),id
					if battleType&8==0 and not (battleType&0x10~=0 and slot&1~=0) and battleType&2~=0 then partyid=id&1 end
					local party=u32(bs+0x68+partyid*4)
					if not inram(party+7) or u32(party+4)>6 or partySlot>=u32(party+4) then return nil end
					local name=PM.boxname(party+8+236*partySlot)
					if not name then return nil end
					name=(slot&1==0) and ("Tu " .. name) or (name .. " rival")
					if gender<2 then name=name .. ", " .. CHARMAP[0x1BB + gender] end
					-- DrawTargetSelectMenu 0226a12c consumes this same 8-byte
					-- TargetMonData: signed current HP +4, maximum HP +6.
					local health=btl_health(u16(p+4),u16(p+6),slot&1)
					if not health then return PM.fail("battle target: invalid health") end
					name=name .. ", " .. health
					out[#out+1]=name
				end
			end
		end
		if cancel then
			local n=grouped and 2 or count+1
			return 4,PM.text_at(368,930) .. ", " .. n .. " de " .. n
		end
		if #out==0 then return button,nil end
		return grouped and 0 or button,table.concat(out,"; ") .. ", " .. (grouped and 1 or before) .. " de " .. (grouped and 2 or count+1)
	end
	local choice_owner,choice_cfg,choice_row
	MODULES[#MODULES+1] = {
		name="battle targets and choices",
		detect=function()
			local shown,cfg=subscreen_shown()
			if shown~=choice_owner or cfg~=choice_cfg then choice_owner,choice_cfg,choice_row=shown,cfg,nil end
			local sc,live=subscreen()
			return sc~=nil and ((live>=7 and live<=10) or (live>=12 and live<=17))
		end,
		update=function()
			local sc,cfg=subscreen()
			if not sc then return end
			local row,text=PM.battle_choices(sc,cfg)
			if row~=nil and text and row~=choice_row then
				say(text,choice_row~=nil); choice_row=row
				btl_take_after_msg()
			end
		end,
	}

	local said_owner, said_page, said_prompt, said_row, queued_prompt
	MODULES[#MODULES + 1] = {
		name = "battle party and bag",
		detect = function() return PM.battle_menu() ~= nil end,
		on_exit = function()
			PM.forget_message(said_owner)
			said_owner, said_page, said_prompt, said_row, queued_prompt = nil,nil,nil,nil,nil
		end,
		update = function()
			local s = PM.battle_menu()
			if not s then return end
			local page, prompt, row, text
			if s.party then page,prompt,row,text = PM.party_screen(s) else page,prompt,row,text = PM.bag_screen(s) end
			if not page then return end
			if s.ui ~= said_owner or page ~= said_page then
				said_owner, said_page, said_prompt, said_row, queued_prompt = s.ui, page, nil, nil, nil
			end
			local spoke_prompt = prompt and prompt ~= said_prompt
			if spoke_prompt then
				say(prompt)
				said_prompt, queued_prompt = prompt, true
			end
			if row ~= nil and (row ~= said_row or spoke_prompt) then
				local first = said_row == nil
				said_row = row -- empty cells still move the cursor, so returning to a move speaks again
				if text then say(text, not (spoke_prompt or first and (queued_prompt or prompt))); queued_prompt = nil end
			end
		end,
	}
end)()

