	--[[ SERVICE_DATA:END ]]

	-- Read the loaded cartridge through BizHawk's ROM domain. Prices are freed
	-- immediately by Item_LoadParam, so a retail price bake would misread hacks.
	-- DS header -> named FNT directory -> FAT file -> NARC member, cached once.
	-- All reads specify ROM explicitly; the active RAM domain is never changed.
	local item_archive, rom_size
	local function rom_read(offset, bytes)
		if not rom_size then
			if not memory or not memory.getmemorydomainsize or not memory.getmemorydomainlist then return PM.fail("shop ROM: memory API unavailable") end
			local ok,domains=pcall(memory.getmemorydomainlist)
			local found=false
			if ok and type(domains)=="table" then
				for _,name in pairs(domains) do if name=="ROM" then found=true; break end end
			end
			if not found then return PM.fail("shop ROM: no cartridge domain") end
			local ok, size = pcall(memory.getmemorydomainsize, "ROM")
			if not ok or not size or size < 0x200 then return PM.fail("shop ROM: no cartridge domain") end
			rom_size = size
		end
		if not offset or offset < 0 or offset + bytes > rom_size then return PM.fail("shop ROM: read bounds") end
		local reader = ({[1]=memory.read_u8, [2]=memory.read_u16_le, [4]=memory.read_u32_le})[bytes]
		if not reader then return PM.fail("shop ROM: read width") end
		local ok, value = pcall(reader, offset, "ROM")
		if not ok then return PM.fail("shop ROM: cartridge read failed") end
		return value
	end
	local function rom_file(path)
		local fnt, fntsize, fat, fatsize = rom_read(0x40,4),rom_read(0x44,4),rom_read(0x48,4),rom_read(0x4C,4)
		if not fnt or not fntsize or not fat or not fatsize or fntsize < 8 or fatsize < 8
			or fnt+fntsize > rom_size or fat+fatsize > rom_size then return PM.fail("shop ROM: filesystem header") end
		local dirs = rom_read(fnt+6,2)
		if not dirs or dirs < 1 or dirs > 4096 or dirs*8 > fntsize then return PM.fail("shop ROM: directory count") end
		local parts = {}; for p in path:gmatch("[^/]+") do parts[#parts+1]=p end
		local dir = 0
		for depth, part in ipairs(parts) do
			if dir < 0 or dir >= dirs then return PM.fail("shop ROM: directory id") end
			local offset, fileid = rom_read(fnt+dir*8,4),rom_read(fnt+dir*8+4,2)
			if not offset or not fileid or offset < dirs*8 or offset >= fntsize then return PM.fail("shop ROM: directory entries") end
			local found = false
			while offset < fntsize do
				local tag = rom_read(fnt+offset,1)
				if not tag then return nil end
				offset = offset+1
				if tag == 0 then break end
				local length, subdir = tag&127,tag&128~=0
				if length == 0 or offset+length+(subdir and 2 or 0)>fntsize then return PM.fail("shop ROM: filename bounds") end
				local name = {}
				for i=0,length-1 do
					local ch=rom_read(fnt+offset+i,1); if not ch then return nil end
					name[#name+1]=string.char(ch)
				end
				offset=offset+length
				if table.concat(name)==part then
					if depth<#parts and subdir then
						local id=rom_read(fnt+offset,2)
						if not id or id<0xF000 then return PM.fail("shop ROM: child directory") end
						dir,found=id-0xF000,true; break
					elseif depth==#parts and not subdir then
						if (fileid+1)*8>fatsize then return PM.fail("shop ROM: file id") end
						local first,last=rom_read(fat+fileid*8,4),rom_read(fat+fileid*8+4,4)
						if first and last and first<last and last<=rom_size then return first,last end
						return PM.fail("shop ROM: file range")
					end
				end
				if subdir then offset=offset+2 else fileid=fileid+1 end
			end
			if not found then return PM.fail("shop ROM: item archive missing") end
		end
	end
	local function load_archive(path)
		local first,last=rom_file(path)
		if not first then return nil end
		if rom_read(first,4)~=0x4352414E or rom_read(first+4,4)~=0x0100FFFE then return PM.fail("shop ROM: NARC header") end
		local size,header,blocks=rom_read(first+8,4),rom_read(first+12,2),rom_read(first+14,2)
		if not size or not header or size>last-first or header<16 or blocks~=3 then return PM.fail("shop ROM: NARC layout") end
		local offset, entries, count, data, data_end=first+header
		for _=1,blocks do
			if offset+8>first+size then return PM.fail("shop ROM: NARC block header") end
			local magic,n=rom_read(offset,4),rom_read(offset+4,4)
			if not n or n<8 or offset+n>first+size then return PM.fail("shop ROM: NARC block size") end
			if magic==0x46415442 then -- BTAF
				if entries then return PM.fail("shop ROM: duplicate member table") end
				count=rom_read(offset+8,2)
				if not count or count<1 or 12+count*8>n then return PM.fail("shop ROM: member count") end
				entries=offset+12
			elseif magic==0x46494D47 then -- GMIF
				if data then return PM.fail("shop ROM: duplicate data block") end
				data,data_end=offset+8,offset+n
			elseif magic~=0x464E5442 then return PM.fail("shop ROM: unknown NARC block") end
			offset=offset+n
		end
		if not entries or not data then return PM.fail("shop ROM: incomplete NARC") end
		return {entries=entries,count=count,data=data,last=data_end}
	end
	PM.rom_read = rom_read
	local archives = {}
	function PM.rom_member(path,member,size)
		if archives[path]==nil then archives[path]=load_archive(path) or false end
		local archive=archives[path]
		if not archive then return nil end
		if member<0 or member>=archive.count then return PM.fail("cartridge: member id") end
		local p=archive.entries+member*8
		local first,last=rom_read(p,4),rom_read(p+4,4)
		if not first or not last or last-first<size or first+archive.data<archive.data
			or last+archive.data>archive.last then return PM.fail("cartridge: member bounds") end
		return archive.data+first, last-first
	end
	function PM.item_price(id)
		if not id or id<1 or id>467 then return PM.fail("shop: item id") end
		if item_archive==nil then item_archive=load_archive("itemtool/itemdata/pl_item_data.narc") or false end
		if not item_archive then return nil end
		local member=u16(A.ItemArchiveIDs+id*8)
		if member>=item_archive.count then return PM.fail("shop ROM: item member id") end
		local p=item_archive.entries+member*8
		local first,last=rom_read(p,4),rom_read(p+4,4)
		-- The serialized member is 34 bytes; ALIGN_4 pads the C struct to 36.
		if not first or not last or last-first<34 or first+item_archive.data<item_archive.data
			or last+item_archive.data>item_archive.last then return PM.fail("shop ROM: item member bounds") end
		return rom_read(item_archive.data+first,2) -- Item_Get(PRICE), 0207d044
	end

	-- Only the top FieldTask executes (02050966). Its fieldSystem back-pointer
	-- and callback own this allocation; the script below it may still show old text.
	function PM.shop_owner()
		local fs=field_sys(); if not fs then return nil end
		local task=u32(fs+0x10)
		if not inram(task) or not inram(task+0x1F) then return nil end
		local fn=u32(task+4)
		if fn~=A.FieldTask_InitShop and fn~=A.FieldTask_ShopMisc then return nil end
		if u32(task+0x18)~=fs then return PM.fail("shop: field task owner") end
		local ui=u32(task+0xC)
		if not inram(ui) or not inram(ui+0x253) then return PM.fail("shop: task data") end
		return ui,fs,fn
	end
	shop_active=function() return PM.shop_owner()~=nil end
	function PM.shop()
		local ui,fs,fn=PM.shop_owner()
		if not ui or fn~=A.FieldTask_InitShop or field_map_live()~=fs then return nil end
		local state,kind=u8(ui+0x233),u8(ui+0x245)
		if state>20 or kind>3 then return PM.fail("shop: state or currency") end
		return {ui=ui,fs=fs,state=state,kind=kind}
	end
	function PM.shop_price(s,id)
		if s.kind==0 then return PM.item_price(id) end
		if s.kind==1 then
			if id<1 or id>138 then return PM.fail("shop: decoration id") end
			return u32(A.GoodMoneyPrices+id*28)
		end
		if s.kind==2 then
			if id<1 or id>80 then return PM.fail("shop: seal id") end
			return u16(A.SealData+id*10+4)
		end
		-- A bounded native data table, read only on row selection; never a RAM scan.
		for i=0,40 do
			local p=A.ShopBPPrices+i*4
			if u16(p)==id then return u16(p+2) end
		end
		return PM.fail("shop: item has no BP price")
	end
	function PM.shop_row(s,previous)
		local pos,id,name,count=PM.list(u32(s.ui+0x78),s.ui)
		if not pos then return nil end
		if count~=u8(s.ui+0x230)+1 then return PM.fail("shop: list count") end
		if pos==previous then return nil end
		if id==0xFFFFFFFE then return pos,PM.text_at(543,8)..", "..(pos+1).." de "..count end
		if not name then return PM.fail("shop: item label") end
		local price=PM.shop_price(s,id)
		if not price or price>999999 then return PM.fail("shop: item price") end
		local desc
		if s.kind==0 or s.kind==3 then
			desc=PM.text_at(391,id)
			if id>=328 and id<=420 then
				local machine=PM.text_at(392,id)
				if not machine then return nil end
				name=machine..", "..name
			end
		elseif s.kind==1 then desc=PM.text_at(626,138+id)
		else desc=PM.text_at(542,u8(A.SealData+id*10+6)) end
		if not desc then return PM.fail("shop: item description") end
		local amount=s.kind==3 and PM.text_at(543,32,{[0]=price}) or tostring(price)
		return pos,name..", "..amount..". "..desc.." "..(pos+1).." de "..count
	end
	function PM.shop_quantity(s)
		local q,limit,price=u16(s.ui+0x248),u16(s.ui+0x24A),u32(s.ui+0x24C)
		if q<1 or limit<1 or q>limit or limit>99 or price>999999 or q*price>999999 then return PM.fail("shop: purchase quantity") end
		local total=s.kind==3 and PM.text_at(543,34,{[0]=q*price}) or tostring(q*price)
		return q,q..", "..total
	end
	function PM.shop_money()
		local s=PM.shop()
		local info,save
		if s and s.state>=4 and s.state<=11 then
			save=u32(s.ui+0x220)
			if s.kind==3 then
				if save~=u32(A.sSaveDataPtr) then return PM.fail("shop money: save owner") end
				local page=save_page(23,nil,"shop BP")
				if not page or not inram(page+0x955) or u32(save+SD_PAGES+23*SD_PAGE+4)<0x956 then return PM.fail("shop BP: record") end
				local bp=u16(page+0x954)
				if bp>9999 then return PM.fail("shop BP: value") end
				return PM.text_at(543,38,{[0]=bp})
			end
			info=u32(s.ui+0x20C)
		else
			local bag=PM.field_bag()
			if not bag or bag.state<1 or u8(bag.ctx+0x65)~=2 then return nil end
			save=u32(bag.ctx)
			info=u32(bag.ui+0xCC) -- BagUI_PrintMoney 022402b4..ba -> TrainerInfo_Money
		end
		if save~=u32(A.sSaveDataPtr) then return PM.fail("shop money: save owner") end
		local page=save_page(1,nil,"shop money")
		if not page then return nil end
		if u32(save+SD_PAGES+SD_PAGE+4)<0x1C then return PM.fail("shop money: player page size") end
		if info and info~=page+4 then return PM.fail("shop money: trainer owner") end
		local value=u32(page+0x18) -- SaveData_GetTrainerInfo +4, TrainerInfo_Money +14
		if value>999999 then return PM.fail("shop money: value") end
		return tostring(value)
	end
	function PM.money_step(pressed)
		if pressed.B or pressed[pad.PAD.."LeftThumb"] then
			local value=PM.shop_money(); if value then say(value) end
		end
	end

	local owner,phase,row,prompt,queued,candidate,full,lastpage
	local function shop_reset()
		owner,phase,row,prompt,queued,candidate,full,lastpage=nil,nil,nil,nil,nil,nil,nil,nil
	end
	local SHOP_PHASE={[1]="context",[4]="list",[5]="quantity",[6]="quantity",[7]="confirm",[8]="confirm",
		[9]="result",[10]="result",[11]="premier",[13]="context",[20]="exit"}
	MODULES[#MODULES+1]={
		name="shop",detect=function() return PM.shop()~=nil end,on_exit=shop_reset,
		update=function()
			local s=PM.shop(); if not s then return end
			if owner~=s.ui then shop_reset(); owner=s.ui end
			local nextphase=SHOP_PHASE[s.state]
			if phase~=nextphase then phase,row,prompt,queued,candidate,full,lastpage=nextphase,nil,nil,nil,nil,nil,nil end
			if not phase then return end
			local spoke_prompt = false
			if s.state~=1 and s.state~=4 then
				local first,last=str_range(u32(s.ui+0x234),96)
				if first then
					local pages=pt_pages(first,last)
					local printer,cursor=printer_at(u8(s.ui+0x240),first,last)
					local parts={}; for i,p in ipairs(pages) do parts[i]=p.text end
					local text=table.concat(parts,"\1")
					local committed=printer~=nil or text==candidate
					candidate=text
					if not committed and #pages>0 then return end
					if committed then
						if full~=text then full,lastpage=text,nil end
						local n=cursor and page_at(pages,cursor) or lastpage or 1
						local p=pages[n]
						if p and (p.text~=prompt or n~=lastpage) then
							say(p.text); prompt,queued,lastpage=p.text,true,n; spoke_prompt=true
						end
					end
				end
			end
			local nextrow,text
			if s.state==1 or s.state==8 then nextrow,text=PM.menu(u32(s.ui+0x80))
			elseif s.state==4 then nextrow,text=PM.shop_row(s,row)
			elseif s.state==6 then nextrow,text=PM.shop_quantity(s) end
			if nextrow~=nil and text and (nextrow~=row or spoke_prompt) then
				local first=row==nil
				say(text,not(spoke_prompt or first and (queued or phase=="context")))
				row,queued=nextrow,nil
			end
		end,
	}

	function PM.options()
		local ui,_,app=PM.field_app(A.OptionsMenu_Main,74)
		if not ui then return nil end
		if not inram(ui+0x2BB) then return PM.fail("options: application data") end
		local state=u32(ui+4)
		if state>5 then return nil end
		if u32(ui+0x1C)~=u32(app+0x18) then return PM.fail("options: arguments owner") end
		return {ui=ui,state=state}
	end
	function PM.option_row(s)
		local row=(u32(s.ui+0x10)>>2)&7
		local def=PM.option_entries[row+1]
		if not def then return PM.fail("options: cursor") end
		local entry=s.ui+0x5C+row*0x54
		local count,selected=u16(entry),u16(entry+2)
		if count~=def[3] or (count>0 and selected>=count) then return PM.fail("options: choices") end
		local label,desc=PM.text_at(220,def[1]),PM.text_at(220,def[2])
		local value
		if count>0 then
			local first,last=str_range(u32(entry+4+selected*4),256)
			local pages=first and pt_pages(first,last)
			value=pages and pages[1] and pages[1].text
			if not value then return PM.fail("options: selected value") end
		end
		if not label or not desc then return nil end
		return row,value,label..(value and ", "..value or "")..". "..desc.." "..(row+1).." de 7"
	end
	local opt_owner,opt_phase,opt_row,opt_value,opt_queued
	MODULES[#MODULES+1]={
		name="options menu",detect=function() return PM.options()~=nil end,
		on_exit=function() opt_owner,opt_phase,opt_row,opt_value,opt_queued=nil,nil,nil,nil,nil end,
		update=function()
			local s=PM.options(); if not s then return end
			if opt_owner~=s.ui then opt_owner,opt_phase,opt_row,opt_value,opt_queued=s.ui,nil,nil,nil,nil end
			if s.state==2 then
				if opt_phase~="entries" then
					opt_phase,opt_row,opt_value="entries",nil,nil
					say(PM.text_at(220,0)); opt_queued=true
				end
				local selected,value,text=PM.option_row(s)
				if selected~=nil then
					if selected~=opt_row then say(text,not opt_queued); opt_queued=nil
					elseif value and value~=opt_value then say(value) end
					opt_row,opt_value=selected,value
				end
			elseif s.state==4 or s.state==5 then
				if opt_phase~="confirm" then
					opt_phase,opt_row="confirm",nil
					say(PM.text_at(220,49)); opt_queued=true
				end
				if s.state==5 then
					local selected,text=PM.menu(u32(s.ui+0x2A8))
					if selected~=nil and text and selected~=opt_row then
						say(text,not opt_queued); opt_row,opt_queued=selected,nil
					end
				end
			end
		end,
	}

	-- The card's strings are drawn and freed in the same call. Reconstruct them
	-- from the application's own TrainerCase, following the two draw consumers.
	-- Card title, colours, stars and the badge-case button are graphics only:
	-- trainer_case.narc, rendered by research/re/pt_card_art.py.
	local CARD_COLORS={"roja","azul cobalto","bronce","plata","oro","negra"}
	function PM.trainer_card()
		local ui,_,app=PM.field_app(A.TrainerCaseApp_Main,71)
		if not ui then return nil end
		if not inram(ui+0x331F) then return PM.fail("trainer card: application data") end
		local state=u32(app+0x14)
		if state>4 or state==2 then return nil end
		local card=u32(ui+0xB4)
		if not inram(card) or not inram(card+0x67) then return PM.fail("trainer card: arguments") end
		if card~=u32(app+0x18) then return PM.fail("trainer card: arguments owner") end
		local back,opened=u32(ui+0x30C0),u8(ui+0x3318)
		if back>1 or opened>1 or u8(card+3)>5 then return PM.fail("trainer card: page or rank") end
		return {ui=ui,card=card,state=state,back=back,opened=opened,flags=u8(card+4)}
	end
	function PM.card_date(year,month,day)
		if year>99 or month<1 or month>12 or day<1 or day>31 then return PM.fail("trainer card: date") end
		return PM.text_at(616,17,{[2]=string.format("%02d",year),[3]=PM.text_at(414,month-1),[4]=string.format("%02d",day)})
	end
	function PM.card_time(hours,minutes)
		if hours>999 or minutes>59 then return PM.fail("trainer card: play time") end
		return PM.text_at(616,15,{[0]=hours,[1]=string.format("%02d",minutes)})
	end
	function PM.card_front(s)
		local c=s.card
		local name=chars_name(c+8,8)
		if not name then return PM.fail("trainer card: name") end
		local money,seen,score=u32(c+0x1C),u32(c+0x20),u32(c+0x24)
		if money>999999 or seen>493 or score>999999999 then return PM.fail("trainer card: front values") end
		local hours,minutes=u16(c+0x2A),u8(c+0x2E)
		if s.flags&2~=0 then
			local time=u32(c+0x18)
			if not inram(time) or not inram(time+3) then return PM.fail("trainer card: live play time") end
			hours,minutes=u16(time),u8(time+2)
		end
		local time=PM.card_time(hours,minutes)
		local date=PM.card_date(u8(c+0x2F),u8(c+0x30),u8(c+0x31))
		if not time or not date then return nil end
		local rank=s.flags&8~=0 and u8(c+3) or 0
		local rows={"Ficha de entrenador, nivel "..rank..", "..CARD_COLORS[rank+1],
			PM.text_at(616,0).." "..string.format("%05d",u16(c+0x28)),
			PM.text_at(616,1).." "..name,
			PM.text_at(616,2).." "..PM.text_at(616,14,{[5]=money})}
		if s.flags&8~=0 then rows[#rows+1]=PM.text_at(616,3).." "..seen end
		rows[#rows+1]=PM.text_at(616,4).." "..score
		rows[#rows+1]=PM.text_at(616,5).." "..time
		rows[#rows+1]=PM.text_at(616,6).." "..date
		return table.concat(rows,". ")
	end
	function PM.card_back(s)
		local c=s.card
		local date,time
		if u8(c+0x33)==0 then
			date=PM.text_at(616,20)
			time=PM.text_at(616,15,{[0]=PM.text_at(616,12),[1]=PM.text_at(616,12)})
		else
			date=PM.card_date(u8(c+0x32),u8(c+0x33),u8(c+0x34))
			time=PM.card_time(u16(c+0x2C),u8(c+0x35))
		end
		if not date or not time then return nil end
		local linked,wins,losses,trades=u32(c+0x38),u32(c+0x3C),u32(c+0x40),u32(c+0x44)
		if linked>999999 or wins>9999 or losses>9999 or trades>999999 then return PM.fail("trainer card: record values") end
		return {PM.text_at(616,7).." "..date..", "..time,
			PM.text_at(616,8).." "..linked,
			PM.text_at(616,9).." "..PM.text_at(616,18).." "..wins..", "..PM.text_at(616,19).." "..losses,
			PM.text_at(616,10).." "..trades}
	end
	function PM.card_badges(s)
		local rows={{id=0,text=s.opened==0 and "Open badge case" or "Close badge case"}}
		if s.opened==1 then
			for badge=0,7 do
				if u32(s.card+0x48+badge*4)&1~=0 then
					rows[#rows+1]={id=badge+1,text=PM.badge_names[badge+1]}
				end
			end
		end
		return rows
	end
	function PM.card_tap(s,id)
		if s.state~=1 or touch.busy() then return nil end
		if id<0 or id>8 then return PM.fail("trainer card: touch selection") end
		if id>0 and (s.opened~=1 or s.flags&1==0 or u32(s.card+0x44+id*4)&1==0) then return nil end
		-- GetPlayerInput -> sTouchRectangleSets[interactable][open].
		local rects=u32(A.TrainerCaseTouchRects+(s.flags&1)*8+s.opened*4)
		if not inram(rects) or not inram(rects+id*4+3) then return PM.fail("trainer card: touch rectangles") end
		local r=rects+id*4
		local top,bottom,left,right=u8(r),u8(r+1),u8(r+2),u8(r+3)
		if top>=bottom or bottom>=192 or left>=right then return PM.fail("trainer card: touch bounds") end
		return touch.tap((left+right)//2,(top+bottom)//2)
	end
	pad.register_rt(function() return PM.trainer_card()~=nil end,true)
	local card_owner,card_page,case_open,case_row,case_layer
	MODULES[#MODULES+1]={
		name="trainer card",detect=function() return PM.trainer_card()~=nil end,
		-- D on the card: its owner. TrainerCase +4 bit 2 is the owner's gender, written by
		-- TrainerCase_SetTrainerInfo (0x02072044: `movs r2,#4 ; bics ; lsls #0x1f ; lsrs #0x1d`);
		-- +0 gameVersion (10/11 Diamond/Pearl, whose outfit the card draws); +5 trainerAppearance,
		-- 0xFF for the owner's own sprite. A Union Room card with another appearance says nothing.
		describe_trainer=function()
			local s=PM.trainer_card()
			if not s or u8(s.card+5)~=0xFF then return nil end
			local ver=u8(s.card)
			return (s.flags>>2)&1==1 and "dawn" or "lucas",(ver==10 or ver==11) and {"dp"} or {"platinum","dp"}
		end,
		on_exit=function()
			card_owner,card_page,case_open,case_row,case_layer=nil,nil,nil,nil,nil
			if touch.busy() then touch.cancel() end
		end,
		update=function(pressed)
			local s=PM.trainer_card(); if not s then return end
			if card_owner~=s.ui then card_owner,card_page,case_open,case_row,case_layer=s.ui,nil,nil,1,nil end
			if s.state~=1 then return end
			local queued=false
			if card_page~=s.back then
				local rows=s.back==0 and {PM.card_front(s)} or PM.card_back(s)
				if rows and rows[1] then
					for i,text in ipairs(rows) do say(text,i==1) end
					card_page,queued=s.back,true
				end
			end
			local rows=PM.card_badges(s)
			if case_open~=s.opened then
				if s.opened==1 then
					local names={}; for i=2,#rows do names[#names+1]=rows[i].text end
					say("Estuche de medallas abierto"..(#names>0 and ". "..table.concat(names,", ") or ""),not queued)
					queued=true
				elseif case_open~=nil then say("Estuche de medallas cerrado",not queued); queued=true end
				case_open,case_row,case_layer=s.opened,1,nil
			end
			local rt=keys.held()[pad.PAD.."RightTrigger"] and true or false
			local moved=false
			if pressed.J then case_row=(case_row-2)%#rows+1; moved=true
			elseif pressed.L then case_row=case_row%#rows+1; moved=true end
			if moved or (rt and not case_layer) then
				say(rows[case_row].text..", "..case_row.." de "..#rows,moved or not (queued or rt and not case_layer))
			end
			case_layer=rt
			if pressed.H then PM.card_tap(s,rows[case_row].id) end
		end,
	}
end)()

