	--[[ PC_DATA:END ]]
	-- SysTaskManager_ExecuteTasks 0201CDD4 follows +0C, then each node's +8,
	-- invoking callback +14 with parameter +10. Validate membership before use.
	function PM.pc_task_queue()
		local manager=u32(A.gSystem+0x18)
		if not inram(manager+0x33) then return PM.fail("PC: task manager") end
		local maximum,count,array=u16(manager),u16(manager+2),u32(manager+0x24)
		if maximum<1 or maximum>1024 or count>maximum or not inram(array)
			or not inram(array+maximum*0x1C-1) then return PM.fail("PC: task allocation") end
		local sentinel=manager+4
		local function allocated(task)
			return task and task>=array and task<array+maximum*0x1C and (task-array)%0x1C==0
		end
		local function linked(task)
			if not allocated(task) or u32(task)~=manager then return false end
			local prev,nextp=u32(task+4),u32(task+8)
			return (prev==sentinel or allocated(prev)) and (nextp==sentinel or allocated(nextp))
				and u32(prev+8)==task and u32(nextp+4)==task
		end
		return {manager=manager,sentinel=sentinel,count=count,linked=linked}
	end
	function PM.pc_field_menu()
		if not field_map_live() then return nil end
		local sm=script_manager()
		if not sm then return nil end
		local waiting=false
		for _,offset in ipairs({0x38,0x3C}) do
			local ctx=u32(sm+offset)
			if inram(ctx+0x83) and u8(ctx+1)==2 and u32(ctx+4)==A.ScriptWaitMenu then waiting=true end
		end
		if not waiting then return nil end
		local ui=u32(sm+0x10)
		if not inram(ui+0x2DF) then return PM.fail("field menu: manager") end
		local queue=PM.pc_task_queue()
		local task=u32(ui+4)
		if not queue or not queue.linked(task) or u32(task+0x10)~=ui or u32(task+0x18)~=0 then return nil end
		local callback=u32(task+0x14)
		if callback~=A.FieldMenuTask and callback~=A.FieldListMenuTask then return nil end
		if u32(ui)~=field_sys() then return PM.fail("field menu: FieldSystem owner") end
		local result=u32(ui+0xA0)
		if not inram(result+1) or u16(result)~=0xEEEE then return nil end
		if u8(ui+0x94)~=0 then return nil end
		return {ui=ui,list=callback==A.FieldListMenuTask}
	end
	function PM.pc_field_menu_screen(s)
		local ready,serial=field_dialogue_step()
		if ready==false then return nil end
		if not s.list then
			local row,text=PM.menu(u32(s.ui+0xB8))
			return "menu:"..serial,nil,row,text
		end
		local row,_,name,count=PM.list(u32(s.ui+0x1BC),s.ui)
		if not name or count~=u8(s.ui+0x9B) or count>28 then return nil end
		local out={name}
		if s.list then
			local alt=u16(s.ui+0x2A4+row*2)
			if alt~=255 then
				local loader=u32(s.ui+0x8C)
				-- These transient description Strings are freed inside the print call.
				-- Global PC menus use bank 361; other menus retain their live labels.
				if inram(loader+7) and u16(loader+4)==26 and u16(loader+6)==361 then
					local description=PM.text_at(361,alt)
					if description then out[#out+1]=description end
				end
			end
		end
		out[#out+1]=(row+1).." de "..count
		return "list:"..serial,nil,row,table.concat(out,". ")
	end
	PM.register("PC field menus",PM.pc_field_menu,PM.pc_field_menu_screen,nil,true)
	local mailbox_task,mailbox_env,mailbox_result,mailbox_result_owner
	function PM.pc_mailbox()
		local fs=field_sys(); if not fs then return nil end
		local task=u32(fs+0x10)
		if not inram(task+0x1F) or u32(task+4)~=A.MailboxFieldTask then
			mailbox_task,mailbox_env=nil,nil; return nil
		end
		if u32(task+0x18)~=fs then return PM.fail("mailbox: field task owner") end
		local env=u32(task+0xC)
		if not inram(env+7) or u32(env+4)~=1 or u32(env)~=0 then return nil end
		local queue=PM.pc_task_queue(); if not queue then return nil end
		local function owned(p)
			if not queue.linked(p) or u32(p+0x18)~=0 then return nil end
			local callback=u32(p+0x14)
			local known=false
			for _,fn in pairs(A.MailboxTask) do if fn==callback then known=true; break end end
			if not known then return nil end
			local ui=u32(p+0x10)
			if not inram(ui+0x1B7) or u32(ui)~=43 or u32(ui+4)~=env or u32(ui+8)~=p
				or u32(ui+0x16C)~=fs then return nil end
			return {ui=ui,fs=fs,callback=callback,state=u16(ui+0x10)}
		end
		if mailbox_env~=env then mailbox_task,mailbox_env=nil,env end
		local s=mailbox_task and owned(mailbox_task)
		if not s then
			-- Acquisition follows the native task list. Subsequent frames use its owner.
			local p=u32(queue.sentinel+8)
			for _=1,queue.count do
				if p==queue.sentinel or not queue.linked(p) then break end
				s=owned(p)
				if s then mailbox_task=p; break end
				p=u32(p+8)
			end
		end
		return s
	end
	function PM.pc_mailbox_screen(s)
		if field_map_live()~=s.fs then return nil end
		local ui,fn,state=s.ui,s.callback,s.state
		local cb=A.MailboxTask
		local msg
		if fn~=cb.Result then mailbox_result,mailbox_result_owner=nil,nil end
		if fn==cb.List then
			local row,_,label,count=PM.list(u32(ui+0x160),ui)
			if not label or count>21 then return nil end
			return "list",PM.message(u32(ui+0x11C),nil,128),row,label..", "..(row+1).." de "..count
		elseif fn==cb.Actions or (fn==cb.ActionInit and state==1) then
			local row,_,label,count=PM.list(u32(ui+0x160),ui)
			if not label or count~=4 then return nil end
			return "actions",PM.message(u32(ui+0x114),u8(ui+0x138),128),row,label..", "..(row+1).." de "..count
		elseif fn==cb.PutAway then
			if state==1 or state==2 then msg=1 elseif state==4 or state==5 then msg=2 else return nil end
		elseif fn==cb.GiveCancelled and (state==1 or state==2) then msg=5
		elseif fn==cb.Result and (state==1 or state==2) then
			-- The result is not retained as an ID. Its live printer references one of
			-- two owned Strings; remember that choice after the printer is destroyed.
			if mailbox_result_owner~=ui then mailbox_result=nil; mailbox_result_owner=ui end
			for id=3,4 do
				local first,last=str_range(u32(ui+0x120+id*4),128)
				if first and printer_at(u8(ui+0x138),first,last) then mailbox_result=id end
			end
			msg=mailbox_result
			if not msg then return PM.fail("mailbox: result printer not observed") end
		else return nil end
		local prompt=PM.message(u32(ui+0x120+msg*4),u8(ui+0x138),128)
		if fn==cb.PutAway and (state==2 or state==5) then
			local row,text=PM.menu(u32(ui+0x168))
			return "question:"..msg,prompt,row,text
		end
		return "message:"..msg,prompt
	end
	PM.register("PC mailbox",PM.pc_mailbox,PM.pc_mailbox_screen)
	pc_field_active=function() return PM.pc_field_menu()~=nil or PM.pc_mailbox()~=nil end
	function PM.mail_child(main,overlay,state)
		local parent,parentstate=PM.field_app(A.MailApp_Main,0xFFFFFFFF)
		if not parent or parentstate~=state or not inram(parent+0x1B) then return nil end
		local child=u32(parent+0xC)
		local ui=app_at(child,main,overlay)
		return ui,child,parent
	end
	function PM.ec_word(word)
		if word==0xFFFF then return "" end
		word=word&0xFFF
		for _,bank in ipairs(PM.ec_word_banks) do
			if word<bank[2] then return PM.text_at(bank[1],word) end
			word=word-bank[2]
		end
		return PM.fail("mail: word ID")
	end
	function PM.ec_sentence(p,blanks)
		if not inram(p+7) then return nil end
		local kind,id=u16(p),u16(p+2)
		if kind==0xFFFF then return "Vacío" end
		local bank=PM.ec_sentence_banks[kind+1]
		if not bank or not PM.text[bank][id] then return PM.fail("mail: sentence ID") end
		local words={[0]="",[1]=""}
		for i=0,1 do
			local word=u16(p+4+i*2)
			if word==0xFFFF then
				if blanks then words[i]="Vacío" else break end
			else
				words[i]=PM.ec_word(word)
				if not words[i] then return nil end
			end
		end
		return PM.text_at(bank,id,words)
	end
	function PM.mail_viewer()
		local ui,app,parent=PM.mail_child(A.MailViewer_Main,75,1)
		if not ui or not inram(ui+0xBB) or u32(ui+4)~=3 then return nil end
		local args=u32(ui+0x1C)
		if not inram(args+0x33) or args~=u32(app+0x18) or args~=u32(parent+0x10) then
			return PM.fail("mail viewer: arguments owner")
		end
		local mode=u8(ui+0xC)
		if mode>3 then return PM.fail("mail viewer: mode") end
		return {ui=ui,args=args,mode=mode,state=u16(ui+8)}
	end
	function PM.mail_viewer_screen(s)
		local t=PM.mail_text
		if s.mode==0 then
			local out={}
			for i=0,2 do
				if u16(s.args+0x1A+i*8)~=0xFFFF then
					local sentence=PM.ec_sentence(s.args+0x1A+i*8)
					if not sentence then return nil end
					out[#out+1]=sentence
				end
			end
			local sender=PM.message(u32(s.args+0x10),nil,8)
			if not sender then return PM.fail("mail viewer: sender") end
			out[#out+1]=sender
			return "read",table.concat(out,". ")
		elseif s.mode==1 then
			local row,col=u8(s.ui+0x11),u8(s.ui+0x12)
			if row>3 or col>1 then return PM.fail("mail viewer: selection") end
			if row<3 then
				local text=PM.ec_sentence(s.args+0x1A+row*8)
				return "write",nil,row,text and text..", "..(row+1).." de 3"
			end
			return "write",nil,3+col,(col==0 and t.Confirm or t.Cancel)..", "..(col+1).." de 2"
		elseif s.mode==2 and s.state==1 then return "empty",t.EnterPhraseOrWord
		elseif s.mode==3 and (s.state==1 or s.state==2) then
			local row,text
			if s.state==2 then row,text=PM.menu(u32(s.ui+0xA4)) end
			return "cancel",t.StopGivingMailPrompt,row,text
		end
	end
	PM.register("PC mail",PM.mail_viewer,PM.mail_viewer_screen)
	function PM.mail_editor()
		local ui,app,parent=PM.mail_child(A.EasyChat_Main,20,4)
		if not ui or not inram(ui+0x67) or u32(ui+4)~=2 then return nil end
		local args,gfx,words=u32(ui),u32(ui+0x14),u32(ui+0x18)
		if args~=u32(app+0x18) or args~=u32(parent+8) then return PM.fail("mail editor: arguments owner") end
		if not inram(gfx+0x1F) or u32(gfx+0x18)~=ui or u32(gfx+0x1C)~=words then
			return PM.fail("mail editor: graphics owner")
		end
		if not inram(words+0x18AF) or u32(words)~=args then return PM.fail("mail editor: word list owner") end
		local mode=u8(ui+0x65)
		if mode>1 then return PM.fail("mail editor: category mode") end
		return {ui=ui,gfx=gfx,words=words,mode=mode,callback=u32(ui+0x20),state=u32(ui+0x1C),
			task=u32(ui+0x2C),taskstate=u32(ui+0x28)}
	end
	function PM.ec_group(s,group)
		if group>=(s.mode==0 and 12 or 27) then return nil end
		local base=s.mode==0 and 8 or 0xC18
		local count=u32(s.words+base+group*4)
		local start=u32(s.words+(s.mode==0 and 0x38 or 0xC84)+group*4)
		if count>1496 or start+count>1496 then return PM.fail("mail editor: word range") end
		return count,start,s.words+(s.mode==0 and 0x68 or 0xCF0)
	end
	function PM.mail_editor_screen(s)
		for i=0,3 do if u32(s.gfx+8+i*4)~=0 then return nil end end
		local fn=A.EasyChatAction
		if s.task~=0 then
			local prompt
			if s.task==fn.Confirm and s.taskstate==2 then return "missing",PM.text_at(437,7) end
			if s.task==fn.Confirm and s.taskstate==1 then prompt=PM.text_at(437,6)
			elseif s.task==fn.Cancel and s.taskstate==1 then prompt=PM.text_at(437,8)
			else return nil end
			local row=u8(s.ui+0x66)
			if row>1 then return PM.fail("mail editor: yes/no cursor") end
			return s.task,prompt,row,PM.text_at(437,9+row)..", "..(row+1).." de 2"
		end
		local heading=PM.text_at(437,11+s.mode)
		-- ⛔ The sentence screen's stored main function is EasyChat_Main_INITIAL (the constructor's
		-- `str r0,[r4,#0x20]` 0x021D0F3C, and EasyChat_SetMainFunc on every return), which
		-- dispatches each frame through its type table 0x021D5148 to EasyChat_Main_Sentence
		-- (type 2, entry 0x021D1261). That table is the only place the Sentence address exists in
		-- overlay 20, so +0x20 never holds it. Type 2 is already required by PM.mail_editor.
		if s.callback==fn.Initial and s.state<=1 then
			local sentence=PM.ec_sentence(s.ui+8,true)
			local slot,count=u16(s.ui+0x4E),u8(s.ui+0x64)
			if not sentence or count>2 or (count>0 and slot>=count) then return nil end
			local word=count>0 and PM.ec_word(u16(s.ui+0xC+slot*2)) or nil
			if count>0 and word==nil then return nil end
			local key=table.concat({u32(s.ui+8),u32(s.ui+0xC),slot},":")
			local text=sentence
			if count>0 then text=text..". "..(word~="" and word or "Vacío")..", "..(slot+1).." de "..count end
			return "sentence",heading,key,text
		elseif s.callback==fn.Buttons and s.state==0 then
			local row=u16(s.ui+0x4C)
			if row>1 then return PM.fail("mail editor: button cursor") end
			return "buttons",heading,row,PM.text_at(438,row)..", "..(row+1).." de 2"
		elseif s.callback==fn.Category and s.state==0 then
			local group=u16(s.ui+0x50)
			local total=s.mode==0 and 13 or 28
			if group==0xFE then return "category:"..s.mode,heading,group,PM.text_at(436,13)..", "..total.." de "..total end
			local count=PM.ec_group(s,group); if not count then return nil end
			local label=s.mode==0 and PM.text_at(436,count==0 and 12 or group)
				or CHARMAP[u16(A.EasyChatABC+group*10)]
			if not label then return PM.fail("mail editor: category label") end
			return "category:"..s.mode,heading,group,label..(count==0 and ", Vacío" or "")..", "..(group+1).." de "..total
		elseif s.callback==fn.Word and s.state==0 then
			local group=u16(s.ui+0x50)
			local count,start,base=PM.ec_group(s,group); if not count then return nil end
			local scroll,col,row=u16(s.ui+0x54),u8(s.ui+0x5A),u8(s.ui+0x5B)
			local index=(scroll+row)*2+col
			if count~=u16(s.ui+0x58) or col>1 or row>4 or index>=count then return PM.fail("mail editor: word cursor") end
			local word=PM.ec_word(u16(base+(start+index)*2))
			return "words:"..s.mode..":"..group,heading,index,word and word..", "..(index+1).." de "..count
		end
	end
	PM.register("PC mail editor",PM.mail_editor,PM.mail_editor_screen)
	local species_cache = {}
	function PM.pc_species(species)
		if species<1 or species>507 then return nil end
		if species_cache[species]==nil then
			local p=PM.rom_member("poketool/personal/pl_personal.narc",species,44)
			if not p then return nil end
			local data={type1=PM.rom_read(p+6,1),type2=PM.rom_read(p+7,1),
				gender=PM.rom_read(p+0x10,1),growth=PM.rom_read(p+0x13,1)}
			if not data.gender or not data.growth or data.growth>7
				or not BTLTEXT.types[data.type1] or not BTLTEXT.types[data.type2] then return PM.fail("PC: species data") end
			species_cache[species]=data
		end
		return species_cache[species]
	end
	function PM.pc_gender(species,personality)
		local data=PM.pc_species(species)
		if not data then return nil end
		local ratio=data.gender
		if ratio==0 then return 0 elseif ratio==254 then return 1 elseif ratio==255 then return 2 end
		return ratio>(personality&255) and 1 or 0
	end
	local growth_tables = {}
	function PM.pc_level(species,experience)
		local data=PM.pc_species(species)
		if not data then return nil end
		local growth=growth_tables[data.growth]
		if not growth then
			local p=PM.rom_member("poketool/personal/pl_growtbl.narc",data.growth,404)
			if not p then return nil end
			growth={}
			for level=1,100 do
				local value=PM.rom_read(p+4*level,4)
				if not value or (level>1 and value<growth[level-1]) then return PM.fail("PC: experience table") end
				growth[level]=value
			end
			growth_tables[data.growth]=growth
		end
		local low,high=1,100
		while low<high do
			local mid=(low+high+1)//2
			if growth[mid]<=experience then low=mid else high=mid-1 end
		end
		return low
	end
	function PM.pc_hall()
		local ui,state,app=PM.field_app(A.PCHallOfFameManager_Main,87)
		if not ui or state~=0 then return nil end
		if not inram(ui+0xDB) then return PM.fail("Hall of Fame: manager") end
		if u32(ui+0xD8)~=0 then return nil end -- native transition still drawing
		local gfx=u32(ui+0xC8)
		if not inram(gfx+0x19B) or u32(gfx)~=ui or u32(gfx+4)~=ui then return PM.fail("Hall of Fame: display owner") end
		local count,index,mode=u32(ui+0x14),u32(ui+0x18),u32(ui+0x1C)
		local stored,entry=u32(ui+0xD0),u32(ui+0xD4)
		if count<1 or count>6 or index>=count or mode>1 or stored<1 or stored>30 or entry>=stored then return PM.fail("Hall of Fame: selection") end
		return {ui=ui,app=app,count=count,index=index,mode=mode}
	end
	function PM.pc_hall_screen(s)
		local ui=s.ui
		local number,year,month,day=u32(ui),u32(ui+4),u32(ui+8),u32(ui+12)
		if number<1 or year>99 or month<1 or month>12 or day<1 or day>31 then return PM.fail("Hall of Fame: entry date") end
		local header=PM.text_at(352,0,{[0]=number,[1]=year+2000,[2]=PM.text_at(414,month-1),[3]=day})
		local p=ui+0x20+s.index*0x1C
		local name=str_name(u32(p),12)
		if not name then return nil end
		local out={name}
		if s.mode==0 then
			local species,level=u16(p+0x10),u8(p+0x12)
			local speciesname,ot=PM.text_at(412,species),str_name(u32(p+4),8)
			local gender=PM.pc_gender(species,u32(p+8))
			if not speciesname or not ot or gender==nil or level<1 or level>100 then return PM.fail("Hall of Fame: Pokemon") end
			if name~=speciesname then out[#out+1]=speciesname end
			if gender<2 then out[#out+1]=PM.text_at(352,3+gender) end
			out[#out+1]=PM.text_at(352,1,{[0]=level})
			out[#out+1]=PM.text_at(352,2)..ot
		else
			for i=0,3 do
				local move=u16(p+0x14+i*2)
				if move==0 then break end
				if not BTLTEXT.moves[move] then return PM.fail("Hall of Fame: move") end
				out[#out+1]=BTLTEXT.moves[move]
			end
		end
		out[#out+1]=(s.index+1).." de "..s.count
		return number,header,s.index..":"..s.mode,table.concat(out,", ")
	end
	PM.register("PC Hall of Fame",PM.pc_hall,PM.pc_hall_screen)
	local fn = A.PCAction
	local menus = {
		[fn.CloseBox]={[2]=true}, [fn.ContinueBoxOperations]={[5]=true},
		[fn.MonCursorMenu]={[1]=true,[2]=true}, [fn.MonItemMenu]={[1]=true,[2]=true},
		[fn.BoxHeaderMenu]={[1]=true,[2]=true},
		[fn.WallpaperMenu]={[2]=true,[3]=true,[4]=true,[5]=true}, [fn.Mark]={[1]=true},
		[fn.ReleaseMon]={[1]=true}, [fn.MonItemHeld]={[1]=true}, [fn.PutAwayItem]={[1]=true},
	}
	function PM.pc_context()
		local ui, app = pc_box_app()
		if not ui then return nil end
		local action, state = u32(ui+0x1AC), u32(ui+0x1B4)
		-- These actions free BoxGraphics without nulling +114 before their child runs.
		if state==2 and (action==fn.RenameBox or action==fn.OpenSummary or action==fn.GiveItemFromBag) then return nil end
		local gfx, boxes, party = u32(ui+0x114), u32(ui), u32(ui+4)
		if not inram(gfx+0xB3B3) or u32(gfx+0x160)~=ui or u32(gfx+0xB3B0)~=ui then return PM.fail("PC: graphics owner") end
		if not inram(boxes+0x121B3) or boxes~=u32(ui+0x120) or party~=u32(ui+0x124)
			or not inram(party+7) or u32(party)~=6 or u32(party+4)>6 then return PM.fail("PC: storage owner") end
		local mode, box = u8(ui+0x48), u8(ui+0x40)
		if mode>4 or box>=18 then return PM.fail("PC: mode or box") end
		local msg=gfx+0x65F4
		if u32(msg+8)~=ui or u32(msg+0xC)~=gfx then return PM.fail("PC: message owner") end
		return {ui=ui,app=app,gfx=gfx,boxes=boxes,party=party,mode=mode,box=box,
			action=action,state=state,handler=u32(ui+0x1A8),inputstate=u32(ui+0x1B0),msg=msg}
	end
	function PM.pc_idle(s)
		for i=0,3 do if u32(s.gfx+8+i*4)~=0 then return false end end
		return true
	end
	function PM.pc_box_name(s,box)
		if box<0 or box>=18 then return nil end
		-- PCBoxes_BufferBoxName 02079B08: inline u16 names at +11EE4, stride28.
		local p=s.boxes+0x11EE4+box*0x28
		for i=0,19 do
			if u16(p+i*2)==0xFFFF then
				local pages=pt_pages(p,p+i*2)
				return pages[1] and pages[1].text
			end
		end
		return nil
	end
	function PM.pc_box_count(s,box)
		local count=0
		for i=0,29 do
			local data=PM.boxdata(s.boxes+4+box*0xFF0+i*0x88)
			if not data then return nil end
			if data.word(1,0)~=0 then count=count+1 end
		end
		return count
	end
	-- Shapes are graphics, not messages: graphic/box tiles 132..137 and 152..157.
	local marks={"Círculo","Triángulo","Cuadrado","Corazón","Estrella","Rombo"}
	function PM.pc_preview(s)
		local p=s.ui+0x4C
		local egg,level,gender=u8(p+15),u8(p+10),u8(p+14)
		local species=PM.message(u32(p+0x18),nil,12)
		if egg>1 or not species then return nil end
		if egg==1 then return species end
		local name=str_name(u32(p+0x14),12)
		if not name or level<1 or level>100 then return PM.fail("PC: preview identity") end
		local out={name}
		if gender==0 then out[#out+1]=PM.text_at(19,21)
		elseif gender==1 then out[#out+1]=PM.text_at(19,22)
		elseif gender~=2 and gender~=255 then return nil end
		out[#out+1]=PM.text_at(19,36).." "..level
		if name~=species then out[#out+1]=species end
		local dex=u16(p+8)
		if dex>493 then return PM.fail("PC: preview dex number") end
		if dex>0 then out[#out+1]=PM.text_at(455,8).." "..dex end
		local type1,type2=BTLTEXT.types[u8(p+12)],BTLTEXT.types[u8(p+13)]
		local item,nature,ability=PM.message(u32(p+0x1C),nil,18),PM.message(u32(p+0x20),nil,12),PM.message(u32(p+0x24),nil,16)
		if not type1 or not type2 or not item or not nature or not ability then return PM.fail("PC: preview details") end
		out[#out+1]=type1
		if type2~=type1 then out[#out+1]=type2 end
		out[#out+1]=item; out[#out+1]=nature; out[#out+1]=ability
		local bits=u8(p+11)
		if bits>63 then return PM.fail("PC: preview markings") end
		for i=1,6 do if bits&(1<<(i-1))~=0 then out[#out+1]=marks[i] end end
		return table.concat(out,", ")
	end
	function PM.pc_menu(s)
		local p=s.ui+0x74
		local row,count=u8(p+0x20),u8(p+0x21)
		if count<1 or count>8 or row>=count then return nil end
		local id=u32(p+4*row)
		local label
		if id>=56 and id<=61 then
			label=marks[id-55]..", "..(u8(p+0x22)&(1<<(id-56))~=0 and "marked" or "unmarked")
		else label=PM.text_at(18,24+id) end
		local key=id>=56 and id<=61 and (row..":"..u8(p+0x22)) or row
		return key,label and (label..", "..(row+1).." de "..count)
	end
	function PM.pc_slot(s)
		local ui=s.ui
		local loc=u8(ui+0xC)
		if loc==2 then return "header",PM.pc_box_name(s,s.box) end
		if loc==3 then return "party","PARTY POKéMON" end -- graphic/box cell member 10
		if loc==4 then return "close","CLOSE" end
		local pos,mon,where
		if loc==0 then
			local col,row=u8(ui+0xD),u8(ui+0xE)
			pos=u8(ui+0xF)
			if col>5 or row>4 or pos~=row*6+col then return nil end
			mon=s.boxes+4+s.box*0xFF0+pos*0x88
			where="row "..(row+1)..", column "..(col+1)
		elseif loc==1 then
			pos=u8(ui+0x10)
			if pos==6 then return "partyback","EXIT" end -- graphic/box member 6
			if pos>6 then return nil end
			if pos<u32(s.party+4) then mon=s.party+8+pos*0xEC end
			where="Pokémon del equipo, "..(pos+1).." de 6"
		else return nil end
		local text="Vacío"
		if u8(ui+0x12)==1 then
			if not mon or u32(ui+8)~=mon then return PM.fail("PC: cursor Pokemon owner") end
			if u32(ui+0x4C)==mon then text=PM.pc_preview(s)
			else
				-- While carrying a Pokemon, the game's preview follows the carried
				-- Pokemon. Read the destination's identity separately, as in BW.
				local data=PM.boxdata(mon)
				if not data then return nil end
				text=PM.boxname(mon)
				if data.long(2,0x10)&0x40000000==0 then
					local level=PM.pc_level(data.word(1,0),data.long(1,8))
					if not level then return nil end
					text=text and (text..", "..PM.text_at(19,36).." "..level)
				end
			end
		elseif u8(ui+0x12)~=0 then return nil end
		return loc..":"..pos,text and (text..", "..where)
	end
	function PM.pc_compare(s)
		local side,page=u8(s.ui+0xA4),u8(s.ui+0xA5)
		if side>1 or page>2 then return PM.fail("PC: comparison selection") end
		local out={}
		for i=0,1 do
			local label=i==0 and "Left" or "Right"
			local present=i==side and u8(s.ui+0x12)==1 or i~=side and u8(s.ui+0xA6+i)==1
			if not present then out[#out+1]=label..", Vacío"
			else
				local p=s.ui+0xAC+i*0x30
				local name=str_name(u32(p+0x28),12)
				if not name then return PM.fail("PC: comparison name") end
				local line={label,name}
				local egg=u8(p+6)
				if egg>1 then return nil end
				if egg==1 then line[#line+1]=PM.text_at(19,44)
				elseif page==0 then
					local nature=PM.message(u32(p+0x2C),nil,12)
					if not nature then return PM.fail("PC: comparison nature") end
					line[#line+1]=PM.text_at(19,35).." "..nature
					for n=0,6 do
						local value=u16(p+8+n*2)
						if value<1 or value>(n==0 and 100 or 999) then return PM.fail("PC: comparison stat") end
						line[#line+1]=PM.text_at(19,36+n).." "..value
					end
				elseif page==1 then
					-- Labels are baked into graphic/box member 130.
					for n,label2 in ipairs({"Cool","Beauty","Cute","Smart","Tough"}) do
						local value=u16(p+0x14+n*2)
						if value>255 then return PM.fail("PC: comparison condition") end
						line[#line+1]=label2.." "..value.." de 255"
					end
				else
					for n=0,3 do
						local id=u16(p+0x20+n*2)
						if id~=0 then
							if not BTLTEXT.moves[id] then return PM.fail("PC: comparison move") end
							line[#line+1]=BTLTEXT.moves[id]
						end
					end
				end
				out[#out+1]=table.concat(line,", ")
			end
		end
		return table.concat(out,". ")
	end
	local header_key, header, slot_key, slot_text, last_held, selector_key, selector_text
	function PM.pc_screen(s)
		if not PM.pc_idle(s) then return nil end
		local prompt=u16(s.msg+0x1C)==1 and PM.message(u32(s.msg+0x34),nil,64) or nil
		if s.action==fn.TouchScreenBoxJump and s.state==1 and u8(s.ui+0x9C)==1 then
			local box=u8(s.ui+0x9E)
			if box>=18 then return PM.fail("PC: touch dial box") end
			return "box dial",nil,box,PM.pc_box_name(s,box)
		end
		if s.action==fn.MarkingsFilter and s.state==1 and u8(s.ui+0x9C)==2 then
			-- Eight graphical filter buttons rotate through six visible positions.
			-- The native renderer uses bit 0 for held items, then the six markings.
			local offset,mask=u8(s.ui+0x9D),u16(s.ui+0x4A)
			if offset>7 or mask>127 then return PM.fail("PC: marking filters") end
			local labels={"Todos","Objeto equipado",table.unpack(marks)}
			local text={}
			for i=0,5 do
				local id=(offset+i)%8
				local enabled=id==0 and mask==0 or id>0 and mask&(1<<(id-1))~=0
				text[#text+1]=labels[id+1]..", "..(enabled and "on" or "off")
			end
			return "marking filters",nil,offset..":"..mask,table.concat(text,". ")
		end
		if (s.action==fn.BoxJump or s.action==fn.StoreMon) and s.state==1 then
			local state,box=u32(s.ui+0x1BC),u8(s.ui+0x1C1)
			if (state==2 or state==3) and box<18 and u32(s.ui+0x98)==box then
				local key=s.app..":"..s.action..":"..box
				if selector_key~=key then
					local name,count=PM.pc_box_name(s,box),PM.pc_box_count(s,box)
					selector_text=name and count and (name..", "..count.." Pokémon, "..(box+1).." de 18")
					selector_key=selector_text and key or nil
				end
				return "box selector",prompt,box,selector_text
			end
		end
		if s.action==fn.DisplayItemInfo and (s.state==2 or s.state==3) then
			local p=s.gfx+0x662C
			if u32(p)~=s.gfx or u32(p+12)~=s.ui then return PM.fail("PC: item information owner") end
			local description=PM.message(u32(p+0x4BFC),nil,500)
			return "item information",description
		end
		if u16(s.msg+0x1E)==1 then
			local allowed=menus[s.action]
			if allowed and allowed[s.state] then
				local row,text=PM.pc_menu(s)
				return "menu:"..s.action..":"..u32(s.ui+0x10C),prompt,row,text
			end
			return "message",prompt
		end
		if prompt then return "message",prompt end
		local regular=s.action==0 and s.inputstate==0 and
			(s.handler==fn.CursorInBox or s.handler==fn.CursorInParty or s.handler==fn.CursorOnHeader
			 or s.handler==fn.CursorOnClose or s.handler==fn.CursorOnPartyButton)
		local multi=s.action==fn.MultiSelect and (s.state==1 or s.state==2)
		if not regular and not multi then return nil end
		local hk=s.app..":"..s.box
		if hk~=header_key then
			local name,count=PM.pc_box_name(s,s.box),PM.pc_box_count(s,s.box)
			header=name and count and (PM.pc_modes[s.mode]..". "..name..", "..count.." Pokémon")
			header_key=header and hk or nil
		end
		local mon=u32(s.ui+8)
		local stamp=inram(mon+7) and u32(mon+4) or 0
		local key=table.concat({s.app,s.box,u32(s.ui+0xC),u32(s.ui+0x10),mon,stamp,u32(s.ui+0x18),
			u32(s.ui+0x1C),u32(s.ui+0x48),u16(s.ui+0x52),u16(s.ui+0x112),u32(s.ui+0xA4)},":")
		local pickup
		if key~=slot_key then
			local _,text=PM.pc_slot(s)
			if text and s.mode==4 then
				local comparison=PM.pc_compare(s)
				if not comparison then return nil end
				text=text..". "..comparison
			end
			local source=u8(s.ui+0x13)
			local held=source==2 or source==4 or source==8
			if text and held and not last_held then
				local carried
				if source==2 then carried=PM.pc_preview(s)
				else carried=u8(s.ui+0x1C).." Pokémon" end
				if carried then pickup="Picked up "..carried..". " end
			end
			if text then last_held=held end
			if text and multi and s.state==1 then
				local c1,r1,c2,r2=u8(s.ui+0x18),u8(s.ui+0x19),u8(s.ui+0x1A),u8(s.ui+0x1B)
				if c1>5 or c2>5 or r1>4 or r2>4 then return PM.fail("PC: selection rectangle") end
				text=text..". Selected rows "..(math.min(r1,r2)+1).." to "..(math.max(r1,r2)+1)
					..", columns "..(math.min(c1,c2)+1).." to "..(math.max(c1,c2)+1)
			end
			slot_key=text and key or nil
			slot_text=text
		end
		return hk,header,key,pickup and (pickup..slot_text) or slot_text
	end
	PM.register("PC storage",PM.pc_context,PM.pc_screen)
	local reset_reader=MODULES[#MODULES].on_exit
	MODULES[#MODULES].on_exit=function()
		reset_reader()
		header_key,header,slot_key,slot_text,last_held,selector_key,selector_text=nil,nil,nil,nil,nil,nil,nil
	end

	-- CapsuleMenu_Main owns overlay 76 only in state 1. The field task destroys
	-- this application before opening the party selector and creates it again
	-- on return. CapsuleMenu_Init and SealCase_GetCapsuleById establish the
	-- twelve capsule pointers; the seal editor consumes their render copies.
	function PM.pc_capsules()
		local ui,state,app=PM.field_app(A.CapsuleMenu_Main,76)
		if not ui or state~=1 then return nil end
		if not inram(ui+0x42F) then return PM.fail("capsules: allocation") end
		local args=u32(ui)
		if args~=u32(app+0x18) or not inram(args+0x2F) then return PM.fail("capsules: arguments") end
		local party,case=u32(args+0x1C),u32(args+0x20)
		if not inram(party+0x58F) or u32(party)~=6 or u32(party+4)>6 or u32(args)~=u32(party+4) then
			return PM.fail("capsules: party owner")
		end
		if not inram(case+0x16F) or u32(ui+0x64)~=case+0x120 then return PM.fail("capsules: seal case owner") end
		for i=0,11 do
			if u32(ui+8+i*8)~=case+i*0x18 then return PM.fail("capsules: capsule owner") end
		end
		local func,step=u32(ui+0x3CC),u32(ui+0x3D4)
		local selected=u32(ui+0x3C4)
		if func>5 or step>10 or selected>11 then return PM.fail("capsules: screen state") end
		return {ui=ui,app=app,args=args,party=party,case=case,func=func,state=step,selected=selected}
	end
	function PM.pc_seal_name(id)
		if id<1 or id>80 then return PM.fail("capsules: seal type") end
		return PM.text_at(12,u8(A.SealData+id*10))
	end
	function PM.pc_capsule_contents(s,index,editing)
		if index>11 then return nil end
		local out={"Capsule "..(index+1)} -- numbered capsule icons
		local monIndex=u32(s.ui+4+index*8)
		if monIndex~=255 then
			if monIndex>=u32(s.party+4) or u32(s.args+4+monIndex*4)~=s.party+8+monIndex*0xEC then
				return PM.fail("capsules: assigned Pokemon")
			end
			local name=PM.boxname(s.party+8+monIndex*0xEC)
			if not name then return nil end
			out[#out+1]=name
		end
		local count=0
		for i=0,7 do
			local p=editing and s.ui+0x324+i*0x10 or s.case+index*0x18+i*3
			local id=editing and u8(p+4) or u8(p)
			if editing and u32(p)>1 then return PM.fail("capsules: seal render state") end
			if id~=0 and (not editing or u32(p)==1) then
				local name=PM.pc_seal_name(id)
				if not name then return nil end
				count=count+1
				out[#out+1]=name
			end
		end
		if count==0 then out[#out+1]="Vacío" end
		out[#out+1]="row "..(index//4+1)..", column "..(index%4+1)
		return table.concat(out,", ")
	end
	function PM.pc_capsule_yesno(s)
		if s.func~=1 or s.state~=7 or u32(s.ui+0x3DC)~=3 then return nil end
		local p=u32(s.ui+0x224)
		if not inram(p+0x9B) or u32(p+0x7C)~=u32(s.ui+0xE4) or u32(p+0x80)~=4
			or u8(p+0x9B)&15~=1 then return PM.fail("capsules: confirmation owner") end
		return p
	end
	function PM.pc_capsule_error(s)
		-- Native hit testing retains which button fired and a held-frame counter.
		-- Read the actual callback's first frame, before either transient refusal
		-- is lost: CapsuleGraphics_PrintMessage frees its temporary String.
		local actions=u32(s.ui+0x1CC)
		if not inram(actions+0x13) or u32(actions)~=s.ui+0x1D0 or u32(actions+4)~=21
			or u32(actions+8)~=A.CapsuleTouch or u32(actions+12)~=s.ui then
			return PM.fail("capsules: touch action owner")
		end
		local states=u32(actions+16)
		if not inram(states+83) then return PM.fail("capsules: touch action states") end
		for i=0,7 do
			local p=states+i*4
			if u8(p)==1 and u8(p+1)==1 and u16(p+2)==0 then
				local full=true
				for n=0,7 do if u32(s.ui+0x324+n*16)==0 then full=false; break end end
				if full then return PM.text_at(8,15) end
				local id=u8(s.ui+0x420+i)
				if id>0 and id<=80 and u8(s.case+0x120+id-1)==0 then return PM.text_at(8,16) end
			end
		end
	end
	local capsule_owner,capsule_func,capsule_state
	function PM.pc_capsule_screen(s)
		local ui=s.ui
		local finished=capsule_owner==ui and capsule_func==1 and capsule_state==6 and s.func==1 and s.state==8
		capsule_owner,capsule_func,capsule_state=ui,s.func,s.state
		if finished then return "capsule finished",PM.text_at(8,12) end
		if s.func==0 then
			if s.state==3 then
				return "capsules",PM.text_at(8,7),s.selected,PM.pc_capsule_contents(s,s.selected,false)
			elseif s.state==4 then
				local row,text=PM.menu(u32(ui+0x1A0))
				return "capsule menu",PM.text_at(8,8),row,text
			end
		elseif s.func==3 and s.state==1 then
			return "capsule removed",PM.text_at(8,9)
		elseif s.func==4 then
			if s.state==1 then
				local target=u32(ui+0x3C8)
				return "capsule shift",PM.text_at(8,10),target,PM.pc_capsule_contents(s,target,false)
			elseif s.state==2 then return "capsules switched",PM.text_at(8,11) end
		elseif s.func==1 then
			if s.state==5 and u32(ui+0x3DC)>0 then return "capsule preview",PM.text_at(8,13) end
			if s.state==7 then
				local p=PM.pc_capsule_yesno(s)
				if p then
					local pressed=u8(p+0x9A)
					if pressed==3 then return "capsule cancel",PM.text_at(8,14) end
					if pressed<2 then return "capsule cancel",PM.text_at(8,14),pressed,PM.text_at(437,9+pressed) end
				end
				return nil
			end
			if s.state~=4 or u32(ui+0xD8)~=1 then return nil end
			local page,pages=u32(ui+0x418),u32(ui+0x41C)
			if pages>10 or (pages>0 and page>=pages) or (pages==0 and page~=0) then
				return PM.fail("capsules: inventory page")
			end
			local title=PM.pc_capsule_contents(s,s.selected,true)
			if not title then return nil end
			local held=u32(ui+0xD4)
			if held~=255 then
				if held>7 or u32(ui+0x324+held*16)~=1 then return PM.fail("capsules: held seal") end
				local p=ui+0x324+held*16
				local name=PM.pc_seal_name(u8(p+4))
				local x,y=u8(p+5),u8(p+6)
				return "capsule editing",nil,held..":"..x..":"..y,name and (name..", x "..x..", y "..y)
			end
			local error=PM.pc_capsule_error(s)
			if error then return "capsule error",error end
			local inventory={}
			for i=0,7 do
				local id=u8(ui+0x420+i)
				if id~=0 then
					local name=PM.pc_seal_name(id)
					if not name then return nil end
					inventory[#inventory+1]=u8(s.case+0x120+id-1).." "..name
				end
			end
			local text=#inventory==0 and "Vacío" or table.concat(inventory,". ")..". "..(page+1).." de "..pages
			return "capsule editing",title,text,text
		end
	end
	PM.register("PC Ball Capsules",PM.pc_capsules,PM.pc_capsule_screen)
	local reset_capsules=MODULES[#MODULES].on_exit
	MODULES[#MODULES].on_exit=function()
		reset_capsules()
		capsule_owner,capsule_func,capsule_state=nil,nil,nil
	end

	-- Shared RT layout: J/L selects an item, I/O its action, H activates it.
	-- While carrying a seal those four directions move the spoken placement grid.
	-- All changes go through native touch consumers; no storage/save writes.
	function PM.pc_touch_table(owner,offset,count,callback,inline)
		local p=u32(owner+offset)
		if not inram(p+19) or u32(p+4)~=count or u32(p+8)~=callback or u32(p+12)~=owner then
			return PM.fail("PC touch: action owner "..offset)
		end
		local rects=u32(p)
		if not inram(rects+count*4-1) or (inline and rects~=owner+inline) then
			return PM.fail("PC touch: hit table "..offset)
		end
		return rects
	end
	function PM.pc_touch_rect(p)
		local top,bottom,left,right=u8(p),u8(p+1),u8(p+2),u8(p+3)
		if top>=bottom or bottom>192 or left>=right then return PM.fail("PC touch: rectangle bounds") end
		return {left=left,right=right,top=top,bottom=bottom,x=(left+right)//2,y=(top+bottom)//2}
	end
	function PM.pc_touch_circle(rects,index)
		local p=rects+index*4
		if u8(p)~=254 or u8(p+2)>=192 or u8(p+3)==0 then return PM.fail("PC touch: circle bounds") end
		return u8(p+1),u8(p+2)
	end
	function PM.pc_touch_storage_kind(s,waiting)
		if s.action==fn.TouchScreenBoxJump then
			if waiting or (s.state==1 and u8(s.ui+0x9C)==1 and PM.pc_idle(s)) then return "boxes" end
		elseif s.action==fn.MarkingsFilter then
			if waiting or (s.state==1 and u8(s.ui+0x9C)==2 and PM.pc_idle(s)) then return "filters" end
		elseif s.action==0 and (waiting or (s.inputstate==0 and PM.pc_idle(s))) and
			(s.handler==fn.CursorInBox or s.handler==fn.CursorInParty or s.handler==fn.CursorOnHeader
			 or s.handler==fn.CursorOnClose or s.handler==fn.CursorOnPartyButton) then
			return s.mode==4 and "compare" or "storage"
		end
	end
	function PM.pc_touch_storage_rows(s)
		local kind=PM.pc_touch_storage_kind(s)
		if not kind then return nil end
		local rows={}
		if kind=="compare" then
			local side,page=u8(s.ui+0xA4),u8(s.ui+0xA5)
			if side>1 or page>2 then return PM.fail("PC touch: comparison selection") end
			if u8(s.ui+0x12)==1 then rows[#rows+1]={id="side",button=side,text=PM.text_at(18,76+side)} end
			rows[#rows+1]={id="page",button=2,text="Comparison page, "..({"Stats","Condition","Moves"})[page+1],actions={"Siguiente"}}
		elseif kind=="storage" then
			rows[#rows+1]={id="boxes",button=0,text=PM.text_at(18,24)}
			if s.mode~=3 then rows[#rows+1]={id="filters",button=1,text="Marking filters"} end
		else
			if kind=="filters" then
				local offset,mask=u8(s.ui+0x9D),u16(s.ui+0x4A)
				if offset>7 or mask>127 then return PM.fail("PC touch: filter selection") end
				local labels={"Todos","Objeto equipado",table.unpack(marks)} -- graphical buttons
				for i=0,5 do
					local id=(offset+i)%8
					local on=id==0 and mask==0 or id>0 and mask&(1<<(id-1))~=0
					rows[#rows+1]={id="filter"..i,mark=i,text=labels[id+1]..", "..(on and "on" or "off")}
				end
			end
			local dial=kind=="boxes" and PM.text_at(18,24)
				or "Filter dial, "..({"All","Held item",table.unpack(marks)})[u8(s.ui+0x9D)+1]
			rows[#rows+1]={id="dial",dial=true,text=dial,
				actions={"Anterior","Siguiente"}}
			if kind=="filters" then rows[#rows+1]={id="boxes",button=0,text=PM.text_at(18,24)}
			elseif s.mode~=3 then rows[#rows+1]={id="filters",button=1,text="Marking filters"} end
		end
		return kind,rows
	end
	function PM.pc_touch_dial(s,direction)
		local p=s.ui+0x1C8
		local cx,cy,inner,outer=u32(p+12),u32(p+16),u8(p+0x2B),u8(p+0x2F)
		local callback=u32(p+0x30)
		local expected=s.action==fn.TouchScreenBoxJump and 0 or 255
		if cx~=expected or cy~=192 or inner~=56 or outer~=88
			or u8(p+0x28)~=254 or u8(p+0x2C)~=254
			or u8(p+0x29)~=cx or u8(p+0x2D)~=cx or u8(p+0x2A)~=cy or u8(p+0x2E)~=cy
			or (callback~=A.PCDialStart and callback~=A.PCDialScroll)
			or u32(p+0x24)~=(cx==0 and 1 or 0xFFFFFFFF) then return PM.fail("PC touch: dial owner") end
		-- Retail thresholds are 4.219 and 33.75 degrees. A 15-degree arc inside
		-- the live annulus advances exactly one notch without crossing atan2's wrap.
		local angle=(cx==0 and -45 or -135)*math.pi/180
		local delta=direction*(cx==0 and 1 or -1)*15*math.pi/180
		local radius=(inner+outer)/2
		local x1,y1=math.floor(cx+radius*math.cos(angle)+0.5),math.floor(cy+radius*math.sin(angle)+0.5)
		local x2,y2=math.floor(cx+radius*math.cos(angle+delta)+0.5),math.floor(cy+radius*math.sin(angle+delta)+0.5)
		-- Hold both endpoints: animation states may defer their next input poll.
		local frames={false,false}
		for _=1,6 do frames[#frames+1]={x1,y1} end
		for _=1,6 do frames[#frames+1]={x2,y2} end
		frames[#frames+1]=false
		return touch.gesture(frames)
	end
	function PM.pc_touch_storage_activate(s,row,action)
		if touch.busy() or not PM.pc_touch_storage_kind(s) then return end
		if row.dial then return PM.pc_touch_dial(s,action==1 and -1 or 1) end
		local marking=row.mark~=nil
		local count=marking and 7 or s.mode==4 and 4 or 3 -- includes native sentinel
		local rects=PM.pc_touch_table(s.ui,marking and 0x180 or 0x17C,count,marking and A.PCMarkTouch or A.PCMainTouch)
		if not rects then return nil end
		if u8(rects+(count-1)*4)~=255 then return PM.fail("PC touch: hit table sentinel") end
		local x,y=PM.pc_touch_circle(rects,marking and row.mark or row.button)
		if x then return touch.tap(x,y) end
	end
	function PM.pc_touch_capsule_kind(s)
		if s.func~=1 then return nil end
		if s.state==4 and u32(s.ui+0xD8)==1 then return "seals" end
		local p=PM.pc_capsule_yesno(s)
		if p and u8(p+0x9A)==3 then return "seal confirmation" end
	end
	function PM.pc_seal_grid(x,y)
		return "row "..(math.floor((y-10)/10+0.5)+1)..", column "..(math.floor((x-130)/10+0.5)+1)
	end
	function PM.pc_touch_capsule_rows(s)
		local kind=PM.pc_touch_capsule_kind(s)
		if not kind then return nil end
		if kind=="seal confirmation" then
			return kind,{{id="yes",answer=0,text=PM.text_at(437,9)},{id="no",answer=1,text=PM.text_at(437,10)}}
		end
		local page,pages=u32(s.ui+0x418),u32(s.ui+0x41C)
		if pages>10 or (pages==0 and page~=0) or (pages>0 and page>=pages) then return PM.fail("PC touch: seal page") end
		local rows={}
		for i=0,7 do
			local id=u8(s.ui+0x420+i)
			if id~=0 then
				local name=PM.pc_seal_name(id); if not name then return nil end
				rows[#rows+1]={id="inventory"..i,inventory=i,seal=id,text=u8(s.case+0x120+id-1).." "..name,
					actions={PM.text_at(18,59)}}
			end
		end
		for i=0,7 do
			local p=s.ui+0x324+i*16
			if u32(p)>1 then return PM.fail("PC touch: seal render state") end
			if u32(p)==1 then
				local id=u8(p+4); local name=PM.pc_seal_name(id); if not name then return nil end
				rows[#rows+1]={id="placed"..i,slot=i,seal=id,text=name..", "..PM.pc_seal_grid(u8(p+5),u8(p+6)),
					actions={PM.text_at(18,58),PM.text_at(8,3)}}
			end
		end
		if pages>1 then
			rows[#rows+1]={id="pages",button=8,text="Página de sellos "..(page+1).." de "..pages,actions={"Anterior","Siguiente"}}
		end
		rows[#rows+1]={id="button10",button=10,text="Preview"} -- animated ball icon
		for i=11,12 do rows[#rows+1]={id="button"..i,button=i,text=PM.text_at(8,i-6)} end
		return kind,rows
	end
	function PM.pc_seal_rects(s)
		return PM.pc_touch_table(s.ui,0x1CC,21,A.CapsuleTouch,0x1D0)
	end
	function PM.pc_seal_rect(s,rects,slot)
		local p=s.ui+0x324+slot*16
		local r=rects+(13+slot)*4
		local x,y=u8(p+5),u8(p+6)
		if u32(p+12)~=r or x<130 or x>250 or y<10 or y>130
			or u8(r)~=(y-10)%256 or u8(r+1)~=(y+10)%256
			or u8(r+2)~=(x-10)%256 or u8(r+3)~=(x+10)%256 then
			return PM.fail("PC touch: seal rectangle owner or bounds")
		end
		-- At the right edge, native byte bounds wrap. Its unsigned subtraction
		-- still accepts x >= left; clip that visible segment to the screen here.
		return {left=x-10,right=math.min(256,x+10),top=y-10,bottom=y+10,x=x,y=y}
	end
	function PM.pc_seal_pickpoint(s,rects,slot)
		local p=s.ui+0x324+slot*16
		local target=PM.pc_seal_rect(s,rects,slot); if not target then return nil end
		-- The native callback chooses the FIRST overlapping seal. Find an exposed
		-- part of this rectangle from rectangle edges, not from a RAM/pixel scan.
		local xs,ys={target.x,target.left,target.right-1},{target.y,target.top,target.bottom-1}
		local earlier={}
		for i=0,slot-1 do
			if u32(s.ui+0x324+i*16)==1 then
				local r=PM.pc_seal_rect(s,rects,i); if not r then return nil end
				earlier[#earlier+1]=r
				xs[#xs+1]=r.left-1; xs[#xs+1]=r.right
				ys[#ys+1]=r.top-1; ys[#ys+1]=r.bottom
			end
		end
		local best,distance
		for _,x in ipairs(xs) do for _,y in ipairs(ys) do
			if x>=target.left and x<target.right and y>=target.top and y<target.bottom then
				local covered=false
				for _,r in ipairs(earlier) do
					if x>=r.left and x<r.right and y>=r.top and y<r.bottom then covered=true; break end
				end
				local d=(x-u8(p+5))^2+(y-u8(p+6))^2
				if not covered and (not distance or d<distance) then best,distance={x=x,y=y},d end
			end
		end end
		return best,not best
	end
	function PM.pc_touch_capsule_activate(s,row,action,t)
		if touch.busy() then return end
		if row.answer~=nil then
			local p=PM.pc_capsule_yesno(s)
			if not p or u8(p+0x9A)~=3 then return end
			local rects=PM.pc_touch_table(p,0,2,A.YesNoTouch,4)
			local r=rects and PM.pc_touch_rect(rects+row.answer*4)
			if r then return touch.tap(r.x,r.y) end
			return
		end
		if PM.pc_touch_capsule_kind(s)~="seals" or u32(s.ui+0xD4)~=255 then return end
		local rects=PM.pc_seal_rects(s); if not rects then return end
		if row.button then
			local index=row.button==8 and (action==1 and 8 or 9) or row.button
			local r=PM.pc_touch_rect(rects+index*4)
			if r then return touch.tap(r.x,r.y) end
			return
		end
		local slot,point=row.slot
		local x,y=190,70
		if row.inventory~=nil then
			for i=0,7 do if u32(s.ui+0x324+i*16)==0 then slot=i; break end end
			if not slot then say(PM.text_at(8,15)); return end
			if u8(s.case+0x120+row.seal-1)==0 then say(PM.text_at(8,16)); return end
			point=PM.pc_touch_rect(rects+row.inventory*4)
		else
			local covered
			point,covered=PM.pc_seal_pickpoint(s,rects,slot)
			if not point then
				if covered then say("Tapado por otro sello. Mueve antes ese sello.") end
				return
			end
			x,y=u8(s.ui+0x329+slot*16),u8(s.ui+0x32A+slot*16)
		end
		if not point then return end
		t.drag={phase="pickup",frames=0,slot=slot,seal=row.seal,source=point,x=x,y=y,
			remove=row.slot~=nil and action==2,original=row.slot~=nil}
		touch.release()
		return true
	end
	function PM.pc_seal_drag(s,t,pressed)
		local d=t.drag
		if not d then return false end
		if PM.pc_touch_capsule_kind(s)~="seals" then
			touch.cancel(); t.drag=nil; PM.fail("PC touch: seal editor changed during drag"); return false
		end
		local p=s.ui+0x324+d.slot*16
		local held=u32(s.ui+0xD4)
		d.frames=d.frames+1
		if d.phase=="pickup" then
			if held==255 then
				if d.frames>60 then
					touch.cancel(); t.drag=nil; PM.fail("PC touch: seal pickup not acknowledged")
				else touch.hold(d.source.x,d.source.y) end
				return true
			end
			if held~=d.slot or u32(p)~=1 or u8(p+4)~=d.seal then
				touch.cancel(); t.drag=nil; PM.fail("PC touch: unexpected held seal"); return true
			end
			d.phase,d.frames="move",0
			if d.remove then d.x,d.y=128,160 end -- outside the native radius; native returns the seal
		elseif d.phase=="release" then
			touch.release()
			if held==255 then
				local correct=d.remove and u32(p)==0 or not d.remove and u32(p)==1 and u8(p+4)==d.seal
					and u8(p+5)==d.x and u8(p+6)==d.y
				if correct then
					say(PM.pc_seal_name(d.seal)..", "..(d.remove and PM.text_at(8,3) or PM.text_at(18,59)..", "..PM.pc_seal_grid(d.x,d.y)))
				else PM.fail("PC touch: seal drop result") end
				t.drag,t.last=nil,nil
			elseif d.frames>60 then touch.cancel(); t.drag=nil; PM.fail("PC touch: seal release not acknowledged") end
			return true
		elseif held~=d.slot or u32(p)~=1 or u8(p+4)~=d.seal then
			touch.cancel(); t.drag=nil; PM.fail("PC touch: lost held seal"); return true
		end
		-- Only release AFTER the game's render copy acknowledges the coordinates.
		local arrived=u8(p+5)==d.x and u8(p+6)==d.y
		if d.remove and arrived then
			d.phase,d.frames="release",0; touch.release(); return true
		end
		if not d.remove then
			if not d.spoken and arrived then say(PM.pc_seal_name(d.seal)..", "..PM.pc_seal_grid(d.x,d.y)); d.spoken=true end
			if pressed.H then d.drop=true end
			if pressed.J or pressed.L or pressed.I or pressed.O then
				local col,row=math.floor((d.x-130)/10+0.5),math.floor((d.y-10)/10+0.5)
				col=col+(pressed.I and -1 or pressed.O and 1 or 0)
				row=row+(pressed.J and -1 or pressed.L and 1 or 0)
				local x,y=130+col*10,10+row*10
				if col>=0 and col<=12 and row>=0 and row<=12 and (x-190)^2+(y-70)^2<=3600 then
					d.x,d.y,d.spoken,d.frames,d.drop=x,y,false,0,false
				else say("Borde de la cápsula, "..PM.pc_seal_grid(d.x,d.y)) end
			elseif d.drop and arrived then d.phase,d.frames="release",0; touch.release(); return true end
		end
		if not arrived and d.frames>60 then
			touch.cancel(); t.drag=nil; PM.fail("PC touch: seal movement not acknowledged"); return true
		end
		touch.hold(d.x,d.y) -- refresh even with RT released; only confirm places the seal
		return true
	end
	function PM.pc_touch_attach(name,detect,layout,activate,capsules)
		local module
		for _,m in ipairs(MODULES) do if m.name==name then module=m; break end end
		local read,reset=module.update,module.on_exit
		local t={}
		local function clear()
			if t.owns then touch.cancel() end
			t={}
		end
		module.on_exit=function() clear(); reset() end
		pad.register_rt(function()
			local s=detect()
			return s and (capsules and s.func==1 or not capsules and PM.pc_touch_storage_kind(s,true)~=nil)
		end,true)
		module.update=function(pressed)
			local s=detect(); if not s then clear(); return end
			if t.owner~=s.ui then clear(); t.owner=s.ui end
			if capsules and PM.pc_seal_drag(s,t,pressed) then return end
			local kind,rows=layout(s)
			local rt=keys.held()[pad.PAD.."RightTrigger"] and true or false
			local input=pressed.J or pressed.L or pressed.I or pressed.O or pressed.H
			local fresh=kind and t.kind~=kind
			local returned=kind and not t.ready
			if fresh then t.kind,t.row,t.action,t.last,t.focus,t.item=kind,1,1,nil,false,nil end
			if returned then t.last=nil end
			if kind and (rt or input) then t.focus=true end
			local focused=kind=="seals" and t.focus or kind=="filters" and t.focus
			if not focused then read(pressed) end
			t.ready=kind~=nil
			if not kind then t.rt=rt; return end
			-- Inventory pages can have different lengths. Keep the selected control
			-- (especially its page arrows/Confirm) when rows before it appear or vanish.
			if t.item then for i,row in ipairs(rows) do if row.id==t.item then t.row=i; break end end end
			if t.row>#rows then t.row=1; t.action=1 end
			if touch.busy() then t.rt=rt; return end
			if pressed.J then t.row=(t.row-2)%#rows+1; t.action=1
			elseif pressed.L then t.row=t.row%#rows+1; t.action=1 end
			local row=rows[t.row]
			if t.item and t.item~=row.id then t.action=1 end
			t.item=row.id
			local count=row.actions and #row.actions or 1
			if pressed.I then t.action=(t.action-2)%count+1
			elseif pressed.O then t.action=t.action%count+1 end
			if t.action>count then t.action=1 end
			local text=row.text..(row.actions and (", "..row.actions[t.action]) or "")..", "..t.row.." de "..#rows
			if t.focus and (text~=t.last or input or rt and not t.rt) then
				local moved=pressed.J or pressed.L or pressed.I or pressed.O
				local landing=fresh or returned or kind=="seal confirmation" and not t.last
				say(text,moved or focused or not landing); t.last=text
			end
			t.rt=rt
			if pressed.H and activate(s,row,t.action,t) then t.owns=true end
		end
	end
	PM.pc_touch_attach("PC storage",PM.pc_context,PM.pc_touch_storage_rows,PM.pc_touch_storage_activate,false)
	PM.pc_touch_attach("PC Ball Capsules",PM.pc_capsules,PM.pc_touch_capsule_rows,PM.pc_touch_capsule_activate,true)
end)()

------------------------------------------------------------ TOWN MAP / FLY -----
-- The screen Fly opens (and the Town Map item and wall maps): Sinnoh with a cursor the D-pad moves
-- one map square at a time, the hovered place's name, and its descriptions. Black and White's fly
-- map, carried over (questions_flymap.md): the free cursor speaks name and description; hold the
-- right trigger and press up/down to step through the unlocked fly destinations ("name,
-- description, X of Y"); right trigger + A flies to the place the cursor holds.
--
-- ⭐ STEPPING MOVES THE GAME'S OWN CURSOR WITH THE GAME'S OWN INPUT. Unlike Black and White there is
-- no touch commit to tap: HandleInput (overlay 80, 021d18f8) moves the cursor one square per
-- D-pad step, so the reader presses the D-pad (pad.press) until the cursor stands on the place it
-- announced. Nothing flies without A, and A commits only what CanFlyToHoveredLocation accepts.
--
-- THE CHAIN, every hop read in the retail overlay (src/applications/town_map/, overlay 80):
--   field child app, main TownMap_Main 021d0dd8, overlay 80 (FieldSystem_OpenTownMap 0203d884)
--   TownMapAppData: +00 u8 mode (1 = Fly) · +02 u16 unlockedHiddenLocations · +08 mainAppState
--     (TownMap_Main `ldr r1,[r4,#8]`; 4 = MAIN_LOOP, the only state that reads input)
--     · +2C context · +30 MainMapMatrixData · +34 graphicsMan · +40 TownMapBlockList
--     (UpdateHoveredLocation 021d1a30..54)
--   graphicsMan: +11 queuedMovement, +13 zoomedMapMvtStage, +18 cursorX, +1C cursorZ (HandleInput
--     021d18f8..19be; bounds z>=7 up, z<=27 down, x<=27 right, x>=2 left) · +14 zoom-button
--     transition (>1 = input ignored, TownMap_HandleInput_Fly 021d167c) · +20 hovered map header
--     · +9C fly locations · +A0 hovered TownMapBlock (CanFlyToHoveredLocation 021d29bc)
--   fly locations: +00 u16 count, +08 list, stride 1C: +00 mapHeader, +0A u16 special id,
--     +0C/+10 sprite x/y, +14 isUnlocked (TownMap_GetFlyLocationAtPos 021d2c5c)
--   blocks: +00 count, +04 entries, stride 18: +00/+02 x/z, +08 area and +0A landmark text,
--     +14 hidden-location flags, +16 index (TownMap_GetMapBlockAtPosition 021d2e24)
--   context +5C: one byte of description checks per block index (PrintLocationDescription 021d1b5c)
--   matrix: u16 header ids, 30 per row (MainMapMatrixData_GetMapHeaderIDAtCoords 02039f04)
-- ⛔ graphicsMan is freed in CLEANUP without being cleared, so nothing reads it outside MAIN_LOOP.
;(function()
	local TEXT = PM.town_map_text
	local WORDS = { nothing = "Nothing is selected", cannot = "You cannot fly there",
	                stuck = "The cursor would not move", none = "Nowhere to fly to yet" }
	local MAIN_LOOP, MODE_FLY, MATRIX_W, MAX_HEADER = 4, 1, 30, 0x251
	local X_MIN, X_MAX, Z_MIN, Z_MAX = 1, 28, 6, 28
	local t = {}

	local function town_map()
		local ui = PM.field_app(A.TownMap_Main, 80)
		if not ui or not inram(ui + 0x43) or u8(ui) > 2 then return nil end
		return ui
	end
	-- The graphics, context, matrix and blocks, only while the main loop runs.
	local function live(ui)
		if u32(ui + 0x08) ~= MAIN_LOOP then return nil end
		local g, ctx, mat, bl = u32(ui + 0x34), u32(ui + 0x2C), u32(ui + 0x30), u32(ui + 0x40)
		if not inram(g) or not inram(g + 0xA3) then dbg("town map: graphics unreadable"); return nil end
		if not inram(ctx) or not inram(ctx + 0x5C + 199) then dbg("town map: context unreadable"); return nil end
		if not inram(mat) or not inram(mat + MATRIX_W * MATRIX_W * 2 - 1) then dbg("town map: matrix unreadable"); return nil end
		local n, e = inram(bl + 7) and u32(bl) or 0, inram(bl + 7) and u32(bl + 4) or 0
		if n < 1 or n > 200 or not inram(e) or not inram(e + n * 0x18 - 1) then dbg("town map: block list invalid"); return nil end
		return { ui = ui, g = g, ctx = ctx, mat = mat, blocks = e, nblocks = n, hidden = u16(ui + 0x02) }
	end

	-- A map header's name: MapHeader_LoadName (mapLabelTextID into bank 433). Header 0 is the
	-- matrix's "everywhere"; LoadMapName first looks the square up in its own off-matrix table.
	local function place(header, x, z)
		if header == 0 then
			local tbl, n = u32(A.TownMapOffMatrixNames), u8(A.TownMapOffMatrixCount)
			if u8(A.TownMapOffMatrixCount + 1) ~= 0x29 or n > 32 or not inram(tbl) or not inram(tbl + n * 8 - 1) then
				dbg("town map: off-matrix name table unreadable"); return nil
			end
			for i = 0, n - 1 do
				local r = tbl + i * 8
				if u16(r) == x and u16(r + 2) == z then header = u32(r + 4); break end
			end
		end
		if header >= MAX_HEADER then return nil end
		local nm = PM.text[433][u8(A.sMapHeaders + header * 0x18 + 0x12)]
		return (nm and nm ~= "") and nm or nil
	end

	-- Name, then the area and landmark descriptions the game would print for this block, each
	-- shown unless its check failed (no check, or a passed one). Full stops become the joins.
	local function describe(s, header, x, z, b)
		local nm = place(header, x, z)
		if not nm then return nil end
		local parts = { nm }
		local idx = u16(b + 0x16)
		if idx < 200 then
			local chk = u8(s.ctx + 0x5C + idx)
			for _, d in ipairs({ { 0x08, chk & 3, (chk >> 2) & 3 }, { 0x0A, (chk >> 4) & 3, (chk >> 6) & 3 } }) do
				local id = u16(b + d[1])
				local text = id ~= 0xFFFF and (d[2] == 0 or d[3] ~= 0) and TEXT[id] or nil
				if text and text ~= "" then parts[#parts + 1] = (text:gsub("%.$", "")) end
			end
		end
		return table.concat(parts, ", ")
	end

	-- The fly location the game would commit on this square (TownMap_GetFlyLocationAtPos): the first
	-- entry with the header; a special entry (Pal Park, Victory Road, the League) only on its own
	-- square, which is its sprite square — the same squares the function compares as immediates.
	local function fly_at(fm, n, header, x, z)
		local list = u32(fm + 8)
		for i = 0, n - 1 do
			local e = list + i * 0x1C
			if u32(e) == header then
				if u16(e + 0x0A) == 0 then return e end
				if u32(e + 0x0C) // 7 == x and u32(e + 0x10) // 7 == z then return e end
			end
		end
		return nil
	end
	local function flylist(s)
		local fm = u32(s.g + 0x9C)
		local n = inram(fm + 0x0B) and u16(fm) or 0
		if n < 1 or n > 32 or not inram(u32(fm + 8)) or not inram(u32(fm + 8) + n * 0x1C - 1) then
			dbg("town map: fly locations invalid"); return nil
		end
		return fm, n
	end

	-- The unlocked destinations in the game's own order, each on the visible block nearest its
	-- sprite whose square really commits to it — so the cursor lands where A would fly.
	local function destinations(s)
		local fm, n = flylist(s)
		if not fm then return nil end
		local first, out = {}, {}
		for j = 0, s.nblocks - 1 do
			local b = s.blocks + j * 0x18
			local x, z = u16(b), u16(b + 2)
			local key = x * 64 + z
			if first[key] == nil then
				local f = u16(b + 0x14)
				first[key] = (f == 0 or f & s.hidden ~= 0) and b or false
			end
		end
		local list = u32(fm + 8)
		for i = 0, n - 1 do
			local e = list + i * 0x1C
			if u32(e + 0x14) ~= 0 then
				local sx, sz = u32(e + 0x0C) // 7, u32(e + 0x10) // 7
				local best, bd
				for key, b in pairs(first) do
					local x, z = key // 64, key % 64
					if b and x >= X_MIN and x <= X_MAX and z >= Z_MIN and z <= Z_MAX then
						local header = u16(s.mat + (x + z * MATRIX_W) * 2)
						if header == u32(e) and fly_at(fm, n, header, x, z) == e then
							local d = math.abs(x - sx) + math.abs(z - sz)
							if not best or d < bd or (d == bd and key < best.key) then
								best, bd = { key = key, x = x, z = z, b = b, header = header }, d
							end
						end
					end
				end
				if best then out[#out + 1] = best
				else dbg("town map: no square commits to fly location " .. i) end
			end
		end
		return out
	end

	local function reset()
		t = {}
	end

	MODULES[#MODULES + 1] = {
		name = "town map",
		detect = function() return town_map() ~= nil end,
		on_enter = reset,
		on_exit = reset,
		update = function(pressed)
			local ui = town_map()
			local s = ui and live(ui)
			if not s then return end
			local g = s.g
			local cx, cz = s32(g + 0x18), s32(g + 0x1C)
			local hov = u32(g + 0xA0)
			if hov ~= 0 and not inram(hov + 0x17) then hov = 0 end
			local hline = hov ~= 0 and describe(s, u32(g + 0x20), cx, cz, hov) or nil
			local fly = u8(ui) == MODE_FLY

			-- Arrival: the prompt interrupts and the place under the cursor queues behind it.
			if not t.said then
				t.said, t.hov, t.line = true, hov, hline
				if fly and TEXT[0] then say(TEXT[0], true); if hline then say(hline, false) end
				elseif hline then say(hline, true) end
				return
			end

			-- A cursor move the player made speaks the new place; one our own steps make does not
			-- (the step already said where it goes). Squares of the same place say nothing new.
			if hov ~= t.hov then
				t.hov = hov
				if hline and hline ~= t.line and not t.goal then say(hline, true) end
				t.line = hline
			end

			-- Travel: one D-pad step at a time until the cursor stands on the goal.
			-- ⛔ A PRESS IS HELD UNTIL THE GAME TAKES IT, never for a fixed frame count. NitroMain reads
			-- the pad once per application tick, which is every SECOND frame on retail (src/main.c
			-- 120-152) and every frame on 60 fps hacks, so a one-frame press can fall between reads.
			-- Taken = queuedMovement set or the cursor moved; holding past that is harmless, because
			-- HandleInput returns at once while queuedMovement is set (graphics.c:377).
			local ready = u8(g + 0x14) <= 1 and u8(g + 0x11) == 0 and u8(g + 0x13) == 0
			local here = cx * 64 + cz
			if t.goal then
				if cx == t.goal.x and cz == t.goal.z and not t.held and u8(g + 0x11) == 0 then
					t.goal = nil
					t.line = hline
				elseif t.held and (here ~= t.from or u8(g + 0x11) ~= 0) then
					t.held = nil                              -- taken: wait for the step to finish
				elseif t.held then
					if u8(g + 0x14) <= 1 then
						t.wait = t.wait - 1
						if t.wait <= 0 then t.goal, t.held, t.fly = nil, nil, nil; say(WORDS.stuck, true)
						else pad.press(t.held) end
					end
				elseif ready then
					local b = {}
					if t.goal.x < cx then b.Left = true elseif t.goal.x > cx then b.Right = true end
					if t.goal.z < cz then b.Up = true elseif t.goal.z > cz then b.Down = true end
					t.held, t.from, t.wait = b, here, 30
					pad.press(b)
				end
			end

			if pressed["J"] or pressed["L"] then
				t.list = t.list or destinations(s)
				local n = t.list and #t.list or 0
				if n == 0 then say(WORDS.none, true); return end
				if not t.sel then t.sel = pressed["L"] and 1 or n
				else t.sel = pressed["L"] and (t.sel % n + 1) or ((t.sel - 2) % n + 1) end
				local d = t.list[t.sel]
				local line = describe(s, d.header, d.x, d.z, d.b)
				if line then say(line .. ", " .. t.sel .. " de " .. n, true) end
				-- A new choice replaces the old goal outright, including a press not yet taken: a
				-- step already on its way can carry the cursor off this square, and it walks back.
				t.fly, t.held, t.goal = nil, nil, d
				pad.press(nil)
				return
			end

			-- Right trigger + A: the game's own A, on the square the cursor holds, when it can fly.
			-- Pressed while the cursor is still travelling or mid-step, it waits for the cursor to
			-- settle on the place last announced rather than being dropped.
			if pressed["H"] and fly then t.fly = true end
			if t.fly and not t.goal and ready then
				local fm, n = flylist(s)
				local e = fm and hov ~= 0 and fly_at(fm, n, u32(g + 0x20), cx, cz)
				if t.fly == true then
					if hov == 0 then t.fly = nil; say(WORDS.nothing, true)
					elseif not (e and u32(e + 0x14) ~= 0) then t.fly = nil; say(WORDS.cannot, true)
					else t.fly = 30 end
				end
				-- Held, like the D-pad, until the app leaves its main loop (then this reader stops
				-- running). JOY_NEW fires once however long A is held.
				if type(t.fly) == "number" then
					t.fly = t.fly - 1
					if t.fly <= 0 then t.fly = nil; dbg("town map: A was not taken")
					else pad.press({ A = true }) end
				end
			end
		end,
	}
	pad.register_rt(function() return town_map() ~= nil end, true)
end)()

--------------------------------------------------------------- MAIN LOOP -----
-- These menus join a question already on screen. In particular, a PC/Yes-No
-- menu can take dispatch several frames after field dialogue spoke the question.
local speech_continuations = {
	["battle level-up gains"] = { [false] = true },
	["save screen"] = { ["field dialogue"] = true },
	["PC field menus"] = { ["field dialogue"] = true },
	-- The mart scripts greet, then CloseMessageWithoutErasing and PokeMartCommon: the greeting
	-- stays on screen under BUY/SELL/SEE YA! (asm/macros/scrcmd.inc PokeMartCommonWithGreeting).
	["shop"] = { ["field dialogue"] = true },
	["battle command menu"] = { [false] = true },
	["battle move menu"] = { [false] = true },
	["battle targets and choices"] = { [false] = true },
}
local battle_question_continuations = {
	[false] = true,
	["battle command menu"] = true,
	["battle move menu"] = true,
	["battle targets and choices"] = true,
}
local previous_speech_screen, dialogue_gap
local function speech_screen(now)
	local name = battle_levelup_screen() or (now and now.name)
	if name == "field party" then name = PM.field_levelup_screen() or name end
	-- ⛔ ONE FRAME OF GRACE AFTER FIELD DIALOGUE, because the emulator samples in mid-tick. The mart
	-- greeting's CloseMessageWithoutErasing clears isMsgBoxOpen and PokeMartCommon pushes the shop
	-- task in the SAME script tick, but at 30 Hz a frame can end between the two: nothing claims it,
	-- and stopping there cut the greeting before BUY could queue (the player's log, 7 November:
	-- "field dialogue", "none", "shop" on every visit). A real exit only stops one frame later, and
	-- nothing speaks in an unclaimed field frame: battle text needs a battle, which the trainer
	-- encounter transition takes many frames to start.
	if not name and previous_speech_screen == "field dialogue" and not dialogue_gap then
		dialogue_gap = true
		return
	end
	dialogue_gap = false
	if not name then
		-- Input is unavailable while a menu slides IN, but its question still
		-- belongs to that screen. A selection's transition task instead closes
		-- the menu: let that exit stop speech immediately, before battle text.
		local sc, cfg = subscreen_shown()
		if sc and u32(sc + SC.TRANS) == 0 then
			if cfg >= 1 and cfg <= 6 then name = "battle command menu"
			elseif cfg == 11 then name = "battle move menu"
			elseif cfg >= 7 and cfg <= 17 then name = "battle targets and choices" end
		end
	end
	local continuation = speech_continuations[name]
	-- Task_PlayerShowYesNoMenu prints the question before SetupBackground.
	-- A finished transition can leave the previous config readable meanwhile.
	-- Preserve only that same, already spoken message when its choices join it.
	if name ~= previous_speech_screen and name == "battle targets and choices" and btl_message_continues() then
		continuation = battle_question_continuations
	end
	sp.screen(name, continuation)
	previous_speech_screen = name
end
local function context_of()
	for _, m in ipairs(MODULES) do
		if m.detect() then return m end
	end
	return nil
end

-- The one allowed meta line (Rule 1). The name comes from the loader so it can never disagree with
-- which game file actually got loaded.
say("Accesibilidad de Pokémon Platino en marcha.")
local active = nil
while true do
	local pressed = poll_keys()
	-- Retire the old speech before ANY new-screen output, including global
	-- battle messages. Stopping after those readers would cut off the new line.
	battle_menu_forget()
	local now = context_of()
	speech_screen(now)
	if now ~= active then
		if active and active.on_exit then active.on_exit() end
		active = now
		if active and active.on_enter then active.on_enter() end
		dbg(active and active.name or "none")
	end
	if pressed[KEY_STOP]   then stop_speech() end
	if pressed[KEY_REPEAT] then say(sp.last()) end
	-- Match BW: raw keyboard B / unmodified L3, before the trigger translation.
	PM.money_step(pressed)

	-- Every frame, and deliberately OUTSIDE the module dispatch: this has to hold on screens no
	-- reader has been written for yet, which is most of the game.
	if FAST_TEXT then fast_text_step() end

	-- The controller layer, BEFORE the readers: it folds pad chords into the same virtual letters
	-- the readers already listen for, so a reader never needs to know the pad exists.
	pad_step(pressed)

	-- THE BATTLE MESSAGE BOX, and deliberately a STEP rather than a module — see the long note
	-- above battle_text_step. It runs BEFORE the module dispatch so that when a message and a menu
	-- appear on the same frame ("What will TURTWIG do?" and the four commands) the message is
	-- spoken first and the menu row queues behind it, which is the order they are on screen in.
	battle_text_step()

	-- "How is my Pokémon doing?" on I / O. A step for the same reason: it has to answer while the
	-- command menu or the move menu holds the context. It reads `pressed`, so it goes AFTER
	-- pad_step, which is what turns a left-trigger D-pad chord into those letters.
	battle_status_step(pressed)

	-- The level-up stat panel, for the same reason again: it appears while the battle's own
	-- message box is still up, so it cannot be a context module competing with one.
	battle_levelup_step()

	if active and active.update then active.update(pressed) end

	-- D: how the Pokémon in focus looks (core/describe.lua). The battle answers inside
	-- battle_status_step; a module answers through its `describe` field.
	if pressed["D"] and active and active.describe then
		local species, form, shiny = active.describe()
		if species then describe_mon(species, form, shiny) else dbg("describe: nothing in focus on " .. active.name) end
	elseif pressed["D"] and active and active.describe_trainer then
		local key, games = active.describe_trainer()
		if not (key and describe_trainer(key, games)) then dbg("describe: no trainer in focus on " .. active.name) end
	end

	-- Synthetic touch, AFTER the modules: a module that queues a gesture does it inside its own
	-- update(), and this both advances that gesture and releases a touch nobody is driving any more.
	-- The core reads input after this whole iteration, so the last write of the frame is what it sees.
	touch.step()

	emu.frameadvance()
end
